    private function is_booster_helper(int $booster_id): bool
    {
        return isset(self::$booster_helper_ids[$booster_id]);
    }

    private function add_booster_helper_bonus_payment(int $booster_id, int $order_id, int $bonus_base_amount, string $sender, string $sender_type, int $sender_id, string $created_at): int
    {
        if ($booster_id <= 0 || $order_id <= 0 || $bonus_base_amount <= 0 || !$this->is_booster_helper($booster_id)) {
            return 0;
        }

        global $db;

        // Safety: never add the helper bonus twice for the same order/booster.
        $existing_rows = $db->run(
            "SELECT COALESCE(SUM(amount), 0) AS paid
             FROM booster_payments
             WHERE type = 'booster_helper_bonus' AND note = ? AND booster_id = ?",
            (string)$order_id,
            $booster_id
        );
        $already_paid = (is_array($existing_rows) && isset($existing_rows[0]['paid'])) ? (int)$existing_rows[0]['paid'] : 0;
        if ($already_paid !== 0) {
            return 0;
        }

        $bonus_amount = (int) round($bonus_base_amount * self::BOOSTER_HELPER_BONUS_PERCENT / 100);
        if ($bonus_amount <= 0) {
            return 0;
        }

        $booster_now = db_get_row('boosters', ['id' => $booster_id]);
        if ($booster_now == false) {
            return 0;
        }

        $old_balance = (int)($booster_now['balance'] ?? 0);
        $new_balance = $old_balance + $bonus_amount;

        db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance]);

        db_add_row('booster_payments', [
            'booster_id' => $booster_id,
            'type' => 'booster_helper_bonus',
            'note' => (string)$order_id,
            'amount' => $bonus_amount,
            'currency' => 'EUR',
            'sender' => $sender,
            'sender_type' => $sender_type,
            'sender_id' => $sender_id,
            'balance_update' => $old_balance . '|' . $new_balance,
            'created_at' => $created_at,
        ]);

        if (function_exists('log_admin_action')) {
            log_admin_action($sender_id, "Order #{$order_id}: booster helper bonus for booster #{$booster_id} €" . number_format($bonus_amount / 100, 2, '.', ''));
        }

        return $bonus_amount;
    }



    private function ensure_order_claim_blocks_table(): void
    {
        global $db;
        try {
            $db->run("CREATE TABLE IF NOT EXISTS order_claim_blocks (
                id INT UNSIGNED NOT NULL AUTO_INCREMENT,
                order_id INT UNSIGNED NOT NULL,
                booster_id INT UNSIGNED NOT NULL,
                admin_id INT UNSIGNED NULL DEFAULT NULL,
                reason VARCHAR(255) NULL DEFAULT NULL,
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                UNIQUE KEY uniq_order_booster (order_id, booster_id),
                KEY idx_booster_id (booster_id),
                KEY idx_order_id (order_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        } catch (\Throwable $e) {
            // If auto-create is unavailable on the server, the manual SQL patch can be imported.
        }
    }

    private function block_booster_from_order_claim(int $order_id, int $booster_id, ?int $admin_id = null, string $reason = 'Removed from order by admin'): void
    {
        if ($order_id <= 0 || $booster_id <= 0) {
            return;
        }

        global $db;
        $this->ensure_order_claim_blocks_table();

        try {
            $db->run(
                "INSERT INTO order_claim_blocks (order_id, booster_id, admin_id, reason, created_at)
                 VALUES (?, ?, ?, ?, NOW())
                 ON DUPLICATE KEY UPDATE admin_id = VALUES(admin_id), reason = VALUES(reason), created_at = VALUES(created_at)",
                $order_id,
                $booster_id,
                $admin_id,
                $reason
            );
        } catch (\Throwable $e) {
            // Do not break the admin remove flow if the table was not created yet.
        }
    }

    private function is_booster_blocked_from_order_claim(int $order_id, int $booster_id): bool
    {
        if ($order_id <= 0 || $booster_id <= 0) {
            return false;
        }

        global $db;
        $this->ensure_order_claim_blocks_table();

        try {
            $rows = $db->run(
                "SELECT id FROM order_claim_blocks WHERE order_id = ? AND booster_id = ? LIMIT 1",
                $order_id,
                $booster_id
            );
            return !empty($rows);
        } catch (\Throwable $e) {
            return false;
        }
    }

    private function get_monthly_top_booster_award(int $booster_id, string $at): ?array
    {
        if ($booster_id <= 0) {
            return null;
        }

        global $db;

        try {
            $rows = $db->run(
                "SELECT booster_id, position, bonus_percent, title
                 FROM booster_monthly_bonus_awards
                 WHERE booster_id = ?
                   AND active_from <= ?
                   AND active_until > ?
                 ORDER BY position ASC
                 LIMIT 1",
                $booster_id,
                $at,
                $at
            ) ?: [];
        } catch (\Throwable $e) {
            return null;
        }

        return !empty($rows[0]) ? $rows[0] : null;
    }

    private function add_monthly_top_booster_bonus_payment(int $booster_id, int $order_id, int $bonus_base_amount, string $sender, string $sender_type, int $sender_id, string $created_at): int
    {
        if ($booster_id <= 0 || $order_id <= 0 || $bonus_base_amount <= 0) {
            return 0;
        }

        global $db;

        $award = $this->get_monthly_top_booster_award($booster_id, $created_at);
        if (empty($award) || (float)($award['bonus_percent'] ?? 0) <= 0) {
            return 0;
        }

        try {
            $existing_rows = $db->run(
                "SELECT COALESCE(SUM(amount), 0) AS paid
                 FROM booster_payments
                 WHERE type = 'monthly_top_booster_bonus' AND note = ? AND booster_id = ?",
                (string)$order_id,
                $booster_id
            );
        } catch (\Throwable $e) {
            return 0;
        }

        $already_paid = (is_array($existing_rows) && isset($existing_rows[0]['paid'])) ? (int)$existing_rows[0]['paid'] : 0;
        if ($already_paid !== 0) {
            return 0;
        }

        $bonus_percent = (float)$award['bonus_percent'];
        $bonus_amount = (int) round($bonus_base_amount * $bonus_percent / 100);
        if ($bonus_amount <= 0) {
            return 0;
        }

        $booster_now = db_get_row('boosters', ['id' => $booster_id]);
        if ($booster_now == false) {
            return 0;
        }

        $old_balance = (int)($booster_now['balance'] ?? 0);
        $new_balance = $old_balance + $bonus_amount;

        db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance]);

        db_add_row('booster_payments', [
            'booster_id' => $booster_id,
            'type' => 'monthly_top_booster_bonus',
            'note' => (string)$order_id,
            'amount' => $bonus_amount,
            'currency' => 'EUR',
            'sender' => $sender,
            'sender_type' => $sender_type,
            'sender_id' => $sender_id,
            'balance_update' => $old_balance . '|' . $new_balance,
            'created_at' => $created_at,
        ]);

        if (function_exists('log_admin_action')) {
            $position = (int)($award['position'] ?? 0);
            log_admin_action($sender_id, "Order #{$order_id}: monthly top booster bonus for booster #{$booster_id}, position #{$position}, €" . number_format($bonus_amount / 100, 2, '.', ''));
        }

        return $bonus_amount;
    }

    /**
     * Normalize LoL division input coming from admin UI.
     * Internal system uses: 1=IV, 2=III, 3=II, 4=I.
     * Some UI components may send either roman strings ("I","II","III","IV")
     * This normalizes to internal numeric (1=IV,2=III,3=II,4=I).
     */
    private static function normalize_lol_division($division): ?int
    {
        if ($division === null || $division === '') return null;

        // Roman strings
        if (!is_numeric($division)) {
            $d = strtoupper(trim((string)$division));
            $map = ['IV' => 1, 'III' => 2, 'II' => 3, 'I' => 4];
            return $map[$d] ?? null;
        }

        $n = (int)$division;
        if ($n < 1 || $n > 4) return $n;

        // UI sends internal values: 1=IV, 2=III, 3=II, 4=I
        return $n;
    }


    private function is_duo_pass_order($order): bool
    {
        return in_array((int)($order['form_id'] ?? 0), [27, 36], true);
    }

    /**
     * Push the current Duo Pass timer state to every browser that has this order open.
     * The client runs its own 1s countdown locally and only needs to hear about the
     * discrete state changes (start / pause / continue), so this replaces what used to
     * be a check_duo_timer_status poll every 3 seconds per open order page — 20 full
     * app bootstraps per minute per viewer, which was a large share of the origin CPU.
     */
    private function emit_duo_timer_update(int $order_id): void
    {
        $helper = dirname(__DIR__) . '/helpers/realtime.php';
        if (is_file($helper)) {
            require_once $helper;
        }
        if (function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('duo_timer_update', $order_id);
        }
    }

    private function duo_timer_start_payload($order, ?string $now = null): array
    {
        if (!$this->is_duo_pass_order($order)) {
            return [];
        }

        $now = $now ?: date('Y-m-d H:i:s');
        $started = trim((string)($order['duo_timer_started_at'] ?? ''));
        if ($started !== '' && $started !== '0000-00-00 00:00:00') {
            return [];
        }

        return ['duo_timer_started_at' => $now];
    }

    private function duo_timer_stop_payload($order, ?string $now = null): array
    {
        if (!$this->is_duo_pass_order($order)) {
            return [];
        }

        $now = $now ?: date('Y-m-d H:i:s');
        $spent = (int)($order['duo_timer_spent_seconds'] ?? 0);
        $started = trim((string)($order['duo_timer_started_at'] ?? ''));

        // Manual-start mode: only a real started_at may advance the timer.
        if ($started !== '' && $started !== '0000-00-00 00:00:00') {
            $delta = max(0, strtotime($now) - strtotime($started));
            $spent += (int)$delta;
        }

        return [
            'duo_timer_spent_seconds' => $spent,
            'duo_timer_started_at' => null,
        ];
    }



    /**
     * Booster sets their own availability (Online / Away / Offline) from the header chip.
     * This flag is the truth for the public online display; the heartbeat only keeps it fresh.
     */
    public function booster_set_availability()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $status = lb_booster_presence_normalize_status($_POST['status'] ?? '');

        if (!lb_booster_set_status((int) BOOSTER_ID, $status)) {
            $reason = lb_booster_presence_last_error();
            echo json_encode([
                'success' => false,
                'reason' => $reason,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Status could not be saved.' . ($reason !== '' ? ' (' . $reason . ')' : ''),
                ],
            ]);
            return;
        }

        $meta = lb_booster_presence_statuses()[$status];

        echo json_encode([
            'success' => true,
            'status'  => $status,
            'label'   => $meta['label'],
            'sendToast' => [
                'type' => 'success',
                'title' => 'Status updated',
                'message' => 'You are now ' . $meta['label'] . '.',
            ],
        ]);
    }

    public function booster_start_duo_timer()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false || !$this->is_duo_pass_order($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        if (($order['status'] ?? '') !== 'IN_PROGRESS') {
            echo json_encode(['success' => false, 'message' => 'Order is not active']);
            return;
        }

        $alreadyStarted = !empty($order['duo_timer_started_at']) && $order['duo_timer_started_at'] !== '0000-00-00 00:00:00';
        $spent = (int)($order['duo_timer_spent_seconds'] ?? 0);
        if ($alreadyStarted || $spent > 0) {
            echo json_encode(['success' => true, 'started' => true, 'refreshPage' => true]);
            return;
        }

        $payload = array_merge(
            ['is_paused' => 0],
            $this->duo_timer_start_payload($order)
        );

        db_update_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], $payload);
        $this->emit_duo_timer_update($order_id);

        echo json_encode([
            'success' => true,
            'started' => true,
            'sendToast' => [
                'type' => 'success',
                'title' => 'Timer started',
                'message' => 'Duo Pass timer started.'
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function booster_pause_duo_timer()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
        if ($order == false || !$this->is_duo_pass_order($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        if (($order['status'] ?? '') !== 'IN_PROGRESS') {
            echo json_encode(['success' => false, 'message' => 'Order is not active']);
            return;
        }

        if ((int)($order['is_paused'] ?? 0) === 1) {
            echo json_encode(['success' => true, 'paused' => true, 'refreshPage' => true]);
            return;
        }

        $payload = array_merge(
            ['is_paused' => 1],
            $this->duo_timer_stop_payload($order)
        );

        db_update_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], $payload);
        $this->emit_duo_timer_update($order_id);

        echo json_encode([
            'success' => true,
            'paused' => true,
            'sendToast' => [
                'type' => 'success',
                'title' => 'Timer stopped',
                'message' => 'Duo Pass timer stopped.'
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function booster_continue_duo_timer()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
        if ($order == false || !$this->is_duo_pass_order($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        if (($order['status'] ?? '') !== 'IN_PROGRESS') {
            echo json_encode(['success' => false, 'message' => 'Order is not active']);
            return;
        }

        if ((int)($order['is_paused'] ?? 0) !== 1) {
            echo json_encode(['success' => true, 'paused' => false, 'refreshPage' => true]);
            return;
        }

        $payload = array_merge(
            ['is_paused' => 0],
            $this->duo_timer_start_payload($order)
        );

        db_update_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], $payload);
        $this->emit_duo_timer_update($order_id);

        echo json_encode([
            'success' => true,
            'paused' => false,
            'sendToast' => [
                'type' => 'success',
                'title' => 'Timer continued',
                'message' => 'Duo Pass timer continued.'
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

