    public function auth_seller_login()
    {
        $validator = new Validator;
        if (!isset($_POST['email']) && isset($_POST['login'])) {
            $_POST['email'] = $_POST['login'];
        }

        $validation = $validator->make($_POST, [
            'email'    => 'required',
            'password' => 'required',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {
            $email    = esc(trim($_POST['email']));
            $password = sha1(trim($_POST['password']));
            $seller   = db_get_row('sellers', ['email' => $email, 'password' => $password]);

            if (!$seller) {
                $form_error = ['email' => 'Invalid email and password combination'];
            } elseif (!empty($seller['is_banned'])) {
                $form_error = ['email' => 'Your seller account has been banned.'];
            } elseif (($seller['onboarding_status'] ?? 'pending') !== 'approved' || empty($seller['is_active'])) {
                $form_error = ['email' => 'Your seller account is not approved yet.'];
            } else {
                $token = db_auth_session_start($seller['id'], 'sellers');
                if ($token) {
                    util_create_cookie('seller_session_token', $token, isset($_POST['remember_me']) ? 1 : 0);
                    echo json_encode([
                        'noNotif'     => true,
                        'redirect'    => BASE_URL . '/seller-area/dashboard',
                        'redirectUrl' => BASE_URL . '/seller-area/dashboard',
                    ]);
                    return;
                }
                $form_error = ['email' => 'Could not create seller session. Please try again.'];
            }
        }

        if (!empty($form_error)) {
            $this->validationErrors = $form_error;
            echo json_encode(['validationErrors' => $this->validationErrors]);
        }
    }

    public function auth_client_register()
    {
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'email' => 'required|email',
            'password' => 'required|min:6',
            'username' => 'required',
            'tos' => 'required'
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {
            $email = esc($_POST["email"]);
            $password = sha1($_POST["password"]);
            $username = esc($_POST["username"]);
            // Deleted clients have their old email moved to deleted_email, so the real email can register again.
            $email_exists = db_get_row_count('clients', ['email' => $email]);
            if ($email_exists) {
                $form_error = ['email' => 'Email already exists'];
            } else {
                $form_error = false;
                $client_id = db_add_row('clients', [
                    'email' => $email,
                    'password' => $password,
                    'username' => $username
                ]);
                if ($client_id) {
                    $token = db_auth_session_start($client_id, 'clients');
                    if ($token != false) {
                        util_create_cookie('client_session_token', $token, 0);
                        $redirect = $_POST['redirectUrl'] ?? $_POST['redirect_after_login'] ?? null;
                        $redirect = is_string($redirect) ? trim($redirect) : null;

                        // Allow redirect only to internal URLs (prevents open redirect attacks)
                        if ($redirect) {
                            // If relative URL like "/checkout?x=1", convert to absolute
                            if (strpos($redirect, '/') === 0 && strpos($redirect, '//') !== 0) {
                                $redirect = BASE_URL . $redirect;
                            }

                            // If absolute URL, only allow if it starts with BASE_URL
                            if (strpos($redirect, BASE_URL) === 0) {
                                echo json_encode([
                                    'sendToast' => [
                                        'type' => 'primary',
                                        'title' => 'Success',
                                        'message' => 'Account created successfully ✅',
                                    ],
                                    'playSound' => 'success',
                                    'redirectUrl' => $redirect,
                                ]);
                                return;
                            }
                        }

                        echo json_encode([
                            'sendToast' => [
                                'type' => 'primary',
                                'title' => 'Success',
                                'message' => 'Account created successfully ✅',
                            ],
                            'playSound' => 'success',
                            'refreshPage' => true,
                        ]);
                        return;
                    } else {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Error',
                                'message' => 'Something went wrong, please try again',
                            ]
                        ]);
                    }
                } else {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Something went wrong, please try again',
                        ]
                    ]);
                }
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

