    public function prepare_account_purchase()
    {

        $package_id = intval($_POST['id']);
        if (empty($package_id)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid package',
                ]
            ]);
            exit;
        }

        $package = db_get_row('account_packages', ['id' => $package_id, 'status' => 1]);

        if (empty($package)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid package',
                ]
            ]);
            exit;
        }

        // check if package has at least one account available
        // Performance fix: a simple EXISTS/LIMIT check is enough here, no full COUNT needed.
        global $db;
        $available_accounts = (int)($db->cell(
            "SELECT 1 FROM accounts WHERE package_id = ? AND status = 0 LIMIT 1",
            $package_id
        ) ?: 0);

        if ($available_accounts == 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'This package is currently out of stock',
                ]
            ]);
            exit;
        }

        // check if session currency is usd
        if ($_SESSION['currency'] == 'USD') {
            $price = $package['price'] * get_exchange_rate();
        } else {
            $price = $package['price'];
        }

        $uuid = Uuid::uuid4();
        $uuid = $uuid->toString();

        $invoice_id = db_add_row('invoices', function_exists('lb_referral_attach_snapshot_to_invoice_data')
            ? lb_referral_attach_snapshot_to_invoice_data([
            'uuid' => $uuid,
            'order_id' => $package_id,
            'order_type' => 'account',
            'price' => $price,
            'price_eur' => $package['price'],
            'total_price' => $price,
            'currency' => $_SESSION['currency'] ?? 'EUR',
            'description' => strtoupper($package['server']) . ' - ' . $package['name'] . ' LoL account',
            'client_id' => CLIENT_ID ?? null
        
            ])
            : [
            'uuid' => $uuid,
            'order_id' => $package_id,
            'order_type' => 'account',
            'price' => $price,
            'price_eur' => $package['price'],
            'total_price' => $price,
            'currency' => $_SESSION['currency'] ?? 'EUR',
            'description' => strtoupper($package['server']) . ' - ' . $package['name'] . ' LoL account',
            'client_id' => CLIENT_ID ?? null
        ]
        );

        echo json_encode(array(
            'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
        ));
    }

    public function get_boost_price()
    {
        // validate type
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'uuid' => 'required',
            'form_id' => 'required',
        ]);
        $validation->validate();

        // if validation fails, return errors

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {
            // if validation passes, send api request to get boost price
            $_POST = esc_array($_POST);

            // IMPORTANT: Do NOT remap $_POST['form_id'] here.
            // TFT Coaching is form_id 25 and must stay 25 for order creation.
            // If pricing needs to reuse the Coaching (form_id 15) pricing logic,
            // do that inside calculate_boost_pricing() using a local copy.

            // GGirls is not a normal boost order. Keep price checks valid for the global JS,
            // but route Buy Now to the dedicated egirl checkout creator.
            $customFormId = (int)$_POST['form_id'];
            if ($customFormId === 28) {
                if (isset($_POST['buy_now'])) {
                    $this->egirl_book_lol_boost();
                    return;
                }

                $queue = preg_replace('/[^a-z0-9_]/i', '', (string)($_POST['ggirl_queue_type'] ?? 'normal_draft'));
                $amount = max(1, min(20, (int)($_POST['ggirl_amount'] ?? 1)));
                $rank = preg_replace('/[^a-z0-9_\-]/i', '', (string)($_POST['ggirl_rank'] ?? 'unranked'));
                $prices = [
                    'normal_draft' => 500,
                    'swiftplay' => 400,
                    'aram' => 400,
                    'solo_queue' => 600,
                    'chatting' => 600,
                    'watching' => 500,
                ];
                $rankModifiers = [
                    'unranked' => 0, 'iron' => 0, 'bronze' => 0, 'silver' => 0, 'gold' => 0,
                    'platinum' => 0, 'emerald' => 0, 'diamond' => 0, 'master' => 0,
                ];
                $pricingFile = SYS_PATH . '/public/uploads/private/boost-forms/ggirls-lol.json';
                if (is_file($pricingFile) && is_readable($pricingFile)) {
                    $pricingRaw = @file_get_contents($pricingFile);
                    $pricingJson = $pricingRaw !== false ? json_decode($pricingRaw, true) : null;
                    if (is_array($pricingJson)) {
                        if (!empty($pricingJson['modes']) && is_array($pricingJson['modes'])) {
                            foreach ($pricingJson['modes'] as $modeKey => $modeData) {
                                if (is_array($modeData)) $prices[$modeKey] = (int)($modeData['price_cents'] ?? 0);
                            }
                        }
                        if (!empty($pricingJson['ranks']) && is_array($pricingJson['ranks'])) {
                            foreach ($pricingJson['ranks'] as $rankKey => $rankData) {
                                if (is_array($rankData)) $rankModifiers[$rankKey] = (int)($rankData['price_modifier_cents'] ?? 0);
                            }
                        }
                    }
                }
                $unitPriceEur = max(0, (int)($prices[$queue] ?? 0) + (int)($rankModifiers[$rank] ?? 0));
                $priceEur = $unitPriceEur * $amount;
                $price = $priceEur;
                if (($_SESSION['currency'] ?? 'EUR') === 'USD') {
                    $rate = (float)(function_exists('get_exchange_rate') ? get_exchange_rate() : 0);
                    if ($rate > 0) $price = (int)round($priceEur * $rate);
                }
                echo json_encode([
                    'completion_time' => $amount,
                    'updatePricing' => 1,
                    'price' => $price,
                    'currency' => util_format_currency_display($_SESSION['currency'] ?? 'EUR'),
                ]);
                return;
            }

            // Pro Games uses custom booster-based pricing. Duo Pass has its own standalone pricing.
            if (in_array($customFormId, [26, 35], true)) {
                $data = ['id' => 26, 'type' => 'pro-games', 'extra' => [], 'lp_gain' => []];
            } else {
                $data = get_pricing_json($_POST['uuid']);
            }

            // Enforce the Master+ restriction server-side for forms that do
            // not explicitly support it. Rank Boost, Win Boost, Pro Games and
            // Duo Pass intentionally retain a selectable Solo/Duo mode.
            $pricingGame = strtolower(trim((string)($data['game'] ?? '')));
            $masterDuoAllowedForms = [1, 2, 21, 22, 24, 26, 27, 35, 36];
            if (
                $pricingGame === ''
                && (int)($_POST['start_tier'] ?? 0) >= 8
                && !in_array($customFormId, $masterDuoAllowedForms, true)
            ) {
                $pricingForm = db_get_row('boost_forms', ['id' => $customFormId, 'select' => 'game'], 1) ?: [];
                $pricingGame = strtolower(trim((string)($pricingForm['game'] ?? '')));
            }
            $isLolPricing = in_array($pricingGame, ['lol', 'league', 'leagu', 'league-of-legends', 'league_of_legends'], true);
            if (
                $isLolPricing
                && (int)($_POST['start_tier'] ?? 0) >= 8
                && !in_array($customFormId, $masterDuoAllowedForms, true)
            ) {
                $_POST['is_duo'] = 0;
            }
            if (in_array($customFormId, [26, 27, 35, 36], true)) {
                $_POST['is_duo'] = 1;
            }
            $form_error = false;
            if (isset($_POST['matches0'])) {
                $_POST['matches'] = $_POST['matches0'];
                unset($_POST['matches0']);
            }
            if ($customFormId === 4) {
                $_POST['matches'] = max(1, min(20, (int)($_POST['matches'] ?? 5)));
            }

            if (in_array($customFormId, [27, 36], true)) {
                $rankId = (int)($_POST['start_tier'] ?? -1);
                $hours = (int)($_POST['hours'] ?? 0);
                $server = strtolower(trim((string)($_POST['server'] ?? '')));
                $price = 0;
                $completion_time = max(1, $hours);
                $price_eur = 0;

                $serverBuckets = [
                    'euw' => 'eu', 'eune' => 'eu', 'me' => 'eu', 'tr' => 'eu', 'ru' => 'eu',
                    'na' => 'na', 'br' => 'na', 'lan' => 'na', 'las' => 'na', 'oce' => 'na', 'jp' => 'na', 'kr' => 'na',
                    'sg' => 'na', 'ph' => 'na', 'th' => 'na', 'tw' => 'na', 'vn' => 'na'
                ];

                $duoPassPricing = $data['main'] ?? [];

                if ($rankId < 0 || $hours <= 0 || $server === '') {
                    $form_error = 'Please select rank, duration and server.';
                    $price_data = [0, 0, 0];
                } else {
                    $bucket = $serverBuckets[$server] ?? 'eu';
                    $price = (int)($duoPassPricing[$rankId][$hours][$bucket] ?? 0);

                    if ($price <= 0) {
                        $form_error = 'No Duo Pass price found for the selected configuration.';
                        $price_data = [0, 0, 0];
                    } else {
                        $completion_time = $hours;
                        $price_eur = (($_SESSION['currency'] ?? 'EUR') === 'EUR') ? $price : ($price / get_exchange_rate());
                        $price_data = [$price, $completion_time, $price_eur];
                    }
                }
            } else {
                $price_data = calculate_boost_pricing($data, $_POST);
                $price = $price_data[0];
                $completion_time = $price_data[1];
            }

            // Check if discount post exists and is not empty
            if (isset($_POST['discount_code']) && !empty($_POST['discount_code'])) {
                $discount_data = db_get_row('discounts', ['code' => $_POST['discount_code']]);
                if ($discount_data != false && !empty($discount_data)) {

                    $is_discount_valid = verify_discount($discount_data, 'boosting');

                    $response['discount_status'] = $is_discount_valid[0];
                    $response['discount_msg'] = $is_discount_valid[1];
                    if ($is_discount_valid[0] == true) {
                        // Remove the check for client login status
                        $price = apply_discount($discount_data, $price);

                        // Check if the user has reached the max uses for this coupon
                        if ($this->is_client) {
                            $client_past_uses = (int)(db_get_row_count('invoices', ['client_id' => CLIENT_ID, 'discount_id' => $discount_data['id'], 'status' => 'PAID']) ?: 0);
                            if ($client_past_uses >= $discount_data['max_uses']) {
                                $response['discount_status'] = false;
                                $response['discount_msg'] = "You have reached the max uses for this coupon 😔";
                            }
                        }
                    }
                } else {
                    $response['discount_status'] = false;
                    $response['discount_msg'] = "Invalid discount code 😔";
                }
            }

            if (isset($_POST['lb_coins']) && $_POST['lb_coins'] == 1) {
                $client_points = CLIENT_DATA['points'];
                $response['lb_coins'] = floatval($client_points);
                $response['lb_coins_status'] = true;

                if ($client_points >= $price) {
                    $price = 0;
                } else {
                    $price -= floatval($client_points) * 100;
                }
            } else {
                $response['lb_coins_status'] = false;
            }

            $response['completion_time'] = $completion_time;
            $response['updatePricing'] = 1;
            $response['price'] = $price;
            $response['currency'] = util_format_currency_display($_SESSION['currency'] ?? 'EUR');

            if ($form_error == false) {
                if (isset($_POST['buy_now'])) {
                    // if (isset($response['discount_status']) && $response['discount_status']) {
                    //     $_POST['discount_code'] = $discount_data['code'];
                    // }
                    if ($_SESSION['currency'] == 'EUR') {
                        $price_eur = $price;
                    } else {
                        $price_eur = $price / get_exchange_rate();
                    }
                    $boost_data = [
                        'form_id' => $_POST['form_id'],
                        'price_eur' => $price_eur,
                        'price' => $price,
                        'currency' => $_SESSION['currency'] ?? 'EUR',
                        'client_id' => CLIENT_ID ?? null,
                        'status' => 'UNPAID',
                    ];
                    $boost_options_data = [];
                    if (isset($_POST['start_tier']) && ($_POST['start_tier'] > 7 || $_POST['start_tier'] == 0)) {
                        unset($_POST['start_division']);
                    }
                    if (isset($_POST['end_tier']) && ($_POST['end_tier'] > 7 || $_POST['end_tier'] == 0)) {
                        unset($_POST['end_division']);
                    }

                    $boost_options_list = load_boost_options();
                    foreach ($_POST as $key => $value) {
                        if (in_array($key, $boost_options_list)) {
                            if (is_array($value)) {
                                $value = array_values(array_unique(array_filter(array_map('trim', $value), static function ($item) {
                                    return $item !== '';
                                })));
                                $value = implode(',', $value);
                            }
                            $boost_options_data[$key] = $value;
                        }
                    }

                    $multi_request_form = in_array((int)($_POST['form_id'] ?? 0), [4, 19, 29], true);
                    $requested_booster_ids = [];
                    if ($multi_request_form) {
                        $requested_raw = $_POST['selected_boosters'] ?? [];
                        if (!is_array($requested_raw)) {
                            $requested_raw = preg_split('/[\s,|]+/', (string)$requested_raw, -1, PREG_SPLIT_NO_EMPTY);
                        }
                        foreach ((array)$requested_raw as $requested_id) {
                            $requested_id = (int)$requested_id;
                            if ($requested_id > 0 && !in_array($requested_id, $requested_booster_ids, true)) {
                                $requested_booster_ids[] = $requested_id;
                            }
                        }
                        $requested_limit = max(1, min(4, (int)($_POST['boosters'] ?? 1)));
                        $requested_booster_ids = array_slice($requested_booster_ids, 0, $requested_limit);
                        $boost_options_data['selected_boosters'] = implode(',', $requested_booster_ids);
                    }

                    // Ranked 5s, always persist the selected number of boosters explicitly.
                    // This must not depend only on the generic option whitelist because the checkout
                    // also uses the key "boosters" for the available booster list.
                    if (in_array((int)($_POST['form_id'] ?? 0), [4, 29], true)) {
                        $ranked5s_boosters = (int)($_POST['boosters'] ?? $_POST['booster_count'] ?? $_POST['ranked_5s_boosters_count'] ?? 1);
                        $ranked5s_boosters = max(1, min(4, $ranked5s_boosters));

                        $boost_options_data['boosters'] = $ranked5s_boosters;
                        if ((int)($_POST['form_id'] ?? 0) === 29) {
                            $boost_options_data['queue_type'] = 'ranked_5s';
                            $boost_options_data['is_duo'] = 1;
                            $boost_options_data['is_hidden_duo'] = 0;
                        }
                    }

                    // Numeric point inputs are used by open-ended ranks such as Apex Master.
                    // Persist them under the existing order_options LP columns so checkout and
                    // all downstream order displays receive the exact selected RP amount.
                    // The LoL/TFT rank + win forms post BOTH values: the LP band select
                    // (start_lp = "0-20") and the Master+ points input (start_lp_full), which
                    // stays at "0" while the selected rank is below Master. Letting the numeric
                    // input win unconditionally overwrote the band with 0 on every sub-Master
                    // order, which is why "Start LP" disappeared from the order views.
                    if (isset($_POST['start_lp_full']) && is_numeric($_POST['start_lp_full'])) {
                        $startLpBand = trim((string)($_POST['start_lp'] ?? ''));
                        if ((int)$_POST['start_lp_full'] > 0 || $startLpBand === '') {
                            $boost_options_data['start_lp'] = (int)$_POST['start_lp_full'];
                        }
                    }

                    if (isset($_POST['end_lp_full']) && is_numeric($_POST['end_lp_full'])) {
                        $boost_options_data['end_lp'] = (int)$_POST['end_lp_full'];
                    }

                    if (isset($_POST['start_tier']) && $_POST['start_tier'] == 8 && isset($_POST['start_rr_full'])) {
                        $boost_options_data['start_rr'] = $_POST['start_rr_full'];
                    }

                    if ($_POST['form_id'] == 5 && $_POST['end_tier'] == 8 && isset($_POST['end_rr_full']) && !empty($_POST['end_rr_full'])) {
                        $boost_options_data['end_rr'] = $_POST['end_rr_full'];
                    }

                    if ($_POST['form_id'] == 19) {
                        $boost_options_data['hours'] = $_POST['boosters'];
                    }

                    // Pro Games selects a booster before checkout. Duo Pass does not.
                    if (in_array((int)$_POST['form_id'], [26, 35], true)) {
                        $selected_bid = (int)($_POST['selected_booster_id'] ?? 0);
                        if ($selected_bid > 0) {
                            $boost_data['booster_id'] = $selected_bid;
                        }
                        $boost_data['status'] = 'UNPAID';
                    } else {
                        // All other forms: save optional booster preference from order summary selector
                        $selected_bid_any = $multi_request_form
                            ? (int)($requested_booster_ids[0] ?? 0)
                            : (int)($_POST['booster_id'] ?? 0);
                        if ($selected_bid_any > 0) {
                            $boost_data['booster_id'] = $selected_bid_any;
                        }
                    }
                    try {
                    $boost_id = db_add_row('orders', $boost_data);
                    $boost_options_data['order_id'] = $boost_id;
                    if (function_exists('lb_order_options_schema_ensure')) {
                        lb_order_options_schema_ensure();
                    }
                    db_add_row('order_options', $boost_options_data);
                    // Seed the tracked start rank straight from the ordered rank, so the
                    // progress card is filled even before (or without) a Riot API sync.
                    if (function_exists('lb_order_progress_ensure_start_rank')) {
                        lb_order_progress_ensure_start_rank((int) $boost_id);
                    }
                    $boost_form = db_get_row('boost_forms', ['id' => $_POST['form_id']]);
                    // generate uuid using Ramsey\Uuid\Uuid
                    $uuid = Uuid::uuid4();
                    $uuid = $uuid->toString();

                    $invoice_id = db_add_row('invoices', function_exists('lb_referral_attach_snapshot_to_invoice_data')
                        ? lb_referral_attach_snapshot_to_invoice_data([
                            'uuid' => $uuid,
                            'order_id' => $boost_id,
                            'order_type' => 'order',
                            'price' => $price_data[0],
                            'price_eur' => $price_data[2],
                            'discount_id' => $discount_data['id'] ?? null,
                            'discount_amount' => ($price - $price_data[0]) ?? 0,
                            'coins_used' => $response['lb_coins'] ?? 0,
                            'total_price' => $price,
                            'currency' => $_SESSION['currency'] ?? 'EUR',
                            'description' => util_format_boost_overview($boost_form['game'], $boost_form['type'], $boost_options_data),
                            'client_id' => CLIENT_ID ?? null
                        ])
                        : [
                            'uuid' => $uuid,
                            'order_id' => $boost_id,
                            'order_type' => 'order',
                            'price' => $price_data[0],
                            'price_eur' => $price_data[2],
                            'discount_id' => $discount_data['id'] ?? null,
                            'discount_amount' => ($price - $price_data[0]) ?? 0,
                            'coins_used' => $response['lb_coins'] ?? 0,
                            'total_price' => $price,
                            'currency' => $_SESSION['currency'] ?? 'EUR',
                            'description' => util_format_boost_overview($boost_form['game'], $boost_form['type'], $boost_options_data),
                            'client_id' => CLIENT_ID ?? null
                        ]);

                    db_update_row('orders', ['id' => $boost_id], ['invoice_id' => $invoice_id]);
                    echo json_encode(array(
                        'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
                    ));
                    } catch (\Throwable $e) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Order Error',
                                'message' => $e->getMessage(),
                            ],
                            'playSound' => 'error',
                            'debug_error' => $e->getMessage(),
                        ]);
                        return;
                    }
                } else {
                    echo json_encode($response);
                }
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

    public function check_order_status()
    {
        $order_id = (int)($_POST['order_id'] ?? 0);
        $order = db_get_row('orders', [
            'id' => $order_id,
            'select' => 'id,form_id,status,booster_id,claimed_at'
        ], 1);

        if (empty($order)) {
            echo json_encode(['error' => 'Order not found']);
            return;
        }

        $isRanked5s = ((int)($order['form_id'] ?? 0) === 29);
        $isMultiBooster = function_exists('lb_is_multi_booster_order')
            ? lb_is_multi_booster_order($order)
            : $isRanked5s;
        $isAssigned = false;
        $membership = null;

        if ($this->is_booster) {
            $isAssigned = ((int)($order['booster_id'] ?? 0) === (int)BOOSTER_ID);
            if ($isMultiBooster) {
                try {
                    global $db;
                    $rows = $db->run(
                        "SELECT slot_no, role, cut_percent, claimed_at
                           FROM order_boosters
                          WHERE order_id = ?
                            AND booster_id = ?
                            AND status = 'ACTIVE'
                          ORDER BY id DESC
                          LIMIT 1",
                        $order_id,
                        (int)BOOSTER_ID
                    ) ?: [];
                    $membership = !empty($rows) ? reset($rows) : null;
                    if (!empty($membership)) {
                        $isAssigned = true;
                    }
                } catch (Throwable $e) {
                    $membership = null;
                }
            }
        }

        $requiredBoosters = $isMultiBooster && function_exists('lb_multi_booster_required_count')
            ? lb_multi_booster_required_count($order_id)
            : 1;
        $claimedBoosters = $isMultiBooster && function_exists('lb_multi_booster_claimed_count')
            ? lb_multi_booster_claimed_count($order_id)
            : ((int)($order['booster_id'] ?? 0) > 0 ? 1 : 0);
        $hasOpenMultiSlot = $isMultiBooster
            && in_array((string)($order['status'] ?? ''), ['PAID', 'PROCESSING', 'IN_PROGRESS'], true)
            && $claimedBoosters < $requiredBoosters;

        $effectiveStatus = (string)($order['status'] ?? '');
        if ($isMultiBooster && $isAssigned && in_array($effectiveStatus, ['PAID', 'PROCESSING'], true)) {
            $effectiveStatus = 'IN_PROGRESS';
        }

        $claimed = trim((string)($membership['claimed_at'] ?? $order['claimed_at'] ?? ''));
        echo json_encode([
            'success' => true,
            'order_status' => $effectiveStatus,
            'booster_id' => $order['booster_id'] ?? null,
            'claimed_at' => ($claimed === '' || $claimed === '0000-00-00 00:00:00') ? '' : $claimed,
            'is_ranked_5s' => $isRanked5s,
            'is_multi_booster' => $isMultiBooster,
            'assigned_to_me' => $isAssigned,
            'available' => $isAssigned || $hasOpenMultiSlot,
            'removed_from_order' => ($isMultiBooster && $this->is_booster && !$isAssigned && !$hasOpenMultiSlot),
            'claimed_boosters' => $claimedBoosters,
            'required_boosters' => $requiredBoosters,
            'slot_no' => (int)($membership['slot_no'] ?? 0),
            'role' => (string)($membership['role'] ?? ''),
        ]);
    }


    public function check_duo_timer_status()
    {
        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order) || !$this->is_duo_pass_order($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        $hours = (int)($order['hours'] ?? 0);
        $booked = max(0, $hours * 3600);
        $spent = max(0, (int)($order['duo_timer_spent_seconds'] ?? 0));
        $status = strtoupper((string)($order['status'] ?? ''));
        $isPaused = (int)($order['is_paused'] ?? 0) === 1;
        $startedAt = trim((string)($order['duo_timer_started_at'] ?? ''));
        $isStarted = ($startedAt !== '' && $startedAt !== '0000-00-00 00:00:00');
        $isRunning = false;

        if ($status === 'IN_PROGRESS' && !$isPaused && $isStarted) {
            $ts = strtotime($startedAt);
            if ($ts !== false) {
                $spent += max(0, time() - $ts);
                $isRunning = true;
            }
        }

        $used = min($booked, max(0, $spent));
        $remaining = max(0, $booked - $used);
        $progress = $booked > 0 ? (int)round(($used / $booked) * 100) : 0;

        $state = 'Waiting';
        if ($remaining <= 0) {
            $state = 'Finished';
            $isRunning = false;
        } elseif ($isPaused) {
            $state = 'Paused';
        } elseif ($isRunning) {
            $state = 'Running';
        }

        echo json_encode([
            'success' => true,
            'booked_seconds' => $booked,
            'used_seconds' => $used,
            'remaining_seconds' => $remaining,
            'progress_percent' => max(0, min(100, $progress)),
            'status_label' => $state,
            'is_running' => $isRunning,
            'is_paused' => $isPaused,
            'order_status' => $status,
        ]);
    }

    public function load_chat()
    {
        $order_id = esc($_POST['order_id']);
        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode([
                'error' => 'Order not found',
            ]);
            return;
        }

        $chat = chat_load_messages($order_id);

        // Viewer-based filtering:
        // - admin: show placeholders "Message deleted."
        // - booster/client: hide deleted messages completely
        $viewer = 'client';
        if ($this->is_admin) {
            $viewer = 'admin';
        } elseif ($this->is_booster) {
            $viewer = 'booster';
        }

        if (function_exists('chat_prepare_for_viewer')) {
            $chat = chat_prepare_for_viewer($chat, $viewer);
        }

        echo json_encode($chat);
    }


    public function update_chat_seen()
    {
        $order_id = esc($_POST['order_id'] ?? '');
        $message_id = (int)($_POST['id'] ?? -1);

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'error' => 'Order not found']);
            return;
        }

        $viewer_type = $this->is_admin ? 'admin' : ($this->is_booster ? 'booster' : 'client');
        $viewer_id   = $this->is_admin ? (int) ADMIN_ID : ($this->is_booster ? (int) BOOSTER_ID : (int) CLIENT_ID);

        $res = chat_update_seen($order_id, $viewer_type, $viewer_id, $message_id);
        echo json_encode($res);
    }


    public function update_chat_notify()
    {
        $order_id = esc($_POST['order_id'] ?? '');
        $message_id = (int)($_POST['id'] ?? -1);

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'error' => 'Order not found']);
            return;
        }

        $res = chat_update_notify($order_id, $message_id);
        echo json_encode($res);
    }

    public function admin_delete_chat_message()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $order_id   = (int) ($_POST['order_id'] ?? 0);
        $message_id = (int) ($_POST['id'] ?? -1);

        if ($order_id <= 0 || $message_id < 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid parameters']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        // --- DB-basierter Soft-Delete ---
        global $db;
        $row = $db->row(
            "SELECT id, deleted, type FROM chat_messages
             WHERE order_id = ?
             ORDER BY time ASC, id ASC
             LIMIT 1 OFFSET ?",
            (string) $order_id,
            $message_id
        );

        if (!$row) {
            echo json_encode(['success' => false, 'message' => 'Message not found']);
            return;
        }

        // Idempotent: bereits gelöscht
        if (!empty($row['deleted']) || ($row['type'] ?? '') === 'deleted') {
            echo json_encode(['success' => true]);
            return;
        }

        $db->run(
            "UPDATE chat_messages
             SET deleted = 1, type = 'deleted', content = 'Message deleted.', raw = '',
                 deleted_by = 'admin'
             WHERE id = ?",
            $row['id']
        );

        echo json_encode(['success' => true]);
    }


    public function edit_chat_message()
    {
        if (!$this->is_admin && !$this->is_booster && !$this->is_client) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $order_id   = (int) ($_POST['order_id'] ?? 0);
        $message_id = (int) ($_POST['id'] ?? ($_POST['message_id'] ?? -1));
        $new_text   = trim((string) ($_POST['message'] ?? ''));

        if ($order_id <= 0 || $message_id < 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid parameters']);
            return;
        }
        if ($new_text === '') {
            echo json_encode(['success' => false, 'message' => 'Message is empty']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        // --- DB-basierte Bearbeitung ---
        global $db;
        $row = $db->row(
            "SELECT id, sender, sender_id, deleted, type FROM chat_messages
             WHERE order_id = ?
             ORDER BY time ASC, id ASC
             LIMIT 1 OFFSET ?",
            (string) $order_id,
            $message_id
        );

        if (!$row) {
            echo json_encode(['success' => false, 'message' => 'Message not found']);
            return;
        }

        if (!empty($row['deleted']) || ($row['type'] ?? '') === 'deleted') {
            echo json_encode(['success' => false, 'message' => 'Cannot edit deleted message']);
            return;
        }

        if (($row['type'] ?? '') === 'image') {
            echo json_encode(['success' => false, 'message' => 'Cannot edit image messages']);
            return;
        }

        // Berechtigungsprüfung (Booster/Client dürfen nur eigene Nachrichten bearbeiten)
        if (!$this->is_admin) {
            if ($this->is_booster) {
                if (($row['sender'] ?? '') !== 'booster' || (string)($row['sender_id'] ?? '') !== (string) BOOSTER_ID) {
                    echo json_encode(['success' => false, 'message' => 'Forbidden']);
                    return;
                }
            } elseif ($this->is_client) {
                if (($row['sender'] ?? '') !== 'client' || (string)($row['sender_id'] ?? '') !== (string) CLIENT_ID) {
                    echo json_encode(['success' => false, 'message' => 'Forbidden']);
                    return;
                }
            }
        }

        $safe     = esc($new_text);
        $rendered = make_links_clickable($safe);

        $db->run(
            "UPDATE chat_messages SET content = ?, raw = ?, edited = 1 WHERE id = ?",
            $rendered,
            $safe,
            $row['id']
        );

        echo json_encode(['success' => true]);
    }


