    public function admin_add_booster()
    {
        if ($this->is_admin) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'username' => 'required',
                'games' => 'required',
                'rank_id' => 'required',
                'email' => 'required|email',
                'lol_tier_limit' => 'required',
                'lol_division_limit' => 'required',
                'val_tier_limit' => 'required',
                'val_division_limit' => 'required',
                'order_limit' => 'required',
            ]);
            $validation->validate();

            // if validation fails, return errors
            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $_POST['lol_rank_limit'] = $_POST['lol_tier_limit'] . '|' . $_POST['lol_division_limit'];
                $_POST['val_rank_limit'] = $_POST['val_tier_limit'] . '|' . $_POST['val_division_limit'];
                unset($_POST['lol_division_limit']);
                unset($_POST['lol_tier_limit']);
                unset($_POST['val_division_limit']);
                unset($_POST['val_tier_limit']);
                unset($_POST['tft_division_limit']);
                unset($_POST['tft_tier_limit']);
                $params = esc_array($_POST);
                $password = generate_password();
                $params['password'] = sha1($password);
                $params['games'] = implode('|', $params['games']);
                $params['verified'] = 0;
                $params['rating'] = random_booster_start_rating();
                $booster_limits = [
                    'lol_rank_limit' => $params['lol_rank_limit'],
                    'val_rank_limit' => $params['val_rank_limit'],
                    'order_limit' => $params['order_limit'],
                ];
                $params = array_diff_key($params, array_flip(['lol_rank_limit', 'val_rank_limit', 'tft_rank_limit', 'order_limit']));
                $booster_id = db_add_row('boosters', $params);
                if ($booster_id != false) {
                    $booster_limits['booster_id'] = $booster_id;
                    db_add_row('booster_limits', $booster_limits);
                    $form_error = false;
                    log_admin_action(ADMIN_ID, 'Added new booster #' . $booster_id);
                    db_insert_row('notifications', [
                        'type' => 'welcome_booster',
                        'data' => json_encode([
                            'action_url' => base64_encode(BSTR_URL . '/auth/login'),
                            'email' => base64_encode($params['email']),
                            'password' => base64_encode($password),
                        ]),
                        'recipient' => 'booster',
                        'recipient_id' => $booster_id,
                        'is_email' => 1,
                        'is_web' => 1,
                    ]);
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Booster added successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'redirectUrl' => ADMN_URL . '/booster/' . $booster_id
                    ));
                } else {
                    $form_error = $booster_id;
                }
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => is_array($form_error) ? implode(' | ', $form_error) : (string)$form_error,
                    ],
                    'playSound' => 'error',
                    'validationErrors' => $form_error,
                ]);
            }
        }
    }

    public function admin_update_booster()
    {
        if (!$this->is_admin) {
            return;
        }

        global $db;

        $booster_id = intval($_POST['id'] ?? 0);
        unset($_POST['id']);

        // Normalize multi-select fields before validation. TomSelect may submit
        // a scalar, a JSON string, a pipe-separated value or a real array.
        $normalizeMulti = static function ($value): array {
            if (is_array($value)) {
                $items = $value;
            } else {
                $raw = trim((string)$value);
                if ($raw === '') {
                    return [];
                }

                $decoded = json_decode($raw, true);
                if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
                    $items = $decoded;
                } else {
                    $items = preg_split('/[|,]+/', $raw) ?: [];
                }
            }

            $result = [];
            foreach ($items as $item) {
                $item = strtolower(trim((string)$item));
                $item = str_replace(' ', '-', $item);
                if ($item === '') {
                    continue;
                }

                // Keep legacy core values compatible with the rest of the app.
                $aliases = [
                    'league-of-legends' => 'lol',
                    'leagueoflegends' => 'lol',
                    'valorant' => 'val',
                    'teamfight-tactics' => 'tft',
                    'teamfighttactics' => 'tft',
                    'lol-classic' => 'lol_classic',
                    'league-of-legends-classic' => 'lol_classic',
                ];
                $item = $aliases[$item] ?? $item;
                $result[] = $item;
            }

            return array_values(array_unique($result));
        };

        $_POST['games'] = $normalizeMulti($_POST['games'] ?? []);
        $_POST['languages'] = $normalizeMulti($_POST['languages'] ?? []);

        $validator = new Validator();
        $validation = $validator->make($_POST, [
            'username' => 'required',
            'rank_id' => 'required',
            'email' => 'required|email',
            'games' => 'required',
            'order_limit' => 'required',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $form_error = $validation->errors()->firstOfAll();
        } elseif ($booster_id <= 0 || empty($_POST['games'])) {
            $form_error = ['games' => 'Please select at least one game.'];
        } else {
            $games = $_POST['games'];

            // Build rank limits only for selected games.
            if (in_array('lol', $games, true) || in_array('lol_classic', $games, true)) {
                $lolTier = intval($_POST['lol_tier_limit'] ?? 1);
                $lolDivision = intval($_POST['lol_division_limit'] ?? 4);
                if ($lolTier > 7) {
                    $lolDivision = 4;
                }
                $_POST['lol_rank_limit'] = $lolTier . '|' . $lolDivision;
            }

            if (in_array('val', $games, true)) {
                $valTier = intval($_POST['val_tier_limit'] ?? 1);
                $valDivision = intval($_POST['val_division_limit'] ?? 3);
                if ($valTier > 7) {
                    $valDivision = 3;
                }
                $_POST['val_rank_limit'] = $valTier . '|' . $valDivision;
            }

            if (in_array('tft', $games, true)) {
                $tftTier = intval($_POST['tft_tier_limit'] ?? 7);
                $tftDivision = intval($_POST['tft_division_limit'] ?? 4);
                if ($tftTier > 7) {
                    $tftDivision = 4;
                }
                $_POST['tft_rank_limit'] = $tftTier . '|' . $tftDivision;
            }

            // These columns belong to booster_limits, never to boosters.
            $limitColumns = [
                'order_limit',
                'solo_order_limit',
                'duo_order_limit',
                'lol_solo_order_limit',
                'lol_duo_order_limit',
                'val_solo_order_limit',
                'val_duo_order_limit',
                'tft_order_limit',
                'lol_classic_solo_order_limit',
                'lol_classic_duo_order_limit',
                'lol_rank_limit',
                'val_rank_limit',
                'tft_rank_limit',
            ];

            $booster_limits = [];
            foreach ($limitColumns as $column) {
                if (array_key_exists($column, $_POST)) {
                    $value = $_POST[$column];
                    if (str_ends_with($column, '_rank_limit')) {
                        $booster_limits[$column] = trim((string)$value);
                    } else {
                        $booster_limits[$column] = max(0, intval($value));
                    }
                    unset($_POST[$column]);
                }
            }

            // Keep the general limit available even when only game-specific
            // limit fields were edited.
            if (!array_key_exists('order_limit', $booster_limits)) {
                $booster_limits['order_limit'] = max(0, intval($_POST['order_limit'] ?? 0));
            }

            unset(
                $_POST['lol_division_limit'],
                $_POST['lol_tier_limit'],
                $_POST['val_division_limit'],
                $_POST['val_tier_limit'],
                $_POST['tft_division_limit'],
                $_POST['tft_tier_limit']
            );

            $params = esc_array($_POST);
            $params['games'] = implode('|', $games);
            $params['languages'] = implode('|', $_POST['languages']);

            // The legacy schema used VARCHAR(100) for boosters.games. That was
            // sufficient for the original three short game keys, but truncates
            // the pipe-separated value now that admins can select every dynamic
            // game slug. A truncated slug no longer matches an option after a
            // reload, which makes the selection appear to have vanished.
            try {
                $gamesColumn = $db->row("SHOW COLUMNS FROM boosters LIKE 'games'");
                $gamesColumnType = strtolower((string)($gamesColumn['Type'] ?? ''));
                if (preg_match('/^varchar\((\d+)\)$/', $gamesColumnType, $matches)
                    && strlen($params['games']) > (int)$matches[1]) {
                    $db->run("ALTER TABLE boosters MODIFY games TEXT NOT NULL");

                    $gamesColumn = $db->row("SHOW COLUMNS FROM boosters LIKE 'games'");
                    $gamesColumnType = strtolower((string)($gamesColumn['Type'] ?? ''));
                    if (preg_match('/^varchar\((\d+)\)$/', $gamesColumnType, $matches)
                        && strlen($params['games']) > (int)$matches[1]) {
                        throw new \RuntimeException('boosters.games could not be expanded');
                    }
                }
            } catch (\Throwable $e) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'The Games field is too small in the database and could not be expanded.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            if (empty($params['password'])) {
                unset($params['password']);
            } else {
                $params['password'] = sha1($params['password']);
            }

            $update = db_update_row('boosters', ['id' => $booster_id], $params);
            if ($update !== false) {
                $existing_limits = db_get_row('booster_limits', ['booster_id' => $booster_id], 1);
                if ($existing_limits == false) {
                    $limits_update = db_add_row('booster_limits', array_merge([
                        'booster_id' => $booster_id,
                    ], $booster_limits));
                } else {
                    $limits_update = db_update_row('booster_limits', ['booster_id' => $booster_id], $booster_limits);
                }

                if ($limits_update !== false) {
                    $form_error = false;
                    log_admin_action(ADMIN_ID, 'Updated booster account #' . $booster_id);
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Booster updated successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'redirectUrl' => ADMN_URL . '/booster/' . $booster_id,
                    ]);
                    return;
                }

                $form_error = $limits_update;
            } else {
                $form_error = $update;
            }
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => is_array($form_error ?? null)
                    ? implode(' | ', array_filter(array_map('strval', $form_error)))
                    : 'Could not update the booster settings.',
            ],
            'playSound' => 'error',
            'validationErrors' => $form_error ?? [],
        ]);
    }

    public function admin_update_booster_profile()
    {
        if ($this->is_admin) {
            $booster_id = intval($_POST['id']);
            unset($_POST['id']);
            $gameProfilesRaw = (string)($_POST['game_profiles'] ?? '');
            $gameProfiles = json_decode($gameProfilesRaw, true);
            if (!is_array($gameProfiles)) $gameProfiles = [];
            foreach ((array)($_POST['game_rank_tier'] ?? []) as $gameSlug => $tier) {
                $gameProfiles[$gameSlug]['rank_tier'] = (int)$tier;
                $gameProfiles[$gameSlug]['rank_division'] = (int)(($_POST['game_rank_division'] ?? [])[$gameSlug] ?? 0);
                $gameProfiles[$gameSlug]['specialties'] = (array)(($_POST['game_specialties'] ?? [])[$gameSlug] ?? []);
            }
            unset($_POST['game_profiles'], $_POST['game_rank_tier'], $_POST['game_rank_division'], $_POST['game_specialties']);
            // Never pass game slugs such as "apex-legends" to EasyDB as column names.
            foreach (array_keys($_POST) as $postKey) {
                if (!preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/', (string)$postKey)) unset($_POST[$postKey]);
            }

            // Some fields on the admin "Booster Profile" form actually belong to booster_limits,
            // not booster_profiles. Keep them separated to avoid updating non-existent columns.
            $booster_limits_update = [];

            // TFT rank limit comes from two selects in the admin profile form
            // (tft_tier_limit + tft_division_limit). The DB stores this as tft_rank_limit (tier|division).
            // If we don't normalize/unset these, EasyDB will try to UPDATE non-existent columns
            // (tft_tier_limit / tft_division_limit) and the request will fail with a PDOException.
            if (array_key_exists('tft_tier_limit', $_POST) || array_key_exists('tft_division_limit', $_POST)) {
                $tier = isset($_POST['tft_tier_limit']) ? intval($_POST['tft_tier_limit']) : 0;
                $division = isset($_POST['tft_division_limit']) ? intval($_POST['tft_division_limit']) : 0;
                // Master+ has no divisions in TFT -> store as Division I (4)
                if ($tier > 7) {
                    $division = 4;
                }
                // This value is stored in booster_limits.tft_rank_limit
                $booster_limits_update['tft_rank_limit'] = $tier . '|' . $division;
                unset($_POST['tft_tier_limit'], $_POST['tft_division_limit']);
            }

            if (!isset($_POST['champions']))
                $_POST['champions'] = [];
            if (!isset($_POST['roles']))
                $_POST['roles'] = [];

            // NEW: servers default (damit leere Auswahl sauber gespeichert wird)
            if (!isset($_POST['servers']))
                $_POST['servers'] = [];

            // OPTIONAL (empfohlen): allowlist, damit nur bekannte server keys gespeichert werden
            $allowedServers = function_exists('util_servers_list') ? util_servers_list() : [];
            if (!empty($allowedServers) && is_array($_POST['servers'])) {
                $_POST['servers'] = array_values(array_unique(array_filter(
                    array_map('strtolower', $_POST['servers']),
                    function ($s) use ($allowedServers) {
                        return in_array($s, $allowedServers, true);
                    }
                )));
            }

            foreach ($_POST as $key => $value) {
                if (is_array($value)) {
                    $value = array_values(array_unique(array_filter(array_map('trim', $value), static function ($item) {
                        return $item !== '';
                    })));
                    $_POST[$key] = esc(implode('|', $value));
                }
            }

            if (isset($_POST['lol'])) {
                $_POST['lol_rank_0'] = intval($_POST['lol_rank_0']) ?? 0;
                $_POST['lol_rank_1'] = intval($_POST['lol_rank_1']) ?? 0;
                $_POST['lol_rank'] = $_POST['lol_rank_0'] . '|' . $_POST['lol_rank_1'];
            }
            if (isset($_POST['val'])) {
                $_POST['val_rank_0'] = intval($_POST['val_rank_0']) ?? 0;
                $_POST['val_rank_1'] = intval($_POST['val_rank_1']) ?? 0;
                $_POST['val_rank'] = $_POST['val_rank_0'] . '|' . $_POST['val_rank_1'];
            }
            if (isset($_POST['tft'])) {
                $_POST['tft_rank_0'] = intval($_POST['tft_rank_0']) ?? 0;
                $_POST['tft_rank_1'] = intval($_POST['tft_rank_1']) ?? 0;
                $_POST['tft_rank'] = $_POST['tft_rank_0'] . '|' . $_POST['tft_rank_1'];
            }

            unset($_POST['lol_rank_0'], $_POST['lol_rank_1'], $_POST['val_rank_0'], $_POST['val_rank_1'], $_POST['tft_rank_0'], $_POST['tft_rank_1'], $_POST['lol'], $_POST['val'], $_POST['tft']);

            // Validate/normalize timezone (optional). Empty means "N/A" (not set)
            if (array_key_exists('timezone', $_POST)) {
                $tz = $_POST['timezone'];
                $tz = is_string($tz) ? trim($tz) : '';
                if ($tz === '') {
                    $_POST['timezone'] = '';
                } else {
                    $valid_timezones = DateTimeZone::listIdentifiers();
                    if (!in_array($tz, $valid_timezones, true)) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Error',
                                'message' => 'Please select a valid timezone 😔',
                            ],
                            'playSound' => 'error',
                            'validationErrors' => ['timezone' => 'Please select a valid timezone'],
                        ]);
                        return;
                    }
                    $_POST['timezone'] = $tz;
                }
            }


            $post_params = esc_array($_POST);

            try {
                // 1) Update booster_profiles
                $upd_booster = db_update_row('booster_profiles', ['booster_id' => $booster_id], $post_params);

                // 2) Update booster_limits (if present)
                if (!empty($booster_limits_update)) {
                    $existing_limits = db_get_row('booster_limits', ['booster_id' => $booster_id], 1);
                    if ($existing_limits == false) {
                        db_add_row('booster_limits', array_merge(['booster_id' => $booster_id], $booster_limits_update));
                    } else {
                        db_update_row('booster_limits', ['booster_id' => $booster_id], $booster_limits_update);
                    }
                }
            } catch (\Throwable $e) {
                // Always return JSON so the frontend doesn't fail JSON.parse() silently
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Database error while updating the booster profile 😔',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            if ($upd_booster) {
                if (is_array($gameProfiles)) lb_booster_game_profiles_save($booster_id, $gameProfiles);
                log_admin_action(ADMIN_ID, 'Updated booster profile #' . $booster_id);
                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Booster profile updated successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                    'refreshPageNow' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    /**
     * Re-verifies a booster whose Orders Panel activity went stale.
     *
     * The booster layout locks order claiming once `last_order_check` is older
     * than 14 days; setting it to now lifts that lock.
     */
    public function admin_mark_booster_checked()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        $booster_id = (int)($_POST['id'] ?? 0);
        if ($booster_id <= 0 || !db_get_row('boosters', ['id' => $booster_id])) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Booster not found.']]);
            return;
        }

        db_update_row('boosters', ['id' => $booster_id], ['last_order_check' => date('Y-m-d H:i:s')]);

        echo json_encode([
            'success'     => true,
            'sendToast'   => ['type' => 'success', 'title' => 'Verified', 'message' => 'Account verified. Order claiming is enabled again.'],
            'refreshPage' => true,
        ]);
    }

    public function admin_update_booster_personals()
    {
        if ($this->is_admin) {
            $booster_id = intval($_POST['id']);
            unset($_POST['id']);
            $booster = db_get_row('boosters', ['id' => $booster_id]);

            $post_params = esc_array($_POST);

            $upd_booster = db_update_row('booster_personal_details', ['booster_id' => $booster_id], $post_params);

            $id_card_front = $_FILES['id_front'] ?? [];
            $id_card_back = $_FILES['id_back'] ?? [];
            $selfie = $_FILES['selfie'] ?? [];

            if ($id_card_front['name'] != '') {
                $image_url = upload_image($id_card_front, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['id_front' => $image_url]);

                }
            }

            if ($id_card_back['name'] != '') {
                $image_url = upload_image($id_card_back, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['id_back' => $image_url]);
                }
            }

            if ($selfie['name'] != '') {
                $image_url = upload_image($selfie, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['selfie' => $image_url]);
                }
            }

            $updated_booster = db_get_row('booster_personal_details', ['booster_id' => $booster_id]);
            $docs_complete = $this->pd_docs_complete($updated_booster);
            db_update_row('boosters', ['id' => $booster_id], ['docs_complete' => $docs_complete]);

if ($upd_booster) {
                log_admin_action(ADMIN_ID, 'Updated booster personal details #' . $booster_id);
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Booster Personal Details Updated Successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ));
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    /**
     * Resolves the admin username behind an onboarding link.
     * Falls back to "Unknown" for links generated before the creator was tracked.
     */
    private function onboarding_hired_by_label($admin_id): string
    {
        global $db;

        $admin_id = (int)$admin_id;
        if ($admin_id <= 0) {
            return 'Unknown';
        }

        try {
            $admin = $db->row("SELECT username, email FROM admins WHERE id = ? LIMIT 1", $admin_id);
            $username = trim((string)($admin['username'] ?? ''));
            if ($username !== '') {
                return $username;
            }
            $email = trim((string)($admin['email'] ?? ''));
            if ($email !== '') {
                return $email;
            }
        } catch (\Throwable $e) {}

        return 'Admin #' . $admin_id;
    }

    /**
     * Reads hired_by_admin_id back from the freshly created booster/seller row.
     */
    private function onboarding_stored_hired_by(string $kind, int $record_id): int
    {
        global $db;

        if ($record_id <= 0) {
            return 0;
        }

        $table = ($kind === 'seller') ? 'sellers' : 'boosters';

        try {
            $row = $db->row("SELECT hired_by_admin_id FROM {$table} WHERE id = ? LIMIT 1", $record_id);
        } catch (\Throwable $e) {
            return 0;
        }

        return (int)($row['hired_by_admin_id'] ?? 0);
    }

    /**
     * Detailed Discord notice fired when someone finishes onboarding.
     * Covers boosters, GG Girls and sellers with the same embed layout.
     *
     * @param string $kind booster|egirl|seller
     */
    private function send_onboarding_complete_webhook(string $kind, int $record_id, array $data): void
    {
        $webhookUrl = "https://discord.com/api/webhooks/1387889082218057898/lDxgfWuT6l9vjjsB6PWjjipcXhyRuBWeyEDNCE5pHsR0IaTe5ntznA4aFuGV3E8fuG6O";

        $games_list = array_values(array_filter(explode('|', (string)($data['games'] ?? '')), 'strlen'));
        $games_label = '—';
        if (!empty($games_list)) {
            $games_label = implode(', ', array_map(static function ($slug) {
                return function_exists('util_game_display_name')
                    ? util_game_display_name($slug)
                    : ucwords(str_replace(['-', '_'], ' ', $slug));
            }, $games_list));
        }

        // Discord thumbnails need an absolute URL and cannot render SVG.
        $thumbnail_url = '';
        if (!empty($games_list) && function_exists('util_game_icon_url')) {
            $icon = trim((string)util_game_icon_url((string)$games_list[0]));
            if ($icon !== '' && !preg_match('~\.svg($|\?)~i', $icon)) {
                if (!preg_match('~^https?://~i', $icon)) {
                    $icon = rtrim((string)BASE_URL, '/') . '/' . ltrim($icon, '/');
                }
                $thumbnail_url = $icon;
            }
        }

        $titles = ['booster' => 'New Booster', 'egirl' => 'New GG Girl', 'seller' => 'New Seller'];
        $colors = ['booster' => hexdec("5865F2"), 'egirl' => hexdec("E91E8C"), 'seller' => hexdec("2ECC71")];
        $links  = [
            'booster' => BASE_URL . '/admin-area/booster/' . $record_id,
            'egirl'   => BASE_URL . '/admin-area/booster/' . $record_id,
            'seller'  => BASE_URL . '/admin-area/seller/' . $record_id,
        ];

        $fields = [
            ["name" => "Username", "value" => esc((string)($data['username'] ?? '')) ?: '—', "inline" => false],
        ];
        if ($kind !== 'seller') {
            $fields[] = ["name" => "Games", "value" => $games_label, "inline" => true];
        }
        // The caller may not have been able to resolve the link creator (lost token).
        // The stored record is the second source before falling back to "Unknown".
        $hired_by_admin_id = (int)($data['hired_by_admin_id'] ?? 0);
        if ($hired_by_admin_id <= 0) {
            $hired_by_admin_id = $this->onboarding_stored_hired_by($kind, $record_id);
        }
        $fields[] = ["name" => "Hired by", "value" => $this->onboarding_hired_by_label($hired_by_admin_id), "inline" => true];
        $fields[] = ["name" => "Country", "value" => esc(trim((string)($data['country'] ?? '')) ?: '—'), "inline" => true];
        $fields[] = ["name" => "Full name", "value" => esc(trim((string)($data['fullname'] ?? '')) ?: '—'), "inline" => true];
        $fields[] = ["name" => "Email", "value" => esc(trim((string)($data['email'] ?? '')) ?: '—'), "inline" => true];
        $fields[] = ["name" => "Status", "value" => "⏳ Onboarding completed — waiting for admin activation", "inline" => false];
        $fields[] = ["name" => "Action", "value" => "[🚀 Verify & Activate](" . ($links[$kind] ?? $links['booster']) . ")", "inline" => false];

        $embed = [
            "title" => $titles[$kind] ?? 'New Application',
            "description" => "Onboarding has been completed. Please review and activate the account.",
            "color" => $colors[$kind] ?? hexdec("5865F2"),
            "fields" => $fields,
            "timestamp" => date("c"),
        ];
        if ($thumbnail_url !== '') {
            $embed['thumbnail'] = ['url' => $thumbnail_url];
        }

        $payload = [
            "username" => "New Booster Notif",
            "content" => "<@&1083064775623327784> <@&1295032857907171339>",
            "allowed_mentions" => [
                "roles" => ["1083064775623327784", "1295032857907171339"]
            ],
            "embeds" => [$embed],
        ];

        $ch = curl_init($webhookUrl);
        curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
        curl_setopt($ch, CURLOPT_POST, 1);
        curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload));
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
        curl_setopt($ch, CURLOPT_HEADER, 0);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_TIMEOUT, 5);
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
        curl_exec($ch);
        curl_close($ch);
    }

    public function admin_verify_booster()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $booster_id = (int)($_POST['id'] ?? $_POST['booster_id'] ?? $_POST['egirl_id'] ?? $_POST['user_id'] ?? 0);
        if ($booster_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $password = generate_password();
        $booster = db_get_row('boosters', ['id' => $booster_id]);

        if (!$booster) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Booster not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $is_egirl = !empty($booster['is_egirl']) && (int)$booster['is_egirl'] === 1;

        $activation_time = trim((string)($booster['created_at'] ?? ''));
        if ($activation_time === '' || $activation_time === '0000-00-00 00:00:00' || strtotime($activation_time) === false) {
            $activation_time = date('Y-m-d H:i:s');
        }

        $updated = db_update_row('boosters', ['id' => $booster_id], [
            'verified' => 1,
            'is_banned' => 0,
            'password' => sha1($password),
            'last_order_check' => $activation_time,
        ]);

        if (!$updated) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => 'Could not verify account.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $email_type = $is_egirl ? 'welcome_egirl' : 'welcome_booster';
        $success_msg = $is_egirl ? 'eGirl verified successfully and login sent 🎉' : 'Booster verified successfully and login sent 🎉';

        log_admin_action(ADMIN_ID, 'Added verified ' . ($is_egirl ? 'egirl' : 'booster') . ' #' . $booster_id);
        $notif = db_insert_row('notifications', [
            'type' => $email_type,
            'data' => json_encode([
                'action_url' => base64_encode(BSTR_URL . '/auth/login'),
                'email' => base64_encode($booster['email']),
                'password' => base64_encode($password),
            ]),
            'recipient' => 'booster',
            'recipient_id' => $booster_id,
            'is_email' => 1,
            'is_web' => 1,
        ]);

        if (!$notif) {
            echo json_encode([
                'sendToast' => ['type' => 'warning', 'title' => 'Partially done', 'message' => 'Verified, but login email notification could not be created.'],
                'playSound' => 'warning',
                'refreshPage' => true,
            ]);
            return;
        }

        echo json_encode(array(
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => $success_msg,
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ));
    }
