    public function admin_resend_booster_login()
    {
        $booster_id = (int)($_POST['id'] ?? $_POST['booster_id'] ?? $_POST['egirl_id'] ?? $_POST['user_id'] ?? 0);
        $booster = db_get_row('boosters', ['id' => $booster_id]);

        if (!$booster) {
            echo json_encode(array(
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Booster not found.',
                ],
                'playSound' => 'error',
            ));
            return;
        }

        // Only resend for approved boosters (admin verified)
        if ((int)($booster['verified'] ?? 0) !== 1) {
            echo json_encode(array(
                'sendToast' => [
                    'type' => 'warning',
                    'title' => 'Not verified',
                    'message' => 'This booster is not admin-verified yet. Use "Verify" first.',
                ],
                'playSound' => 'warning',
            ));
            return;
        }

        if ((int)($booster['is_banned'] ?? 0) === 1) {
            echo json_encode(array(
                'sendToast' => [
                    'type' => 'warning',
                    'title' => 'Booster banned',
                    'message' => 'This booster is banned/pending. Unban or verify before sending logins.',
                ],
                'playSound' => 'warning',
            ));
            return;
        }

        $password = generate_password();

        db_update_row('boosters', ['id' => $booster_id], [
            'password' => sha1($password),
        ]);

        log_admin_action(ADMIN_ID, 'Resent booster login email #' . $booster_id);

        db_insert_row('notifications', [
            'type' => 'welcome_booster',
            'data' => json_encode([
                'action_url' => base64_encode(BSTR_URL . '/auth/login'),
                'email' => base64_encode($booster['email']),
                'password' => base64_encode($password),
            ]),
            'recipient' => 'booster',
            'recipient_id' => $booster_id,
            'is_email' => 1,
            'is_web' => 1,
        ]);

        echo json_encode(array(
            'sendToast' => [
                'type' => 'success',
                'title' => 'Sent',
                'message' => 'Login email sent. A new password was generated.',
            ],
            'playSound' => 'success',
        ));
    }



    public function admin_logout_booster_sessions()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
            return;
        }

        $booster_id = (int)($_POST['id'] ?? $_POST['booster_id'] ?? 0);

        if ($booster_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid booster ID.'],
            ]);
            return;
        }

        $booster = db_get_row('boosters', ['id' => $booster_id]);
        if (!$booster) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Booster not found.'],
            ]);
            return;
        }

        // Delete active session + all presence logs
        db_delete_rows('booster_sessions', ['booster_id' => $booster_id]);
        db_delete_rows('booster_session_logs', ['booster_id' => $booster_id]);

        log_admin_action(ADMIN_ID, 'Logged out all sessions for booster #' . $booster_id);

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Logged out',
                'message' => 'All active sessions for this booster have been terminated.',
            ],
            'playSound' => 'success',
            'reloadPage' => true,
        ]);
    }



    public function admin_decline_booster()
    {
        $booster_id = (int)($_POST['id'] ?? $_POST['booster_id'] ?? $_POST['egirl_id'] ?? $_POST['user_id'] ?? 0);
