    public function admin_decline_egirl()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
            return;
        }
        $booster_id = (int)($_POST['id'] ?? $_POST['egirl_id'] ?? 0);
        if ($booster_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid ID.']]);
            return;
        }
        global $db;
        $egirl = $db->row("SELECT id FROM boosters WHERE id = ? AND is_egirl = 1 LIMIT 1", $booster_id);
        if (!$egirl) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'E-Girl not found.']]);
            return;
        }
        $db->run("DELETE FROM boosters WHERE id = ? AND is_egirl = 1", $booster_id);
        $db->run("DELETE FROM egirl_profiles WHERE egirl_id = ?", $booster_id);
        $db->run("DELETE FROM egirl_balance WHERE egirl_id = ?", $booster_id);
        $db->run("DELETE FROM egirl_services WHERE egirl_id = ?", $booster_id);
        $db->run("DELETE FROM booster_sessions WHERE booster_id = ?", $booster_id);
        log_admin_action(ADMIN_ID, 'Declined & deleted E-Girl application #' . $booster_id);
        echo json_encode([
            'success'     => true,
            'sendToast'   => ['type' => 'success', 'title' => 'Declined', 'message' => 'E-Girl application declined and removed.'],
            'playSound'   => 'success',
            'redirectUrl' => ADMN_URL . '/egirls',
        ]);
    }

