    public function admin_unban_booster()
    {
        if ($this->is_admin) {
            $booster_id = intval($_POST['id']);
            $booster = db_get_row('boosters', ['id' => $booster_id]);

            $activation_data = ['is_banned' => 0];
            $last_order_check = trim((string)($booster['last_order_check'] ?? ''));

            if ($last_order_check === '' || $last_order_check === '0000-00-00 00:00:00' || strtotime($last_order_check) === false) {
                $activation_time = trim((string)($booster['created_at'] ?? ''));
                if ($activation_time === '' || $activation_time === '0000-00-00 00:00:00' || strtotime($activation_time) === false) {
                    $activation_time = date('Y-m-d H:i:s');
                }
                $activation_data['last_order_check'] = $activation_time;
            }

            $upd_booster = db_update_row('boosters', ['id' => $booster_id], $activation_data);
            if ($upd_booster) {
                log_admin_action(ADMIN_ID, 'Unbanned booster account #' . $booster_id);
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Booster unbanned successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ));
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    public function admin_update_client()
    {
        if ($this->is_admin) {
            $client_id = intval($_POST['id']);
            unset($_POST['id']);
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'username' => 'required',
                'email' => 'required|email',
            ]);
            $validation->validate();

            // if validation fails, return errors
            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $_POST['referral_enabled'] = isset($_POST['referral_enabled']) ? 1 : 0;
                if (isset($_POST['referral_percent'])) {
                    $referralPercentRaw = trim((string)$_POST['referral_percent']);
                    if ($referralPercentRaw === '') {
                        $_POST['referral_percent'] = null;
                    } else {
                        $referralPercentRaw = str_replace(',', '.', $referralPercentRaw);
                        $_POST['referral_percent'] = max(0, min(100, round((float)$referralPercentRaw, 2)));
                    }
                }
                $params = esc_array($_POST);
                if (array_key_exists('referral_percent', $_POST) && $_POST['referral_percent'] === null) {
                    $params['referral_percent'] = null;
                }

                // if password is empty, unset it
                if (empty($params['password'])) {
                    unset($params['password']);
                } else {
                    $params['password'] = sha1($params['password']);
                }

                $update = db_update_row('clients', ['id' => $client_id], $params);
                if ($update != false) {
                    $form_error = false;
                    log_admin_action(ADMIN_ID, 'Updated client account #' . $client_id);
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Client updated successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'redirectUrl' => ADMN_URL . '/client/' . $client_id
                    ));
                } else {
                    $form_error = $update;
                }
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please fill in all the fields 😔',
                    ],
                    'playSound' => 'error',
                    'validationErrors' => $form_error,
                ]);
            }
        }
    }

