    public function admin_delete_client()
    {
        if ($this->is_admin) {
            global $db;

            $client_id = intval($_POST['id'] ?? 0);
            $reason = esc($_POST['reason'] ?? '');
            $details = esc($_POST['details'] ?? '');

            $client = db_get_row('clients', ['id' => $client_id]);
            if (!$client) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Client not found 😔',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            if (!empty($client['is_deleted'])) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'warning',
                        'title' => 'Already deleted',
                        'message' => 'This client account is already deleted.',
                    ],
                    'refreshPage' => true,
                ]);
                return;
            }

            $old_email = (string)($client['email'] ?? '');
            $deleted_email = $old_email !== '' ? $old_email : (string)($client['deleted_email'] ?? '');
            $replacement_email = 'deleted_client_' . $client_id . '_' . time() . '@deleted.local';

            $upd_client = db_update_row('clients', ['id' => $client_id], [
                'is_deleted' => 1,
                'is_banned' => 1,
                'deleted_at' => date('Y-m-d H:i:s'),
                'deleted_email' => $deleted_email,
                'deleted_reason' => $reason,
                'deleted_details' => $details,
                'deleted_by_admin_id' => ADMIN_ID,
                'email' => $replacement_email,
                'password' => null,
                'recovery_id' => null,
            ]);

            if ($upd_client) {
                // Kill active client sessions immediately.
                try {
                    $db->run('DELETE FROM client_sessions WHERE client_id = ?', $client_id);
                } catch (Throwable $e) {
                    // Keep the delete action successful even if old sessions cannot be cleaned.
                }

                log_admin_action(ADMIN_ID, 'Deleted client account #' . $client_id . ' for reason: ' . $reason . ' with details: ' . $details);
                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Client account deleted successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                    'refreshPageNow' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

