    public function egirl_set_unpaid()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $order = db_get_row('egirl_orders', ['id' => $order_id], 1);

        if (!$order) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'E-Girl order not found'],
                'playSound' => 'error',
            ]);
            return;
        }

        db_update_row('egirl_orders', ['id' => $order_id], [
            'status' => 'UNPAID',
            'claimed_at' => null,
            'completed_at' => null,
        ]);

        if (!empty($order['invoice_id'])) {
            db_update_row('invoices', ['id' => (int)$order['invoice_id']], [
                'status' => 'UNPAID',
                'paid_at' => null,
            ]);
        }

        log_admin_action(ADMIN_ID, 'Set E-Girl order #' . $order_id . ' to UNPAID');

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Updated', 'message' => 'E-Girl order set to UNPAID'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

