    public function egirl_remove_assigned_girl()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $order = db_get_row('egirl_orders', ['id' => $order_id], 1);

        if (!$order) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'E-Girl order not found'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (empty($order['egirl_id'])) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No GG-Girl is currently assigned to this order'],
                'playSound' => 'error',
            ]);
            return;
        }

        $removedEgirlId = (int)$order['egirl_id'];

        $updates = [
            'egirl_id'   => 0,
            'claimed_at' => null,
        ];

        // If the order was already claimed/in progress, send it back into the
        // open booking pool so any GG-Girl can pick it up again.
        if (($order['status'] ?? '') === 'IN_PROGRESS') {
            $updates['status'] = 'PAID';
        }

        db_update_row('egirl_orders', ['id' => $order_id], $updates);

        $this->add_egirl_site_notification('egirl_booking_removed', $removedEgirlId, [
            'order_id' => $order_id,
            'egirl_id' => $removedEgirlId,
            'client_id' => (int)($order['client_id'] ?? 0),
            'status' => 'REMOVED',
        ]);

        log_admin_action(ADMIN_ID, 'Removed assigned GG-Girl (#' . $removedEgirlId . ') from E-Girl order #' . $order_id);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Removed', 'message' => 'GG-Girl removed from order. It is now available again in the booking panel.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function egirl_assign_girl()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $egirl_id = (int)($_POST['egirl_id'] ?? 0);

        $order = db_get_row('egirl_orders', ['id' => $order_id], 1);
        if (!$order) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'E-Girl order not found'],
                'playSound' => 'error',
            ]);
            return;
        }

        if ($egirl_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select a GG-Girl'],
                'playSound' => 'error',
            ]);
            return;
        }

        $egirl = db_get_row('boosters', ['id' => $egirl_id, 'is_egirl' => 1, 'is_banned' => 0], 1);
        if (!$egirl) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Selected GG-Girl is not available'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Same duration parsing as egirl_accept_order, so admin-assigned
        // sessions get a correct session_end_at timer too.
        $unit_value = (float)($order['unit_value'] ?? 1);
        $unit_type  = strtolower((string)($order['unit_type'] ?? 'hours'));
        if (in_array($unit_type, ['minute', 'minutes', 'min', 'mins'], true)) {
            $duration_seconds = (int)round($unit_value * 60);
        } elseif (in_array($unit_type, ['day', 'days'], true)) {
            $duration_seconds = (int)round($unit_value * 86400);
        } else {
            $duration_seconds = (int)round($unit_value * 3600);
        }
        if ($duration_seconds <= 0) {
            $duration_seconds = 3600;
        }

        $now_dt = date('Y-m-d H:i:s');
        $session_end_at = date('Y-m-d H:i:s', time() + $duration_seconds);

        $egirl_cut = (array_key_exists('egirl_cut_percent', $egirl) && $egirl['egirl_cut_percent'] !== null && $egirl['egirl_cut_percent'] !== '')
            ? (float)$egirl['egirl_cut_percent']
            : 60.0;

        db_update_row('egirl_orders', ['id' => $order_id], [
            'egirl_id'    => $egirl_id,
            'egirl_cut'   => $egirl_cut,
            'status'      => 'IN_PROGRESS',
            'claimed_at'  => $now_dt,
            'session_end_at' => $session_end_at,
            'is_paused'   => 0,
            'paused_remaining_seconds' => null,
        ]);

        db_add_row('egirl_notifications', [
            'egirl_id'   => $egirl_id,
            'type'       => 'order_assigned',
            'data'       => json_encode(['order_id' => $order_id, 'client_id' => (int)($order['client_id'] ?? 0)]),
            'created_at' => date('Y-m-d H:i:s'),
        ]);

        $this->add_egirl_site_notification('egirl_booking_assigned', $egirl_id, [
            'order_id' => $order_id,
            'egirl_id' => $egirl_id,
            'client_id' => (int)($order['client_id'] ?? 0),
            'status' => 'IN_PROGRESS',
        ], true);

        log_admin_action(ADMIN_ID, 'Assigned GG-Girl #' . $egirl_id . ' to E-Girl order #' . $order_id);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Assigned', 'message' => 'GG-Girl assigned to order and session started.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }


    public function admin_order_chat_send()
    {
        if ($this->is_admin) {

            $order_id = esc($_POST['order_id'] ?? 0);
            $message  = esc($_POST['message'] ?? '');

                        // Optional image upload
            $image_url = null;
            $fileKey = null;
            if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
                $fileKey = 'chat_image';
            } elseif (isset($_FILES['image_url']) && !empty($_FILES['image_url']['tmp_name'])) { // backwards compatibility
                $fileKey = 'image_url';
            }

            if ($fileKey) {
                $image_url = upload_image($_FILES[$fileKey], 'private/chat_images');
                if ($image_url === false) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Image upload failed (file type not allowed or server rejected it).',
                        ],
                        'playSound' => 'error',
                    ]);
                    exit();
                }
            }
            if ($message === '' && !$image_url) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please type a message or attach an image.',
                    ],
                    'playSound' => 'error',
                ]);
                exit();
            }

            // If both are present, store as two messages (keeps compatibility with existing renderer)
            if ($message !== '') {
                chat_insert_message($order_id, [
                    'message' => $message,
                    'message_type' => 'text',
                ], ADMIN_DATA, 'admin');
            }

            if ($image_url) {
                chat_insert_message($order_id, [
                    'message' => $image_url,
                    'message_type' => 'image',
                ], ADMIN_DATA, 'admin');
            }

            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit_order('chat_update', $order_id);
            }

            echo json_encode(["resetForm" => true, "reFocus" => true]);
            exit();
        }
    }

public function admin_set_order_paid()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['order_id']);
            $order = db_get_row('orders', ['id' => $order_id]);
            $invoice = db_get_row('invoices', ['order_id' => $order_id]);
            if ($order != false) {
                $upd_order = db_update_row('orders', ['id' => $order_id], ['status' => 'PAID', 'paid_at' => date('Y-m-d H:i:s')]);
                if ($upd_order) {
                    log_admin_action(ADMIN_ID, 'Set order #' . $order_id . ' as paid');
                    $notification = [
                        'type' => 'order_ping',
                        'data' => json_encode([
                            'order_id' => base64_encode($order_id ?? ' '),
                        ]),
                        'is_discord' => true,
                    ];
                    // db_add_row('notifications', $notification);

                    process_cashback_points($order['client_id'], $invoice['total_price'] > 0 ? $invoice['total_price'] / 100 : $invoice['coins_used'], $order['id'], $invoice['coins_used']);

                    // Giveaway: grant 1 ticket for this paid invoice
                    if (!empty($invoice['id']) && function_exists('giveaway_grant_invoice_ticket')) {
                        giveaway_grant_invoice_ticket((int)$invoice['id']);
                    }

                    if (function_exists('lb_realtime_emit') && empty($order['booster_id'])) {
                        if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
                    }
                    // The order view (admin + client) only refreshes on order_status_update.
                    if (function_exists('lb_realtime_emit_order')) {
                        lb_realtime_emit_order('order_status_update', $order_id);
                    }

                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Order set as paid successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ));
                } else {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Something went wrong 😔',
                        ],
                        'playSound' => 'error',
                    ));
                }
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }



    /**
     * Added from ajax.php: Riot progress tracking sync + match history endpoints.
     */
    public function refresh_order_progress()
    {
        global $db;

        $silent = isset($_POST['silent']) && (string) $_POST['silent'] === '1';

        $isAdmin = $this->is_admin;
        $isClient = defined('CLIENT_ID') && CLIENT_ID > 0;
        $isBooster = defined('BOOSTER_ID') && BOOSTER_ID > 0;

        if (!$isAdmin && !$isClient && !$isBooster) {
            $response = ['ok' => false, 'message' => 'Unauthorized.'];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            $response = ['ok' => false, 'message' => 'Invalid order id.'];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order id.'];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            $response = ['ok' => false, 'message' => 'Order not found.'];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.'];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        // Ownership check
        if (!$isAdmin) {
            if ($isClient && (int) ($order['client_id'] ?? 0) !== CLIENT_ID) {
                echo json_encode(['ok' => false, 'message' => 'Access denied.']);
                return;
            }
            if ($isBooster && !$isClient) {
                $expectedBooster = (int) ($order['booster_id'] ?? 0);
                if ($expectedBooster !== BOOSTER_ID) {
                    echo json_encode(['ok' => false, 'message' => 'Access denied.']);
                    return;
                }
            }
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $order_acc = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
        $order_progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];

        if (($order['status'] ?? '') !== 'IN_PROGRESS') {
            $response = ['ok' => false, 'message' => 'Rank sync is only available for orders that are currently in progress.'];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'warning', 'title' => 'Sync Skipped', 'message' => 'Rank sync is only available for orders that are currently in progress.'];
            }
            echo json_encode($response);
            return;
        }

        $riotId = trim((string) ($order_acc['ign'] ?? ''));
        if ($riotId === '') {
            $response = ['ok' => false, 'message' => 'Riot ID is missing on this order. Tracking cannot be refreshed.'];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'warning', 'title' => 'Missing Riot ID', 'message' => 'Riot ID is missing on this order. Tracking cannot be refreshed.'];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        try {
            // $silent is the automatic sync that every order view fires on page load. Only an
            // explicit click on the refresh button gets the shorter throttle window.
            $fresh_progress = riot_sync_order_progress(
                $order_id, $order, $order_opts, $order_acc, $order_progress, $db,
                $silent ? RIOT_SYNC_MIN_INTERVAL_AUTO : RIOT_SYNC_MIN_INTERVAL_FORCED
            );
            // Riot may not return a rank (unranked/decayed account, API hiccup). Keep the
            // ordered start rank visible instead of dropping back to "Unranked".
            $fresh_progress = lb_order_progress_ensure_start_rank($order_id, $fresh_progress);

            $response = [
                'ok' => true,
                'message' => 'Current rank values and match results were refreshed successfully.',
                'orderProgress' => [
                    'start_tier' => $fresh_progress['start_tier'] ?? null,
                    'start_division' => $fresh_progress['start_division'] ?? null,
                    'start_lp' => $fresh_progress['start_lp'] ?? null,
                    'current_tier' => $fresh_progress['current_tier'] ?? null,
                    'current_division' => $fresh_progress['current_division'] ?? null,
                    'current_lp' => $fresh_progress['current_lp'] ?? null,
                    'wins' => $fresh_progress['wins'] ?? null,
                    'losses' => $fresh_progress['losses'] ?? null,
                    'last_match_id' => $fresh_progress['last_match_id'] ?? null,
                    'last_sync_at' => $fresh_progress['last_sync_at'] ?? null,
                    'puuid' => $fresh_progress['puuid'] ?? null,
                ],
            ];

            if (!$silent) {
                $response['sendToast'] = ['type' => 'success', 'title' => 'Progress Updated', 'message' => 'Current rank values and match results were refreshed successfully.'];
                $response['playSound'] = 'success';
            }

            echo json_encode($response);
            return;
        } catch (\Throwable $e) {
            $message = function_exists('riot_user_friendly_error_message')
                ? riot_user_friendly_error_message($e)
                : $e->getMessage();
            $response = ['ok' => false, 'message' => $message];
            if (!$silent) {
                $response['sendToast'] = ['type' => 'danger', 'title' => 'Refresh failed', 'message' => $message];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

    }



    public function admin_refresh_order_progress()
    {
        global $db;

        $silent = isset($_POST['silent']) && (string) $_POST['silent'] === '1';

        if (!$this->is_admin) {
            $response = [
                'ok' => false,
                'message' => 'Unauthorized.',
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized.',
                ];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            $response = [
                'ok' => false,
                'message' => 'Invalid order id.',
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid order id.',
                ];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            $response = [
                'ok' => false,
                'message' => 'Order not found.',
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Order not found.',
                ];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $order_acc = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
        $order_progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];

        if (($order['status'] ?? '') !== 'IN_PROGRESS') {
            $response = [
                'ok' => false,
                'message' => 'Rank sync is only available for orders that are currently in progress.',
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'warning',
                    'title' => 'Sync Skipped',
                    'message' => 'Rank sync is only available for orders that are currently in progress.',
                ];
            }
            echo json_encode($response);
            return;
        }

        $riotId = trim((string) ($order_acc['ign'] ?? ''));
        if ($riotId === '') {
            $response = [
                'ok' => false,
                'message' => 'Riot ID is missing on this order. Tracking cannot be refreshed.',
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'warning',
                    'title' => 'Missing Riot ID',
                    'message' => 'Riot ID is missing on this order. Tracking cannot be refreshed.',
                ];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

        try {
            // $silent is the automatic sync that every order view fires on page load. Only an
            // explicit click on the refresh button gets the shorter throttle window.
            $fresh_progress = riot_sync_order_progress(
                $order_id, $order, $order_opts, $order_acc, $order_progress, $db,
                $silent ? RIOT_SYNC_MIN_INTERVAL_AUTO : RIOT_SYNC_MIN_INTERVAL_FORCED
            );
            // Riot may not return a rank (unranked/decayed account, API hiccup). Keep the
            // ordered start rank visible instead of dropping back to "Unranked".
            $fresh_progress = lb_order_progress_ensure_start_rank($order_id, $fresh_progress);

            $response = [
                'ok' => true,
                'message' => 'Current rank values and match results were refreshed successfully.',
                'orderProgress' => [
                    'start_tier' => $fresh_progress['start_tier'] ?? null,
                    'start_division' => $fresh_progress['start_division'] ?? null,
                    'start_lp' => $fresh_progress['start_lp'] ?? null,
                    'current_tier' => $fresh_progress['current_tier'] ?? null,
                    'current_division' => $fresh_progress['current_division'] ?? null,
                    'current_lp' => $fresh_progress['current_lp'] ?? null,
                    'wins' => $fresh_progress['wins'] ?? null,
                    'losses' => $fresh_progress['losses'] ?? null,
                    'last_match_id' => $fresh_progress['last_match_id'] ?? null,
                    'last_sync_at' => $fresh_progress['last_sync_at'] ?? null,
                    'puuid' => $fresh_progress['puuid'] ?? null,
                ],
            ];

            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'success',
                    'title' => 'Progress Updated',
                    'message' => 'Current rank values and match results were refreshed successfully.',
                ];
                $response['playSound'] = 'success';
            }

            echo json_encode($response);
            return;
        } catch (\Throwable $e) {
            $message = function_exists('riot_user_friendly_error_message')
                ? riot_user_friendly_error_message($e)
                : $e->getMessage();
            $response = [
                'ok' => false,
                'message' => $message,
            ];
            if (!$silent) {
                $response['sendToast'] = [
                    'type' => 'danger',
                    'title' => 'Refresh failed',
                    'message' => $message,
                ];
                $response['playSound'] = 'error';
            }
            echo json_encode($response);
            return;
        }

    }





    /**
     * Booster Area: monthly leaderboard across all non-banned boosters.
     * Scores are weighted by starting Elo and Duo / Play With Booster difficulty.
     */
    public function get_booster_leaderboard()
    {
        global $db;
        riot_ensure_order_matches_remake_columns($db);

        $month = trim((string)($_POST['month'] ?? date('Y-m')));
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) {
            $month = date('Y-m');
        }

        $start = $month . '-01 00:00:00';
        $end = date('Y-m-d H:i:s', strtotime($start . ' +1 month'));

        $minimumGames = 10;
        $minimumTopWinrate = 50.0;

        /*
         * Fixed reward system.
         *
         * Tier IDs:
         * 0 / fallback = Unranked
         * 1 = Iron
         * 2 = Bronze
         * 3 = Silver
         * 4 = Gold
         * 5 = Platinum
         * 6 = Emerald
         * 7 = Diamond
         * 8 = Master
         * 9 = Grandmaster
         * 10 = Challenger
         *
         * Play with booster = yes -> order_options.is_duo = 1
         * Play with booster = no  -> order_options.is_duo = 0
         */
        $isDuoSql = "(COALESCE(oo.is_duo, 0) = 1)";

        // Leaderboard record/score counts all assigned matches, including client-side Duo rows.
        // PUUID ownership filtering is only used by Champion Statistics, not by win/loss records.

        // Fixed win rewards. Unranked is under Gold but above Silver.
        $soloWinPointsSql = "CASE COALESCE(oo.start_tier, 0)
            WHEN 10 THEN 25
            WHEN 9 THEN 22
            WHEN 8 THEN 18
            WHEN 7 THEN 13
            WHEN 6 THEN 10
            WHEN 5 THEN 7
            WHEN 4 THEN 5
            WHEN 3 THEN 3
            WHEN 2 THEN 2
            WHEN 1 THEN 2
            ELSE 4
        END";

        $duoWinPointsSql = "CASE COALESCE(oo.start_tier, 0)
            WHEN 10 THEN 32
            WHEN 9 THEN 28
            WHEN 8 THEN 23
            WHEN 7 THEN 17
            WHEN 6 THEN 13
            WHEN 5 THEN 10
            WHEN 4 THEN 8
            WHEN 3 THEN 5
            WHEN 2 THEN 3
            WHEN 1 THEN 3
            ELSE 7
        END";

        // Fixed loss penalties. Low Elo losses hurt more. Solo losses hurt more than Duo losses.
        $soloLossPointsSql = "CASE COALESCE(oo.start_tier, 0)
            WHEN 10 THEN 8
            WHEN 9 THEN 9
            WHEN 8 THEN 10
            WHEN 7 THEN 12
            WHEN 6 THEN 13
            WHEN 5 THEN 14
            WHEN 4 THEN 15
            WHEN 3 THEN 18
            WHEN 2 THEN 20
            WHEN 1 THEN 22
            ELSE 16
        END";

        $duoLossPointsSql = "CASE COALESCE(oo.start_tier, 0)
            WHEN 10 THEN 6
            WHEN 9 THEN 7
            WHEN 8 THEN 8
            WHEN 7 THEN 10
            WHEN 6 THEN 11
            WHEN 5 THEN 12
            WHEN 4 THEN 13
            WHEN 3 THEN 15
            WHEN 2 THEN 17
            WHEN 1 THEN 19
            ELSE 14
        END";

        $winPointsSql = "(CASE WHEN $isDuoSql THEN ($duoWinPointsSql) ELSE ($soloWinPointsSql) END)";
        $lossPointsSql = "(CASE WHEN $isDuoSql THEN ($duoLossPointsSql) ELSE ($soloLossPointsSql) END)";

        $rows = $db->run(
            "SELECT
                b.id AS booster_id,
                b.username,
                b.icon,
                b.rank_id,

                COUNT(*) AS games,
                SUM(CASE WHEN om.won = 1 THEN 1 ELSE 0 END) AS wins,
                SUM(CASE WHEN om.won = 0 THEN 1 ELSE 0 END) AS losses,

                SUM(CASE WHEN $isDuoSql THEN 0 ELSE 1 END) AS solo_games,
                SUM(CASE WHEN $isDuoSql THEN 1 ELSE 0 END) AS duo_games,

                SUM(CASE WHEN NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS solo_wins,
                SUM(CASE WHEN $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS duo_wins,

                SUM(CASE WHEN NOT $isDuoSql AND om.won = 0 THEN 1 ELSE 0 END) AS solo_losses,
                SUM(CASE WHEN $isDuoSql AND om.won = 0 THEN 1 ELSE 0 END) AS duo_losses,

                SUM(CASE WHEN om.won = 1 THEN $winPointsSql ELSE 0 END) AS win_points,
                SUM(CASE WHEN om.won = 0 THEN $lossPointsSql ELSE 0 END) AS loss_penalty,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 0 THEN 1 ELSE 0 END) AS unranked_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 1 THEN 1 ELSE 0 END) AS iron_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 2 THEN 1 ELSE 0 END) AS bronze_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 3 THEN 1 ELSE 0 END) AS silver_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 4 THEN 1 ELSE 0 END) AS gold_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 5 THEN 1 ELSE 0 END) AS platinum_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 6 THEN 1 ELSE 0 END) AS emerald_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 7 THEN 1 ELSE 0 END) AS diamond_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) >= 8 THEN 1 ELSE 0 END) AS master_plus_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) >= 7 THEN 1 ELSE 0 END) AS diamond_plus_games,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) >= 8 AND NOT $isDuoSql THEN 1 ELSE 0 END) AS master_plus_solo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) >= 8 AND NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS master_plus_solo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 7 AND NOT $isDuoSql THEN 1 ELSE 0 END) AS diamond_solo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 7 AND NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS diamond_solo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 7 AND $isDuoSql THEN 1 ELSE 0 END) AS diamond_duo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 7 AND $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS diamond_duo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 6 AND NOT $isDuoSql THEN 1 ELSE 0 END) AS emerald_solo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 6 AND NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS emerald_solo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 6 AND $isDuoSql THEN 1 ELSE 0 END) AS emerald_duo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 6 AND $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS emerald_duo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 5 AND NOT $isDuoSql THEN 1 ELSE 0 END) AS platinum_solo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 5 AND NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS platinum_solo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 5 AND $isDuoSql THEN 1 ELSE 0 END) AS platinum_duo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) = 5 AND $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS platinum_duo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) IN (0,4) AND NOT $isDuoSql THEN 1 ELSE 0 END) AS gold_unranked_solo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) IN (0,4) AND NOT $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS gold_unranked_solo_wins,

                SUM(CASE WHEN COALESCE(oo.start_tier, 0) IN (0,4) AND $isDuoSql THEN 1 ELSE 0 END) AS gold_unranked_duo_games,
                SUM(CASE WHEN COALESCE(oo.start_tier, 0) IN (0,4) AND $isDuoSql AND om.won = 1 THEN 1 ELSE 0 END) AS gold_unranked_duo_wins

             FROM order_matches om FORCE INDEX (idx_order_matches_leaderboard_fast)
             JOIN orders o
               ON o.id = om.order_id
             LEFT JOIN order_options oo
               ON oo.order_id = o.id
             LEFT JOIN order_progress op
               ON op.order_id = o.id
             JOIN boosters b
               ON b.id = COALESCE(om.booster_id, o.booster_id)
             WHERE om.played_at >= ?
               AND om.played_at < ?
               AND COALESCE(om.is_hidden, 0) = 0
               AND COALESCE(om.is_remake, 0) = 0
               AND COALESCE(b.is_banned, 0) = 0
               AND COALESCE(b.is_egirl, 0) = 0
               AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
               AND COALESCE(oo.is_moderate_kda, 0) = 0
             GROUP BY b.id, b.username, b.icon, b.rank_id",
            $start,
            $end
        );

        $leaderboard = [];

        $tierWinrateReward = function ($wins, $games, $minGames, array $rewards) {
            $games = (int)$games;
            $wins = (int)$wins;

            if ($games < $minGames || $games <= 0) {
                return 0;
            }

            $wr = ($wins / $games) * 100;

            foreach ($rewards as $threshold => $points) {
                if ($wr >= $threshold) {
                    return $points;
                }
            }

            return 0;
        };

        foreach ((is_array($rows) ? $rows : []) as $row) {
            $games = (int)($row['games'] ?? 0);
            $wins = (int)($row['wins'] ?? 0);
            $losses = (int)($row['losses'] ?? 0);
            $winrate = $games > 0 ? round(($wins / $games) * 100, 2) : 0.0;

            $soloGames = (int)($row['solo_games'] ?? 0);
            $duoGames = (int)($row['duo_games'] ?? 0);
            $soloWins = (int)($row['solo_wins'] ?? 0);
            $duoWins = (int)($row['duo_wins'] ?? 0);
            $soloLosses = (int)($row['solo_losses'] ?? 0);
            $duoLosses = (int)($row['duo_losses'] ?? 0);

            $winPoints = (float)($row['win_points'] ?? 0);
            $lossPenalty = (float)($row['loss_penalty'] ?? 0);

            $winrateRewards = 0;

            // Winrate rewards. These do not stack by game amount; they are category achievements.
            $winrateRewards += $tierWinrateReward(
                $row['master_plus_solo_wins'] ?? 0,
                $row['master_plus_solo_games'] ?? 0,
                10,
                [95 => 100, 90 => 80, 85 => 60, 80 => 40, 75 => 20]
            );

            $winrateRewards += $tierWinrateReward(
                $row['diamond_solo_wins'] ?? 0,
                $row['diamond_solo_games'] ?? 0,
                10,
                [95 => 50, 90 => 40, 85 => 30, 80 => 20, 75 => 10]
            );

            $winrateRewards += $tierWinrateReward(
                $row['diamond_duo_wins'] ?? 0,
                $row['diamond_duo_games'] ?? 0,
                5,
                [95 => 100, 90 => 80, 85 => 60, 80 => 40, 75 => 20]
            );

            $winrateRewards += $tierWinrateReward(
                $row['emerald_solo_wins'] ?? 0,
                $row['emerald_solo_games'] ?? 0,
                20,
                [95 => 25, 90 => 20, 85 => 15, 80 => 10, 75 => 5]
            );

            $winrateRewards += $tierWinrateReward(
                $row['emerald_duo_wins'] ?? 0,
                $row['emerald_duo_games'] ?? 0,
                10,
                [95 => 50, 90 => 40, 85 => 30, 80 => 20, 75 => 10]
            );

            $winrateRewards += $tierWinrateReward(
                $row['platinum_solo_wins'] ?? 0,
                $row['platinum_solo_games'] ?? 0,
                20,
                [95 => 14, 90 => 12, 85 => 9, 80 => 7, 75 => 5]
            );

            $winrateRewards += $tierWinrateReward(
                $row['platinum_duo_wins'] ?? 0,
                $row['platinum_duo_games'] ?? 0,
                10,
                [95 => 35, 90 => 25, 85 => 20, 80 => 15, 75 => 7]
            );

            $winrateRewards += $tierWinrateReward(
                $row['gold_unranked_solo_wins'] ?? 0,
                $row['gold_unranked_solo_games'] ?? 0,
                40,
                [95 => 12, 90 => 10, 85 => 7, 80 => 5, 75 => 3]
            );

            $winrateRewards += $tierWinrateReward(
                $row['gold_unranked_duo_wins'] ?? 0,
                $row['gold_unranked_duo_games'] ?? 0,
                20,
                [95 => 24, 90 => 20, 85 => 14, 80 => 10, 75 => 6]
            );

            // Small activity bonus. It should never beat quality.
            $activityBonus = 0;
            if ($games >= 150) {
                $activityBonus = 40;
            } elseif ($games >= 100) {
                $activityBonus = 25;
            } elseif ($games >= 50) {
                $activityBonus = 10;
            }

            // High Elo volume bonus.
            $diamondPlusGames = (int)($row['diamond_plus_games'] ?? 0);
            $masterPlusGames = (int)($row['master_plus_games'] ?? 0);

            $highEloBonus = 0;
            if ($diamondPlusGames >= 40) {
                $highEloBonus += 50;
            } elseif ($diamondPlusGames >= 20) {
                $highEloBonus += 20;
            }

            if ($masterPlusGames >= 15) {
                $highEloBonus += 60;
            }

            // Duo ratio bonus. No hard penalty because boosters do not fully control order supply.
            $duoRatio = $games > 0 ? ($duoGames / $games) * 100 : 0;
            $duoRatioBonus = 0;
            if ($duoRatio >= 40) {
                $duoRatioBonus = 25;
            } elseif ($duoRatio >= 20) {
                $duoRatioBonus = 10;
            }

            $rawScore = $winPoints - $lossPenalty + $winrateRewards + $activityBonus + $highEloBonus + $duoRatioBonus;
            $score = max(0, $rawScore);

            // Hard rule: below 50% total winrate = 0 points.
            // Booster stays visible, but cannot rank with a positive score.
            if ($winrate < $minimumTopWinrate) {
                $score = 0;
            }

            // Quality dampening:
            // 50-54.99% winrate should not be able to dominate by volume only.
            // The score becomes fully active only from 60%+ winrate.
            if ($winrate >= 50 && $winrate < 60) {
                $score *= max(0, ($winrate - 50) / 10);
            }

            $qualified = $games >= $minimumGames && $winrate >= $minimumTopWinrate;

            $leaderboard[] = [
                'booster_id' => (int)$row['booster_id'],
                'username' => (string)($row['username'] ?? 'Booster'),
                'icon' => (string)($row['icon'] ?? ''),
                'rank_id' => (int)($row['rank_id'] ?? 0),

                'games' => $games,
                'wins' => $wins,
                'losses' => $losses,
                'solo_games' => $soloGames,
                'duo_games' => $duoGames,
                'solo_wins' => $soloWins,
                'solo_losses' => $soloLosses,
                'duo_wins' => $duoWins,
                'duo_losses' => $duoLosses,
                'winrate' => $winrate,

                'win_points' => round($winPoints, 2),
                'loss_penalty' => round($lossPenalty, 2),
                'winrate_rewards' => round($winrateRewards, 2),
                'activity_bonus' => round($activityBonus, 2),
                'high_elo_bonus' => round($highEloBonus, 2),
                'duo_ratio_bonus' => round($duoRatioBonus, 2),
                'duo_ratio' => round($duoRatio, 2),
                'raw_score' => round($rawScore, 2),
                'score' => round($score, 2),

                // Kept for older frontend compatibility.
                'weighted_games' => $games,
                'weighted_wins' => round($winPoints, 2),
                'weighted_losses' => round($lossPenalty, 2),
                'negative_winrate_penalty' => $winrate < $minimumTopWinrate ? round(max(0, $rawScore), 2) : 0,

                'qualified' => $qualified,
            ];
        }

        usort($leaderboard, function ($a, $b) {
            if ($a['qualified'] !== $b['qualified']) {
                return $a['qualified'] ? -1 : 1;
            }

            if ($a['score'] == $b['score']) {
                if ($a['winrate'] == $b['winrate']) {
                    return $b['games'] <=> $a['games'];
                }
                return $b['winrate'] <=> $a['winrate'];
            }

            return $b['score'] <=> $a['score'];
        });

        foreach ($leaderboard as $i => &$row) {
            $row['position'] = $i + 1;
            $row['is_top_5'] = $row['qualified'] && $i < 5;
            $row['has_monthly_bonus'] = false;
            $row['monthly_bonus_percent'] = 0;
            $row['monthly_bonus_position'] = null;
            $row['monthly_bonus_title'] = null;
        }
        unset($row);

        $monthlyBonusMap = [];
        try {
            $bonusRows = $db->run(
                "SELECT booster_id, position, bonus_percent, title
                 FROM booster_monthly_bonus_awards
                 WHERE award_month COLLATE utf8mb4_unicode_ci = ? COLLATE utf8mb4_unicode_ci
                 ORDER BY position ASC",
                $month
            ) ?: [];

            foreach ($bonusRows as $bonusRow) {
                $monthlyBonusMap[(int)($bonusRow['booster_id'] ?? 0)] = $bonusRow;
            }
        } catch (\Throwable $e) {
            $monthlyBonusMap = [];
        }

        foreach ($leaderboard as &$row) {
            $award = $monthlyBonusMap[(int)$row['booster_id']] ?? null;
            if (!empty($award)) {
                $row['has_monthly_bonus'] = true;
                $row['monthly_bonus_percent'] = (float)($award['bonus_percent'] ?? 0);
                $row['monthly_bonus_position'] = (int)($award['position'] ?? 0);
                $row['monthly_bonus_title'] = (string)($award['title'] ?? 'Top Booster');
            }
        }
        unset($row);

        echo json_encode([
            'ok' => true,
            'month' => $month,
            'minimum_games' => $minimumGames,
            'minimum_top_winrate' => $minimumTopWinrate,
            'scoring_type' => 'fixed_rewards',
            'below_50_winrate_points' => 0,
            'rows' => $leaderboard,
        ]);
    }
    public function get_order_matches()
    {
        global $db;

        // Works for admins, clients, and boosters. Each can only fetch their own orders.
        $isAdmin = $this->is_admin;
        $isClient = defined('CLIENT_ID') && CLIENT_ID > 0;
        $isBooster = defined('BOOSTER_ID') && BOOSTER_ID > 0;

        if (!$isAdmin && !$isClient && !$isBooster) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = (int) ($_POST['order_id'] ?? 0);
        $page = max(1, (int) ($_POST['page'] ?? 1));
        $per_page = max(1, min(50, (int) ($_POST['per_page'] ?? 20)));

        if ($order_id <= 0) {
            echo json_encode(['ok' => false, 'message' => 'Invalid order id.']);
            return;
        }

        // Ownership check for clients
        if ($isClient && !$isAdmin) {
            $order = db_get_row('orders', ['id' => $order_id, 'client_id' => CLIENT_ID], 1);
            if (empty($order)) {
                echo json_encode(['ok' => false, 'message' => 'Order not found.']);
                return;
            }
        }

        // Ownership check for boosters
        if ($isBooster && !$isAdmin) {
            $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
            if (empty($order)) {
                echo json_encode(['ok' => false, 'message' => 'Order not found.']);
                return;
            }
        }

        $result = get_order_matches($order_id, $page, $per_page, $db);

        // Normalize booster icon fields for match-history frontends.
        // Some templates read booster_icon, some read avatar/icon, and some expect a nested booster object.
        if (isset($result['rows']) && is_array($result['rows'])) {
            foreach ($result['rows'] as &$matchRow) {
                $boosterIcon = trim((string)($matchRow['booster_icon'] ?? $matchRow['booster_avatar'] ?? $matchRow['avatar'] ?? $matchRow['icon'] ?? ''));
                $boosterName = trim((string)($matchRow['booster_name'] ?? $matchRow['booster_username'] ?? 'Booster'));
                $boosterId = isset($matchRow['booster_id']) ? (int)$matchRow['booster_id'] : null;

                $matchRow['booster_icon'] = $boosterIcon;
                $matchRow['booster_avatar'] = $boosterIcon;
                $matchRow['booster_icon_url'] = $boosterIcon;
                $matchRow['booster_image'] = $boosterIcon;
                $matchRow['booster_img'] = $boosterIcon;

                // Keep generic icon/avatar aliases too, but do not change champion data.
                $matchRow['avatar'] = $boosterIcon;
                $matchRow['icon'] = $boosterIcon;

                $matchRow['booster'] = [
                    'id' => $boosterId,
                    'name' => $boosterName,
                    'username' => $boosterName,
                    'icon' => $boosterIcon,
                    'avatar' => $boosterIcon,
                    'image' => $boosterIcon,
                ];
            }
            unset($matchRow);
        }

        echo json_encode(['ok' => true, 'matches' => $result]);
    }



    /**
     * Public endpoint: Gibt die Match-History eines Boosters zurück.
     * Wird vom Performance-Tab auf dem öffentlichen Booster-Profil genutzt.
     * Erfordert KEINEN Login.
     */
    public function get_booster_performance()
    {
        global $db;
        riot_ensure_order_matches_remake_columns($db);

        $booster_id = (int) ($_POST['booster_id'] ?? 0);
        $page       = max(1, (int) ($_POST['page']     ?? 1));
        $allRows    = (int) ($_POST['all'] ?? 0) === 1;
        $perLimit   = $allRows ? 5000 : 50;
        $per_page   = max(1, min($perLimit, (int) ($_POST['per_page'] ?? 20)));
        $mode       = in_array($_POST['mode'] ?? '', ['solo','duo','all']) ? $_POST['mode'] : 'solo';
        $queue      = trim((string) ($_POST['queue'] ?? 'all'));
        $allowedQueues = ['all','soloq','solo/duo','solo_duo','ranked_solo_duo','flex','flexq','flex_queue','ranked_flex','normal','aram','arena','clash','bots','tft','featured','custom','tutorial','summoners_rift'];
        $queue = in_array($queue, $allowedQueues, true) ? $queue : 'all';
        $scope      = trim((string) ($_POST['scope'] ?? ''));
        $boosterOwnedOnly = (int) ($_POST['booster_owned_only'] ?? 0) === 1;
        $adminDashboardAllGames = ($scope === 'booster_order_dashboard' && defined('ADMIN_ID') && ADMIN_ID);

        // Admin booster dashboard loads a large audit list by default, but must still
        // respect the selected Solo/Duo/All filter from the UI.
        if ($adminDashboardAllGames) {
            $allRows = true;
            $per_page = max(1, min(5000, (int) ($_POST['per_page'] ?? 5000)));
            $mode = in_array($_POST['mode'] ?? '', ['solo','duo','all'], true) ? $_POST['mode'] : 'all';
            $queue = trim((string) ($_POST['queue'] ?? 'all'));
            $queue = in_array($queue, $allowedQueues, true) ? $queue : 'all';
        }

        if ($booster_id <= 0) {
            echo json_encode(['ok' => false, 'message' => 'Invalid booster_id.']);
            return;
        }

        $boosterRow = db_get_row('boosters', ['id' => $booster_id]);
        if (empty($boosterRow)) {
            echo json_encode(['ok' => false, 'message' => 'Booster not found.']);
            return;
        }

        $offset = ($page - 1) * $per_page;

        // Keep the large/all response for the booster dashboard/admin only.
        if ($allRows && !$adminDashboardAllGames && !(defined('BOOSTER_ID') && (int) BOOSTER_ID === $booster_id) && !(defined('ADMIN_ID') && ADMIN_ID)) {
            $per_page = min($per_page, 50);
            $offset = ($page - 1) * $per_page;
        }

        // Mode filter:
        // - solo: exclude both native Duo (oo.is_duo=1) and paid Play With Booster/Duo add-ons
        // - duo: include native Duo and paid Play With Booster/Duo add-ons
        // - all: no filter
        $playWithBoosterAddonSql = "EXISTS (
            SELECT 1
              FROM invoices ai
             WHERE ai.order_id = o.id
               AND ai.order_type = 'addon'
               AND ai.status = 'PAID'
               AND (
                    LOWER(COALESCE(ai.note, '')) LIKE '%duo%'
                 OR LOWER(COALESCE(ai.note, '')) LIKE '%play with booster%'
                 OR LOWER(COALESCE(ai.note, '')) LIKE '%play_with_booster%'
               )
        )";
        $playWithBoosterSql = "(COALESCE(oo.is_duo, 0) = 1 OR $playWithBoosterAddonSql)";

        // Optional booster-owned scope for public booster profile recent games:
        // - Solo rows count normally.
        // - Duo rows count only when the stored match PUUID is not the client's PUUID
        //   (or exactly matches the saved booster duo PUUID). This keeps client-side Duo
        //   rows out of Recent Games / Champion-style displays while preserving fallback
        //   for older booster duo accounts.
        $boosterPlayedDuoSql = "(
            $playWithBoosterSql
            AND COALESCE(om.puuid, '') <> ''
            AND (
                   (COALESCE(op.booster_puuid, '') <> '' AND om.puuid = op.booster_puuid)
                OR (COALESCE(op.puuid, '') <> '' AND om.puuid <> op.puuid)
            )
        )";

        if ($boosterOwnedOnly) {
            if ($mode === 'solo') {
                $modeFilter = "AND NOT $playWithBoosterSql";
            } elseif ($mode === 'duo') {
                $modeFilter = "AND $boosterPlayedDuoSql";
            } else {
                $modeFilter = "AND (NOT $playWithBoosterSql OR $boosterPlayedDuoSql)";
            }
        } else {
            // Record/winrate views count all assigned matches, including client-side Duo rows.
            if ($mode === 'solo') {
                $modeFilter = "AND NOT $playWithBoosterSql";
            } elseif ($mode === 'duo') {
                $modeFilter = "AND $playWithBoosterSql";
            } else {
                $modeFilter = "";
            }
        }

        // Queue filter supports Riot queue categories. soloq is kept as a legacy alias for solo/duo.
        $queueFilter = '';
        $queueAlias = function_exists('util_normalize_lol_queue_type') ? util_normalize_lol_queue_type($queue) : (($queue === 'soloq') ? 'solo/duo' : $queue);
        if ($queueAlias !== 'all') {
            $queueIds = function_exists('util_lol_queue_type_ids') ? util_lol_queue_type_ids($queueAlias) : [];
            if (empty($queueIds) && $queueAlias === 'solo/duo') {
                $queueIds = [420];
            }
            $queueIds = array_values(array_unique(array_map('intval', $queueIds)));
            if (!empty($queueIds)) {
                $queueFilter = 'AND om.queue_id IN (' . implode(',', $queueIds) . ')';
            }
        }

        $totalRes = $db->run(
            "SELECT COUNT(*) AS cnt
               FROM order_matches om
               JOIN orders o ON o.id = om.order_id
               LEFT JOIN order_options oo ON oo.order_id = o.id
               LEFT JOIN order_progress op ON op.order_id = o.id
              WHERE COALESCE(om.booster_id, o.booster_id) = ?
                AND COALESCE(om.is_hidden, 0) = 0
                $modeFilter
                $queueFilter
                AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
                AND COALESCE(oo.is_moderate_kda, 0) = 0",
            $booster_id
        );
        $total = (int) ($totalRes[0]['cnt'] ?? 0);
        $pages = $total > 0 ? (int) ceil($total / $per_page) : 0;

        if ($total === 0) {
            echo json_encode([
                'ok'      => true,
                'matches' => ['rows' => [], 'total' => 0, 'page' => $page, 'per_page' => $per_page, 'pages' => 0],
            ]);
            return;
        }

        $rows = $db->run(
            "SELECT om.id,
                    om.order_id,
                    om.match_id,
                    om.champion,
                    om.position,
                    om.kills,
                    om.deaths,
                    om.assists,
                    om.won,
                    om.duration,
                    om.queue_id,
                    om.played_at,
                    COALESCE(om.rank_snapshot, NULL) AS rank_snapshot,
                    COALESCE(om.is_remake, 0) AS is_remake,
                    CASE WHEN $playWithBoosterSql THEN 1 ELSE 0 END AS is_duo,
                    CASE
                        WHEN COALESCE(op.booster_puuid, '') <> ''
                             AND COALESCE(om.puuid, '') <> ''
                             AND om.puuid = op.booster_puuid
                            THEN 'booster'
                        ELSE 'client'
                    END AS stat_subject,
                    CASE
                        WHEN COALESCE(op.booster_puuid, '') <> '' OR COALESCE(op.booster_ign, '') <> '' THEN 1
                        ELSE 0
                    END AS has_duo_account
               FROM order_matches om
               JOIN orders o ON o.id = om.order_id
               LEFT JOIN order_options oo ON oo.order_id = o.id
               LEFT JOIN order_progress op ON op.order_id = o.id
              WHERE COALESCE(om.booster_id, o.booster_id) = ?
                AND COALESCE(om.is_hidden, 0) = 0
                $modeFilter
                $queueFilter
                AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
                AND COALESCE(oo.is_moderate_kda, 0) = 0
              ORDER BY om.played_at DESC, om.id DESC
              LIMIT ? OFFSET ?",
            $booster_id,
            $per_page,
            $offset
        );

        if (is_array($rows)) {
            foreach ($rows as &$row) {
                $duration         = (int) ($row['duration']  ?? 0);
                $storedRemake     = (int) ($row['is_remake'] ?? 0) === 1;
                $durationFallback = ($duration > 0 && $duration < 300);
                $row['is_remake'] = ($storedRemake || $durationFallback) ? 1 : 0;
                $row['result']    = ((int) $row['is_remake'] === 1)
                    ? 'remake'
                    : (((int) ($row['won'] ?? 0) === 1) ? 'win' : 'loss');
                // Riot stores Wukong internally as "MonkeyKing" — normalize for display
                if (($row['champion'] ?? '') === 'MonkeyKing') $row['champion'] = 'Wukong';
            }
            unset($row);
        }

        echo json_encode([
            'ok'      => true,
            'matches' => [
                'rows'     => is_array($rows) ? $rows : [],
                'total'    => $total,
                'page'     => $page,
                'per_page' => $per_page,
                'pages'    => $pages,
            ],
        ]);
    }



    /**
     * Public endpoint: Aggregierte Champion-Stats + Rank-Breakdown für den Performance-Tab.
     */
    public function get_booster_stats()
    {
        global $db;

        $booster_id = (int) ($_POST['booster_id'] ?? 0);
        $year       = (int) ($_POST['year'] ?? 0);
        $mode       = in_array($_POST['mode'] ?? '', ['solo','duo','all']) ? $_POST['mode'] : 'all';
        // champ_mode: always solo unless explicitly set (champions only tracked on booster's own account)
        $champMode  = in_array($_POST['champ_mode'] ?? '', ['solo','duo','all']) ? $_POST['champ_mode'] : 'solo';

        if ($booster_id <= 0) {
            echo json_encode(['ok' => false, 'message' => 'Invalid booster_id.']);
            return;
        }

        $boosterRow = db_get_row('boosters', ['id' => $booster_id]);
        if (empty($boosterRow)) {
            echo json_encode(['ok' => false, 'message' => 'Booster not found.']);
            return;
        }

        $rankNames = [
            0=>'Unranked',1=>'Iron',2=>'Bronze',3=>'Silver',4=>'Gold',5=>'Platinum',
            6=>'Emerald',7=>'Diamond',8=>'Master',9=>'Grandmaster',10=>'Challenger'
        ];

        // Rank filter (for competitive progression). Play With Booster add-ons count as Duo.
        $playWithBoosterAddonSql = "EXISTS (
            SELECT 1
              FROM invoices ai
             WHERE ai.order_id = o.id
               AND ai.order_type = 'addon'
               AND ai.status = 'PAID'
               AND (
                    LOWER(COALESCE(ai.note, '')) LIKE '%duo%'
                 OR LOWER(COALESCE(ai.note, '')) LIKE '%play with booster%'
                 OR LOWER(COALESCE(ai.note, '')) LIKE '%play_with_booster%'
               )
        )";
        $playWithBoosterSql = "(COALESCE(oo.is_duo, 0) = 1 OR $playWithBoosterAddonSql)";

        // Champion filter:
        // - Solo orders count normally because the booster played those games.
        // - Duo/Play-with-Booster orders only count when the stored match PUUID belongs
        //   to the booster's duo account, not to the client's Riot account.
        //   Client account:        om.puuid == order_progress.puuid
        //   Booster duo account:   om.puuid == order_progress.booster_puuid
        //   Fallback for older rows: if client puuid is known and om.puuid differs,
        //   treat the row as booster stats. If both PUUIDs are missing, exclude it
        //   to avoid showing client stats as champion stats.
        $boosterPlayedDuoSql = "(
            $playWithBoosterSql
            AND COALESCE(om.puuid, '') <> ''
            AND (
                   (COALESCE(op.booster_puuid, '') <> '' AND om.puuid = op.booster_puuid)
                OR (COALESCE(op.puuid, '') <> '' AND om.puuid <> op.puuid)
            )
        )";

        // Rank breakdown / win-loss totals count all assigned matches.
        // Champion stats below use $champFilter and exclude client-side Duo rows.
        if ($mode === 'solo') {
            $modeFilter = "AND NOT $playWithBoosterSql";
        } elseif ($mode === 'duo') {
            $modeFilter = "AND $playWithBoosterSql";
        } else {
            $modeFilter = "";
        }

        if ($champMode === 'solo') {
            $champFilter = "AND NOT $playWithBoosterSql";
        } elseif ($champMode === 'duo') {
            $champFilter = "AND $boosterPlayedDuoSql";
        } else {
            $champFilter = "AND (NOT $playWithBoosterSql OR $boosterPlayedDuoSql)";
        }

        $yearSql = $year > 0 ? "AND YEAR(om.played_at) = " . $year : "";

        // ── Available years (always across all modes so filter doesn't disappear) ──
        $yearsRes = $db->run(
            "SELECT DISTINCT YEAR(om.played_at) AS y
               FROM order_matches om
               JOIN orders o ON o.id = om.order_id
               LEFT JOIN order_options oo ON oo.order_id = o.id
               LEFT JOIN order_progress op ON op.order_id = o.id
              WHERE COALESCE(om.booster_id, o.booster_id) = ?
                AND COALESCE(om.is_hidden, 0) = 0
                AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
                AND COALESCE(oo.is_moderate_kda, 0) = 0
              ORDER BY y DESC",
            $booster_id
        );
        $years = array_values(array_filter(array_column(is_array($yearsRes) ? $yearsRes : [], 'y')));

        // ── Champion stats — always solo (booster's own games) ─
        $champRows = $db->run(
            "SELECT
                om.champion,
                COUNT(*)                                              AS games,
                SUM(CASE WHEN om.won = 1 THEN 1 ELSE 0 END)          AS wins,
                SUM(CASE WHEN om.won = 0 THEN 1 ELSE 0 END)          AS losses,
                ROUND(AVG(om.kills),   2)                             AS avg_kills,
                ROUND(AVG(om.deaths),  2)                             AS avg_deaths,
                ROUND(AVG(om.assists), 2)                             AS avg_assists
             FROM order_matches om
             JOIN orders o ON o.id = om.order_id
             LEFT JOIN order_options oo ON oo.order_id = o.id
             LEFT JOIN order_progress op ON op.order_id = o.id
             WHERE COALESCE(om.booster_id, o.booster_id) = ?
               AND COALESCE(om.is_hidden, 0) = 0
               $champFilter
               AND om.champion IS NOT NULL
               AND COALESCE(om.is_remake, 0) = 0
               AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
               AND COALESCE(oo.is_moderate_kda, 0) = 0
               $yearSql
             GROUP BY om.champion
             ORDER BY games DESC, wins DESC
             LIMIT 15",
            $booster_id
        );

        $champions = [];
        foreach ((is_array($champRows) ? $champRows : []) as $r) {
            $k    = (float)($r['avg_kills']   ?? 0);
            $d    = (float)($r['avg_deaths']  ?? 0);
            $a    = (float)($r['avg_assists'] ?? 0);
            $kda  = $d > 0 ? round(($k + $a) / $d, 2) : ($k + $a > 0 ? 99.0 : 0.0);
            $games = (int)($r['games'] ?? 0);
            $wins  = (int)($r['wins']  ?? 0);
            $wr    = $games > 0 ? round(($wins / $games) * 100, 2) : 0;
            // Riot stores Wukong internally as "MonkeyKing" — normalize for display
            $champName = $r['champion'];
            if ($champName === 'MonkeyKing') $champName = 'Wukong';
            $champions[] = [
                'champion'    => $champName,
                'games'       => $games,
                'wins'        => $wins,
                'losses'      => (int)($r['losses'] ?? 0),
                'avg_kills'   => $k,
                'avg_deaths'  => $d,
                'avg_assists' => $a,
                'kda'         => $kda,
                'winrate'     => $wr,
            ];
        }

        // ── Rank breakdown ───────────────────────────────────────
        // Priority: rank_snapshot (actual elo at match time) → oo.start_tier (order start rank, fallback for old matches) → 0
        $tierMap = "CASE
            WHEN om.rank_snapshot IS NOT NULL AND om.rank_snapshot != '' AND om.rank_snapshot NOT LIKE 'UNRANKED%' THEN
                CASE
                    WHEN om.rank_snapshot LIKE 'IRON%'        THEN 1
                    WHEN om.rank_snapshot LIKE 'BRONZE%'      THEN 2
                    WHEN om.rank_snapshot LIKE 'SILVER%'      THEN 3
                    WHEN om.rank_snapshot LIKE 'GOLD%'        THEN 4
                    WHEN om.rank_snapshot LIKE 'PLATINUM%'    THEN 5
                    WHEN om.rank_snapshot LIKE 'EMERALD%'     THEN 6
                    WHEN om.rank_snapshot LIKE 'DIAMOND%'     THEN 7
                    WHEN om.rank_snapshot LIKE 'MASTER%'      THEN 8
                    WHEN om.rank_snapshot LIKE 'GRANDMASTER%' THEN 9
                    WHEN om.rank_snapshot LIKE 'CHALLENGER%'  THEN 10
                    ELSE COALESCE(oo.start_tier, 0)
                END
            ELSE COALESCE(oo.start_tier, 0)
        END";

        $rankRows = $db->run(
            "SELECT
                ($tierMap)                                                           AS tier,
                SUM(CASE WHEN om.won = 1 AND COALESCE(om.is_remake,0)=0 THEN 1 ELSE 0 END) AS wins,
                SUM(CASE WHEN om.won = 0 AND COALESCE(om.is_remake,0)=0 THEN 1 ELSE 0 END) AS losses
             FROM order_matches om
             JOIN orders o ON o.id = om.order_id
             LEFT JOIN order_options oo ON oo.order_id = o.id
             LEFT JOIN order_progress op ON op.order_id = o.id
             WHERE COALESCE(om.booster_id, o.booster_id) = ?
               AND COALESCE(om.is_hidden, 0) = 0
               $modeFilter
               AND COALESCE(om.is_remake, 0) = 0
               AND COALESCE(oo.is_undercover_winrate, 0) = 0
               AND COALESCE(o.form_id, 0) NOT IN (15, 16, 25)
               AND COALESCE(om.queue_id, 0) <> 400
               AND COALESCE(oo.is_moderate_kda, 0) = 0
               $yearSql
             GROUP BY tier
             ORDER BY tier DESC",
            $booster_id
        );

        $ranks = [];
        foreach ((is_array($rankRows) ? $rankRows : []) as $r) {
            $tier   = (int)($r['tier']   ?? 0);
            $wins   = (int)($r['wins']   ?? 0);
            $losses = (int)($r['losses'] ?? 0);
            $total  = $wins + $losses;
            if ($total === 0) continue;
            $wr = round(($wins / $total) * 100, 2);
            $ranks[] = [
                'tier'    => $tier,
                'name'    => $rankNames[$tier] ?? 'Unknown',
                'wins'    => $wins,
                'losses'  => $losses,
                'winrate' => $wr,
            ];
        }

        echo json_encode([
            'ok'        => true,
            'champions' => $champions,
            'ranks'     => $ranks,
            'years'     => $years,
        ]);
    }




    public function admin_backfill_order_matches()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode([
                'ok' => false,
                'message' => 'Unauthorized.',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode([
                'ok' => false,
                'message' => 'Invalid order id.',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order id.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode([
                'ok' => false,
                'message' => 'Order not found.',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $order_acc = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
        $order_progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];

        $riot_id = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string)($_POST['riot_id'] ?? ''))
            : trim((string)($_POST['riot_id'] ?? ''));
        $puuid = trim((string)($_POST['puuid'] ?? ''));
        $play_mode = strtolower(trim((string)($_POST['play_mode'] ?? '')));
        $start_at = trim((string)($_POST['start_at'] ?? $_POST['from'] ?? ''));
        $end_at = trim((string)($_POST['end_at'] ?? $_POST['to'] ?? ''));
        $queue_type = trim((string)($_POST['queue_type'] ?? ($order_opts['queue_type'] ?? 'solo/duo')));
        $queue_type = function_exists('util_normalize_lol_queue_type') ? util_normalize_lol_queue_type($queue_type) : $queue_type;
        $max_matches = (int)($_POST['max_matches'] ?? 100);
        $save_duo_account = isset($_POST['save_duo_account']) && (string)$_POST['save_duo_account'] === '1';
        $save_order_account = isset($_POST['save_order_account']) && (string)$_POST['save_order_account'] === '1';

        if ($puuid === '' && $riot_id !== '' && function_exists('lb_is_valid_riot_id') && !lb_is_valid_riot_id($riot_id)) {
            echo json_encode([
                'ok' => false,
                'message' => 'Invalid Riot ID format. Use: Name#TAG',
                'sendToast' => ['type' => 'warning', 'title' => 'Invalid Riot ID', 'message' => 'Use Riot ID format: Name#TAG'],
                'playSound' => 'error',
            ]);
            return;
        }

        try {
            $result = riot_backfill_order_matches($order_id, $order, $order_opts, $order_acc, $order_progress, $db, [
                'riot_id' => $riot_id,
                'puuid' => $puuid,
                'play_mode' => $play_mode,
                'start_at' => $start_at,
                'end_at' => $end_at,
                'queue_type' => $queue_type !== '' ? $queue_type : ($order_opts['queue_type'] ?? 'solo/duo'),
                'max_matches' => $max_matches,
                'save_duo_account' => $save_duo_account,
                'save_order_account' => $save_order_account,
            ]);

            if (function_exists('log_admin_action')) {
                log_admin_action(
                    ADMIN_ID,
                    'Backfilled order matches for order #' . $order_id . ' (' . (int)$result['matched_from_riot'] . ' Riot matches, +' . (int)$result['inserted_visible'] . ' visible)'
                );
            }

            $result['message'] = 'Backfill sync completed. ' . (int)$result['matched_from_riot'] . ' Riot matches checked, +' . (int)$result['inserted_visible'] . ' visible matches added.';
            $result['sendToast'] = [
                'type' => 'success',
                'title' => 'Backfill Completed',
                'message' => $result['message'],
            ];
            $result['playSound'] = 'success';
            echo json_encode($result);
            return;
        } catch (\Throwable $e) {
            $message = function_exists('riot_user_friendly_error_message')
                ? riot_user_friendly_error_message($e)
                : $e->getMessage();
            echo json_encode([
                'ok' => false,
                'message' => $message,
                'sendToast' => ['type' => 'danger', 'title' => 'Backfill failed', 'message' => $message],
                'playSound' => 'error',
            ]);
            return;
        }
    }

    public function admin_delete_order_match()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $match_id = (int) ($_POST['match_id'] ?? ($_POST['id'] ?? 0));
        if ($match_id <= 0) {
            echo json_encode(['ok' => false, 'message' => 'Invalid match id.']);
            return;
        }

        $match = db_get_row('order_matches', ['id' => $match_id], 1);
        if (empty($match)) {
            echo json_encode(['ok' => false, 'message' => 'Game not found.']);
            return;
        }

        riot_ensure_order_matches_remake_columns($db);

        $hidden = db_update_row('order_matches', ['id' => $match_id], [
            'is_hidden' => 1,
            'hidden_at' => date('Y-m-d H:i:s'),
            'hidden_by' => defined('ADMIN_ID') ? (int) ADMIN_ID : 0,
            'hidden_reason' => 'admin_hidden',
        ]);
        if ($hidden != false) {
            if (function_exists('log_admin_action')) {
                log_admin_action(ADMIN_ID, 'Hidden order match #' . $match_id . ' from order #' . (int)($match['order_id'] ?? 0));
            }
            echo json_encode([
                'ok' => true,
                'message' => 'Game hidden successfully.',
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Hidden',
                    'message' => 'Game hidden successfully.',
                ],
                'playSound' => 'success',
            ]);
            return;
        }

        echo json_encode([
            'ok' => false,
            'message' => 'Could not hide game.',
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Could not hide game.',
            ],
            'playSound' => 'error',
        ]);
    }




    public function admin_delete_order_matches()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $raw = $_POST['match_ids'] ?? ($_POST['ids'] ?? []);
        if (is_string($raw)) {
            $raw = preg_split('/[^0-9]+/', $raw, -1, PREG_SPLIT_NO_EMPTY);
        }
        if (!is_array($raw)) {
            $raw = [];
        }

        $ids = array_values(array_unique(array_filter(array_map('intval', $raw), static function ($id) {
            return $id > 0;
        })));

        if (empty($ids)) {
            echo json_encode(['ok' => false, 'message' => 'No games selected.']);
            return;
        }

        $placeholders = implode(',', array_fill(0, count($ids), '?'));

        riot_ensure_order_matches_remake_columns($db);

        $matches = $db->run("SELECT id, order_id FROM order_matches WHERE id IN ($placeholders) AND COALESCE(is_hidden, 0) = 0", ...$ids);
        if (empty($matches) || !is_array($matches)) {
            echo json_encode(['ok' => false, 'message' => 'Selected games were not found.']);
            return;
        }

        $deleteIds = array_values(array_unique(array_map('intval', array_column($matches, 'id'))));
        $hiddenCount = 0;

        foreach ($deleteIds as $deleteId) {
            $hidden = db_update_row('order_matches', ['id' => $deleteId], [
                'is_hidden' => 1,
                'hidden_at' => date('Y-m-d H:i:s'),
                'hidden_by' => defined('ADMIN_ID') ? (int) ADMIN_ID : 0,
                'hidden_reason' => 'admin_hidden_bulk',
            ]);
            if ($hidden != false) {
                $hiddenCount++;
            }
        }

        if ($hiddenCount > 0) {
            if (function_exists('log_admin_action')) {
                $orderIds = array_values(array_unique(array_map('intval', array_column($matches, 'order_id'))));
                log_admin_action(ADMIN_ID, 'Hidden ' . $hiddenCount . ' order matches #' . implode(',', $deleteIds) . ' from orders #' . implode(',', $orderIds));
            }
            echo json_encode([
                'ok' => true,
                'deleted' => $hiddenCount,
                'hidden' => $hiddenCount,
                'message' => $hiddenCount . ' game(s) hidden successfully.',
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Hidden',
                    'message' => $hiddenCount . ' game(s) hidden successfully.',
                ],
                'playSound' => 'success',
            ]);
            return;
        }

        echo json_encode([
            'ok' => false,
            'message' => 'Could not hide selected games.',
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Could not hide selected games.',
            ],
            'playSound' => 'error',
        ]);
    }



    public function admin_set_order_unpaid()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['order_id']);
            $order = db_get_row('orders', ['id' => $order_id]);
            $invoice = db_get_row('invoices', ['order_id' => $order_id]);
            if ($order != false) {
                $upd_order = db_update_row('orders', ['id' => $order_id], ['status' => 'UNPAID', 'paid_at' => null]);
                if ($upd_order) {
                    log_admin_action(ADMIN_ID, 'Set order #' . $order_id . ' as unpaid');
                    process_cashback_return($order['client_id'], $invoice['total_price'] > 0 ? $invoice['total_price'] / 100 : $invoice['coins_used'], $order['id'], $invoice['coins_used']);

                    // Giveaway: revoke ticket for this invoice
                    if (!empty($invoice['id']) && function_exists('giveaway_revoke_invoice_ticket')) {
                        giveaway_revoke_invoice_ticket((int)$invoice['id'], 'order_set_unpaid');
                    }

                    if (function_exists('lb_realtime_emit')) {
                        // Order is no longer claimable/visible — boosters' panels need to drop it now.
                        lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                    }
                    if (function_exists('lb_realtime_emit_order')) {
                        lb_realtime_emit_order('order_status_update', $order_id);
                    }

                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Order set as unpaid successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ));
                } else {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Something went wrong 😔',
                        ],
                        'playSound' => 'error',
                    ));
                }
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    function admin_set_order_refunded()
{
    if ($this->is_admin) {
        $order_id = esc($_POST['order_id'] ?? ($_POST['id'] ?? ''));
        $order = db_get_row('orders', ['id' => $order_id]);

        if ($order != false) {
            $invoice = db_get_row('invoices', ['order_type' => 'order', 'order_id' => $order_id]);

            $upd = db_update_row('orders', ['id' => $order_id], [
                'status' => 'REFUNDED',
                'waiting_for_approval' => 0,
                'approval_requested_at' => null,
            ]);

            if ($upd) {
                log_admin_action(ADMIN_ID, 'Set order #' . $order_id . ' as refunded');

                if (!empty($invoice)) {
                    process_cashback_return(
                        $order['client_id'],
                        $invoice['total_price'] > 0 ? $invoice['total_price'] / 100 : $invoice['coins_used'],
                        $order['id'],
                        $invoice['coins_used']
                    );
                }

                if (!empty($invoice) && !empty($invoice['id']) && function_exists('giveaway_revoke_invoice_ticket')) {
                    giveaway_revoke_invoice_ticket((int)$invoice['id'], 'order_refunded');
                }

                if (function_exists('lb_realtime_emit')) {
                    lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                }
                if (function_exists('lb_realtime_emit_order')) {
                    lb_realtime_emit_order('order_status_update', $order_id);
                }

                // Notify client by email using emails/body/order_refunded.php
                if (!empty($order['client_id'])) {
                    db_add_row('notifications', [
                        'type' => 'order_refunded',
                        'data' => json_encode([
                            'order_id' => base64_encode((string)$order_id),
                        ]),
                        'recipient' => 'client',
                        'recipient_id' => (int)$order['client_id'],
                        'is_email' => 1,
                    ]);

                    if (function_exists('trigger_notification_sender_async')) {
                        @trigger_notification_sender_async();
                    }
                }

                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Order set as refunded successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Something went wrong 😔',
                ],
                'playSound' => 'error',
            ]);
        }
    }
}

