    public function admin_add_booster_to_order()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['order_id']);
            $booster_id = intval($_POST['booster_id']);
            $order = db_get_row('orders', ['id' => $order_id]);

            if ($order != false) {
                global $db;
                $orderOptions = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
                $requiredBoosters = max(1, min(4, (int)($orderOptions['boosters'] ?? 1)));
                $isRanked5s = (int)($order['form_id'] ?? 0) === 29;
                $isMultiBoosterOrder = $isRanked5s
                    || (in_array((int)($order['form_id'] ?? 0), [4, 19], true) && $requiredBoosters > 1);

                $existing_cut = $order['booster_cut'] ?? null;
                if (is_numeric($existing_cut) && (float)$existing_cut > 0) {
                    // Keep an existing stored cut (e.g. requested-booster flow).
                    $booster_price = (float)$existing_cut;
                } else {
                    // No cut currently stored on the order (e.g. the previous booster was just
                    // removed, which clears booster_cut). Prefer the cut used by the last booster
                    // on this order instead of resetting to the default time-based curve, so
                    // reassigning a booster keeps the previously configured cut.
                    $last_segment = db_get_rows('order_booster_segments', [
                        'order_id' => $order_id,
                        'order' => 'id,desc',
                        'limit' => 1,
                    ], true);
                    $last_cut = !empty($last_segment) ? ($last_segment[0]['cut_percent'] ?? null) : null;
                    if (is_numeric($last_cut) && (float)$last_cut > 0) {
                        $booster_price = (float)$last_cut;
                    } else {
                        // Manual admin assignment should snapshot the live cut at assignment time.
                        $booster_price = (float) calculate_booster_cut($order, 'percent');
                    }
                }

                $fixedBoosterCut = function_exists('lb_fixed_booster_cut_percent')
                    ? lb_fixed_booster_cut_percent($order, $booster_id)
                    : null;
                if (!$isMultiBoosterOrder && $fixedBoosterCut !== null) {
                    $booster_price = (float)$fixedBoosterCut;
                }

                $booster = db_get_row('boosters', ['id' => $booster_id]);
                if ($booster == false) {
                    echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Booster not found.'], 'playSound' => 'error']);
                    return;
                }

                $upd_order = $duo_now = date('Y-m-d H:i:s');
                if ($isMultiBoosterOrder) {
                    $booster_price = 50;
                    $activeRows = $db->run(
                        "SELECT booster_id, role, slot_no FROM order_boosters WHERE order_id = ? AND status = 'ACTIVE' ORDER BY slot_no ASC, id ASC",
                        $order_id
                    ) ?: [];
                    foreach ($activeRows as $activeRow) {
                        if ((int)($activeRow['booster_id'] ?? 0) === $booster_id) {
                            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Already assigned', 'message' => 'This booster is already assigned to the order.'], 'playSound' => 'error']);
                            return;
                        }
                    }
                    if (count($activeRows) >= $requiredBoosters) {
                        echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Team full', 'message' => 'All booked booster slots are already filled.'], 'playSound' => 'error']);
                        return;
                    }

                    $usedSlots = [];
                    foreach ($activeRows as $activeRow) {
                        $usedSlots[(int)($activeRow['slot_no'] ?? 0)] = true;
                    }
                    $slotNo = 1;
                    while ($slotNo <= $requiredBoosters && !empty($usedSlots[$slotNo])) {
                        $slotNo++;
                    }
                    if ($slotNo > $requiredBoosters) {
                        echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Team full', 'message' => 'No booster slot is available.'], 'playSound' => 'error']);
                        return;
                    }
                    $role = 'ClashSlot' . $slotNo;
                    if ($isRanked5s) {
                        $clientRole = function_exists('lb_ranked_5s_normalize_role') ? lb_ranked_5s_normalize_role($orderOptions['roles'] ?? '') : '';
                        $availableRoles = function_exists('lb_ranked_5s_available_roles') ? lb_ranked_5s_available_roles((int)$order_id, $clientRole) : [];
                        $requestedRole = function_exists('lb_ranked_5s_normalize_role')
                            ? lb_ranked_5s_normalize_role($_POST['ranked_5s_lane'] ?? '')
                            : trim((string)($_POST['ranked_5s_lane'] ?? ''));
                        $role = in_array($requestedRole, $availableRoles, true)
                            ? $requestedRole
                            : (string)($availableRoles[0] ?? '');
                        if ($role === '') {
                            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'No lane available', 'message' => 'No Ranked 5s lane is available.'], 'playSound' => 'error']);
                            return;
                        }
                    }
                    $existingMembership = $db->run(
                        "SELECT id FROM order_boosters WHERE order_id = ? AND booster_id = ? LIMIT 1",
                        $order_id,
                        $booster_id
                    ) ?: [];
                    if (!empty($existingMembership)) {
                        $db->run(
                            "UPDATE order_boosters
                                SET slot_no = ?, role = ?, cut_percent = 50, status = 'ACTIVE',
                                    claimed_at = ?, updated_at = ?
                              WHERE id = ?",
                            $slotNo,
                            $role,
                            $duo_now,
                            $duo_now,
                            (int)$existingMembership[0]['id']
                        );
                    } else {
                        $db->run(
                            "INSERT INTO order_boosters (order_id, booster_id, slot_no, role, cut_percent, status, claimed_at)
                             VALUES (?, ?, ?, ?, 50, 'ACTIVE', ?)",
                            $order_id,
                            $booster_id,
                            $slotNo,
                            $role,
                            $duo_now
                        );
                    }
                }

                $order_update = ['status' => 'IN_PROGRESS', 'booster_cut' => $isMultiBoosterOrder ? 50 : $booster_price];
                if (!$isMultiBoosterOrder || empty($order['booster_id'])) {
                    $order_update['booster_id'] = $booster_id;
                    $order_update['claimed_at'] = $duo_now;
                }
                $upd_order = db_update_row('orders', ['id' => $order_id], $order_update);
                if ($isMultiBoosterOrder) {
                    if (function_exists('lb_multi_booster_sync_primary')) {
                        lb_multi_booster_sync_primary((int)$order_id);
                    }
                    $upd_order = true;
                }

                // Web notifications for assignment
                $client_row = db_get_row('clients', ['id' => (int)$order['client_id']]);
                $client_username = $client_row != false && !empty($client_row['username']) ? (string)$client_row['username'] : 'Client';

                db_add_row('notifications', [
                    'type' => 'booster_assigned',
                    'recipient' => 'client',
                    'recipient_id' => (int)$order['client_id'],
                    'data' => json_encode([
                        'order_id' => base64_encode((string)$order_id),
                        'booster_username' => base64_encode((string)($booster['username'] ?? 'Booster')),
                        'booster_id' => base64_encode((string)$booster_id),
                    ]),
                    'is_web' => 1,
                    'is_sent' => 1,
                ]);

                db_add_row('notifications', [
                    'type' => 'booster_assigned',
                    'recipient' => 'booster',
                    'recipient_id' => (int)$booster_id,
                    'data' => json_encode([
                        'order_id' => base64_encode((string)$order_id),
                        'client_username' => base64_encode((string)$client_username),
                    ]),
                    'is_web' => 1,
                    'is_sent' => 1,
                ]);

                if ($upd_order) {
                    log_admin_action(ADMIN_ID, 'Added booster #' . $booster_id . ' to order #' . $order_id);

                    $chat_data = [
                        'message' => 'Booster ' . $booster['username'] . ' has been assigned to your order! 🎉',
                        'message_type' => 'text',
                    ];

                    $user = [
                        'id' => '999',
                        'username' => 'System',
                        'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png'
                    ];

                    chat_insert_message($order_id, $chat_data, $user, 'system');

                    if (function_exists('lb_realtime_emit')) {
                        lb_realtime_emit_order('chat_update', $order_id);
                        lb_realtime_emit_order('order_status_update', $order_id);
                        lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                    }

                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Booster added to order successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ));

                    // The Discord DM below is two sequential calls to the Discord API and
                    // used to run BEFORE this response, so the admin waited seconds for a
                    // notification that has nothing to do with the assignment succeeding.
                    // Answer first, notify afterwards.
                    if (function_exists('lb_finish_request_early')) {
                        lb_finish_request_early();
                    }

                    if (!empty($booster['discord_id'])) {
                        $botToken = DS_BOT_TOKEN;
                        $discordUserId = $booster['discord_id'];
                        $dmChannel = getDMChannelId($botToken, $discordUserId);

                        $orderUrl = BASE_URL . '/booster-area/order/' . $order['id'];

                        if ($dmChannel) {
                            $embed = [
                                "title" => 'YOU HAVE BEEN ASSIGNED TO A NEW ORDER',
                                "author" => [
                                    "name" => "LoLBoost.GG",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "description" => "You have been assigned to a new order #" . $order['id'] . "! 🎉\n\nPlease check your dashboard for more details and respond to the customer through the website chat.\n",
                                "footer" => [
                                    "text" => "LoLBoost.GG - Ranking up never been easier",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "timestamp" => date('c'),
                                "color" => 0x5865F2
                            ];

                            $components = [
                                [
                                    "type" => 1,
                                    "components" => [
                                        [
                                            "type" => 2,
                                            "style" => 5,
                                            "label" => "🔎 View Order",
                                            "url" => $orderUrl
                                        ]
                                    ]
                                ]
                            ];

                            if ($dmChannel && $embed !== null) {
                                $msg = json_encode([
                                    "embeds" => [$embed],
                                    "components" => $components
                                ], JSON_UNESCAPED_SLASHES);

                                sendEmbedDM($botToken, $dmChannel, $msg);
                            }
                        }
                    }
                } else {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Something went wrong 😔',
                        ],
                        'playSound' => 'error',
                    ));
                }
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }


    private function complete_ranked_5s_order_fixed_payout(array $order): void
    {
        global $db;

        $order_id = (int)($order['id'] ?? 0);
        $isRanked5s = (int)($order['form_id'] ?? 0) === 29;
        $current_timestamp = date('Y-m-d H:i:s');
        $requiredBoosters = 1;

        try {
            $opts = db_get_row('order_options', [
                'order_id' => $order_id,
                'select' => 'boosters',
            ], 1);
            $requiredBoosters = max(1, min(4, (int)($opts['boosters'] ?? 1)));
        } catch (Throwable $e) {
            $requiredBoosters = 1;
        }

        $priceEur = (int)($order['price_eur'] ?? 0);
        if ($priceEur <= 0) {
            $priceEur = (int)($order['price'] ?? 0);
        }

        $teamCutPercent = in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true)
            ? 50
            : max(0, min(100, (int)($order['booster_cut'] ?? calculate_booster_cut($order, 'percent'))));
        $teamPool = (int)floor(($priceEur * $teamCutPercent) / 100);

        $assignedRows = [];
        try {
            $assignedRows = $db->run(
                "SELECT DISTINCT booster_id
                   FROM order_boosters
                  WHERE order_id = ?
                    AND status = 'ACTIVE'
                    AND booster_id IS NOT NULL
                    AND booster_id > 0
                  ORDER BY booster_id ASC",
                $order_id
            ) ?: [];
        } catch (Throwable $e) {
            $assignedRows = [];
        }

        $boosterIds = [];
        foreach ($assignedRows as $assignedRow) {
            $bid = (int)($assignedRow['booster_id'] ?? 0);
            if ($bid > 0) {
                $boosterIds[$bid] = $bid;
            }
        }

        $mainBoosterId = (int)($order['booster_id'] ?? 0);
        if ($mainBoosterId > 0) {
            $boosterIds[$mainBoosterId] = $mainBoosterId;
        }

        if (empty($boosterIds)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'No boosters are assigned to this multi-booster order.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $boosterIds = array_values($boosterIds);
        $payoutDivisor = count($boosterIds);
        $basePayout = intdiv($teamPool, $payoutDivisor);
        $payoutRemainder = $teamPool % $payoutDivisor;

        foreach ($boosterIds as $boosterIndex => $boosterId) {
            // Split the complete 50% pool across the actually assigned boosters.
            // Any indivisible cent is assigned deterministically so the payouts
            // always add up to the exact team pool.
            $targetPayout = $basePayout + ($boosterIndex < $payoutRemainder ? 1 : 0);
            $alreadyPaid = 0;
            try {
                $alreadyPaid = (int)$db->single(
                    "SELECT COALESCE(SUM(amount), 0)
                       FROM booster_payments
                      WHERE booster_id = ?
                        AND type IN ('order_completion', 'order_completion_cancel')
                        AND note = ?",
                    [$boosterId, (string)$order_id]
                );
            } catch (Throwable $e) {
                $alreadyPaid = 0;
            }

            // Reconcile to the target instead of merely skipping existing rows.
            // This also corrects a legacy full single-booster payout when an
            // additional team member was assigned afterwards.
            $payoutAdjustment = $targetPayout - $alreadyPaid;
            if ($payoutAdjustment === 0) {
                continue;
            }

            $booster = db_get_row('boosters', ['id' => $boosterId]);
            if ($booster == false) {
                continue;
            }

            $oldBalance = (int)($booster['balance'] ?? 0);
            $newBalance = $oldBalance + $payoutAdjustment;

            db_update_row('boosters', ['id' => $boosterId], ['balance' => $newBalance]);

            db_add_row('booster_payments', [
                'booster_id' => $boosterId,
                'type' => 'order_completion',
                'note' => (string)$order_id,
                'amount' => $payoutAdjustment,
                'currency' => 'EUR',
                'sender' => ADMIN_DATA['username'],
                'sender_type' => 'admin',
                'sender_id' => ADMIN_ID,
                'balance_update' => $oldBalance . '|' . $newBalance,
                'created_at' => $current_timestamp,
            ]);

            if ($payoutAdjustment > 0) {
                db_add_row('notifications', [
                    'type' => 'order_completed',
                    'data' => json_encode([
                        'order_id' => base64_encode((string)$order_id),
                        'payout_cents' => $targetPayout,
                    ]),
                    'recipient' => 'booster',
                    'recipient_id' => $boosterId,
                    'is_web' => 1,
                    'is_sent' => 1,
                ]);
            }

            log_admin_action(
                ADMIN_ID,
                "Team order #{$order_id} payout reconciled: booster #{$boosterId} adjustment €"
                . number_format($payoutAdjustment / 100, 2, '.', '')
                . ", target €" . number_format($targetPayout / 100, 2, '.', '')
            );
        }

        // Finalize the team order and clear the review flag in the same update.
        // The list view prioritizes waiting_for_approval while the detail view
        // reads orders.status, so leaving either value stale creates the two
        // conflicting states "WAITING FOR APPROVAL" and "IN PROGRESS".
        $db->run(
            "UPDATE orders
                SET status = 'COMPLETED',
                    completed_at = ?,
                    booster_cut = ?,
                    waiting_for_approval = 0
              WHERE id = ?",
            $current_timestamp,
            $teamCutPercent,
            $order_id
        );

        $completedOrder = db_get_row('orders', ['id' => $order_id], 1);
        if ($completedOrder == false || strtoupper((string)($completedOrder['status'] ?? '')) !== 'COMPLETED') {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Completion failed',
                    'message' => 'The payouts were processed, but the order status could not be finalized. Please contact a developer before retrying.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        try {
            $db->run(
                "UPDATE order_boosters
                    SET cut_percent = ?,
                        updated_at = ?
                  WHERE order_id = ?
                    AND status = 'ACTIVE'",
                $teamCutPercent,
                $current_timestamp,
                $order_id
            );
        } catch (Throwable $e) {}

        if (function_exists('lb_referral_handle_completed_order')) {
            lb_referral_handle_completed_order($order_id);
        }

        $file_url = db_get_row('order_screenshots', ['order_id' => $order_id]);
        $file_url = $file_url != false ? $file_url['file_url'] : '';

        db_add_row('notifications', [
            'type' => 'order_completed',
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'file_url' => base64_encode((string)$file_url),
                'booster_id' => base64_encode((string)$mainBoosterId),
            ]),
            'recipient' => 'client',
            'recipient_id' => (int)($order['client_id'] ?? 0),
            'is_email' => 1,
        ]);

        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit_order('order_status_update', $order_id);
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => $isRanked5s
                    ? 'Ranked 5s order completed. Every assigned booster received the fixed 50% team share.'
                    : 'Team order completed. The 50% booster pool was split equally between the booked slots.',
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_set_order_completed()
    {
        if (!$this->is_admin) {
            // Returning with no body sent an empty response, which the frontend
            // cannot parse as JSON — it then failed silently instead of saying
            // the session was not recognised as admin.
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Not authorized',
                    'message' => 'Your admin session expired. Please reload and log in again.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int) esc($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid order ID.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id]);
        if ($order == false || $order['booster_id'] == null || $order['status'] !== 'IN_PROGRESS') {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Order not found, no booster assigned, or order is not IN_PROGRESS.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $isClashTeamOrder = false;
        if (in_array((int)($order['form_id'] ?? 0), [4, 19], true)) {
            $requiredTeamSize = function_exists('lb_multi_booster_required_count')
                ? lb_multi_booster_required_count($order_id)
                : 1;
            $assignedTeamSize = function_exists('lb_multi_booster_claimed_count')
                ? lb_multi_booster_claimed_count($order_id)
                : 0;
            $isClashTeamOrder = max($requiredTeamSize, $assignedTeamSize) > 1;
        }
        if ((int)($order['form_id'] ?? 0) === 29 || $isClashTeamOrder) {
            $this->complete_ranked_5s_order_fixed_payout($order);
            return;
        }

        $cut_raw = trim((string)($_POST['cut'] ?? ''));
        $is_fixed = (int)($_POST['is_fixed'] ?? 0);

        // Admin 3 may not change the cut: always complete with the predefined cut.
        if ((int) ADMIN_ID === 3) {
            $is_fixed = 0;
            $cut_raw = (string) (function_exists('calculate_effective_booster_cut_percent')
                ? calculate_effective_booster_cut_percent($order)
                : (float)($order['booster_cut'] ?? 0));
        }

        if ($cut_raw === '') {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Please enter a cut amount',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // Normalize "10,5" -> "10.5"
        $cut_raw = str_replace(',', '.', $cut_raw);

        $form = db_get_row('boost_forms', ['id' => (int)$order['form_id']]);
        $form_type = $form != false ? (string)$form['type'] : '';

        $booster_id = (int) $order['booster_id'];
        $this->block_booster_from_order_claim($order_id, $booster_id, (defined('ADMIN_ID') ? (int)ADMIN_ID : null), 'Removed from order by admin');
        $booster = db_get_row('boosters', ['id' => $booster_id]);
        if ($booster == false) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Booster not found.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }


        $fixedBoosterCut = function_exists('lb_fixed_booster_cut_percent')
            ? lb_fixed_booster_cut_percent($order, $booster_id)
            : null;
        if ($fixedBoosterCut !== null) {
            $is_fixed = 0;
            $cut_raw = (string)$fixedBoosterCut;
        }


        // Auto-generate a progress note if none was provided (keeps UI optional)
        $progress_note = trim((string)($_POST['progress_note'] ?? ''));
        if ($progress_note === '' && !empty($progress_arr)) {
            $pf = [];
            if (!empty($progress_from)) {
                $dec_pf = json_decode((string)$progress_from, true);
                $pf = is_array($dec_pf) ? $dec_pf : [];
            }

            $delta_str = function(int $from, int $to): string {
                $d = $to - $from;
                return ($d >= 0 ? '+' : '') . (string)$d;
            };

            if (in_array($form_type, ['win', 'arena'], true)) {
                $from = (int)($pf['wins_completed'] ?? 0);
                $to = (int)($progress_arr['wins_completed'] ?? 0);
                $progress_note = "Wins {$from} → {$to} (" . $delta_str($from, $to) . ")";
            } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true)) {
                $from = (int)($pf['matches_completed'] ?? 0);
                $to = (int)($progress_arr['matches_completed'] ?? 0);
                $progress_note = "Games {$from} → {$to} (" . $delta_str($from, $to) . ")";
            } elseif ($form_type === 'coaching') {
                $from = (int)($pf['hours_completed'] ?? 0);
                $to = (int)($progress_arr['hours_completed'] ?? 0);
                $progress_note = "Hours {$from} → {$to} (" . $delta_str($from, $to) . ")";
            } elseif (in_array($form_type, ['mastery', 'level'], true)) {
                $from = (int)($pf['reached_level'] ?? $pf['start_tier'] ?? 0);
                $to = (int)($progress_arr['reached_level'] ?? $progress_arr['start_tier'] ?? 0);
                $progress_note = "Level {$from} → {$to} (" . $delta_str($from, $to) . ")";
            } elseif ($form_type === 'rank') {
                // For rank forms, progress payload updates START fields to the reached point.
                $from_t = (string)($pf['start_tier'] ?? $pf['reached_tier'] ?? '');
                $from_d = (string)($pf['start_division'] ?? $pf['reached_division'] ?? '');
                $to_t = (string)($progress_arr['start_tier'] ?? '');
                $to_d = (string)($progress_arr['start_division'] ?? '');
                $from_lbl = trim($from_t . ' ' . $from_d);
                $to_lbl = trim($to_t . ' ' . $to_d);
                if ($from_lbl !== '' || $to_lbl !== '') {
                    $progress_note = "Rank {$from_lbl} → {$to_lbl}";
                }
            }
        }

        $current_timestamp = date('Y-m-d H:i:s');

        // Base order value (EUR cents) that is still "in the order" for the current booster.
        $base_remaining_eur = (int)($order['price_eur'] ?? 0);
        if ($base_remaining_eur < 0) {
            $base_remaining_eur = 0;
        }

        // Calculate payout for the base order part (add-ons are handled separately and distributed proportionally).
        $payout_base = 0; // EUR cents
        $cut_percent = 0; // integer percent snapshot

        if ($is_fixed === 1) {
            // Fixed payout entered in EUR (e.g., "12.34") -> cents
            $payout_base = (int) util_format_price_db((float)$cut_raw);

            if ($base_remaining_eur > 0) {
                $cut_percent = (int) round(($payout_base / $base_remaining_eur) * 100);
            }
        } else {
            // Percent payout
            $cut_percent = (int) round((float)$cut_raw);
            if ($cut_percent < 0) $cut_percent = 0;
            if ($cut_percent > 100) $cut_percent = 100;

            $payout_base = (int) round($base_remaining_eur * $cut_percent / 100);
        }

        // Update booster balance + create booster_payments row for base payout
        if ($payout_base !== 0) {
            $old_balance = (int)($booster['balance'] ?? 0);
            $new_balance = $old_balance + $payout_base;

            db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance]);

            db_add_row('booster_payments', [
                'booster_id' => $booster_id,
                'type' => 'order_completion',
                'note' => (string)$order_id,
                'amount' => $payout_base,
                'currency' => 'EUR',
                'sender' => ADMIN_DATA['username'],
                'sender_type' => 'admin',
                'sender_id' => ADMIN_ID,
                'balance_update' => $old_balance . '|' . $new_balance,
                'created_at' => $current_timestamp,
            ]);

            log_admin_action(ADMIN_ID, "Order #{$order_id} completed: booster #{$booster_id} base payout €" . number_format($payout_base / 100, 2, '.', ''));
        }


$addon_remainder = 0; // EUR cents

// --- Add-on remainder payout to current booster (same cut logic as base) ---
// Add-ons are paid via separate invoices. At completion, pay remaining addon pool to current booster.
global $db;
$addons_total = (int) $this->get_paid_addons_total_eur_cents((int)$order_id); // EUR cents, paid add-ons
if ($addons_total > 0) {
    $base_invoice_eur = (int) $this->get_base_order_invoice_total_eur_cents((int)$order_id);
    $addons_already_in_base_payout = ($base_invoice_eur > 0 && $base_remaining_eur >= ($base_invoice_eur + $addons_total - 1));

    if ($addons_already_in_base_payout) {
        // orders.price_eur already includes the add-on invoices, so payout_base already contains the add-on cut.
        // Do not create a second addon_payment row for the same add-on amount.
        $addons_pool = 0;
    } else {
        $addons_pool = (int) round($addons_total * $cut_percent / 100); // EUR cents, cut-applied pool
    }

    // Total already paid out for this order as addon_payment (EUR cents)
    $paid_rows = $db->run(
        "SELECT COALESCE(SUM(amount), 0) AS paid
         FROM booster_payments
         WHERE type = 'addon_payment' AND note = ?",
        (string)$order_id
    );
    $already_paid_addons = (is_array($paid_rows) && isset($paid_rows[0]['paid'])) ? (int)$paid_rows[0]['paid'] : 0;

    $addon_remainder = $addons_pool - $already_paid_addons;

    // Pay remainder only to current booster (no clawbacks)
    if ($addon_remainder > 0) {
        $booster_now = db_get_row('boosters', ['id' => $booster_id]);
        if ($booster_now != false) {
            $old_balance2 = (int)($booster_now['balance'] ?? 0);
            $new_balance2 = $old_balance2 + $addon_remainder;

            db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance2]);

            db_add_row('booster_payments', [
                'booster_id' => $booster_id,
                'type' => 'addon_payment',
                'note' => (string)$order_id,
                'amount' => $addon_remainder,
                'currency' => 'EUR',
                'sender' => ADMIN_DATA['username'],
                'sender_type' => 'admin',
                'sender_id' => ADMIN_ID,
                'balance_update' => $old_balance2 . '|' . $new_balance2,
                'created_at' => $current_timestamp,
            ]);

            log_admin_action(ADMIN_ID, "Order #{$order_id} completed: booster #{$booster_id} addon remainder payout €" . number_format($addon_remainder / 100, 2, '.', ''));
        }
    }
}

        // Booster helpers receive +5 percentage points on the same cut base.
        // Example: normal 40% cut + helper bonus 5% = 45% total, stored separately.
        $helper_bonus_base = (int)$base_remaining_eur;
        if ((int)$addon_remainder > 0 && (int)$cut_percent > 0) {
            $helper_bonus_base += (int) round(((int)$addon_remainder * 100) / (int)$cut_percent);
        }

        $helper_bonus = $this->add_booster_helper_bonus_payment(
            $booster_id,
            $order_id,
            $helper_bonus_base,
            ADMIN_DATA['username'],
            'admin',
            (int)ADMIN_ID,
            $current_timestamp
        );

        $monthly_top_booster_bonus = $this->add_monthly_top_booster_bonus_payment(
            $booster_id,
            $order_id,
            $helper_bonus_base,
            ADMIN_DATA['username'],
            'admin',
            (int)ADMIN_ID,
            $current_timestamp
        );

        // Mark order as completed (keep booster assigned; status is the source of truth)
        $complete_update = [
            'status' => 'COMPLETED',
            'completed_at' => $current_timestamp,
            'booster_cut' => $cut_percent,
            'waiting_for_approval' => 0,
        ];
        $complete_update = array_merge($complete_update, $this->duo_timer_stop_payload($order, $current_timestamp));
        db_update_row('orders', ['id' => $order_id], $complete_update);

        if (function_exists('lb_referral_handle_completed_order')) {
            lb_referral_handle_completed_order($order_id);
        }

        log_admin_action(ADMIN_ID, 'Completed order #' . $order_id, $order_id, 'order_action');
        // Notify client
        $file_url = db_get_row('order_screenshots', ['order_id' => $order_id]);
        $file_url = $file_url != false ? $file_url['file_url'] : '';

        db_add_row('notifications', [
            'type' => 'order_completed',
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'file_url' => base64_encode((string)$file_url),
                'booster_id' => base64_encode((string)$booster_id),
            ]),
            'recipient' => 'client',
            'recipient_id' => $order['client_id'],
            'is_email' => 1,
        ]);
// Notify booster (web) about completion payout
$payout_total = (int)$payout_base + (int)$addon_remainder + (int)$helper_bonus; // EUR cents
if ($payout_total < 0) $payout_total = 0;

db_add_row('notifications', [
    'type' => 'order_completed',
    'data' => json_encode([
        'order_id' => base64_encode((string)$order_id),
        'payout_cents' => $payout_total,
    ]),
    'recipient' => 'booster',
    'recipient_id' => (int)$booster_id,
    'is_web' => 1,
    'is_sent' => 1,
]);

        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit_order('order_status_update', $order_id);
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => 'Order completed successfully 🎉',
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_calc_edit_order_price()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'message' => 'Not authorized.']);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $order = $order_id > 0 ? db_get_row('orders', ['id' => $order_id]) : false;
        $stored_options = $order ? db_get_row('order_options', ['order_id' => $order_id]) : false;
        if (!$order || !$stored_options) {
            echo json_encode(['success' => false, 'message' => 'Order data could not be loaded.']);
            return;
        }

        $options = $stored_options;
        foreach ($_POST as $key => $value) {
            if (strpos((string)$key, 'order_options-') !== 0) continue;
            $column = substr((string)$key, strlen('order_options-'));
            if (!array_key_exists($column, $stored_options)) continue;
            if (is_array($value)) {
                $value = implode(',', array_values(array_filter(array_map('trim', $value), static function ($item) {
                    return $item !== '';
                })));
            }
            $options[$column] = $value;
        }

        $form_id = (int)($_POST['orders-form_id'] ?? $order['form_id']);
        $calc = $this->calc_current_total_price_cents($order_id, $options, $form_id, false);
        if (($calc['success'] ?? false) !== true) {
            echo json_encode($calc);
            return;
        }

        echo json_encode([
            'success' => true,
            'price_cents' => (int)$calc['order_cents'],
            'price' => number_format(((int)$calc['order_cents']) / 100, 2, '.', ''),
            'currency' => (string)($order['currency'] ?? 'EUR'),
        ]);
    }

    public function admin_edit_order()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'You are not authorized to perform this action.',
                ],
                'playSound' => 'error'
            ]);
            return; // WICHTIG: sonst läuft der Code weiter
        }

        if (!isset($_POST['order_id']) || !is_numeric($_POST['order_id'])) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid order ID provided.',
                ],
                'playSound' => 'error'
            ]);
            return;
        }

        $order_id = (int) $_POST['order_id'];

        // BEFORE snapshots (für Audit-Log)
        $before_orders = db_get_row('orders', ['id' => $order_id]);
        $before_options = db_get_row('order_options', ['order_id' => $order_id]) ?: [];
        $before_accounts = db_get_row('order_accounts', ['order_id' => $order_id]) ?: [];

        if (!$before_orders) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Order not found.',
                ],
                'playSound' => 'error'
            ]);
            return;
        }


        // === Customer snapshot: save ORIGINAL order/options at the first admin edit ===
        // Customer will keep seeing this snapshot; booster/admin see edited version.
        $orig_exists = db_get_row('order_original_data', ['order_id' => $order_id, 'select' => 'order_id'], 1);
        if (empty($orig_exists)) {
            db_insert_row('order_original_data', [
                'order_id' => $order_id,
                'orders_json' => json_encode($before_orders, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                'options_json' => json_encode($before_options ?: [], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                'created_by' => (int) ADMIN_ID,
                'created_at' => date('Y-m-d H:i:s'),
            ]);
        }

        // Diff helper
        $build_changes = function (array $before, array $after, array $fields, array $redact = []) {
            $changes = [];
            foreach ($fields as $f) {
                $old = array_key_exists($f, $before) ? $before[$f] : null;
                $new = array_key_exists($f, $after) ? $after[$f] : null;

                if (is_string($old))
                    $old = trim($old);
                if (is_string($new))
                    $new = trim($new);

                if ((string) $old === (string) $new)
                    continue;

                if (in_array($f, $redact, true)) {
                    $changes[$f] = ['old' => '[REDACTED]', 'new' => '[REDACTED]'];
                } else {
                    $changes[$f] = ['old' => $old, 'new' => $new];
                }
            }
            return $changes;
        };

        $_POST['order_options-roles'] = $_POST['order_options-roles'] ?? [];
        $_POST['order_options-champions'] = $_POST['order_options-champions'] ?? [];
        $_POST['order_options-agents'] = $_POST['order_options-agents'] ?? [];

        $data = [
            'orders' => [
                'form_id' => null,
                'price' => null,
                'price_eur' => null,
                'booster_cut' => null,
            ],
            'order_options' => [
                'server' => '',
                'is_duo' => 0,
                'start_tier' => null,
                'start_division' => null,
                'end_tier' => null,
                'end_division' => null,
                'start_lp' => null,
                'start_rr' => null,
                'end_lp' => null,
                'lp_gain' => null,
                'matches' => null,
                'hours' => null,
                'coach_type' => '',
                'current_rank' => '',
                'roles' => '',
                'champions' => '',
                'agents' => '',
                'queue_type' => '',
                'platform' => '',
                'flash_position' => '',
                'is_priority' => 0,
                'is_streaming' => 0,
                'is_solo_only' => 0,
                'is_bonus_win' => 0,
                'is_coaching' => 0,
                'is_voice' => 0,
                'is_hidden_duo' => 0,
                'is_offline_mode' => 0,
                'is_undercover_winrate' => 0,
                'is_moderate_kda' => 0
            ],
            'order_accounts' => [
                'ign' => '',
                'login' => '',
                'password' => ''
            ]
        ];

        foreach ($_POST as $key => $value) {
            if ($key === 'order_id')
                continue;

            $parts = explode('-', $key);
            if (count($parts) !== 2)
                continue;

            $table = $parts[0];
            $column = $parts[1];

            if (!isset($data[$table]))
                continue;
            if (!array_key_exists($column, $data[$table]))
                continue;

            if (is_array($value)) {
                $value = array_values(array_unique(array_filter(array_map('trim', $value), static function ($item) {
                    return $item !== '';
                })));
                $value = implode(',', $value);
            } elseif ($value === '') {
                if (in_array($column, ['ign', 'login', 'password', 'flash_position', 'coach_type', 'current_rank', 'queue_type', 'server'], true)) {
                    $value = '';
                } else {
                    $value = null;
                }
            }

            if ($column === 'price' && $value !== null) {
                $value = util_format_price_db($value);
                $data[$table]['price'] = $value;

                $order = db_get_row('orders', ['id' => $order_id, 'select' => 'currency']);
                if ($order && $order['currency'] == 'EUR') {
                    $data[$table]['price_eur'] = $value;
                } else {
                    $data[$table]['price_eur'] = round($value / get_exchange_rate());
                }
                continue;
            }

            if (strpos($column, 'is_') === 0) {
                $value = $value ? 1 : 0;
            }

            $data[$table][$column] = $value;
        }

        try {
            // Updates
            db_update_row('orders', ['id' => $order_id], $data['orders']);

            $options_exists = db_get_row('order_options', ['order_id' => $order_id, 'select' => 'id']);
            if ($options_exists) {
                db_update_row('order_options', ['order_id' => $order_id], $data['order_options']);
            } else {
                $data['order_options']['order_id'] = $order_id;
                db_insert_row('order_options', $data['order_options']);
            }

            $accounts_exists = db_get_row('order_accounts', ['order_id' => $order_id, 'select' => 'id']);
            if ($accounts_exists) {
                db_update_row('order_accounts', ['order_id' => $order_id], $data['order_accounts']);
            } else {
                $data['order_accounts']['order_id'] = $order_id;
                db_insert_row('order_accounts', $data['order_accounts']);
            }

            // AFTER snapshots (für Audit-Log)
            $after_orders = db_get_row('orders', ['id' => $order_id]);
            $after_options = db_get_row('order_options', ['order_id' => $order_id]) ?: [];
            $after_accounts = db_get_row('order_accounts', ['order_id' => $order_id]) ?: [];

            // Admin log + ID (WICHTIG: log_admin_action muss int zurückgeben!)
            $adminLogId = log_admin_action(ADMIN_ID, "Edited order #" . $order_id);

            // Fields (Whitelist)
            $orders_fields = ['form_id', 'price', 'price_eur', 'booster_cut'];
            $options_fields = [
                'server',
                'is_duo',
                'start_tier',
                'start_division',
                'end_tier',
                'end_division',
                'start_lp',
                'start_rr',
                'end_lp',
                'lp_gain',
                'matches',
                'hours',
                'coach_type',
                'current_rank',
                'roles',
                'champions',
                'agents',
                'queue_type',
                'platform',
                'flash_position',
                'is_priority',
                'is_streaming',
                'is_solo_only',
                'is_bonus_win',
                'is_coaching',
                'is_voice',
                'is_hidden_duo',
                'is_offline_mode',
                'is_undercover_winrate',
                'is_moderate_kda'
            ];
            $accounts_fields = ['ign', 'login', 'password'];

            // Build diffs
            $chg_orders = $build_changes($before_orders, $after_orders ?: [], $orders_fields);
            $chg_options = $build_changes($before_options, $after_options, $options_fields);
            $chg_accounts = $build_changes($before_accounts, $after_accounts, $accounts_fields, ['password']);

            // Save change logs (only if not empty)
            if (!empty($chg_orders)) {
                db_insert_row('admin_log_changes', [
                    'admin_log_id' => $adminLogId,
                    'admin_id' => (int) ADMIN_ID,
                    'entity_type' => 'orders',
                    'entity_id' => $order_id,
                    'changes' => json_encode($chg_orders, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                ]);
            }

            if (!empty($chg_options)) {
                db_insert_row('admin_log_changes', [
                    'admin_log_id' => $adminLogId,
                    'admin_id' => (int) ADMIN_ID,
                    'entity_type' => 'order_options',
                    'entity_id' => $order_id,
                    'changes' => json_encode($chg_options, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                ]);
            }

            if (!empty($chg_accounts)) {
                db_insert_row('admin_log_changes', [
                    'admin_log_id' => $adminLogId,
                    'admin_id' => (int) ADMIN_ID,
                    'entity_type' => 'order_accounts',
                    'entity_id' => $order_id,
                    'changes' => json_encode($chg_accounts, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                ]);
            }

            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Order edited successfully 🎉',
                ],
                'refreshPage' => true,
                'playSound' => 'success'
            ]);
            return;

        } catch (Exception $e) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'error',
                    'title' => 'Error',
                    'message' => $e->getMessage(),
                ],
                'playSound' => 'error'
            ]);
            return;
        }
    }

    public function admin_sync_customer_order_view()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'You are not authorized to perform this action.',
                ],
                'playSound' => 'error'
            ]);
            return;
        }

        if (!isset($_POST['order_id']) || !is_numeric($_POST['order_id'])) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid order ID provided.',
                ],
                'playSound' => 'error'
            ]);
            return;
        }

        $order_id = (int) $_POST['order_id'];

        try {
            $order = db_get_row('orders', ['id' => $order_id]);
            if (!$order) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Order not found.',
                    ],
                    'playSound' => 'error'
                ]);
                return;
            }

            $options = db_get_row('order_options', ['order_id' => $order_id], true);
            if (empty($options)) $options = [];

            $json_flags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES;

            // What the customer should see (can be updated by this button)
            $customer_payload = [
                'customer_orders_json'   => json_encode($order, $json_flags),
                'customer_options_json'  => json_encode($options, $json_flags),
                'customer_updated_by'    => (int) (defined('ADMIN_ID') ? ADMIN_ID : 0),
                'customer_updated_at'    => date('Y-m-d H:i:s'),
            ];

            // Ensure the immutable ORIGINAL snapshot exists (created once on first edit)
            $exists = db_get_row('order_original_data', ['order_id' => $order_id], true);

            if (empty($exists)) {
                // If someone clicks sync before any edit happened, create both original + customer snapshots as current.
                db_insert_row('order_original_data', array_merge([
                    'order_id'     => $order_id,
                    'orders_json'  => json_encode($order, $json_flags),
                    'options_json' => json_encode($options, $json_flags),
                    'created_by'   => (int) (defined('ADMIN_ID') ? ADMIN_ID : 0),
                    'created_at'   => date('Y-m-d H:i:s'),
                ], $customer_payload));
            } else {
                // Only update what the CUSTOMER sees. Keep orders_json/options_json untouched.
                db_update_row('order_original_data', ['order_id' => $order_id], $customer_payload);
            }

            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Customer view updated to current edited order.',
                ],
                'refreshPage' => true,
                'playSound' => 'success'
            ]);
            return;

        } catch (Exception $e) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'error',
                    'title' => 'Error',
                    'message' => $e->getMessage(),
                ],
                'playSound' => 'error'
            ]);
            return;
        }
    }






