    public function admin_delete_order()
{
    if ($this->is_admin) {
        $order_id = (int) esc($_POST['order_id'] ?? $_POST['id'] ?? 0);
        unset($_POST['order_id'], $_POST['id']);

        $order = $order_id > 0 ? db_get_row('orders', ['id' => $order_id]) : false;

        // Allow deleting UNPAID orders even if a booster was pre-assigned
        if ($order != false && ($order['status'] ?? null) === 'UNPAID') {

            if (!empty($order['booster_id'])) {
                db_update_row('orders', ['id' => $order_id], [
                    'booster_id' => null,
                    'claimed_at' => null,
                    'booster_cut' => null,
                    'waiting_for_approval' => 0,
                    'approval_requested_at' => null,
                ]);
            }

            db_delete_rows('orders', ['id' => $order_id]);
            log_admin_action(ADMIN_ID, 'Deleted order #' . $order['id']);

            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Order deleted successfully 🎉',
                ],
                'playSound' => 'success',
                'redirectUrl' => ADMN_URL . '/orders',
            ]);
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Something went wrong 😔',
                ],
                'playSound' => 'error',
            ]);
        }
    }
}

public function admin_delete_egirl_order()
{
    if (!$this->is_admin) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
        return;
    }

    $raw_id = esc($_POST['order_id'] ?? $_POST['id'] ?? '');
    // Strip 'eg_' prefix if present
    $egirl_order_id = (int) preg_replace('/^eg_/i', '', $raw_id);

    if ($egirl_order_id <= 0) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order ID.']]);
        return;
    }

    global $db;
    $order = $db->row("SELECT id, status FROM egirl_orders WHERE id = ? LIMIT 1", $egirl_order_id);

    if (!$order || strtoupper((string)($order['status'] ?? '')) !== 'UNPAID') {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Only UNPAID E-Girl orders can be deleted.']]);
        return;
    }

    $db->run("DELETE FROM egirl_notifications WHERE data LIKE ?", '%"order_id":' . $egirl_order_id . '%');
    $db->run("DELETE FROM invoices WHERE order_id = ? AND order_type = 'egirl_session'", $egirl_order_id);
    $db->run("DELETE FROM egirl_orders WHERE id = ?", $egirl_order_id);

    log_admin_action(ADMIN_ID, 'Deleted E-Girl order #' . $egirl_order_id);

    echo json_encode([
        'sendToast' => ['type' => 'success', 'title' => 'Deleted', 'message' => 'E-Girl order #' . $egirl_order_id . ' deleted.'],
        'playSound' => 'success',
        'reload' => true,
    ]);
}

public function admin_unassign_booster()
{
    if (!$this->is_admin) return;

    $order_id = (int) esc($_POST['id'] ?? $_POST['order_id'] ?? 0);
    $order = $order_id > 0 ? db_get_row('orders', ['id' => $order_id]) : false;

    // Not for started orders
    if ($order == false || empty($order['booster_id']) || in_array(($order['status'] ?? ''), ['IN_PROGRESS', 'COMPLETED'], true)) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Order not found or booster cannot be unassigned in the current status.',
            ],
            'playSound' => 'error',
        ]);
        return;
    }

    $removed_booster_id = (int)($order['booster_id'] ?? 0);
    $this->block_booster_from_order_claim($order_id, $removed_booster_id, (defined('ADMIN_ID') ? (int)ADMIN_ID : null), 'Unassigned from order by admin');

    db_update_row('orders', ['id' => $order_id], [
        'booster_id' => null,
        'claimed_at' => null,
        'booster_cut' => null,
        'waiting_for_approval' => 0,
        'approval_requested_at' => null,
    ]);

    // Clear only the duo account IGN/PUUID so the next booster must set their own account.
    // last_match_id is intentionally kept so the next sync does not re-import old matches.
    // booster_ign_set_at is cleared so the new booster's set-time will be used as the tracking start.
    $existing_progress = db_get_row('order_progress', ['order_id' => $order_id], 1);
    if (!empty($existing_progress)) {
        global $db;
        // Ensure booster_ign_set_at column exists (added for duo-account time-range tracking)
        try { $db->run("ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {}
        $clearPayload = ['booster_ign' => null, 'booster_puuid' => null, 'booster_ign_set_at' => null];
        if (function_exists('riot_ensure_order_progress_duo_columns')) {
            riot_ensure_order_progress_duo_columns($db);
        }
        db_update_row('order_progress', ['order_id' => $order_id], $clearPayload);
    }

    log_admin_action(ADMIN_ID, 'Unassigned booster from order #' . $order_id);

    // The order is claimable again — refresh the booster panel and every open order view.
    if (function_exists('lb_realtime_emit_order')) {
        lb_realtime_emit_order('order_status_update', $order_id);
    }
    if (function_exists('lb_realtime_emit_new_order')) {
        lb_realtime_emit_new_order($order_id);
    }

        echo json_encode([
      'sendToast' => [
        'type' => 'success',
        'title' => 'Success',
        'message' => 'Booster unassigned successfully ✅',
      ],
      'playSound' => 'success',
      'redirectUrl' => ADMN_URL . '/order/' . $order_id,
]);
}

    public function admin_pause_order()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['id']);
            $order = db_get_row('orders', ['id' => $order_id]);
            if ($order != false) {
                $recipients = [];

                $booster = db_get_row('boosters', ['id' => $order['booster_id']]);
                $client = db_get_row('clients', ['id' => $order['client_id']]);

                if ($booster != false) {
                    if (!empty($booster['discord_id'])) { $recipients['booster'] = $booster['discord_id']; }
                }

                if ($client != false) {
                    if (!empty($client['discord_id'])) { $recipients['client'] = $client['discord_id']; }
                }

                if (in_array($order['status'], ['IN_PROGRESS', 'PAID'], true)) {
                    $pause_now = date('Y-m-d H:i:s');
                    $pause_update = ['status' => 'PAUSED'];
                    $pause_update = array_merge($pause_update, $this->duo_timer_stop_payload($order, $pause_now));
                    db_update_row('orders', ['id' => $order_id], $pause_update);

                    // Booster and client order views listen for order_status_update.
                    if (function_exists('lb_realtime_emit_order')) {
                        lb_realtime_emit_order('order_status_update', $order_id);
                        lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                    }

                    db_add_row('notifications', [
                        'type' => 'order_paused',
                        'data' => json_encode([
                            'order_id' => base64_encode($order_id),
                        ]),
                        'is_email' => true,
                        'is_discord' => false,
                        'recipient' => 'client',
                        'recipient_id' => $order['client_id'],
                    ]);

                    log_admin_action(ADMIN_ID, 'Paused order #' . $order['id']);

                    if (!empty($recipients)) {
                        $botToken = DS_BOT_TOKEN;

                        foreach ($recipients as $key => $recipient) {
                            $dmChannel = getDMChannelId($botToken, $recipient);

                            if ($key == 'booster') {
                                $order_url = BASE_URL . '/booster-area/order/' . $order['id'];
                            } else {
                                $order_url = BASE_URL . '/order/' . $order['id'];
                            }

                            $embed = null;
                            if ($dmChannel) {
                                $embed = [
                                    "title" => 'YOUR ORDER HAS BEEN PAUSED',
                                    "author" => [
                                        "name" => "LoLBoost.GG",
                                        "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                    ],
                                    "description" => "Your order #" . $order['id'] . " has been paused by admin! 🎉\n\nPlease check your dashboard for more details.\n",
                                    "footer" => [
                                        "text" => "LoLBoost.GG - Ranking up never been easier",
                                        "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                    ],
                                    "timestamp" => date('c'),
                                    "color" => 0x5865F2
                                ];
                            }

                            $components = [
                                [
                                    "type" => 1,
                                    "components" => [
                                        [
                                            "type" => 2,
                                            "style" => 5,
                                            "label" => "🔎 View Order",
                                            "url" => $order_url
                                        ]
                                    ]
                                ]
                            ];

                            if ($dmChannel && $embed !== null) {
                                $msg = json_encode([
                                    "embeds" => [$embed],
                                    "components" => $components
                                ], JSON_UNESCAPED_SLASHES);

                                sendEmbedDM($botToken, $dmChannel, $msg);
                            }
                        }
                    }

                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Order paused successfully 🎉'
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ));
                } else {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Order cannot be paused 😔'
                        ],
                        'playSound' => 'error',
                    ));
                }
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔'
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    public function admin_resume_order()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['id']);
            $order = db_get_row('orders', ['id' => $order_id]);

            if ($order != false) {

                // Optional: wenn nicht paused, dann nichts tun
                if ($order['status'] !== 'PAUSED') {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Order is not paused 😔'
                        ],
                        'playSound' => 'error',
                    ]);
                    return;
                }

                $hasBooster = (!empty($order['booster_id']) && (int) $order['booster_id'] > 0);
                $newStatus = $hasBooster ? 'IN_PROGRESS' : 'PAID';

                $resume_update = ['status' => $newStatus];
                if ($newStatus === 'IN_PROGRESS') {
                    $resume_update = array_merge($resume_update, $this->duo_timer_start_payload($order));
                } else {
                    $resume_update = array_merge($resume_update, $this->duo_timer_stop_payload($order));
                }
                db_update_row('orders', ['id' => $order_id], $resume_update);

                // Booster and client order views listen for order_status_update.
                if (function_exists('lb_realtime_emit_order')) {
                    lb_realtime_emit_order('order_status_update', $order_id);
                    lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                }

                $recipients = [];

                $booster = $hasBooster ? db_get_row('boosters', ['id' => $order['booster_id']]) : false;
                $client = db_get_row('clients', ['id' => $order['client_id']]);

                if ($hasBooster && $booster != false && !empty($booster['discord_id'])) {
                    if (!empty($booster['discord_id'])) { $recipients['booster'] = $booster['discord_id']; }
                }

                if ($client != false && !empty($client['discord_id'])) {
                    if (!empty($client['discord_id'])) { $recipients['client'] = $client['discord_id']; }
                }

                log_admin_action(ADMIN_ID, 'Resumed order #' . $order['id'] . ' -> ' . $newStatus);

                if (!empty($recipients)) {
                    $botToken = DS_BOT_TOKEN;

                    foreach ($recipients as $key => $recipient) {
                        $dmChannel = getDMChannelId($botToken, $recipient);

                        $order_url = ($key === 'booster')
                            ? BASE_URL . '/booster-area/order/' . $order['id']
                            : BASE_URL . '/order/' . $order['id'];

                        if ($dmChannel) {
                            $embed = [
                                "title" => 'YOUR ORDER HAS BEEN RESUMED',
                                "author" => [
                                    "name" => "LoLBoost.GG",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "description" => "Your order #" . $order['id'] . " has been resumed by admin! 🎉\n\nPlease check your dashboard for more details.\n",
                                "footer" => [
                                    "text" => "LoLBoost.GG - Ranking up never been easier",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "timestamp" => date('c'),
                                "color" => 0x5865F2
                            ];

                            $components = [
                                [
                                    "type" => 1,
                                    "components" => [
                                        [
                                            "type" => 2,
                                            "style" => 5,
                                            "label" => "🔎 View Order",
                                            "url" => $order_url
                                        ]
                                    ]
                                ]
                            ];

                            if ($dmChannel && $embed !== null) {
                                $msg = json_encode([
                                    "embeds" => [$embed],
                                    "components" => $components
                                ], JSON_UNESCAPED_SLASHES);

                                sendEmbedDM($botToken, $dmChannel, $msg);
                            }
                        }
                    }
                }

                $toastMessage = $hasBooster
                    ? 'Order resumed successfully 🎉'
                    : 'Order resumed — no booster assigned, status set to PAID ⚠️';

                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => $toastMessage
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
                return;

            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔'
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }
        }
    }

    /**
     * Returns context for the Progress Payment modal (form type + current order_options + pricing json keys).
     */
    public function admin_get_progress_payment_context()
    {
        if (!$this->is_admin) {
            return;
        }

        $order_id = (int) esc($_POST['order_id'] ?? $_POST['id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order ID.']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id]);
        if ($order == false) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        $options = db_get_row('order_options', ['order_id' => $order_id]);
        $form = db_get_row('boost_forms', ['id' => (int)$order['form_id']]);

        $pricing_json = null;
        $start_lp_options = [];
        $lp_gain_options = [];

        if ($form != false && !empty($form['uuid'])) {
            $pricing_json = get_pricing_json($form['uuid']);
            if (is_array($pricing_json)) {
                if (isset($pricing_json['start_lp']) && is_array($pricing_json['start_lp'])) {
                    $start_lp_options = array_keys($pricing_json['start_lp']);
                }
                if (isset($pricing_json['lp_gain']) && is_array($pricing_json['lp_gain'])) {
                    $lp_gain_options = array_keys($pricing_json['lp_gain']);
                }
            }
        }

        // Build a human-friendly goal label for the UI.
        $goal_label = '';
        $form_type = $form != false ? (string)$form['type'] : '';
        $form_id = (int)($order['form_id'] ?? 0);
        $game_key = $form != false ? (string)($form['game'] ?? '') : (string)($order['game'] ?? '');

        // Dynamic-game rank config (tier names, division counts, open-ended top tiers) so the
        // admin "Remove Booster" progress UI can show correct names/selects for non-LoL/VAL/TFT
        // games instead of always assuming LoL's tier list. Games without a config (LoL/VAL/TFT)
        // keep using their existing hardcoded frontend maps.
        $rank_config = null;

        // LoL Classic uses its own ladder and does not use LP bands.
        // Keep the values aligned with the Classic boost forms 30, 31 and 32:
        // 0 Unranked, 1 Salt, 2 Wood, 3 Silver, 4 Gold, 5 Platinum, 6 Diamond, 7 Legend.
        $is_lol_classic_rank = $form_type === 'rank'
            && (in_array($form_id, [30, 31, 32], true)
                || in_array(strtolower(trim($game_key)), ['lol_classic', 'lol-classic', 'league-of-legends-classic'], true));

        if ($is_lol_classic_rank) {
            $rank_config = [
                'ranks' => [
                    0 => 'Unranked',
                    1 => 'Salt',
                    2 => 'Wood',
                    3 => 'Silver',
                    4 => 'Gold',
                    5 => 'Platinum',
                    6 => 'Diamond',
                    7 => 'Legend',
                ],
                'rank_divs' => [
                    0 => 0,
                    1 => 4,
                    2 => 4,
                    3 => 4,
                    4 => 4,
                    5 => 4,
                    6 => 4,
                    7 => 0,
                ],
                'flat_tiers' => [0, 7],
                'is_lol_classic' => true,
            ];
        } elseif ($form_type === 'rank' && function_exists('lb_generic_game_rank_config')) {
            $cfg = lb_generic_game_rank_config($game_key);
            if ($cfg !== null) {
                if (is_array($pricing_json)) {
                    if (!empty($pricing_json['rank_names']) && is_array($pricing_json['rank_names'])) {
                        $cfg['ranks'] = $pricing_json['rank_names'];
                    }
                    if (!empty($pricing_json['rank_divs']) && is_array($pricing_json['rank_divs'])) {
                        $cfg['rank_divs'] = $pricing_json['rank_divs'];
                    }
                    if (isset($pricing_json['flat_tiers']) && is_array($pricing_json['flat_tiers'])) {
                        $cfg['flat_tiers'] = $pricing_json['flat_tiers'];
                    }
                    if (isset($pricing_json['start_max_tier'])) {
                        $cfg['start_max_tier'] = (int)$pricing_json['start_max_tier'];
                    }
                    if (isset($pricing_json['points_min_start'])) {
                        $cfg['points_min_start'] = $pricing_json['points_min_start'];
                    }
                    if (isset($pricing_json['points_max'])) {
                        $cfg['points_max'] = (int)$pricing_json['points_max'];
                    }
                    if (isset($pricing_json['points_step'])) {
                        $cfg['points_step'] = (int)$pricing_json['points_step'];
                    }
                }
                $rank_config = $cfg;
            }
        }
        if (is_array($options)) {
            if ($form_type === 'rank') {
                $goal_label = 'Tier ' . ($options['end_tier'] ?? '') . ' ' . ($options['end_division'] ?? '');
            } elseif (in_array($form_type, ['win', 'arena'], true)) {
                $goal_label = (int)($options['matches'] ?? 0) . ' Wins';
            } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true)) {
                $goal_label = (int)($options['matches'] ?? 0) . ' Games';
            } elseif ($form_type === 'coaching') {
                $goal_label = (int)($options['hours'] ?? 0) . ' Hours';
            } elseif ($form_type === 'pro-games' || $form_id === 26) {
                $goal_label = (int)($options['matches'] ?? 0) . ' Pro Games';
            } elseif ($form_type === 'duo-pass' || $form_id === 27) {
                $goal_label = (int)($options['hours'] ?? 0) . ' Hours Duo Pass';
            } elseif (in_array($form_type, ['mastery', 'level'], true)) {
                $goal_label = 'Level ' . (int)($options['end_tier'] ?? 0);
            }
        }

        // Purchased totals and (if available) current progress values.
        // These keys are used by the admin "remove booster (progress payment)" UI.
        $wins_purchased = 0;
        $matches_purchased = 0;
        $hours_purchased = 0;

        // Defaults: try to read already-stored progress from order_options if your codebase stores it.
        // If a key does not exist, it will safely fall back to 0.
        $wins_completed = 0;
        $matches_completed = 0;
        $hours_completed = 0;
        $reached_level = 0;

        if (is_array($options)) {
            if (in_array($form_type, ['win', 'arena'], true)) {
                $wins_purchased = (int)($options['matches'] ?? 0);
                $wins_completed = (int)($options['wins_completed'] ?? $options['wins_done'] ?? $options['completed_wins'] ?? 0);
            }
            if (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true) || $form_type === 'pro-games' || $form_id === 26) {
                $matches_purchased = (int)($options['matches'] ?? 0);
                $matches_completed = (int)($options['matches_completed'] ?? $options['games_completed'] ?? $options['completed_games'] ?? 0);
            }
            if ($form_type === 'coaching' || $form_type === 'duo-pass' || $form_id === 27) {
                $hours_purchased = (float)($options['hours'] ?? 0);
                $hours_completed = (float)($options['hours_completed'] ?? $options['completed_hours'] ?? 0);

                // Duo Pass: use the real timer sessions instead of manual order_options.
                if ($form_type === 'duo-pass' || $form_id === 27) {
                    $spent_seconds = max(0, (int)($order['duo_timer_spent_seconds'] ?? 0));
                    $started_at = trim((string)($order['duo_timer_started_at'] ?? ''));
                    $is_paused = (int)($order['is_paused'] ?? 0) === 1;
                    if (($order['status'] ?? '') === 'IN_PROGRESS' && !$is_paused && $started_at !== '' && $started_at !== '0000-00-00 00:00:00') {
                        $started_ts = strtotime($started_at);
                        if ($started_ts !== false) {
                            $spent_seconds += max(0, time() - $started_ts);
                        }
                    }
                    $hours_completed = $spent_seconds / 3600;
                    if ($hours_purchased > 0 && $hours_completed > $hours_purchased) {
                        $hours_completed = $hours_purchased;
                    }
                }
            }
            if (in_array($form_type, ['mastery', 'level'], true)) {
                $reached_level = (int)($options['reached_level'] ?? $options['current_level'] ?? $options['start_tier'] ?? 0);
            }
        }

        // Best-effort "progress_from" (used for auto progress-note in UI):
        // Use the last recorded segment's progress_to as the baseline.
        $progress_from_json = null;
        $progress_from_arr = [];
        $last_seg = db_get_rows('order_booster_segments', [
            'order_id' => $order_id,
            'order' => 'id,desc',
            'limit' => 1,
        ], true);
        if (!empty($last_seg) && !empty($last_seg[0]['progress_to'])) {
            $progress_from_json = $last_seg[0]['progress_to'];
            $decoded_pf = json_decode((string)$progress_from_json, true);
            $progress_from_arr = is_array($decoded_pf) ? $decoded_pf : [];
        }

        // Convenience "from" values for quantity-based forms
        $wins_from = (int)($progress_from_arr['wins_completed'] ?? 0);
        $matches_from = (int)($progress_from_arr['matches_completed'] ?? 0);
        $hours_from = (int)($progress_from_arr['hours_completed'] ?? 0);
        $level_from = (int)($progress_from_arr['reached_level'] ?? $reached_level ?? 0);


        echo json_encode([
            'success' => true,
            'order_id' => $order_id,
            'form_id' => (int)$order['form_id'],
            'form_type' => $form != false ? $form['type'] : null,
            'game' => $game_key,
            'rank_config' => $rank_config,
            'currency' => $order['currency'] ?? 'EUR',
            'currency_symbol' => util_currency_symbol($order['currency'] ?? 'EUR'),
            // cents in order currency (EUR or USD)
            'current_total_cents' => (int)($order['price'] ?? $order['price_eur'] ?? 0),
            // cents in EUR (used for payouts)
            'current_total_eur_cents' => (int)($order['price_eur'] ?? 0),
            'booster_cut' => $order['booster_cut'] !== null ? (int)$order['booster_cut'] : 0,
            'cut_percent' => $order['booster_cut'] !== null ? (float)$order['booster_cut'] : 0,
            // Keep both keys for backwards compatibility (some JS uses options, some uses order_options).
            'options' => $options != false ? $options : null,
            'order_options' => $options != false ? $options : null,
            'start_lp_options' => $start_lp_options,
            'lp_gain_options' => $lp_gain_options,
            'goal_label' => $goal_label,

            // Totals/progress for quantity-based forms.
            'wins_purchased' => $wins_purchased,
            'matches_purchased' => $matches_purchased,
            'hours_purchased' => $hours_purchased,
            'wins_completed' => $wins_completed,
            'matches_completed' => $matches_completed,
            'hours_completed' => $hours_completed,
            'reached_level' => $reached_level,

            // Baseline progress (previous segment) for auto-generated progress display
            'progress_from_json' => $progress_from_json,
            'progress_from' => $progress_from_arr,
            'wins_from' => $wins_from,
            'matches_from' => $matches_from,
            'hours_from' => $hours_from,
            'level_from' => $level_from,
            'duo_remaining_hours' => max(0, $hours_purchased - $hours_completed),
        ]);
    }

    /**
     * Calculate the new remaining total (discount/coins snapshot aware) based on progress.
     * Expects: order_id + progress (JSON string or array)
     */
    public function admin_calc_progress_payment_price()
    {
        if (!$this->is_admin) {
            return;
        }

        $order_id = (int) esc($_POST['order_id'] ?? $_POST['id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order ID.']);
            return;
        }

        $progress = $_POST['progress'] ?? $_POST['progress_to'] ?? [];
        if (!is_array($progress)) {
            $decoded = json_decode((string)$progress, true);
            $progress = is_array($decoded) ? $decoded : [];
        }

        $order = db_get_row('orders', ['id' => $order_id]);
        $currency = $order != false ? ($order['currency'] ?? 'EUR') : 'EUR';

        // Current totals in order currency cents. Prefer Price-JSON/current-options so the
        // preview uses the same base as the final remove-booster action.
        $current_total_order_cents = 0;
        $current_total_eur_cents = 0;
        if ($order != false) {
            $current_total_order_cents = (int)($order['price'] ?? 0);
            $current_total_eur_cents = (int)($order['price_eur'] ?? $current_total_order_cents);
            $computed_current = $this->calc_current_total_price_cents($order_id);
            if (is_array($computed_current) && ($computed_current['success'] ?? false) === true) {
                $current_total_order_cents = (int)($computed_current['order_cents'] ?? $current_total_order_cents);
                $current_total_eur_cents = (int)($computed_current['eur_cents'] ?? $current_total_eur_cents);
            }
            if ($current_total_order_cents === 0 && isset($order['price_eur'])) {
                $current_total_order_cents = (int)$order['price_eur'];
            }
            if ($current_total_eur_cents === 0) {
                $current_total_eur_cents = ($currency === 'EUR') ? $current_total_order_cents : (int)util_order_cents_to_eur_cents($order, $current_total_order_cents);
            }
        }

        // If the admin selects "no progress", keep the Price-JSON checked current price.
        $opts = db_get_row('order_options', ['order_id' => $order_id]);
        $is_no_progress = false;
        if (isset($progress['wins_completed'])) {
            $is_no_progress = ((int)$progress['wins_completed'] === 0);
        } elseif (isset($progress['matches_completed'])) {
            $is_no_progress = ((int)$progress['matches_completed'] === 0);
        } elseif (isset($progress['hours_completed'])) {
            $is_no_progress = ((int)$progress['hours_completed'] === 0);
        } elseif (isset($progress['reached_level']) && $opts != false) {
            $is_no_progress = ((int)$progress['reached_level'] === (int)($opts['start_tier'] ?? 0));
        } elseif (isset($progress['start_tier']) && $opts != false) {
            // Rank-like forms: progress payload updates the START fields.
            $keys = ['start_tier', 'start_division', 'start_lp', 'lp_gain', 'queue_type'];
            $is_no_progress = true;
            foreach ($keys as $k) {
                if (array_key_exists($k, $progress) && (string)$progress[$k] !== (string)($opts[$k] ?? '')) {
                    $is_no_progress = false;
                    break;
                }
            }
            // Optional full LP inputs for master+ tiers
            if ($is_no_progress && array_key_exists('start_lp_full', $progress)) {
                if ((string)$progress['start_lp_full'] !== (string)($opts['start_lp_full'] ?? '')) {
                    $is_no_progress = false;
                }
            }
        }

        if ($is_no_progress) {
            $new_total_order_cents = (int)$current_total_order_cents;
            $new_total_eur_cents = (int)$current_total_eur_cents;

            $new_total_order = number_format($new_total_order_cents / 100, 2, '.', '');
            $new_total_eur = number_format($new_total_eur_cents / 100, 2, '.', '');

            echo json_encode([
                'success' => true,
                'currency' => $currency,
                'currency_symbol' => util_currency_symbol($currency),
                // Order currency
                'new_total_cents' => (int)$new_total_order_cents,
                'new_total' => $new_total_order,
                // EUR (payout base)
                'new_total_eur_cents' => (int)$new_total_eur_cents,
                'new_total_eur' => $new_total_eur,
                // Backwards-compatible display keys
                'remaining_total_display' => $new_total_order,
                'remaining_total_display_eur' => $new_total_eur,
                'discount_code' => null,
                'discount_percent' => null,
                'coins_used' => 0,
                'meta' => ['no_progress' => true],
            ]);
            return;
        }

        $calc = $this->calc_remaining_total_price_cents($order_id, $progress);
        if ($calc['success'] !== true) {
            echo json_encode($calc);
            return;
        }

        // calc_remaining_total_price_cents returns EUR cents
        $new_total_eur_cents = (int)$calc['new_total_cents'];

        // Convert EUR cents to order currency cents using the live EUR->USD rate (matches website pricing display)
        $new_total_order_cents = $new_total_eur_cents;
        if ($currency != 'EUR') {
            $rate = (float)get_exchange_rate();
            if ($rate <= 0) {
                $rate = 1.0;
            }
            $new_total_order_cents = (int)round($new_total_eur_cents * $rate);
        }



        $new_total_order = number_format($new_total_order_cents / 100, 2, '.', '');
        $new_total_eur = number_format($new_total_eur_cents / 100, 2, '.', '');
        $meta = is_array($calc['meta'] ?? null) ? $calc['meta'] : [];

        echo json_encode([
            'success' => true,
            'currency' => $currency,
            'currency_symbol' => util_currency_symbol($currency),
            // Order currency
            'new_total_cents' => (int)$new_total_order_cents,
            'new_total' => $new_total_order,
            // EUR (payout base)
            'new_total_eur_cents' => (int)$new_total_eur_cents,
            'new_total_eur' => $new_total_eur,
            // Backwards-compatible display keys
            'remaining_total_display' => $new_total_order,
            'remaining_total_display_eur' => ((($currency ?? 'EUR') !== 'EUR') ? $new_total_order : $new_total_eur),
            'discount_code' => $meta['discount_code'] ?? null,
            'discount_percent' => $meta['discount_percent'] ?? null,
            'coins_used' => $meta['coins_used'] ?? 0,
            'meta' => $meta,
        ]);
    }

public function admin_remove_booster_from_order()
    {
        global $db;
        if (!$this->is_admin) {
            return;
        }

        $order_id = (int) esc($_POST['id'] ?? $_POST['order_id'] ?? 0);
        $new_total_price_input = trim((string)($_POST['new_total_price'] ?? ''));
        $progress_note = trim((string)($_POST['progress_note'] ?? ''));
        $progress_type = trim((string)($_POST['progress_type'] ?? 'custom'));

        // Optional: progress_to can be a JSON string or an array.
        $progress_to = null;
        if (isset($_POST['progress_to'])) {
            if (is_array($_POST['progress_to'])) {
                $progress_to = json_encode($_POST['progress_to'], JSON_UNESCAPED_SLASHES);
            } else {
                $tmp = trim((string)$_POST['progress_to']);
                $progress_to = $tmp !== '' ? $tmp : null;
            }
        }

        // Decode progress_to once (used for both manual and auto-calc)
        $progress_arr = [];
        if (!empty($progress_to)) {
            $decoded = json_decode((string)$progress_to, true);
            $progress_arr = is_array($decoded) ? $decoded : [];
        }

        // Current order options snapshot (used to update remaining options)
        $options = db_get_row('order_options', ['order_id' => $order_id]);


        if ($order_id <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid order ID.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id]);
        if ($order == false || $order['booster_id'] == null || $order['status'] != 'IN_PROGRESS') {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Order not found, no booster assigned, or order is not IN_PROGRESS.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $isMultiBoosterRemoval = in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true)
            && ((int)($order['form_id'] ?? 0) === 29 || max(1, (int)($options['boosters'] ?? 1)) > 1);
        $selectedBoosterId = (int)($_POST['ranked_5s_booster_id'] ?? 0);
        $booster_id = (int)$order['booster_id'];

        if ($isMultiBoosterRemoval) {
            if ($selectedBoosterId <= 0) {
                echo json_encode([
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select the booster to remove.'],
                    'playSound' => 'error',
                ]);
                return;
            }
            $membershipRows = $db->run(
                "SELECT id, booster_id
                   FROM order_boosters
                  WHERE order_id = ?
                    AND booster_id = ?
                    AND status = 'ACTIVE'
                  LIMIT 1",
                $order_id,
                $selectedBoosterId
            ) ?: [];
            if (empty($membershipRows)) {
                echo json_encode([
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'The selected booster is no longer assigned to this order.'],
                    'playSound' => 'error',
                ]);
                return;
            }
            $booster_id = $selectedBoosterId;
        }

        // Prevent this booster from claiming the same order again after an admin removed them.
        $this->block_booster_from_order_claim(
            $order_id,
            $booster_id,
            (defined('ADMIN_ID') ? (int)ADMIN_ID : null),
            'Removed from order by admin'
        );

        $booster = db_get_row('boosters', ['id' => $booster_id]);

        $old_price_eur = (int)($order['price_eur'] ?? 0); // cents in EUR (payout base)
        $old_price_order = (int)($order['price'] ?? $old_price_eur); // cents in order currency (USD or EUR)

        $cut_percent = $isMultiBoosterRemoval
            ? 50
            : ($order['booster_cut'] !== null ? (int)$order['booster_cut'] : 0); // snapshot
        $currency = $order['currency'] ?? 'EUR';

        // Best-effort progress_from: use the last segment progress_to.
        // No-progress means no new progress since this booster started, not always absolute 0.
        $progress_from = null;
        $progress_from_arr = [];
        $last_seg = db_get_rows('order_booster_segments', [
            'order_id' => $order_id,
            'order' => 'id,desc',
            'limit' => 1,
        ], true);
        if (!empty($last_seg) && !empty($last_seg[0]['progress_to'])) {
            $progress_from = $last_seg[0]['progress_to'];
            $decoded_pf = json_decode((string)$progress_from, true);
            $progress_from_arr = is_array($decoded_pf) ? $decoded_pf : [];
        }

        if (isset($progress_arr['wins']) && !isset($progress_arr['wins_completed'])) {
            $progress_arr['wins_completed'] = (int)$progress_arr['wins'];
        }
        if (isset($progress_arr['games_completed']) && !isset($progress_arr['matches_completed'])) {
            $progress_arr['matches_completed'] = (int)$progress_arr['games_completed'];
        }

        // Price-JSON/current-options cross-check: use the same base as auto progress calculation.
        // If the pricing JSON cannot be calculated, safely keep the stored order price.
        $computed_old = $this->calc_current_total_price_cents($order_id);
        if (is_array($computed_old) && ($computed_old['success'] ?? false) === true) {
            $old_price_eur = (int)($computed_old['eur_cents'] ?? $old_price_eur);
            $old_price_order = (int)($computed_old['order_cents'] ?? $old_price_order);
        }

        $progress_value_int = function ($arr, $key, $fallback = 0) {
            return is_array($arr) && array_key_exists($key, $arr) ? (int)$arr[$key] : (int)$fallback;
        };
        $progress_value_float = function ($arr, $key, $fallback = 0.0) {
            return is_array($arr) && array_key_exists($key, $arr) ? (float)$arr[$key] : (float)$fallback;
        };

        $is_no_progress = false;
        $allows_fine = false;
        if (isset($progress_arr['wins_completed'])) {
            $from = $progress_value_int($progress_from_arr, 'wins_completed', 0);
            $to = (int)$progress_arr['wins_completed'];
            $is_no_progress = ($to === $from);
            $allows_fine = ($to < $from || $to < 0);
        } elseif (isset($progress_arr['matches_completed'])) {
            $from = $progress_value_int($progress_from_arr, 'matches_completed', 0);
            $to = (int)$progress_arr['matches_completed'];
            $is_no_progress = ($to === $from);
            $allows_fine = ($to < $from);
        } elseif (isset($progress_arr['hours_completed'])) {
            $from = $progress_value_int($progress_from_arr, 'hours_completed', 0);
            $to = (int)$progress_arr['hours_completed'];
            $is_no_progress = ($to === $from);
            $allows_fine = ($to < $from);
        } elseif (isset($progress_arr['remaining_hours'])) {
            $hours_purchased = $options != false ? (float)($options['hours'] ?? 0) : 0.0;
            $from_remaining = $progress_value_float($progress_from_arr, 'remaining_hours', $hours_purchased);
            $to_remaining = (float)$progress_arr['remaining_hours'];
            $is_no_progress = (abs($to_remaining - $from_remaining) < 0.00001);
            $allows_fine = ($to_remaining > $from_remaining + 0.00001);
        } elseif (isset($progress_arr['reached_level'])) {
            $from = $progress_value_int($progress_from_arr, 'reached_level', ($options['start_tier'] ?? 0));
            $to = (int)$progress_arr['reached_level'];
            $is_no_progress = ($to === $from);
            $allows_fine = ($to < $from);
        } elseif (isset($progress_arr['start_tier']) && $options != false) {
            $baseline = !empty($progress_from_arr) ? $progress_from_arr : $options;
            $keys = ['start_tier', 'start_division', 'start_lp', 'lp_gain', 'queue_type', 'start_lp_full'];
            $is_no_progress = true;
            foreach ($keys as $k) {
                if (array_key_exists($k, $progress_arr) && (string)$progress_arr[$k] !== (string)($baseline[$k] ?? '')) {
                    $is_no_progress = false;
                    break;
                }
            }
            $to_score = ((int)($progress_arr['start_tier'] ?? 0) * 100000) + ((int)($progress_arr['start_division'] ?? ($baseline['start_division'] ?? 0)) * 10000) + (int)($progress_arr['start_lp_full'] ?? 0);
            $from_score = ((int)($baseline['start_tier'] ?? 0) * 100000) + ((int)($baseline['start_division'] ?? 0) * 10000) + (int)($baseline['start_lp_full'] ?? 0);
            $allows_fine = ($to_score < $from_score);
        }

        // Manual admin override is allowed only when the UI explicitly sends manual_price_override=1.
        // This keeps normal prefilled/calc values protected from stale visible input, while allowing admins
        // to enter the exact remaining order price when the automatic progress calculation is not suitable.
        $manual_override = (($_POST['manual_price_override'] ?? '') === '1');
        if ($manual_override) {
            if ($new_total_price_input === '') {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please enter the new total price or use Calculate price.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            $normalized_manual_price = str_replace([' ', ','], ['', '.'], $new_total_price_input);
            if (!is_numeric($normalized_manual_price)) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Manual new total price is invalid.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            $manual_float = (float)$normalized_manual_price;
            if ($manual_float < 0) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Manual new total price cannot be negative.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            // Safety cap: do not allow accidental 100x values. Regression/fine is still possible up to 3x old price.
            $manual_cents_tmp = (int)util_format_price_db($manual_float);
            if ($old_price_order > 0 && $manual_cents_tmp > ($old_price_order * 3)) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Manual new total price is too high. Please check the amount.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            $new_price_order = $manual_cents_tmp;
            $new_price_eur = $new_price_order;
            if ($currency != 'EUR') {
                $rate = (float)get_exchange_rate();
                if ($rate <= 0) { $rate = 1.0; }
                $new_price_eur = (int)round($new_price_order / $rate);
            }
        } elseif ($is_no_progress) {
            // Hard guard: zero progress must never create a payout or fine.
            $new_price_eur = (int)$old_price_eur;
            $new_price_order = (int)$old_price_order;
        } else {
            $calc = $this->calc_remaining_total_price_cents($order_id, $progress_arr);
            if ($calc['success'] !== true) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Auto-calc failed. Please enter the new total price manually.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }
            $new_price_eur = (int)$calc['new_total_cents'];
            $new_price_order = $new_price_eur;
            if ($currency != 'EUR') {
                $rate = (float)get_exchange_rate();
                if ($rate <= 0) { $rate = 1.0; }
                $new_price_order = (int)round($new_price_eur * $rate);
            }

            // Normal progress must never become a fine because of pricing drift.
            // Explicit regression/negative progress can still create a fine.
            if (!$allows_fine && $new_price_eur > $old_price_eur) {
                $new_price_eur = (int)$old_price_eur;
                $new_price_order = (int)$old_price_order;
            }
        }

        if ($new_price_order < 0) $new_price_order = 0;
        if ($new_price_eur < 0) $new_price_eur = 0;

        // Price delta in EUR (new - old). Negative = progress payment (price decreased), Positive = fine (price increased).
        $price_delta_eur = $new_price_eur - $old_price_eur; // cents

        // For transfers (price decreased), segment_value is positive.
        // For fines (price increased), segment_value is negative.
        $segment_value = -$price_delta_eur; // cents

        // Payout delta for the outgoing booster (can be negative for fines)
        $payout = (int) round($segment_value * $cut_percent / 100);
        if ($isMultiBoosterRemoval) {
            $teamSize = max(1, min(4, (int)($options['boosters'] ?? 1)));
            $payout = (int)floor($payout / $teamSize);
        }

        // Decide payment type
        $payment_type = $payout >= 0 ? 'progress_payment' : 'progress_payment_fine';

        // Best-effort progress_from: use the last segment progress_to
        $progress_from = null;
        $last_seg = db_get_rows('order_booster_segments', [
            'order_id' => $order_id,
            'order' => 'id,desc',
            'limit' => 1,
        ], true);
        if (!empty($last_seg) && !empty($last_seg[0]['progress_to'])) {
            $progress_from = $last_seg[0]['progress_to'];
        }

        // ------------------------------------------------------------------
        // Auto-generate a progress note if none was provided (prevents "-" in admin tables)
        // Supports win/match/placement/normal/clash, coaching, level/mastery, rank
        // ------------------------------------------------------------------
        if ($progress_note === '') {
            $form = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)]);
            $form_type = $form != false ? (string)$form['type'] : '';

            $pf_arr = [];
            if (!empty($progress_from)) {
                $tmp = json_decode((string)$progress_from, true);
                $pf_arr = is_array($tmp) ? $tmp : [];
            }
            $pt_arr = is_array($progress_arr) ? $progress_arr : [];

            $format_delta = function ($from, $to) {
                $d = (int)$to - (int)$from;
                return ($d >= 0 ? '+' : '') . (string)$d;
            };

            // Rank label helpers (best effort)
            $tier_name = function ($t) {
                $n = (int)$t;
                $map = [
                    1 => 'Iron',
                    2 => 'Bronze',
                    3 => 'Silver',
                    4 => 'Gold',
                    5 => 'Platinum',
                    6 => 'Emerald',
                    7 => 'Diamond',
                    8 => 'Master',
                    9 => 'Grandmaster',
                    10 => 'Challenger',
                ];
                return $map[$n] ?? ($n ? (string)$n : '');
            };
            $div_roman = function ($d) {
                $n = (int)$d;
                $map = [1 => 'I', 2 => 'II', 3 => 'III', 4 => 'IV'];
                return $map[$n] ?? ($n ? (string)$n : '');
            };
            $rank_label = function ($arr) use ($tier_name, $div_roman) {
                if (!is_array($arr)) return '';
                $t = (int)($arr['start_tier'] ?? 0);
                $is_apex = ($t > 7 || $t === 0);
                if ($is_apex) {
                    $lp_full = (int)($arr['start_lp_full'] ?? 0);
                    $base = trim($tier_name($t));
                    return $base !== '' ? trim($base . ' ' . $lp_full . ' LP') : '';
                }
                $d = (int)($arr['start_division'] ?? 0);
                $lp = trim((string)($arr['start_lp'] ?? ''));
                $base = trim($tier_name($t) . ' ' . $div_roman($d));
                return $lp !== '' ? trim($base . ' (' . $lp . ' LP)') : $base;
            };

            if (in_array($form_type, ['win', 'arena'], true)) {
                $from = (int)($pf_arr['wins_completed'] ?? 0);
                $to = (int)($pt_arr['wins_completed'] ?? 0);
                $progress_note = 'Wins ' . $from . ' → ' . $to . ' (' . $format_delta($from, $to) . ')';
            } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true) || $form_type === 'pro-games' || (int)($order['form_id'] ?? 0) === 26) {
                $from = (int)($pf_arr['matches_completed'] ?? 0);
                $to = (int)($pt_arr['matches_completed'] ?? 0);
                $progress_note = 'Games ' . $from . ' → ' . $to . ' (' . $format_delta($from, $to) . ')';
            } elseif ($form_type === 'duo-pass' || (int)($order['form_id'] ?? 0) === 27) {
                $total = (float)($options['hours'] ?? 0);
                $remaining = isset($pt_arr['remaining_hours']) ? (float)$pt_arr['remaining_hours'] : max(0, $total - (float)($pt_arr['hours_completed'] ?? 0));
                $completed = max(0, $total - $remaining);
                $progress_note = 'Duo Pass ' . number_format($completed, 2, '.', '') . 'h done, ' . number_format($remaining, 2, '.', '') . 'h remaining';
            } elseif ($form_type === 'coaching') {
                $from = (int)($pf_arr['hours_completed'] ?? 0);
                $to = (int)($pt_arr['hours_completed'] ?? 0);
                $progress_note = 'Hours ' . $from . ' → ' . $to . ' (' . $format_delta($from, $to) . ')';
            } elseif (in_array($form_type, ['mastery', 'level'], true)) {
                // For level-like forms we store reached_level in progress_to
                $from = (int)($pf_arr['reached_level'] ?? ($options['reached_level'] ?? $options['start_tier'] ?? 0));
                $to = (int)($pt_arr['reached_level'] ?? 0);
                $progress_note = 'Level ' . $from . ' → ' . $to . ' (' . $format_delta($from, $to) . ')';
            } elseif ($form_type === 'rank') {
                // For rank forms, progress_to updates the START fields (reached rank)
                $from_lbl = $rank_label(!empty($pf_arr) ? $pf_arr : (is_array($options) ? $options : []));
                $to_lbl = $rank_label($pt_arr);
                if ($from_lbl !== '' || $to_lbl !== '') {
                    $progress_note = trim($from_lbl . ' → ' . $to_lbl);
                }
            }
        }

        $current_timestamp = date('Y-m-d H:i:s');

        // Log action
        $log_msg = 'Removed booster #' . $booster_id . ' from order #' . $order_id;
        $log_msg .= ' | price: €' . number_format($old_price_eur / 100, 2, '.', '') . ' -> €' . number_format($new_price_eur / 100, 2, '.', '');
        $log_msg .= ' | delta: €' . number_format($price_delta_eur / 100, 2, '.', '') . ' | cut: ' . $cut_percent . '% | booster delta: €' . number_format($payout / 100, 2, '.', '');
        $action_log_id = log_admin_action(ADMIN_ID, $log_msg);

        // Save segment (transfer or fine). Note: to support fines, segment_value_eur / payout_eur must allow negative values.
        db_add_row('order_booster_segments', [
            'order_id' => $order_id,
            'booster_id' => $booster_id,
            'form_id' => isset($order['form_id']) ? (int) $order['form_id'] : null,
            'cut_percent' => $cut_percent,
            'segment_value_eur' => $segment_value,
            'payout_eur' => $payout,
            'progress_type' => $progress_type !== '' ? $progress_type : 'custom',
            'progress_from' => $progress_from,
            'progress_to' => $progress_to,
            'progress_note' => $progress_note !== '' ? $progress_note : null,
            'admin_id' => ADMIN_ID,
            'admin_log_id' => $action_log_id,
            'created_at' => $current_timestamp,
        ]);

        // Update booster balance + create booster_payments row (positive = payout, negative = fine)
        if ($payout != 0 && $booster != false) {
            $old_balance = (int) $booster['balance'];
            $new_balance = $old_balance + $payout; // payout can be negative

            db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance]);

            db_add_row('booster_payments', [
                'booster_id' => $booster_id,
                'type' => $payment_type,
                'note' => (string) $order_id,
                'amount' => $payout,
                'currency' => 'EUR',
                'sender' => ADMIN_DATA['username'],
                'sender_type' => 'admin',
                'sender_id' => ADMIN_ID,
                'balance_update' => $old_balance . '|' . $new_balance,
                'created_at' => $current_timestamp,
            ]);
        }

        $remainingTeamBoosters = [];
        if ($isMultiBoosterRemoval) {
            try {
                $db->run(
                    "UPDATE order_boosters
                        SET status = 'REMOVED',
                            slot_no = 1000000 + id,
                            role = CONCAT('Removed', id, '_', UNIX_TIMESTAMP()),
                            updated_at = ?
                      WHERE order_id = ? AND booster_id = ? AND status = 'ACTIVE'",
                    $current_timestamp,
                    $order_id,
                    $booster_id
                );
            } catch (Throwable $e) {
                $db->run(
                    "DELETE FROM order_boosters WHERE order_id = ? AND booster_id = ? AND status = 'ACTIVE'",
                    $order_id,
                    $booster_id
                );
            }
            $remainingTeamBoosters = $db->run(
                "SELECT booster_id, claimed_at
                   FROM order_boosters
                  WHERE order_id = ? AND status = 'ACTIVE'
                  ORDER BY slot_no ASC, id ASC",
                $order_id
            ) ?: [];
        }

        // Update the order: reduce price and either keep the remaining team or reopen it.
        $remove_update = [
            'price_eur' => $new_price_eur,
            'price' => $new_price_order,
            'waiting_for_approval' => 0,
            'approval_requested_at' => null,
            'paid_at' => $current_timestamp,
        ];
        if ($isMultiBoosterRemoval && !empty($remainingTeamBoosters)) {
            $replacement = $remainingTeamBoosters[0];
            $remove_update['booster_id'] = (int)$replacement['booster_id'];
            $remove_update['status'] = 'IN_PROGRESS';
            $remove_update['booster_cut'] = 50;
            $remove_update['claimed_at'] = $replacement['claimed_at'] ?? $order['claimed_at'];
        } else {
            $remove_update['booster_id'] = null;
            $remove_update['status'] = 'PAID';
            $remove_update['booster_cut'] = null;
            $remove_update['claimed_at'] = null;
            $remove_update = array_merge($remove_update, $this->duo_timer_stop_payload($order, $current_timestamp));
        }
        db_update_row('orders', ['id' => $order_id], $remove_update);

        // Clear only duo account IGN/PUUID when booster is removed.
        // last_match_id is kept so the next booster's sync doesn't re-import old matches.
        // booster_ign_set_at is cleared so the new booster's set-time becomes the new tracking start.
        $existing_progress = db_get_row('order_progress', ['order_id' => $order_id], 1);
        if (!empty($existing_progress) && (!$isMultiBoosterRemoval || empty($remainingTeamBoosters))) {
            try { $db->run("ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {}
            $clearPayload = ['booster_ign' => null, 'booster_puuid' => null, 'booster_ign_set_at' => null];
            if (function_exists('riot_ensure_order_progress_duo_columns')) {
                riot_ensure_order_progress_duo_columns($db);
            }
            db_update_row('order_progress', ['order_id' => $order_id], $clearPayload);
        }

        // Do NOT create a separate partial addon_payment here.
        // $segment_value is calculated from old price - new remaining price; for add-on orders,
        // that completed segment already contains the proportional add-on share.
        // Creating another addon_payment here would double-pay the outgoing booster.

        
        // Update remaining order options based on progress_to (so the next booster starts from the reached point)
        // NOTE: We intentionally ignore LB coins for this calculation (order price stays the same regardless of coins).
        if ($options != false && is_array($progress_arr) && !empty($progress_arr)) {
            $form = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)]);
            $form_type = $form != false ? (string)$form['type'] : '';

            $updates = [];

            
            // Rank boost / Rank-like forms: move the start point forward to what the booster reached.
            // Payload may come in different shapes depending on UI:
            // - rank auto-calc sends: start_tier/start_division/start_lp (band) or start_lp_full (integer LP for apex)
            // - older versions may send: reached_tier/reached_division/reached_lp_band
            if ($form_type === 'rank') {
                $tier = null;
                if (isset($progress_arr['reached_tier'])) $tier = (int)$progress_arr['reached_tier'];
                if ($tier === null && isset($progress_arr['start_tier'])) $tier = (int)$progress_arr['start_tier'];

                $division = null;
                if (isset($progress_arr['reached_division'])) $division = self::normalize_lol_division($progress_arr['reached_division']);
                if ($division === null && isset($progress_arr['start_division'])) $division = self::normalize_lol_division($progress_arr['start_division']);

                $lp_band = null;
                if (isset($progress_arr['reached_lp_band'])) $lp_band = (string)$progress_arr['reached_lp_band'];
                if (($lp_band === null || $lp_band === '') && isset($progress_arr['start_lp'])) $lp_band = (string)$progress_arr['start_lp'];

                $lp_full = null;
                if (isset($progress_arr['start_lp_full'])) $lp_full = (int)$progress_arr['start_lp_full'];

                $lp_gain = null;
                if (isset($progress_arr['lp_gain'])) $lp_gain = (string)$progress_arr['lp_gain'];

                if ($tier !== null) {
                    $updates['start_tier'] = (int)$tier;
                }
                if ($division !== null) {
                    $updates['start_division'] = (int)$division;
                }

                // start_lp is used as LP band for normal tiers. For apex tiers, store the numeric LP value as string.
                if ($lp_full !== null) {
                    $updates['start_lp'] = (string)$lp_full;
                } elseif ($lp_band !== null && $lp_band !== '') {
                    $updates['start_lp'] = (string)$lp_band;
                }

                if ($lp_gain !== null && $lp_gain !== '') {
                    $updates['lp_gain'] = (string)$lp_gain;
                }
            }

            // Quantity-based forms: adjust remaining count based on progress.

            // Win-like (Win Boost, Arena Boost): wins stored in `matches`.
            if (in_array($form_type, ['win', 'arena'], true)) {
                $completed = (int)($progress_arr['wins_completed'] ?? 0);
                $total = (int)($options['matches'] ?? 0);
                $remaining = $completed < 0 ? ($total + abs($completed)) : ($total - $completed);
                if ($remaining < 0) $remaining = 0;
                $updates['matches'] = $remaining;
            }

            // Match-like (Matches / Placements / Normals / Clash): games stored in `matches`.
            if (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true) || $form_type === 'pro-games' || (int)($order['form_id'] ?? 0) === 26) {
                $completed = (int)($progress_arr['matches_completed'] ?? 0);
                $total = (int)($options['matches'] ?? 0);
                $remaining = $completed < 0 ? ($total + abs($completed)) : ($total - $completed);
                if ($remaining < 0) $remaining = 0;
                $updates['matches'] = $remaining;
            }

            // Duo Pass: remaining hours are entered directly.
            if ($form_type === 'duo-pass' || (int)($order['form_id'] ?? 0) === 27) {
                $total = (float)($options['hours'] ?? 0);
                if (isset($progress_arr['remaining_hours'])) {
                    $remaining = (float)$progress_arr['remaining_hours'];
                } else {
                    $completed = (float)($progress_arr['hours_completed'] ?? 0);
                    $remaining = $completed < 0 ? ($total + abs($completed)) : ($total - $completed);
                }
                if ($remaining < 0) $remaining = 0;
                if ($total > 0 && $remaining > $total) $remaining = $total;
                $updates['hours'] = $remaining;
            }

            // Coaching: remaining hours.
            if ($form_type === 'coaching') {
                $completed = (int)($progress_arr['hours_completed'] ?? 0);
                $total = (int)($options['hours'] ?? 0);
                $remaining = $completed < 0 ? ($total + abs($completed)) : ($total - $completed);
                if ($remaining < 0) $remaining = 0;
                $updates['hours'] = $remaining;
            }

// Mastery/Level: move start level forward (remaining is recalculated on the next booster).
            if (in_array($form_type, ['mastery', 'level'], true)) {
                $reached = null;
                if (isset($progress_arr['reached_level'])) $reached = (int)$progress_arr['reached_level'];
                if ($reached === null && isset($progress_arr['reached_tier'])) $reached = (int)$progress_arr['reached_tier'];
                if ($reached !== null) {
                    $updates['start_tier'] = $reached;
                }
            }

            if (!empty($updates)) {
                db_update_row('order_options', ['order_id' => (int)$order_id], $updates);
            }
        }

        // System chat message to customer
        $booster_name = $booster != false ? $booster['username'] : 'A booster';

        // Web notifications for removal
        db_add_row('notifications', [
            'type' => 'booster_removed',
            'recipient' => 'client',
            'recipient_id' => (int)$order['client_id'],
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'booster_username' => base64_encode((string)$booster_name),
                'booster_id' => base64_encode((string)$booster_id),
            ]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);

        db_add_row('notifications', [
            'type' => 'booster_removed',
            'recipient' => 'booster',
            'recipient_id' => (int)$booster_id,
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
            ]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);

        $chat_data = [
            'message' => 'Booster ' . $booster_name . " was removed from your order.\n\nA new booster will be assigned shortly.\n\nIf you have any questions, our live chat is available anytime! 💬",
            'message_type' => 'text',
        ];

        $user = [
            'id' => '999',
            'username' => 'System',
            'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png'
        ];

        chat_insert_message($order_id, $chat_data, $user, 'system');

        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit_order('chat_update', $order_id);
            lb_realtime_emit_order('order_status_update', $order_id);
            if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => $payout < 0
                    ? 'Booster removed. Fine and segment were recorded.'
                    : 'Booster removed. Transfer segment and payout were recorded.',
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);

        // Everything below is a courtesy DM to the removed booster: two sequential
        // calls to the Discord API. From shared hosting those regularly take several
        // seconds, and they used to run BEFORE the response — which is why "Remove
        // Booster" appeared frozen for 5-10 seconds even though the order itself was
        // already updated within a few hundred milliseconds.
        // The admin now gets the answer first; the DM still goes out afterwards.
        if (function_exists('lb_finish_request_early')) {
            lb_finish_request_early();
        }

        if ($booster != false && !empty($booster['discord_id'])) {
            $botToken = DS_BOT_TOKEN;
            $discordUserId = $booster['discord_id'];
            $dmChannel = getDMChannelId($botToken, $discordUserId);

            $orderUrl = BASE_URL . '/booster-area/order/' . $order['id'];

            if ($dmChannel) {
                $embed = [
                    'title' => 'YOU HAVE BEEN REMOVED FROM AN ORDER',
                    'author' => [
                        'name' => 'LoLBoost.GG',
                        'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'
                    ],
                    'description' => 'You have been removed from order #' . $order['id'] . ".\n\nPlease check your dashboard for more details.\n",
                    'footer' => [
                        'text' => 'LoLBoost.GG - Ranking up never been easier',
                        'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'
                    ],
                    'timestamp' => date('c'),
                    'color' => 0x5865F2
                ];

                $components = [
                    [
                        'type' => 1,
                        'components' => [
                            [
                                'type' => 2,
                                'style' => 5,
                                'label' => '🔎 View Order',
                                'url' => $orderUrl
                            ]
                        ]
                    ]
                ];

                $msg = json_encode([
                    'embeds' => [$embed],
                    'components' => $components
                ], JSON_UNESCAPED_SLASHES);

                sendEmbedDM($botToken, $dmChannel, $msg);
            }
        }
    }

    /**
     * Internal helper used by Progress Payment features.
     * Returns: ['success'=>bool, 'new_total_cents'=>int, 'meta'=>array]
     */

    /**
     * Calculates the CURRENT total price (in EUR cents + order-currency cents) from the pricing JSON
     * using the current order_options (i.e. the edited scope), and applies the latest order-invoice
     * discount snapshot. Coins are intentionally ignored (same as progress calculations).
     *
     * This is used for Progress Payment / Remove Booster so payouts stay correct even if
     * orders.price/price_eur are kept as "original paid" values.
     */
    private function calc_current_total_price_cents($order_id, $options_override = null, $form_id_override = null, $include_paid_addons = true)
    {
        $order = db_get_row('orders', ['id' => (int)$order_id]);
        if ($order == false) {
            return ['success' => false, 'message' => 'Order not found.'];
        }

        $options = is_array($options_override)
            ? $options_override
            : db_get_row('order_options', ['order_id' => (int)$order_id]);
        if ($options == false) {
            return ['success' => false, 'message' => 'Order options not found.'];
        }

        $effective_form_id = $form_id_override !== null ? (int)$form_id_override : (int)$order['form_id'];
        $form = db_get_row('boost_forms', ['id' => $effective_form_id]);
        if ($form == false) {
            return ['success' => false, 'message' => 'Boost form not found.'];
        }

        $form_type = (string)($form['type'] ?? '');
        $form_id = $effective_form_id;

        // Duo Pass is sold by time and its customer price is stored on the order/invoice.
        // Do NOT recalculate it via calculate_boost_pricing here, because that pricing path
        // needs selected_booster_id and returns 0 after the booster is removed or not present.
        if ($form_type === 'duo-pass' || $form_id === 27) {
            $eur_cents = (int)($order['price_eur'] ?? 0);
            $order_cents = (int)($order['price'] ?? $eur_cents);

            if ($eur_cents <= 0) {
                $inv_rows = db_get_rows('invoices', [
                    'order_type' => 'order',
                    'order_id' => (int)$order_id,
                    'status' => 'PAID',
                    'order' => 'id,desc',
                    'limit' => 1,
                ], true);
                if (!empty($inv_rows)) {
                    $inv = $inv_rows[0];
                    $eur_cents = (int)($inv['price_eur'] ?? $inv['total_price'] ?? $inv['price'] ?? 0);
                    if ($order_cents <= 0) {
                        $order_cents = (int)($inv['total_price'] ?? $inv['price'] ?? $eur_cents);
                    }
                }
            }

            if ($eur_cents <= 0 && $order_cents > 0) {
                $currency = $order['currency'] ?? 'EUR';
                if ($currency !== 'EUR' && function_exists('util_order_cents_to_eur_cents')) {
                    $eur_cents = (int)util_order_cents_to_eur_cents($order, $order_cents);
                } else {
                    $eur_cents = $order_cents;
                }
            }
            if ($order_cents <= 0) {
                $order_cents = $eur_cents;
            }

            return [
                'success' => true,
                'eur_cents' => max(0, (int)$eur_cents),
                'order_cents' => max(0, (int)$order_cents),
                'meta' => ['pricing_mode' => 'duo_pass_stored_current_total'],
            ];
        }

        if (empty($form['uuid'])) {
            return ['success' => false, 'message' => 'Boost form pricing UUID not found.'];
        }

        $pricing_json = get_pricing_json($form['uuid']);
        if (!is_array($pricing_json)) {
            return ['success' => false, 'message' => 'Pricing JSON not found.'];
        }

        // Latest invoice snapshot (discount/coins)
        $invoice = null;
        $inv_rows = db_get_rows('invoices', [
            'order_type' => 'order',
            'order_id' => (int)$order_id,
            'order' => 'id,desc',
            'limit' => 1,
        ], true);
        if (!empty($inv_rows)) {
            $invoice = $inv_rows[0];
        }

        $post_data = $options;
        $post_data['form_id'] = $effective_form_id;
        // Keep the full option set (solo/duo, play-with-booster, bonus win, etc.) in the pricing calc.
        // If your codebase bills post-purchase add-ons via separate addon invoices, those are added below.
        $addon_keys = [];

$calc = calculate_boost_pricing($pricing_json, $post_data);
        if (!is_array($calc)) {
            return ['success' => false, 'message' => 'Pricing calculation failed.'];
        }

        // Prefer EUR price (index 2)
        $raw_price = null;
        if (isset($calc[2])) {
            $raw_price = $calc[2];
        } elseif (isset($calc['price_eur'])) {
            $raw_price = $calc['price_eur'];
        } elseif (isset($calc[0])) {
            $raw_price = $calc[0];
        }

        if ($raw_price === null || $raw_price === '') {
            return ['success' => false, 'message' => 'Pricing calculation failed.'];
        }

        // Normalize to cents
        $base_total_cents = 0;
        if (is_string($raw_price)) {
            $rp = str_replace(',', '.', $raw_price);
            if (strpos($rp, '.') !== false) {
                $base_total_cents = (int) round(((float)$rp) * 100);
            } else {
                $base_total_cents = (int) $rp;
            }
        } elseif (is_float($raw_price)) {
            if (abs($raw_price - floor($raw_price)) > 0.00001) {
                $base_total_cents = (int) round($raw_price * 100);
            } else {
                $base_total_cents = (int) $raw_price;
            }
        } else {
            $base_total_cents = (int) $raw_price;
        }

        // Same heuristic scaling as the remaining-calc.
        $scale_ref = 0;
        if ($invoice && isset($invoice['price_eur']) && (int)$invoice['price_eur'] > 0) {
            $scale_ref = (int)$invoice['price_eur'];
        } elseif (isset($order['price_eur']) && (int)$order['price_eur'] > 0) {
            $scale_ref = (int)$order['price_eur'];
        }
        if ($scale_ref > 0 && $base_total_cents > ($scale_ref * 20)) {
            $base_total_cents = (int) round($base_total_cents / 100);
        }

        // Apply invoice discount snapshot (coins intentionally ignored)
        $discounted_cents = $base_total_cents;
        $discount_code = null;
        $discount_percent = null;

        if ($invoice && isset($invoice['price']) && (int)$invoice['price'] > 0) {
            if (!empty($invoice['discount_id']) && isset($invoice['discount_amount']) && (int)$invoice['discount_amount'] !== 0) {
                $discount_row = db_get_row('discounts', ['id' => (int)$invoice['discount_id']]);
                if ($discount_row != false && !empty($discount_row['code'])) {
                    $discount_code = (string)$discount_row['code'];
                }

                $discount_percent = round((abs((int)$invoice['discount_amount']) / max(1, (int)$invoice['price'])) * 100, 2);

                if ($discount_row != false && (int)$discount_row['is_fixed'] === 1) {
                    $discounted_cents = $base_total_cents + (int)$invoice['discount_amount']; // discount_amount is negative
                } else {
                    $pct = abs((int)$invoice['discount_amount']) / (int)$invoice['price'];
                    if ($pct > 1) $pct = 1;
                    $discounted_cents = (int)round($base_total_cents * (1 - $pct));
                }
            }
        }

        if ($discounted_cents < 0) {
            $discounted_cents = 0;
        }
        // Add PAID addon invoices (addons are paid separately and should be reflected in the current total).
        // We add them AFTER applying the base-order discount snapshot, because discounts typically apply to the base order only.
        $addon_paid_cents_eur = 0;
        $addon_invoices = $include_paid_addons ? db_get_rows('invoices', [
            'order_type' => 'addon',
            'order_id' => (int)$order_id,
            'status' => 'PAID',
        ], true) : [];
        if (!empty($addon_invoices)) {
            foreach ($addon_invoices as $ai) {
                
                // Avoid double-counting Duo / Play With Booster if it's already included in base pricing (is_duo=1)
                $pwb_enabled = isset($options['is_duo']) && (int)$options['is_duo'] === 1;
                if ($pwb_enabled) {
                    $haystack = strtolower(json_encode($ai));
                    if (strpos($haystack, 'duo') !== false || strpos($haystack, 'play with booster') !== false || strpos($haystack, 'play_with_booster') !== false) {
                        continue;
                    }
                }
if (isset($ai['price_eur'])) {
                    $addon_paid_cents_eur += (int)$ai['price_eur'];
                } elseif (isset($ai['total_price'])) {
                    // fallback (currency assumed EUR for older rows)
                    $addon_paid_cents_eur += (int)$ai['total_price'];
                }
            }
        }

        if ($addon_paid_cents_eur > 0) {
            $discounted_cents += $addon_paid_cents_eur;
        }


        // Convert to order currency cents for UI/log compatibility
        $currency = $order['currency'] ?? 'EUR';
        $order_cents = $discounted_cents;
        if ($currency != 'EUR') {
            $rate = (float)get_exchange_rate();
            if ($rate <= 0) { $rate = 1.0; }
            $order_cents = (int)round($discounted_cents * $rate);
        }

        return [
            'success' => true,
            'eur_cents' => (int)$discounted_cents,
            'order_cents' => (int)$order_cents,
            'meta' => [
                'server' => (string)($options['server'] ?? ''),
                'addons_paid_cents' => (int)$addon_paid_cents_eur,
                'discount_code' => $discount_code,
                'discount_percent' => $discount_percent,
            ],
        ];
    }

    private 
function calc_remaining_total_price_cents($order_id, $progress)
    {
        $order = db_get_row('orders', ['id' => (int)$order_id]);
        if ($order == false) {
            return ['success' => false, 'message' => 'Order not found.'];
        }

        $options = db_get_row('order_options', ['order_id' => (int)$order_id]);
        if ($options == false) {
            return ['success' => false, 'message' => 'Order options not found.'];
        }

        $form = db_get_row('boost_forms', ['id' => (int)$order['form_id']]);
        if ($form == false) {
            return ['success' => false, 'message' => 'Boost form not found.'];
        }

        $form_type = (string)$form['type'];
        $form_id = (int)($order['form_id'] ?? 0);

        if (!is_array($progress)) {
            $progress = [];
        }

        // Quantity based orders are paid proportionally. This is intentionally independent
        // from individual pricing JSON shapes, so new games/forms use the same reliable
        // preview and final remove-booster calculation.
        $quantity_key = null;
        $completed_key = null;
        if (in_array($form_type, ['win', 'arena'], true)) {
            $quantity_key = 'matches';
            $completed_key = 'wins_completed';
        } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true)) {
            $quantity_key = 'matches';
            $completed_key = 'matches_completed';
        } elseif ($form_type === 'coaching') {
            $quantity_key = 'hours';
            $completed_key = 'hours_completed';
        }
        if ($quantity_key !== null) {
            $purchased = max(0, (float)($options[$quantity_key] ?? 0));
            $completed = (float)($progress[$completed_key] ?? 0);
            // Only the legacy LoL win form supports a negative progress fine.
            $allow_negative = $form_type === 'win' && $form_id === 2;
            if (!$allow_negative) $completed = max(0, $completed);
            if ($purchased > 0 && $completed > $purchased) $completed = $purchased;
            $ratio = $purchased > 0 ? (($purchased - $completed) / $purchased) : 1.0;
            if (!$allow_negative) $ratio = max(0, min(1, $ratio));

            $current = $this->calc_current_total_price_cents((int)$order_id);
            $current_eur = (($current['success'] ?? false) === true)
                ? (int)$current['eur_cents']
                : (int)($order['price_eur'] ?? $order['price'] ?? 0);

            return [
                'success' => true,
                'new_total_cents' => max(0, (int)round($current_eur * $ratio)),
                'meta' => [
                    'pricing_mode' => 'quantity_proportional_current_total',
                    'quantity_purchased' => $purchased,
                    'quantity_completed' => $completed,
                    'remaining_ratio' => $ratio,
                    'discount_code' => $current['meta']['discount_code'] ?? null,
                    'discount_percent' => $current['meta']['discount_percent'] ?? null,
                ],
            ];
        }

        // Form ID 26 / Pro Games has no reliable pricing JSON because the booster sets the price.
        // Use the complete current payable scope proportionally: base order price + paid addon invoices.
        if ($form_type === 'pro-games' || $form_id === 26) {
            $purchased = max(0, (int)($options['matches'] ?? 0));
            $completed = max(0, (int)($progress['matches_completed'] ?? $progress['games_completed'] ?? 0));
            if ($purchased > 0 && $completed > $purchased) { $completed = $purchased; }
            $remaining = max(0, $purchased - $completed);
            $ratio = $purchased > 0 ? ($remaining / $purchased) : 1.0;
            if ($ratio < 0) $ratio = 0;
            if ($ratio > 1) $ratio = 1;

            $base_current_eur_cents = (int)($order['price_eur'] ?? 0);
            if ($base_current_eur_cents <= 0) { $base_current_eur_cents = (int)($order['price'] ?? 0); }
            $addon_paid_cents_eur = (int)$this->get_paid_addons_total_eur_cents((int)$order_id);
            $current_scope_eur_cents = max(0, $base_current_eur_cents + $addon_paid_cents_eur);

            return [
                'success' => true,
                'new_total_cents' => max(0, (int)round($current_scope_eur_cents * $ratio)),
                'meta' => [
                    'pricing_mode' => 'pro_games_proportional_current_total_plus_paid_addons',
                    'server' => (string)($options['server'] ?? ''),
                    'base_current_cents' => $base_current_eur_cents,
                    'addons_paid_cents' => $addon_paid_cents_eur,
                    'current_scope_cents' => $current_scope_eur_cents,
                    'games_purchased' => $purchased,
                    'games_completed' => $completed,
                    'games_remaining' => $remaining,
                    'remaining_ratio' => $ratio,
                    'discount_code' => null,
                    'discount_percent' => null,
                ],
            ];
        }

        // Form ID 27 / Duo Pass is time based: complete current scope * remaining hours / booked hours.
        if ($form_type === 'duo-pass' || $form_id === 27) {
            $purchased = max(0, (float)($options['hours'] ?? 0));
            if (isset($progress['remaining_hours'])) {
                $remaining = max(0, (float)$progress['remaining_hours']);
            } else {
                $completed = max(0, (float)($progress['hours_completed'] ?? 0));
                $remaining = max(0, $purchased - $completed);
            }
            if ($purchased > 0 && $remaining > $purchased) { $remaining = $purchased; }
            $ratio = $purchased > 0 ? ($remaining / $purchased) : 1.0;
            if ($ratio < 0) $ratio = 0;
            if ($ratio > 1) $ratio = 1;

            $base_current_eur_cents = (int)($order['price_eur'] ?? 0);
            if ($base_current_eur_cents <= 0) { $base_current_eur_cents = (int)($order['price'] ?? 0); }
            $addon_paid_cents_eur = (int)$this->get_paid_addons_total_eur_cents((int)$order_id);
            $current_scope_eur_cents = max(0, $base_current_eur_cents + $addon_paid_cents_eur);

            return [
                'success' => true,
                'new_total_cents' => max(0, (int)round($current_scope_eur_cents * $ratio)),
                'meta' => [
                    'pricing_mode' => 'duo_pass_time_proportional_current_total_plus_paid_addons',
                    'server' => (string)($options['server'] ?? ''),
                    'base_current_cents' => $base_current_eur_cents,
                    'addons_paid_cents' => $addon_paid_cents_eur,
                    'current_scope_cents' => $current_scope_eur_cents,
                    'hours_purchased' => $purchased,
                    'hours_remaining' => $remaining,
                    'hours_completed' => max(0, $purchased - $remaining),
                    'remaining_ratio' => $ratio,
                    'discount_code' => null,
                    'discount_percent' => null,
                ],
            ];
        }

        if (empty($form['uuid'])) {
            return ['success' => false, 'message' => 'Boost form pricing UUID not found.'];
        }

        $pricing_json = get_pricing_json($form['uuid']);
        if (!is_array($pricing_json)) {
            return ['success' => false, 'message' => 'Pricing JSON not found.'];
        }
        // Pull the latest invoice snapshot for discount (coins intentionally ignored for progress calculations).
        $invoice = null;
        $inv_rows = db_get_rows('invoices', [
            'order_type' => 'order',
            'order_id' => (int)$order_id,
            'order' => 'id,desc',
            'limit' => 1,
        ], true);
        if (!empty($inv_rows)) {
            $invoice = $inv_rows[0];
        }


        // Helper: normalize pricing return value to cents.
        $normalize_to_cents = function ($raw_price, $scale_ref) {
            if ($raw_price === null || $raw_price === '') {
                return 0;
            }

            $cents = 0;
            if (is_string($raw_price)) {
                $rp = str_replace(',', '.', $raw_price);
                if (strpos($rp, '.') !== false) {
                    $cents = (int) round(((float)$rp) * 100);
                } else {
                    $cents = (int) $rp;
                }
            } elseif (is_float($raw_price)) {
                if (abs($raw_price - floor($raw_price)) > 0.00001) {
                    $cents = (int) round($raw_price * 100);
                } else {
                    $cents = (int) $raw_price;
                }
            } else {
                $cents = (int) $raw_price;
            }

            // Heuristic fix: sometimes pricing returns values 100x larger than expected.
            if ($scale_ref > 0 && $cents > ($scale_ref * 20)) {
                $cents = (int) round($cents / 100);
            }
            return $cents;
        };

        // Helper: apply invoice discount snapshot (no coins).
        $apply_discount_snapshot = function ($base_cents) use ($invoice) {
            $discounted = $base_cents;
            $discount_meta = null;
            $discount_code = null;
            $discount_percent = null;

            if ($invoice && isset($invoice['price']) && (int)$invoice['price'] > 0) {
                if (!empty($invoice['discount_id']) && isset($invoice['discount_amount']) && (int)$invoice['discount_amount'] !== 0) {
                    $discount_row = db_get_row('discounts', ['id' => (int)$invoice['discount_id']]);
                    if ($discount_row != false && !empty($discount_row['code'])) {
                        $discount_code = (string)$discount_row['code'];
                    }

                    // Derive effective percent from invoice snapshot
                    $discount_percent = round((abs((int)$invoice['discount_amount']) / max(1, (int)$invoice['price'])) * 100, 2);

                    if ($discount_row != false && (int)$discount_row['is_fixed'] === 1) {
                        // discount_amount is negative
                        $discounted = $base_cents + (int)$invoice['discount_amount'];
                        $discount_meta = ['type' => 'fixed', 'amount_cents' => (int)$invoice['discount_amount']];
                    } else {
                        $pct = abs((int)$invoice['discount_amount']) / (int)$invoice['price'];
                        if ($pct > 1) {
                            $pct = 1;
                        }
                        $discounted = (int) round($base_cents * (1 - $pct));
                        $discount_meta = ['type' => 'percent_snapshot', 'percent' => $pct];
                    }
                }
            }

            if ($discounted < 0) {
                $discounted = 0;
            }

            return [$discounted, $discount_meta, $discount_code, $discount_percent];
        };

        // Keep the full option set (solo/duo, play-with-booster, bonus win, etc.) in the pricing calc.
        // Some codebases bill post-purchase add-ons via separate addon invoices; those are handled below (proportionally) without altering option-based pricing.
        $addon_keys = [];

        // === BASE TOTAL (current scope) ===
        $base_post_data = $options;
        $base_post_data['form_id'] = (int)$order['form_id'];
        foreach ($addon_keys as $k) {
            if (isset($base_post_data[$k])) {
                $base_post_data[$k] = 0;
            }
        }

        $calc_total = calculate_boost_pricing($pricing_json, $base_post_data);
        if (!is_array($calc_total)) {
            return ['success' => false, 'message' => 'Pricing calculation failed.'];
        }

        $raw_total = null;
        if (isset($calc_total[2])) {
            $raw_total = $calc_total[2];
        } elseif (isset($calc_total['price_eur'])) {
            $raw_total = $calc_total['price_eur'];
        } elseif (isset($calc_total[0])) {
            $raw_total = $calc_total[0];
        }

        $scale_ref = 0;
        if ($invoice && isset($invoice['price_eur']) && (int)$invoice['price_eur'] > 0) {
            $scale_ref = (int)$invoice['price_eur'];
        } elseif (isset($order['price_eur']) && (int)$order['price_eur'] > 0) {
            $scale_ref = (int)$order['price_eur'];
        }

        $base_total_cents = $normalize_to_cents($raw_total, $scale_ref);
        [$base_total_discounted, $discount_meta_total, $discount_code, $discount_percent] = $apply_discount_snapshot($base_total_cents);

        // === BASE REMAINING (after progress) ===
        $post_data = $options;
        $post_data['form_id'] = (int)$order['form_id'];

        // Rank boost: override start point.
        if ($form_type === 'rank') {
            if (isset($progress['start_tier'])) {
                $post_data['start_tier'] = (int)$progress['start_tier'];
            }
            if (isset($progress['start_division'])) {
                $post_data['start_division'] = (int)$progress['start_division'];
            }
            if (isset($progress['start_lp'])) {
                $post_data['start_lp'] = (string)$progress['start_lp'];
                unset($post_data['start_lp_full']);
            }
            if (isset($progress['start_lp_full'])) {
                $post_data['start_lp_full'] = (int)$progress['start_lp_full'];
                unset($post_data['start_lp']);
            }
            if (isset($progress['lp_gain'])) {
                $post_data['lp_gain'] = (string)$progress['lp_gain'];
            }
        }

        // Win/Arena/Match/etc: override remaining count based on progress.
        if ($form_type === 'win' || $form_type === 'arena') {
            $purchased = isset($options['matches']) ? (int)$options['matches'] : (isset($options['wins']) ? (int)$options['wins'] : 0);
            $completed = isset($progress['wins_completed']) ? (int)$progress['wins_completed'] : 0;
            $post_data['matches'] = $purchased - $completed; // can be negative
        } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true)) {
            $purchased = isset($options['matches']) ? (int)$options['matches'] : 0;
            $completed = isset($progress['matches_completed']) ? (int)$progress['matches_completed'] : 0;
            $post_data['matches'] = $purchased - $completed; // can be negative
        } elseif ($form_type === 'coaching') {
            $purchased = isset($options['hours']) ? (int)$options['hours'] : 0;
            $completed = isset($progress['hours_completed']) ? (int)$progress['hours_completed'] : 0;
            $post_data['hours'] = $purchased - $completed; // can be negative
        }

        

        foreach ($addon_keys as $k) {
            if (isset($post_data[$k])) {
                $post_data[$k] = 0;
            }
        }

        $calc = calculate_boost_pricing($pricing_json, $post_data);
        if (!is_array($calc)) {
            return ['success' => false, 'message' => 'Pricing calculation failed.'];
        }

        $raw_remaining = null;
        if (isset($calc[2])) {
            $raw_remaining = $calc[2];
        } elseif (isset($calc['price_eur'])) {
            $raw_remaining = $calc['price_eur'];
        } elseif (isset($calc[0])) {
            $raw_remaining = $calc[0];
        }

        if ($raw_remaining === null || $raw_remaining === '') {
            return ['success' => false, 'message' => 'Pricing calculation failed.'];
        }

        $base_remaining_cents = $normalize_to_cents($raw_remaining, $scale_ref);
        [$base_remaining_discounted, $discount_meta_remaining, $discount_code2, $discount_percent2] = $apply_discount_snapshot($base_remaining_cents);

        // Use remaining snapshot meta if present, otherwise total snapshot meta.
        $discount_meta = $discount_meta_remaining ?? $discount_meta_total;
        $discount_code = $discount_code2 ?? $discount_code;
        $discount_percent = $discount_percent2 ?? $discount_percent;

        // === PAID ADDONS ===
        $addon_paid_cents_eur = 0;
        $addon_invoices = db_get_rows('invoices', [
            'order_type' => 'addon',
            'order_id' => (int)$order_id,
            'status' => 'PAID',
        ], true);
        if (!empty($addon_invoices)) {
            foreach ($addon_invoices as $ai) {
                
                // Avoid double-counting Duo / Play With Booster if it's already included in base pricing (is_duo=1)
                $pwb_enabled = isset($options['is_duo']) && (int)$options['is_duo'] === 1;
                if ($pwb_enabled) {
                    $haystack = strtolower(json_encode($ai));
                    if (strpos($haystack, 'duo') !== false || strpos($haystack, 'play with booster') !== false || strpos($haystack, 'play_with_booster') !== false) {
                        continue;
                    }
                }
if (isset($ai['price_eur'])) {
                    $addon_paid_cents_eur += (int)$ai['price_eur'];
                } elseif (isset($ai['total_price'])) {
                    $addon_paid_cents_eur += (int)$ai['total_price'];
                }
            }
        }

        // Remaining ratio based on discounted base values (no coins).
        $ratio = 0.0;
        if ($base_total_discounted > 0) {
            $ratio = $base_remaining_discounted / $base_total_discounted;
            if ($ratio < 0) $ratio = 0;
            if ($ratio > 1) $ratio = 1;
        }

        $addon_remaining = 0;
        if ($addon_paid_cents_eur > 0) {
            $addon_remaining = (int) round($addon_paid_cents_eur * $ratio);
            if ($addon_remaining < 0) $addon_remaining = 0;
            if ($addon_remaining > $addon_paid_cents_eur) $addon_remaining = $addon_paid_cents_eur;
        }

        $new_total_cents = $base_remaining_discounted + $addon_remaining;
        if ($new_total_cents < 0) {
            $new_total_cents = 0;
        }

        return [
            'success' => true,
            'new_total_cents' => $new_total_cents,
            'meta' => [
                'server' => (string)($options['server'] ?? ''),
                'base_total_discounted_cents' => $base_total_discounted,
                'base_remaining_discounted_cents' => $base_remaining_discounted,
                'remaining_ratio' => $ratio,
                'addons_paid_cents' => $addon_paid_cents_eur,
                'addons_remaining_cents' => $addon_remaining,
                'discount' => $discount_meta,
                'discount_code' => $discount_code,
                'discount_percent' => $discount_percent,
            ],
        ];
    }


    public function admin_cancel_order_completion()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['id']);
            unset($_POST['id']);
            $order = db_get_row('orders', ['id' => $order_id]);
            if ($order != false && $order['booster_id'] != null && $order['status'] == 'COMPLETED') {
                $booster_id = $order['booster_id'];
                global $db;
                $completionBalances = $db->run(
                    "SELECT booster_id, COALESCE(SUM(amount), 0) AS net_amount
                       FROM booster_payments
                      WHERE note = ?
                        AND type IN ('order_completion', 'order_completion_cancel')
                      GROUP BY booster_id",
                    (string)$order_id
                ) ?: [];

                $cancelledBoosters = 0;
                foreach ($completionBalances as $completionBalance) {
                    $paymentBoosterId = (int)($completionBalance['booster_id'] ?? 0);
                    $netCompletionAmount = (int)($completionBalance['net_amount'] ?? 0);
                    if ($paymentBoosterId <= 0 || $netCompletionAmount <= 0) {
                        continue;
                    }

                    $paymentBooster = db_get_row('boosters', ['id' => $paymentBoosterId]);
                    if ($paymentBooster == false) {
                        continue;
                    }

                    $oldCompletionBalance = (int)($paymentBooster['balance'] ?? 0);
                    $newCompletionBalance = $oldCompletionBalance - $netCompletionAmount;
                    db_update_row('boosters', ['id' => $paymentBoosterId], ['balance' => $newCompletionBalance]);
                    db_add_row('booster_payments', [
                        'booster_id' => $paymentBoosterId,
                        'type' => 'order_completion_cancel',
                        'note' => (string)$order_id,
                        'amount' => -$netCompletionAmount,
                        'currency' => 'EUR',
                        'sender' => ADMIN_DATA['username'],
                        'sender_type' => 'admin',
                        'sender_id' => ADMIN_ID,
                        'balance_update' => $oldCompletionBalance . '|' . $newCompletionBalance,
                        'created_at' => date('Y-m-d H:i:s'),
                    ]);
                    $cancelledBoosters++;
                    log_admin_action(
                        ADMIN_ID,
                        "Order #{$order_id}: cancelled completion payout for booster #{$paymentBoosterId} ("
                        . number_format($netCompletionAmount / 100, 2, '.', '') . " EUR)"
                    );
                }
                $booster = db_get_row('boosters', ['id' => $booster_id]);
                $helper_bonus_payment = db_get_row('booster_payments', ['note' => $order_id, 'type' => 'booster_helper_bonus']);
                if ($helper_bonus_payment != false) {
                    $booster_latest = db_get_row('boosters', ['id' => $booster_id]);
                    if ($booster_latest != false) {
                        $old_bonus_balance = (int)($booster_latest['balance'] ?? 0);
                        $new_bonus_balance = $old_bonus_balance - (int)$helper_bonus_payment['amount'];
                        db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_bonus_balance]);

                        db_add_row('booster_payments', [
                            'booster_id' => $booster_id,
                            'type' => 'booster_helper_bonus_cancel',
                            'note' => (string)$order_id,
                            'amount' => -((int)$helper_bonus_payment['amount']),
                            'currency' => 'EUR',
                            'sender' => ADMIN_DATA['username'],
                            'sender_type' => 'admin',
                            'sender_id' => ADMIN_ID,
                            'balance_update' => $old_bonus_balance . '|' . $new_bonus_balance,
                            'created_at' => date('Y-m-d H:i:s'),
                        ]);

                        log_admin_action(ADMIN_ID, "Order #{$order_id}: cancelled booster helper bonus for booster #{$booster_id}");
                    }
                }

                $monthly_bonus_payment = db_get_row('booster_payments', ['note' => $order_id, 'type' => 'monthly_top_booster_bonus']);
                if ($monthly_bonus_payment != false) {
                    $booster_latest = db_get_row('boosters', ['id' => $booster_id]);
                    if ($booster_latest != false) {
                        $old_monthly_balance = (int)($booster_latest['balance'] ?? 0);
                        $new_monthly_balance = $old_monthly_balance - (int)$monthly_bonus_payment['amount'];
                        db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_monthly_balance]);

                        db_add_row('booster_payments', [
                            'booster_id' => $booster_id,
                            'type' => 'monthly_top_booster_bonus_cancel',
                            'note' => (string)$order_id,
                            'amount' => -((int)$monthly_bonus_payment['amount']),
                            'currency' => 'EUR',
                            'sender' => ADMIN_DATA['username'],
                            'sender_type' => 'admin',
                            'sender_id' => ADMIN_ID,
                            'balance_update' => $old_monthly_balance . '|' . $new_monthly_balance,
                            'created_at' => date('Y-m-d H:i:s'),
                        ]);

                        log_admin_action(ADMIN_ID, "Order #{$order_id}: cancelled monthly top booster bonus for booster #{$booster_id}");
                    }
                }


                db_update_row('orders', ['id' => $order_id], ['status' => 'IN_PROGRESS', 'completed_at' => null]);
                log_admin_action(ADMIN_ID, 'Cancelled order completion ' . $order['id']);

                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Order completion cancelled successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ));
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    public function admin_add_package()
    {
        if ($this->is_admin) {
            $validator = new Validator;
            $validation = $validator->make($_POST, [
                'name' => 'required',
                'price' => 'required',
                'features' => 'required',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $data = esc_array($_POST);
                if (empty($data['icon'])) { $data['icon'] = 'rp'; }

                $features = [];
                if (!empty($data['features']) && is_array($data['features'])) {
                    $features = array_merge($features, $data['features']);
                }
                if (!empty($data['custom_features']) && is_array($data['custom_features'])) {
                    $features = array_merge($features, $data['custom_features']);
                }
                $features = array_values(array_filter(array_map('trim', $features), static function ($feature) {
                    return $feature !== '';
                }));

                $rankedReady = isset($data['ranked_ready']) ? (int)$data['ranked_ready'] : 1;
                $data['ranked_ready'] = $rankedReady === 0 ? 0 : 1;

                $readinessFeature = $data['ranked_ready'] === 1
                    ? 'Ranked Ready'
                    : 'Not Ranked Ready (requires 10 normals)';

                $features = array_values(array_filter($features, static function ($feature) {
                    $lower = strtolower($feature);
                    return $lower !== 'ranked ready'
                        && strpos($lower, 'not ranked ready') === false
                        && strpos($lower, 'requires 10 normals') === false;
                }));
                array_unshift($features, $readinessFeature);

                unset($data['custom_features']);
                $data['features'] = implode('|', $features);
                $data['price'] = util_format_price_db($data['price']);
                $package_id = db_add_row('account_packages', $data);
                if ($package_id != false) {
                    log_admin_action(ADMIN_ID, 'Added package ' . $package_id);
                    $form_error = false;
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Package added successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'redirectUrl' => ADMN_URL . '/account-package/' . $package_id,
                    ));
                } else {
                    $form_error = 'Something went wrong 😔';
                }
            }
            if ($form_error != false) {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

