    public function admin_delete_package()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid package ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Check the package exists
        $package = db_get_row('account_packages', ['id' => $id]);
        if (empty($package)) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'Package #' . $id . ' not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Block deletion if accounts are still attached to this package
        $accountCount = db_get_row_count('accounts', ['package_id' => $id]);
        if ($accountCount > 0) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => [
                    'type'    => 'warning',
                    'title'   => 'Cannot delete',
                    'message' => 'Package #' . $id . ' still has ' . $accountCount . ' account(s) attached. Remove them first.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $deleted = db_delete_rows('account_packages', ['id' => $id]);

        if ($deleted != false) {
            log_admin_action(ADMIN_ID, 'Deleted package #' . $id . ' – ' . ($package['name'] ?? ''));
            echo json_encode([
                'status'  => 'success',
                'success' => true,
                'sendToast' => [
                    'type'    => 'success',
                    'title'   => 'Deleted',
                    'message' => 'Package "' . ($package['name'] ?? '#' . $id) . '" deleted successfully.',
                ],
                'playSound' => 'success',
            ]);
        } else {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not delete package. Please try again.'],
                'playSound' => 'error',
            ]);
        }
    }

    public function admin_delete_package_account()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid account ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $account = db_get_row('accounts', ['id' => $id]);
        if (empty($account)) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'Account #' . $id . ' not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Block deletion if account has already been sold (client_id set)
        if (!empty($account['client_id'])) {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => [
                    'type'    => 'warning',
                    'title'   => 'Cannot delete',
                    'message' => 'Account #' . $id . ' has already been sold to a client and cannot be deleted.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $deleted = db_delete_rows('accounts', ['id' => $id]);

        if ($deleted != false) {
            log_admin_action(ADMIN_ID, 'Deleted package account #' . $id . ' (login: ' . ($account['login'] ?? '—') . ')');
            echo json_encode([
                'status'  => 'success',
                'success' => true,
                'sendToast' => [
                    'type'    => 'success',
                    'title'   => 'Deleted',
                    'message' => 'Account #' . $id . ' deleted successfully.',
                ],
                'playSound' => 'success',
            ]);
        } else {
            echo json_encode([
                'status'    => 'error',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not delete account. Please try again.'],
                'playSound' => 'error',
            ]);
        }
    }

    public function admin_add_account()
    {
        if ($this->is_admin) {
            $validator = new Validator;
            $validation = $validator->make($_POST, [
                'login' => 'required',
                'password' => 'required',
                'package_id' => 'required',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $data = esc_array($_POST);
