    public function admin_bulk_add_accounts()
    {
        if ($this->is_admin) {
            $package_id = (int)($_POST['package_id'] ?? 0);
            $game_id    = (int)($_POST['game_id'] ?? 1);
            $bulk       = trim((string)($_POST['accounts_bulk'] ?? ''));
            $skip_duplicates = (int)($_POST['skip_duplicates'] ?? 0) === 1;

            if ($package_id <= 0 || $bulk === '') {
                echo json_encode([
                    'status' => 'error',
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please paste at least one account.'],
                    'playSound' => 'error',
                ]);
                return;
            }

            $package = db_get_row('account_packages', ['id' => $package_id]);
            if (!$package) {
                echo json_encode([
                    'status' => 'error',
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Package not found.'],
                    'playSound' => 'error',
                ]);
                return;
            }

            $lines = preg_split('/\r\n|\r|\n/', $bulk);
            $added = 0;
            $duplicates = 0;
            $invalid = 0;
            $seen = [];

            foreach ($lines as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }

                if (preg_match('/^login\s*[,:]\s*password/i', $line)) {
                    continue;
                }

                // Accept comma-separated and colon-separated account rows.
                // Everything after the second separator remains account Data.
                $first_comma = strpos($line, ',');
                $first_colon = strpos($line, ':');
                if ($first_comma === false) {
                    $separator = $first_colon === false ? '' : ':';
                } elseif ($first_colon === false) {
                    $separator = ',';
                } else {
                    $separator = $first_colon < $first_comma ? ':' : ',';
                }
                if ($separator === '') {
                    $invalid++;
                    continue;
                }

                $parts = explode($separator, $line, 3);
                $login = trim($parts[0] ?? '');
                $password = trim($parts[1] ?? '');
                $extra_data = trim($parts[2] ?? '');

                if ($login === '' || $password === '') {
                    $invalid++;
                    continue;
                }

                $seen_key = strtolower($login) . ':' . $package_id;
                if (isset($seen[$seen_key])) {
                    $duplicates++;
                    continue;
                }
                $seen[$seen_key] = true;

                if ($skip_duplicates && db_get_row('accounts', ['package_id' => $package_id, 'login' => $login])) {
                    $duplicates++;
                    continue;
                }

                $row = [
                    'game_id'    => $game_id,
                    'package_id' => $package_id,
                    'login'      => $login,
                    'password'   => $password,
                    'data'       => $extra_data,
                    'admin_id'   => ADMIN_ID,
                    'status'     => 0,
                ];

                $account_id = db_add_row('accounts', esc_array($row));
                if ($account_id != false) {
                    $added++;
                } else {
                    $invalid++;
                }
            }

            if ($added > 0) {
                $package_label = !empty($package['name']) ? $package['name'] : ('Package #' . $package_id);
                log_admin_action(ADMIN_ID, 'Bulk added ' . $added . ' package accounts (package: ' . $package_label . ', duplicates skipped: ' . $duplicates . ', invalid rows: ' . $invalid . ')');

                echo json_encode([
                    'status' => 'success',
                    'success' => true,
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Import complete',
                        'message' => $added . ' accounts added, ' . $duplicates . ' duplicates skipped, ' . $invalid . ' invalid rows.',
                    ],
                    'playSound' => 'success',
                    'resetForm' => true,
                    'reload' => true,
                    'refreshPage' => true,
                ]);
            } else {
                echo json_encode([
                    'status' => 'error',
                    'sendToast' => [
                        'type' => 'warning',
                        'title' => 'Nothing imported',
                        'message' => '0 accounts added, ' . $duplicates . ' duplicates skipped, ' . $invalid . ' invalid rows.',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    public function admin_update_account()
    {
        if ($this->is_admin) {
