    public function admin_add_article()
    {
        if ($this->is_admin || $this->is_seo) {

            $validator = new Validator;
            $validation = $validator->make($_POST, [
                'title' => 'required',
                'excerpt' => 'required',
                'content' => 'required',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please fill all required fields ⚠️',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            // Clean inputs
            $data = esc_array($_POST);
            $data['title']       = $_POST['title'];
            $data['excerpt']     = $_POST['excerpt'];
            $data['description'] = $_POST['description'] ?? '';
            $data['content'] = $_POST['content'];

            // Blog posts may be tagged with a game. The column is created lazily so no
            // migration is needed, and an empty selection is stored as NULL.
            if (function_exists('lb_articles_ensure_game_column')) lb_articles_ensure_game_column();
            $data['game_id'] = ((int)($_POST['game_id'] ?? 0)) ?: null;

            // 🔥 FIX: decode HTML entities FIRST
            $title = html_entity_decode($data['title'], ENT_QUOTES, 'UTF-8');

            // 🔥 Slug that doesn't produce garbage
            $slug = strtolower($title);
            $slug = preg_replace('/[^a-z0-9]+/i', '-', $slug);
            $slug = trim($slug, '-');

            $data['slug'] = $slug;

            // Image upload
            $image_url = $_FILES['image_url'] ?? null;

            if ($image_url && $image_url['name'] !== '') {
                $uploaded = upload_image($image_url, 'articles/' . $data['slug']);

                if ($uploaded === false) {
                    echo json_encode([
                        "sendToast" => [
                            "type" => "danger",
                            "title" => "Error",
                            "message" => "Invalid file type."
                        ]
                    ]);
                    return;
                }

                $data['image_url'] = $uploaded;
            }

            // Insert
            $article_id = db_add_row('articles', $data);

            if ($article_id) {
                log_admin_action(ADMIN_ID, 'Added article ' . $article_id);

                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Article added successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'redirectUrl' => ADMN_URL . '/articles',
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

