    // client FUNCTIONS

    public function auth_client_login()
    {
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'email' => 'required',
            'password' => 'required'
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {

            $email = esc($_POST["email"]);
            $password = sha1($_POST["password"]);

            $client = db_get_row('clients', ['email' => $email]);
            if ($client && !empty($client['is_deleted'])) {
                $form_error = ['email' => 'Account deleted'];
            } elseif ($client && !empty($client['is_banned'])) {
                $form_error = ['email' => 'Account banned'];
            } else {
                $client_id = db_auth_login($email, $password, 'clients');
            }

            if (empty($form_error) && !empty($client_id)) {
                $token = db_auth_session_start($client_id, 'clients');
                if ($token != false) {
                    $form_error = false;
                    if (isset($_POST['remember_me'])) {
                        $lifetime = 1;
                    } else {
                        $lifetime = 0;
                    }
                    util_create_cookie('client_session_token', $token, $lifetime);
                    $redirect = $_POST['redirectUrl'] ?? $_POST['redirect_after_login'] ?? null;
                    $redirect = is_string($redirect) ? trim($redirect) : null;

                    // Allow redirect only to internal URLs (prevents open redirect attacks)
                    if ($redirect) {
                        // If relative URL like "/checkout?x=1", convert to absolute
                        if (strpos($redirect, '/') === 0 && strpos($redirect, '//') !== 0) {
                            $redirect = BASE_URL . $redirect;
                        }

                        // If absolute URL, only allow if it starts with BASE_URL
                        if (strpos($redirect, BASE_URL) === 0) {
                            echo json_encode([
                                'sendToast' => [
                                    'type' => 'primary',
                                    'title' => 'Success',
                                    'message' => 'Logged in successfully ✅',
                                ],
                                'playSound' => 'success',
                                'redirectUrl' => $redirect,
                            ]);
                            return;
                        }
                    }

                    echo json_encode([
                        'sendToast' => [
                            'type' => 'primary',
                            'title' => 'Success',
                            'message' => 'Logged in successfully ✅',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ]);
                    return;
                } else {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Something went wrong, please try again',
                        ]
                    ]);
                }
            } elseif (empty($form_error)) {
                $deleted_client = empty($client) ? db_get_row('clients', ['deleted_email' => $email, 'is_deleted' => 1]) : false;
                if ($deleted_client) {
                    $form_error = ['email' => 'Account deleted'];
                } else {
                    $form_error = ['email' => 'Invalid email and password combination'];
                }
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

    public function auth_client_guest_login()
    {
