                    'is_email' => 1,
                ]);
                $token = db_auth_session_start($client_id, 'clients');
                $form_error = false;
                util_create_cookie('client_session_token', $token, 1);

                $redirect = $_POST['redirectUrl'] ?? $_POST['redirect_after_login'] ?? null;
                $redirect = is_string($redirect) ? trim($redirect) : null;

                // Allow redirect only to internal URLs (prevents open redirect attacks)
                if ($redirect) {
                    // If relative URL like "/checkout?x=1", convert to absolute
                    if (strpos($redirect, '/') === 0 && strpos($redirect, '//') !== 0) {
                        $redirect = BASE_URL . $redirect;
                    }

                    // If absolute URL, only allow if it starts with BASE_URL
                    if (strpos($redirect, BASE_URL) === 0) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'primary',
                                'title' => 'Success',
                                'message' => 'Logged in successfully ✅',
                            ],
                            'playSound' => 'success',
                            'redirectUrl' => $redirect,
                        ]);
                        return;
                    }
                }

                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => 'Logged in successfully ✅',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
                return;
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

    public function auth_client_guest_email_update()
    {
        if (!$this->is_client || !defined('CLIENT_DATA') || empty(CLIENT_DATA)) {
            echo json_encode([
                'validationErrors' => ['email' => 'Please sign in again.'],
            ]);
            return;
        }

        $username = (string)(CLIENT_DATA['username'] ?? '');
        if (stripos($username, 'Guest#') !== 0) {
            echo json_encode([
                'validationErrors' => ['email' => 'Email changes are only available for guest checkout.'],
            ]);
            return;
        }

        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'email' => 'required|email',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            echo json_encode([
                'validationErrors' => $validation->errors()->firstOfAll(),
            ]);
            return;
        }

        $email = esc($_POST['email']);
        $existingClient = db_get_row('clients', ['email' => $email]);
        if ($existingClient && (int)$existingClient['id'] !== (int)CLIENT_ID) {
            echo json_encode([
                'validationErrors' => ['email' => 'This email is already used. Please log in instead.'],
            ]);
            return;
        }

        db_update_row('clients', ['id' => CLIENT_ID], ['email' => $email]);

        echo json_encode([
            'sendToast' => [
                'type' => 'primary',
                'title' => 'Success',
                'message' => 'Email updated successfully.',
            ],
            'refreshPage' => true,
        ]);
    }

    public function client_checkout()
    {
        if ($this->is_client) {
            $invoice_uuid = esc($_POST['invoice_uuid']);
            $invoice = db_get_row('invoices', ['uuid' => $invoice_uuid, 'client_id' => CLIENT_ID]);
            $processor = esc($_POST['processor']);

            // Fallback: claim guest checkout for the currently logged in client
            if ($invoice == false) {
                $invoice_any = db_get_row('invoices', ['uuid' => $invoice_uuid], 1);
                if ($invoice_any && (int)($invoice_any['client_id'] ?? 0) === 0) {
                    $guestType = (string)($invoice_any['order_type'] ?? '');
                    if ($guestType === 'egirl_session') {
                        db_update_row('invoices', ['id' => $invoice_any['id']], ['client_id' => CLIENT_ID]);
                        db_update_row('egirl_orders', ['id' => $invoice_any['order_id']], ['client_id' => CLIENT_ID]);
                        $invoice = db_get_row('invoices', ['id' => $invoice_any['id']], 1);
                    } elseif ($guestType === 'digital_good') {
                        db_update_row('invoices', ['id' => $invoice_any['id']], ['client_id' => CLIENT_ID]);
                        try {
                            global $db;
                            $db->run("UPDATE digital_good_purchases SET client_id = ? WHERE invoice_id = ? AND (client_id IS NULL OR client_id = 0)", (int)CLIENT_ID, (int)$invoice_any['id']);
                        } catch (\Throwable $e) {}
                        $invoice = db_get_row('invoices', ['id' => $invoice_any['id']], 1);
                    }
                }
            }

            // check if invoice exists
            if ($invoice == false) {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invoice not found',
                    ],
                    'playSound' => 'error',
                ));
                return;
            }

            $checkoutOrder = db_get_row('orders', ['id' => (int)$invoice['order_id']], 1);
            if ($checkoutOrder && in_array((int)($checkoutOrder['form_id'] ?? 0), [4, 19, 29], true)
                && array_key_exists('selected_boosters', $_POST)) {
                $requestedRaw = $_POST['selected_boosters'];
                if (!is_array($requestedRaw)) {
                    $requestedRaw = preg_split('/[\s,|]+/', (string)$requestedRaw, -1, PREG_SPLIT_NO_EMPTY);
                }
                $requestedIds = array_values(array_unique(array_filter(array_map('intval', (array)$requestedRaw))));
                $checkoutOptions = db_get_row('order_options', ['order_id' => (int)$invoice['order_id']], 1) ?: [];
                $requestLimit = max(1, min(4, (int)($checkoutOptions['boosters'] ?? $checkoutOptions['hours'] ?? 1)));
                $requestedIds = array_slice($requestedIds, 0, $requestLimit);
                foreach ($requestedIds as $requestedId) {
                    if (!db_get_row('boosters', ['id' => $requestedId], 1)) {
                        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'One selected booster is no longer available.']]);
                        return;
                    }
                }
                if (function_exists('lb_order_options_schema_ensure')) {
                    lb_order_options_schema_ensure();
                }
                db_update_row('order_options', ['order_id' => (int)$invoice['order_id']], [
                    'selected_boosters' => implode(',', $requestedIds),
                ]);
                db_update_row('orders', ['id' => (int)$invoice['order_id']], [
                    'booster_id' => $requestedIds[0] ?? null,
                    'claimed_at' => null,
                ]);
            }

            // check if invoice is paid

            if ($invoice['status'] == 'PAID') {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invoice is already paid',
                    ],
                    'playSound' => 'error',
                ));
                return;
            }

            if ($invoice['total_price'] == 0) {
                if (esc($_POST['points_used'])) {
                    if (isset($_POST['booster_id']) && !empty($_POST['booster_id'])) {
                        $booster_id = esc($_POST['booster_id']);
                        $booster = db_get_row('boosters', ['id' => $booster_id]);
                        if (!$booster) {
                            echo json_encode(array(
                                'sendToast' => [
                                    'type' => 'danger',
                                    'title' => 'Error',
                                    'message' => 'Booster not found',
                                ],
                                'playSound' => 'error',
                            ));
                            return;
                        }

                        db_update_row('orders', ['id' => $invoice['order_id']], ['booster_id' => $booster_id]);
                        // Den angefragten Booster in Echtzeit benachrichtigen.
                        // Ohne das feuert 'booster_request' nur beim Annehmen/Ablehnen/Entfernen -
                        // nie beim eigentlichen Kunden-Request. Das Modal im Booster-Panel wurde
                        // dadurch nie ausgeloest.
                        if (function_exists('lb_realtime_emit')) {
                            lb_realtime_emit('booster_request', ['order_id' => (int)$invoice['order_id']]);
                            lb_realtime_emit('orders_panel_update', ['order_id' => (int)$invoice['order_id']]);
                        }
                    }

                    if (isset($_POST['order_note']) && !empty($_POST['order_note'])) {
                        $note = $_POST['order_note'];
                        // check if the order has already a note
                        $order_note = db_get_row('order_notes', ['order_id' => $invoice['order_id'], 'type' => 'client']);
                        if ($order_note) {
                            db_update_row('order_notes', ['id' => $order_note['id']], ['order_note' => $note]);
                        } else {
                            db_add_row('order_notes', [
                                'order_id' => $invoice['order_id'],
                                'order_note' => $note,
                                'type' => 'client'
                            ]);
                        }
                    }

                    echo json_encode(array(
                        'redirectUrl' => '/checkout/' . $invoice['uuid'] . '/process?coins_order=true',
                    ));
                    return;
                } else {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Invoice price is invalid',
                        ],
                        'playSound' => 'error',
                    ));
                    return;
                }
            }

            // check if payment processor is valid
            if (!in_array($processor, ['stripe', 'coinbase', 'payop', 'stripe_paypal'])) {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Payment processor is invalid',
                    ],
                    'playSound' => 'error',
                ));
                return;
            }

            if (isset($_POST['booster_id']) && !empty($_POST['booster_id'])) {
                $booster_id = esc($_POST['booster_id']);
                $booster = db_get_row('boosters', ['id' => $booster_id]);
                if (!$booster) {
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Booster not found',
                        ],
                        'playSound' => 'error',
                    ));
                    return;
                }

                db_update_row('orders', ['id' => $invoice['order_id']], ['booster_id' => $booster_id]);
                // Den angefragten Booster in Echtzeit benachrichtigen.
                // Ohne das feuert 'booster_request' nur beim Annehmen/Ablehnen/Entfernen -
                // nie beim eigentlichen Kunden-Request. Das Modal im Booster-Panel wurde
                // dadurch nie ausgeloest.
                if (function_exists('lb_realtime_emit')) {
                    lb_realtime_emit('booster_request', ['order_id' => (int)$invoice['order_id']]);
                    lb_realtime_emit('orders_panel_update', ['order_id' => (int)$invoice['order_id']]);
                }
            }

            if (isset($_POST['order_note']) && !empty($_POST['order_note'])) {
                $note = esc($_POST['order_note']);
                // check if the order has already a note
                $order_note = db_get_row('order_notes', ['order_id' => $invoice['order_id'], 'type' => 'client']);
                if ($order_note) {
                    db_update_row('order_notes', ['id' => $order_note['id']], ['order_note' => $note]);
                } else {
                    db_add_row('order_notes', [
                        'order_id' => $invoice['order_id'],
                        'order_note' => $note,
                        'type' => 'client'
                    ]);
                }
            }

            if ($processor == 'stripe_paypal') {
                $invoice['total_price'] = round($invoice['total_price'] + ($invoice['total_price'] * 0.1));
            }

            $url = get_payment_url($invoice, $processor);

            echo json_encode(array(
                'redirectUrl' => $url,
            ));
        } else {
            echo json_encode(array(
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Please login in order to proceed with the payment 😊',
                ],
                'playSound' => 'error',
            ));
        }
    }

    public function client_discount_invoice()
    {
        $discount_code = esc($_POST['discount_code']);
        $invoice_id = intval($_POST['invoice_id']);
        $invoice = db_get_row('invoices', ['id' => $invoice_id]);
        if ($invoice != false) {
            if ($this->is_client) {
                $discount = db_get_row('discounts', ['code' => $discount_code]);
                if ($discount != false) {
                    $is_discount_valid = verify_discount($discount, $invoice['order_type']);

                    $response['discount_status'] = $is_discount_valid[0];
                    $response['discount_msg'] = $is_discount_valid[1];
                    if ($is_discount_valid[0] == true) {
                        $client_past_uses = (int)(db_get_row_count('invoices', ['client_id' => CLIENT_ID, 'discount_id' => $discount['id'], 'status' => 'PAID']) ?: 0);
                        if ($client_past_uses >= $discount['max_uses_client']) {
                            $response['discount_status'] = false;
                            $response['discount_msg'] = "You have reached the maximum uses of this coupon 😔";
                        } else {
                            $price = apply_discount($discount, $invoice['total_price']);
                            $price_diff = $invoice['total_price'] - $price;
                            db_update_row('invoices', ['id' => $invoice_id], ['total_price' => $price, 'discount_id' => $discount['id'], 'discount_amount' => $price_diff]);
                            // if order type is order, update order price
                            if ($invoice['order_type'] == 'order') {
                                if ($_SESSION['currency'] === 'USD') {
                                    $price_eur = $price / get_exchange_rate();
                                } else {
                                    $price_eur = $price;
                                }
                                db_update_row('orders', ['id' => $invoice['order_id']], ['price' => $price, 'price_eur' => $price_eur]);
                            }

                            $response['discount_status'] = true;
                            $response['discount_msg'] = "Discount applied successfully ✅";
                            $response['discount_price'] = $price;
                        }
                    }
                } else {
                    $response['discount_status'] = false;
                    $response['discount_msg'] = "Invalid discount code 😔";
                }
            } else {
                $response['discount_status'] = false;
                $response['discount_msg'] = "Please login in order to apply a discount 😊";
            }
        } else {
            $response['discount_status'] = false;
            $response['discount_msg'] = "Invalid invoice 😔";
        }
        echo json_encode($response);
    }

    public function client_update_referral_code()
    {
        if (!$this->is_client) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Please login first.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (!function_exists('lb_referral_client_is_allowed') || !lb_referral_client_is_allowed((int)CLIENT_ID)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Referral disabled', 'message' => 'Referral access is not enabled for your account.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $customCode = trim((string)($_POST['custom_code'] ?? ''));
        $customCode = function_exists('lb_referral_public_slug') ? lb_referral_public_slug($customCode) : strtolower(preg_replace('/[^a-z0-9-_]+/i', '-', $customCode));
        $customCode = trim($customCode, '-_');

        if ($customCode === '' || strlen($customCode) < 3 || strlen($customCode) > 64 || !preg_match('/^[a-z0-9][a-z0-9-_]{1,62}[a-z0-9]$/i', $customCode)) {
            echo json_encode([
                'validationErrors' => ['custom_code' => 'Use 3-64 characters: letters, numbers, dashes or underscores.'],
                'sendToast' => ['type' => 'danger', 'title' => 'Invalid link', 'message' => 'Please choose a valid custom referral link.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $reserved = ['admin', 'admin-area', 'ajax', 'api', 'assets', 'booster', 'boosters', 'checkout', 'client', 'profile', 'seller', 'seller-area', 'sellers', 'support'];
        if (in_array(strtolower($customCode), $reserved, true)) {
            echo json_encode([
                'validationErrors' => ['custom_code' => 'This link is reserved. Please choose another one.'],
                'sendToast' => ['type' => 'danger', 'title' => 'Reserved link', 'message' => 'This referral link is reserved.'],
                'playSound' => 'error',
            ]);
            return;
        }

        global $db;
        $link = function_exists('lb_referral_get_or_create_link') ? lb_referral_get_or_create_link('client', (int)CLIENT_ID) : false;
        if (!$link) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not load your referral link.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $duplicate = $db->row("SELECT id FROM referral_links WHERE LOWER(code) = LOWER(?) AND id <> ? LIMIT 1", $customCode, (int)$link['id']);
        if ($duplicate) {
            echo json_encode([
                'validationErrors' => ['custom_code' => 'This referral link is already taken.'],
                'sendToast' => ['type' => 'danger', 'title' => 'Already taken', 'message' => 'This referral link is already taken.'],
                'playSound' => 'error',
            ]);
            return;
        }

        db_update_row('referral_links', ['id' => (int)$link['id']], ['code' => $customCode]);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Your referral link was updated.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function client_update_profile()
    {
        if ($this->is_client) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'username' => 'required',
                'email' => 'required|email',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $client = db_get_row('clients', ['id' => CLIENT_ID]);
                if ($client != false) {
                    $birthday = trim((string)($_POST['birthday'] ?? ''));
                    if ($birthday !== '') {
                        $birthdayDate = DateTime::createFromFormat('Y-m-d', $birthday);
                        $birthdayValid = $birthdayDate
                            && $birthdayDate->format('Y-m-d') === $birthday
                            && strtotime($birthday) <= strtotime(date('Y-m-d'));

                        if (!$birthdayValid) {
                            $form_error = ['birthday' => 'Please enter a valid birthday.'];
                        }
                    }

                    $post_data = [
                        'username' => esc($_POST['username']),
                        'email' => esc($_POST['email']),
                        'discord' => esc($_POST['discord']),
                    ];

                    if (!isset($form_error) || $form_error == false) {
                        $post_data['birthday'] = ($birthday !== '') ? esc($birthday) : null;
                    }

                    // check if email is already used by another client if not then update client data
                    $email_check = db_get_row('clients', ['email' => $post_data['email']]);
                    if ((!isset($form_error) || $form_error == false) && ($email_check == false || $email_check['id'] == $client['id'])) {
                        db_update_row('clients', ['id' => CLIENT_ID], $post_data);
                        $form_error = false;
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'primary',
                                'title' => 'Success',
                                'message' => 'Profile updated successfully ✅',
                            ],
                            'playSound' => 'success',
                            'refreshPage' => true,
                        ]);
                    } elseif (!isset($form_error) || $form_error == false) {
                        $form_error = ['email' => 'This email is already used.'];
                    }
                } else {
                    $form_error = ['email' => 'Invalid client.'];
                }
            }

            if ($form_error != false) {
                $this->validationErrors = $form_error;
                echo json_encode(array(
                    'validationErrors' => $this->validationErrors,
                ));
            }
        }
    }

