    public function client_pause_order()
    {
        if ($this->is_client) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'order_id' => 'required|numeric',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $order_id = esc($_POST['order_id']);
                $order = db_get_row('orders', ['id' => $order_id]);
                $booster = db_get_row('boosters', ['id' => $order['booster_id']]);

                if (in_array($order['status'], ['IN_PROGRESS', 'PAID'], true)) {
                    db_update_row('orders', ['id' => $order_id], ['status' => 'PAUSED']);

                    // The booster's open order view only refreshes on order_status_update.
                    if (function_exists('lb_realtime_emit_order')) {
                        lb_realtime_emit_order('order_status_update', $order_id);
                        lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                    }

                    $form_error = false;

                    db_add_row('notifications', [
                        'type' => 'order_paused',
                        'data' => json_encode([
                            'order_id' => base64_encode($order_id),
                            'booster_discord' => base64_encode(db_get_row('boosters', ['id' => $order['booster_id']])['discord']),
                        ]),
                        'is_discord' => false,
                    ]);

                    if (!empty($booster['discord_id'])) {
                        $botToken = DS_BOT_TOKEN;
                        $discordUserId = $booster['discord_id'];
                        $dmChannel = getDMChannelId($botToken, $discordUserId);

                        $orderUrl = BASE_URL . '/booster-area/order/' . $order['id'];

                        if ($dmChannel) {
                            $embed = [
                                "title" => 'YOUR ORDER HAS BEEN PAUSED',
                                "author" => [
                                    "name" => "LoLBoost.GG",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "description" => "Your order #" . $order['id'] . " has been paused by client! 🎉\n\nPlease check your dashboard for more details.\n",
                                "footer" => [
                                    "text" => "LoLBoost.GG - Ranking up never been easier",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "timestamp" => date('c'),
                                "color" => 0x5865F2
                            ];

                            $components = [
                                [
                                    "type" => 1,
                                    "components" => [
                                        [
                                            "type" => 2,
                                            "style" => 5,
                                            "label" => "🔎 View Order",
                                            "url" => $orderUrl
                                        ]
                                    ]
                                ]
                            ];

                            if ($dmChannel && $embed !== null) {
                                $msg = json_encode([
                                    "embeds" => [$embed],
                                    "components" => $components
                                ], JSON_UNESCAPED_SLASHES);

                                sendEmbedDM($botToken, $dmChannel, $msg);
                            }
                        }
                    }

                    echo json_encode([
                        'sendToast' => [
                            'type' => 'primary',
                            'title' => 'Success',
                            'message' => 'Order successfully paused ✅',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ]);
                } else {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Order cannot be paused',
                        ],
                        'playSound' => 'error',
                    ]);
                }
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    public function client_resume_order()
    {
        if ($this->is_client) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'order_id' => 'required|numeric',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $order_id = esc($_POST['order_id']);
                $order = db_get_row('orders', ['id' => $order_id]);

                if ($order['status'] !== 'PAUSED') {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Order is not paused',
                        ],
                        'playSound' => 'error',
                    ]);
                    return;
                }

                $hasBooster = (!empty($order['booster_id']) && (int) $order['booster_id'] > 0);
                $newStatus = $hasBooster ? 'IN_PROGRESS' : 'PAID';

                db_update_row('orders', ['id' => $order_id], ['status' => $newStatus]);

                // The booster's open order view only refreshes on order_status_update.
                if (function_exists('lb_realtime_emit_order')) {
                    lb_realtime_emit_order('order_status_update', $order_id);
                    lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                }

                // DM nur an Booster wenn vorhanden
                if ($hasBooster) {
                    $booster = db_get_row('boosters', ['id' => $order['booster_id']]);

                    if ($booster != false && !empty($booster['discord_id'])) {
                        $botToken = DS_BOT_TOKEN;
                        $discordUserId = $booster['discord_id'];
                        $dmChannel = getDMChannelId($botToken, $discordUserId);

                        $orderUrl = BASE_URL . '/booster-area/order/' . $order['id'];

                        if ($dmChannel) {
                            $embed = [
                                "title" => 'YOUR ORDER HAS BEEN RESUMED',
                                "author" => [
                                    "name" => "LoLBoost.GG",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "description" => "Your order #" . $order['id'] . " has been resumed by client! 🎉\n\nPlease check your dashboard for more details.\n",
                                "footer" => [
                                    "text" => "LoLBoost.GG - Ranking up never been easier",
                                    "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                                ],
                                "timestamp" => date('c'),
                                "color" => 0x5865F2
                            ];

                            $components = [
                                [
                                    "type" => 1,
                                    "components" => [
                                        [
                                            "type" => 2,
                                            "style" => 5,
                                            "label" => "🔎 View Order",
                                            "url" => $orderUrl
                                        ]
                                    ]
                                ]
                            ];

                            if ($dmChannel && $embed !== null) {
                                $msg = json_encode([
                                    "embeds" => [$embed],
                                    "components" => $components
                                ], JSON_UNESCAPED_SLASHES);

                                sendEmbedDM($botToken, $dmChannel, $msg);
                            }
                        }
                    }
                }

                $form_error = false;

                $toastMessage = $hasBooster
                    ? 'Order successfully resumed ✅'
                    : 'Order resumed — no booster assigned, status set to PAID ⚠️';

                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => $toastMessage,
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
                return;
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
