    public function client_riot_id_suggestions()
    {
        global $db;

        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['ok' => false, 'suggestions' => []]);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        $query = trim((string)($_POST['query'] ?? ''));
        $query_length = function_exists('mb_strlen') ? mb_strlen($query, 'UTF-8') : strlen($query);
        if ($order_id <= 0 || $query_length < 2 || $query_length > 64) {
            echo json_encode(['ok' => true, 'suggestions' => []]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'client_id' => (int)CLIENT_ID], 1);
        if (!$order) {
            echo json_encode(['ok' => false, 'suggestions' => []]);
            return;
        }

        $current_options = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $server = strtolower(trim((string)($current_options['server'] ?? '')));

        try {
            $rows = $db->run(
                "SELECT oa.ign AS riot_id,
                        LOWER(COALESCE(oo.server, '')) AS server,
                        MAX(o.id) AS latest_order_id
                   FROM order_accounts oa
                   INNER JOIN orders o ON o.id = oa.order_id
                   LEFT JOIN order_options oo ON oo.order_id = o.id
                  WHERE o.client_id = ?
                    AND oa.ign IS NOT NULL
                    AND TRIM(oa.ign) <> ''
                    AND LOWER(oa.ign) LIKE LOWER(CONVERT(? USING utf8mb4) COLLATE utf8mb4_unicode_ci)
                    AND (CONVERT(? USING utf8mb4) COLLATE utf8mb4_unicode_ci = ''
                         OR LOWER(COALESCE(oo.server, '')) COLLATE utf8mb4_unicode_ci = CONVERT(? USING utf8mb4) COLLATE utf8mb4_unicode_ci)
                  GROUP BY oa.ign, LOWER(COALESCE(oo.server, ''))
                  ORDER BY latest_order_id DESC
                  LIMIT 8",
                (int)CLIENT_ID,
                $query . '%',
                $server,
                $server
            ) ?: [];
        } catch (\Throwable $e) {
            @error_log('[Riot ID suggestions] ' . $e->getMessage());
            echo json_encode(['ok' => false, 'suggestions' => []]);
            return;
        }

        echo json_encode([
            'ok' => true,
            'suggestions' => array_map(static function (array $row): array {
                return [
                    'riot_id' => (string)($row['riot_id'] ?? ''),
                    'server' => strtoupper((string)($row['server'] ?? '')),
                ];
            }, $rows),
        ]);
    }

    public function client_preview_riot_account()
    {
        if (!$this->is_client) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        $riot_id = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string)($_POST['riot_id'] ?? ''))
            : trim((string)($_POST['riot_id'] ?? ''));

        if ($order_id <= 0) {
            echo json_encode(['ok' => false, 'message' => 'Invalid order.']);
            return;
        }

        if ($riot_id === '' || (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id))) {
            echo json_encode(['ok' => false, 'message' => 'Please enter your Riot ID in this format: Faker#1234']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'client_id' => CLIENT_ID], 1);
        if ($order == false) {
            echo json_encode(['ok' => false, 'message' => 'Invalid order.']);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $server = strtolower(trim((string)($order_opts['server'] ?? '')));
        if ($server === '') {
            $server = strtolower(trim((string)($order['server'] ?? '')));
        }
        if ($server === '') {
            $server = 'euw';
        }

        $server_labels = [
            'na' => 'NA', 'euw' => 'EUW', 'eune' => 'EUNE', 'br' => 'BR',
            'lan' => 'LAN', 'las' => 'LAS', 'oce' => 'OCE', 'tr' => 'TR',
            'ru' => 'RU', 'jp' => 'JP', 'kr' => 'KR', 'pbe' => 'PBE',
            'vn' => 'VN', 'ph' => 'PH', 'sg' => 'SG', 'th' => 'TH', 'tw' => 'TW',
        ];
        $server_candidates = ['euw', 'eune', 'na', 'br', 'lan', 'las', 'oce', 'tr', 'ru', 'jp', 'kr', 'vn', 'ph', 'sg', 'th', 'tw'];
        $order_server_label = $server_labels[$server] ?? strtoupper($server);

        $find_account_on_server = function (string $try_server) use ($riot_id) {
            $puuid = function_exists('riot_get_puuid') ? riot_get_puuid($riot_id, $try_server) : null;
            $summoner = $puuid && function_exists('riot_get_summoner_profile') ? riot_get_summoner_profile($puuid, $try_server) : null;
            if (!$puuid || !$summoner) {
                return null;
            }
            return ['puuid' => $puuid, 'summoner' => $summoner];
        };

        try {
            $found = $find_account_on_server($server);
            if ($found) {
                $summoner = $found['summoner'];
                $profileIconId = $summoner['profileIconId'] ?? null;

                echo json_encode([
                    'ok' => true,
                    'account' => [
                        'riot_id' => $riot_id,
                        'server' => $server,
                        'puuid' => $found['puuid'],
                        'summoner_level' => isset($summoner['summonerLevel']) ? (int)$summoner['summonerLevel'] : null,
                        'profile_icon_id' => $profileIconId !== null ? (int)$profileIconId : null,
                        'profile_icon_url' => function_exists('riot_profile_icon_url') ? riot_profile_icon_url($profileIconId) : null,
                    ]
                ]);
                return;
            }

            foreach ($server_candidates as $try_server) {
                if ($try_server === $server) {
                    continue;
                }

                $other_found = $find_account_on_server($try_server);
                if (!$other_found) {
                    continue;
                }

                $summoner = $other_found['summoner'];
                $profileIconId = $summoner['profileIconId'] ?? null;
                $found_server_label = $server_labels[$try_server] ?? strtoupper($try_server);

                echo json_encode([
                    'ok' => false,
                    'reason' => 'wrong_server',
                    'message' => "This order is for {$order_server_label}, but this Riot ID was found on {$found_server_label}. Please contact support to change the order server. Saving is disabled.",
                    'order_server' => $server,
                    'order_server_label' => $order_server_label,
                    'found_server' => $try_server,
                    'found_server_label' => $found_server_label,
                    'account' => [
                        'riot_id' => $riot_id,
                        'server' => $try_server,
                        'puuid' => $other_found['puuid'],
                        'summoner_level' => isset($summoner['summonerLevel']) ? (int)$summoner['summonerLevel'] : null,
                        'profile_icon_id' => $profileIconId !== null ? (int)$profileIconId : null,
                        'profile_icon_url' => function_exists('riot_profile_icon_url') ? riot_profile_icon_url($profileIconId) : null,
                    ]
                ]);
                return;
            }

            echo json_encode([
                'ok' => false,
                'reason' => 'not_found_on_order_server',
                'order_server' => $server,
                'order_server_label' => $order_server_label,
                'message' => "No account found on {$order_server_label}. This order is for {$order_server_label}; please enter the Riot ID for this server or contact support to change the order server."
            ]);
            return;
        } catch (\Throwable $e) {
            echo json_encode([
                'ok' => false,
                'message' => "No account found on {$order_server_label}. This order is for {$order_server_label}; please enter the Riot ID for this server or contact support to change the order server."
            ]);
            return;
        }
    }

    public function client_update_order_account()
    {
        if ($this->is_client) {
            $order_id = intval($_POST['order_id']);
            $order = db_get_row('orders', ['id' => $order_id, 'client_id' => CLIENT_ID]);
            if ($order != false) {
                $order_account = db_get_row('order_accounts', ['order_id' => $order_id]);
                $raw_riot_id = function_exists('lb_normalize_riot_id')
                    ? lb_normalize_riot_id((string)($_POST['ign'] ?? ''))
                    : trim((string)($_POST['ign'] ?? ''));

                // LoL orders must have a real Riot ID. This server-side Riot API check prevents
                // invalid Riot IDs from being saved if the modal/front-end JS is bypassed.
                $is_lol_order = false; // Riot tracking/verification removed.
                if ($is_lol_order) {
                    if ($raw_riot_id === '' || (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($raw_riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $raw_riot_id))) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Riot ID not found',
                                'message' => 'Riot ID not found',
                            ],
                            'validationErrors' => ['ign' => 'Riot ID not found'],
                            'playSound' => 'error',
                        ]);
                        return;
                    }

                    $order_opts_for_riot = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
                    $riot_server = strtolower(trim((string)($order_opts_for_riot['server'] ?? '')));
                    if ($riot_server === '') {
                        $riot_server = 'euw';
                    }

                    $server_labels = [
                        'na' => 'NA', 'euw' => 'EUW', 'eune' => 'EUNE', 'br' => 'BR',
                        'lan' => 'LAN', 'las' => 'LAS', 'oce' => 'OCE', 'tr' => 'TR',
                        'ru' => 'RU', 'jp' => 'JP', 'kr' => 'KR', 'pbe' => 'PBE',
                        'vn' => 'VN', 'ph' => 'PH', 'sg' => 'SG', 'th' => 'TH', 'tw' => 'TW',
                    ];
                    $server_candidates = ['euw', 'eune', 'na', 'br', 'lan', 'las', 'oce', 'tr', 'ru', 'jp', 'kr', 'vn', 'ph', 'sg', 'th', 'tw'];
                    $order_server_label = $server_labels[$riot_server] ?? strtoupper($riot_server);

                    $find_account_on_server = function (string $try_server) use ($raw_riot_id) {
                        $puuid = function_exists('riot_get_puuid') ? riot_get_puuid($raw_riot_id, $try_server) : null;
                        $summoner = $puuid && function_exists('riot_get_summoner_profile') ? riot_get_summoner_profile($puuid, $try_server) : null;
                        return ($puuid && $summoner) ? ['puuid' => $puuid, 'summoner' => $summoner] : null;
                    };

                    try {
                        $found_on_order_server = $find_account_on_server($riot_server);
                        if (!$found_on_order_server) {
                            foreach ($server_candidates as $try_server) {
                                if ($try_server === $riot_server) {
                                    continue;
                                }
                                $found_on_other_server = $find_account_on_server($try_server);
                                if (!$found_on_other_server) {
                                    continue;
                                }

                                $found_server_label = $server_labels[$try_server] ?? strtoupper($try_server);
                                $message = "This order is for {$order_server_label}, but this Riot ID was found on {$found_server_label}. Please contact support to change the order server. Saving is disabled.";
                                echo json_encode([
                                    'sendToast' => [
                                        'type' => 'danger',
                                        'title' => 'Wrong server',
                                        'message' => $message,
                                    ],
                                    'validationErrors' => ['ign' => $message],
                                    'reason' => 'wrong_server',
                                    'order_server' => $riot_server,
                                    'order_server_label' => $order_server_label,
                                    'found_server' => $try_server,
                                    'found_server_label' => $found_server_label,
                                    'playSound' => 'error',
                                ]);
                                return;
                            }

                            $message = "No account found on {$order_server_label}. This order is for {$order_server_label}; please enter the Riot ID for this server or contact support to change the order server.";
                            echo json_encode([
                                'sendToast' => [
                                    'type' => 'danger',
                                    'title' => "No {$order_server_label} account found",
                                    'message' => $message,
                                ],
                                'validationErrors' => ['ign' => $message],
                                'reason' => 'not_found_on_order_server',
                                'order_server' => $riot_server,
                                'order_server_label' => $order_server_label,
                                'playSound' => 'error',
                            ]);
                            return;
                        }
                    } catch (\Throwable $e) {
                        $message = "No account found on {$order_server_label}. This order is for {$order_server_label}; please enter the Riot ID for this server or contact support to change the order server.";
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => "No {$order_server_label} account found",
                                'message' => $message,
                            ],
                            'validationErrors' => ['ign' => $message],
                            'playSound' => 'error',
                        ]);
                        return;
                    }
                }

                $post_data = [
                    'ign' => esc($raw_riot_id !== '' ? $raw_riot_id : (string)($order_account['ign'] ?? '')),
                    'login' => esc($_POST['login']),
                    'password' => esc($_POST['password']),
                ];

                // LoL account preferences can be updated together with the login details.
                $has_any_option = isset($_POST['vpn_country'])
                    || isset($_POST['flash_position'])
                    || isset($_POST['is_offline_mode']);
                if ($has_any_option) {
                    $opt_row = db_get_row('order_options', ['order_id' => $order_id]);
                    $opt_data = [
                        'vpn_country' => isset($_POST['vpn_country']) ? esc($_POST['vpn_country']) : '',
                        'flash_position' => isset($_POST['flash_position']) ? esc($_POST['flash_position']) : '',
                        'is_offline_mode' => isset($_POST['is_offline_mode']) ? intval($_POST['is_offline_mode']) : 0,
                    ];

                    if ($opt_row != false) {
                        db_update_row('order_options', ['order_id' => $order_id], $opt_data);
                    } else {
                        $opt_data['order_id'] = $order_id;
                        db_insert_row('order_options', $opt_data);
                    }
                }
                if ($order_account != false) {
                    // update row
                    db_update_row('order_accounts', ['order_id' => $order_id], $post_data);
                } else {
                    // create new row
                    $post_data['order_id'] = $order_id;
                    db_insert_row('order_accounts', $post_data);
                }

                // The Riot ID is usually added after checkout, so this is the first moment the
                // real start rank can be read. No-op once it is already Riot-verified.
                if (function_exists('lb_order_capture_riot_start_rank')) {
                    lb_order_capture_riot_start_rank($order_id);
                }

                if (function_exists('lb_realtime_emit')) {
                    lb_realtime_emit_order('order_account_update', $order_id);
                }

                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => 'Order account updated successfully ✅',
                    ],
                    'playSound' => 'success',
                    'orderAccountUpdated' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invalid order 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    public function client_update_order_options()
    {
        // update flash_position, offline mode and vpn_country (client edits are pending until admin applies)
        if ($this->is_client) {
            $order_id = intval($_POST['order_id']);
            $order = db_get_row('orders', ['id' => $order_id, 'client_id' => CLIENT_ID]);

