                    'vpn_country'     => isset($_POST['vpn_country']) ? esc($_POST['vpn_country']) : '',
                    'is_offline_mode' => isset($_POST['is_offline_mode']) ? intval($_POST['is_offline_mode']) : 0,
                ];

                // UPSERT: some orders have no row in order_options yet
                $opt_row = db_get_row('order_options', ['order_id' => $order_id], true);

                if ($opt_row != false) {
                    db_update_row('order_options', ['order_id' => $order_id], $post_data);
                } else {
                    $post_data['order_id'] = $order_id;
                    db_insert_row('order_options', $post_data);
