                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Saved',
                        'message' => 'Order account updated successfully ✅',
                    ],
                    'playSound' => 'success',
                    // Don\'t refresh because customer view shows the original snapshot until admin applies changes
                    'refreshPage' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invalid order 😔',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    public function client_send_tip()
    {
        // Tip checkout must also work for guests. The checkout page handles login/register,
        // so this endpoint always returns valid JSON and redirects to a checkout invoice.
        try {
            $amount_raw = $_POST['amount'] ?? 0;
            $amount = util_format_price_db($amount_raw);
            $currency = $_SESSION['currency'] ?? 'EUR';
            $order_id = intval($_POST['order_id'] ?? 0);
            $note = esc($_POST['note'] ?? '');
            $booster_id = intval($_POST['booster_id'] ?? 0);

            if ($booster_id <= 0 || $amount <= 0) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invalid tip data.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            $client_id = ($this->is_client && defined('CLIENT_ID') && (int)CLIENT_ID > 0) ? (int)CLIENT_ID : null;
            $sender_name = 'Guest';

            if ($client_id !== null) {
                $client = db_get_row('clients', ['id' => $client_id]);
                if (!empty($client['username'])) {
                    $sender_name = $client['username'];
                }
            }

            $tip_id = db_add_row('tips', [
                'booster_id' => $booster_id,
                'sender' => $sender_name,
                'sender_id' => $client_id ?: 0,
                'amount' => $amount,
                'currency' => $currency,
                'status' => 0,
                'description' => $note,
                'order_id' => $order_id,
            ]);

            if (!$tip_id) {
                throw new \RuntimeException('Could not create tip row.');
            }

            $uuid = Uuid::uuid4()->toString();
            $price_eur = ($currency === 'EUR') ? $amount : (int)round($amount / get_exchange_rate());

            $invoice_data = [
                'uuid' => $uuid,
                'order_id' => $tip_id,
                'booster_id' => $booster_id,
                'order_type' => 'tip',
                'price' => $amount,
                'price_eur' => $price_eur,
                'total_price' => $amount,
                'currency' => $currency,
                'description' => 'Tip for booster #' . $booster_id,
                'client_id' => $client_id,
            ];

            if (function_exists('lb_referral_attach_snapshot_to_invoice_data')) {
                $invoice_data = lb_referral_attach_snapshot_to_invoice_data($invoice_data);
            }

            $invoice_id = db_add_row('invoices', $invoice_data);

            if (!$invoice_id) {
                throw new \RuntimeException('Could not create tip invoice.');
            }

            echo json_encode([
                'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
            ]);
            return;
        } catch (\Throwable $e) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Could not create checkout for this tip.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }
    }
    public function client_order_chat_send()
    {
        if ($this->is_client) {

            $order_id = (int)($_POST['order_id'] ?? 0);
            $order = db_get_row('orders', ['id' => $order_id]);
            $message = esc($_POST['message'] ?? '');

                        // Optional image upload
            $image_url = null;
            $fileKey = null;
            if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
                $fileKey = 'chat_image';
            } elseif (isset($_FILES['image_url']) && !empty($_FILES['image_url']['tmp_name'])) { // backwards compatibility
                $fileKey = 'image_url';
            }

            if ($fileKey) {
                $image_url = upload_image($_FILES[$fileKey], 'private/chat_images');
                if ($image_url === false) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Image upload failed (file type not allowed or server rejected it).',
                        ],
                        'playSound' => 'error',
                    ]);
                    exit();
                }
            }
            if ($message === '' && !$image_url) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please type a message or attach an image.',
                    ],
                    'playSound' => 'error',
                ]);
                exit();
            }

            if ($message !== '') {
                $chat_data = [
                    'message' => $message,
                    'message_type' => 'text',
                ];
                chat_insert_message($order_id, $chat_data, CLIENT_DATA, 'client');
            }

            if ($image_url) {
                $chat_data = [
                    'message' => $image_url,
                    'message_type' => 'image',
                ];
                chat_insert_message($order_id, $chat_data, CLIENT_DATA, 'client');
            }

            // Realtime: push chat_update so the booster's order view refreshes instantly.
            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit_order('chat_update', $order_id);
            }

            // Notify booster (existing behavior)
            if ($order && !empty($order['booster_id'])) {
                db_insert_row('notifications', [
                    'type' => 'ds_msg_notif_booster',
                    'recipient' => 'booster',
                    'recipient_id' => $order['booster_id'],
                    'data' => json_encode([
                        'order_id' => base64_encode($order_id),
                        'client_username' => base64_encode(CLIENT_DATA['username']),
                    ])
                ]);
            }

            echo json_encode(["resetForm" => true, "reFocus" => true]);
            exit();
        }
    }

    public function client_forgot_password()
    {
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'email' => 'required'
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {


            $email = esc($_POST["email"]);

            $data = db_get_row('clients', ['email' => $email]);

            if ($data != false) {

                // generate uuid4
                $uuid4 = Uuid::uuid4();
                $token = $uuid4->toString();
                db_update_row('clients', ['id' => $data['id']], ['recovery_id' => $token]);
                $form_error = false;
                db_add_row('notifications', [
                    'type' => 'client_password_recovery',
                    'recipient' => 'client',
                    'recipient_id' => $data['id'],
                    'data' => json_encode(['token' => base64_encode($token)]),
                    'is_email' => 1,
                ]);
                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => 'Password recovery email sent successfully',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
            } else {
                $form_error = ["email" => "Email does not exist."];
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

    public function client_reset_password()
    {
        //validate password
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'password' => 'required|min:6',
        ]);

        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            $form_error = $errors->firstOfAll();
        } else {
            $password = esc($_POST['password']);
            $token = esc($_POST['recovery_id']);
            $client = db_get_row('clients', ['recovery_id' => $token]);
            $form_error = false;
            if (!empty($client)) {
                $password_hash = sha1($password);
                db_update_row('clients', ['id' => $client['id']], ['password' => $password_hash, 'recovery_id' => null]);
                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => 'Password reset successfully',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Invalid token',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }

        if ($form_error != false) {
            $this->validationErrors = $form_error;
            echo json_encode(array(
                'validationErrors' => $this->validationErrors,
            ));
        }
    }

    public function client_upload_profile_picture()
    {
        if ($this->is_client) {
            $image_url = $_FILES['image_url'];
            if ($image_url['name'] != '') {
                $image_url = upload_image($image_url, 'icons/');
                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                }
                db_update_row('clients', ['id' => CLIENT_ID], ['icon' => $image_url]);
                echo json_encode([
                    "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Profile picture updated successfully."],
                    "playSound" => "success",
                    "refreshPage" => true
                ]);
            } else {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
            }
        }
    }

