    private function lb_preview_riot_account_payload($order_id, $riot_id, $server_override = null)
    {
        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $server = trim((string)($server_override !== null ? $server_override : ($order_opts['server'] ?? '')));
        if ($server === '') {
            $server = 'euw';
        }

        $puuid = function_exists('riot_get_puuid') ? riot_get_puuid($riot_id, $server) : null;
        if (!$puuid) {
            return null;
        }

        $summoner = function_exists('riot_get_summoner_profile') ? riot_get_summoner_profile($puuid, $server) : null;
        if (!$summoner) {
            return null;
        }

        $profileIconId = $summoner['profileIconId'] ?? null;

        return [
            'riot_id' => $riot_id,
            'server' => $server,
            'puuid' => $puuid,
            'summoner_level' => isset($summoner['summonerLevel']) ? (int)$summoner['summonerLevel'] : null,
            'profile_icon_id' => $profileIconId !== null ? (int)$profileIconId : null,
            'profile_icon_url' => function_exists('riot_profile_icon_url') ? riot_profile_icon_url($profileIconId) : null,
        ];
    }

    public function admin_preview_riot_account()
    {
        if (!$this->is_admin) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        $riot_id = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string)($_POST['riot_id'] ?? ''))
            : trim((string)($_POST['riot_id'] ?? ''));

        if ($order_id <= 0 || $riot_id === '' || (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id))) {
            echo json_encode(['ok' => false, 'message' => 'Use Riot ID format: Name#TAG. Admins can still save manually from the edit form.']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(['ok' => false, 'message' => 'Order not found.']);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $server = strtolower(trim((string)($_POST['server'] ?? ($order_opts['server'] ?? ''))));
        if ($server === '') {
            $server = 'euw';
        }

        $server_labels = [
            'na' => 'NA', 'euw' => 'EUW', 'eune' => 'EUNE', 'br' => 'BR',
            'lan' => 'LAN', 'las' => 'LAS', 'oce' => 'OCE', 'tr' => 'TR',
            'ru' => 'RU', 'jp' => 'JP', 'kr' => 'KR', 'pbe' => 'PBE',
            'vn' => 'VN', 'ph' => 'PH', 'sg' => 'SG', 'th' => 'TH', 'tw' => 'TW',
        ];
        $server_candidates = ['euw', 'eune', 'na', 'br', 'lan', 'las', 'oce', 'tr', 'ru', 'jp', 'kr', 'vn', 'ph', 'sg', 'th', 'tw'];
        $order_server_label = $server_labels[$server] ?? strtoupper($server);

        try {
            $account = $this->lb_preview_riot_account_payload($order_id, $riot_id, $server);
            if ($account) {
                echo json_encode(['ok' => true, 'account' => $account]);
                return;
            }

            foreach ($server_candidates as $try_server) {
                if ($try_server === $server) {
                    continue;
                }

                $other_account = $this->lb_preview_riot_account_payload($order_id, $riot_id, $try_server);
                if (!$other_account) {
                    continue;
                }

                $found_server_label = $server_labels[$try_server] ?? strtoupper($try_server);
                echo json_encode([
                    'ok' => false,
                    'reason' => 'wrong_server',
                    'message' => "This Riot ID was not found on {$order_server_label}, but was found on {$found_server_label}. Admin manual save is allowed if you intentionally want to override it.",
                    'order_server' => $server,
                    'order_server_label' => $order_server_label,
                    'found_server' => $try_server,
                    'found_server_label' => $found_server_label,
                    'account' => $other_account,
                ]);
                return;
            }

            echo json_encode([
                'ok' => false,
                'reason' => 'not_found_on_order_server',
                'order_server' => $server,
                'order_server_label' => $order_server_label,
                'message' => "No account found on {$order_server_label}. Admin manual save is allowed if Riot API cannot verify it.",
            ]);
            return;
        } catch (\Throwable $e) {
            echo json_encode([
                'ok' => false,
                'message' => "Lookup failed. Admin manual save is allowed if Riot API cannot verify it.",
            ]);
            return;
        }
    }

    public function booster_preview_riot_account()
    {
        // Used by both the booster Duo modal and the admin Match History backfill UI.
        // Admins may preview any order; boosters may only preview their assigned order.
        if (!$this->is_booster && !$this->is_admin) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        $riot_id = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string)($_POST['riot_id'] ?? ''))
            : trim((string)($_POST['riot_id'] ?? ''));

        if ($order_id <= 0 || $riot_id === '' || (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id))) {
            echo json_encode(['ok' => false, 'message' => 'Riot ID not found']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(['ok' => false, 'message' => 'Order not found.']);
            return;
        }

        if (!$this->is_admin && (!defined('BOOSTER_ID') || (int)($order['booster_id'] ?? 0) !== (int)BOOSTER_ID)) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        try {
            $account = $this->lb_preview_riot_account_payload($order_id, $riot_id);
            if (!$account) {
                echo json_encode(['ok' => false, 'message' => 'Riot ID not found']);
                return;
            }

            echo json_encode(['ok' => true, 'account' => $account]);
            return;
        } catch (\Throwable $e) {
            echo json_encode(['ok' => false, 'message' => 'Riot ID not found']);
            return;
        }
    }

    public function booster_update_order_riot_id()
    {
        // Also allow admins to save a missing client Riot ID from the Match History UI.
        if (!$this->is_booster && !$this->is_admin) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = intval($_POST['order_id'] ?? 0);
        $riot_id = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string)($_POST['riot_id'] ?? ''))
            : trim((string)($_POST['riot_id'] ?? ''));

        if ($order_id <= 0 || $riot_id === '' || (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id))) {
            echo json_encode(['success' => false, 'message' => 'Riot ID not found']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        if (!$this->is_admin && (!defined('BOOSTER_ID') || (int)($order['booster_id'] ?? 0) !== (int)BOOSTER_ID)) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_account = db_get_row('order_accounts', ['order_id' => $order_id], 1);

        try {
            $account = $this->lb_preview_riot_account_payload($order_id, $riot_id);
            if (!$account) {
                echo json_encode(['success' => false, 'message' => 'Riot ID not found']);
                return;
            }

            if ($order_account != false) {
                db_update_row('order_accounts', ['order_id' => $order_id], ['ign' => esc($riot_id)]);
            } else {
                db_insert_row('order_accounts', [
                    'order_id' => $order_id,
                    'ign' => esc($riot_id),
                    'login' => '',
                    'password' => '',
                ]);
            }

            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit_order('order_account_update', $order_id);
            }

            echo json_encode([
                'success' => true,
                'message' => 'Riot ID saved successfully.',
                'account' => [
                    'ign' => $riot_id,
                    'riot_id' => $riot_id,
                    'profile_icon_url' => $account['profile_icon_url'] ?? null,
                    'summoner_level' => $account['summoner_level'] ?? null,
                    'server' => $account['server'] ?? null,
                ],
            ]);
            return;
        } catch (\Throwable $e) {
            echo json_encode(['success' => false, 'message' => 'Riot ID not found']);
            return;
        }
    }

    /**
     * booster_set_duo_account
     * Saves the booster's own Riot ID for a Duo order so games can be tracked
     * from the booster's account (better KDA/champion accuracy).
     * POST: order_id, riot_id  (use riot_id='' to clear)
     */
    public function booster_set_duo_account()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = (int) ($_POST['order_id'] ?? 0);
        $riot_id  = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string) ($_POST['riot_id'] ?? ''))
            : trim((string) ($_POST['riot_id'] ?? ''));

        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order.']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        if (empty($order_opts['is_duo'])) {
            echo json_encode(['success' => false, 'message' => 'This is not a Duo order.']);
            return;
        }

        // Allow clearing
        if ($riot_id === '') {
            global $db;
            try { $db->run("ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {}
            if (function_exists('riot_ensure_order_progress_duo_columns')) {
                riot_ensure_order_progress_duo_columns($db);
            }
            // Keep last_match_id so re-linking later doesn't re-import old matches.
            db_update_row('order_progress', ['order_id' => $order_id], [
                'booster_ign'        => null,
                'booster_puuid'      => null,
                'booster_ign_set_at' => null,
            ]);
            echo json_encode(['success' => true, 'cleared' => true, 'message' => 'Duo account removed.']);
            return;
        }

        if (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id)) {
            echo json_encode(['success' => false, 'message' => 'Invalid Riot ID format. Use: Name#TAG']);
            return;
        }

        $server = trim((string) ($order_opts['server'] ?? 'euw'));

        try {
            $account = $this->lb_preview_riot_account_payload($order_id, $riot_id);
            if (!$account) {
                echo json_encode(['success' => false, 'message' => 'Riot ID not found. Please check name and tag.']);
                return;
            }

            $puuid = function_exists('riot_get_puuid') ? (string)(riot_get_puuid($riot_id, $server) ?? '') : '';

            global $db;
            if (function_exists('riot_ensure_order_progress_duo_columns')) {
                riot_ensure_order_progress_duo_columns($db);
            }

            // Ensure booster_ign_set_at column exists for duo-account time-range tracking
            if (isset($db)) { try { $db->run("ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {} }

            $duo_set_at = date('Y-m-d H:i:s');
            $progress = db_get_row('order_progress', ['order_id' => $order_id], 1);
            if (empty($progress)) {
                db_add_row('order_progress', [
                    'order_id'           => $order_id,
                    'booster_ign'        => $riot_id,
                    'booster_puuid'      => $puuid !== '' ? $puuid : null,
                    'last_match_id'      => null,
                    'booster_ign_set_at' => $duo_set_at,
                ]);
            } else {
                db_update_row('order_progress', ['order_id' => $order_id], [
                    'booster_ign'        => $riot_id,
                    'booster_puuid'      => $puuid !== '' ? $puuid : null,
                    'last_match_id'      => null,  // reset cursor so sync picks up from booster_ign_set_at
                    'booster_ign_set_at' => $duo_set_at,
                ]);
            }

            echo json_encode([
                'success' => true,
                'message' => 'Duo account saved. Games will be tracked from your account.',
                'account' => [
                    'ign'              => $riot_id,
                    'profile_icon_url' => $account['profile_icon_url'] ?? null,
                    'summoner_level'   => $account['summoner_level']   ?? null,
                    'server'           => $account['server']           ?? $server,
                ],
            ]);
        } catch (\Throwable $e) {
            echo json_encode(['success' => false, 'message' => 'Riot ID not found. Please check name and tag.']);
        }
    }


    /**
     * admin_set_duo_account
     * Admin version of booster_set_duo_account, used by Match History backfill
     * to attach the confirmed Duo/booster Riot ID to an order.
     * POST: order_id, riot_id  (use riot_id='' to clear)
     */
    public function admin_set_duo_account()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = (int) ($_POST['order_id'] ?? 0);
        $riot_id  = function_exists('lb_normalize_riot_id')
            ? lb_normalize_riot_id((string) ($_POST['riot_id'] ?? ''))
            : trim((string) ($_POST['riot_id'] ?? ''));

        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order.']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];

        global $db;
        if (function_exists('riot_ensure_order_progress_duo_columns')) {
            riot_ensure_order_progress_duo_columns($db);
        }
        try { $db->run("ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {}

        if ($riot_id === '') {
            db_update_row('order_progress', ['order_id' => $order_id], [
                'booster_ign'        => null,
                'booster_puuid'      => null,
                'booster_ign_set_at' => null,
            ]);
            echo json_encode(['success' => true, 'cleared' => true, 'message' => 'Duo account removed.']);
            return;
        }

        if (function_exists('lb_is_valid_riot_id') ? !lb_is_valid_riot_id($riot_id) : !preg_match('/^[^#]{2,32}#[^#]{2,16}$/u', $riot_id)) {
            echo json_encode(['success' => false, 'message' => 'Invalid Riot ID format. Use: Name#TAG']);
            return;
        }

        $server = trim((string) ($order_opts['server'] ?? 'euw'));
        if ($server === '') $server = 'euw';

        try {
            $account = $this->lb_preview_riot_account_payload($order_id, $riot_id);
            if (!$account) {
                echo json_encode(['success' => false, 'message' => 'Riot ID not found. Please check name and tag.']);
                return;
            }

            $puuid = function_exists('riot_get_puuid') ? (string)(riot_get_puuid($riot_id, $server) ?? '') : '';
            $duo_set_at = date('Y-m-d H:i:s');
            $payload = [
                'booster_ign'        => $riot_id,
                'booster_puuid'      => $puuid !== '' ? $puuid : null,
                'last_match_id'      => null,
                'booster_ign_set_at' => $duo_set_at,
            ];

            $progress = db_get_row('order_progress', ['order_id' => $order_id], 1);
            if (empty($progress)) {
                $payload['order_id'] = $order_id;
                db_add_row('order_progress', $payload);
            } else {
                db_update_row('order_progress', ['order_id' => $order_id], $payload);
            }

            echo json_encode([
                'success' => true,
                'message' => 'Duo account saved. Games can now be synced from this account.',
                'account' => [
                    'ign'              => $riot_id,
                    'riot_id'          => $riot_id,
                    'profile_icon_url' => $account['profile_icon_url'] ?? null,
                    'summoner_level'   => $account['summoner_level']   ?? null,
                    'server'           => $account['server']           ?? $server,
                    'puuid'            => $puuid !== '' ? $puuid : ($account['puuid'] ?? null),
                ],
            ]);
        } catch (\Throwable $e) {
            echo json_encode(['success' => false, 'message' => 'Riot ID not found. Please check name and tag.']);
        }
    }

    public function admin_update_order_riot_id()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        // Reuse the same save flow. booster_update_order_riot_id now supports admin safely.
        $this->booster_update_order_riot_id();
    }

    /**
     * booster_get_duo_account
     * Returns the currently saved booster Riot ID for a duo order.
     * POST: order_id
     */
    public function booster_get_duo_account()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $order_id = (int) ($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order.']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
        if (empty($order)) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        $progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];
        $ign = trim((string) ($progress['booster_ign'] ?? ''));

        echo json_encode([
            'success'     => true,
            'booster_ign' => $ign !== '' ? $ign : null,
        ]);
    }

    public function booster_order_account_get()
    {
        if ($this->is_booster) {
            $order_id = intval($_POST['order_id'] ?? 0);

            if ($order_id <= 0) {
                echo json_encode(['success' => false, 'msg' => 'Missing order_id']);
                exit();
            }

            // order holen (für security / booster_id check)
            $order = db_get_row('orders', ['id' => $order_id]);
            if ($order == false) {
                echo json_encode(['success' => false, 'msg' => 'Order not found']);
                exit();
            }

            // nur assigned booster darf es sehen
            if (!defined('BOOSTER_ID') || (int) ($order['booster_id'] ?? 0) !== (int) BOOSTER_ID) {
                echo json_encode(['success' => false, 'msg' => 'Not allowed']);
                exit();
            }

            // account daten aus order_accounts holen (eine Zeile pro order)
            $acc = db_get_row('order_accounts', ['order_id' => $order_id]) ?: [];

            echo json_encode([
                'success' => true,
                'data' => [
                    'ign' => (string) ($acc['ign'] ?? ''),
                    'login' => (string) ($acc['login'] ?? ''),
                    'password' => (string) ($acc['password'] ?? ''),
                ]
            ]);
            exit();
        }
    }

    public function admin_order_account_get()
    {
        if (!$this->is_admin) return;
        $order_id = intval($_POST['order_id'] ?? 0);
        if ($order_id <= 0 || db_get_row('orders', ['id' => $order_id]) == false) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }
        $acc = db_get_row('order_accounts', ['order_id' => $order_id]) ?: [];
        echo json_encode(['success' => true, 'data' => [
            'login' => (string)($acc['login'] ?? ''),
            'password' => (string)($acc['password'] ?? ''),
        ]]);
    }

    public function booster_complete_order()
    {
        if (!$this->is_booster) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Unauthorized."]]);
            return;
        }

        global $db;

        $order_id = (int) esc($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order not found."]]);
            return;
        }
        if ($order['status'] === 'PAUSED') {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order is paused."]]);
            return;
        }
        if ($order['status'] !== 'IN_PROGRESS') {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order is not in progress."]]);
            return;
        }

        $order_opts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $order_acc  = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
        $form       = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)]);
        $form_type  = $form != false ? (string)$form['type'] : '';

        $form_id    = (int)($order['form_id'] ?? 0);
        // is_duo is stored in order_options, not in orders — fallback to orders.is_duo for safety
        $is_duo     = (int)($order_opts['is_duo'] ?? $order['is_duo'] ?? 0) === 1;

        // Completion proof rules:
        // - These form IDs are always admin-approved, so proof is mandatory.
        // - LoL Rank Boost solo orders (form_id 1 + is_duo 0) also always need proof.
        // - All other Riot-trackable orders try automatic completion first; if that fails, proof becomes mandatory.
        $manual_approval_screenshot_form_ids = [5, 6, 7, 8, 16, 21, 22, 23, 24, 25, 27, 15, 17];
        $is_multi_booster_team = in_array($form_id, [4, 19], true)
            && function_exists('lb_multi_booster_required_count')
            && lb_multi_booster_required_count($order_id) > 1;
        // A single booster must never auto-complete and receive the entire 50%
        // pool of an order booked for multiple boosters. Team orders are
        // finalized once by an admin and paid through the shared-pool path.
        $force_manual_approval = in_array($form_id, $manual_approval_screenshot_form_ids, true)
            || $is_multi_booster_team;
        $is_solo_rank_boost = ($form_id === 1 && !$is_duo);

        $tracking_forms = ['rank', 'win', 'arena', 'match', 'placement', 'normal', 'clash', 'pro-games'];
        $riot_id        = trim((string)($order_acc['ign'] ?? ''));
        $has_riot_id    = $riot_id !== '';
        $tracking_available = in_array($form_type, $tracking_forms, true) && $has_riot_id;
        $can_track      = $tracking_available && !$force_manual_approval;

        $requires_completion_screenshot = true; // Always required for chargeback proof

        // ── Screenshot upload (always required) ──
        $file_url = null;
        if (!empty($_FILES['file_url']['name'])) {
            $uploaded = upload_image($_FILES['file_url'], 'private/orders/' . date('Y-m'));
            if ($uploaded === false) {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type for screenshot."]]);
                return;
            }
            $file_url = $uploaded;
            db_delete_rows('order_screenshots', ['order_id' => $order_id]);
            db_add_row('order_screenshots', ['order_id' => $order_id, 'file_url' => $file_url, 'booster_id' => BOOSTER_ID]);
        }

        $existing_screenshot = db_get_row('order_screenshots', ['order_id' => $order_id], 1) ?: [];
        $existing_file_url = trim((string)($order['file_url'] ?? ($existing_screenshot['file_url'] ?? '')));

        // Screenshot is ALWAYS required — needed as chargeback proof regardless of tracking.
        if ($file_url === null && $existing_file_url === '') {
            $required_message = "Please upload a completion screenshot as proof before completing the order.";
            echo json_encode([
                "sendToast" => [
                    "type" => "danger",
                    "title" => "Screenshot required",
                    "message" => $required_message
                ],
                "playSound" => "error",
                "trackingResult" => "screenshot_required",
                "requireScreenshot" => true,
                "message" => $required_message,
            ]);
            return;
        }


        // ── Tracking-based forms: try to verify via Riot API ──
        if ($can_track) {
            // Sync latest progress from Riot
            try {
                $order_progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];
                // Never throttled: this is the final rank/match snapshot of the order and
                // decides payout and the customer-facing result.
                $fresh = riot_sync_order_progress($order_id, $order, $order_opts, $order_acc, $order_progress, $db, 0);
            } catch (\Throwable $e) {
                $fresh = null;
            }

            $goal_reached = false;

            if ($fresh !== null) {
                if ($form_type === 'rank') {
                    // Goal: current tier/division >= end tier/division.
                    // Riot/order_progress can store current_tier/current_division as text (e.g. "GOLD" / "III"),
                    // while order_options stores the target as numeric values (Gold=4, III=2).
                    // Do not cast Riot text directly to int, otherwise "GOLD III 1 LP" becomes 0/0 and falls back to admin review.
                    $tier_to_int = static function ($value): int {
                        if (is_numeric($value)) {
                            return (int)$value;
                        }
                        $key = strtoupper(trim((string)$value));
                        $map = [
                            'UNRANKED' => 0,
                            'IRON' => 1,
                            'BRONZE' => 2,
                            'SILVER' => 3,
                            'GOLD' => 4,
                            'PLATINUM' => 5,
                            'EMERALD' => 6,
                            'DIAMOND' => 7,
                            'MASTER' => 8,
                            'GRANDMASTER' => 9,
                            'CHALLENGER' => 10,
                        ];
                        return $map[$key] ?? 0;
                    };
                    $division_to_int = static function ($value): int {
                        if (is_numeric($value)) {
                            return (int)$value;
                        }
                        $key = strtoupper(trim((string)$value));
                        $map = [
                            'IV' => 1,
                            'III' => 2,
                            'II' => 3,
                            'I' => 4,
                        ];
                        return $map[$key] ?? 0;
                    };

                    $end_tier     = $tier_to_int($order_opts['end_tier'] ?? 0);
                    $end_division = $division_to_int($order_opts['end_division'] ?? 0);
                    $cur_tier     = $tier_to_int($fresh['current_tier'] ?? 0);
                    $cur_div      = $division_to_int($fresh['current_division'] ?? 0);

                    if ($cur_tier >= 8 && $cur_tier >= $end_tier) {
                        // Master+ has no IV/III/II/I division, reaching the tier is enough.
                        $goal_reached = true;
                    } elseif ($cur_tier > $end_tier) {
                        $goal_reached = true;
                    } elseif ($cur_tier === $end_tier) {
                        // Division: 1=IV, 2=III, 3=II, 4=I - higher number = better.
                        // LP does not need to be exactly 0; Gold III 1 LP satisfies a Gold III target.
                        $goal_reached = ($cur_div >= $end_division && $end_division > 0);
                    }

                } elseif (in_array($form_type, ['win', 'arena'], true)) {
                    $needed = (int)($order_opts['matches'] ?? 0);
                    $done   = (int)($fresh['wins']         ?? 0);
                    $goal_reached = ($done >= $needed && $needed > 0);

                } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash', 'pro-games'], true) || $form_id === 26) {
                    $needed = (int)($order_opts['matches']              ?? 0);
                    $done   = ((int)($fresh['wins'] ?? 0)) + ((int)($fresh['losses'] ?? 0));
                    $goal_reached = ($done >= $needed && $needed > 0);
                }
            }

            if ($goal_reached) {
                // ── AUTO-COMPLETE: goal verified by Riot tracking ──
                $booster_id   = (int) BOOSTER_ID;
                $booster      = db_get_row('boosters', ['id' => $booster_id]);
                $fixedBoosterCut = function_exists('lb_fixed_booster_cut_percent')
                    ? lb_fixed_booster_cut_percent($order, $booster_id)
                    : null;
                $cut_percent  = $fixedBoosterCut !== null
                    ? (int)$fixedBoosterCut
                    : (int)($order['booster_cut'] ?? 0);
                $price_eur    = (int)($order['price_eur']   ?? 0);
                $payout_base  = (int) round($price_eur * $cut_percent / 100);
                $now          = date('Y-m-d H:i:s');

                // Base payout
                if ($payout_base > 0 && $booster != false) {
                    $old_bal = (int)($booster['balance'] ?? 0);
                    $new_bal = $old_bal + $payout_base;
                    db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_bal]);
                    db_add_row('booster_payments', [
                        'booster_id'     => $booster_id,
                        'type'           => 'order_completion',
                        'note'           => (string)$order_id,
                        'amount'         => $payout_base,
                        'currency'       => 'EUR',
                        'sender'         => 'system',
                        'sender_type'    => 'system',
                        'sender_id'      => 0,
                        'balance_update' => $old_bal . '|' . $new_bal,
                        'created_at'     => $now,
                    ]);
                }

                // Add-on remainder
                $addon_remainder = 0;
                $addons_total = (int) $this->get_paid_addons_total_eur_cents((int)$order_id);
                if ($addons_total > 0) {
                    $base_invoice_eur = (int) $this->get_base_order_invoice_total_eur_cents((int)$order_id);
                    $addons_already_in_base_payout = ($base_invoice_eur > 0 && $price_eur >= ($base_invoice_eur + $addons_total - 1));

                    if ($addons_already_in_base_payout) {
                        // orders.price_eur already includes the add-on invoices, so payout_base already contains the add-on cut.
                        // Do not create a second addon_payment row for the same add-on amount.
                        $addons_pool = 0;
                    } else {
                        $addons_pool = (int) round($addons_total * $cut_percent / 100);
                    }
                    $paid_rows   = $db->run("SELECT COALESCE(SUM(amount), 0) AS paid FROM booster_payments WHERE type = 'addon_payment' AND note = ?", (string)$order_id);
                    $already     = (is_array($paid_rows) && isset($paid_rows[0]['paid'])) ? (int)$paid_rows[0]['paid'] : 0;
                    $addon_remainder = max(0, $addons_pool - $already);
                    if ($addon_remainder > 0) {
                        $booster_now = db_get_row('boosters', ['id' => $booster_id]);
                        if ($booster_now != false) {
                            $ob2 = (int)($booster_now['balance'] ?? 0);
                            $nb2 = $ob2 + $addon_remainder;
                            db_update_row('boosters', ['id' => $booster_id], ['balance' => $nb2]);
                            db_add_row('booster_payments', [
                                'booster_id'     => $booster_id,
                                'type'           => 'addon_payment',
                                'note'           => (string)$order_id,
                                'amount'         => $addon_remainder,
                                'currency'       => 'EUR',
                                'sender'         => 'system',
                                'sender_type'    => 'system',
                                'sender_id'      => 0,
                                'balance_update' => $ob2 . '|' . $nb2,
                                'created_at'     => $now,
                            ]);
                        }
                    }
                }

                // Booster helpers receive +5 percentage points on the same cut base.
                // Example: normal 40% cut + helper bonus 5% = 45% total, stored separately.
                $helper_bonus_base = (int)$price_eur;
                if ((int)$addon_remainder > 0 && (int)$cut_percent > 0) {
                    $helper_bonus_base += (int) round(((int)$addon_remainder * 100) / (int)$cut_percent);
                }

                $helper_bonus = $this->add_booster_helper_bonus_payment(
                    $booster_id,
                    $order_id,
                    $helper_bonus_base,
                    'system',
                    'system',
                    0,
                    $now
                );

                $monthly_top_booster_bonus = $this->add_monthly_top_booster_bonus_payment(
                    $booster_id,
                    $order_id,
                    $helper_bonus_base,
                    'system',
                    'system',
                    0,
                    $now
                );

                // Mark order completed
                $complete_update = [
                    'status'       => 'COMPLETED',
                    'completed_at' => $now,
                    'booster_cut'  => $cut_percent,
                ];
                $complete_update = array_merge($complete_update, $this->duo_timer_stop_payload($order, $now));
                db_update_row('orders', ['id' => $order_id], $complete_update);

                if (function_exists('lb_referral_handle_completed_order')) {
                    lb_referral_handle_completed_order($order_id);
                }

                // Notify client
                db_add_row('notifications', [
                    'type'         => 'order_completed',
                    'data'         => json_encode([
                        'order_id'   => base64_encode((string)$order_id),
                        'file_url'   => base64_encode((string)($file_url ?? '')),
                        'booster_id' => base64_encode((string)$booster_id),
                    ]),
                    'recipient'    => 'client',
                    'recipient_id' => $order['client_id'],
                    'is_email'     => 1,
                ]);

                // Notify booster (web)
                $payout_total = $payout_base + $addon_remainder + (int)$helper_bonus;
                db_add_row('notifications', [
                    'type'         => 'order_completed',
                    'data'         => json_encode([
                        'order_id'     => base64_encode((string)$order_id),
                        'payout_cents' => $payout_total,
                    ]),
                    'recipient'    => 'booster',
                    'recipient_id' => $booster_id,
                    'is_web'       => 1,
                    'is_sent'      => 1,
                ]);

                // Discord confirmation notification for automatic Riot-tracking completion (no role ping)
                $webhookUrl = lb_booster_notification_webhook_url('auto_order_completion');
                $boosterName = BOOSTER_DATA['username'] ?? ('Booster #' . $booster_id);
                $siteUrl = defined('BASE_URL') ? rtrim(BASE_URL, '/') : 'https://lolboost.gg';
                $orderUrl = $siteUrl . '/admin-area/order/' . $order_id;
                $completeOrderUrl = $orderUrl;

                $mergedOrderData = array_merge((array)$form, (array)$order_opts, (array)$order_acc, (array)$order);
                $gameLabel = strtoupper((string)($form['game'] ?? $order['game'] ?? 'LOL'));
                $formName = trim((string)($form['name'] ?? 'Order'));
                $orderTitle = trim($gameLabel . ' ' . $formName);
                $orderDetails = $orderTitle;
                if (function_exists('util_format_boost_overview')) {
                    try {
                        $tmpDetails = trim(strip_tags((string)util_format_boost_overview($form['game'] ?? $order['game'] ?? 'lol', $form_type, $mergedOrderData)));
                        if ($tmpDetails !== '') {
                            $orderDetails = html_entity_decode($tmpDetails, ENT_QUOTES, 'UTF-8');
                        }
                    } catch (Throwable $e) {
                        // Keep fallback title.
                    }
                }

                $inGameName = '';
                foreach (['ign', 'in_game_name', 'riot_id', 'summoner_name', 'account_name', 'username'] as $ignKey) {
                    $candidate = trim((string)($mergedOrderData[$ignKey] ?? ''));
                    if ($candidate !== '') {
                        $inGameName = $candidate;
                        break;
                    }
                }
                if ($inGameName === '') {
                    $inGameName = '-';
                }

                $discordTitle = $boosterName . ' has automatically completed a ' . $orderTitle;
                $wPayload = [
                    'username'         => 'Orders Notif',
                    'avatar_url'       => 'https://lolboost.gg/public/uploads/icons/default1.png',
                    'content'          => $boosterName . ' has automatically completed a ' . $orderTitle . ' via Riot Tracking - [View Order](' . $completeOrderUrl . ')',
                    'allowed_mentions' => ['parse' => []],
                    'embeds'           => [[
                        'title'  => '#' . $order_id . "\n\n" . $discordTitle,
                        'url'    => $orderUrl,
                        'color'  => 0x5865F2,
                        'fields' => [
                            ['name' => 'Order Details', 'value' => $orderDetails, 'inline' => true],
                            ['name' => 'In Game Name',  'value' => $inGameName,   'inline' => true],
                        ],
                        'footer'    => ['text' => 'Automatically completed via Riot Tracking'],
                        'timestamp' => date('c'),
                    ]],
                ];
                $ch = curl_init($webhookUrl);
                curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => json_encode($wPayload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 6]);
                curl_exec($ch); curl_close($ch);

                if (function_exists('lb_realtime_emit')) {
                    lb_realtime_emit_order('order_status_update', $order_id);
                    lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                }

                echo json_encode([
                    "sendToast" => ["type" => "success", "title" => "Order Completed!", "message" => "Goal verified via Riot tracking. Your order has been completed and payout added to your balance."],
                    "playSound" => "success",
                    "refreshPage" => true,
                ]);
                return;

            } else {
                // Goal NOT reached / API could not verify.
                // For regular tracking forms, require a screenshot before admin review.
                if ($file_url === null && $existing_file_url === '') {
                    $required_message = "Automatic Riot tracking could not verify the completion. Please upload a screenshot for admin review.";
                    echo json_encode([
                        "sendToast" => [
                            "type" => "danger",
                            "title" => "Screenshot required",
                            "message" => $required_message
                        ],
                        "playSound" => "error",
                        "trackingResult" => "screenshot_required",
                        "requireScreenshot" => true,
                        "message" => $required_message,
                    ]);
                    return;
                }

                db_update_row('orders', ['id' => $order_id], ['waiting_for_approval' => 1]);
                db_add_row('notifications', [
                    'type' => 'order_completion_request',
                    'data' => json_encode([
                        'order_id' => base64_encode((string)$order_id),
                        'tracking_note' => 'Riot tracking could not verify goal — manual review needed.',
                    ]),
                    'is_discord' => 1,
                ]);
                if (function_exists('lb_realtime_emit')) {
                    lb_realtime_emit_order('order_status_update', $order_id);
                    lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                }
                echo json_encode([
                    "sendToast" => ["type" => "primary", "title" => "Sent for review", "message" => "Riot tracking could not verify the goal automatically. Your screenshot has been sent to an admin for review."],
                    "playSound" => "success",
                    "refreshPage" => true,
                    "trackingResult" => "pending_review",
                ]);
                return;
            }
        }

        // ── Non-tracking forms, missing Riot ID, or forced manual forms → admin review.
        // A screenshot was required above whenever automatic completion was not available.
        db_update_row('orders', ['id' => $order_id], ['waiting_for_approval' => 1]);
        db_add_row('notifications', [
            'type' => 'order_completion_request',
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
            ]),
            'is_discord' => 1,
        ]);
        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit_order('order_status_update', $order_id);
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }
        echo json_encode([
            "sendToast" => ["type" => "primary", "title" => "Success", "message" => $file_url === null ? "Completion confirmed. Waiting for admin approval." : "Completion request sent. Waiting for admin approval."],
            "playSound" => "success",
            "refreshPage" => true,
        ]);
    }

    public function booster_upload_profile_picture()
    {
        if ($this->is_booster) {
            $image_url = $_FILES['image_url'];
            if ($image_url['name'] != '') {
                $image_url = upload_image($image_url, 'icons/');
                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                }
                db_update_row('boosters', ['id' => BOOSTER_ID], ['icon' => $image_url]);
                echo json_encode([
                    "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Profile picture updated successfully."],
                    "playSound" => "success",
                    "refreshPage" => true
                ]);
            } else {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
            }
        }
    }

    public function booster_upload_cover()
    {
        if (!$this->is_booster) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Unauthorized."]]);
            return;
        }

        global $db;

        $position_raw = trim($_POST['cover_position'] ?? '50% 50%');
        $cover_position = preg_match('/^(\d{1,3}(?:\.\d{1,2})?%)\s+(\d{1,3}(?:\.\d{1,2})?%)$/', $position_raw)
            ? $position_raw
            : '50% 50%';

        try {
            $this->ensure_selling_schema();
        } catch (\Throwable $e) {}

        $payload = ['cover_position' => $cover_position];

        $image_url = $_FILES['image_url'] ?? null;
        if ($image_url && !empty($image_url['name'])) {
            $uploaded_url = upload_image($image_url, 'covers/');
            if ($uploaded_url == false) {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                exit();
            }
            $payload['cover'] = $uploaded_url;
        }

        if (count($payload) === 1 && empty(BOOSTER_DATA['cover'])) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Please choose a cover image first."]]);
            return;
        }

        db_update_row('boosters', ['id' => BOOSTER_ID], $payload);

        echo json_encode([
            "sendToast" => ["type" => "primary", "title" => "Success", "message" => !empty($payload['cover']) ? "Cover updated successfully." : "Cover position saved successfully."],
            "playSound" => "success",
            "refreshPage" => true
        ]);
    }

    public function admin_upload_profile_picture()
    {
        if ($this->is_admin) {
            $image_url = $_FILES['image_url'];
            if ($image_url['name'] != '') {
                $image_url = upload_image($image_url, 'icons/');
                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                }
                db_update_row('admins', ['id' => ADMIN_ID], ['icon' => $image_url]);
                echo json_encode([
                    "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Profile picture updated successfully."],
                    "playSound" => "success",
                    "refreshPage" => true
                ]);
            } else {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
            }
        }
    }

    public function booster_claim_order()
    {
        global $db;

        if (!$this->is_booster) {
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(["success" => false, "message" => "Invalid order.", "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
            return;
        }

        // Load the real order first. Do not filter by status/booster here, otherwise
        // local validation errors can incorrectly fall through to "already claimed".
        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(["success" => false, "message" => "Invalid order.", "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
            return;
        }

        if ($this->is_booster_blocked_from_order_claim($order_id, (int)BOOSTER_ID)) {
            echo json_encode([
                "success" => false,
                "blocked" => true,
                "order_id" => $order_id,
                "message" => "An admin has restricted you from claiming this order. If you still wanna claim, please open a support ticket.",
                "sendToast" => [
                    "type" => "warning",
                    "title" => "Claim restricted",
                    "message" => "An admin has restricted you from claiming this order. If you still wanna claim, please open a support ticket."
                ],
                "playSound" => "error"
            ]);
            return;
        }

        $status = (string)($order['status'] ?? '');
        $boosterIdOnOrder = (int)($order['booster_id'] ?? 0);
        $claimableStatuses = ['PAID', 'PROCESSING'];

        $order_options = db_get_row('order_options', ['order_id' => $order_id]);
        if ($order_options == false) $order_options = [];

        $order_form = db_get_row('boost_forms', ['id' => $order['form_id']]);
        if ($order_form == false) {
            echo json_encode(["success" => false, "message" => "Invalid order form.", "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order form."]]);
            return;
        }

        $order_data = array_merge($order_options, $order_form, $order);
        $isRanked5sOrder = function_exists('lb_is_ranked_5s_order') ? lb_is_ranked_5s_order($order, $order_form) : ((int)($order['form_id'] ?? 0) === 29 || ($order_form['type'] ?? '') === 'ranked-5s');
        $isMultiBoosterOrder = function_exists('lb_is_multi_booster_order')
            ? lb_is_multi_booster_order($order, $order_form)
            : $isRanked5sOrder;

        if (!$isMultiBoosterOrder && ($boosterIdOnOrder > 0 || !in_array($status, $claimableStatuses, true))) {
            echo json_encode([
                "success" => false,
                "claimed" => true,
                "removeOrder" => true,
                "order_id" => $order_id,
                "message" => "Diese Order wurde bereits von einem anderen Booster geclaimt.",
                "sendToast" => ["type" => "warning", "title" => "Order already claimed", "message" => "Diese Order wurde bereits von einem anderen Booster geclaimt."],
                "playSound" => "error"
            ]);
            return;
        }

        $order_form_id = (int)($order_data['form_id'] ?? 0);
        $order_game = strtolower(trim((string)($order_form['game'] ?? '')));
        $coaching_form_ids = [15, 16, 25];
        $uses_lol_order_limit = $order_game === 'lol' && !in_array($order_form_id, $coaching_form_ids, true);

        if ($uses_lol_order_limit) {
            $booster_limits = db_get_row('booster_limits', ['booster_id' => BOOSTER_ID]);
            if ($booster_limits == false) $booster_limits = [];

            $is_duo_order = (int)($order_options['is_duo'] ?? 0) === 1;

            // Der Admin-Bereich speichert generische UND spielspezifische Limits
            // (siehe $limitColumns in admin_update_booster). Geprueft wurde hier
            // bisher nur das generische Feld - wer sein Limit im LoL-Feld setzt,
            // lief weiter gegen den alten generischen Wert.
            // Reihenfolge: lol_* -> generisch -> order_limit.
            $suffix = $is_duo_order ? 'duo_order_limit' : 'solo_order_limit';
            $limit_candidates = ['lol_' . $suffix, $suffix, 'order_limit'];

            $order_limit = 0;
            $limit_field = $suffix;
            foreach ($limit_candidates as $candidate) {
                if (isset($booster_limits[$candidate]) && $booster_limits[$candidate] !== '' && (int)$booster_limits[$candidate] > 0) {
                    $order_limit = (int)$booster_limits[$candidate];
                    $limit_field = $candidate;
                    break;
                }
            }

            $claimed_orders = (int)$db->cell(
                "SELECT COUNT(*)
                 FROM orders o
                 INNER JOIN boost_forms bf ON bf.id = o.form_id
                 LEFT JOIN order_options oo ON oo.order_id = o.id
                 WHERE o.booster_id = ?
                   AND o.status = 'IN_PROGRESS'
                   AND bf.game = 'lol'
                   AND o.form_id NOT IN (15, 16, 25)
                   AND COALESCE(oo.is_duo, 0) = ?",
                BOOSTER_ID,
                $is_duo_order ? 1 : 0
            );

            if ($claimed_orders >= $order_limit) {
                $limit_type = $is_duo_order ? 'duo' : 'solo';
                $message = $order_limit === 0
                    ? "You don’t have any available slots for " . ucfirst($limit_type) . " orders. Please ask an admin to increase your " . ucfirst($limit_type) . " Order Limit."
                    : "You’ve reached your " . ucfirst($limit_type) . " Order Limit ({$claimed_orders}/{$order_limit}). Please finish or drop an active " . ucfirst($limit_type) . " order before claiming another one.";

                echo json_encode([
                    "success" => false,
                    "error_code" => "ORDER_LIMIT_REACHED",
                    "limit_type" => $limit_type,
                    "order_limit" => $order_limit,
                    "active_orders" => $claimed_orders,
                    "message" => $message,
                    "sendToast" => [
                        "type" => "danger",
                        "title" => ucfirst($limit_type) . " order limit reached",
                        "message" => $message
                    ],
                    "playSound" => "error"
                ]);
                return;
            }

            if (isset($booster_limits['lol_rank_limit']) && in_array(($order_form['game'] ?? ''), ['lol', 'lol_classic', 'lol-classic'], true)) {
                $booster_limits['rank_limit'] = explode('|', $booster_limits['lol_rank_limit']);
            }

            if (isset($booster_limits['val_rank_limit']) && ($order_form['game'] ?? '') == 'val') {
                $booster_limits['rank_limit'] = explode('|', $booster_limits['val_rank_limit']);
            }

            if (isset($booster_limits['rank_limit']) && is_array($booster_limits['rank_limit']) && isset($booster_limits['rank_limit'][0])) {
                $rank_limit = intval($booster_limits['rank_limit'][0] . ($booster_limits['rank_limit'][1] ?? 0));
                switch ($order_data['type'] ?? '') {
                    case 'win':
                    case 'placement':
                        $order_rank = intval(($order_data["start_tier"] ?? 0) . ($order_data["start_division"] ?? 0));
                        if ($order_rank > $rank_limit) {
                            echo json_encode([
                                "success" => false,
                                "message" => "Can’t claim this order — your rank limit is too low.",
                                "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Can’t claim this order — your rank limit is too low."],
                                "playSound" => "error"
                            ]);
                            return;
                        }
                        break;
                    case 'rank':
                        $order_rank = intval(($order_data["end_tier"] ?? 0) . ($order_data["end_division"] ?? 0));
                        if ($order_rank > $rank_limit) {
                            echo json_encode([
                                "success" => false,
                                "message" => "Can’t claim this order — your rank limit is too low.",
                                "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Can’t claim this order — your rank limit is too low."],
                                "playSound" => "error"
                            ]);
                            return;
                        }
                        break;
                }
            }
        }

        if (!empty($isMultiBoosterOrder)) {
            global $db;
            $claimableR5sStatuses = ['PAID', 'PROCESSING', 'IN_PROGRESS'];
            if (!in_array($status, $claimableR5sStatuses, true) || !empty($order['completed_at'])) {
                echo json_encode([
                    "success" => false,
                    "claimed" => true,
                    "removeOrder" => true,
                    "order_id" => $order_id,
                    "message" => "Diese Ranked 5s Order ist nicht mehr verfügbar.",
                    "sendToast" => ["type" => "warning", "title" => "Order unavailable", "message" => "Diese Ranked 5s Order ist nicht mehr verfügbar."],
                    "playSound" => "error"
                ]);
                return;
            }

            $requiredBoosters = function_exists('lb_multi_booster_required_count') ? lb_multi_booster_required_count($order_id) : max(1, min(4, (int)($order_options['boosters'] ?? 1)));
            $requiredBoosters = max(1, min(4, (int)$requiredBoosters));

            if (function_exists('lb_multi_booster_has_claim') && lb_multi_booster_has_claim($order_id, (int)BOOSTER_ID)) {
                echo json_encode([
                    "success" => true,
                    "redirectUrl" => BSTR_URL . "/order/" . $order_id,
                    "sendToast" => ["type" => "primary", "title" => "Already joined", "message" => "You already joined this Ranked 5s order."],
                    "playSound" => "success"
                ]);
                return;
            }

            $claimedBefore = function_exists('lb_multi_booster_claimed_count') ? lb_multi_booster_claimed_count($order_id) : 0;
            if ($claimedBefore >= $requiredBoosters) {
                echo json_encode([
                    "success" => false,
                    "claimed" => true,
                    "removeOrder" => true,
                    "order_id" => $order_id,
                    "message" => "Diese Ranked 5s Order hat bereits alle Booster.",
                    "sendToast" => ["type" => "warning", "title" => "Order full", "message" => "Diese Ranked 5s Order hat bereits alle Booster."],
                    "playSound" => "error"
                ]);
                return;
            }

            $clientRole = '';
            $requestedRole = '';
            $availableRoles = [];
            if ($isRanked5sOrder) {
                $clientRole = function_exists('lb_ranked_5s_normalize_role') ? lb_ranked_5s_normalize_role($order_options['roles'] ?? '') : (string)($order_options['roles'] ?? '');
                $requestedRole = function_exists('lb_ranked_5s_normalize_role') ? lb_ranked_5s_normalize_role($_POST['ranked_5s_lane'] ?? $_POST['role'] ?? '') : (string)($_POST['ranked_5s_lane'] ?? $_POST['role'] ?? '');
                $availableRoles = function_exists('lb_ranked_5s_available_roles') ? lb_ranked_5s_available_roles($order_id, $clientRole) : [];
            } else {
                $activeSlots = $db->run(
                    "SELECT slot_no FROM order_boosters WHERE order_id = ? AND status = 'ACTIVE'",
                    $order_id
                ) ?: [];
                $usedSlots = array_map(static fn($row) => (int)($row['slot_no'] ?? 0), $activeSlots);
                $nextSlot = 1;
                while (in_array($nextSlot, $usedSlots, true)) {
                    $nextSlot++;
                }
                $requestedRole = 'ClashSlot' . $nextSlot;
                $availableRoles = [$requestedRole];
            }

            if ($requestedRole === '' && !empty($availableRoles)) {
                $requestedRole = (string)$availableRoles[0];
            }

            if ($requestedRole === '' || !in_array($requestedRole, $availableRoles, true)) {
                echo json_encode([
                    "success" => false,
                    "message" => "This lane is no longer available.",
                    "sendToast" => ["type" => "warning", "title" => "Lane unavailable", "message" => "Diese Lane ist nicht mehr verfügbar."],
                    "playSound" => "error"
                ]);
                return;
            }

            $booster_price = 50;
            $duo_now = date('Y-m-d H:i:s');
            $slotNo = $isRanked5sOrder ? ($claimedBefore + 1) : (int)substr($requestedRole, strlen('ClashSlot'));

            try {
                $db->run(
                    "UPDATE order_boosters
                        SET slot_no = 1000000 + id,
                            role = CONCAT('Removed', id, '_', UNIX_TIMESTAMP())
                      WHERE order_id = ? AND role = ? AND status <> 'ACTIVE'",
                    $order_id,
                    $requestedRole
                );
                $existingMembership = $db->row(
                    "SELECT id FROM order_boosters WHERE order_id = ? AND booster_id = ? LIMIT 1",
                    $order_id,
                    (int)BOOSTER_ID
                );
                if ($existingMembership) {
                    $db->run(
                        "UPDATE order_boosters
                            SET slot_no = ?, role = ?, cut_percent = ?, status = 'ACTIVE', claimed_at = ?
                          WHERE id = ?",
                        $slotNo,
                        $requestedRole,
                        (int)$booster_price,
                        $duo_now,
                        (int)$existingMembership['id']
                    );
                } else {
                    $db->run(
                        "INSERT INTO order_boosters (order_id, booster_id, slot_no, role, cut_percent, status, claimed_at) VALUES (?, ?, ?, ?, ?, 'ACTIVE', ?)",
                        $order_id,
                        (int)BOOSTER_ID,
                        $slotNo,
                        $requestedRole,
                        (int)$booster_price,
                        $duo_now
                    );
                }
            } catch (\Throwable $e) {
                $claimTypeLabel = $isRanked5sOrder ? 'Lane' : 'Booster spot';
                echo json_encode([
                    "success" => false,
                    "message" => $claimTypeLabel . " is no longer available. Please refresh and try again.",
                    "sendToast" => ["type" => "danger", "title" => "Claim failed", "message" => $claimTypeLabel . " is no longer available. Please refresh and try again."],
                    "playSound" => "error",
                    "debug_error" => $e->getMessage()
                ]);
                return;
            }

            $pendingRequestedIds = array_values(array_unique(array_filter(array_map(
                'intval',
                preg_split('/[\s,|]+/', (string)($order_options['selected_boosters'] ?? ''), -1, PREG_SPLIT_NO_EMPTY)
            ))));
            if (in_array((int)BOOSTER_ID, $pendingRequestedIds, true)) {
                $pendingRequestedIds = array_values(array_filter(
                    $pendingRequestedIds,
                    static fn($id) => (int)$id !== (int)BOOSTER_ID
                ));
                db_update_row('order_options', ['order_id' => $order_id], [
                    'selected_boosters' => implode(',', $pendingRequestedIds),
                ]);
            }

            $claimedAfter = function_exists('lb_multi_booster_claimed_count') ? lb_multi_booster_claimed_count($order_id) : ($claimedBefore + 1);

            // order_boosters is authoritative for team orders. Keep the legacy
            // primary pointer on the oldest active slot instead of replacing it
            // with whichever booster claimed most recently.
            $primaryMembership = function_exists('lb_multi_booster_sync_primary')
                ? lb_multi_booster_sync_primary($order_id)
                : null;
            if (empty($primaryMembership)) {
                db_update_row('orders', ['id' => $order_id], [
                    'status' => 'IN_PROGRESS',
                    'booster_id' => (int)BOOSTER_ID,
                    'claimed_at' => $duo_now,
                    'booster_cut' => $booster_price,
                ]);
            }

            db_add_row('notifications', [
                'type' => 'order_claimed',
                'recipient' => 'client',
                'recipient_id' => $order_data['client_id'],
                'data' => json_encode([
                    'order_id' => base64_encode($order_data['id']),
                    'booster_username' => base64_encode(BOOSTER_DATA['username']),
                    'booster_id' => base64_encode(BOOSTER_ID),
                    'ranked_5s_lane' => base64_encode($requestedRole),
                    'ranked_5s_slot' => base64_encode((string)$claimedAfter . '/' . $requiredBoosters),
                ]),
                'is_email' => ($claimedAfter === 1 ? 1 : 0),
                'is_web' => 1,
            ]);

            $client_row = db_get_row('clients', ['id' => (int)$order_data['client_id']]);
            $client_username = $client_row != false && !empty($client_row['username']) ? (string)$client_row['username'] : 'Client';

            db_add_row('notifications', [
                'type' => 'order_claimed',
                'recipient' => 'booster',
                'recipient_id' => BOOSTER_ID,
                'data' => json_encode([
                    'order_id' => base64_encode($order_data['id']),
                    'client_username' => base64_encode($client_username),
                ]),
                'is_web' => 1,
                'is_sent' => 1,
            ]);

            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit('ranked_5s_lanes_update', [
                    'order_id' => $order_id,
                    'claimed' => $claimedAfter,
                    'required' => $requiredBoosters,
                    'silent' => true,
                ]);
                // The admin and client order views listen for order_status_update.
                // Without it, an open order view keeps showing the old state after a claim.
                lb_realtime_emit_order('order_status_update', $order_id);
            }

            echo json_encode([
                "success" => true,
                "redirectUrl" => BSTR_URL . "/order/" . $order_id,
                "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Ranked 5s lane claimed successfully."],
                "playSound" => "success",
                "refreshPage" => false
            ]);
            return;
        }

        $fixedBoosterCut = function_exists('lb_fixed_booster_cut_percent')
            ? lb_fixed_booster_cut_percent($order, (int)BOOSTER_ID)
            : null;
        $booster_price = $fixedBoosterCut !== null
            ? $fixedBoosterCut
            : calculate_booster_cut($order, 'percent');
        $duo_now = date('Y-m-d H:i:s');
        $claim_update = ['booster_id' => BOOSTER_ID, 'status' => 'IN_PROGRESS', 'claimed_at' => $duo_now, 'booster_cut' => $booster_price];

        // Atomic claim. This is the only place where a real race condition becomes "already claimed".
        if (db_update_row('orders', ['id' => $order_id, 'booster_id' => null, 'status' => $status], $claim_update) != false) {
            db_add_row('notifications', [
                'type' => 'order_claimed',
                'recipient' => 'client',
                'recipient_id' => $order_data['client_id'],
                'data' => json_encode([
                    'order_id' => base64_encode($order_data['id']),
                    'booster_username' => base64_encode(BOOSTER_DATA['username']),
                    'booster_id' => base64_encode(BOOSTER_ID),
                ]),
                'is_email' => 1,
            ]);

            $client_row = db_get_row('clients', ['id' => (int)$order_data['client_id']]);
            $client_username = $client_row != false && !empty($client_row['username']) ? (string)$client_row['username'] : 'Client';

            db_add_row('notifications', [
                'type' => 'order_claimed',
                'recipient' => 'booster',
                'recipient_id' => BOOSTER_ID,
                'data' => json_encode([
                    'order_id' => base64_encode($order_data['id']),
                    'client_username' => base64_encode($client_username),
                ]),
                'is_web' => 1,
                'is_sent' => 1,
            ]);

            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
                // orders_panel_update only refreshes the booster panel list. The admin and
                // client order views listen for order_status_update, so without this an
                // open order view still shows "no booster assigned" after a claim.
                lb_realtime_emit_order('order_status_update', $order_id);
            }

            echo json_encode([
                "success" => true,
                "redirectUrl" => BSTR_URL . "/order/" . $order_id,
                "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Order claimed successfully."],
                "playSound" => "success",
                "refreshPage" => true
            ]);
            return;
        }

        echo json_encode([
            "success" => false,
            "claimed" => true,
            "removeOrder" => true,
            "order_id" => $order_id,
            "message" => "Diese Order wurde gerade von einem anderen Booster geclaimt.",
            "sendToast" => ["type" => "warning", "title" => "Order already claimed", "message" => "Diese Order wurde gerade von einem anderen Booster geclaimt."],
            "playSound" => "error"
        ]);
    }

    public function booster_accept_requested_order()
    {
        if (!$this->is_booster) return;

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order not found."]]);
            return;
        }

        $requestOpts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $isMultiRequest = in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true);
        $requestedIds = array_values(array_unique(array_filter(array_map('intval', preg_split('/[\s,|]+/', (string)($requestOpts['selected_boosters'] ?? ''), -1, PREG_SPLIT_NO_EMPTY)))));
        $claimedAt = trim((string)($order['claimed_at'] ?? ''));
        $isPending = in_array((string)($order['status'] ?? ''), ['PAID', 'PROCESSING', 'IN_PROGRESS'], true)
            && ($isMultiRequest ? in_array((int)BOOSTER_ID, $requestedIds, true) : (int)($order['booster_id'] ?? 0) === (int)BOOSTER_ID)
            && ($isMultiRequest || $claimedAt === '' || $claimedAt === '0000-00-00 00:00:00');

        if (!$isPending) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "This order is no longer waiting for your response."]]);
            return;
        }

        $booster_price = (isset($order['booster_cut']) && is_numeric($order['booster_cut']) && (float)$order['booster_cut'] > 0)
            ? (float)$order['booster_cut']
            : (float)calculate_booster_cut($order, 'percent');
        $duo_now = date('Y-m-d H:i:s');
        $accept_update = [
            'status' => 'IN_PROGRESS',
            'claimed_at' => $duo_now,
            'booster_cut' => $booster_price,
        ];
        if ($isMultiRequest) {
            $required = max(1, min(4, (int)($requestOpts['boosters'] ?? $requestOpts['hours'] ?? 1)));
            $activeRows = $this->conn->run(
                "SELECT booster_id, slot_no FROM order_boosters WHERE order_id = ? AND status = 'ACTIVE' ORDER BY slot_no ASC",
                $order_id
            ) ?: [];
            foreach ($activeRows as $activeRow) {
                if ((int)($activeRow['booster_id'] ?? 0) === (int)BOOSTER_ID) {
                    echo json_encode(["sendToast" => ["type" => "success", "title" => "Accepted", "message" => "You already joined this order."], "redirectUrl" => BSTR_URL . "/order/" . $order_id]);
                    return;
                }
            }
            if (count($activeRows) >= $required) {
                echo json_encode(["sendToast" => ["type" => "warning", "title" => "Team full", "message" => "All booster spots are filled."]]);
                return;
            }
            $usedSlots = array_map(static fn($r) => (int)($r['slot_no'] ?? 0), $activeRows);
            $slotNo = 1;
            while (in_array($slotNo, $usedSlots, true)) $slotNo++;
            $existingMembership = $this->conn->row(
                "SELECT id FROM order_boosters WHERE order_id = ? AND booster_id = ? LIMIT 1",
                $order_id,
                (int)BOOSTER_ID
            );
            $slotRole = 'ClashSlot' . $slotNo;
            $this->conn->run(
                "UPDATE order_boosters
                    SET slot_no = 1000000 + id,
                        role = CONCAT('Removed', id, '_', UNIX_TIMESTAMP())
                  WHERE order_id = ? AND role = ? AND status <> 'ACTIVE'",
                $order_id,
                $slotRole
            );
            if ($existingMembership) {
                $this->conn->run(
                    "UPDATE order_boosters SET slot_no = ?, role = ?, cut_percent = 50, status = 'ACTIVE', claimed_at = ? WHERE id = ?",
                    $slotNo,
                    $slotRole,
                    $duo_now,
                    (int)$existingMembership['id']
                );
            } else {
                $this->conn->run(
                    "INSERT INTO order_boosters (order_id, booster_id, slot_no, role, cut_percent, status, claimed_at) VALUES (?, ?, ?, ?, 50, 'ACTIVE', ?)",
                    $order_id,
                    (int)BOOSTER_ID,
                    $slotNo,
                    $slotRole,
                    $duo_now
                );
            }
            $requestedIds = array_values(array_filter(
                $requestedIds,
                static fn($id) => (int)$id !== (int)BOOSTER_ID
            ));
            db_update_row('order_options', ['order_id' => $order_id], [
                'selected_boosters' => implode(',', $requestedIds),
            ]);
        }
        $updated = db_update_row('orders', [
            'id' => $order_id,
        ], $accept_update);
        if ($isMultiRequest && function_exists('lb_multi_booster_sync_primary')) {
            lb_multi_booster_sync_primary($order_id);
            $updated = true;
        }

        if ($updated == false) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Failed to accept order."]]);
            return;
        }

        $client_row = db_get_row('clients', ['id' => (int)($order['client_id'] ?? 0)], 1);
        $client_username = (!empty($client_row['username']) ? (string)$client_row['username'] : 'Client');

        db_add_row('notifications', [
            'type' => 'booster_assigned',
            'recipient' => 'client',
            'recipient_id' => (int)$order['client_id'],
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'booster_username' => base64_encode((string)(BOOSTER_DATA['username'] ?? 'Booster')),
                'booster_id' => base64_encode((string)BOOSTER_ID),
            ]),
            'is_email' => 1,
            'is_web' => 1,
        ]);

        db_add_row('notifications', [
            'type' => 'booster_assigned',
            'recipient' => 'booster',
            'recipient_id' => BOOSTER_ID,
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'client_username' => base64_encode($client_username),
            ]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);

        if (function_exists('lb_realtime_emit')) {
            // Clears the "pending request" modal/badge for this booster and refreshes their panel.
            lb_realtime_emit('booster_request', ['order_id' => $order_id]);
            lb_realtime_emit_order('order_status_update', $order_id);
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }

        echo json_encode([
            "sendToast" => ["type" => "success", "title" => "Accepted", "message" => "Order accepted. You can start now."],
            "playSound" => "success",
            "redirectUrl" => BSTR_URL . "/order/" . $order_id
        ]);
    }

    public function booster_decline_requested_order()
    {
        if (!$this->is_booster) return;

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order not found."]]);
            return;
        }

        $requestOpts = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $isMultiRequest = in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true);
        $requestedIds = array_values(array_unique(array_filter(array_map('intval', preg_split('/[\s,|]+/', (string)($requestOpts['selected_boosters'] ?? ''), -1, PREG_SPLIT_NO_EMPTY)))));
        $claimedAt = trim((string)($order['claimed_at'] ?? ''));
        $isPending = in_array((string)($order['status'] ?? ''), ['PAID', 'PROCESSING', 'IN_PROGRESS'], true)
            && ($isMultiRequest ? in_array((int)BOOSTER_ID, $requestedIds, true) : (int)($order['booster_id'] ?? 0) === (int)BOOSTER_ID)
            && ($isMultiRequest || $claimedAt === '' || $claimedAt === '0000-00-00 00:00:00');

        if (!$isPending) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "This order is no longer waiting for your response."]]);
            return;
        }

        if ($isMultiRequest) {
            $requestedIds = array_values(array_filter($requestedIds, static fn($id) => (int)$id !== (int)BOOSTER_ID));
            db_update_row('order_options', ['order_id' => $order_id], ['selected_boosters' => implode(',', $requestedIds)]);
            $activeCountRows = $this->conn->run("SELECT COUNT(*) AS total FROM order_boosters WHERE order_id = ? AND status = 'ACTIVE'", $order_id) ?: [];
            $hasActiveTeam = (int)($activeCountRows[0]['total'] ?? 0) > 0;
            $updated = db_update_row('orders', ['id' => $order_id], [
                'booster_id' => $hasActiveTeam ? ($order['booster_id'] ?? null) : ($requestedIds[0] ?? null),
                'status' => $hasActiveTeam ? 'IN_PROGRESS' : 'PAID',
                'claimed_at' => $hasActiveTeam ? ($order['claimed_at'] ?? null) : null,
                'booster_cut' => $hasActiveTeam ? ($order['booster_cut'] ?? 50) : null,
            ]);
        } else {
            $updated = db_update_row('orders', [
                'id' => $order_id,
                'booster_id' => BOOSTER_ID,
            ], [
                'booster_id' => null,
                'status' => 'PAID',
                'claimed_at' => null,
                'booster_cut' => null,
            ]);
        }

        if ($updated == false) {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Failed to decline order."]]);
            return;
        }

        db_add_row('notifications', [
            'type' => 'booster_request_declined',
            'recipient' => 'client',
            'recipient_id' => (int)$order['client_id'],
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'booster_username' => base64_encode((string)(BOOSTER_DATA['username'] ?? '')),
                'booster_id' => base64_encode((string)BOOSTER_ID),
            ]),
            'is_web' => 1,
        ]);

        if (function_exists('lb_realtime_emit')) {
            // Clears the "pending request" modal/badge, and the order is open for everyone again.
            lb_realtime_emit('booster_request', ['order_id' => $order_id]);
            if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
        }

        // Webhook 1: Decline alert
        $client_row      = db_get_row('clients', ['id' => (int)($order['client_id'] ?? 0)], 1);
        $client_username = !empty($client_row['username']) ? (string)$client_row['username'] : 'Unknown';
        $order_type_lbl  = strtoupper((string)($order['type'] ?? $order['order_type'] ?? 'Order'));
        $_dPayload = [
            "username"         => "Booster Decline Notif",
            "avatar_url"       => "https://lolboost.gg/public/uploads/icons/default1.png",
            "content"          => "<@&1083064775623327784> <@&1295032857907171339>",
            "allowed_mentions" => ["roles" => ["1083064775623327784", "1295032857907171339"]],
            "embeds" => [[
                "title"       => "Booster Declined Requested Order",
                "description" => "A booster has **declined** a client-requested order. Returned to pool.",
                "color"       => hexdec("ED4245"),
                "fields" => [
                    ["name" => "Order ID", "value" => "#" . $order_id,           "inline" => true],
                    ["name" => "Type",     "value" => $order_type_lbl,             "inline" => true],
                    ["name" => "Booster",  "value" => BOOSTER_DATA['username'],    "inline" => true],
                    ["name" => "Client",   "value" => $client_username . " (ID: " . (int)($order['client_id'] ?? 0) . ")", "inline" => true],
                    ["name" => "Action",   "value" => "[Open Order](" . BASE_URL . "/admin-area/order/{$order_id})", "inline" => false],
                ],
                "footer"    => ["text" => "LoLBoost.GG", "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"],
                "timestamp" => date("c"),
            ]],
        ];
        $_ch = curl_init(lb_booster_notification_webhook_url('order_drop'));
        curl_setopt($_ch, CURLOPT_HTTPHEADER,    ['Content-type: application/json']);
        curl_setopt($_ch, CURLOPT_POST,          1);
        curl_setopt($_ch, CURLOPT_POSTFIELDS,    json_encode($_dPayload));
        curl_setopt($_ch, CURLOPT_FOLLOWLOCATION,1);
        curl_setopt($_ch, CURLOPT_HEADER,        0);
        curl_setopt($_ch, CURLOPT_RETURNTRANSFER,1);
        curl_exec($_ch);
        curl_close($_ch);

        // Webhook 2: Order available again (game-routed new-order channel)
        $order_full = db_get_row('orders',        ['id'       => $order_id], 1);
        $order_form = $order_full ? db_get_row('boost_forms',   ['id'       => $order_full['form_id']]) : [];
        $order_opts = $order_full ? db_get_row('order_options', ['order_id' => $order_id])              : [];
        $order_note = $order_full ? db_get_row('order_notes',   ['order_id' => $order_id])              : false;
        if ($order_full && $order_form) {
            $om   = array_merge((array)$order_form, (array)$order_opts, (array)$order_full);
            $game = $om['game'] ?? 'lol';
            $gameKey = strtolower(trim((string)$game));
            if (ctype_digit($gameKey)) {
                $gameRow = db_get_row('games', ['id' => (int)$gameKey], 1);
                if (is_array($gameRow) && !empty($gameRow['slug'])) {
                    $gameKey = strtolower(trim((string)$gameRow['slug']));
                    $game = $gameKey;
                }
            }
            $gameAliases = [
                'league-of-legends' => 'lol',
                'league-of-legends-classic' => 'lol_classic', 'lol-classic' => 'lol_classic',
                'teamfight-tactics' => 'tft',
                'valorant' => 'val', 'valo' => 'val',
                'wildrift' => 'wild-rift', 'lol-wild-rift' => 'wild-rift', 'lol_wild_rift' => 'wild-rift',
                'overwatch' => 'ow2', 'overwatch-2' => 'ow2', 'overwatch2' => 'ow2',
                'rocket-league' => 'rl', 'rocketleague' => 'rl', 'rocket_league' => 'rl',
                'apex-legends' => 'apex', 'apexlegends' => 'apex',
                'marvel-rivals' => 'rivals', 'marvel_rivals' => 'rivals',
                'counter-strike-2' => 'cs2', 'counterstrike2' => 'cs2', 'counter-strike' => 'cs2', 'csgo' => 'cs2',
            ];
            $gameKey = $gameAliases[$gameKey] ?? $gameKey;
            $discordRoutes = [
                'lol'         => ['926928458490212412',  '1528087731891343570'],
                'lol_classic' => ['926928458490212412',  '1528087671522459880'],
                'tft'         => ['1476574350735048704', '1528087538827395142'],
                'val'         => ['1149987241284878416', '1528087576894902334'],
                'wild-rift'   => ['1528351346137501777', '1528087459924279336'],
                'ow2'         => ['1528351318207369279', '1528087282358419626'],
                'rl'          => ['1528351285890519192', '1528087225949224970'],
                'apex'        => ['1528351266445459526', '1528087157074427934'],
                'rivals'      => ['1528351186602688633', '1528087090611486751'],
                'fortnite'    => ['1529540249947082862', '1529515122610143312'],
                'cs2'         => ['1529540037153132816', '1529538564885315654'],
            ];
            [$routeRoleId, $routeThreadId] = $discordRoutes[$gameKey] ?? $discordRoutes['val'];
            // Prefer the plain per-game channel once configured, otherwise the forum thread.
            $_noWh = function_exists('lb_discord_channel_webhook') ? lb_discord_channel_webhook('new_order', $gameKey) : '';
            if ($_noWh === '') {
                $_noWh = 'https://discord.com/api/webhooks/1528353465800196146/kceuOj9RBUVb0Iy6h3i37eyGepb0SaSwGrAk66CVyx7wodRRyxev7lWYiCoB3lv6IjFL?thread_id=' . rawurlencode($routeThreadId);
            }
            $_noMention = '<@&' . $routeRoleId . '>';
            $isCounterStrikeOrder = ($gameKey === 'cs2');
            $_noFields = [
                ["name" => "Order ID", "value" => "#" . $order_id, "inline" => true],
            ];
            if (!$isCounterStrikeOrder && !empty($om['server'])) {
                $_noFields[] = ["name" => "Server", "value" => strtoupper((string)$om['server']), "inline" => true];
            }
            if (!empty($om['current_rank'])) {
                $_noFields[] = ["name" => "Current Rank", "value" => util_format_default_type($om['current_rank']), "inline" => true];
            }
            if (!empty($om['is_voice'])) {
