            }
            if ($order_note) {
                $_noFields[] = ["name" => "Note", "value" => decode_entities($order_note['order_note']), "inline" => false];
            }
            $_noPayload = [
                "username" => "New Order Notif",
                "content"  => $_noMention . ($isCounterStrikeOrder || empty($om['server']) ? '' : ' ' . strtoupper((string)$om['server'])) . ' Order (re-available) - [Claim Order](' . BSTR_URL . '/order/' . $order_id . ')',
                "embeds"   => [[
                    "title"       => util_format_boost_overview($game, $om['type'] ?? '', $om),
                    "author"      => ["name" => $om['name'] ?? ''],
                    "color"       => 5793266,
                    "description" => "Previously requested booster declined. Order is now open again.",
                    "fields"      => $_noFields,
                    "timestamp"   => date("c"),
                ]],
            ];
            $_ch2 = curl_init($_noWh);
