    public function booster_pending_request_modal()
    {
        global $db;

        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Not allowed']);
            return;
        }

        $booster_id = (int)(BOOSTER_ID ?? 0);
        if ($booster_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Not logged in']);
            return;
        }

        $rows = $db->run(
            "SELECT o.id, o.form_id, o.price, o.currency, o.status, o.created_at, o.paid_at, o.client_id, o.booster_cut,
                    c.username AS client_username,
                    bf.name AS form_name,
                    bf.game AS game_name,
                    bf.type AS form_type
             FROM orders o
             LEFT JOIN clients c ON c.id = o.client_id
             LEFT JOIN boost_forms bf ON bf.id = o.form_id
             LEFT JOIN order_options oo ON oo.order_id = o.id
             WHERE (
                    (
                        o.form_id NOT IN (4,19,29)
                        AND o.booster_id = ?
                    )
                    OR (
                        o.form_id IN (4,19,29)
                        AND FIND_IN_SET(?, REPLACE(COALESCE(oo.selected_boosters, ''), ' ', '')) > 0
                        AND NOT EXISTS (
                            SELECT 1 FROM order_boosters ob
                            WHERE ob.order_id = o.id AND ob.booster_id = ? AND ob.status = 'ACTIVE'
                        )
                        AND NOT (
                            o.booster_id = ?
                            AND o.claimed_at IS NOT NULL
                            AND o.claimed_at <> ''
                            AND o.claimed_at <> '0000-00-00 00:00:00'
                        )
                        AND NOT EXISTS (
                            SELECT 1
                              FROM notifications accepted_notif
                             WHERE accepted_notif.recipient = 'booster'
                               AND accepted_notif.recipient_id = ?
                               AND accepted_notif.type IN ('order_claimed','booster_assigned')
                               AND JSON_UNQUOTE(JSON_EXTRACT(accepted_notif.data, '$.order_id')) = TO_BASE64(CAST(o.id AS CHAR))
                        )
                    )
               )
               AND o.status IN ('PAID','PROCESSING','IN_PROGRESS')
               AND (
                    o.form_id IN (4,19,29)
                    OR o.claimed_at IS NULL OR o.claimed_at = '' OR o.claimed_at = '0000-00-00 00:00:00'
               )
             ORDER BY COALESCE(o.paid_at, o.created_at) DESC, o.id DESC
             LIMIT 1",
            $booster_id,
            $booster_id,
            $booster_id,
            $booster_id,
            $booster_id
        );

        if (!$rows || empty($rows)) {
            echo json_encode(['success' => true, 'data' => null]);
            return;
        }

        $order = $rows[0];
        $opts = db_get_row('order_options', ['order_id' => (int)$order['id']], 1);
        if (!is_array($opts)) {
            $opts = [];
        }

        $game = (string)($order['game_name'] ?? 'lol');
        $isCounterStrikeOrder = in_array(strtolower(trim($game)), ['cs2', 'counter-strike-2', 'counterstrike2', 'counter-strike', 'csgo'], true);
        $form_type = (string)($order['form_type'] ?? '');
        $merged = array_merge($opts, [
            'form_id' => (int)$order['form_id'],
            'server' => $opts['server'] ?? '',
            'game' => $game,
            'type' => $form_type,
        ]);

        $title = !empty($order['form_name']) ? (string)$order['form_name'] : ('Order #' . (int)$order['id']);
        if ($form_type && function_exists('util_format_boost_overview')) {
            try {
                $tmp = util_format_boost_overview($game, $form_type, $merged);
                if (!empty($tmp)) {
                    $title = $tmp;
                }
            } catch (Throwable $e) {
            }
        }

        $formatValue = function ($key, $value) {
            if (is_array($value)) {
                $clean = [];
                foreach ($value as $item) {
                    $item = trim((string)$item);
                    if ($item !== '') {
                        $clean[] = $item;
                    }
                }
                return implode(', ', $clean);
            }

            $value = (string)$value;
            if ($value === '') {
                return '';
            }

            if (in_array($key, ['roles', 'champions', 'agents', 'coach_type', 'current_rank'], true) && function_exists('util_format_option_inline')) {
                $tmp = util_format_option_inline($key, $value);
                if (is_array($tmp) && isset($tmp[1])) {
                    $value = (string)$tmp[1];
                }
            }

            $decoded = json_decode($value, true);
            if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
                $clean = [];
                foreach ($decoded as $item) {
                    $item = trim((string)$item);
                    if ($item !== '') {
                        $clean[] = $item;
                    }
                }
                if (!empty($clean)) {
                    return implode(', ', $clean);
                }
            }

            $value = trim($value);
            if ($value === '') {
                return '';
            }

            if (str_starts_with($value, '[') && str_ends_with($value, ']')) {
                $trimmed = trim($value, '[]');
                if ($trimmed !== '') {
                    $parts = array_filter(array_map('trim', preg_split('/[,|]/', $trimmed)));
                    if (!empty($parts)) {
                        return implode(', ', $parts);
                    }
                }
            }

            return $value;
        };

        $queueType = '';
        if (!empty($opts['queue_type'])) {
            $queueType = function_exists('util_format_default_type') ? util_format_default_type($opts['queue_type']) : (string)$opts['queue_type'];
        }

        $statusRaw = (string)($order['status'] ?? '');
        $statusText = $statusRaw !== '' ? str_replace('_', ' ', $statusRaw) : 'PAID';
        $earningText = '-';
        if ($order['price'] !== null && $order['price'] !== '') {
            $priceCents = (int)($order['price'] ?? 0);
            $cutPercent = (isset($order['booster_cut']) && is_numeric($order['booster_cut']) && (float)$order['booster_cut'] > 0)
                ? (float)$order['booster_cut']
                : (float)calculate_booster_cut($order, 'percent');
            $earningCents = (int) floor(($priceCents * $cutPercent) / 100);
            if (in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true)) {
                $requiredBoosters = max(1, min(4, (int)($opts['boosters'] ?? $opts['hours'] ?? 1)));
                $earningCents = (int) floor($earningCents / $requiredBoosters);
            }
            $amount = function_exists('util_format_price_display') ? util_format_price_display($earningCents) : number_format(((float)$earningCents / 100), 2);
            $currency = strtoupper((string)($order['currency'] ?? 'EUR'));
            $currencySymbol = function_exists('util_currency_symbol') ? util_currency_symbol($currency) : (($currency === 'USD') ? '$' : (($currency === 'EUR') ? '€' : $currency . ' '));
            $earningText = $currencySymbol . $amount;
        }

        $rowsOut = [
            ['label' => 'Order', 'value' => '#' . (int)$order['id']],
            ['label' => 'Boost', 'value' => $title],
            ['label' => 'Client', 'value' => (string)($order['client_username'] ?: 'Client')],
            ['label' => 'Earning', 'value' => $earningText],
        ];

        if ($queueType !== '') {
            $rowsOut[] = ['label' => 'Queue', 'value' => $queueType];
        }
        if (!$isCounterStrikeOrder && !empty($opts['server'])) {
            $rowsOut[] = ['label' => 'Server', 'value' => strtoupper((string)$opts['server'])];
        }
        if (!empty($opts['is_duo'])) {
            $rowsOut[] = ['label' => 'Play With Booster', 'value' => 'Yes'];
        }
        if (!empty($opts['is_voice'])) {
            $rowsOut[] = ['label' => 'Voice Chat', 'value' => 'Yes'];
        }

        $extras = [];

        echo json_encode([
            'success' => true,
            'data' => [
                'order_id' => (int)$order['id'],
                // WICHTIG: Hier KEIN created_ts/paid_at mitschicken.
                // Das Frontend behandelt jeden Request, dessen Zeitstempel aelter
                // ist als der Sitzungsstart des Boosters (requestTs < sinceTs), als
                // "alt" und blendet das Modal aus. paid_at liegt fast immer VOR dem
                // Oeffnen des Dashboards -> Modal wurde nie angezeigt. Ohne Zeitstempel
                // bleibt requestTs = 0 und das Modal erscheint beim booster_request-Event.
                'client_username' => (string)($order['client_username'] ?: 'Client'),
                'title' => $title,
                'price' => (string)($order['price'] ?? ''),
                'currency' => (string)($order['currency'] ?? ''),
                'booster_cut' => (string)($order['booster_cut'] ?? ''),
                'summary_rows' => $rowsOut,
                'extras' => [],
            ]
        ]);
    }



    public function booster_update_account()
    {
        if ($this->is_booster) {
            $validator = new Validator;
            $validation = $validator->make($_POST, [
                'username' => 'required',
                'email' => 'required|email',
            ]);
            $validation->validate();

            if (!isset($_POST['languages']) || !is_array($_POST['languages'])) {
                $_POST['languages'] = [];
            }

            // if validation fails, return errors
            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                // Do not save the whole $_POST here.
                // This form does not send discord/discord_id, so saving $_POST can overwrite
                // the existing Discord connection with NULL/empty values.
                $params = [
                    'username'       => esc($_POST['username'] ?? ''),
                    'email'          => esc($_POST['email'] ?? ''),
                    'languages'      => implode('|', array_map('esc', $_POST['languages'])),
                    'show_profile'   => (int)($_POST['show_profile'] ?? 0),
                    'boost_requests' => (int)($_POST['boost_requests'] ?? 0),
                ];

                $update = db_update_row('boosters', ['id' => BOOSTER_ID], $params);
                if ($update != false) {
                    $form_error = false;
                    echo json_encode(array(
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Account updated successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ));
                } else {
                    $form_error = $update;
                }
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please fill in all the fields 😔',
                    ],
                    'playSound' => 'error',
                    'validationErrors' => $form_error,
                ]);
            }
        }
    }

    public function booster_update_password()
    {
        if ($this->is_booster) {
            $validator = new Validator;
            $validation = $validator->make($_POST, [
                'current_password' => 'required',
                'new_password' => 'required|min:6',
                'confirm_password' => 'required|same:new_password',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $currentPassword = (string)($_POST['current_password'] ?? '');
                $newPassword = (string)($_POST['new_password'] ?? '');

                $booster = db_get_row('boosters', [
                    'id' => BOOSTER_ID,
                    'select' => 'id,password',
                ]);

                $currentHash = sha1($currentPassword);
                $storedHash = (string)($booster['password'] ?? '');

                if (!$booster || !hash_equals($storedHash, $currentHash)) {
                    $form_error = ['current_password' => 'Current password is incorrect'];
                } elseif (hash_equals($storedHash, sha1($newPassword))) {
                    $form_error = ['new_password' => 'New password must be different from the current password'];
                } else {
                    $update = db_update_row('boosters', ['id' => BOOSTER_ID], [
                        'password' => sha1($newPassword),
                    ]);

                    if ($update != false) {
                        $form_error = false;
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'success',
                                'title' => 'Success',
                                'message' => 'Password updated successfully 🎉',
                            ],
                            'playSound' => 'success',
                        ]);
                    } else {
                        $form_error = ['new_password' => 'Password could not be updated'];
                    }
                }
            }

            if ($form_error != false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please check your password fields 😔',
                    ],
                    'playSound' => 'error',
                    'validationErrors' => $form_error,
                ]);
            }
        }
    }

    public function booster_update_profile()
    {
        if ($this->is_booster) {
            $gameProfilesRaw = (string)($_POST['game_profiles'] ?? '');
            $gameProfiles = json_decode($gameProfilesRaw, true);
            if (!is_array($gameProfiles)) $gameProfiles = [];
            foreach ((array)($_POST['game_rank_tier'] ?? []) as $gameSlug => $tier) {
                $gameProfiles[$gameSlug]['rank_tier'] = (int)$tier;
                $gameProfiles[$gameSlug]['rank_division'] = (int)(($_POST['game_rank_division'] ?? [])[$gameSlug] ?? 0);
                $gameProfiles[$gameSlug]['specialties'] = (array)(($_POST['game_specialties'] ?? [])[$gameSlug] ?? []);
            }
            unset($_POST['game_profiles'], $_POST['game_rank_tier'], $_POST['game_rank_division'], $_POST['game_specialties']);
            // Dynamic game data is stored separately; reject slug-shaped keys before EasyDB.
            foreach (array_keys($_POST) as $postKey) {
                if (!preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/', (string)$postKey)) unset($_POST[$postKey]);
            }
            if (!isset($_POST['champions'])) {
                $_POST['champions'] = [];
            }

            if (!isset($_POST['roles'])) {
                $_POST['roles'] = [];
            }

            if (!isset($_POST['agents'])) {
                $_POST['agents'] = [];
            }

            foreach ($_POST as $key => $value) {
                if (is_array($value)) {
                    $value = array_values(array_unique(array_filter(array_map('trim', $value), static function ($item) {
                        return $item !== '';
                    })));
                    $_POST[$key] = esc(implode('|', $value));
                }
            }
            if (isset($_POST['lol'])) {
                $_POST['lol_rank_0'] = intval($_POST['lol_rank_0']) ?? 0;
                $_POST['lol_rank_1'] = intval($_POST['lol_rank_1']) ?? 0;
                $_POST['lol_rank'] = $_POST['lol_rank_0'] . '|' . $_POST['lol_rank_1'];
            }
            if (isset($_POST['val'])) {
                $_POST['val_rank_0'] = intval($_POST['val_rank_0']) ?? 0;
                $_POST['val_rank_1'] = intval($_POST['val_rank_1']) ?? 0;
                $_POST['val_rank'] = $_POST['val_rank_0'] . '|' . $_POST['val_rank_1'];
            }

            if (isset($_POST['tft'])) {
                $_POST['tft_rank_0'] = intval($_POST['tft_rank_0']) ?? 0;
                $_POST['tft_rank_1'] = intval($_POST['tft_rank_1']) ?? 0;
                $_POST['tft_rank'] = $_POST['tft_rank_0'] . '|' . $_POST['tft_rank_1'];
            }
            unset($_POST['lol_rank_0']);
            unset($_POST['lol_rank_1']);
            unset($_POST['val_rank_0']);
            unset($_POST['val_rank_1']);
            unset($_POST['tft_rank_0']);
            unset($_POST['tft_rank_1']);
            unset($_POST['lol']);
            unset($_POST['val']);
            unset($_POST['tft']);

            // Build pg_prices JSON from pg_price_0 ... pg_price_10 fields
            $pgPricesArr = [];
            $pgPosted = false;
            for ($pgT = 0; $pgT <= 10; $pgT++) {
                $key = 'pg_price_' . $pgT;
                if (array_key_exists($key, $_POST)) $pgPosted = true;
                if (isset($_POST[$key]) && $_POST[$key] !== '') {
                    $pgEur = floatval($_POST[$key]);
                    $pgPricesArr[$pgT] = $pgEur > 0 ? (int)round($pgEur * 100) : 0;
                } else {
                    $pgPricesArr[$pgT] = 0;
                }
                unset($_POST[$key]);
            }
            // Same reasoning as the Classic block below: a booster without "lol"
            // never sees these inputs, so an absent block must not wipe pg_prices.
            $pgHasAny = array_sum($pgPricesArr) > 0;
            if ($pgPosted) {
                $_POST['pg_prices'] = $pgHasAny ? json_encode($pgPricesArr) : null;
            }

            // General service_prices JSON (currently used for Duo Pass)
            $existingProfile = db_get_row('booster_profiles', ['booster_id' => BOOSTER_ID, 'select' => 'service_prices'], 1);
            $servicePrices = [];
            if (!empty($existingProfile['service_prices'])) {
                $servicePrices = json_decode($existingProfile['service_prices'], true);
                if (!is_array($servicePrices)) {
                    $servicePrices = [];
                }
            }
            if ($pgPosted) {
                if ($pgHasAny) {
                    $servicePrices['pro_games'] = $pgPricesArr;
                } else {
                    unset($servicePrices['pro_games']);
                }
            }

            // The Classic block is only rendered for boosters that actually have
            // lol_classic. If it was never on the form, leave the stored prices alone
            // instead of silently deleting them.
            $classicPgPricesArr = [];
            $classicPgPosted = false;
            for ($classicPgT = 1; $classicPgT <= 7; $classicPgT++) {
                $key = 'classic_pg_price_' . $classicPgT;
                $raw = $_POST[$key] ?? null;
                if (array_key_exists($key, $_POST)) $classicPgPosted = true;
                $classicPgPricesArr[$classicPgT] = ($raw !== null && $raw !== '')
                    ? max(0, (int)round(floatval($raw) * 100))
                    : 0;
                unset($_POST[$key]);
            }
            if ($classicPgPosted) {
                if (array_sum($classicPgPricesArr) > 0) {
                    $servicePrices['lol_classic_pro_games'] = $classicPgPricesArr;
                } else {
                    unset($servicePrices['lol_classic_pro_games']);
                }
            }

            $duoPassArr = [];
            for ($dpT = 0; $dpT <= 10; $dpT++) {
                $keyA = 'duo_pass_price_' . $dpT;
                $keyB = 'dp_price_' . $dpT;
                $raw = $_POST[$keyA] ?? ($_POST[$keyB] ?? null);
                if ($raw !== null && $raw !== '') {
                    $eur = floatval($raw);
                    $duoPassArr[$dpT] = $eur > 0 ? (int)round($eur * 100) : 0;
                } else {
                    $duoPassArr[$dpT] = 0;
                }
                unset($_POST[$keyA], $_POST[$keyB]);
            }
            if (array_sum($duoPassArr) > 0) {
                $servicePrices['duo_pass'] = $duoPassArr;
            }
            $_POST['service_prices'] = !empty($servicePrices) ? json_encode($servicePrices) : null;

            // Remove old single price field if present
            unset($_POST['price_per_game_eur'], $_POST['price_per_game']);

            // Validate/normalize timezone (optional). Empty means "N/A" (not set)
            if (array_key_exists('timezone', $_POST)) {
                $tz = $_POST['timezone'];
                $tz = is_string($tz) ? trim($tz) : '';
                if ($tz === '') {
                    // Store as empty string to represent "not set"
                    $_POST['timezone'] = '';
                } else {
                    $valid_timezones = DateTimeZone::listIdentifiers();
                    if (!in_array($tz, $valid_timezones, true)) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Error',
                                'message' => 'Please select a valid timezone 😔',
                            ],
                            'playSound' => 'error',
                            'validationErrors' => ['timezone' => 'Please select a valid timezone'],
                        ]);
                        return;
                    }
                    $_POST['timezone'] = $tz;
                }
            }

// Extract JSON fields before esc_array (JSON would be corrupted by htmlspecialchars)
            $pg_prices_raw = $_POST['pg_prices'] ?? null;
            $service_prices_raw = $_POST['service_prices'] ?? null;
            unset($_POST['pg_prices'], $_POST['service_prices']);

            $post_params = esc_array($_POST);

            // This endpoint updates booster_profiles only. A strict allowlist
            // prevents game slugs (for example apex-legends) or unrelated form
            // controls from ever being interpreted as SQL identifiers by EasyDB.
            $allowedProfileColumns = [
                'lol_rank', 'val_rank', 'tft_rank',
                'champions', 'roles', 'agents',
                'servers', 'timezone', 'description',
            ];
            $post_params = array_intersect_key($post_params, array_flip($allowedProfileColumns));

            // Re-inject JSON as raw strings
            $post_params['pg_prices'] = $pg_prices_raw !== null ? $pg_prices_raw : null;
            $post_params['service_prices'] = $service_prices_raw !== null ? $service_prices_raw : null;

            $upd_booster = db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], $post_params);
            if ($upd_booster) {
                if ($gameProfiles) lb_booster_game_profiles_save((int)BOOSTER_ID, $gameProfiles);
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Profile updated successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ));
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }


    /**
     * Quick inline booster profile updates (used in Booster Order View).
     * Supports: icon, cover, timezone, rank (lol_rank), champions, roles, languages.
     */
    public function booster_profile_quick_update()
    {
        if (!$this->is_booster) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized 😔'],
                'playSound' => 'error',
            ]);
            return;
        }

        $field = esc($_POST['field'] ?? '');
        $allowed = ['icon', 'cover', 'timezone', 'rank', 'champions', 'roles', 'languages', 'servers', 'description', 'show_profile', 'boost_requests', 'setup_settings_ack'];
        if (!in_array($field, $allowed, true)) {
            echo json_encode([
                'success' => false,
                'message' => 'Invalid field',
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid field 😔'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Ensure profile row exists
        $profile = db_get_row('booster_profiles', ['booster_id' => BOOSTER_ID]);
        if ($profile == false) {
            db_insert_row('booster_profiles', ['booster_id' => BOOSTER_ID]);
        }

        $resp = [
            'success' => true,
            'data' => [],
        ];

        // ---------- FILE UPLOADS ----------
        if ($field === 'icon' || $field === 'cover') {
            $file = $_FILES['image_url'] ?? null;
            if (!$file || empty($file['name'])) {
                echo json_encode([
                    'success' => false,
                    'message' => 'Missing file',
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please choose a file 😔'],
                    'playSound' => 'error',
                ]);
                return;
            }

            $folder = ($field === 'icon') ? 'icons/' : 'covers/';
            $image_url = upload_image($file, $folder);
            if ($image_url == false) {
                echo json_encode([
                    'success' => false,
                    'message' => 'Invalid file type',
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid file type 😔'],
                    'playSound' => 'error',
                ]);
                return;
            }

            if ($field === 'icon') {
                db_update_row('boosters', ['id' => BOOSTER_ID], ['icon' => $image_url]);
                $resp['data']['icon_url'] = $image_url;
                $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Avatar updated 🎉'];
            } else {
                db_update_row('boosters', ['id' => BOOSTER_ID], ['cover' => $image_url]);
                $resp['data']['cover_url'] = $image_url;
                $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Banner updated 🎉'];
            }
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // ---------- TIMEZONE ----------
        if ($field === 'timezone') {
            $tz = $_POST['value'] ?? '';
            $tz = is_string($tz) ? trim($tz) : '';

            if ($tz === '') {
                $tz = '';
            } else {
                $valid_timezones = DateTimeZone::listIdentifiers();
                if (!in_array($tz, $valid_timezones, true)) {
                    echo json_encode([
                        'success' => false,
                        'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select a valid timezone 😔'],
                        'playSound' => 'error',
                        'validationErrors' => ['timezone' => 'Please select a valid timezone'],
                    ]);
                    return;
                }
            }

            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['timezone' => $tz]);

            $display = ($tz === '') ? 'N/A' : $tz;
            if (function_exists('util_format_timezone_display')) {
                $display = (string) util_format_timezone_display($tz);
            }

            $resp['data']['timezone_raw'] = $tz;
            $resp['data']['timezone_display'] = $display;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Timezone updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // ---------- RANK (booster_profiles.lol_rank: "tier|div") ----------
        if ($field === 'rank') {
            $tier = intval($_POST['rank_tier'] ?? 0);
            $div = intval($_POST['rank_div'] ?? 0);

            if ($tier < 0 || $tier > 10) $tier = 0;
            if ($div < 0 || $div > 4) $div = 0;

            // Division rules:
            // - Unranked: no division
            // - Master / Grandmaster / Challenger: no division
            // - Iron..Diamond: IV-III-II-I (stored as 4..1)
            if ($tier === 0 || $tier >= 8) {
                $div = 0;
            }

            $rankStr = $tier . '|' . $div;
            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['lol_rank' => $rankStr]);

            $lolranks = [
                1 => 'Iron', 2 => 'Bronze', 3 => 'Silver', 4 => 'Gold', 5 => 'Platinum',
                6 => 'Emerald', 7 => 'Diamond', 8 => 'Master', 9 => 'Grandmaster', 10 => 'Challenger'
            ];
            $rankName = $lolranks[$tier] ?? 'Unranked';
            $rankIcon = ASSET_URL . '/core/main/img/lol/ranks/max/' . $tier . '.png';

            $resp['data']['rank_tier'] = $tier;
            $resp['data']['rank_div'] = $div;
            $resp['data']['rank_id'] = $tier;
            $resp['data']['rank_name'] = $rankName;
            $resp['data']['rank_icon'] = $rankIcon;

            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Rank updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // helper: sanitize string list to pipe string
        $to_pipe = function ($arr) {
            if (!is_array($arr)) $arr = [];
            $arr = array_values(array_filter(array_map(function ($v) {
                return esc(trim((string) $v));
            }, $arr)));
            return implode('|', $arr);
        };

        // ---------- CHAMPIONS ----------
        if ($field === 'champions') {
            $champs = $_POST['champions'] ?? [];
            if (!is_array($champs)) $champs = [$champs];
            $pipe = $to_pipe($champs);

            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['champions' => $pipe]);

            $resp['data']['champions_raw'] = $pipe;
            $resp['data']['champions'] = $champs; // array of champion keys
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Champions updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // ---------- ROLES ----------
        if ($field === 'roles') {
            $roles = $_POST['roles'] ?? [];
            if (!is_array($roles)) $roles = [$roles];

            $allow = ['TopLane', 'Jungle', 'MidLane', 'AdCarry', 'Support'];
            $roles = array_values(array_filter(array_map(function ($r) {
                return trim((string) $r);
            }, $roles), function ($r) use ($allow) {
                return in_array($r, $allow, true);
            }));

            $pipe = $to_pipe($roles);
            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['roles' => $pipe]);

            $resp['data']['roles_raw'] = $pipe;
            $resp['data']['roles'] = $roles; // array of role keys
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Lanes updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // ---------- LANGUAGES (boosters.languages) ----------
        if ($field === 'languages') {
            $langs = $_POST['languages'] ?? [];
            if (!is_array($langs)) $langs = [$langs];

            // Store the values exactly as submitted by the UI (e.g. "Deutsch", "Français", "Español")
            // Only trim and remove empty entries.
            $langs = array_values(array_filter(array_map(function ($l) {
                return trim((string) $l);
            }, $langs), function ($l) {
                return $l !== '';
            }));

            $pipe = $to_pipe($langs);

            // Also acknowledge setup step 2 (so it won't be shown again after Next)
            db_update_row('boosters', ['id' => BOOSTER_ID], [
                'languages' => $pipe,
                'setup_settings_ack' => 1
            ]);

            $resp['data']['languages_raw'] = $pipe;
            $resp['data']['languages'] = $langs; // array of labels/keys
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Languages updated 🎉'];
            $resp['playSound'] = 'success';
            $resp['refreshPage'] = true;

            echo json_encode($resp);
            return;
        }


        
        

        // ---------- OPTIONAL TOGGLES (boosters.show_profile / boosters.boost_requests) ----------
        if ($field === 'show_profile') {
            $val = intval($_POST['value'] ?? 0);
            $val = ($val === 1) ? 1 : 0;

            db_update_row('boosters', ['id' => BOOSTER_ID], ['show_profile' => $val]);

            $resp['data']['show_profile'] = $val;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Profile visibility updated 🎉'];
            $resp['playSound'] = 'success';
            $resp['refreshPage'] = true;

            echo json_encode($resp);
            return;
        }

        if ($field === 'boost_requests') {
            $val = intval($_POST['value'] ?? 0);
            $val = ($val === 1) ? 1 : 0;

            db_update_row('boosters', ['id' => BOOSTER_ID], ['boost_requests' => $val]);

            $resp['data']['boost_requests'] = $val;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Request setting updated 🎉'];
            $resp['playSound'] = 'success';
            $resp['refreshPage'] = true;

            echo json_encode($resp);
            return;
        }

        // ---------- SETUP ACK (boosters.setup_settings_ack) ----------
        // This is used by the Setup Guide: once "Next" is clicked on the settings step,
        // the user will not be asked again.
        if ($field === 'setup_settings_ack') {
            db_update_row('boosters', ['id' => BOOSTER_ID], ['setup_settings_ack' => 1]);

            $resp['data']['setup_settings_ack'] = 1;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Saved', 'message' => 'Preferences confirmed.'];
            $resp['playSound'] = 'success';
            $resp['refreshPage'] = true;

            echo json_encode($resp);
            return;
        }

// ---------- SERVERS (booster_profiles.servers) ----------
        if ($field === 'servers') {
            $servers = $_POST['servers'] ?? [];
            if (!is_array($servers)) $servers = [$servers];
            $pipe = $to_pipe($servers);

            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['servers' => $pipe]);

            $resp['data']['servers_raw'] = $pipe;
            $resp['data']['servers'] = $servers;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Servers updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

        // ---------- DESCRIPTION (booster_profiles.description) ----------
        if ($field === 'description') {
            $desc = $_POST['value'] ?? '';
            $desc = is_string($desc) ? trim($desc) : '';
            db_update_row('booster_profiles', ['booster_id' => BOOSTER_ID], ['description' => esc($desc)]);

            $resp['data']['description'] = $desc;
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Success', 'message' => 'Description updated 🎉'];
            $resp['playSound'] = 'success';

            echo json_encode($resp);
            return;
        }

// Fallback
        echo json_encode([
            'success' => false,
            'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Nothing to update 😔'],
            'playSound' => 'error',
        ]);
    }

    public function egirl_profile_quick_update()
    {
        if (!$this->is_egirl) {
            echo json_encode([
                'success'   => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized 😔'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (function_exists('lb_egirl_profiles_ensure_game_ranks_column')) {
            lb_egirl_profiles_ensure_game_ranks_column();
        }

        $field   = esc($_POST['field'] ?? '');
        $allowed = ['bio', 'languages', 'games', 'voice_chat'];
        if (!in_array($field, $allowed, true)) {
            echo json_encode([
                'success'   => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid field 😔'],
                'playSound' => 'error',
            ]);
            return;
        }

        global $db;

        // Ensure egirl_profiles row exists
        if (!$db->row("SELECT id FROM egirl_profiles WHERE egirl_id = ? LIMIT 1", BOOSTER_ID)) {
            $db->run("INSERT IGNORE INTO egirl_profiles (egirl_id) VALUES (?)", BOOSTER_ID);
        }

        $resp = ['success' => true];

        if ($field === 'bio') {
            $val = trim((string)($_POST['value'] ?? ''));
            if (strlen($val) < 30) {
                echo json_encode([
                    'success'   => false,
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Bio must be at least 30 characters 😔'],
                    'playSound' => 'error',
                ]);
                return;
            }
            $db->run("UPDATE egirl_profiles SET bio = ? WHERE egirl_id = ?", $val, BOOSTER_ID);
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Saved', 'message' => 'Bio updated 🎉'];
            $resp['playSound'] = 'success';
        }

        elseif ($field === 'languages') {
            $langs = array_values(array_filter(array_map('trim', (array)($_POST['languages'] ?? []))));
            if (empty($langs)) {
                echo json_encode([
                    'success'   => false,
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select at least one language 😔'],
                    'playSound' => 'error',
                ]);
                return;
            }
            $val = implode('|', $langs);
            $db->run("UPDATE egirl_profiles SET languages = ? WHERE egirl_id = ?", $val, BOOSTER_ID);
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Saved', 'message' => 'Languages updated 🎉'];
            $resp['playSound'] = 'success';
        }

        elseif ($field === 'games') {
            $allowed_games = ['lol', 'val', 'tft'];
            $games = array_values(array_filter(array_map('trim', (array)($_POST['games'] ?? [])), fn($g) => in_array($g, $allowed_games, true)));
            if (empty($games)) {
                echo json_encode([
                    'success'   => false,
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select at least one game 😔'],
                    'playSound' => 'error',
                ]);
                return;
            }
            $val = implode('|', $games);
            $db->run("UPDATE egirl_profiles SET games = ? WHERE egirl_id = ?", $val, BOOSTER_ID);
            // Also update boosters.games so listing filters work
            $db->run("UPDATE boosters SET games = ? WHERE id = ?", $val, BOOSTER_ID);
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Saved', 'message' => 'Games updated 🎉'];
            $resp['playSound'] = 'success';
        }

        elseif ($field === 'voice_chat') {
            $val = (int)($_POST['value'] ?? 0) === 1 ? 1 : 0;
            $db->run("UPDATE boosters SET voice_chat = ? WHERE id = ?", $val, BOOSTER_ID);
            $resp['sendToast'] = ['type' => 'success', 'title' => 'Saved', 'message' => 'Voice chat preference updated 🎉'];
            $resp['playSound'] = 'success';
        }

        echo json_encode($resp);
    }

