    public function get_duo_pass_boosters()
    {
        global $db;

        $boosters = $db->run("
            SELECT boosters.id AS booster_id, boosters.username, boosters.profile_picture,
                   booster_ranks.name AS rank_name,
                   booster_profiles.service_prices,
                   CASE WHEN " . lb_booster_online_sql('boosters') . " THEN 1 ELSE 0 END AS is_online
            FROM boosters
            INNER JOIN booster_profiles ON boosters.id = booster_profiles.booster_id
            LEFT JOIN booster_ranks ON boosters.rank_id = booster_ranks.id
            WHERE boosters.is_banned = 0
              AND boosters.boost_requests = 1
              AND booster_profiles.service_prices IS NOT NULL
              AND booster_profiles.service_prices != ''
              AND booster_profiles.service_prices LIKE '%\"duo_pass\"%'
            ORDER BY is_online DESC, boosters.id ASC
        ");

        echo json_encode(['status' => 'success', 'boosters' => $boosters ?: []]);
    }

    public function load_boosters()
    {
        global $db;

        $page = $_POST['page'] ?? 1;
        $itemsPerPage = 9;
        $offset = ($page - 1) * $itemsPerPage;

        $query = "SELECT 
            boosters.*, 
            booster_ranks.name as rank_name, 
            booster_profiles.*, 
            boosters.id as booster_id,
            COUNT(orders.id) as completed_orders,
            COALESCE(rev.review_count, 0) AS review_count
        FROM boosters
        INNER JOIN booster_profiles 
            ON boosters.id = booster_profiles.booster_id
        LEFT JOIN booster_ranks 
            ON boosters.rank_id = booster_ranks.id
        LEFT JOIN orders 
            ON boosters.id = orders.booster_id AND orders.status = 'COMPLETED'
        LEFT JOIN (
            SELECT booster_id, COUNT(*) AS review_count
            FROM reviews WHERE approved = 1
            GROUP BY booster_id
        ) rev ON rev.booster_id = boosters.id
        WHERE 
            boosters.is_banned = 0 
            AND (boosters.is_egirl IS NULL OR boosters.is_egirl = 0)
            AND booster_profiles.champions IS NOT NULL 
            AND booster_profiles.roles IS NOT NULL
            AND boosters.show_profile = 1
        GROUP BY boosters.id
        ORDER BY completed_orders DESC, boosters.id ASC
        LIMIT $itemsPerPage OFFSET $offset";

        $boosters = $db->run($query);

        view_file('/website/components/boosters/booster-cards', ['boosters' => $boosters]);
    }

    public function filter_boosters()
    {
        global $db;

        $name      = $_POST['name']      ?? '';
        $online    = (int)($_POST['online'] ?? 0);

        // ── Game ──────────────────────────────────────────────────────────────
        // Frontend sends either:
        //   game=lol          (single string, new dropdown)
        //   games[]=lol       (legacy array, kept for compatibility)
        $game_single = trim((string)($_POST['game'] ?? ''));
        // display_game only picks which game's rank/champions/roles a card shows.
        // It must NEVER narrow the result set - LoL Classic Pro Games uses it so the
        // cards render the booster's LoL profile without excluding boosters whose
        // `games` list happens to be spelled differently.
        $display_game = trim((string)($_POST['display_game'] ?? ''));
        $games_arr   = $_POST['games'] ?? [];
        if (!is_array($games_arr)) $games_arr = [$games_arr];
        // Merge both sources into one list
        if ($game_single !== '') $games_arr[] = $game_single;
        $games = array_values(array_filter(array_map('esc', $games_arr)));

        // ── Other filters ─────────────────────────────────────────────────────
        $roles     = $_POST['roles']     ?? [];
        $champions = $_POST['champions'] ?? [];
        $agents    = $_POST['agents']    ?? [];
        $languages = $_POST['languages'] ?? [];
        $servers   = $_POST['servers']   ?? [];

        if (!is_array($roles))     $roles     = [$roles];
        if (!is_array($champions)) $champions = [$champions];
        if (!is_array($agents))    $agents    = [$agents];
        if (!is_array($languages)) $languages = [$languages];
        if (!is_array($servers))   $servers   = [$servers];

        $name      = esc($name);
        $roles     = array_values(array_filter(array_map('esc', $roles)));
        $champions = array_values(array_filter(array_map('esc', $champions)));
        $agents    = array_values(array_filter(array_map('esc', $agents)));
        $languages = array_values(array_filter(array_map('esc', $languages)));
        $servers   = array_values(array_filter(array_map('esc', $servers)));

        // ── Base conditions ───────────────────────────────────────────────────
        $where   = [];
        $where[] = "boosters.is_banned = 0";
        $where[] = "boosters.show_profile = 1";
        $where[] = "boosters.is_egirl = 0";   // only real boosters, not GG-Girls
        $where[] = "boosters.username LIKE '%{$name}%'";
        $where[] = "booster_profiles.champions IS NOT NULL";
        $where[] = "booster_profiles.roles IS NOT NULL";

        // ── Game filter ───────────────────────────────────────────────────────
        if (!empty($games)) {
            $tmp = [];
            foreach ($games as $g) {
                // Match a complete token in the legacy pipe/comma list. A plain
                // substring match made e.g. "lol" also match "lol-wild-rift".
                $tmp[] = "CONCAT(',', REPLACE(REPLACE(LOWER(COALESCE(boosters.games, '')), '|', ','), ' ', ''), ',') LIKE '%,{$g},%'";
            }
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Language filter ───────────────────────────────────────────────────
        if (!empty($languages)) {
            $tmp = [];
            foreach ($languages as $l)
                $tmp[] = "boosters.languages LIKE '%{$l}%'";
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Role filter ───────────────────────────────────────────────────────
        if (!empty($roles)) {
            $tmp = [];
            foreach ($roles as $r)
                $tmp[] = "booster_profiles.roles LIKE '%{$r}%'";
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Champion filter ───────────────────────────────────────────────────
        if (!empty($champions)) {
            $tmp = [];
            foreach ($champions as $c)
                $tmp[] = "booster_profiles.champions LIKE '%{$c}%'";
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Agents filter (Valorant) ──────────────────────────────────────────
        if (!empty($agents)) {
            $tmp = [];
            foreach ($agents as $a)
                $tmp[] = "booster_profiles.agents LIKE '%{$a}%'";
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Server filter ─────────────────────────────────────────────────────
        if (!empty($servers)) {
            $tmp = [];
            foreach ($servers as $s)
                $tmp[] = "booster_profiles.servers LIKE '%{$s}%'";
            $where[] = "(" . implode(" OR ", $tmp) . ")";
        }

        // ── Online filter ─────────────────────────────────────────────────────
        if ($online === 1) {
            $where[] = lb_booster_online_sql('boosters');
        }

        // ── Pro Games ─────────────────────────────────────────────────────────
        if (!empty($_POST['has_pg_prices'])) {
            $where[] = "(booster_profiles.pg_prices IS NOT NULL AND booster_profiles.pg_prices != '' AND booster_profiles.pg_prices != '{}')";
            $where[] = "COALESCE(boosters.boost_requests, 0) = 1";
        }
        if (!empty($_POST['has_classic_pg_prices'])) {
            // Classic has its own rank ladder (Salt..Legend), so a booster only
            // qualifies with dedicated Classic prices — normal pg_prices do not map.
            $where[] = "(booster_profiles.service_prices IS NOT NULL AND booster_profiles.service_prices != '' AND booster_profiles.service_prices LIKE '%\"lol_classic_pro_games\"%')";
            $where[] = "COALESCE(boosters.boost_requests, 0) = 1";
        }

        // ── Duo Pass ─────────────────────────────────────────────────────────
        if (!empty($_POST['has_duo_pass_prices'])) {
            $where[] = "(booster_profiles.service_prices IS NOT NULL AND booster_profiles.service_prices != '' AND booster_profiles.service_prices LIKE '%\"duo_pass\"%')";
            $where[] = "COALESCE(boosters.boost_requests, 0) = 1";
        }

        $query = "
        SELECT boosters.*, booster_ranks.name as rank_name, booster_profiles.*,
            COUNT(orders.id) as completed_orders,
            COALESCE(rev.review_count, 0) AS review_count
        FROM boosters
        INNER JOIN booster_profiles ON boosters.id = booster_profiles.booster_id
        LEFT JOIN booster_ranks ON boosters.rank_id = booster_ranks.id
        LEFT JOIN orders
            ON boosters.id = orders.booster_id AND orders.status = 'COMPLETED'
        LEFT JOIN (
            SELECT booster_id, COUNT(*) AS review_count
            FROM reviews WHERE approved = 1
            GROUP BY booster_id
        ) rev ON rev.booster_id = boosters.id
        WHERE " . implode("\n AND ", $where) . "
        GROUP BY boosters.id
        ORDER BY completed_orders DESC, boosters.id ASC
        ";

        $boosters = $db->run($query);

        view_file("/website/components/boosters/booster-cards", ["boosters" => $boosters, "selected_game" => ($game_single !== '' ? $game_single : $display_game)]);
    }
    public function load_booster_orders()
    {
        global $db;

        $page = $_POST['page'] ?? 1;
        $itemsPerPage = 5;
        $offset = ($page - 1) * $itemsPerPage;

        $id = $_POST['id'];

        $sql = "
        SELECT * 
        FROM orders 
        WHERE booster_id = $id
        AND status IN ('COMPLETED', 'IN_PROGRESS') 
        ORDER BY created_at DESC 
        LIMIT $offset, $itemsPerPage
        ";

        $orders = $db->run($sql);

        $forms = db_get_rows('boost_forms', ['select' => 'id,type,name,icon,game']);
        $forms = array_column($forms, null, 'id');

        foreach ($orders as $key => $order) {
            $order_opts = db_get_row('order_options', ['order_id' => $order['id'], 'select' => 'server,hours,start_tier,start_division,end_tier,end_division,start_lp,end_lp,matches,queue_type,is_duo'], 1);
            $orders[$key] = array_merge($order_opts, $forms[$order['form_id']], $order);
        }

        $html = '';

        foreach ($orders as $order) {
            $html .= "<tr>
                        <td>
                            <div class='type'>
                                <span class='icon'>
                                    <i class='fa-duotone text-body " . $order['icon'] . "'></i>
                                </span>
                                <p class='mb-0'>
                                    " . $order['name'] . "
                                    <small class='text-primary d-block'>
                                        " . util_format_boost_overview($order['game'], $order['type'], $order) . "
                                    </small>
                                </p>
                            </div>
                        </td>
                        <td style='width: 570px;'>
                            " . util_format_boost_icons($order['game'], $order['type'], $order) . "
                        </td>
                        <td>
                            <span class='badge bg-primary bg-opacity-75 d-block p-3'>
                                " . $order['status'] . "
                            </span>
                        </td>
                    </tr>";
        }

        echo $html;
    }

    public function admin_add_loyalty_rank()
    {
        if ($this->is_admin) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'name' => 'required',
                'target_amount' => 'required|numeric',
                'cashback' => 'required|numeric',
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors();
                $form_error = $errors->firstOfAll();
            } else {
                $post_data = esc_array($_POST);
                $insert = db_insert_row('loyalty_ranks', $post_data);
                if ($insert) {
                    $form_error = false;
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Loyalty rank added successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'redirectUrl' => BASE_URL . '/admin-area/loyalty',
                    ]);
                } else {
                    $form_error = $insert;
                }
            }
        }
    }

