    public function admin_add_seller_rank()
    {
        global $db;

        if (!$this->is_admin) {
            return;
        }

        $validator = new Validator();
        $validation = $validator->make($_POST, [
            'name' => 'required',
            'min_sales' => 'required|numeric',
            'fee_percent' => 'required|numeric',
            'sort_order' => 'required|numeric',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors();
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Validation error',
                    'message' => implode(' ', $errors->firstOfAll()),
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $post_data = esc_array($_POST);
        $min_sales = (int) ($post_data['min_sales'] ?? 0);
        $exists = $db->row("SELECT id FROM seller_ranks WHERE min_sales = ? LIMIT 1", $min_sales);
        if (!empty($exists)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Duplicate threshold',
                    'message' => 'A seller rank with this sales threshold already exists.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $insert_data = [
            'name' => trim((string) ($post_data['name'] ?? '')),
            'min_sales' => $min_sales,
            'icon_class' => trim((string) ($post_data['icon_class'] ?? 'fa-solid fa-badge-check')),
            'icon_color' => trim((string) ($post_data['icon_color'] ?? 'text-slate-400')),
            'fee_percent' => number_format((float) ($post_data['fee_percent'] ?? 0), 2, '.', ''),
            'sort_order' => (int) ($post_data['sort_order'] ?? 0),
            'status' => isset($post_data['status']) ? (int) $post_data['status'] : 1,
        ];

        $insert = db_insert_row('seller_ranks', $insert_data);

        if ($insert) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Seller rank added successfully 🎉',
                ],
                'playSound' => 'success',
                'redirectUrl' => BASE_URL . '/admin-area/seller-ranks',
            ]);
            return;
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Something went wrong 😔',
            ],
            'playSound' => 'error',
        ]);
    }

    public function admin_update_seller_rank()
    {
