        }

        $update_data = [
            'name' => trim((string) ($post_data['name'] ?? '')),
            'min_sales' => $min_sales,
            'icon_class' => trim((string) ($post_data['icon_class'] ?? 'fa-solid fa-badge-check')),
            'icon_color' => trim((string) ($post_data['icon_color'] ?? 'text-slate-400')),
            'fee_percent' => number_format((float) ($post_data['fee_percent'] ?? 0), 2, '.', ''),
            'sort_order' => (int) ($post_data['sort_order'] ?? 0),
            'status' => isset($post_data['status']) ? (int) $post_data['status'] : 1,
        ];

        $update = db_update_row('seller_ranks', ['id' => $id], $update_data);

        if ($update) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Seller rank updated successfully 🎉',
                ],
                'playSound' => 'success',
            ]);
            return;
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Something went wrong 😔',
            ],
            'playSound' => 'error',
        ]);
    }

    public function admin_delete_seller_rank()
    {
        global $db;

        if (!$this->is_admin) {
            return;
        }

        $id = (int) ($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid seller rank id.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $rank = $db->row("SELECT * FROM seller_ranks WHERE id = ? LIMIT 1", $id);
        if (empty($rank)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Seller rank not found.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $db->run("UPDATE sellers SET seller_rank_id = NULL WHERE seller_rank_id = ?", $id);
        $deleted = $db->run("DELETE FROM seller_ranks WHERE id = ? LIMIT 1", $id);

        if ($deleted) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Seller rank deleted successfully 🗑️',
                ],
                'playSound' => 'success',
                'redirectUrl' => BASE_URL . '/admin-area/seller-ranks',
            ]);
            return;
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Something went wrong 😔',
            ],
            'playSound' => 'error',
        ]);
    }

    public function admin_recalculate_seller_ranks()
{
    global $db;

    if (!$this->is_admin) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Unauthorized.',
            ],
            'playSound' => 'error',
        ]);
        return;
    }

    $ranks = $db->run("SELECT * FROM seller_ranks WHERE status = 1 ORDER BY min_sales ASC, sort_order ASC") ?: [];
    if (empty($ranks)) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'No ranks found',
                'message' => 'Please create at least one active seller rank first.',
            ],
            'playSound' => 'error',
        ]);
        return;
    }

    $sellers = $db->run("SELECT id FROM sellers ORDER BY id ASC") ?: [];
    $updated_count = 0;

    foreach ($sellers as $seller) {
        $seller_id = (int)($seller['id'] ?? 0);
        if ($seller_id <= 0) {
            continue;
        }

        $total_sold_row = $db->row(
            "SELECT
                COALESCE((SELECT COUNT(*) FROM selling_accounts WHERE seller_id = ? AND sold = 1 AND client_id IS NOT NULL), 0)
                +
                COALESCE((SELECT SUM(sold_count) FROM selling_items WHERE seller_id = ?), 0) AS cnt",
            $seller_id,
            $seller_id
        );

        $total_sales = (int)($total_sold_row['cnt'] ?? 0);
        $matched_rank = null;

        foreach ($ranks as $rank) {
            if ($total_sales >= (int)($rank['min_sales'] ?? 0)) {
                $matched_rank = $rank;
            }
        }

        if (!empty($matched_rank)) {
            $iconValue = trim(
                ((string)($matched_rank['icon_class'] ?? 'fa-solid fa-badge-check')) . ' ' .
                ((string)($matched_rank['icon_color'] ?? 'text-slate-400'))
            );

            $db->run(
                "UPDATE sellers
                 SET seller_rank_id = ?, rank = ?, fee_percent = ?, rank_icon = ?
                 WHERE id = ?",
                (int)$matched_rank['id'],
                (string)($matched_rank['name'] ?? ''),
                (float)($matched_rank['fee_percent'] ?? 0),
                $iconValue,
                $seller_id
            );

            $updated_count++;
        }
    }

    echo json_encode([
        'sendToast' => [
            'type' => 'success',
            'title' => 'Success',
            'message' => $updated_count . ' seller ranks recalculated successfully 🎉',
        ],
        'playSound' => 'success',
        'refreshPage' => true,
    ]);
}

    public function admin_sync_seller_ranks()
    {
        return $this->admin_recalculate_seller_ranks();
    }

    public function checkout_coins_toggle()
    {
        if (!$this->is_client) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Please login first.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $invoice_id = esc($_POST['invoice_id']);
        $use_coins = esc($_POST['use_coins']);

        $invoice = db_get_row('invoices', ['uuid' => $invoice_id, 'client_id' => CLIENT_ID]);

        // Fallback: claim guest checkout for current client
        if (!$invoice) {
            $invoice_any = db_get_row('invoices', ['uuid' => $invoice_id], 1);
            if ($invoice_any && (int)($invoice_any['client_id'] ?? 0) === 0) {
                $guestType = (string)($invoice_any['order_type'] ?? '');
                if ($guestType === 'egirl_session') {
                    db_update_row('invoices', ['id' => $invoice_any['id']], ['client_id' => CLIENT_ID]);
                    db_update_row('egirl_orders', ['id' => $invoice_any['order_id']], ['client_id' => CLIENT_ID]);
                    $invoice = db_get_row('invoices', ['id' => $invoice_any['id']], 1);
                } elseif ($guestType === 'digital_good') {
                    db_update_row('invoices', ['id' => $invoice_any['id']], ['client_id' => CLIENT_ID]);
                    try {
                        global $db;
                        $db->run("UPDATE digital_good_purchases SET client_id = ? WHERE invoice_id = ? AND (client_id IS NULL OR client_id = 0)", (int)CLIENT_ID, (int)$invoice_any['id']);
                    } catch (\Throwable $e) {}
                    $invoice = db_get_row('invoices', ['id' => $invoice_any['id']], 1);
                }
            }
        }

        if (!$invoice) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invoice not found',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $total_price = (float) $invoice['total_price'];
        $coins_used = (float) ($invoice['coins_used'] ?? 0);

        $new_total_price = $total_price;
        $new_coins_used = $coins_used;

        if ($use_coins == 'true') {
            $available_coins = (float) CLIENT_DATA['points'] * 100;
            if ($available_coins >= $total_price) {
                $new_total_price = 0;
                $new_coins_used = $total_price / 100;
            } else {
                $new_total_price = $total_price - $available_coins;
                $new_coins_used = $available_coins / 100;
            }
        } else {
            $new_total_price = $total_price + $coins_used * 100;
            $new_coins_used = 0;
        }

        db_update_row(
            'invoices',
            ['uuid' => $invoice_id, 'client_id' => CLIENT_ID],
            ['coins_used' => $new_coins_used, 'total_price' => $new_total_price]
        );

        echo json_encode([
            'coins_used' => $new_coins_used,
            'total_price' => $new_total_price,
        ]);
    }

    public function admin_add_prize()
