                } else {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Failed to add prize.',
                        ],
                        'playSound' => 'error',
                    ]);
                }
            }
        }
    }

