    function admin_update_coins()
    {
        if ($this->is_admin) {
            $validator = new Validator();
            $validation = $validator->make($_POST, [
                'points' => 'required|numeric'
            ]);
            $validation->validate();

            if ($validation->fails()) {
                $errors = $validation->errors()->firstOfAll();
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Please fill in all the fields 😔',
                    ],
                    'playSound' => 'error',
                    'validationErrors' => $errors,
                ]);
            } else {
                $record = db_get_row('clients', ['id' => $_POST['id']], 'points');
                $current_points = $record['points'] ?? 0;

                if ($_POST['type'] == 'increment') {
                    $new_points = $current_points + number_format($_POST['points'], 2);
                } elseif ($_POST['type'] == 'decrement') {
                    $new_points = $current_points - number_format($_POST['points'], 2);

                    if ($new_points < 0) {
                        echo json_encode([
                            'sendToast' => [
                                'type' => 'danger',
                                'title' => 'Error',
                                'message' => 'Client coins cannot be negative.',
                            ],
                            'playSound' => 'error',
                        ]);
                        return;
                    }
                }

                $post_data = esc_array($_POST);
                $update = db_update_row('clients', ['id' => $post_data['id']], ['points' => number_format($new_points, 2)]);

                if ($_POST['type'] == 'increment') {
                    db_add_row('coins_history', [
                        'client_id' => $post_data['id'],
                        'amount' => number_format($_POST['points'], 2),
                        'type' => 'increment',
                        'reason' => '🎁 Bonus coins from the team'
                    ]);
                } elseif ($_POST['type'] == 'decrement') {
                    db_add_row('coins_history', [
                        'client_id' => $post_data['id'],
                        'amount' => number_format($_POST['points'], 2),
                        'type' => 'decrement',
                        'reason' => '🔄 Deducted coins by admin'
                    ]);
                }

                if ($update) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'success',
                            'title' => 'Success',
                            'message' => 'Client coins updated successfully 🎉',
                        ],
                        'playSound' => 'success',
                        'refreshPage' => true,
                    ]);
                } else {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'Failed to update client coins.',
                        ],
                        'playSound' => 'error',
                        'refreshPage' => true,
                    ]);
                }
            }
        }
    }

