    public function check_new_orders()
    {
        global $db;

        $booster_id = (int) (BOOSTER_ID ?? 0);

        if (!$booster_id) {
            echo json_encode(['success' => false, 'message' => 'Not logged in']);
            return;
        }

        // GG-Girls don't use the boost_forms/orders system at all — they have
        // their own egirl_orders table. Branch off early and reuse the same
        // toast/sound frontend that already exists for regular boosters.
        if (defined('IS_EGIRL') && IS_EGIRL) {
            $lastOrderId = isset($_POST['last_order_id']) ? (int) $_POST['last_order_id'] : 0;
            $sinceTs = isset($_POST['since_ts']) ? (int) $_POST['since_ts'] : 0;

            $query = "SELECT eo.*
                        FROM egirl_orders eo
                       WHERE eo.status = 'PAID'
                         AND (eo.egirl_id = 0 OR eo.egirl_id = ?)
                         AND eo.id > ?
                         AND eo.created_at >= DATE_SUB(NOW(), INTERVAL 2 MINUTE)";
            $args = [$booster_id, $lastOrderId];

            if ($sinceTs > 0) {
                $query .= " AND eo.created_at >= FROM_UNIXTIME(?)";
                $args[] = $sinceTs;
            }
            $query .= " ORDER BY eo.id ASC LIMIT 1";

            $rows = $db->run($query, ...$args);
            if (!$rows || empty($rows)) {
                echo json_encode(['success' => false, 'data' => null]);
                return;
            }

            $order = $rows[0];

            $clientUsername = '';
            $clientIcon = '';
            $clientId = (int)($order['client_id'] ?? 0);
            if ($clientId > 0) {
                $clientRow = db_get_row('clients', ['id' => $clientId], 1);
                $clientUsername = trim((string)($clientRow['username'] ?? $clientRow['name'] ?? $clientRow['email'] ?? ''));
                $clientIcon = trim((string)($clientRow['icon'] ?? ''));
            }

            $name = (string)($order['service_title'] ?? 'GG-Girl Booking');

            // Best-effort: pull mode/server out of the structured DATA: json
            // block (used by the LoL GGirl boost flow), fall back to game/unit.
            $modeMeta = ['mode' => '', 'server' => ''];
            $notes = (string)($order['client_notes'] ?? '');
            if (preg_match('/DATA:\s*(\{.*\})/s', $notes, $m)) {
                $json = json_decode(trim($m[1]), true);
                if (is_array($json)) {
                    $modeMeta['mode'] = (string)($json['mode_title'] ?? '');
                    $modeMeta['server'] = strtoupper((string)($json['server'] ?? ''));
                }
            }
            $amount = (int)($order['unit_value'] ?? 1);
            $unit = (string)($order['unit_type'] ?? 'games');
            $unitLabel = $amount . ' ' . ($amount === 1 ? rtrim($unit, 's') : $unit);

            $detailsParts = [];
            if ($modeMeta['server'] !== '') $detailsParts[] = $modeMeta['server'];
            $detailsParts[] = $modeMeta['mode'] !== '' ? $modeMeta['mode'] : preg_replace('/^LoL\s+GGirl:\s*/i', '', $name);
            $detailsParts[] = $unitLabel;

            echo json_encode([
                'success' => true,
                'data' => [
                    'order_id' => (int) $order['id'],
                    'name' => $name,
                    'details' => implode(' - ', $detailsParts),
                    'type' => (string) ($order['service_type'] ?? 'egirl_session'),
                    'created_at' => (string) ($order['created_at'] ?? ''),
                    'game' => strtolower((string)($order['game'] ?? '')),
                    'created_ts' => !empty($order['created_at']) ? (int) strtotime($order['created_at']) : 0,
                    'client_username' => $clientUsername,
                    'client_icon' => $clientIcon,
                    'is_egirl' => true,
                ]
            ]);
            return;
        }


        // Cache booster game access for a few minutes. This endpoint is polled often,
        // so avoiding the same booster lookup on every request reduces DB load.
        $cacheKey = 'lb_booster_games_' . $booster_id;
        $cacheTtlKey = $cacheKey . '_ts';
        $games = [];
        if (session_status() === PHP_SESSION_ACTIVE
            && isset($_SESSION[$cacheKey], $_SESSION[$cacheTtlKey])
            && (time() - (int)$_SESSION[$cacheTtlKey]) < 300
        ) {
            $games = is_array($_SESSION[$cacheKey]) ? $_SESSION[$cacheKey] : [];
        }
        if (empty($games)) {
            $booster = db_get_row('boosters', ['id' => $booster_id]);
            $gamesRaw = is_array($booster) ? (string)($booster['games'] ?? '') : '';
            $games = array_values(array_filter(array_map(function($g){
                $g = strtolower(trim((string)$g));
                // allow only simple slugs like "lol" / "val"
                return preg_match('/^[a-z0-9_-]+$/', $g) ? $g : null;
            }, preg_split('/\|+/', $gamesRaw))));
            // Keep in sync with orders_panel_state()/the orders-panel route: legacy short
            // codes saved before the games-select fix must still resolve to the full slug
            // stored on boost_forms.game. Both functions share the same session cache key
            // (lb_booster_games_<id>), so missing this here poisoned that shared cache.
            $legacyShortCodeToSlug = [
                'rl' => 'rocket-league',
                'apex' => 'apex-legends',
                'rivals' => 'marvel-rivals',
                'ow2' => 'overwatch-2',
                'wild-rift' => 'lol-wild-rift',
                // LoL Classic is not a separate qualification: every LoL booster may take
                // Classic orders and uses the same LoL rank/order limits.
                'lol' => 'lol_classic',
            ];
            foreach ($games as $g) {
                if (isset($legacyShortCodeToSlug[$g])) {
                    $games[] = $legacyShortCodeToSlug[$g];
                }
            }
            $games = array_values(array_unique($games));
            if (session_status() === PHP_SESSION_ACTIVE) {
                $_SESSION[$cacheKey] = $games;
                $_SESSION[$cacheTtlKey] = time();
            }
        }

        if (empty($games)) {
            // Booster has no game assignment -> no orders
            echo json_encode(['success' => false, 'data' => null]);
            return;
        }

        $lastOrderId = isset($_POST['last_order_id']) ? (int) $_POST['last_order_id'] : 0;
        $sinceTs = isset($_POST['since_ts']) ? (int) $_POST['since_ts'] : 0;

        
        $lastNotifId = isset($_POST['last_notif_id']) ? (int) $_POST['last_notif_id'] : 0;

        $buildBrowserOrderDetails = function ($order, $form) {
            $order = is_array($order) ? $order : [];
            $form = is_array($form) ? $form : [];
            $orderId = (int)($order['id'] ?? 0);
            $opts = $orderId > 0 ? db_get_row('order_options', ['order_id' => $orderId], 1) : [];
            if (!is_array($opts)) $opts = [];
            $acc = $orderId > 0 ? db_get_row('order_accounts', ['order_id' => $orderId], 1) : [];
            if (!is_array($acc)) $acc = [];

            $game = (string)($form['game'] ?? $order['game'] ?? $opts['game'] ?? 'lol');
            $type = (string)($form['type'] ?? $order['type'] ?? $opts['type'] ?? '');
            $merged = array_merge($form, $opts, $acc, $order, [
                'game' => $game,
                'type' => $type,
            ]);

            if ($type !== '' && function_exists('util_format_boost_overview')) {
                try {
                    $details = trim(strip_tags((string)util_format_boost_overview($game, $type, $merged)));
                    $details = html_entity_decode($details, ENT_QUOTES, 'UTF-8');
                    $details = preg_replace('/\s+/', ' ', $details);
                    if ($details !== '') return $details;
                } catch (Throwable $e) {}
            }

            $server = strtoupper(trim((string)($merged['server'] ?? '')));
            $name = trim((string)($form['name'] ?? 'Order'));
            return trim($server . ($server !== '' ? ' - ' : '') . $name);
        };

        // 1) Repost-Events über notifications (order_ping)
        //    Damit werden auch "alte" Orders beim Repost als "New Order" gepusht.
        $notifRows = $db->run(
            "SELECT id, data, created_at
               FROM notifications
              WHERE type = 'order_ping'
                AND id > ?
                AND created_at >= DATE_SUB(NOW(), INTERVAL 30 MINUTE)
              ORDER BY id ASC
              LIMIT 1",
            $lastNotifId
        );

        if ($notifRows && !empty($notifRows)) {
            $n = $notifRows[0];
            $payload = json_decode($n['data'] ?? '', true);

            $encoded = $payload['order_id'] ?? '';
            $decodedOrderId = 0;

            if (is_string($encoded) && $encoded !== '') {
                $tmp = base64_decode($encoded, true);
                if ($tmp !== false) $decodedOrderId = (int) $tmp;
            }

            if ($decodedOrderId > 0) {
                $order = db_get_row('orders', ['id' => $decodedOrderId]);
                if ($order) {
                    $form = db_get_row('boost_forms', ['id' => $order['form_id'] ?? 0]);

                    $game = strtolower(trim((string)($form['game'] ?? '')));
                    $allowed = in_array($game, $games, true);

                    $isAvailable =
                        ($order['status'] ?? null) === 'PAID' &&
                        empty($order['completed_at']) &&
                        empty($order['booster_id']) &&
                        $allowed;

                    if ($isAvailable) {
                        // Client-Username für das Claim-Modal mitliefern
                        $repostClientUsername = '';
                        $repostClientIcon = '';
                        $repostClientId = (int)($order['client_id'] ?? 0);
                        if ($repostClientId > 0) {
                            $repostClientRow = db_get_row('clients', ['id' => $repostClientId], 1);
                            $repostClientUsername = trim((string)($repostClientRow['username'] ?? $repostClientRow['name'] ?? $repostClientRow['email'] ?? ''));
                            $repostClientIcon = trim((string)($repostClientRow['icon'] ?? ''));
                        }

                        echo json_encode([
                            'success' => true,
                            'data' => [
                                'kind' => 'repost',
                                'notif_id' => (int) $n['id'],
                                'order_id' => (int) $decodedOrderId,
                                'name' => (string) ($form['name'] ?? 'Order'),
                                'details' => $buildBrowserOrderDetails($order, $form),
                                'type' => (string) ($form['type'] ?? 'order'),
                                'created_at' => (string) ($n['created_at'] ?? ''),
                                'game' => (string) ($form['game'] ?? ''),
                                'created_ts' => ($n['created_at'] ? (int) strtotime($n['created_at']) : 0),
                                'client_username' => $repostClientUsername,
                                'client_icon' => $repostClientIcon,
                            ]
                        ]);
                        return;
                    }
                }
            }

            // Wenn Notification kaputt / Order nicht verfügbar -> Cursor trotzdem weiterziehen
            echo json_encode([
                'success' => true,
                'data' => [
                    'kind' => 'repost_skip',
                    'notif_id' => (int) $n['id'],
                ]
            ]);
            return;
        }

        // Cursor-only: finde die nächste Order nach last_order_id (nur ab Tab-Login + max. 2 Minuten alt)
        $inPlaceholders = implode(',', array_fill(0, count($games), '?'));

        // Cursor-only: finde die nächste Order nach last_order_id (nur ab Tab-Login + max. 2 Minuten alt)
        $query = "SELECT o.*, bf.game, bf.type AS form_type, COALESCE(o.paid_at, o.created_at) AS order_ts
                      FROM orders o
                      INNER JOIN boost_forms bf ON bf.id = o.form_id
                      WHERE o.status = 'PAID'
                        AND o.completed_at IS NULL
                        AND o.booster_id IS NULL
                        AND bf.game IN ($inPlaceholders)
                        AND o.id > ?
                        AND COALESCE(o.paid_at, o.created_at) >= DATE_SUB(NOW(), INTERVAL 2 MINUTE)";

        $args = array_merge($games, [$lastOrderId]);

        if ($sinceTs > 0) {
            $query .= " AND COALESCE(o.paid_at, o.created_at) >= FROM_UNIXTIME(?)";
            $query .= " ORDER BY o.id ASC LIMIT 1";
            $args2 = array_merge($args, [$sinceTs]);
            $rows = $db->run($query, ...$args2);
        } else {
            $query .= " ORDER BY o.id ASC LIMIT 1";
            $rows = $db->run($query, ...$args);
        }
        if (!$rows || empty($rows)) {
            echo json_encode(['success' => false, 'data' => null]);
            return;
        }

        $order = $rows[0];

        $invoice = db_get_row('invoices', ['id' => $order['invoice_id']]);
        if (!$invoice || ($invoice['order_type'] ?? null) !== 'order') {
            echo json_encode(['success' => false, 'data' => null]);
            return;
        }

        $form = db_get_row('boost_forms', ['id' => $order['form_id']]);

        // Client-Username für das Claim-Modal mitliefern
        $clientUsername = '';
        $clientIcon = '';
        $clientId = (int)($order['client_id'] ?? $invoice['client_id'] ?? 0);
        if ($clientId > 0) {
            $clientRow = db_get_row('clients', ['id' => $clientId], 1);
            $clientUsername = trim((string)($clientRow['username'] ?? $clientRow['name'] ?? $clientRow['email'] ?? ''));
            $clientIcon = trim((string)($clientRow['icon'] ?? ''));
        }

        echo json_encode([
            'success' => true,
            'data' => [
                'order_id' => (int) $order['id'],
                'name' => (string) ($form['name'] ?? 'Order'),
                'details' => $buildBrowserOrderDetails($order, $form),
                'type' => (string) ($form['type'] ?? 'order'),
                'created_at' => (string) ($order['order_ts'] ?? ''),
                'game' => (string) ($form['game'] ?? ($order['game'] ?? '')),
                'created_ts' => ($order['order_ts'] ? (int) strtotime($order['order_ts']) : 0),
                'client_username' => $clientUsername,
                'client_icon' => $clientIcon,
            ]
        ]);
    }


    public function booster_order_notify_payload()
    {
        global $db;

        $booster_id = (int) (BOOSTER_ID ?? 0);
        $order_id = isset($_POST['order_id']) ? (int) $_POST['order_id'] : 0;

        if (!$booster_id || !$order_id) {
            echo json_encode(['success' => false, 'eligible' => false]);
            return;
        }

        // Regular boosters only. GG-Girl orders use the separate egirl_orders flow.
        if (defined('IS_EGIRL') && IS_EGIRL) {
            echo json_encode(['success' => false, 'eligible' => false]);
            return;
        }

        $cacheKey = 'lb_booster_games_' . $booster_id;
        $cacheTtlKey = $cacheKey . '_ts';
        $games = [];

        if (session_status() === PHP_SESSION_ACTIVE
            && isset($_SESSION[$cacheKey], $_SESSION[$cacheTtlKey])
            && (time() - (int) $_SESSION[$cacheTtlKey]) < 300
        ) {
            $games = is_array($_SESSION[$cacheKey]) ? $_SESSION[$cacheKey] : [];
        }

        if (empty($games)) {
            $booster = db_get_row('boosters', ['id' => $booster_id]);
            $gamesRaw = is_array($booster) ? (string) ($booster['games'] ?? '') : '';
            $games = array_values(array_filter(array_map(function ($g) {
                $g = strtolower(trim((string) $g));
                return preg_match('/^[a-z0-9_-]+$/', $g) ? $g : null;
            }, preg_split('/\|+/', $gamesRaw))));

            // Keep in sync with orders_panel_state()/check_new_orders()/the orders-panel route:
            // all share the same session cache key (lb_booster_games_<id>), so missing this
            // mapping here would poison that shared cache for the other functions too.
            $legacyShortCodeToSlug = [
                'rl' => 'rocket-league',
                'apex' => 'apex-legends',
                'rivals' => 'marvel-rivals',
                'ow2' => 'overwatch-2',
                'wild-rift' => 'lol-wild-rift',
                // LoL Classic is not a separate qualification: every LoL booster may take
                // Classic orders and uses the same LoL rank/order limits.
                'lol' => 'lol_classic',
            ];
            foreach ($games as $g) {
                if (isset($legacyShortCodeToSlug[$g])) {
                    $games[] = $legacyShortCodeToSlug[$g];
                }
            }
            $games = array_values(array_unique($games));

            if (session_status() === PHP_SESSION_ACTIVE) {
                $_SESSION[$cacheKey] = $games;
                $_SESSION[$cacheTtlKey] = time();
            }
        }

        if (empty($games)) {
            echo json_encode(['success' => true, 'eligible' => false]);
            return;
        }

        $inPlaceholders = implode(',', array_fill(0, count($games), '?'));
        $args = array_merge([$order_id], $games);

        $rows = $db->run(
            "SELECT o.*, bf.name, bf.game, bf.type, COALESCE(o.paid_at, o.created_at) AS order_ts
               FROM orders o
               INNER JOIN boost_forms bf ON bf.id = o.form_id
              WHERE o.id = ?
                AND o.status = 'PAID'
                AND o.completed_at IS NULL
                AND o.booster_id IS NULL
                AND bf.game IN ($inPlaceholders)
              LIMIT 1",
            ...$args
        );

        if (!$rows || empty($rows)) {
            echo json_encode(['success' => true, 'eligible' => false]);
            return;
        }

        $order = $rows[0];
        $invoice = db_get_row('invoices', ['id' => $order['invoice_id'] ?? 0]);

        if (!$invoice || ($invoice['order_type'] ?? null) !== 'order') {
            echo json_encode(['success' => true, 'eligible' => false]);
            return;
        }

        $clientUsername = '';
        $clientIcon = '';
        $clientId = (int) ($order['client_id'] ?? $invoice['client_id'] ?? 0);
        if ($clientId > 0) {
            $clientRow = db_get_row('clients', ['id' => $clientId], 1);
            if (is_array($clientRow)) {
                $clientUsername = trim((string) ($clientRow['username'] ?? $clientRow['name'] ?? $clientRow['email'] ?? ''));
                $clientIcon = trim((string) ($clientRow['icon'] ?? ''));
            }
        }

        echo json_encode([
            'success' => true,
            'eligible' => true,
            'data' => [
                'order_id' => (int) $order['id'],
                'name' => (string) ($order['name'] ?? 'Order'),
                'type' => (string) ($order['type'] ?? 'order'),
                'game' => (string) ($order['game'] ?? ''),
                'created_at' => (string) ($order['order_ts'] ?? ''),
                'created_ts' => !empty($order['order_ts']) ? (int) strtotime($order['order_ts']) : 0,
                'client_username' => $clientUsername,
                'client_icon' => $clientIcon,
                '__notifyValidated' => true,
            ]
        ]);
    }


    public function orders_panel_state()
    {
        global $db;

        $booster_id = (int) (BOOSTER_ID ?? 0);
        if (!$booster_id) {
            echo json_encode(['success' => false]);
            return;
        }

        // E-Girls never claim normal boost orders — don't feed them the order pool.
        if (defined('IS_EGIRL') && IS_EGIRL) {
            echo json_encode(['success' => true, 'data' => ['hash' => md5(''), 'ids' => []]]);
            return;
        }


        // Cache booster game access for a few minutes. This endpoint is polled often,
        // so avoiding the same booster lookup on every request reduces DB load.
        $cacheKey = 'lb_booster_games_' . $booster_id;
        $cacheTtlKey = $cacheKey . '_ts';
        $games = [];
        if (session_status() === PHP_SESSION_ACTIVE
            && isset($_SESSION[$cacheKey], $_SESSION[$cacheTtlKey])
            && (time() - (int)$_SESSION[$cacheTtlKey]) < 300
        ) {
            $games = is_array($_SESSION[$cacheKey]) ? $_SESSION[$cacheKey] : [];
        }
        if (empty($games)) {
            $booster = db_get_row('boosters', ['id' => $booster_id]);
            $gamesRaw = is_array($booster) ? (string)($booster['games'] ?? '') : '';
            $games = array_values(array_filter(array_map(function($g){
                $g = strtolower(trim((string)$g));
                return preg_match('/^[a-z0-9_-]+$/', $g) ? $g : null;
            }, preg_split('/\|+/', $gamesRaw))));
            // Some boosters have a legacy short code saved (e.g. "rl") from a previous version
            // of the Games select that incorrectly aliased these dynamically-added games.
            // boost_forms.game actually stores the full games.slug (e.g. "rocket-league"), so
            // add the full-slug equivalent for any legacy short code found in boosters.games.
            $legacyShortCodeToSlug = [
                'rl' => 'rocket-league',
                'apex' => 'apex-legends',
                'rivals' => 'marvel-rivals',
                'ow2' => 'overwatch-2',
                'wild-rift' => 'lol-wild-rift',
                // LoL Classic is not a separate qualification: every LoL booster may take
                // Classic orders and uses the same LoL rank/order limits.
                'lol' => 'lol_classic',
            ];
            foreach ($games as $g) {
                if (isset($legacyShortCodeToSlug[$g])) {
                    $games[] = $legacyShortCodeToSlug[$g];
                }
            }
            $games = array_values(array_unique($games));
            if (session_status() === PHP_SESSION_ACTIVE) {
                $_SESSION[$cacheKey] = $games;
                $_SESSION[$cacheTtlKey] = time();
            }
        }

        if (empty($games)) {
            echo json_encode(['success' => true, 'data' => ['hash' => md5(''), 'ids' => []]]);
            return;
        }

        // WICHTIG: Diese WHERE muss exakt deinem Panel entsprechen!
        // Ich nehme hier "verfügbare Orders" wie in check_new_orders.
        $inPlaceholders = implode(',', array_fill(0, count($games), '?'));
        $rows = $db->run("
            SELECT o.id, o.status, o.paid_at, o.completed_at, o.booster_id
            FROM orders o
            INNER JOIN boost_forms bf ON bf.id = o.form_id
            WHERE o.status = 'PAID'
              AND o.completed_at IS NULL
              AND o.booster_id IS NULL
              AND bf.game IN ($inPlaceholders)
            ORDER BY o.id DESC
            LIMIT 50
        ", ...$games);

        $flat = [];
        $ids = [];

        if ($rows) {
            foreach ($rows as $r) {
                $ids[] = (int) $r['id'];
                $flat[] = $r['id'] . '|' . $r['status'] . '|' . ($r['paid_at'] ?? '') . '|' . ($r['completed_at'] ?? '') . '|' . ($r['booster_id'] ?? '');
            }
        }

        $hash = md5(implode(',', $flat));

        echo json_encode([
            'success' => true,
            'data' => [
                'hash' => $hash,
                'ids' => $ids
            ]
        ]);
    }


public function admin_repost_order()
    {
        if ($this->is_admin) {
            $order_id = esc($_POST['id']);
            $order = db_get_row('orders', ['id' => $order_id]);

            if (!$order) {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Failed to repost order."]]);
                return;
            }

            $inserted = false;
            try {
                // Same builder a brand-new paid order uses, so the resulting Discord
                // message (routing, role ping, embed, claim link) is identical either way.
                $inserted = db_add_row('notifications', lb_build_new_order_ping_notification($order['id']));
            } catch (\Throwable $e) {
                error_log('[admin_repost_order] Failed to insert order_ping notification for order #' . $order['id'] . ': ' . $e->getMessage());
            }

            if (!$inserted) {
                echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Failed to repost order."]]);
                return;
            }

            trigger_notification_sender_async();

            // Re-surface the order to the booster panel live, same as when a booster is
            // removed/dropped and the order becomes claimable again.
            if (function_exists('lb_realtime_emit_new_order')) {
                $repostEventId = is_int($inserted) || (is_string($inserted) && ctype_digit($inserted))
                    ? (string)$inserted
                    : ((string)time() . '-' . (string)$order['id']);
                lb_realtime_emit_new_order($order['id'], 'boosters', [
                    'kind' => 'repost',
                    'notif_id' => $repostEventId,
                ]);
            }

            echo json_encode([
                "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Order reposted successfully."],
                "playSound" => "success",
                "refreshPage" => true
            ]);
        }
    }

    public function poke_client()
    {
        if ($this->is_booster) {
            $order_id = esc($_POST['id']);
            $order = db_get_row('orders', ['id' => $order_id]);

            $client_id = $order['client_id'];
            $client = db_get_row('clients', ['id' => $client_id]);

            if ($client) {
                global $db;

                $encoded_order_id = base64_encode($order['id']);
                $query = "
                    SELECT * FROM notifications 
                    WHERE type = 'poke_client' 
                    AND recipient_id = {$client['id']} 
                    AND JSON_EXTRACT(data, '$.order_id') = '{$encoded_order_id}' 
                    ORDER BY created_at DESC 
                    LIMIT 1
                ";
                $last_poke = $db->run($query);

                if (!empty($last_poke) && strtotime($last_poke[0]['created_at']) > strtotime('-45 minutes')) {
                    echo json_encode([
                        "sendToast" => ["type" => "warning", "title" => "Cooldown", "message" => "You can poke this client for this order once every 45 minutes."],
                        "playSound" => "error"
                    ]);
                    return;
                }

                db_add_row('notifications', [

                    'type' => 'poke_client',
                    'recipient' => 'client',
                    'recipient_id' => $client['id'],
                    'data' => json_encode([
                        'order_id' => $encoded_order_id,
                        'sent_by' => base64_encode('booster'),
                        'sender_name' => base64_encode(BOOSTER_DATA['username'] ?? ' '),
                    ]),
                    'is_email' => true,
                    'is_discord' => false,
                
                    'is_web' => 1,

                ]);
trigger_notification_sender_async();

                if (!empty($client['discord_id'])) {
                    $botToken = DS_BOT_TOKEN;
                    $discordUserId = $client['discord_id'];
                    $orderCode = "Order # " . $order['id'];

                    $dmChannel = getDMChannelId($botToken, $discordUserId);

                    $orderUrl = BASE_URL . '/order/' . $order['id'];

                    if ($dmChannel) {
                        $embed = [
                            "title" => $orderCode,
                            "author" => [
                                "name" => "LoLBoost.GG",
                                "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                            ],
                            "description" => "⚠️ **Booster Poked You**\n\nPlease **respond** to the booster **immediately** through the website chat.\n",
                            "footer" => [
                                "text" => "LoLBoost.GG - Ranking up never been easier",
                                "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                            ],
                            "timestamp" => date('c'),
                            "color" => 0x5865F2
                        ];

                        $components = [
                            [
                                "type" => 1,
                                "components" => [
                                    [
                                        "type" => 2,
                                        "style" => 5,
                                        "label" => "🔎 View Order",
                                        "url" => $orderUrl
                                    ]
                                ]
                            ]
                        ];

                        $msg = json_encode([
                            "embeds" => [$embed],
                            "components" => $components
                        ], JSON_UNESCAPED_SLASHES);

                        sendEmbedDM($botToken, $dmChannel, $msg);
                    }
                }

                echo json_encode([
                    "success" => true,
                    "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Poke sent successfully."],
                    "playSound" => "success"
                ]);
            }
        } else {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "You are not a booster."]]);
        }
    }

