                                "icon_url" => "https://lolboost.gg/public/uploads/icons/default1.png"
                            ],
                            "timestamp" => date('c'),
                            "color" => 0x5865F2
                        ];

                        $components = [
                            [
                                "type" => 1,
                                "components" => [
                                    [
                                        "type" => 2,
                                        "style" => 5,
                                        "label" => "🔎 View Order",
                                        "url" => $orderUrl
                                    ]
                                ]
                            ]
                        ];

                        $msg = json_encode([
                            "embeds" => [$embed],
                            "components" => $components
                        ], JSON_UNESCAPED_SLASHES);

                        sendEmbedDM($botToken, $dmChannel, $msg);
                    }
                }

                echo json_encode([
                    "sendToast" => ["type" => "primary", "title" => "Success", "message" => "Poke sent successfully."],
                    "playSound" => "success",
                    "refreshPage" => true
                ]);
            }
        } else {
            echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "You are not a client."]]);
        }
    }

public function client_change_booster_request()
{
    if (!$this->is_client) {
        echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "You are not a client."]]);
        return;
    }

    $order_id = (int)($_POST['order_id'] ?? 0);
    if ($order_id <= 0) {
        echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid order."]]);
        return;
    }

    $order = db_get_row('orders', ['id' => $order_id]);
    if (empty($order)) {
        echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Order not found."]]);
        return;
    }

    if ((int)($order['client_id'] ?? 0) !== (int)CLIENT_DATA['id']) {
        echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Unauthorized."]]);
        return;
    }

    $isMultiBoosterOrder = in_array((int)($order['form_id'] ?? 0), [4, 19, 29], true);
    $orderOptions = $isMultiBoosterOrder ? (db_get_row('order_options', ['order_id' => $order_id], 1) ?: []) : [];
    $pendingRequestedIds = $isMultiBoosterOrder
        ? array_values(array_unique(array_filter(array_map(
            'intval',
            preg_split('/[\s,|]+/', (string)($orderOptions['selected_boosters'] ?? ''), -1, PREG_SPLIT_NO_EMPTY)
        ))))
        : [];
    $requestedTargetId = (int)($_POST['booster_id'] ?? 0);
    $oldBoosterId = $requestedTargetId > 0 ? $requestedTargetId : (int)($order['booster_id'] ?? 0);
    $oldBooster = $oldBoosterId > 0 ? db_get_row('boosters', ['id' => $oldBoosterId]) : null;

    if ($isMultiBoosterOrder && in_array($oldBoosterId, $pendingRequestedIds, true)) {
        $pendingRequestedIds = array_values(array_filter(
            $pendingRequestedIds,
            static fn($id) => (int)$id !== $oldBoosterId
        ));
        db_update_row('order_options', ['order_id' => $order_id], [
            'selected_boosters' => implode(',', $pendingRequestedIds),
        ]);

        db_add_row('notifications', [
            'type' => 'booster_request_declined',
            'recipient' => 'booster',
            'recipient_id' => $oldBoosterId,
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'client_username' => base64_encode((string)(CLIENT_DATA['username'] ?? 'Client')),
            ]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);

        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit('booster_request', ['order_id' => $order_id]);
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }

        echo json_encode([
            'success' => true,
            'sendToast' => [
                'type' => 'success',
                'title' => 'Request removed',
                'message' => 'The pending request for ' . ($oldBooster['username'] ?? 'this booster') . ' was removed. Your active booster stays on the order.',
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
        return;
    }

    $hasActiveMembership = false;
    if ($isMultiBoosterOrder && $oldBoosterId > 0) {
        try {
            global $db;
            $hasActiveMembership = !empty($db->row(
                "SELECT id FROM order_boosters WHERE order_id = ? AND booster_id = ? AND status = 'ACTIVE' LIMIT 1",
                $order_id,
                $oldBoosterId
            ));
        } catch (Throwable $e) {}
    }

    // Only allow free removal if the booster has NOT yet accepted (claimed_at is empty).
    // If the booster already accepted (claimed_at is set), the client must contact support.
    $claimedAt = trim((string)($order['claimed_at'] ?? ''));
    if ($hasActiveMembership || ($claimedAt !== '' && $claimedAt !== '0000-00-00 00:00:00')) {
        echo json_encode([
            'sendToast' => [
                'type' => 'warning',
                'title' => 'Booster already active',
                'message' => 'The booster has already accepted your order. Please contact support to request a booster change.',
            ],
            'playSound' => 'error',
        ]);
        return;
    }

    $update = [
        'booster_id' => null,
        'status' => 'PAID',
        'claimed_at' => null,
        'booster_cut' => null,
        'change_booster_last_request_at' => date('Y-m-d H:i:s'),
    ];

    if (array_key_exists('paid_at', $order)) {
        $update['paid_at'] = date('Y-m-d H:i:s');
    }

    db_update_row('orders', ['id' => $order_id], $update);

    // Repost the order so it appears again in the Discord order feed after the
    // client decides not to wait for the requested/pending booster.
    db_add_row('notifications', lb_build_new_order_ping_notification($order_id));
    trigger_notification_sender_async();
    if (function_exists('lb_realtime_emit_new_order')) {
        lb_realtime_emit_new_order($order_id);
    }

    // Admin audit log: makes it clear this was client-initiated, not a booster/admin action.
    if (function_exists('log_admin_action')) {
        $clientNameForLog = (string)(CLIENT_DATA['username'] ?? 'Client');
        $oldBoosterForLog = (string)($oldBooster['username'] ?? ('Booster #' . $oldBoosterId));
        log_admin_action(0, 'Client requested new booster for order #' . $order_id . ' (client: ' . $clientNameForLog . ', previous requested booster: ' . $oldBoosterForLog . '). Order reposted to Discord.');
    }

    $chat_data = [
        'message' => "Booster " . ($oldBooster['username'] ?? 'Booster') . " was removed from your Order.

A new booster will be assigned to your order shortly.

If you have any questions, our live chat is available anytime! 💬",
        'message_type' => 'text',
    ];
    $chat_user = [
        'id'       => '999',
        'username' => 'System',
        'icon'     => 'https://lolboost.gg/public/uploads/icons/default1.png',
    ];
    chat_insert_message($order_id, $chat_data, $chat_user, 'system');

    if (function_exists('lb_realtime_emit')) {
        lb_realtime_emit_order('chat_update', $order_id);
        lb_realtime_emit_order('order_status_update', $order_id);
        lb_realtime_emit('booster_request', ['order_id' => $order_id]);
        if ($oldBoosterId > 0) {
            // Already triggers a panel refresh on its own — don't also send orders_panel_update.
            if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
        } else {
            lb_realtime_emit('orders_panel_update', ['order_id' => $order_id]);
        }
    }

    if ($oldBoosterId > 0) {
        db_add_row('notifications', [
            'type' => 'booster_removed',
            'recipient' => 'booster',
            'recipient_id' => $oldBoosterId,
            'data' => json_encode([
                'order_id' => base64_encode((string)$order_id),
                'client_username' => base64_encode((string)(CLIENT_DATA['username'] ?? 'Client')),
                'booster_username' => base64_encode((string)($oldBooster['username'] ?? '')),
            ]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);
    }

    echo json_encode([
        'sendToast' => [
            'type' => 'success',
            'title' => 'Booster removed',
            'message' => 'Your order is available for a new booster now.'
        ],
        'playSound' => 'success',
        'refreshPage' => true
    ]);
}

/**
 * client_request_booster_change
 *
 * Called when a client submits the "Change Booster" modal for an order where
 * the booster has ALREADY accepted (claimed_at is set).
 * Does NOT remove the booster — sends a Discord notification to the admin team
 * and sets a 5-minute cooldown so the client cannot spam requests.
 */
public function client_request_booster_change()
{
    if (!$this->is_client) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'You are not a client.']]);
        return;
    }

    $order_id = (int)($_POST['order_id'] ?? 0);
    if ($order_id <= 0) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order.']]);
        return;
    }

    $order = db_get_row('orders', ['id' => $order_id]);
    if (empty($order)) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.']]);
        return;
    }

    if ((int)($order['client_id'] ?? 0) !== (int)CLIENT_DATA['id']) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
        return;
    }

    // Safety: if booster has not accepted yet (claimed_at empty), the free-removal handler should be used instead.
    $claimedAt = trim((string)($order['claimed_at'] ?? ''));
    if ($claimedAt === '' || $claimedAt === '0000-00-00 00:00:00') {
        echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Not needed', 'message' => 'The booster has not yet accepted. You can remove them directly.']]);
        return;
    }

    // 5-minute cooldown — prevent repeated admin pings.
    $cooldownSeconds = 300;
    $lastReqAt = $order['change_booster_last_request_at'] ?? null;
    if (!empty($lastReqAt)) {
        $lastTs = strtotime((string)$lastReqAt);
        if ($lastTs !== false) {
            $elapsed = time() - $lastTs;
            if ($elapsed >= 0 && $elapsed < $cooldownSeconds) {
                $remain = $cooldownSeconds - $elapsed;
                $mins = (int)ceil($remain / 60);
                echo json_encode([
                    'sendToast' => [
                        'type' => 'info',
                        'title' => 'Request already sent',
                        'message' => 'Our admin team is reviewing your request. Please wait about ' . $mins . ' more minute(s).',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                    'lockChangeBooster' => true,
                    'cooldownSeconds' => $remain,
                ]);
                return;
            }
        }
    }

    $progressStatus = trim((string)($_POST['progress_status'] ?? ''));
    $orderProgress  = trim((string)($_POST['order_progress'] ?? ''));
    $reason         = trim((string)($_POST['reason'] ?? ''));

    if (empty($reason)) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please provide a reason for requesting a new booster.'], 'playSound' => 'error']);
        return;
    }

    // Set cooldown marker so the UI shows "admin checking" state.
    db_update_row('orders', ['id' => $order_id], ['change_booster_last_request_at' => date('Y-m-d H:i:s')]);

    // Admin audit log for active orders where the admin team must decide what to do.
    if (function_exists('log_admin_action')) {
        $clientNameForLog = (string)(CLIENT_DATA['username'] ?? 'Client');
        log_admin_action(0, 'Client requested new booster for active order #' . $order_id . ' (client: ' . $clientNameForLog . '). Admin review required before reassignment/repost.');
    }

    $oldBoosterId = (int)($order['booster_id'] ?? 0);
    $oldBooster   = $oldBoosterId > 0 ? db_get_row('boosters', ['id' => $oldBoosterId]) : null;
    $clientName   = CLIENT_DATA['username'] ?? 'Client';
    $boosterName  = $oldBooster['username'] ?? ('Booster #' . $oldBoosterId);

    // System chat message to inform client.
    $chat_data = [
        'message' => "Your booster change request was sent to our admin team for review. Your current booster stays assigned until an admin checks the request.

If you have any questions, our live chat is available anytime! 💬",
        'message_type' => 'text',
    ];
    $chat_user = [
        'id'       => '999',
        'username' => 'System',
        'icon'     => 'https://lolboost.gg/public/uploads/icons/default1.png',
    ];
    chat_insert_message($order_id, $chat_data, $chat_user, 'system');

    if (function_exists('lb_realtime_emit')) {
        lb_realtime_emit_order('chat_update', $order_id);
    }

    // Discord notification to admin team.
    $webhookUrl = lb_booster_notification_webhook_url('change_booster');

    $discordPayload = [
        'username'         => 'Change Booster Request',
        'avatar_url'       => 'https://lolboost.gg/public/uploads/icons/default1.png',
        'content'          => '<@&1083064775623327784> <@&1295032857907171339>',
        'allowed_mentions' => ['roles' => ['1083064775623327784', '1295032857907171339']],
        'embeds' => [[
            'title'       => '🔄 Client Requests Booster Change',
            'description' => '**A client has requested a new booster for an active order.**',
            'color'       => hexdec('F0A30A'),
            'fields'      => [
                ['name' => '📦 Order ID',        'value' => '#' . $order_id,    'inline' => true],
                ['name' => '👤 Client',           'value' => $clientName,        'inline' => true],
                ['name' => '🎮 Current Booster',  'value' => $boosterName,       'inline' => true],
                ['name' => '📊 Progress Status',  'value' => ($progressStatus === 'none' ? '0 Progress' : 'Progress was made'), 'inline' => true],
                ['name' => '🔄 Order Progress',   'value' => ($orderProgress ?: 'Not provided'), 'inline' => false],
                ['name' => '📝 Reason',           'value' => $reason,            'inline' => false],
                ['name' => '🔗 Action',           'value' => '[Open Order](' . BASE_URL . '/admin-area/order/' . $order_id . ')', 'inline' => false],
            ],
            'footer'    => ['text' => 'LoLBoost.GG - Ranking up never been easier', 'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
            'timestamp' => date('c'),
        ]],
    ];

    $ch = curl_init($webhookUrl);
    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($discordPayload));
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
    curl_setopt($ch, CURLOPT_HEADER, 0);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
    curl_setopt($ch, CURLOPT_TIMEOUT, 5);
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
        curl_exec($ch);
    curl_close($ch);

    // Web notification to the booster.
    if ($oldBoosterId > 0) {
        db_add_row('notifications', [
            'type'         => 'booster_change_requested',
            'recipient'    => 'booster',
            'recipient_id' => $oldBoosterId,
            'data'         => json_encode([
                'order_id'        => base64_encode((string)$order_id),
                'client_username' => base64_encode((string)$clientName),
            ]),
            'is_web'  => 1,
            'is_sent' => 1,
        ]);
    }

    echo json_encode([
        'sendToast' => [
            'type'    => 'success',
            'title'   => 'Request sent',
            'message' => 'Our admin team has been notified and will review your request shortly.',
        ],
        'playSound'         => 'success',
        'refreshPage'       => true,
        'lockChangeBooster' => true,
        'cooldownSeconds'   => $cooldownSeconds,
    ]);
}

    private function lb_build_booster_drop_auto_progress(int $order_id): array
    {
        global $db;

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false || (int)($order['booster_id'] ?? 0) !== (int)BOOSTER_ID || (string)($order['status'] ?? '') !== 'IN_PROGRESS') {
            return ['success' => false, 'message' => 'Order not found, not assigned to you, or not IN_PROGRESS.'];
        }

        $form = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)], 1);
        $form_type = $form != false ? (string)($form['type'] ?? '') : '';
        $form_id = (int)($order['form_id'] ?? 0);
        $trackable = ['rank', 'win', 'arena', 'match', 'placement', 'normal', 'clash', 'pro-games'];
        if (!in_array($form_type, $trackable, true) && $form_id !== 26) {
            return ['success' => false, 'message' => 'This order type cannot be auto-checked through Riot tracking. Please submit the drop for admin review.'];
        }

        $options = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $account = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
        if (trim((string)($account['ign'] ?? '')) === '') {
            return ['success' => false, 'message' => 'Riot ID is missing. Please submit the drop for admin review.'];
        }

        try {
            $order_progress = db_get_row('order_progress', ['order_id' => $order_id], 1) ?: [];
            // Never throttled: automated drop verification approves or rejects based on
            // this result, so a stale value would change the outcome.
            $fresh = riot_sync_order_progress($order_id, $order, $options, $account, $order_progress, $db, 0);
        } catch (\Throwable $e) {
            $msg = function_exists('riot_user_friendly_error_message') ? riot_user_friendly_error_message($e) : $e->getMessage();
            return ['success' => false, 'message' => $msg ?: 'Riot progress sync failed.'];
        }

        $progress_to = [];
        $progress_type = 'riot_auto';
        $summary = '';

        $tier_to_int = static function ($value): int {
            if (is_numeric($value)) return (int)$value;
            $map = [
                'UNRANKED' => 0, 'IRON' => 1, 'BRONZE' => 2, 'SILVER' => 3, 'GOLD' => 4,
                'PLATINUM' => 5, 'EMERALD' => 6, 'DIAMOND' => 7, 'MASTER' => 8,
                'GRANDMASTER' => 9, 'CHALLENGER' => 10,
            ];
            return $map[strtoupper(trim((string)$value))] ?? 0;
        };
        $division_to_int = static function ($value): int {
            if (is_numeric($value)) return (int)$value;
            $map = ['IV' => 1, 'III' => 2, 'II' => 3, 'I' => 4];
            return $map[strtoupper(trim((string)$value))] ?? 0;
        };
        $tier_name = static function ($t): string {
            $map = [0 => 'Unranked', 1 => 'Iron', 2 => 'Bronze', 3 => 'Silver', 4 => 'Gold', 5 => 'Platinum', 6 => 'Emerald', 7 => 'Diamond', 8 => 'Master', 9 => 'Grandmaster', 10 => 'Challenger'];
            return $map[(int)$t] ?? (string)$t;
        };
        $div_name = static function ($d): string {
            $map = [1 => 'IV', 2 => 'III', 3 => 'II', 4 => 'I'];
            return $map[(int)$d] ?? '';
        };
        $lp_band = static function ($lp): string {
            $lp = max(0, min(100, (int)$lp));
            if ($lp <= 20) return '0-20';
            if ($lp <= 40) return '21-40';
            if ($lp <= 60) return '41-60';
            if ($lp <= 80) return '61-80';
            return '81-100';
        };

        if ($form_type === 'rank') {
            $tier = $tier_to_int($fresh['current_tier'] ?? 0);
            $division = $division_to_int($fresh['current_division'] ?? 0);
            $lp = (int)($fresh['current_lp'] ?? 0);
            $progress_to['start_tier'] = $tier;
            if ($tier >= 8) {
                $progress_to['start_lp_full'] = $lp;
                $summary = $tier_name($tier) . ' ' . $lp . ' LP';
            } else {
                $progress_to['start_division'] = $division;
                $progress_to['start_lp'] = $lp_band($lp);
                $summary = trim($tier_name($tier) . ' ' . $div_name($division) . ' (' . $lp . ' LP)');
            }
            if (!empty($options['lp_gain'])) {
                $progress_to['lp_gain'] = (string)$options['lp_gain'];
            }
        } elseif (in_array($form_type, ['win', 'arena'], true)) {
            $wins = (int)($fresh['wins'] ?? 0);
            $losses = (int)($fresh['losses'] ?? 0);
            $progress_to['wins_completed'] = $wins;
            $summary = $wins . ' wins, ' . $losses . ' losses';
        } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true) || $form_type === 'pro-games' || $form_id === 26) {
            $wins = (int)($fresh['wins'] ?? 0);
            $losses = (int)($fresh['losses'] ?? 0);
            $games = $wins + $losses;
            $progress_to['matches_completed'] = $games;
            $summary = $games . ' games played (' . $wins . 'W/' . $losses . 'L)';
        }

        if (empty($progress_to)) {
            return ['success' => false, 'message' => 'No supported Riot progress could be derived for this order.'];
        }

        $progress_note = 'Riot auto-sync: ' . $summary;
        $current = $this->calc_current_total_price_cents($order_id);
        $remaining = $this->calc_remaining_total_price_cents($order_id, $progress_to);
        $current_eur = ($current['success'] ?? false) ? (int)$current['eur_cents'] : (int)($order['price_eur'] ?? $order['price'] ?? 0);
        $remaining_eur = ($remaining['success'] ?? false) ? (int)$remaining['new_total_cents'] : $current_eur;
        if ($remaining_eur < 0) $remaining_eur = 0;
        if ($remaining_eur > $current_eur) $remaining_eur = $current_eur;
        $segment_value = max(0, $current_eur - $remaining_eur);
        $cut = (int)($order['booster_cut'] ?? 0);
        $payout = (int)round($segment_value * $cut / 100);

        return [
            'success' => true,
            'order_id' => $order_id,
            'form_type' => $form_type,
            'progress_type' => $progress_type,
            'progress_to' => $progress_to,
            'progress_to_json' => json_encode($progress_to, JSON_UNESCAPED_SLASHES),
            'progress_note' => $progress_note,
            'summary' => $summary,
            'current_total_eur' => $current_eur,
            'remaining_total_eur' => $remaining_eur,
            'segment_value_eur' => $segment_value,
            'payout_eur' => $payout,
            'cut_percent' => $cut,
            'raw_progress' => $fresh,
        ];
    }

    private function lb_apply_booster_auto_drop(int $order_id, array $auto, string $reason_type, string $reason, string $notes = '', string $progress_url = ''): array
    {
        global $db;

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false || (int)($order['booster_id'] ?? 0) !== (int)BOOSTER_ID || (string)($order['status'] ?? '') !== 'IN_PROGRESS') {
            return ['success' => false, 'message' => 'Order not found, not assigned to you, or not IN_PROGRESS.'];
        }

        $booster_id = (int)BOOSTER_ID;
        $booster = db_get_row('boosters', ['id' => $booster_id], 1);
        $options = db_get_row('order_options', ['order_id' => $order_id], 1) ?: [];
        $form = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)], 1);
        $form_type = $form != false ? (string)($form['type'] ?? '') : '';
        $progress_arr = is_array($auto['progress_to'] ?? null) ? $auto['progress_to'] : [];
        $progress_to = json_encode($progress_arr, JSON_UNESCAPED_SLASHES);
        $progress_note = (string)($auto['progress_note'] ?? 'Riot auto-sync');
        $progress_type = (string)($auto['progress_type'] ?? 'riot_auto');
        $now = date('Y-m-d H:i:s');

        $old_price_eur = (int)($auto['current_total_eur'] ?? ($order['price_eur'] ?? $order['price'] ?? 0));
        $new_price_eur = (int)($auto['remaining_total_eur'] ?? $old_price_eur);
        if ($new_price_eur < 0) $new_price_eur = 0;
        if ($new_price_eur > $old_price_eur) $new_price_eur = $old_price_eur;
        $currency = $order['currency'] ?? 'EUR';
        $new_price_order = $new_price_eur;
        if ($currency != 'EUR') {
            $rate = (float)get_exchange_rate();
            if ($rate <= 0) $rate = 1.0;
            $new_price_order = (int)round($new_price_eur * $rate);
        }
        $segment_value = max(0, $old_price_eur - $new_price_eur);
        $cut_percent = (int)($order['booster_cut'] ?? 0);
        $payout = (int)round($segment_value * $cut_percent / 100);

        $progress_from = null;
        $last_seg = db_get_rows('order_booster_segments', ['order_id' => $order_id, 'order' => 'id,desc', 'limit' => 1], true);
        if (!empty($last_seg) && !empty($last_seg[0]['progress_to'])) {
            $progress_from = $last_seg[0]['progress_to'];
        }

        db_add_row('drop_requests', [
            'order_id' => $order_id,
            'booster_id' => $booster_id,
            'order_date' => !empty($_POST['order_date']) ? date('Y-m-d H:i:s', strtotime((string)$_POST['order_date'])) : $now,
            'progress' => $progress_note,
            'progress_url' => $progress_url,
            'reason_type' => $reason_type,
            'reason' => $reason,
            'notes' => $notes,
        ]);

        db_add_row('order_booster_segments', [
            'order_id' => $order_id,
            'booster_id' => $booster_id,
            'form_id' => isset($order['form_id']) ? (int)$order['form_id'] : null,
            'cut_percent' => $cut_percent,
            'segment_value_eur' => $segment_value,
            'payout_eur' => $payout,
            'progress_type' => $progress_type,
            'progress_from' => $progress_from,
            'progress_to' => $progress_to,
            'progress_note' => $progress_note,
            'admin_id' => 0,
            'admin_log_id' => 0,
            'created_at' => $now,
        ]);

        if ($payout > 0 && $booster != false) {
            $old_balance = (int)($booster['balance'] ?? 0);
            $new_balance = $old_balance + $payout;
            db_update_row('boosters', ['id' => $booster_id], ['balance' => $new_balance]);
            db_add_row('booster_payments', [
                'booster_id' => $booster_id,
                'type' => 'progress_payment',
                'note' => (string)$order_id,
                'amount' => $payout,
                'currency' => 'EUR',
                'sender' => 'system',
                'sender_type' => 'system',
                'sender_id' => 0,
                'balance_update' => $old_balance . '|' . $new_balance,
                'created_at' => $now,
            ]);
        }

        $remove_update = [
            'price_eur' => $new_price_eur,
            'price' => $new_price_order,
            'booster_id' => null,
            'status' => 'PAID',
            'booster_cut' => null,
            'claimed_at' => null,
            'waiting_for_approval' => 0,
            'approval_requested_at' => null,
            'change_booster_last_request_at' => $now,
            'paid_at' => $now,
        ];
        $remove_update = array_merge($remove_update, $this->duo_timer_stop_payload($order, $now));
        db_update_row('orders', ['id' => $order_id], $remove_update);

        if (!empty($progress_arr) && is_array($options)) {
            $updates = [];
            if ($form_type === 'rank') {
                if (isset($progress_arr['start_tier'])) $updates['start_tier'] = (int)$progress_arr['start_tier'];
                if (isset($progress_arr['start_division'])) $updates['start_division'] = self::normalize_lol_division($progress_arr['start_division']);
                if (isset($progress_arr['start_lp_full'])) $updates['start_lp'] = (string)((int)$progress_arr['start_lp_full']);
                elseif (isset($progress_arr['start_lp'])) $updates['start_lp'] = (string)$progress_arr['start_lp'];
                if (isset($progress_arr['lp_gain'])) $updates['lp_gain'] = (string)$progress_arr['lp_gain'];
            } elseif (in_array($form_type, ['win', 'arena'], true)) {
                $completed = max(0, (int)($progress_arr['wins_completed'] ?? 0));
                $updates['matches'] = max(0, (int)($options['matches'] ?? 0) - $completed);
            } elseif (in_array($form_type, ['match', 'placement', 'normal', 'clash'], true) || $form_type === 'pro-games' || (int)($order['form_id'] ?? 0) === 26) {
                $completed = max(0, (int)($progress_arr['matches_completed'] ?? 0));
                $updates['matches'] = max(0, (int)($options['matches'] ?? 0) - $completed);
            }
            if (!empty($updates)) {
                db_update_row('order_options', ['order_id' => $order_id], $updates);
            }
        }

        $existing_progress = db_get_row('order_progress', ['order_id' => $order_id], 1);
        if (!empty($existing_progress)) {
            try { $db->run('ALTER TABLE order_progress ADD COLUMN IF NOT EXISTS booster_ign_set_at DATETIME NULL DEFAULT NULL'); } catch (\Throwable $e) {}
            $clearPayload = ['booster_ign' => null, 'booster_puuid' => null, 'booster_ign_set_at' => null];
            if (function_exists('riot_ensure_order_progress_duo_columns')) {
                riot_ensure_order_progress_duo_columns($db);
            }
            db_update_row('order_progress', ['order_id' => $order_id], $clearPayload);
        }

        db_update_row('boosters', ['id' => $booster_id], ['drop_tokens' => max(0, (int)(BOOSTER_DATA['drop_tokens'] ?? 0) - 1)]);

        $booster_name = $booster != false ? (string)($booster['username'] ?? BOOSTER_DATA['username']) : (string)BOOSTER_DATA['username'];
        db_add_row('notifications', [
            'type' => 'booster_removed',
            'recipient' => 'client',
            'recipient_id' => (int)($order['client_id'] ?? 0),
            'data' => json_encode(['order_id' => base64_encode((string)$order_id), 'booster_username' => base64_encode($booster_name), 'booster_id' => base64_encode((string)$booster_id)]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);
        db_add_row('notifications', [
            'type' => 'booster_removed',
            'recipient' => 'booster',
            'recipient_id' => $booster_id,
            'data' => json_encode(['order_id' => base64_encode((string)$order_id)]),
            'is_web' => 1,
            'is_sent' => 1,
        ]);
        db_add_row('notifications', lb_build_new_order_ping_notification($order_id));

        $chat_data = [
            'message' => 'Booster ' . $booster_name . " was removed from your order.\n\nVerified progress: " . $progress_note . "\n\nA new booster will be assigned shortly. If you have any questions, our live chat is available anytime!",
            'message_type' => 'text',
        ];
        $system_user = ['id' => '999', 'username' => 'System', 'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png'];
        chat_insert_message($order_id, $chat_data, $system_user, 'system');
        trigger_notification_sender_async();

        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit_order('chat_update', $order_id);
            lb_realtime_emit_order('order_status_update', $order_id);
            lb_realtime_emit_order('price_update', $order_id);
            if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
        }

        return ['success' => true, 'payout_eur' => $payout, 'segment_value_eur' => $segment_value, 'remaining_total_eur' => $new_price_eur];
    }

    public function booster_drop_progress_preview()
    {
        if (!$this->is_booster) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }
        $order_id = (int)($_POST['order_id'] ?? $_POST['id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order.']);
            return;
        }
        $auto = $this->lb_build_booster_drop_auto_progress($order_id);
        if (!($auto['success'] ?? false)) {
            echo json_encode($auto);
            return;
        }
        $auto['current_total_formatted'] = number_format(((int)$auto['current_total_eur']) / 100, 2, '.', '') . ' EUR';
        $auto['remaining_total_formatted'] = number_format(((int)$auto['remaining_total_eur']) / 100, 2, '.', '') . ' EUR';
        $auto['payout_formatted'] = number_format(((int)$auto['payout_eur']) / 100, 2, '.', '') . ' EUR';
        $auto['segment_value_formatted'] = number_format(((int)$auto['segment_value_eur']) / 100, 2, '.', '') . ' EUR';
        echo json_encode($auto);
    }

    public function booster_drop_order()
    {
        if (!$this->is_booster) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'You are not a booster.']]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id < 1) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order.'], 'playSound' => 'error']);
            return;
        }

        $order = db_get_row('orders', ['id' => $order_id], 1);
        if ($order == false || (int)($order['booster_id'] ?? 0) !== (int)BOOSTER_ID || (string)($order['status'] ?? '') !== 'IN_PROGRESS') {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found, not assigned to you, or not IN_PROGRESS.'], 'playSound' => 'error']);
            return;
        }

        $cooldownSeconds = 20 * 60;
        $lastReqAt = $order['change_booster_last_request_at'] ?? null;
        if (!empty($lastReqAt)) {
            $lastTs = strtotime((string)$lastReqAt);
            if ($lastTs !== false) {
                $elapsed = time() - $lastTs;
                if ($elapsed >= 0 && $elapsed < $cooldownSeconds) {
                    $remain = $cooldownSeconds - $elapsed;
                    $mins = (int)ceil($remain / 60);
                    echo json_encode(['sendToast' => ['type' => 'info', 'title' => 'Please wait', 'message' => 'Admin team is checking your previous drop request. You can submit a new one in about ' . $mins . ' minute(s).'], 'playSound' => 'success', 'refreshPage' => true, 'dropCooldownRemaining' => $remain]);
                    return;
                }
            }
        }

        if (!empty($order['waiting_for_approval']) && (int)$order['waiting_for_approval'] === 1) {
            echo json_encode(['sendToast' => ['type' => 'info', 'title' => 'Admin review', 'message' => 'This order is currently under admin review. Please try again later.'], 'playSound' => 'success', 'refreshPage' => true]);
            return;
        }

        if ((int)(BOOSTER_DATA['drop_tokens'] ?? 0) < 1) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'You do not have enough drop tokens.'], 'playSound' => 'error']);
            return;
        }

        $zero_progress = (int)($_POST['zero_progress'] ?? 0) === 1;
        $auto_confirmed = false; // disabled: auto-drop path requires admin approval
        $reason_type = trim((string)($_POST['reason_type'] ?? ''));
        $reason = trim((string)($_POST['reason'] ?? ''));
        $notes = trim((string)($_POST['notes'] ?? ''));
        $progress_url = trim((string)($_POST['progress_url'] ?? ''));

        if (trim((string)($_POST['order_date'] ?? '')) === '' || $reason_type === '' || $reason === '') {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in Order Date, Drop Reason and Explanation.'], 'playSound' => 'error']);
            return;
        }

        if ($zero_progress) {
            $confirm = strtoupper(trim((string)($_POST['zero_progress_confirm'] ?? '')));
            if ($confirm !== 'ZERO') {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Confirm zero progress', 'message' => 'Please type ZERO to confirm no progress was made.'], 'playSound' => 'error']);
                return;
            }

            $now = date('Y-m-d H:i:s');
            db_add_row('drop_requests', [
                'order_id' => $order_id,
                'booster_id' => BOOSTER_ID,
                'order_date' => date('Y-m-d H:i:s', strtotime((string)$_POST['order_date'])),
                'progress' => '0 progress confirmed by booster',
                'progress_url' => $progress_url,
                'reason_type' => $reason_type,
                'reason' => $reason,
                'notes' => $notes,
            ]);
            db_update_row('orders', ['id' => $order_id], array_merge([
                'booster_id' => null,
                'status' => 'PAID',
                'claimed_at' => null,
                'booster_cut' => null,
                'paid_at' => $now,
                'change_booster_last_request_at' => $now,
            ], $this->duo_timer_stop_payload($order, $now)));
            db_update_row('boosters', ['id' => BOOSTER_ID], ['drop_tokens' => max(0, (int)(BOOSTER_DATA['drop_tokens'] ?? 0) - 1)]);
            // A zero progress drop previously sent no Discord notification at all.
            $this->lb_send_drop_request_webhook($order_id, $order, '0 progress confirmed by booster', $reason_type, $reason, true);
            db_add_row('notifications', ['type' => 'booster_removed', 'recipient' => 'client', 'recipient_id' => (int)($order['client_id'] ?? 0), 'data' => json_encode(['order_id' => base64_encode((string)$order_id), 'booster_username' => base64_encode((string)BOOSTER_DATA['username']), 'booster_id' => base64_encode((string)BOOSTER_ID)]), 'is_web' => 1, 'is_sent' => 1]);
            chat_insert_message($order_id, ['message' => 'Booster ' . BOOSTER_DATA['username'] . " removed from your order.\n\nA new booster will be assigned shortly.", 'message_type' => 'text'], ['id' => '999', 'username' => 'System', 'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png'], 'system');
            db_add_row('notifications', lb_build_new_order_ping_notification($order_id));
            trigger_notification_sender_async();
            if (function_exists('lb_realtime_emit')) {
                lb_realtime_emit_order('chat_update', $order_id);
                lb_realtime_emit_order('order_status_update', $order_id);
                if (function_exists('lb_realtime_emit_new_order')) { lb_realtime_emit_new_order($order_id); } else { lb_realtime_emit('new_order', ['order_id' => $order_id]); }
            }
            echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Success', 'message' => 'Order dropped with 0 progress.'], 'playSound' => 'success', 'redirectUrl' => BASE_URL . '/booster-area/dashboard']);
            return;
        }

        // Auto-progress path disabled: all drops require admin approval.
        // Even if auto_progress_confirmed=1 is posted, treat it as manual flow below.
        $auto_confirmed = false;

        $progress = trim((string)($_POST['progress'] ?? ''));
        if ($progress === '') {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please confirm the automatic progress or enter manual progress.'], 'playSound' => 'error']);
            return;
        }

        $data = [
            'order_id' => $order_id,
            'booster_id' => BOOSTER_DATA['id'],
            'order_date' => date('Y-m-d H:i:s', strtotime((string)$_POST['order_date'])),
            'progress' => $progress,
            'progress_url' => $progress_url,
            'reason_type' => $reason_type,
            'reason' => $reason,
            'notes' => $notes,
        ];
        db_add_row('drop_requests', $data);
        db_update_row('orders', ['id' => $order_id], ['change_booster_last_request_at' => date('Y-m-d H:i:s')]);
        db_update_row('boosters', ['id' => BOOSTER_DATA['id']], ['drop_tokens' => max(0, (int)BOOSTER_DATA['drop_tokens'] - 1)]);

        // Discord webhook: drop request with progress (admin approval required, no order ping)
        $this->lb_send_drop_request_webhook($order_id, $order, $progress, $reason_type, $reason, false);

        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Drop request submitted', 'message' => 'Your drop request was submitted. Please wait about 20 minute(s) before sending a new one.'], 'playSound' => 'success', 'refreshPage' => true, 'dropPending' => true]);
    }

    /**
     * Posts a drop request into the BOOSTER NOTIFICATION "Drop Requests" thread.
     * Used by both the normal drop flow and the zero progress drop.
     * Never throws: a failing webhook must not block the drop itself.
     */
    private function lb_send_drop_request_webhook(int $order_id, array $order, string $progress, string $reason_type, string $reason, bool $auto_dropped = false): void
    {
        try {
            if (!function_exists('lb_booster_notification_webhook_url') || !function_exists('curl_init')) {
                return;
            }

            $dropWebhookUrl = lb_booster_notification_webhook_url('order_drop');
            if ($dropWebhookUrl === '' || strpos($dropWebhookUrl, 'discord.com/api/webhooks/') === false) {
                return;
            }

            $boosterName = BOOSTER_DATA['username'] ?? ('Booster #' . (defined('BOOSTER_ID') ? BOOSTER_ID : 0));
            $siteUrl = defined('BASE_URL') ? rtrim(BASE_URL, '/') : 'https://lolboost.gg';
            $orderUrl = $siteUrl . '/admin-area/order/' . $order_id;

            $dropForm = db_get_row('boost_forms',    ['id' => (int)($order['form_id'] ?? 0)], 1) ?: [];
            $dropOpts = db_get_row('order_options',  ['order_id' => $order_id], 1) ?: [];
            $dropAcc  = db_get_row('order_accounts', ['order_id' => $order_id], 1) ?: [];
            $mergedDrop = array_merge((array)$dropForm, (array)$dropOpts, (array)$dropAcc, (array)$order);

            $gameLabel  = strtoupper((string)($dropForm['game'] ?? $order['game'] ?? 'LOL'));
            $formName   = trim((string)($dropForm['name'] ?? 'Order'));
            $orderTitle = trim($gameLabel . ' ' . $formName);
            $orderDetails = $orderTitle;
            if (function_exists('util_format_boost_overview')) {
                try {
                    $tmpDetails = trim(strip_tags((string)util_format_boost_overview(
                        $dropForm['game'] ?? $order['game'] ?? 'lol',
                        $dropForm['type'] ?? '',
                        $mergedDrop
                    )));
                    if ($tmpDetails !== '') {
                        $orderDetails = html_entity_decode($tmpDetails, ENT_QUOTES, 'UTF-8');
                    }
                } catch (Throwable $e) {}
            }

            $inGameName = '-';
            foreach (['ign', 'in_game_name', 'riot_id', 'summoner_name', 'account_name', 'username'] as $ignKey) {
                $candidate = trim((string)($mergedDrop[$ignKey] ?? ''));
                if ($candidate !== '') { $inGameName = $candidate; break; }
            }

            $reasonLabel = $reason_type !== '' ? ucfirst(str_replace('_', ' ', $reason_type)) : 'Other';
            $footer = $auto_dropped
                ? 'Zero progress drop, order already released'
                : 'Waiting for admin approval';
            $content = $auto_dropped
                ? ($boosterName . ' dropped order #' . $order_id . ' with 0 progress - [View Order](' . $orderUrl . ')')
                : ($boosterName . ' has submitted a drop request for order #' . $order_id . ' - [View Order](' . $orderUrl . ')');

            $dropPayload = [
                'username'         => 'Drop Requests',
                'avatar_url'       => 'https://lolboost.gg/public/uploads/icons/default1.png',
                'content'          => '<@&1083064775623327784> <@&1295032857907171339> ' . $content,
                'allowed_mentions' => ['roles' => ['1083064775623327784', '1295032857907171339']],
                'embeds'           => [[
                    'title'  => '#' . $order_id . ' – Drop Request',
                    'url'    => $orderUrl,
                    'color'  => 0xE67E22,
                    'fields' => [
                        ['name' => 'Booster',       'value' => $boosterName,  'inline' => true],
                        ['name' => 'Order Details', 'value' => $orderDetails, 'inline' => true],
                        ['name' => 'In Game Name',  'value' => $inGameName,   'inline' => true],
                        ['name' => 'Progress',      'value' => $progress !== '' ? $progress : '-', 'inline' => false],
                        ['name' => 'Drop Reason',   'value' => $reasonLabel,  'inline' => true],
                        ['name' => 'Explanation',   'value' => $reason !== '' ? $reason : '-', 'inline' => false],
                    ],
                    'footer'    => ['text' => $footer],
                    'timestamp' => date('c'),
                ]],
            ];

            $ch = curl_init($dropWebhookUrl);
            curl_setopt_array($ch, [
                CURLOPT_POST           => true,
                CURLOPT_POSTFIELDS     => json_encode($dropPayload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                CURLOPT_HTTPHEADER     => ['Content-Type: application/json'],
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_TIMEOUT        => 6,
            ]);
            $resp = curl_exec($ch);
            $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $err  = curl_error($ch);
            curl_close($ch);

            if ($resp === false || $code < 200 || $code >= 300) {
                error_log(sprintf(
                    '[lb_send_drop_request_webhook] FAILED order=%d http=%d curl=%s resp=%s',
                    $order_id, $code, $err, is_string($resp) ? substr($resp, 0, 400) : '(false)'
                ));
            }
        } catch (Throwable $e) {
            error_log('[lb_send_drop_request_webhook] Exception: ' . $e->getMessage());
        }
    }

    public function get_order_info()
    {
        if ($this->is_booster) {
            $order_id = (int) $_POST['id'];

            // Get booster and allowed games
            $booster = db_get_row('boosters', ['id' => BOOSTER_ID], 1);
            $games = explode('|', $booster['games']);

            // Fetch order
            $order = db_get_row('orders', ['id' => $order_id, 'status' => 'PAID'], 1);
            if (!$order)
                exit;

            // Load form
            $form = db_get_row('boost_forms', ['id' => $order['form_id']], 1);
            if (!$form || !in_array($form['game'], $games))
                exit;

            // Load order options
            $opts = db_get_row('order_options', ['order_id' => $order_id], 1);

            // Merge all data
            $row = array_merge($opts, $form, $order);

            view_file('main/components/order-row', ['row' => $row]);
        }
    }


    public function get_updated_prices()
    {
        global $db;

        if (!$this->is_booster) {
            exit(json_encode(['success' => false, 'message' => 'Unauthorized']));
        }

        $order_ids = $_POST['order_ids'] ?? [];

        if (empty($order_ids)) {
            echo json_encode(['success' => false, 'message' => 'No order IDs provided']);
            return;
        }

        $order_ids = array_map('intval', $order_ids);
        $placeholders = implode(',', array_fill(0, count($order_ids), '?'));

        $sql = "SELECT * FROM orders WHERE status = 'PAID' AND id IN ($placeholders)";
        $orders = $db->run($sql, ...$order_ids);

        if (!$orders) {
            echo json_encode(['success' => false, 'message' => 'No orders found']);
            return;
        }

        $result = [];
        foreach ($orders as $order) {
            $booster_price_cents = function_exists('calculate_effective_booster_cut_amount')
                ? calculate_effective_booster_cut_amount($order)
                : calculate_booster_cut($order);
            $price_display = util_format_currency_display($order['currency']) . util_format_price_display($booster_price_cents);

            // New: cut percent + countdown until next cut change
            $cut_meta = calculate_booster_cut_meta($order);

            if (function_exists('calculate_effective_booster_cut_percent')) {
                $effective_cut_percent = calculate_effective_booster_cut_percent($order);
                $dynamic_meta = function_exists('_booster_cut_resolve') ? _booster_cut_resolve($order) : [];
                $dynamic_max_cut = (float) ($dynamic_meta['max_cut'] ?? 0);

                if ($effective_cut_percent > $dynamic_max_cut) {
                    $cut_meta['percent'] = $effective_cut_percent;
                    $cut_meta['next_change_in'] = null;
                    $cut_meta['is_max'] = true;
                }
            }

            $result[] = [
                'order_id' => $order['id'],
                'price' => $price_display,
                'cut_percent' => $cut_meta['percent'],
                'next_change_in' => $cut_meta['next_change_in'], // seconds or null
            ];
        }

        echo json_encode([
            'success' => true,
            'data' => $result,
            'server_ts' => time(),
            'raw_orders' => $orders, // full order data array
        ]);
    }


    public function booster_application()
    {
        global $db;

        $is_egirl = !empty($_POST['is_egirl']) && (int)$_POST['is_egirl'] === 1;

        $rules = [
            'fullname' => 'required',
            'username' => 'required',
            'email' => 'required|email',
            'dob' => 'required',
            'address' => 'required',
            'country' => 'required',
        ];
        // Egirls don't select games
        if (!$is_egirl) {
            $rules['games'] = 'required';
        }

        $validator = new Validator();
        $validation = $validator->make($_POST, $rules);
        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors()->firstOfAll();
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Please fill in all required fields.',
                ],
                'playSound' => 'error',
                'validationErrors' => $errors,
            ]);
            return;
        }

        $existing_email_booster = db_get_row('boosters', [
            'email' => esc($_POST['email'])
        ]);

        if ($existing_email_booster) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'A booster with this email already exists.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $existing_username_booster = db_get_row('boosters', [
            'username' => esc($_POST['username'])
        ]);

        if ($existing_username_booster) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'A booster with this username already exists.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // Egirls don't upload documents
        $id_card_front_url = '';
        $id_card_back_url = '';
        $selfie_url = '';

        if (!$is_egirl) {
            // First validate + upload documents. Only create DB rows after uploads succeeded.
            $id_card_front = $_FILES['id_card_front'] ?? [];
            $id_card_back = $_FILES['id_card_back'] ?? [];
            $selfie = $_FILES['selfie'] ?? [];

            // Allow up to 8 MB for each onboarding image, independently.
            $max_onboarding_image_size = 8 * 1024 * 1024;
            $onboarding_files = [
                'ID Card Front' => $id_card_front,
                'ID Card Back' => $id_card_back,
                'Selfie' => $selfie,
            ];

            foreach ($onboarding_files as $label => $onboarding_file) {
                $upload_error = (int)($onboarding_file['error'] ?? UPLOAD_ERR_NO_FILE);

                if ($upload_error === UPLOAD_ERR_INI_SIZE || $upload_error === UPLOAD_ERR_FORM_SIZE) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => $label . ' is too large. Each image may be up to 8 MB.',
                        ],
                        'playSound' => 'error',
                        'success' => false,
                    ]);
                    return;
                }

                if ($upload_error !== UPLOAD_ERR_OK) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => 'The ' . $label . ' could not be uploaded. Please select the image again.',
                        ],
                        'playSound' => 'error',
                        'success' => false,
                    ]);
                    return;
                }

                if ((int)($onboarding_file['size'] ?? 0) > $max_onboarding_image_size) {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'danger',
                            'title' => 'Error',
                            'message' => $label . ' is too large. Each image may be up to 8 MB.',
                        ],
                        'playSound' => 'error',
                        'success' => false,
                    ]);
                    return;
                }
            }

            if (!empty($id_card_front['name'])) {
                $image_url = upload_image($id_card_front, 'booster_docs/' . $_POST['username']);
                if ($image_url == false) {
                    echo json_encode([
                        "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type (ID Card Front)."],
                        "playSound" => "error",
                        "success" => false,
                    ]);
                    return;
                }
                $id_card_front_url = $image_url;
            }

            if (!empty($id_card_back['name'])) {
                $image_url = upload_image($id_card_back, 'booster_docs/' . $_POST['username']);
                if ($image_url == false) {
                    echo json_encode([
                        "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type (ID Card Back)."],
                        "playSound" => "error",
                        "success" => false,
                    ]);
                    return;
                }
                $id_card_back_url = $image_url;
            }

            if (!empty($selfie['name'])) {
                $image_url = upload_image($selfie, 'booster_docs/' . $_POST['username']);
                if ($image_url == false) {
                    echo json_encode([
                        "sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type (Selfie)."],
                        "playSound" => "error",
                        "success" => false,
                    ]);
                    return;
                }
                $selfie_url = $image_url;
            }
        }

        // Create booster/egirl AFTER validation
        $games_value = $is_egirl ? 'lol' : implode('|', array_values(array_unique(array_filter(
            array_map(static fn($game) => strtolower(trim((string)$game)), (array)($_POST['games'] ?? [])),
            'strlen'
        ))));

        // Dynamic game slugs can exceed the legacy VARCHAR(100) column when an
        // applicant selects many games. Expand it before inserting so the
        // onboarding selection is stored completely.
        try {
            $gamesColumn = $db->row("SHOW COLUMNS FROM boosters LIKE 'games'");
            $gamesColumnType = strtolower((string)($gamesColumn['Type'] ?? ''));
            if (preg_match('/^varchar\((\d+)\)$/', $gamesColumnType, $matches)
                && strlen($games_value) > (int)$matches[1]) {
                $db->run("ALTER TABLE boosters MODIFY games TEXT NOT NULL");
            }
        } catch (\Throwable $e) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'The selected games could not be stored. Please try again.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // "Hired by" is always the admin who generated the onboarding link.
        try { $db->run("ALTER TABLE boosters ADD COLUMN IF NOT EXISTS hired_by_admin_id INT UNSIGNED NULL DEFAULT NULL"); } catch (\Throwable $e) {}
        $hired_by_admin_id = function_exists('onboarding_link_admin_id')
            ? onboarding_link_admin_id(onboarding_current_token(), $is_egirl ? 'egirl_onboarding' : 'onboarding')
            : 0;

        $booster = db_add_row('boosters', [
            'username' => esc($_POST['username']),
            'email' => esc($_POST['email']),
            'games' => $games_value,
            'rank_id' => 1,
            'password' => generate_password(),
            'show_profile' => 0,
            'boost_requests' => 0,
            'verified' => 0,
            'is_banned' => 1,
            'is_egirl' => $is_egirl ? 1 : 0,
            'rating' => $is_egirl ? 0 : random_booster_start_rating(),
            'hired_by_admin_id' => $hired_by_admin_id > 0 ? $hired_by_admin_id : null,
        ]);

        if (!$booster) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Could not create booster. Please try again.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        try {
            $personal_details_id = db_add_row('booster_personal_details', [
                'booster_id' => $booster,
                'fullname' => esc($_POST['fullname']),
                'dob' => esc($_POST['dob']),
                'country' => esc($_POST['country']),
                'address' => esc($_POST['address']),
                'id_front' => $id_card_front_url,
                'id_back' => $id_card_back_url,
                'selfie' => $selfie_url
            ]);

            if (!$personal_details_id) {
                throw new \RuntimeException('Personal details could not be stored.');
            }

            if (!$is_egirl) {
                $limits_id = db_add_row('booster_limits', [
                    'booster_id' => $booster,
                    'order_limit' => 3,
                    'lol_rank_limit' => '6|3',
                ]);

                $profile_id = db_add_row('booster_profiles', [
                    'booster_id' => $booster
                ]);

                if (!$limits_id || !$profile_id) {
                    throw new \RuntimeException('Booster setup could not be stored.');
                }
            }
        } catch (\Throwable $e) {
            // Do not leave an orphaned booster that cannot appear in the admin
            // application list. These rows belong exclusively to this new signup.
            try { db_delete_rows('booster_profiles', ['booster_id' => $booster]); } catch (\Throwable $cleanupError) {}
            try { db_delete_rows('booster_limits', ['booster_id' => $booster]); } catch (\Throwable $cleanupError) {}
            try { db_delete_rows('booster_personal_details', ['booster_id' => $booster]); } catch (\Throwable $cleanupError) {}
            try { db_delete_rows('boosters', ['id' => $booster]); } catch (\Throwable $cleanupError) {}
            error_log('Booster onboarding persistence failed: ' . $e->getMessage());

            echo json_encode([
                'success' => false,
                'playSound' => 'error',
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Your application could not be saved completely. Please try again.',
                ],
            ]);
            return;
        }

        $this->send_onboarding_complete_webhook($is_egirl ? 'egirl' : 'booster', (int)$booster, [
            'username' => $_POST['username'] ?? '',
            'games' => $games_value,
            'hired_by_admin_id' => $hired_by_admin_id,
            'country' => $_POST['country'] ?? '',
            'fullname' => $_POST['fullname'] ?? '',
            'email' => $_POST['email'] ?? '',
        ]);

        echo json_encode(['success' => true]);
        return;
    }

