    // ─── SELLER ONBOARDING ───────────────────────────────────────────────────

    public function get_seller_onboarding_url()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $token = generateOneTimeLink('seller_onboarding', 72); // 72h expiry

        echo json_encode([
            'token' => $token,
            'url'   => BASE_URL . '/seller-onboarding?t=' . $token
        ]);
    }

    public function seller_application()
    {
        // Public handler — no auth required (accessed via onboarding link)
        global $db;

        $validator = new Validator();
        $validation = $validator->make($_POST, [
            'fullname' => 'required',
            'username' => 'required',
            'email'    => 'required|email',
            'dob'      => 'required',
            'address'  => 'required',
            'country'  => 'required',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Check email uniqueness
        $existing = $db->row("SELECT id FROM sellers WHERE email = ? LIMIT 1", esc($_POST['email']));
        if ($existing) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'A seller with this email already exists.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $existing_un = $db->row("SELECT id FROM sellers WHERE username = ? LIMIT 1", esc($_POST['username']));
        if ($existing_un) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'This username is already taken.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Ensure columns exist (centralized schema guard — runs once per process)
        $this->ensure_selling_schema();

        // Upload documents, maximum 8 MB per image.
        $username_slug = preg_replace('/[^a-z0-9_]/', '_', strtolower(esc($_POST['username'])));
        $id_front_url = $id_back_url = $selfie_url = '';
        $max_onboarding_image_size = 8 * 1024 * 1024;
        $seller_files = [
            'id_card_front' => ['label' => 'ID Card Front', 'target' => 'id_front_url'],
            'id_card_back'  => ['label' => 'ID Card Back', 'target' => 'id_back_url'],
            'selfie'        => ['label' => 'Selfie', 'target' => 'selfie_url'],
        ];

        foreach ($seller_files as $fileKey => $meta) {
            $file = $_FILES[$fileKey] ?? [];
            $upload_error = (int)($file['error'] ?? UPLOAD_ERR_NO_FILE);

            if ($upload_error === UPLOAD_ERR_INI_SIZE || $upload_error === UPLOAD_ERR_FORM_SIZE
                || (int)($file['size'] ?? 0) > $max_onboarding_image_size) {
                echo json_encode([
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => $meta['label'] . ' is too large. Each image may be up to 8 MB.'],
                    'playSound' => 'error',
                    'success' => false,
                ]);
                return;
            }

            if ($upload_error !== UPLOAD_ERR_OK) {
                echo json_encode([
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'The ' . $meta['label'] . ' could not be uploaded. Please select the image again.'],
                    'playSound' => 'error',
                    'success' => false,
                ]);
                return;
            }

            $url = upload_image($file, 'seller_docs/' . $username_slug);
            if ($url === false) {
                echo json_encode([
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid file format for ' . $meta['label'] . '. Allowed: JPG, JPEG, PNG, WEBP.'],
                    'playSound' => 'error',
                    'success' => false,
                ]);
                return;
            }
            ${$meta['target']} = $url;
        }

        // Create seller row (pending, is_active=0)
        try {
            $nextSeller = $db->row("SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM sellers");
            $nextSellerId = (int)($nextSeller['next_id'] ?? 1);
            if ($nextSellerId <= 0) {
                $nextSellerId = 1;
            }

            // Auto-generate URL-safe slug from username (spaces -> hyphens)
            $raw_username = esc($_POST['username']);
            $seller_slug  = strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $raw_username), '-'));

            // "Hired by" is the admin who generated the seller onboarding link.
            try { $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS hired_by_admin_id INT UNSIGNED NULL DEFAULT NULL"); } catch (\Throwable $e) {}
            $hired_by_admin_id = function_exists('onboarding_link_admin_id')
                ? onboarding_link_admin_id(onboarding_current_token(), 'seller_onboarding')
                : 0;

            $seller_id = db_add_row('sellers', [
                'id'                => $nextSellerId,
                'hired_by_admin_id' => $hired_by_admin_id > 0 ? $hired_by_admin_id : null,
                'username'          => $raw_username,
                'email'             => esc($_POST['email']),
                'fullname'          => esc($_POST['fullname']),
                'dob'               => esc($_POST['dob']),
                'address'           => esc($_POST['address']),
                'country'           => esc($_POST['country']),
                'id_front'          => $id_front_url,
                'id_back'           => $id_back_url,
                'selfie'            => $selfie_url,
                'password'          => '',
                'balance'           => 0,
                'is_active'         => 0,
                'is_banned'         => 0,
                'onboarding_status' => 'pending',
                'slug'              => $seller_slug,
            ]);

            if (!$seller_id) {
                $seller_id = $nextSellerId;
            }
        } catch (\Throwable $e) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => $e->getMessage()],
                'playSound' => 'error',
            ]);
            return;
        }

        if (!$seller_id) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create seller. Please try again.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Notify admins via notification
        try {
            db_insert_row('notifications', [
                'type'         => 'new_seller_application',
                'data'         => json_encode(['seller_id' => $seller_id, 'username' => esc($_POST['username'])]),
                'recipient'    => 'admin',
                'recipient_id' => 0,
                'is_email'     => 0,
                'is_web'       => 1,
            ]);
        } catch (\Throwable $e) {}

        $this->send_onboarding_complete_webhook('seller', (int)$seller_id, [
            'username' => $_POST['username'] ?? '',
            'games' => '',
            'hired_by_admin_id' => $hired_by_admin_id ?? 0,
            'country' => $_POST['country'] ?? '',
            'fullname' => $_POST['fullname'] ?? '',
            'email' => $_POST['email'] ?? '',
        ]);

        echo json_encode([
            'playSound' => 'success',
        ]);
        return;
    }

    public function admin_approve_seller()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        global $db;
        $seller_id = (int)($_POST['id'] ?? 0);
        if ($seller_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Invalid ID.']]);
            return;
        }

        $seller = $db->row("SELECT * FROM sellers WHERE id = ? LIMIT 1", $seller_id);
        if (!$seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Seller not found.']]);
            return;
        }

        $password = generate_password();

        $db->run(
            "UPDATE sellers SET is_active = 1, is_banned = 0, onboarding_status = 'approved', password = ? WHERE id = ?",
            sha1($password),
            $seller_id
        );

        log_admin_action(ADMIN_ID, 'Approved seller application #' . $seller_id . ' (' . $seller['username'] . ')');

        // Send login credentials via email
        try {
            db_insert_row('notifications', [
                'type'         => 'welcome_seller',
                'data'         => json_encode([
                    'action_url' => base64_encode(BASE_URL . '/seller-area/auth/login'),
                    'email'      => base64_encode($seller['email']),
                    'password'   => base64_encode($password),
                ]),
                'recipient'    => 'seller',
                'recipient_id' => $seller_id,
                'is_email'     => 1,
                'is_web'       => 0,
            ]);
        } catch (\Throwable $e) {}

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Approved!', 'message' => 'Seller approved. Login credentials sent via email.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_decline_seller()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        global $db;
        $seller_id = (int)($_POST['id'] ?? 0);
        if ($seller_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Invalid ID.']]);
            return;
        }

        $db->run(
            "UPDATE sellers SET onboarding_status = 'rejected', is_active = 0 WHERE id = ?",
            $seller_id
        );

        log_admin_action(ADMIN_ID, 'Declined seller application #' . $seller_id);

        echo json_encode([
            'sendToast' => ['type' => 'info', 'title' => 'Declined', 'message' => 'Application declined.'],
            'refreshPage' => true,
        ]);
    }

    public function seller_email_exists()
    {
        global $db;
        $email = esc(trim($_POST['email'] ?? ''));
        if (!$email) { echo json_encode(['exists' => false]); return; }
        $row = $db->row("SELECT id FROM sellers WHERE email = ? LIMIT 1", $email);
        echo json_encode(['exists' => (bool)$row]);
    }

    public function booster_update_booster_personals()
    {
        if ($this->is_booster) {
            $booster_id = intval($_POST['id']);
            unset($_POST['id']);
            $booster = db_get_row('boosters', ['id' => $booster_id]);

            $post_params = esc_array($_POST);

            $get_record = db_get_row('booster_personal_details', ['booster_id' => $booster_id]);

            if (!$get_record) {
                db_add_row('booster_personal_details', ['booster_id' => $booster_id]);
            }

            $upd_booster = db_update_row('booster_personal_details', ['booster_id' => $booster_id], $post_params);

            $id_card_front = $_FILES['id_front'] ?? [];
            $id_card_back = $_FILES['id_back'] ?? [];
            $selfie = $_FILES['selfie'] ?? [];

            if ($id_card_front['name'] != '') {
                $image_url = upload_image($id_card_front, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['id_front' => $image_url]);

                }
            }

            if ($id_card_back['name'] != '') {
                $image_url = upload_image($id_card_back, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['id_back' => $image_url]);
                }
            }

            if ($selfie['name'] != '') {
                $image_url = upload_image($selfie, 'booster_docs/' . $booster['username']);

                if ($image_url == false) {
                    echo json_encode(["sendToast" => ["type" => "danger", "title" => "Error", "message" => "Invalid file type."]]);
                    exit();
                } else {
                    db_update_row('booster_personal_details', ['booster_id' => $booster_id], ['selfie' => $image_url]);
                }
            }

            $updated_booster = db_get_row('booster_personal_details', ['booster_id' => $booster_id]);
            $docs_complete = $this->pd_docs_complete($updated_booster);
            db_update_row('boosters', ['id' => $booster_id], ['docs_complete' => $docs_complete]);

if ($upd_booster) {
                log_admin_action(ADMIN_ID, 'Updated booster personal details #' . $booster_id);
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Booster Personal Details Updated Successfully 🎉',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ));
            } else {
                echo json_encode(array(
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Something went wrong 😔',
                    ],
                    'playSound' => 'error',
                ));
            }
        }
    }

    public function dashboard_data()
    {
        // The UI sends start_date/end_date as YYYY-MM-DD.
        // Your DB timestamps match Europe/Berlin local time (no UTC conversion).
        // So we only expand to full-day ranges and DO NOT convert to UTC.
        date_default_timezone_set('Europe/Berlin');

        $start_raw = trim($_POST['start_date'] ?? '');
        $end_raw   = trim($_POST['end_date'] ?? '');

        // Robust fallback
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $start_raw)) {
            $start_raw = date('Y-m-d');
        }
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $end_raw)) {
            $end_raw = date('Y-m-d');
        }

        $start_date = $start_raw . ' 00:00:00';
        $end_date   = $end_raw   . ' 23:59:59';

        $data = [
            'monthly_revenue' => get_monthly_revenue_data(),
            'weekly_orders' => get_weekly_orders_data($start_date, $end_date),
            'monthly_forms' => get_monthly_forms_revenue_data($start_date, $end_date),
            'total_revenue' => get_total_revenue($start_date, $end_date),
            'boosting_revenue' => get_boosting_revenue($start_date, $end_date),
            'accounts_revenue' => get_accounts_revenue($start_date, $end_date),
            'account_sales_revenue' => get_account_sales_revenue($start_date, $end_date),
            'selling_accounts_fee_revenue' => get_selling_accounts_fee_revenue($start_date, $end_date),
            'smurf_accounts_revenue' => get_smurf_accounts_revenue($start_date, $end_date),
            'tips_revenue' => get_tips_revenue($start_date, $end_date),
            'order_stats' => get_order_stats($start_date, $end_date),
            'expenses' => get_expenses_data($start_date, $end_date),
            'profit' => get_profit_data($start_date, $end_date),
            'payments_summary' => get_payments_summary($start_date, $end_date),
            'customers_summary' => get_customers_summary($start_date, $end_date),
        ];

        echo json_encode($data);
    }

    public function admin_create_account()
    {
