            'blue_essence' => 'nullable|numeric',
            'riot_points' => 'nullable|numeric',
            'winrate_percent' => 'nullable|numeric',
        ]);

        $validation->validate();

        if ($validation->fails()) {
            $errors = $validation->errors()->firstOfAll();

            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Please fill in all required fields.',
                ],
                'playSound' => 'error',
                'validationErrors' => $errors,
            ]);

            return;
        }

        $uploaded_images = [];

        if (isset($_FILES['images']['name']) && is_array($_FILES['images']['name'])) {
            $total = count($_FILES['images']['name']);

            for ($i = 0; $i < $total; $i++) {
                if (
                    empty($_FILES['images']['name'][$i]) ||
                    $_FILES['images']['error'][$i] !== UPLOAD_ERR_OK ||
                    empty($_FILES['images']['tmp_name'][$i])
                ) {
                    continue;
                }

                $file = [
                    'name' => $_FILES['images']['name'][$i],
                    'type' => $_FILES['images']['type'][$i],
                    'tmp_name' => $_FILES['images']['tmp_name'][$i],
                    'error' => $_FILES['images']['error'][$i],
                    'size' => $_FILES['images']['size'][$i],
                ];

                $uuid = uniqid("account_", true);
                $image_url = upload_image($file, 'accounts-gallery/' . $uuid);

                if ($image_url === false) {
                    echo json_encode([
                        "sendToast" => [
                            "type" => "danger",
                            "title" => "Error",
                            "message" => "Invalid file: " . $file['name']
                        ]
                    ]);
                    return;
                }

                $uploaded_images[] = $image_url;
