        if (empty($uploaded_images)) {
            echo json_encode([
                "sendToast" => [
                    "type" => "danger",
                    "title" => "Error",
                    "message" => "You must upload at least one image.",
                ],
                "playSound" => "error",
            ]);
            return;
        }

        $data = [
            'title' => $_POST['title'],
            'slug' => generateUniqueSlug($_POST['title'], 'selling_accounts'),
            'price' => $_POST['price'] * 100,
            'game' => 'lol',
            'admin_id' => (int) ADMIN_ID,
            'description' => $_POST['description'],
            'current_rank' => $_POST['current_rank'],
            'current_division' => $_POST['current_division'],
