            'flex_rank' => $_POST['flex_rank'],
            'flex_division' => $_POST['flex_division'],
            'flex_lp' => $_POST['flex_lp'] == '' ? null : $_POST['flex_lp'],
            'previous_rank' => $_POST['previous_rank'],
            'previous_division' => $_POST['previous_division'],
            'previous_lp' => $_POST['previous_lp'] == '' ? null : $_POST['previous_lp'],
            'server' => $_POST['server'],
            'level_up_method' => $_POST['level_up_method'],
            'level' => (isset($_POST['level']) && $_POST['level'] !== '' ? (int)$_POST['level'] : null),
            'blue_essence' => (isset($_POST['blue_essence']) && $_POST['blue_essence'] !== '' ? (int)$_POST['blue_essence'] : null),
            'riot_points' => (isset($_POST['riot_points']) && $_POST['riot_points'] !== '' ? (int)$_POST['riot_points'] : null),
            'winrate_percent' => (isset($_POST['winrate_percent']) && $_POST['winrate_percent'] !== '' ? (int)$_POST['winrate_percent'] : null),
            'champions' => (isset($_POST['champions']) && is_array($_POST['champions'])) ? implode('|', $_POST['champions']) : '',
            'skins' => (isset($_POST['skins']) && is_array($_POST['skins'])) ? implode('|', $_POST['skins']) : '',
            'champion_count' => (isset($_POST['champion_count']) && $_POST['champion_count'] !== '' && !(isset($_POST['champions']) && is_array($_POST['champions']) && count($_POST['champions']) > 0)) ? (int)$_POST['champion_count'] : null,
            'skin_count' => (isset($_POST['skin_count']) && $_POST['skin_count'] !== '' && !(isset($_POST['skins']) && is_array($_POST['skins']) && count($_POST['skins']) > 0)) ? (int)$_POST['skin_count'] : null,
            'roles' => (isset($_POST['roles']) && is_array($_POST['roles'])) ? implode('|', $_POST['roles']) : '',
            'delivery_type' => $_POST['delivery_type'],
            'login' => $_POST['login'],
            'password' => $_POST['password'],
            'email' => $_POST['email'],
            'email_password' => $_POST['email_password'],
            'in_game_name' => $_POST['in_game_name'],
            '2fa' => !empty($_POST['has_2fa']) ? 1 : 0,
            'delivery_instructions' => $_POST['delivery_instructions'],
        ];

        if (!empty($uploaded_images)) {
            $data['images'] = json_encode($uploaded_images);
        }

        $account = db_add_row('selling_accounts', $data);

        if ($account) {
            log_admin_action(ADMIN_ID, 'Created new account #' . $account);
            if (function_exists('trigger_notification_sender_async')) {
                @trigger_notification_sender_async();
            }
            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Account created successfully 🎉',
                ],
                'playSound' => 'success',
                'refreshPage' => true,
            ]);
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to create account.',
                ],
                'playSound' => 'error',
            ]);
            return;
