                        ]
                    ]);
                    return;
                }

                $uploaded_images[] = $image_url;
            }
        }

        $data = [
            'title' => $_POST['title'],
            'slug' => generateUniqueSlug($_POST['title'], 'selling_accounts'),
            'price' => $_POST['price'] * 100,
            'game' => 'lol',
            'description' => $_POST['description'],
            'current_rank' => $_POST['current_rank'],
            'current_division' => $_POST['current_division'],
            'current_lp' => $_POST['current_lp'] == '' ? null : $_POST['current_lp'],
            'flex_rank' => $_POST['flex_rank'],
            'flex_division' => $_POST['flex_division'],
            'flex_lp' => $_POST['flex_lp'] == '' ? null : $_POST['flex_lp'],
            'previous_rank' => $_POST['previous_rank'],
            'previous_division' => $_POST['previous_division'],
            'previous_lp' => $_POST['previous_lp'] == '' ? null : $_POST['previous_lp'],
            'server' => $_POST['server'],
            'level_up_method' => $_POST['level_up_method'],
            'level' => (isset($_POST['level']) && $_POST['level'] !== '' ? (int)$_POST['level'] : null),
            'blue_essence' => (isset($_POST['blue_essence']) && $_POST['blue_essence'] !== '' ? (int)$_POST['blue_essence'] : null),
            'riot_points' => (isset($_POST['riot_points']) && $_POST['riot_points'] !== '' ? (int)$_POST['riot_points'] : null),
            'winrate_percent' => (isset($_POST['winrate_percent']) && $_POST['winrate_percent'] !== '' ? (int)$_POST['winrate_percent'] : null),
            'champions' => (isset($_POST['champions']) && is_array($_POST['champions'])) ? implode('|', $_POST['champions']) : '',
            'skins' => (isset($_POST['skins']) && is_array($_POST['skins'])) ? implode('|', $_POST['skins']) : '',
            'champion_count' => (isset($_POST['champion_count']) && $_POST['champion_count'] !== '' && !(isset($_POST['champions']) && is_array($_POST['champions']) && count($_POST['champions']) > 0)) ? (int)$_POST['champion_count'] : null,
            'skin_count' => (isset($_POST['skin_count']) && $_POST['skin_count'] !== '' && !(isset($_POST['skins']) && is_array($_POST['skins']) && count($_POST['skins']) > 0)) ? (int)$_POST['skin_count'] : null,
            'roles' => (isset($_POST['roles']) && is_array($_POST['roles'])) ? implode('|', $_POST['roles']) : '',
            'delivery_type' => $_POST['delivery_type'],
            'login' => $_POST['login'],
            'password' => $_POST['password'],
            'email' => $_POST['email'],
            'email_password' => $_POST['email_password'],
            'in_game_name' => $_POST['in_game_name'],
            '2fa' => !empty($_POST['has_2fa']) ? 1 : 0,
            'delivery_instructions' => $_POST['delivery_instructions'],
        ];

        // --- Images: persist visual order + allow reordering/removal ---
        // Frontend sends `images_order` as JSON array containing:
        //  - existing image URLs
        //  - placeholders "__new__0", "__new__1", ... for newly uploaded files
        // Uploaded files come in the same order as placeholders.
        $account_for_images = db_get_row('selling_accounts', ['id' => (int)$_POST['id']]);
        $existing_images = json_decode($account_for_images['images'] ?? '[]', true);
        if (!is_array($existing_images)) {
            $existing_images = [];
        }

        $final_images = null; // null => do not touch images
        $posted_order = null;

        if (isset($_POST['images_order']) && $_POST['images_order'] !== '') {
            $posted_order = json_decode((string)$_POST['images_order'], true);
            if (!is_array($posted_order)) {
                $posted_order = null;
            }
        }

        if (is_array($posted_order)) {
            $final_images = [];
            $existing_set = array_flip($existing_images);
            $used_new = [];

            foreach ($posted_order as $entry) {
                if (!is_string($entry) || $entry === '') {
                    continue;
                }

                // Existing URL: only allow those that already belong to this account
                if (strpos($entry, '__new__') !== 0) {
                    if (isset($existing_set[$entry])) {
                        $final_images[] = $entry;
                    }
                    continue;
                }

                // New placeholder: "__new__{index}"
                $idx = (int)substr($entry, 7);
                if (isset($uploaded_images[$idx]) && !empty($uploaded_images[$idx]) && empty($used_new[$idx])) {
                    $final_images[] = $uploaded_images[$idx];
                    $used_new[$idx] = true;
                }
            }

            // Append any uploaded images that weren't referenced (safety)
            foreach ($uploaded_images as $i => $url) {
                if (empty($used_new[$i])) {
                    $final_images[] = $url;
                }
            }

            // De-duplicate while preserving order
            $seen = [];
            $deduped = [];
            foreach ($final_images as $u) {
                if (isset($seen[$u])) {
                    continue;
                }
                $seen[$u] = true;
                $deduped[] = $u;
            }
            $final_images = $deduped;
        } elseif (!empty($uploaded_images)) {
            // No explicit order provided: append new uploads to existing
            $final_images = array_merge($existing_images, $uploaded_images);
        }

        if ($final_images !== null) {
            $data['images'] = json_encode(array_values($final_images));
        }

$account = db_update_row('selling_accounts', ['id' => $_POST['id']], $data);

        if ($account) {
            log_admin_action(ADMIN_ID, 'Updated account #' . $account);
            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Account Updated successfully 🎉',
                ],
                'playSound' => 'success',
                'refreshPage' => true,
            ]);
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to update account.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }
    }

