    function admin_bulk_delete_accounts()
    {
        // Access control: admins with can_view_all_accounts=1 can manage all accounts.
        // Others can only manage accounts they created (selling_accounts.admin_id = ADMIN_ID).
        $me = db_get_row('admins', ['id' => ADMIN_ID]);
        $can_view_all_accounts = !empty($me['can_view_all_accounts']) || !empty($me['view_all_accounts']);

        $ids = $_POST['ids'] ?? [];
        if (!is_array($ids)) {
            // allow comma-separated
            $ids = array_filter(array_map('trim', explode(',', (string)$ids)));
        }

        $ids = array_values(array_unique(array_filter(array_map('intval', $ids), fn($v) => $v > 0)));

        if (empty($ids)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'No accounts selected.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $deleted = 0;
        $denied = 0;
        $notFound = 0;

        foreach ($ids as $id) {
            $account = db_get_row('selling_accounts', ['id' => (int)$id]);
            if (empty($account)) {
                $notFound++;
                continue;
            }

            if (!$can_view_all_accounts && (int)($account['admin_id'] ?? 0) !== (int)ADMIN_ID) {
                $denied++;
                continue;
            }

            db_delete_rows('selling_accounts', ['id' => (int)$id]);
            $deleted++;
        }

        if ($deleted === 0) {
            $msg = 'No accounts were deleted.';
            if ($denied > 0) $msg .= ' Access denied for ' . $denied . ' account(s).';
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => $msg,
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $msgParts = [];
        $msgParts[] = $deleted . ' account(s) deleted.';
        if ($denied > 0) $msgParts[] = $denied . ' denied.';
        if ($notFound > 0) $msgParts[] = $notFound . ' not found.';

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => implode(' ', $msgParts),
            ],
            'playSound' => 'success',
            // simplest UX: refresh the list
            'refreshPage' => true,
        ]);
    }


    public function account_shop_popular_counts()
    {
        global $db;

        header('Content-Type: application/json; charset=utf-8');

        $filterGame = strtolower(trim((string)($_POST['game'] ?? 'lol')));
        $base = ["sold = 0", "COALESCE(active, 1) = 1"];
        if ($filterGame === 'val') {
            $base[] = "game = 'val'";
        } else {
            $base[] = "(game = 'lol' OR game IS NULL)";
        }

        $serverMap = [
            'EU' => 'EU', 'EUROPE' => 'EU',
            'EUW' => 'EUW', 'EU-WEST' => 'EUW', 'EU WEST' => 'EUW',
            'EUNE' => 'EUNE', 'EU-NORDIC & EAST' => 'EUNE', 'EU-NORTH EAST' => 'EUNE', 'EU NORTHEAST' => 'EUNE',
            'NA' => 'NA', 'NORTH AMERICA' => 'NA',
            'BR' => 'BR', 'BRAZIL' => 'BR',
            'LAN' => 'LAN', 'LATIN AMERICA NORTH' => 'LAN',
            'LAS' => 'LAS', 'LATIN AMERICA SOUTH' => 'LAS',
            'OCE' => 'OCE', 'OCEANIA' => 'OCE',
            'RU' => 'RU', 'RUSSIA' => 'RU',
            'TR' => 'TR', 'TURKEY' => 'TR',
            'JP' => 'JP', 'JAPAN' => 'JP',
            'KR' => 'KR', 'KOREA' => 'KR',
            'SEA' => 'SEA', 'SOUTHEAST ASIA' => 'SEA',
            'ME' => 'ME', 'MIDDLE EAST' => 'ME',
            'VN' => 'VN', 'VIETNAM' => 'VN',
            'PH' => 'PH', 'PHILIPPINES' => 'PH',
            'SG' => 'SG', 'SINGAPORE' => 'SG',
            'TH' => 'TH', 'THAILAND' => 'TH',
            'TW' => 'TW', 'TAIWAN' => 'TW',
        ];

        $rankNameMap = [
            'UNRANKED' => 0,
            'IRON' => 1,
            'BRONZE' => 2,
            'SILVER' => 3,
            'GOLD' => 4,
            'PLATINUM' => 5,
            'EMERALD' => 6,
            'DIAMOND' => 7,
            'ASCENDANT' => 7,
            'MASTER' => 8,
            'IMMORTAL' => 8,
            'GRANDMASTER' => 9,
            'RADIANT' => 9,
            'CHALLENGER' => 10,
        ];

        $checks = $_POST['checks'] ?? [];
        if (!is_array($checks)) {
            $checks = [];
        }

        $counts = [];
        foreach ($checks as $idx => $check) {
            if (!is_array($check)) {
                $counts[$idx] = 0;
                continue;
            }

            $conditions = $base;

            $serverValues = array_filter(array_map('trim', explode(',', (string)($check['servers'] ?? ''))));
            if (!empty($serverValues)) {
                $servers = [];
                foreach ($serverValues as $server) {
                    $key = strtoupper(trim($server));
                    if ($key === '') continue;
                    $servers[] = $serverMap[$key] ?? $key;
                }
                $servers = array_values(array_unique(array_filter($servers)));
                if (!empty($servers)) {
                    $servers = array_map('esc', $servers);
                    $conditions[] = "UPPER(server) IN ('" . implode("','", $servers) . "')";
                }
            }

            $rankValues = array_filter(array_map('trim', explode(',', (string)($check['ranks'] ?? ''))));
            if (!empty($rankValues)) {
                $ranks = [];
                foreach ($rankValues as $rank) {
                    if ($rank === '') continue;
                    if (is_numeric($rank)) {
                        $ranks[] = (int)$rank;
                    } else {
                        $key = preg_replace('/[^A-Z]/', '', strtoupper($rank));
                        if (isset($rankNameMap[$key])) {
                            $ranks[] = $rankNameMap[$key];
                        }
                    }
                }
                $ranks = array_values(array_unique($ranks));
                if (!empty($ranks)) {
                    $conditions[] = "rank IN (" . implode(',', $ranks) . ")";
                }
            }

            $roleValues = array_filter(array_map('trim', explode(',', (string)($check['roles'] ?? ''))));
            if (!empty($roleValues)) {
                $roles = array_map('esc', $roleValues);
                $roleConditions = array_map(function ($role) {
                    return "CONCAT('|', roles, '|') LIKE '%|$role|%'";
                }, $roles);
                $conditions[] = '(' . implode(' OR ', $roleConditions) . ')';
            }

            $deliveryValues = array_filter(array_map('trim', explode(',', (string)($check['delivery'] ?? ''))));
            if (!empty($deliveryValues)) {
                $deliveryValues = array_map('esc', $deliveryValues);
                $conditions[] = "delivery_type IN ('" . implode("','", $deliveryValues) . "')";
            }

            try {
                $where = 'WHERE ' . implode(' AND ', $conditions);
                $row = $db->run("SELECT COUNT(*) AS c FROM selling_accounts $where");
                $counts[$idx] = (int)($row[0]['c'] ?? 0);
            } catch (\Throwable $e) {
                $counts[$idx] = 0;
            }
        }

        echo json_encode(['success' => true, 'counts' => $counts]);
        exit;
    }

    public function shop_popular_filter_counts()
    {
        global $db;
        header('Content-Type: application/json; charset=utf-8');

        $entity = strtolower(trim((string)($_POST['entity'] ?? 'accounts')));
        $game = strtolower(trim((string)($_POST['game'] ?? '')));
        $gameId = (int)($_POST['game_id'] ?? 0);
        $checks = is_array($_POST['checks'] ?? null) ? $_POST['checks'] : [];
        $counts = [];

        foreach (array_slice($checks, 0, 30, true) as $idx => $check) {
            if (!is_array($check)) {
                $counts[$idx] = 0;
                continue;
            }
            $kind = preg_replace('/[^a-zA-Z0-9_]/', '', str_replace('[]', '', (string)($check['kind'] ?? '')));
            $value = trim((string)($check['value'] ?? ''));
            if ($kind === '' || $value === '') {
                $counts[$idx] = 0;
                continue;
            }

            try {
                $safe = esc($value);
                if ($entity === 'items') {
                    $conditions = ['si.active = 1'];
                    $gameAliases = in_array($game, ['lol','league','league-of-legends'], true)
                        ? ['lol','league','league-of-legends'] : array_filter([$game]);
                    if ($gameId > 0 && !empty($gameAliases)) {
                        $conditions[] = "(COALESCE(si.game_id,0) = {$gameId} OR (COALESCE(si.game_id,0) = 0 AND LOWER(TRIM(COALESCE(si.game,''))) IN ('" . implode("','", array_map('esc', $gameAliases)) . "')))";
                    } elseif ($gameId > 0) {
                        $conditions[] = "COALESCE(si.game_id,0) = {$gameId}";
                    } elseif ($game !== '') {
                        $conditions[] = "LOWER(TRIM(COALESCE(si.game,''))) IN ('" . implode("','", array_map('esc', $gameAliases)) . "')";
                    }
                    if (in_array($kind, ['type','types'], true)) {
                        $typeAliases = [
                            'skins' => ['skins','skin'],
                            'chests-keys' => ['chests-keys','chest-key','chest','chests & keys'],
                            'orbs' => ['orbs','orb'],
                            'capsules' => ['capsules','capsule'],
                            'event-pass' => ['event-pass','pass','event pass'],
                            'bundles' => ['bundles','bundle'],
                            'tft-item' => ['tft-item','tft item','tft'],
                            'mystery-gift' => ['mystery-gift','mystery gift','gifting'],
                        ];
                        $aliases = $typeAliases[strtolower($value)] ?? [strtolower($value)];
                        $conditions[] = "LOWER(TRIM(COALESCE(si.type,''))) IN ('" . implode("','", array_map('esc', $aliases)) . "')";
                    } elseif (in_array($kind, ['server','servers'], true)) {
                        $conditions[] = "UPPER(TRIM(COALESCE(si.server,''))) = UPPER('{$safe}')";
                    } else {
                        $path = '$."' . $kind . '"';
                        $conditions[] = "(LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data,'" . esc($path) . "'))) = LOWER('{$safe}') OR LOWER(COALESCE(si.item_data,'')) LIKE LOWER('%\"{$safe}\"%'))";
                    }
                    $row = $db->run('SELECT COUNT(*) AS c FROM selling_items si WHERE ' . implode(' AND ', $conditions));
                } else {
                    $conditions = ['sa.sold = 0', 'COALESCE(sa.active,1) = 1'];
                    if (in_array($game, ['lol','league','league-of-legends'], true)) {
                        $conditions[] = "(sa.game IN ('lol','league','league-of-legends') OR sa.game IS NULL OR sa.game='')";
                    } elseif (in_array($game, ['val','valorant'], true)) {
                        $conditions[] = "sa.game IN ('val','valorant')";
                    } elseif ($game !== '') {
                        $conditions[] = "LOWER(TRIM(COALESCE(sa.game,''))) = '" . esc($game) . "'";
                    }
                    if (in_array($kind, ['server','servers'], true)) {
                        $conditions[] = "UPPER(TRIM(COALESCE(sa.server,''))) = UPPER('{$safe}')";
                    } elseif (in_array($kind, ['role','roles'], true)) {
                        $conditions[] = "LOWER(CONCAT('|',COALESCE(sa.roles,''),'|')) LIKE LOWER('%|{$safe}|%')";
                    } elseif (in_array($kind, ['delivery','delivery_type'], true)) {
                        $conditions[] = "LOWER(COALESCE(sa.delivery_type,'')) = LOWER('{$safe}')";
                    } else {
                        $path = '$."' . $kind . '"';
                        $conditions[] = "(LOWER(JSON_UNQUOTE(JSON_EXTRACT(sa.game_data,'" . esc($path) . "'))) = LOWER('{$safe}') OR LOWER(COALESCE(sa.game_data,'')) LIKE LOWER('%\"{$safe}\"%'))";
                    }
                    $row = $db->run('SELECT COUNT(*) AS c FROM selling_accounts sa WHERE ' . implode(' AND ', $conditions));
                }
                $counts[$idx] = (int)($row[0]['c'] ?? 0);
            } catch (\Throwable $e) {
                $counts[$idx] = 0;
            }
        }

        echo json_encode(['success' => true, 'counts' => $counts]);
        exit;
    }

    function account_shop_filters()
{
    global $db;

    header('Content-Type: application/json; charset=utf-8');

    // --- base conditions (always exclude sold) ---
    $conditions = ["sold = 0", "active = 1"];

    // Game filter. Live originally only knew LoL/Valorant. Dynamic games such as
    // call-of-duty or grand-theft-auto-vi must stay scoped to their own listings.
    $filterGame = strtolower(trim((string)($_POST['game'] ?? 'lol')));
    $gameAliases = [
        'league-of-legends' => 'league-of-legends',
        'lol'               => 'league-of-legends',
        'valorant'          => 'valorant',
        'val'               => 'valorant',
        'teamfight-tactics' => 'teamfight-tactics',
        'tft'               => 'teamfight-tactics',
        'call-of-duty'      => 'call-of-duty',
        'cod'               => 'call-of-duty',
    ];
    $filterGame = $gameAliases[$filterGame] ?? preg_replace('/[^a-z0-9_-]/', '', $filterGame);

    if ($filterGame === 'league-of-legends') {
        $conditions[] = "(game = 'lol' OR game = 'league-of-legends' OR game IS NULL OR game = '')";
    } elseif ($filterGame === 'valorant') {
        $conditions[] = "(game = 'val' OR game = 'valorant')";
    } elseif ($filterGame === 'call-of-duty') {
        $conditions[] = "(game = 'cod' OR game = 'call-of-duty')";
    } else {
        $conditions[] = "game = '" . esc($filterGame) . "'";
    }

    // Public listing search. Search every customer-facing account attribute,
    // including the long champion/skin lists and dynamic game schema JSON.
    // Split the query into words so e.g. "ranked ready" also matches text with
    // punctuation between both words. Never include credentials or email fields.
    if (!empty($_POST['search'])) {
        $rawSearch = trim((string)$_POST['search']);
        $searchTerms = preg_split('/[\s\p{P}\p{S}]+/u', $rawSearch, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $searchTerms = array_slice(array_values(array_unique($searchTerms)), 0, 10);
        $accountSearchHaystack = "LOWER(CONCAT_WS(' ',
            COALESCE(title,''), COALESCE(slug,''), COALESCE(description,''),
            COALESCE(game,''), COALESCE(rank_label,''), COALESCE(game_data,''),
            COALESCE(server,''), COALESCE(level_up_method,''), COALESCE(roles,''),
            COALESCE(champions,''), COALESCE(skins,''), COALESCE(delivery_type,''),
            COALESCE(CAST(current_rank AS CHAR),''), COALESCE(CAST(current_division AS CHAR),''),
            COALESCE(CAST(current_lp AS CHAR),''), COALESCE(CAST(flex_rank AS CHAR),''),
            COALESCE(CAST(flex_division AS CHAR),''), COALESCE(CAST(flex_lp AS CHAR),''),
            COALESCE(CAST(previous_rank AS CHAR),''), COALESCE(CAST(previous_division AS CHAR),''),
            COALESCE(CAST(previous_lp AS CHAR),''), COALESCE(CAST(level AS CHAR),''),
            COALESCE(CAST(blue_essence AS CHAR),''), COALESCE(CAST(riot_points AS CHAR),''),
            COALESCE(CAST(winrate_percent AS CHAR),''), COALESCE(CAST(champion_count AS CHAR),''),
            COALESCE(CAST(skin_count AS CHAR),''), COALESCE(CAST(val_agent_count AS CHAR),'')
        ))";
        foreach ($searchTerms as $term) {
            $safeTerm = esc(mb_strtolower((string)$term, 'UTF-8'));
            if ($safeTerm !== '') {
                $conditions[] = "{$accountSearchHaystack} LIKE '%{$safeTerm}%'";
            }
        }
    }

    // delivery type (single or array)
    if (!empty($_POST['delivery_type'])) {
        if (is_array($_POST['delivery_type'])) {
            $types = array_values(array_filter($_POST['delivery_type'], fn($v) => $v !== '' && $v !== null));
            if (!empty($types)) {
                $types = array_map('esc', $types);
                $conditions[] = "delivery_type IN ('" . implode("','", $types) . "')";
            }
        } else {
            $deliveryType = esc($_POST['delivery_type']);
            $conditions[] = "delivery_type = '$deliveryType'";
        }
    }

    // servers
    $serverInput = $_POST['servers'] ?? ($_POST['servers[]'] ?? []);
    if (!is_array($serverInput)) {
        $serverInput = [$serverInput];
    }
    if (!empty($serverInput)) {
        $serverMap = [
            'EU' => 'EU', 'EUROPE' => 'EU',
            'EUW' => 'EUW', 'EU-WEST' => 'EUW', 'EU WEST' => 'EUW',
            'EUNE' => 'EUNE', 'EU-NORTH EAST' => 'EUNE', 'EU NORTHEAST' => 'EUNE',
            'NA' => 'NA', 'NORTH AMERICA' => 'NA',
            'US' => 'US', 'UNITED STATES' => 'US',
            'BR' => 'BR', 'BRAZIL' => 'BR',
            'LAN' => 'LAN', 'LATIN AMERICA NORTH' => 'LAN',
            'LAS' => 'LAS', 'LATIN AMERICA SOUTH' => 'LAS',
            'OCE' => 'OCE', 'OCEANIA' => 'OCE',
            'RU' => 'RU', 'RUSSIA' => 'RU',
            'TR' => 'TR', 'TURKEY' => 'TR',
            'JP' => 'JP', 'JAPAN' => 'JP',
            'KR' => 'KR', 'KOREA' => 'KR',
            'SEA' => 'SEA', 'SOUTHEAST ASIA' => 'SEA',
            'ME' => 'ME', 'MIDDLE EAST' => 'ME',
            'VN' => 'VN', 'VIETNAM' => 'VN',
            'PH' => 'PH', 'PHILIPPINES' => 'PH',
            'SG' => 'SG', 'SINGAPORE' => 'SG',
            'TH' => 'TH', 'THAILAND' => 'TH',
            'TW' => 'TW', 'TAIWAN' => 'TW',
            // legacy / stray values that may still exist in listings
            'AP' => 'SEA',
        ];

        $servers = [];
        foreach ($serverInput as $server) {
            if ($server === '' || $server === null) {
                continue;
            }
            $raw = strtoupper(trim((string)$server));
            $servers[] = $serverMap[$raw] ?? $raw;
        }
        $servers = array_values(array_unique(array_filter($servers, fn($v) => $v !== '')));

        if (!empty($servers)) {
            $servers = array_map('esc', $servers);
            $conditions[] = "UPPER(server) IN ('" . implode("','", $servers) . "')";
        }
    }

    // ranks — use universal `rank` column (works for all games)
    // Accept both numeric values and SEO friendly labels from URLs, for example rank=Bronze or rank=Radiant.
    $rankInput = $_POST['ranks'] ?? ($_POST['ranks[]'] ?? []);
    if (!is_array($rankInput)) {
        $rankInput = [$rankInput];
    }

    $rankNameMap = [
        'UNRANKED' => 0,
        'IRON' => 1,
        'BRONZE' => 2,
        'SILVER' => 3,
        'GOLD' => 4,
        'PLATINUM' => 5,
        'EMERALD' => 6,
        'DIAMOND' => 7,
        'ASCENDANT' => 7,
        'MASTER' => 8,
        'IMMORTAL' => 8,
        'GRANDMASTER' => 9,
        'RADIANT' => 9,
        'CHALLENGER' => 10,
    ];

    $ranks = [];
    foreach ($rankInput as $rankValue) {
        if ($rankValue === '' || $rankValue === null) {
            continue;
        }
        if (is_numeric($rankValue)) {
            $ranks[] = max(0, (int)$rankValue);
            continue;
        }
        $key = strtoupper(trim((string)$rankValue));
        $key = preg_replace('/[^A-Z]/', '', $key);
        if (isset($rankNameMap[$key])) {
            $ranks[] = $rankNameMap[$key];
        }
    }
    $ranks = array_values(array_unique($ranks));
    if (!empty($ranks)) {
        $conditions[] = "rank IN (" . implode(',', $ranks) . ")";
    }

    // roles (stored as pipe-separated string like "TopLane|Jungle|...")
    if (!empty($_POST['roles']) && is_array($_POST['roles'])) {
        $roles = array_values(array_filter($_POST['roles'], fn($v) => $v !== '' && $v !== null));
        if (!empty($roles)) {
            $roles = array_map('esc', $roles);
            $roleConditions = array_map(function ($r) {
                return "CONCAT('|', roles, '|') LIKE '%|$r|%'";
            }, $roles);
            $conditions[] = '(' . implode(' OR ', $roleConditions) . ')';
        }
    }


    // Dynamic account schema filters stored in selling_accounts.game_data.
    // This powers all non LoL and non Valorant account shops from game_account_schemas.
    if (function_exists('util_account_schema_filter_fields')) {
        foreach (util_account_schema_filter_fields($filterGame) as $schemaField) {
            $schemaKey = preg_replace('/[^a-zA-Z0-9_]/', '', (string)($schemaField['key'] ?? ''));
            if ($schemaKey === '' || in_array($schemaKey, ['price','server','rank','roles'], true)) {
                continue;
            }
            $schemaType = (string)($schemaField['type'] ?? 'text');
            $filterType = (string)($schemaField['filter_type'] ?? $schemaType);
            $jsonPath = "$." . $schemaKey;

            if ($filterType === 'range' || $schemaType === 'number') {
                $minKey = $schemaKey . '_min';
                $maxKey = $schemaKey . '_max';
                $rawMin = (isset($_POST[$minKey]) && $_POST[$minKey] !== '') ? (float)$_POST[$minKey] : null;
                $rawMax = (isset($_POST[$maxKey]) && $_POST[$maxKey] !== '') ? (float)$_POST[$maxKey] : null;
                $defaultMin = isset($schemaField['min']) ? (float)$schemaField['min'] : null;
                $defaultMax = isset($schemaField['max']) ? (float)$schemaField['max'] : null;
                if ($rawMin !== null && $defaultMin !== null && $rawMin <= $defaultMin) $rawMin = null;
                if ($rawMax !== null && $defaultMax !== null && $rawMax >= $defaultMax) $rawMax = null;
                if ($rawMin !== null || $rawMax !== null) {
                    $expr = "CAST(JSON_UNQUOTE(JSON_EXTRACT(game_data, '" . esc($jsonPath) . "')) AS DECIMAL(12,2))";
                    if ($rawMin !== null) $conditions[] = $expr . ' >= ' . (float)$rawMin;
                    if ($rawMax !== null) $conditions[] = $expr . ' <= ' . (float)$rawMax;
                }
                continue;
            }

            if ($filterType === 'checkbox' || $schemaType === 'checkbox') {
                if (!empty($_POST[$schemaKey])) {
                    $conditions[] = "JSON_UNQUOTE(JSON_EXTRACT(game_data, '" . esc($jsonPath) . "')) IN ('1','true','yes','on')";
                }
                continue;
            }

            $vals = $_POST[$schemaKey] ?? ($_POST[$schemaKey . '[]'] ?? []);
            if (!is_array($vals)) $vals = [$vals];
            $vals = array_values(array_filter(array_map('trim', array_map('strval', $vals)), static fn($v) => $v !== ''));
            if (empty($vals)) continue;

            $orParts = [];
            foreach ($vals as $val) {
                $safe = esc($val);
                // Supports scalar JSON values and arrays from multiselect fields.
                $orParts[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(game_data, '" . esc($jsonPath) . "'))) = LOWER('{$safe}')";
                $orParts[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(game_data, '" . esc($jsonPath) . "'))) LIKE LOWER('%\"{$safe}\"%')";
            }
            if (!empty($orParts)) $conditions[] = '(' . implode(' OR ', $orParts) . ')';
        }
    }

    // NOTE: DB stores price in EUR cents (INT).
    // Frontend sends price_min/price_max in EUR (e.g. 49.99).
    // We filter in cents, and we return slider range in EUR.
    $priceMinEur = (isset($_POST['price_min']) && $_POST['price_min'] !== '') ? (float) $_POST['price_min'] : null;
    $priceMaxEur = (isset($_POST['price_max']) && $_POST['price_max'] !== '') ? (float) $_POST['price_max'] : null;

    $priceMin = ($priceMinEur !== null) ? (int) round($priceMinEur * 100) : null;
    $priceMax = ($priceMaxEur !== null) ? (int) round($priceMaxEur * 100) : null;

    $conditionsNoPrice = $conditions; // copy

    if ($priceMin !== null || $priceMax !== null) {
        $min = $priceMin;
        $max = $priceMax;

        if ($min !== null && $max !== null) {
            if ($min > $max) { $tmp = $min; $min = $max; $max = $tmp; }
            $conditions[] = 'price BETWEEN ' . $min . ' AND ' . $max;
        } elseif ($min !== null) {
            $conditions[] = 'price >= ' . $min;
        } elseif ($max !== null) {
            $conditions[] = 'price <= ' . $max;
        }
    }

    $where = 'WHERE ' . implode(' AND ', $conditions);
    $whereNoPrice = 'WHERE ' . implode(' AND ', $conditionsNoPrice);

    // pagination
    $page = !empty($_POST['page']) ? max(1, (int) $_POST['page']) : 1;
    $itemsPerPage = 25;
    $offset = ($page - 1) * $itemsPerPage;

    // sorting
    $sort = !empty($_POST['sort']) ? esc($_POST['sort']) : 'recommended';
    switch ($sort) {
        case 'price_asc':
            $orderBy = "ORDER BY sa.price ASC, sa.id DESC";
            break;
        case 'price_desc':
            $orderBy = "ORDER BY sa.price DESC, sa.id DESC";
            break;
        case 'delivery_fast':
            $orderBy = "ORDER BY (sa.delivery_type = 'instant') DESC, sa.id DESC";
            break;
        case 'newest':
            $orderBy = "ORDER BY sa.id DESC";
            break;
        case 'oldest':
            $orderBy = "ORDER BY sa.id ASC";
            break;
        default:
            $orderBy = "";
            $sort = 'recommended';
            break;
    }

    // total items (respecting price filters)
    $totalItemsRow = $db->run("SELECT COUNT(*) AS c FROM selling_accounts $where");
    $totalItems = (int) (($totalItemsRow[0]['c'] ?? 0));

    $totalPages = max(1, (int) ceil($totalItems / $itemsPerPage));
    if ($page > $totalPages) {
        $page = $totalPages;
        $offset = ($page - 1) * $itemsPerPage;
    }

    // dynamic price range (in cents) based on filters WITHOUT price restriction
    $rangeRow = $db->run("SELECT MIN(price) AS min_p, MAX(price) AS max_p FROM selling_accounts $whereNoPrice");
    $rangeMinCents = isset($rangeRow[0]['min_p']) ? (int)$rangeRow[0]['min_p'] : 0;
    $rangeMaxCents = isset($rangeRow[0]['max_p']) ? (int)$rangeRow[0]['max_p'] : 0;

    if ($rangeMaxCents <= 0) {
        $globalRange = $db->run("SELECT MIN(price) AS min_p, MAX(price) AS max_p FROM selling_accounts WHERE sold = 0 AND active = 1");
        $rangeMinCents = isset($globalRange[0]['min_p']) ? (int)$globalRange[0]['min_p'] : 0;
        $rangeMaxCents = isset($globalRange[0]['max_p']) ? (int)$globalRange[0]['max_p'] : 0;
    }

    // fetch page - with seller info
    // Qualify only complete, still-unqualified column names. The old str_replace()
    // also replaced substrings inside current_rank/rank_label/game_data and could
    // produce invalid SQL such as current_sa.rank as soon as full-text search was used.
    $whereJoin = $where;
    $accountWhereColumns = [
        'sold','active','title','slug','description','game','rank','rank_label','game_data',
        'delivery_type','server','current_rank','current_division','current_lp',
        'flex_rank','flex_division','flex_lp','previous_rank','previous_division','previous_lp',
        'level_up_method','level','blue_essence','riot_points','winrate_percent',
        'champions','skins','roles','champion_count','skin_count','val_agent_count','price','id'
    ];
    foreach ($accountWhereColumns as $column) {
        $whereJoin = preg_replace(
            '/(?<![a-zA-Z0-9_.])' . preg_quote($column, '/') . '(?![a-zA-Z0-9_])/',
            'sa.' . $column,
            $whereJoin
        );
    }


    // Game aware seller statistics for recommended sorting.
    // This keeps Valorant recommended from falling back to mostly newest listings when seller stats are tied.
    $recommendedGameWhere = ($filterGame === 'lol')
        ? "(game = 'lol' OR game = 'league-of-legends' OR game IS NULL OR game = '')"
        : "game = '" . esc($filterGame) . "'";

    // Fast account fetch: always paginate in SQL.
    // Old recommended mode loaded ALL matching rows, balanced them in PHP and then sliced.
    // That was the biggest CPU spike on mobile and during filter changes.
    $baseSelect = "SELECT
                    sa.id, sa.title, sa.slug, sa.server, sa.game,
                    sa.current_rank, sa.current_division,
                    sa.current_lp, sa.rank, sa.rank_label, sa.game_data,
                    sa.images, sa.description, sa.champions, sa.skins,
                    sa.champion_count, sa.skin_count, sa.val_agent_count,
                    sa.level, sa.blue_essence, sa.riot_points, sa.price, sa.delivery_type,
                    sa.created_at,
                    sa.seller_id,
                    s.username  AS seller_username,
                    s.slug      AS seller_slug,
                    s.icon      AS seller_icon,
                    s.rank      AS seller_rank,
                    s.rank_icon AS seller_rank_icon,
                    0           AS seller_rating,
                    s.is_active AS seller_is_active,
                    CASE WHEN ss_online.seller_id IS NULL THEN 0 ELSE 1 END AS seller_is_online,
                    COALESCE(ss_stats.total_sales, 0) AS seller_total_sales,
                    COALESCE(active_listings.seller_active_listings, 0) AS seller_active_listings
                  FROM selling_accounts sa
                  LEFT JOIN sellers s ON s.id = sa.seller_id
                  LEFT JOIN (
                    SELECT seller_id, 1 AS online
                    FROM seller_session_logs
                    WHERE created_at >= (NOW() - INTERVAL 5 MINUTE)
                    GROUP BY seller_id
                  ) ss_online ON ss_online.seller_id = s.id
                  LEFT JOIN seller_stats ss_stats ON ss_stats.seller_id = s.id
                  LEFT JOIN (
                    SELECT seller_id, COUNT(*) AS seller_active_listings
                    FROM selling_accounts
                    WHERE sold = 0 AND COALESCE(active, 1) = 1
                    GROUP BY seller_id
                  ) active_listings ON active_listings.seller_id = s.id
                  $whereJoin";

    if ($sort === 'recommended') {
            // Fair seller mix for every account shop:
            // 1) keep quality signals such as total sales, delivery and newest
            // 2) rotate through matching sellers so one large seller cannot fill a page
            // 3) fill remaining slots normally when a niche filter has too few sellers
            $maxPerSellerPerPage = 4;
            $poolLimit = min(max(160, $page * $itemsPerPage * 8), 800);

            $poolQuery = $baseSelect . "
                      ORDER BY
                        COALESCE(ss_stats.total_sales, 0) DESC,
                        COALESCE(active_listings.seller_active_listings, 0) ASC,
                        (sa.delivery_type = 'instant') DESC,
                        sa.created_at DESC,
                        sa.id DESC
                      LIMIT $poolLimit";
            $pool = $db->run($poolQuery) ?: [];

            $sellerBuckets = [];
            $sellerOrder = [];
            foreach ($pool as $row) {
                $sid = (string)($row['seller_id'] ?? '0');
                if (!isset($sellerBuckets[$sid])) {
                    $sellerBuckets[$sid] = [];
                    $sellerOrder[] = $sid;
                }
                $sellerBuckets[$sid][] = $row;
            }

            $balancedPages = [];
            for ($p = 1; $p <= $page; $p++) {
                $pageRows = [];
                $usedThisPage = [];

                while (count($pageRows) < $itemsPerPage) {
                    $progress = false;
                    foreach ($sellerOrder as $sid) {
                        if (count($pageRows) >= $itemsPerPage) break;
                        if (empty($sellerBuckets[$sid])) continue;
                        if (($usedThisPage[$sid] ?? 0) >= $maxPerSellerPerPage) continue;

                        $pageRows[] = array_shift($sellerBuckets[$sid]);
                        $usedThisPage[$sid] = ($usedThisPage[$sid] ?? 0) + 1;
                        $progress = true;
                    }
                    if (!$progress) break;
                }

                // Fill the page if fewer than 25 rows are available after seller caps.
                // This prevents empty spaces on niche filters where only one seller has matching listings.
                if (count($pageRows) < $itemsPerPage) {
                    foreach ($sellerOrder as $sid) {
                        while (count($pageRows) < $itemsPerPage && !empty($sellerBuckets[$sid])) {
                            $pageRows[] = array_shift($sellerBuckets[$sid]);
                        }
                        if (count($pageRows) >= $itemsPerPage) break;
                    }
                }

                $balancedPages[$p] = $pageRows;
            }

            $data = $balancedPages[$page] ?? [];
    } else {
        $query = $baseSelect . "
                  $orderBy
                  LIMIT $itemsPerPage OFFSET $offset";
        $data = $db->run($query) ?: [];
    }

    // Convert price to display currency (price stored as EUR cents)
    $session_currency = $_SESSION['currency'] ?? 'EUR';
    if ($session_currency === 'USD') {
        $rate = get_exchange_rate();
        foreach ($data as &$row) {
            $row['price'] = (int)round($row['price'] * $rate);
        }
        unset($row);
    }

    ob_start();
    view_file('website/components/accounts/account-cards', ['accounts' => $data, 'game' => $filterGame]);
    $html = ob_get_clean();

    echo json_encode([
        'html' => $html,
        'page' => $page,
        'itemsPerPage' => $itemsPerPage,
        'totalItems' => $totalItems,
        'totalPages' => $totalPages,
        'priceRange' => [
            // return EUR values for the slider UI
            'min' => (float) ($rangeMinCents / 100),
            'max' => (float) ($rangeMaxCents / 100),
        ],
        'sort' => $sort,
    ]);
    exit;
}


function item_shop_filters()
    {
        global $db;

        header('Content-Type: application/json; charset=utf-8');

        $this->ensure_selling_items_extra_schema();

        // Mögliche DB-Rohwerte pro kanonischem Key
        $aliasMap = [
            'skins'        => ['skins', 'skin'],
            'chests-keys'  => ['chests-keys', 'chest-key', 'chest', 'chests & keys'],
            'orbs'         => ['orbs', 'orb'],
            'capsules'     => ['capsules', 'capsule'],
            'event-pass'   => ['event-pass', 'pass', 'event pass'],
            'bundles'      => ['bundles', 'bundle'],
            'tft-item'     => ['tft-item', 'tft item', 'tft'],
            'mystery-gift' => ['mystery-gift', 'mystery gift', 'gifting'],
        ];

        // Key aus beliebigem Rohwert
        $toKey = function (string $raw) use ($aliasMap): string {
            $k = strtolower(trim($raw));
            foreach ($aliasMap as $key => $aliases) {
                if (in_array($k, $aliases, true)) return $key;
            }
            return preg_replace('/[^a-z0-9]+/', '-', $k);
        };

        // ── Conditions ────────────────────────────────────────────────────
        $conds    = ['si.active = 1'];
        $condsFull = ['si.active = 1'];   // ohne Preisfilter (für Slider-Range)

        $postedGameId = (int)($_POST['game_id'] ?? 0);
        $postedGameSlug = strtolower(trim((string)($_POST['game_slug'] ?? ($_POST['game'] ?? ''))));
        $gameSlug = $postedGameSlug;

        if ($postedGameId > 0 || $postedGameSlug !== '') {
            $gameId = $postedGameId;
            $gameSlug = $postedGameSlug;

            try {
                if ($gameId > 0 && $gameSlug === '') {
                    $gr = $db->run('SELECT slug FROM games WHERE id = ? LIMIT 1', $gameId) ?: [];
                    $gameSlug = strtolower(trim((string)($gr[0]['slug'] ?? '')));
                } elseif ($gameSlug !== '' && $gameId <= 0) {
                    if (function_exists('util_get_game_by_slug')) {
                        $g = util_get_game_by_slug($gameSlug);
                        $gameId = (int)($g['id'] ?? 0);
                    } else {
                        $gr = $db->run('SELECT id FROM games WHERE slug = ? LIMIT 1', $gameSlug) ?: [];
                        $gameId = (int)($gr[0]['id'] ?? 0);
                    }
                }
            } catch (\Throwable $e) {}

            $safeGame = esc($gameSlug);
            $slugAliases = [$safeGame];
            if (in_array($gameSlug, ['league-of-legends', 'lol', 'league'], true)) {
                $slugAliases = ['league-of-legends', 'lol', 'league'];
            }
            $slugSql = implode(',', array_map(static fn($v) => "'" . esc((string)$v) . "'", array_values(array_unique(array_filter($slugAliases)))));
            if ($gameId > 0 && $safeGame !== '') {
                $cl = "((COALESCE(si.game_id,0) = {$gameId}) OR (COALESCE(si.game_id,0) = 0 AND LOWER(TRIM(COALESCE(si.game,''))) IN ({$slugSql})))";
            } elseif ($gameId > 0) {
                $cl = "COALESCE(si.game_id,0) = {$gameId}";
            } else {
                $cl = "LOWER(TRIM(COALESCE(si.game,''))) IN ({$slugSql})";
            }
            $conds[] = $cl; $condsFull[] = $cl;
        }

        if (!empty($_POST['search'])) {
            $rawSearch = trim((string)$_POST['search']);
            $searchTerms = preg_split('/[\s\p{P}\p{S}]+/u', $rawSearch, -1, PREG_SPLIT_NO_EMPTY) ?: [];
            $searchTerms = array_slice(array_values(array_unique($searchTerms)), 0, 10);
            $itemSearchHaystack = "LOWER(CONCAT_WS(' ',
                COALESCE(si.title,''), COALESCE(si.slug,''), COALESCE(si.description,''),
                COALESCE(si.delivery_instructions,''), COALESCE(si.game,''),
                COALESCE(si.type,''), COALESCE(si.server,''), COALESCE(si.delivery_type,''),
                COALESCE(si.price_type,''), COALESCE(si.item_data,''),
                COALESCE(CAST(si.price AS CHAR),''), COALESCE(CAST(si.stock AS CHAR),''),
                COALESCE(CAST(si.requires_friendship_days AS CHAR),''),
                COALESCE(CAST(si.waiting_time_amount AS CHAR),''),
                COALESCE(si.waiting_time_unit,''),
                COALESCE(CAST(si.waiting_time_minutes AS CHAR),'')
            ))";
            foreach ($searchTerms as $term) {
                $safeTerm = esc(mb_strtolower((string)$term, 'UTF-8'));
                if ($safeTerm === '') continue;
                $cl = "{$itemSearchHaystack} LIKE '%{$safeTerm}%'";
                $conds[] = $cl;
                $condsFull[] = $cl;
            }
        }

        if (!empty($_POST['types']) && is_array($_POST['types'])) {
            $ors = [];
            foreach (array_filter(array_map('trim', $_POST['types'])) as $t) {
                $key = $toKey($t);
                $aliases = $aliasMap[$key] ?? [$key];
                $list = implode(',', array_map(fn($a) => "'" . esc($a) . "'", $aliases));
                $ors[] = "LOWER(TRIM(si.type)) IN ({$list})";
            }
            if ($ors) { $cl = '(' . implode(' OR ', $ors) . ')'; $conds[] = $cl; $condsFull[] = $cl; }
        }

        if (!empty($_POST['servers']) && is_array($_POST['servers'])) {
            $srvs = array_filter(array_map(fn($s) => esc(strtoupper(trim($s))), $_POST['servers']));
            if ($srvs) { $cl = "UPPER(si.server) IN ('" . implode("','", $srvs) . "')"; $conds[] = $cl; $condsFull[] = $cl; }
        }

        if (!empty($_POST['schema_filters']) && is_array($_POST['schema_filters'])) {
            foreach ($_POST['schema_filters'] as $filterKey => $filterValues) {
                $filterKey = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$filterKey);
                if ($filterKey === '' || in_array($filterKey, ['title','price','stock'], true)) continue;
                if (!is_array($filterValues)) $filterValues = [$filterValues];
                $vals = array_values(array_unique(array_filter(array_map(static fn($v) => strtolower(trim((string)$v)), $filterValues), static fn($v) => $v !== '')));
                if (!$vals) continue;
                $ors = [];
                foreach ($vals as $val) {
                    $safeVal = esc($val);
                    $jsonPath = '$."' . $filterKey . '"';
                    $ors[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '{$jsonPath}'))) = '{$safeVal}'";
                    if ($filterKey === 'platform') {
                        $ors[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.platform'))) = '{$safeVal}'";
                    }
                    if ($filterKey === 'game_version') {
                        $ors[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.game_version'))) = '{$safeVal}'";
                    }
                }
                if ($ors) { $cl = '(' . implode(' OR ', $ors) . ')'; $conds[] = $cl; $condsFull[] = $cl; }
            }
        }

        if (!empty($_POST['delivery_times']) && is_array($_POST['delivery_times'])) {
            $deliveryKeys = array_values(array_filter(array_map(static fn($v) => strtolower(trim((string)$v)), $_POST['delivery_times']), static fn($v) => $v !== ''));
            $deliveryKeys = array_values(array_unique($deliveryKeys));
            $ors = [];
            foreach ($deliveryKeys as $dk) {
                $safe = esc($dk);
                $ors[] = "LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.delivery_time'))) = '{$safe}'";
                if ($dk === 'more_than_24_hours') {
                    $ors[] = "(JSON_EXTRACT(si.item_data, '$.delivery_time') IS NULL AND COALESCE(si.requires_friendship_days, 1) > 1 AND COALESCE(si.requires_friendship_days, 1) < 7)";
                } elseif ($dk === 'after_7_days') {
                    $ors[] = "(COALESCE(si.requires_friendship_days, 1) >= 7 OR LOWER(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.delivery_time'))) IN ('after_7_days','seven_days','7_days','7_day_friendship'))";
                } elseif ($dk === 'within_6_24_hours') {
                    $ors[] = "(JSON_EXTRACT(si.item_data, '$.delivery_time') IS NULL AND COALESCE(si.requires_friendship_days, 1) <= 1)";
                }
            }
            if ($ors) { $cl = '(' . implode(' OR ', $ors) . ')'; $conds[] = $cl; $condsFull[] = $cl; }
        }

        $minEur = isset($_POST['price_min']) && $_POST['price_min'] !== '' ? (float)$_POST['price_min'] : null;
        $maxEur = isset($_POST['price_max']) && $_POST['price_max'] !== '' ? (float)$_POST['price_max'] : null;
        $minC = $minEur !== null ? (int)round($minEur * 100) : null;
        $maxC = $maxEur !== null ? (int)round($maxEur * 100) : null;
        if ($minC !== null && $maxC !== null) { if ($minC > $maxC) { $tmp=$minC;$minC=$maxC;$maxC=$tmp; } $conds[] = "si.price BETWEEN {$minC} AND {$maxC}"; }
        elseif ($minC !== null) { $conds[] = "si.price >= {$minC}"; }
        elseif ($maxC !== null) { $conds[] = "si.price <= {$maxC}"; }

        $where     = 'WHERE ' . implode(' AND ', $conds);
        $whereFull = 'WHERE ' . implode(' AND ', $condsFull);

        // ── Pagination ────────────────────────────────────────────────────
        $page  = max(1, (int)($_POST['page'] ?? 1));
        $limit = 20; // 5 rows × 4 cards
        $sort  = esc($_POST['sort'] ?? 'recommended');
        switch ($sort) {
            case 'price_asc':  $order = 'ORDER BY si.price ASC, si.id DESC'; break;
            case 'price_desc': $order = 'ORDER BY si.price DESC, si.id DESC'; break;
            case 'stock_desc': $order = 'ORDER BY si.stock DESC, si.id DESC'; break;
            case 'sold_desc':  $order = 'ORDER BY si.sold_count DESC, si.id DESC'; break;
            case 'waiting_asc':  $order = "ORDER BY COALESCE(si.waiting_time_minutes, CAST(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.waiting_time_minutes')) AS UNSIGNED), CASE WHEN COALESCE(si.requires_friendship_days,1) >= 7 THEN 10080 WHEN COALESCE(si.requires_friendship_days,1) > 1 THEN COALESCE(si.requires_friendship_days,1) * 1440 ELSE 1440 END) ASC, si.id DESC"; break;
            case 'waiting_desc': $order = "ORDER BY COALESCE(si.waiting_time_minutes, CAST(JSON_UNQUOTE(JSON_EXTRACT(si.item_data, '$.waiting_time_minutes')) AS UNSIGNED), CASE WHEN COALESCE(si.requires_friendship_days,1) >= 7 THEN 10080 WHEN COALESCE(si.requires_friendship_days,1) > 1 THEN COALESCE(si.requires_friendship_days,1) * 1440 ELSE 1440 END) DESC, si.id DESC"; break;
            case 'newest':     $order = 'ORDER BY si.id DESC'; break;
            case 'oldest':     $order = 'ORDER BY si.id ASC'; break;
            default:           $order = 'ORDER BY si.id DESC'; $sort = 'recommended'; break;
        }

        $totalRow   = $db->run("SELECT COUNT(*) AS c FROM selling_items si {$where}");
        $totalItems = (int)(($totalRow[0]['c'] ?? 0));
        $totalPages = max(1, (int)ceil($totalItems / $limit));
        if ($page > $totalPages) { $page = $totalPages; }
        $offset = ($page - 1) * $limit;

        // ── Slider-Preisspanne ────────────────────────────────────────────
        $rr = $db->run("SELECT MIN(si.price) AS mn, MAX(si.price) AS mx FROM selling_items si {$whereFull}");
        $rMin = isset($rr[0]['mn']) ? (int)$rr[0]['mn'] : 0;
        $rMax = isset($rr[0]['mx']) ? (int)$rr[0]['mx'] : 0;
        if ($rMax <= 0) {
            $gr = $db->run("SELECT MIN(price) AS mn, MAX(price) AS mx FROM selling_items WHERE active=1");
            $rMin = (int)($gr[0]['mn'] ?? 0); $rMax = (int)($gr[0]['mx'] ?? 0);
        }

        // ── Items holen (mit Seller) ───────────────────────────────────────
        $rows = $db->run("
            SELECT si.id, si.title, si.slug, si.type, si.server, si.item_data, si.requires_friendship_days,
                   si.game, si.game_id, g.slug AS game_slug, g.name AS game_name, g.icon AS game_icon,
                   si.images, si.description, si.price, si.stock, si.sold_count,
                   s.username AS seller_username, s.slug AS seller_slug,
                   s.icon AS seller_icon, s.is_active AS seller_is_active,
                    (
                        SELECT COUNT(*)
                        FROM seller_session_logs sslog
                        WHERE sslog.seller_id = s.id
                          AND sslog.created_at >= (NOW() - INTERVAL 5 MINUTE)
                    ) AS seller_is_online,
                   s.rank AS seller_rank,
                   s.rank_icon AS seller_rank_icon,
                   " . get_seller_total_sales_subquery('s') . " AS seller_total_sales
            FROM selling_items si
            LEFT JOIN sellers s ON s.id = si.seller_id
            LEFT JOIN games g ON g.id = si.game_id
            {$where} {$order}
            LIMIT {$limit} OFFSET {$offset}
        ");
        if (!is_array($rows)) $rows = [];

        // Währung
        $currency = $_SESSION['currency'] ?? 'EUR';
        if ($currency === 'USD') {
            $rate = get_exchange_rate();
            foreach ($rows as &$row) { $row['price'] = (int)round($row['price'] * $rate); }
            unset($row);
        }

        // ── HTML rendern ──────────────────────────────────────────────────
        ob_start();
        view_file('website/components/items/item-cards', ['items' => $rows, 'currentGameSlug' => $gameSlug]);
        $html = ob_get_clean();

        echo json_encode([
            'html'         => $html,
            'page'         => $page,
            'itemsPerPage' => $limit,
            'totalItems'   => $totalItems,
            'totalPages'   => $totalPages,
            'priceRange'   => ['min' => (float)($rMin / 100), 'max' => (float)($rMax / 100)],
            'sort'         => $sort,
        ]);
        exit;
    }


    public function prepare_lol_account_order()
    {
        $account_id = $_POST['account_id'];

        if (empty($account_id) || !is_numeric($account_id)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid account ID.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id]);

        if (!$account) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Account not found.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // price is stored as EUR cents in selling_accounts
        $price_eur_cents = (int)$account['price'];
        if ($_SESSION['currency'] == 'USD') {
            $price = (int)round($price_eur_cents * get_exchange_rate());
        } else {
            $price = $price_eur_cents;
        }

        $uuid = Uuid::uuid4();
        $uuid = $uuid->toString();

        db_add_row('invoices', function_exists('lb_referral_attach_snapshot_to_invoice_data')
            ? lb_referral_attach_snapshot_to_invoice_data([
            'uuid' => $uuid,
            'order_id' => $account_id,
            'order_type' => 'lol_account',
            'price' => $price,
            'price_eur' => $price_eur_cents, // already in cents, no *100
            'total_price' => $price,
            'currency' => $_SESSION['currency'] ?? 'EUR',
            'description' => strtoupper($account['server']) . ' - ' . $account['title'] . ' LoL account',
            'client_id' => CLIENT_ID ?? null
        
            ])
            : [
            'uuid' => $uuid,
            'order_id' => $account_id,
            'order_type' => 'lol_account',
            'price' => $price,
            'price_eur' => $price_eur_cents, // already in cents, no *100
            'total_price' => $price,
            'currency' => $_SESSION['currency'] ?? 'EUR',
            'description' => strtoupper($account['server']) . ' - ' . $account['title'] . ' LoL account',
            'client_id' => CLIENT_ID ?? null
        ]
        );

        echo json_encode(array(
            'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
        ));
    }

    public function admin_mark_unsold()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Admin access required.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? $_POST['id'] ?? 0);
        if ($account_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid account ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id]);
        if (empty($account)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Account not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if ((int)($account['sold'] ?? 0) !== 1) {
            echo json_encode([
                'sendToast' => ['type' => 'info', 'title' => 'Nothing to do', 'message' => 'Only sold accounts can be marked as unsold.'],
                'playSound' => 'info',
                'refreshPage' => true,
            ]);
            return;
        }

        $reverse = reverse_seller_account_payout(
            $account_id,
            ADMIN_DATA['username'] ?? 'Admin',
            'admin',
            defined('ADMIN_ID') ? (int)ADMIN_ID : null
        );

        if (empty($reverse['ok'])) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => $reverse['message'] ?? 'Failed to reverse seller payout.'],
                'playSound' => 'error',
            ]);
            return;
        }

        db_update_row('selling_accounts', ['id' => $account_id], [
            'sold' => 0,
            'active' => 1,
            'client_id' => null,
            'sold_at' => null,
            'seller_paid' => 0,
        ]);

        if (function_exists('log_admin_action') && defined('ADMIN_ID')) {
            log_admin_action((int)ADMIN_ID, 'Marked selling account #' . $account_id . ' as unsold');
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => 'Account marked as unsold and seller balance reversed.',
            ],
            'playSound' => 'success',
            'refreshPage' => true
        ]);
    }

    public function admin_mark_account_unsold()
    {
        return $this->admin_mark_unsold();
    }

    public function admin_marketplace_order_unsold()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]);
            return;
        }
        global $db;
        $kind = strtolower(trim((string)($_POST['kind'] ?? '')));
        $id = (int)($_POST['id'] ?? $_POST['purchase_id'] ?? 0);
        $map = [
            'item' => ['table'=>'selling_item_purchases','listing'=>'selling_items','fk'=>'item_id'],
            'topup' => ['table'=>'selling_topup_purchases','listing'=>'selling_topups','fk'=>'topup_id'],
            'digital_good' => ['table'=>'digital_good_purchases','listing'=>'digital_goods','fk'=>'item_id'],
        ];
        if ($id <= 0 || empty($map[$kind])) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Invalid order.']]);
            return;
        }
        $cfg = $map[$kind];
        $purchase = db_get_row($cfg['table'], ['id'=>$id], 1);
        if (empty($purchase)) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]);
            return;
        }
        if (in_array(strtoupper((string)($purchase['status'] ?? '')), ['CANCELLED','CANCELED','REFUNDED','UNSOLD'], true)) {
            echo json_encode(['sendToast'=>['type'=>'info','message'=>'This order is already unsold.'],'refreshPage'=>true]);
            return;
        }
        $sellerId = (int)($purchase['seller_id'] ?? 0);
        $seller = $sellerId > 0 ? db_get_row('sellers', ['id'=>$sellerId], 1) : null;
        if (!$seller) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Seller not found.']]);
            return;
        }
        $noteKey = 'Admin unsold ' . $kind . ' order #' . $id;
        $already = $db->row("SELECT id FROM seller_payments WHERE seller_id=? AND type='refund_reversal' AND note=? LIMIT 1", $sellerId, $noteKey);
        if ($already) {
            echo json_encode(['sendToast'=>['type'=>'info','message'=>'The seller payout was already reversed.'],'refreshPage'=>true]);
            return;
        }
        $total = (int)($purchase['price'] ?? $purchase['total_price'] ?? 0);
        $fee = ($seller['fee_percent'] ?? '') !== '' ? (float)$seller['fee_percent'] : 15.0;
        $amount = (int)($purchase['seller_earnings'] ?? $purchase['seller_payout'] ?? 0);
        if ($amount <= 0) $amount = (int)round($total * (1 - $fee / 100));
        $newBalance = (int)($seller['balance'] ?? 0) - $amount;
        $qty = max(1, (int)($purchase['quantity'] ?? 1));
        $listingId = (int)($purchase[$cfg['fk']] ?? 0);
        if ($kind === 'digital_good' && $listingId <= 0 && !empty($purchase['invoice_id'])) {
            $invoice = db_get_row('invoices', ['id'=>(int)$purchase['invoice_id']], 1);
            $listingId = (int)($invoice['order_id'] ?? 0);
        }

        try {
            $db->run("START TRANSACTION");
            $db->run("UPDATE sellers SET balance=? WHERE id=?", $newBalance, $sellerId);
            db_add_row('seller_payments', [
                'seller_id'=>$sellerId, 'type'=>'refund_reversal',
                'amount_cents'=>-$amount, 'note'=>$noteKey, 'balance_after'=>$newBalance,
            ]);
            $db->run("UPDATE {$cfg['table']} SET status='CANCELLED' WHERE id=?", $id);
            if ($listingId > 0) {
                $db->run("UPDATE {$cfg['listing']} SET stock=COALESCE(stock,0)+?, sold_count=GREATEST(0,COALESCE(sold_count,0)-?) WHERE id=?", $qty, $qty, $listingId);
            }
            $db->run("COMMIT");
        } catch (\Throwable $e) {
            try { $db->run("ROLLBACK"); } catch (\Throwable $ignored) {}
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'The order could not be marked as unsold.']]);
            return;
        }
        if (function_exists('sync_seller_stats')) sync_seller_stats($sellerId);
        if (function_exists('log_admin_action') && defined('ADMIN_ID')) log_admin_action((int)ADMIN_ID, 'Marked '.$kind.' order #'.$id.' as unsold and reversed seller payout');
        echo json_encode(['sendToast'=>['type'=>'success','title'=>'Unsold','message'=>'Order marked as unsold and seller payout reversed.'],'playSound'=>'success','refreshPage'=>true]);
    }

    public function admin_delete_unpaid_marketplace_order()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]);
            return;
        }
        $kind = strtolower(trim((string)($_POST['kind'] ?? '')));
        $id = (int)($_POST['id'] ?? $_POST['purchase_id'] ?? 0);
        $tables = [
            'item'=>'selling_item_purchases',
            'topup'=>'selling_topup_purchases',
            'digital_good'=>'digital_good_purchases',
        ];
        if ($id <= 0 || empty($tables[$kind])) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Invalid order.']]);
            return;
        }
        $row = db_get_row($tables[$kind], ['id'=>$id], 1);
        if (empty($row) || strtoupper((string)($row['status'] ?? '')) !== 'UNPAID') {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Only unpaid orders can be deleted.']]);
            return;
        }
        global $db;
        try {
            $db->run("START TRANSACTION");
            if ($kind === 'item') db_delete_rows('selling_item_purchase_details', ['purchase_id'=>$id]);
            db_delete_rows($tables[$kind], ['id'=>$id]);
            if (!empty($row['invoice_id'])) {
                $invoice = db_get_row('invoices', ['id'=>(int)$row['invoice_id']], 1);
                if ($invoice && strtoupper((string)($invoice['status'] ?? '')) === 'UNPAID') {
                    db_delete_rows('invoices', ['id'=>(int)$row['invoice_id']]);
                }
            }
            $db->run("COMMIT");
        } catch (\Throwable $e) {
            try { $db->run("ROLLBACK"); } catch (\Throwable $ignored) {}
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'The unpaid order could not be deleted.']]);
            return;
        }
        $chatPath = null;
        if ($kind === 'digital_good' && function_exists('dg_chat_path')) $chatPath = dg_chat_path($id);
        elseif ($kind === 'item') $chatPath = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_item_purchase_' . $id) . '.json';
        elseif ($kind === 'topup') $chatPath = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_topup_purchase_' . $id) . '.json';
        if ($chatPath && is_file($chatPath)) @unlink($chatPath);
        if (function_exists('log_admin_action') && defined('ADMIN_ID')) log_admin_action((int)ADMIN_ID, 'Deleted unpaid '.$kind.' order #'.$id);
        echo json_encode(['success'=>true,'sendToast'=>['type'=>'success','title'=>'Deleted','message'=>'Unpaid order deleted successfully.'],'playSound'=>'success']);
    }

    public function admin_unlist_marketplace_listing()
    {
        if (!$this->is_admin) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]);
            return;
        }
        $kind = strtolower(trim((string)($_POST['kind'] ?? '')));
        $id = (int)($_POST['id'] ?? 0);
        $active = isset($_POST['active']) && (int)$_POST['active'] === 1 ? 1 : 0;
        $tables = [
            'item' => 'selling_items',
            'topup' => 'selling_topups',
            'digital_good' => 'digital_goods',
        ];
        if ($id <= 0 || empty($tables[$kind])) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Invalid listing.']]);
            return;
        }
        $listing = db_get_row($tables[$kind], ['id'=>$id], 1);
        if (empty($listing)) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Listing not found.']]);
            return;
        }
        try {
            db_update_row($tables[$kind], ['id'=>$id], ['active'=>$active]);
        } catch (\Throwable $e) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Listing status could not be updated.']]);
            return;
        }
        if (function_exists('log_admin_action') && defined('ADMIN_ID')) {
            log_admin_action((int)ADMIN_ID, ($active ? 'Listed ' : 'Unlisted ').$kind.' listing #'.$id);
        }
        echo json_encode(['success'=>true,'sendToast'=>['type'=>'success','title'=>$active ? 'Listed' : 'Unlisted','message'=>$active ? 'Listing was listed successfully.' : 'Listing was unlisted successfully.'],'playSound'=>'success','refreshPage'=>true]);
    }

    public function admin_toggle_account_active()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? $_POST['id'] ?? 0);
        if ($account_id <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid account id.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id]);
        if (!$account) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Account not found.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $current_active = (int)($account['active'] ?? 1);
        $new_active = $current_active === 1 ? 0 : 1;

        $updated = db_update_row('selling_accounts', ['id' => $account_id], [
            'active' => $new_active,
