            log_admin_action((int)ADMIN_ID, ($new_active === 1 ? 'Re-listed' : 'Unlisted') . ' selling account #' . $account_id);
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => $new_active === 1 ? 'Account re-listed successfully.' : 'Account unlisted successfully.',
