    public function admin_refund_selling_account()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Admin access required.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? $_POST['id'] ?? 0);
        if ($account_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid account ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id]);
        if (empty($account)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Account not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if ((int)($account['sold'] ?? 0) === 2) {
            echo json_encode([
                'sendToast' => ['type' => 'info', 'title' => 'Already refunded', 'message' => 'This account is already marked as refunded.'],
                'playSound' => 'info',
                'refreshPage' => true,
            ]);
            return;
        }

        if ((int)($account['sold'] ?? 0) !== 1 && empty($account['sold_at'])) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Only sold accounts can be refunded.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $reverse = reverse_seller_account_payout(
            $account_id,
            ADMIN_DATA['username'] ?? 'Admin',
            'admin',
            defined('ADMIN_ID') ? (int)ADMIN_ID : null
        );

        if (empty($reverse['ok'])) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => $reverse['message'] ?? 'Failed to reverse seller payout.'],
                'playSound' => 'error',
            ]);
            return;
        }

        db_update_row('selling_accounts', ['id' => $account_id], [
            'sold' => 2,
            'active' => 0,
        ]);

        if (function_exists('log_admin_action') && defined('ADMIN_ID')) {
            log_admin_action((int)ADMIN_ID, 'Refunded selling account #' . $account_id);
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Refunded',
                'message' => 'Account marked as refunded and seller payout reversed.',
            ],
            'playSound' => 'success',
            'refreshPage' => true
        ]);
    }

