    public function load_accounts()
    {
        global $db;

        $page = $_POST['page'] ?? 1;
        $itemsPerPage = 15;
        $offset = ($page - 1) * $itemsPerPage;

        $query = "SELECT id,title,slug,server,current_rank,current_division,current_lp,images,description,champions,skins,level,blue_essence,riot_points,price,delivery_type FROM selling_accounts WHERE sold = 0 AND active = 1 ORDER BY created_at DESC LIMIT $itemsPerPage OFFSET $offset";

        $data = $db->run($query);

        view_file('main/components/account-shop-card', ['accounts' => $data]);
    }

    public function upload_quill_image()
    {
        $file = $_FILES['file'];

        if ($file['error'] !== UPLOAD_ERR_OK) {
            http_response_code(400);
            echo json_encode(['error' => 'Upload error.']);
            return;
        }

        if ($file['size'] > 5 * 1024 * 1024) {
            http_response_code(400);
            echo json_encode(['error' => 'File too large (max 5MB).']);
            return;
        }

        $finfo = finfo_open(FILEINFO_MIME_TYPE);
        $mime = finfo_file($finfo, $file['tmp_name']);
        finfo_close($finfo);

        $allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
        if (!in_array($mime, $allowed, true)) {
            http_response_code(400);
            echo json_encode(['error' => 'Unsupported file type.']);
            return;
        }

        $image_url = upload_image($file, 'blog-images');

        if ($image_url === false) {
            http_response_code(500);
            echo json_encode(['error' => 'Failed to save file.']);
            return;
        }

        echo json_encode([
            'url' => $image_url,
            'name' => $file['name'],
            'mime' => $mime,
            'size' => $file['size']
        ]);
    }

    public function add_language()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
        }

        $lang = esc($_POST['language']);
        $languages = util_language_list();
        $lang_name = $languages[$lang] ?? null;

        if (!$lang_name) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid language selected.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $file_path = dirname(__DIR__, 2) . '/public/assets/core/main/translations/' . $lang . '.json';
        if (!file_exists($file_path)) {
            $customData = [
                'name' => $lang_name,
                'translations' => []
            ];

            $result = file_put_contents(
                $file_path,
                json_encode($customData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)
            );

            if ($result === false) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Failed to create language file.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => 'Language added successfully.',
            ],
            'playSound' => 'success',
            'refreshPage' => true
        ]);
    }

