    public function edit_translation()
    {
        $lang = esc($_POST['language']);
        $string = trim($_POST['string']);
        $translation = trim($_POST['translation']);
        $original_string = isset($_POST['original_string'])
            ? trim($_POST['original_string'])
            : $string;
        if (empty($string) || empty($translation)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Key and value cannot be empty.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $file_path = dirname(__DIR__, 2) . "/public/assets/core/main/translations/{$lang}.json";
        if (!file_exists($file_path)) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Language file does not exist.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $data = json_decode(file_get_contents($file_path), true);
        if (!isset($data['translations'])) {
            $data['translations'] = [];
        }

        if ($original_string !== $string && isset($data['translations'][$original_string])) {
            unset($data['translations'][$original_string]);
        }

        $data['translations'][$string] = $translation;

        file_put_contents($file_path, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Success',
                'message' => 'Translation updated successfully.',
            ],
            'playSound' => 'success',
            'refreshPage' => true
        ]);
    }

    public function auth_unified_login()
    {
        $validator = new Validator;
        $validation = $validator->make($_POST, [
            'email' => 'required',
            'password' => 'required'
        ]);
        $validation->validate();

        if ($validation->fails()) {
            echo json_encode([
                'validationErrors' => $validation->errors()->firstOfAll()
            ]);
            return;
        }

        $login = esc($_POST['email']);
        $password = sha1($_POST['password']);
        $remember = isset($_POST['remember_me']) ? 1 : 0;
        $safeWorldcupRedirect = $this->get_safe_worldcup_redirect_url();

        $auth_map = [
            [
                'table' => 'clients',
                'cookie' => 'client_session_token',
                'redirect' => BASE_URL,
            ],
            [
                'table' => 'boosters',
                'cookie' => 'booster_session_token',
                'redirect' => BASE_URL . '/booster-area/dashboard',
            ],
            [
                'table' => 'sellers',
                'cookie' => 'seller_session_token',
                'redirect' => BASE_URL . '/seller-area/dashboard',
            ],
            [
                'table' => 'admins',
                'cookie' => 'admin_session_token',
                'redirect' => BASE_URL . '/admin-area/dashboard',
            ],
        ];

        $authtype = null;
        $redirectUrl = null;
        $matched = false;
        $matchedRoles = [];

        foreach ($auth_map as $auth) {

            $user_id = db_auth_login($login, $password, $auth['table']);
            if (!$user_id) {
                continue;
            }

            if ($auth['table'] === 'sellers') {
                $sellerData = db_get_row('sellers', [
                    'email' => $login,
                    'password' => $password,
                ]);

                if (
                    !$sellerData ||
                    !empty($sellerData['is_banned']) ||
                    ($sellerData['onboarding_status'] ?? 'pending') !== 'approved' ||
                    empty($sellerData['is_active'])
                ) {
                    continue;
                }
            }

            $token = db_auth_session_start($user_id, $auth['table']);
            if (!$token) {
                continue;
            }

            util_create_cookie($auth['cookie'], $token, $remember);

            if ($authtype === null) {
                $authtype = $auth['table'];
            }

            if ($redirectUrl === null) {
                $redirectUrl = $auth['redirect'];
            }

            $matched = true;
            $matchedRoles[] = $auth['table'];
        }

        if ($matched) {

            // Booster has priority if not banned
            if (in_array('boosters', $matchedRoles)) {

                $boosterData = db_get_row('boosters', ['email' => $login, 'password' => $password]);

                if ($boosterData && (int) $boosterData['is_banned'] === 0) {
                    echo json_encode([
                        'noNotif' => true,
                        'redirectUrl' => $safeWorldcupRedirect ?: BASE_URL . '/booster-area/dashboard',
                    ]);
                    return;
                }
            }

            // Seller has priority if approved and active
            if (in_array('sellers', $matchedRoles)) {

                $sellerData = db_get_row('sellers', ['email' => $login, 'password' => $password]);

                if (
                    $sellerData &&
                    empty($sellerData['is_banned']) &&
                    ($sellerData['onboarding_status'] ?? 'pending') === 'approved' &&
                    !empty($sellerData['is_active'])
                ) {
                    echo json_encode([
                        'noNotif' => true,
                        'redirectUrl' => $safeWorldcupRedirect ?: BASE_URL . '/seller-area/dashboard',
                    ]);
                    return;
                }
            }

            // Client fallback
            if (in_array('clients', $matchedRoles)) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'primary',
                        'title' => 'Success',
                        'message' => 'Logged in successfully ✅',
                    ],
                    'playSound' => 'success',
                    'redirectUrl' => $safeWorldcupRedirect,
                    'refreshPage' => $safeWorldcupRedirect ? false : true,
                ]);
                return;
            }

            // Admin fallback
            if (in_array('admins', $matchedRoles)) {
                echo json_encode([
                    'noNotif' => true,
                    'redirectUrl' => $safeWorldcupRedirect ?: BASE_URL . '/admin-area/dashboard',
                ]);
                return;
            }
        } else {
            echo json_encode([
                'validationErrors' => [
                    'email' => 'Invalid login credentials.'
                ]
            ]);
        }
    }


    private function client_calculate_server_change_surcharge(int $orderId, string $newServer): array
    {
        global $db;

        $newServer = strtolower(trim($newServer));
        $allowedServers = ['euw','eune','na','oce','br','lan','las','tr','ru','jp','kr','vn','ph','sg','th','tw'];
        $serverLabels = [
            'euw' => 'EUW', 'eune' => 'EUNE', 'na' => 'NA', 'oce' => 'OCE', 'br' => 'BR',
            'lan' => 'LAN', 'las' => 'LAS', 'tr' => 'TR', 'ru' => 'RU', 'jp' => 'JP',
            'kr' => 'KR', 'vn' => 'VN', 'ph' => 'PH', 'sg' => 'SG', 'th' => 'TH', 'tw' => 'TW'
        ];

        if ($orderId <= 0 || $newServer === '' || !in_array($newServer, $allowedServers, true)) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Invalid server.'];
        }

        $order = db_get_row('orders', ['id' => $orderId]);
        if (!$order || (int)($order['client_id'] ?? 0) !== (int)CLIENT_ID) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Order not found.'];
        }

        $options = db_get_row('order_options', ['order_id' => $orderId]);
        if (!$options) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Order options not found.'];
        }

        $currentServer = strtolower(trim((string)($options['server'] ?? ($order['server'] ?? ''))));
        if ($currentServer === '') {
            $currentServer = 'euw';
        }
        if ($newServer === $currentServer) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Please select a different server.'];
        }

        $form = db_get_row('boost_forms', ['id' => (int)($order['form_id'] ?? 0)]);
        if (!$form || empty($form['uuid'])) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Pricing form not found.'];
        }

        $pricingJson = get_pricing_json($form['uuid']);
        if (!is_array($pricingJson)) {
            return ['ok' => false, 'cents' => 0, 'message' => 'Pricing JSON not found.'];
        }

        $scaleRef = (int)($order['price_eur'] ?? $order['price'] ?? 0);
        $normalizeToCents = function ($raw) use ($scaleRef) {
            if ($raw === null || $raw === '') return 0;
            if (is_string($raw)) {
                $r = str_replace(',', '.', $raw);
                $cents = strpos($r, '.') !== false ? (int)round((float)$r * 100) : (int)$r;
            } elseif (is_float($raw)) {
                $cents = abs($raw - floor($raw)) > 0.00001 ? (int)round($raw * 100) : (int)$raw;
            } else {
                $cents = (int)$raw;
            }
            if ($scaleRef > 0 && $cents > $scaleRef * 20) {
                $cents = (int)round($cents / 100);
            }
            return max(0, $cents);
        };

        $base = (array)$options;
        $base['form_id'] = (int)($order['form_id'] ?? 0);
        $base['server'] = $currentServer;

        $newData = $base;
        $newData['server'] = $newServer;

        $calcCurrent = calculate_boost_pricing($pricingJson, $base);
        $calcNew = calculate_boost_pricing($pricingJson, $newData);

        $rawCurrent = $calcCurrent[2] ?? $calcCurrent['price_eur'] ?? $calcCurrent[0] ?? null;
        $rawNew = $calcNew[2] ?? $calcNew['price_eur'] ?? $calcNew[0] ?? null;

        $currentCents = $normalizeToCents($rawCurrent);
        $newCents = $normalizeToCents($rawNew);
        $diffCents = max(0, $newCents - $currentCents);

        return [
            'ok' => true,
            'cents' => $diffCents,
            'current_server' => $currentServer,
            'current_label' => $serverLabels[$currentServer] ?? strtoupper($currentServer),
            'new_server' => $newServer,
            'new_label' => $serverLabels[$newServer] ?? strtoupper($newServer),
            'current_price_cents' => $currentCents,
            'new_price_cents' => $newCents,
        ];
    }

    public function client_server_change_price()
    {
        global $is_client;

        if (!$is_client) {
            echo json_encode(['price' => 0, 'message' => 'Unauthorized action.']);
            return;
        }

        $orderId = (int)($_POST['order_id'] ?? 0);
        $server = (string)($_POST['server'] ?? '');
        $result = $this->client_calculate_server_change_surcharge($orderId, $server);

        echo json_encode([
            'price' => round(((int)($result['cents'] ?? 0)) / 100, 2),
            'ok' => !empty($result['ok']),
            'message' => $result['message'] ?? '',
            'current_server' => $result['current_server'] ?? '',
            'new_server' => $result['new_server'] ?? '',
        ]);
    }

    /**
     * Returns the surcharge (in EUR cents) for an LP Gain / Current LP correction
     * on a rank-boost order (form_id = 1).
     *
     * POST: order_id, lp_gain_range (optional), clp_range (optional)
     * Returns: { price: float }  — price in euros (already divided by 100)
     */
    public function client_lp_correction_price()
    {
        global $is_client, $db;

        if (!$is_client) {
            echo json_encode(['price' => 0]);
            return;
        }

        $orderId = (int)($_POST['order_id'] ?? 0);
        if ($orderId <= 0) {
            echo json_encode(['price' => 0]);
            return;
        }

        // Only for rank boost (form_id = 1)
        $order = db_get_row('orders', ['id' => $orderId]);
        if (!$order || (int)($order['form_id'] ?? 0) !== 1) {
            echo json_encode(['price' => 0]);
            return;
        }

        // Verify order belongs to this client
        $check = $db->row(
            "SELECT id FROM orders WHERE id = ? AND client_id = ? LIMIT 1",
            $orderId, (int)CLIENT_ID
        );
        if (!$check) {
            echo json_encode(['price' => 0]);
            return;
        }

        $options = db_get_row('order_options', ['order_id' => $orderId]);
        if (!$options) {
            echo json_encode(['price' => 0]);
            return;
        }

        $form = db_get_row('boost_forms', ['id' => (int)$order['form_id']]);
        if (!$form || empty($form['uuid'])) {
            echo json_encode(['price' => 0]);
            return;
        }

        $pricing_json = get_pricing_json($form['uuid']);
        if (!is_array($pricing_json)) {
            echo json_encode(['price' => 0]);
            return;
        }

        // Latest invoice for discount snapshot
        $invoice = null;
        $inv_rows = db_get_rows('invoices', [
            'order_type' => 'order',
            'order_id'   => $orderId,
            'order'      => 'id,desc',
            'limit'      => 1,
        ], true);
        if (!empty($inv_rows)) {
            $invoice = $inv_rows[0];
        }

        // Scale reference for heuristic cents normalization
        $scale_ref = (int)($order['price_eur'] ?? $order['price'] ?? 0);

        $normalize_to_cents = function ($raw) use ($scale_ref) {
            if ($raw === null || $raw === '') return 0;
            if (is_string($raw)) {
                $r = str_replace(',', '.', $raw);
                $cents = strpos($r, '.') !== false ? (int)round((float)$r * 100) : (int)$r;
            } elseif (is_float($raw)) {
                $cents = abs($raw - floor($raw)) > 0.00001 ? (int)round($raw * 100) : (int)$raw;
            } else {
                $cents = (int)$raw;
            }
            if ($scale_ref > 0 && $cents > $scale_ref * 20) $cents = (int)round($cents / 100);
            return $cents;
        };

        $apply_discount = function ($cents) use ($invoice) {
            if (!$invoice || empty($invoice['discount_id']) || !(int)($invoice['discount_amount'] ?? 0)) return $cents;
            $disc = db_get_row('discounts', ['id' => (int)$invoice['discount_id']]);
            if (!$disc) return $cents;
            if ((int)$disc['is_fixed'] === 1) {
                return max(0, $cents + (int)$invoice['discount_amount']);
            }
            $pct = min(1, abs((int)$invoice['discount_amount']) / max(1, (int)$invoice['price']));
            return (int)round($cents * (1 - $pct));
        };

        // Build base post_data from stored order_options
        $base = $options;
        $base['form_id'] = (int)$order['form_id'];

        // --- Calc price with BOOKED values (current) ---
        $calc_current = calculate_boost_pricing($pricing_json, $base);
        $raw_current  = $calc_current[2] ?? $calc_current['price_eur'] ?? $calc_current[0] ?? null;
        $cents_current = $apply_discount($normalize_to_cents($raw_current));

        // --- Calc price with NEW (lower) values ---
        $new_data = $base;
        $lpGainRange = trim((string)($_POST['lp_gain_range'] ?? ''));
        $clpRange    = trim((string)($_POST['clp_range']    ?? ''));

        if ($lpGainRange !== '') $new_data['lp_gain']  = $lpGainRange;
        if ($clpRange    !== '') $new_data['start_lp'] = $clpRange;

        $calc_new  = calculate_boost_pricing($pricing_json, $new_data);
        $raw_new   = $calc_new[2] ?? $calc_new['price_eur'] ?? $calc_new[0] ?? null;
        $cents_new = $apply_discount($normalize_to_cents($raw_new));

        // Surcharge = difference (new tier costs more because booster gets less LP per win)
        $diff_cents = max(0, $cents_new - $cents_current);

        // Fallback: if pricing engine returns same value (LP not in pricing JSON), use 25%
        if ($diff_cents === 0 && ($lpGainRange !== '' || $clpRange !== '')) {
            $diff_cents = (int)round($cents_current * 0.25);
        }

        echo json_encode(['price' => round($diff_cents / 100, 2)]);
    }

    public function client_addon_payment()
    {
        global $is_client, $db;

        if (!$is_client) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $orderId  = (int)($_POST['order_id'] ?? 0);
        $currency = (string)($_POST['currency'] ?? 'EUR');

        if (!empty($_POST['server_change_to'])) {
            $serverResult = $this->client_calculate_server_change_surcharge($orderId, (string)$_POST['server_change_to']);
            $addonTotal = (int)($serverResult['cents'] ?? 0);
            if (empty($serverResult['ok'])) {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'warning',
                        'title' => 'Server Change Unavailable',
                        'message' => $serverResult['message'] ?? 'This server change could not be priced automatically. Please open a support ticket.',
                    ],
                    'playSound' => 'error',
                ]);
                return;
            }

            if ($addonTotal <= 0) {
                $newServer = strtolower(trim((string)($serverResult['new_server'] ?? '')));
                $newLabel = trim((string)($serverResult['new_label'] ?? strtoupper($newServer)));
                $oldLabel = trim((string)($serverResult['current_label'] ?? ''));

                if ($newServer === '') {
                    echo json_encode([
                        'sendToast' => [
                            'type' => 'warning',
                            'title' => 'Server Change Unavailable',
                            'message' => 'This server change could not be processed automatically. Please open a support ticket.',
                        ],
                        'playSound' => 'error',
                    ]);
                    return;
                }

                db_update_row('order_options', ['order_id' => $orderId], ['server' => $newServer]);
                db_update_row('orders', ['id' => $orderId], ['server' => $newServer]);
                if (function_exists('lb_update_customer_snapshot_server')) {
                    lb_update_customer_snapshot_server($orderId, $newServer);
                }

                $serverChangeText = 'Server changed' . ($oldLabel !== '' ? (' from ' . $oldLabel) : '') . ' to ' . ($newLabel !== '' ? $newLabel : strtoupper($newServer));
                $chat_data = [
                    'message' => '✅ ' . $serverChangeText . '. No additional payment was required.',
                    'message_type' => 'text',
                ];
                $user = [
                    'id' => '999',
                    'username' => 'System',
                    'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png',
                ];
                if (function_exists('chat_insert_message')) {
                    chat_insert_message($orderId, $chat_data, $user, 'system');
                }

                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Server Changed',
                        'message' => $serverChangeText . '. No additional payment was required.',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
                return;
            }

            $addonNote = json_encode([
                'type' => 'server_change',
                'from' => $serverResult['current_server'] ?? '',
                'from_label' => $serverResult['current_label'] ?? '',
                'to' => $serverResult['new_server'] ?? '',
                'to_label' => $serverResult['new_label'] ?? '',
            ]);
            $addonKeys = ['server_change'];
        } elseif (!empty($_POST['custom_amount'])) {
            // Custom amount tab: value entered by user is already in euros (float)
            $addonTotal = (int) round(floatval(str_replace(',', '.', $_POST['custom_amount'])) * 100);
            $addonNote  = (string)($_POST['custom_reason'] ?? 'Custom add-on payment');
            $addonKeys  = [];
        } elseif (!empty($_POST['lp_correction_price'])) {
            // LP Correction tab: price is submitted in euros, calculated before checkout.
            $addonTotal = (int) round(floatval(str_replace(',', '.', $_POST['lp_correction_price'])) * 100);

            $lpGain = trim((string)($_POST['lp_correction_gain'] ?? ''));
            $clp    = trim((string)($_POST['lp_correction_clp'] ?? ''));

            $addonNote = json_encode([
                'type'       => 'lp_correction',
                'lp_gain'    => $lpGain,
                'current_lp' => $clp,
            ]);

            $addonKeys = ['lp_correction'];
        } else {
            // Extra Options tab: prices come in as cents (already computed server-side)
            $addonTotal = 0;
            $addonKeys  = [];
            $lpGainUpgrade = null; // track if a lp_gain upgrade was selected

            if (isset($_POST['addons']) && is_array($_POST['addons'])) {
                foreach ($_POST['addons'] as $key => $price) {
                    $addonTotal += (int) round(floatval($price));
                    // Detect lp_gain upgrade keys (format: lp_gain__30+)
                    if (strpos($key, 'lp_gain__') === 0) {
                        $lpGainUpgrade = substr($key, strlen('lp_gain__'));
                    }
                    $addonKeys[] = $key;
                }
            }

            $addonNote = json_encode($addonKeys);

            // If an LP gain upgrade was selected, apply it to the order immediately
            if ($lpGainUpgrade !== null && $orderId > 0) {
                // Verify the order belongs to this client before updating
                $orderCheck = $db->row(
                    "SELECT id FROM orders WHERE id = ? AND client_id = ? LIMIT 1",
                    $orderId, (int) CLIENT_ID
                );
                if ($orderCheck) {
                    $db->run(
                        "UPDATE orders SET lp_gain = ? WHERE id = ? LIMIT 1",
                        $lpGainUpgrade, $orderId
                    );
                    // Also update order_options if it exists
                    $optRow = $db->row(
                        "SELECT id FROM order_options WHERE order_id = ? LIMIT 1",
                        $orderId
                    );
                    if ($optRow) {
                        $db->run(
                            "UPDATE order_options SET lp_gain = ? WHERE order_id = ? LIMIT 1",
                            $lpGainUpgrade, $orderId
                        );
                    }
                }
            }
        }

        if ($addonTotal <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'warning',
                    'title' => 'Nothing Selected',
                    'message' => 'Please select at least one add-on or enter an amount.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $invoice_id = db_add_row('invoices', [
            'uuid'        => Uuid::uuid4()->toString(),
            'issuer'      => 'system',
            'order_type'  => 'addon',
            'order_id'    => $orderId,
            'note'        => $addonNote,
            'price_eur'   => $addonTotal,
            'price'       => $addonTotal,
            'total_price' => $addonTotal,
            'currency'    => $currency,
            'description' => 'Order #' . $orderId . ' - Add-ons',
            'client_id'   => CLIENT_ID,
            'status'      => 'UNPAID',
        ]);

        $processor = (string)($_POST['processor'] ?? 'stripe');
        if ($processor === 'coinbase') {
            echo json_encode([
                'sendToast' => [
                    'type' => 'warning',
                    'title' => 'Payment unavailable',
                    'message' => 'Coinbase is currently unavailable for add-on payments. Please use Stripe or PayPal.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        if (!in_array($processor, ['stripe', 'stripe_paypal'], true)) {
            $processor = 'stripe';
        }

        if ($invoice_id) {
            echo json_encode([
                'nextstep'     => true,
                'invoice_uuid' => db_get_row('invoices', ['id' => $invoice_id])['uuid'],
                'processor'    => $processor,
            ]);
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to create addon invoice.',
                ],
                'playSound' => 'error',
            ]);
        }
    }

    function client_submit_review()
    {
        global $is_client;

        if (!$is_client) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = intval($_POST['order_id']);
        $booster_id = intval($_POST['booster_id']);
        $score = $_POST['score'];
        $highlights = $_POST['highlights'] ?? [];
        $comments = $_POST['comments'] ?? '';

        $communication = intval($score['communication'] ?? 0);
        $skill = intval($score['skill'] ?? 0);
        $speed = intval($score['speed'] ?? 0);
        $overall = intval($score['overall'] ?? 0);

        $highlights_json = json_encode($highlights);

        $existing = db_get_row('reviews', [
            'order_id' => intval($_POST['order_id']),
        ]);

        if ($existing) {
            db_update_row('reviews', [
                'id' => $existing['id'],
            ], [
                'booster_id' => $booster_id,
                'communication' => $communication,
                'skill' => $skill,
                'speed' => $speed,
                'overall' => $overall,
                'highlights' => $highlights_json,
                'comments' => $comments,
                'client_edits' => 1,
                // Auto-approve reviews with 3+ stars overall; lower ratings stay
                // pending for manual admin review.
                'approved' => ($overall >= 3 ? 1 : 0)
            ]);

            recalculate_booster_rating((int)$existing['booster_id']);
            recalculate_booster_rating((int)$booster_id);

            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Review updated successfully. Thank you!',
                ],
                'playSound' => 'success',
                'refreshPage' => true,
            ]);
        } else {
            $review = db_add_row('reviews', [
                'order_id' => $order_id,
                'booster_id' => $booster_id,
                'communication' => $communication,
                'skill' => $skill,
                'speed' => $speed,
                'overall' => $overall,
                'highlights' => $highlights_json,
                'comments' => $comments,
                // Auto-approve reviews with 3+ stars overall; lower ratings stay
                // pending for manual admin review.
                'approved' => ($overall >= 3 ? 1 : 0),
            ]);

            if ($review) {
                recalculate_booster_rating((int)$booster_id);

                // Reviews with 3+ stars are auto-approved on insert, so they never pass
                // through admin_approve_review. Post them to the public review channel here.
                if ($overall >= 3) {
                    $this->lb_send_approved_review_discord_webhook([
                        'id' => $review,
                        'order_id' => $order_id,
                        'booster_id' => $booster_id,
                        'overall' => $overall,
                        'comments' => $comments,
                        'approved' => 0,
                    ]);
                }

                $webhookUrl = "https://discord.com/api/webhooks/1461094683995275358/xEVZbjb_LnUZGjIIwHzhlaQodNUill6dMEST3KHAA3bnS6big5aKA8LmoF1eMgK_xJtM";

                $data = [
                    "username" => "Order Reviews Notifier",
                    "avatar_url" => "https://lolboost.gg/public/uploads/icons/default1.png",
                    "content" => "<@&1295032857907171339>",
                    "allowed_mentions" => [
                        "roles" => [
                            "1083064775623327784",
                            "1295032857907171339"
                        ]
                    ],
                    "embeds" => [
                        [
                            "title" => "New Review Submitted!",
                            "color" => hexdec("5865F2"),
                            "fields" => [
                                [
                                    "name" => "Customer",
                                    "value" => CLIENT_DATA['username'] . " (ID: " . CLIENT_DATA['id'] . ")",
                                    "inline" => true
                                ],
                                [
                                    "name" => "Order ID",
                                    "value" => $order_id,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Action",
                                    "value" => "[🚀 View](" . BASE_URL . "/admin-area/reviews)",
                                    "inline" => false
                                ]
                            ],
                            "timestamp" => date("c")
                        ]
                    ]
                ];

                $ch = curl_init($webhookUrl);
                curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
                curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
                curl_setopt($ch, CURLOPT_HEADER, 0);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_TIMEOUT, 5);
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
        curl_exec($ch);
                curl_close($ch);

                echo json_encode([
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Success',
                        'message' => 'Review submitted successfully. Thank you!',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                ]);
            } else {
                echo json_encode([
                    'sendToast' => [
                        'type' => 'danger',
                        'title' => 'Error',
                        'message' => 'Failed to submit review. Please try again later.',
                    ],
                    'playSound' => 'error',
                ]);
            }
        }
    }

    // ============================================================
    // SELLER LIST – Ajax: Load & Filter
    // ============================================================

    function load_sellers()
    {
        global $db;

        $itemsPerPage = 12;
        $page         = (int)($_POST['page'] ?? 1);
        $offset       = ($page - 1) * $itemsPerPage;

        $sellers = $db->run(
            "SELECT s.id, s.username, s.slug, s.icon, s.banner, s.banner_position, s.is_active, s.rank,
                    COALESCE(ss.total_sales, 0) AS total_sold,
                    (SELECT COUNT(*) FROM selling_accounts WHERE seller_id = s.id AND sold = 0) AS active_listings,
                    (SELECT ROUND(AVG(rating), 1) FROM seller_reviews WHERE seller_id = s.id AND approved = 1) AS avg_rating,
                    (SELECT COUNT(*) FROM seller_reviews WHERE seller_id = s.id AND approved = 1) AS review_count
             FROM sellers s
             LEFT JOIN seller_stats ss ON ss.seller_id = s.id
             WHERE s.is_active = 1
             ORDER BY total_sold DESC
             LIMIT $itemsPerPage OFFSET $offset"
        ) ?: [];

        foreach ($sellers as $s) {
            view_file('website/components/sellers/seller-card', ['s' => $s]);
        }
    }

    function filter_sellers()
    {
        global $db;

        $name     = esc($_POST['name'] ?? '');
        $verified = (int)($_POST['verified'] ?? 0);

        $where = ["s.is_active = 1"];

        if ($name !== '') {
            $where[] = "s.username LIKE '%{$name}%'";
        }

        // verified filter is same as is_active=1, already covered above
        // but we keep the hook for future status levels

        $sellers = $db->run(
            "SELECT s.id, s.username, s.slug, s.icon, s.banner, s.banner_position, s.is_active, s.rank,
                    COALESCE(ss.total_sales, 0) AS total_sold,
                    (SELECT COUNT(*) FROM selling_accounts WHERE seller_id = s.id AND sold = 0) AS active_listings,
                    (SELECT ROUND(AVG(rating), 1) FROM seller_reviews WHERE seller_id = s.id AND approved = 1) AS avg_rating,
                    (SELECT COUNT(*) FROM seller_reviews WHERE seller_id = s.id AND approved = 1) AS review_count
             FROM sellers s
             LEFT JOIN seller_stats ss ON ss.seller_id = s.id
             WHERE " . implode(' AND ', $where) . "
             ORDER BY total_sold DESC"
        ) ?: [];

        if (empty($sellers)) {
            echo '<div class="sellers-empty">No sellers found.</div>';
            return;
        }

        foreach ($sellers as $s) {
            view_file('website/components/sellers/seller-card', ['s' => $s]);
        }
    }

