    function submit_seller_review()
    {
        global $is_client, $db;

        if (!$is_client) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'You must be logged in.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $seller_id   = intval($_POST['seller_id'] ?? 0);
        $purchase_id = intval($_POST['purchase_id'] ?? 0);
        $rating      = intval($_POST['rating'] ?? 0);
        $comment     = trim(strip_tags($_POST['comment'] ?? ''));

        if ($rating < 1 || $rating > 5) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select a rating between 1 and 5.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (strlen($comment) < 10) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please write at least 10 characters.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $purchase = $db->row(
            "SELECT id FROM selling_accounts
             WHERE id = ? AND seller_id = ? AND client_id = ? AND sold = 1
             LIMIT 1",
            $purchase_id, $seller_id, CLIENT_ID
        );

        // Also accept item purchases
        if (!$purchase) {
            $purchase = $db->row(
                "SELECT id FROM selling_item_purchases
                 WHERE seller_id = ? AND client_id = ?
                 LIMIT 1",
                $seller_id, CLIENT_ID
            );
        }

        if (!$purchase) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'You can only review sellers you have purchased from.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $existing = $db->row(
            "SELECT id FROM seller_reviews WHERE seller_id = ? AND client_id = ? LIMIT 1",
            $seller_id, CLIENT_ID
        );

        if ($existing) {
            echo json_encode([
                'sendToast' => ['type' => 'warning', 'title' => 'Already reviewed', 'message' => 'You have already submitted a review for this seller.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $inserted = db_add_row('seller_reviews', [
            'seller_id'   => $seller_id,
            'client_id'   => CLIENT_ID,
            'purchase_id' => $purchase_id,
            'rating'      => $rating,
            'comment'     => $comment,
            'approved'    => 1,
            'created_at'  => date('Y-m-d H:i:s'),
        ]);

        if (!$inserted) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Failed to submit review. Please try again.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (function_exists('lb_send_seller_review_webhook')) {
            // Same two channels the boosting reviews use: the internal #review-notif
            // and the community #reviews webhook.
            $reviewAdminWebhookUrl     = "https://discord.com/api/webhooks/1461094683995275358/xEVZbjb_LnUZGjIIwHzhlaQodNUill6dMEST3KHAA3bnS6big5aKA8LmoF1eMgK_xJtM";
            $reviewCommunityWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

            lb_send_seller_review_webhook([
                'id'          => (int)$inserted,
                'seller_id'   => $seller_id,
                'client_id'   => (int)CLIENT_ID,
                'purchase_id' => $purchase_id,
                'rating'      => $rating,
                'comment'     => $comment,
                'approved'    => 1,
            ], $reviewAdminWebhookUrl, $reviewCommunityWebhookUrl);
        }

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Review submitted!', 'message' => 'Thank you for your feedback!'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_hide_seller_review()
{
    global $db;

    try {
        if (!$this->is_admin) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);

        if ($id <= 0) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid review ID.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $row = $db->row("SELECT id, approved FROM seller_reviews WHERE id = ? LIMIT 1", $id);

        if (!$row) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Review not found.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $current = (int)($row['approved'] ?? 0);
        $newVal = $current === 1 ? 0 : 1;

        $db->run("UPDATE seller_reviews SET approved = ? WHERE id = ?", $newVal, $id);

        echo json_encode([
            'success' => true,
            'sendToast' => [
                'type' => 'success',
                'title' => $newVal ? 'Visible' : 'Hidden',
                'message' => $newVal ? 'Review is now visible.' : 'Review is now hidden.'
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    } catch (\Throwable $e) {
        echo json_encode([
            'success' => false,
            'sendToast' => [
                'type' => 'danger',
                'title' => 'PHP Error',
                'message' => $e->getMessage()
            ],
            'playSound' => 'error',
        ]);
    }
}

    public function admin_approve_seller_review()
    {
        return $this->admin_hide_seller_review();
    }

    public function admin_delete_seller_review()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);

        if ($id <= 0) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid review ID.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $exists = $db->single("SELECT id FROM seller_reviews WHERE id = ?", [$id]);

        if (!$exists) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Review not found.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $deleted = $db->run("DELETE FROM seller_reviews WHERE id = ?", $id);

        if ($deleted === false) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to delete review.'
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Deleted',
                'message' => 'Review deleted.'
            ],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

