    function admin_approve_review()
    {
        global $is_admin;

        if (!$is_admin) {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $review_id = intval($_POST['id']);
        $existing = db_get_row('reviews', ['id' => $review_id]);

        $review = db_update_row('reviews', [
            'id' => $review_id,
        ], [
            'approved' => 1
        ]);

        if ($review) {
            if ($existing) {
                recalculate_booster_rating((int)$existing['booster_id']);
            }

            // Send approved reviews to the official Discord community server.
            // Replace the placeholder below with your Discord webhook URL.
            // The webhook is only sent when a review changes from unapproved to approved.
            if ($existing && (int)($existing['approved'] ?? 0) !== 1) {
                $discordWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

                if (!empty($discordWebhookUrl) && $discordWebhookUrl !== "PASTE_DISCORD_COMMUNITY_REVIEW_WEBHOOK_HERE") {
                    $overallRating = max(1, min(5, (int)($existing['overall'] ?? 5)));
                    $stars = str_repeat("⭐", $overallRating);
                    $comment = trim((string)($existing['comments'] ?? ''));

                    if ($comment === '') {
                        $comment = 'No comment provided.';
                    } elseif (function_exists('mb_substr')) {
                        $comment = mb_substr($comment, 0, 900);
                    } else {
                        $comment = substr($comment, 0, 900);
                    }

                    $order = db_get_row('orders', ['id' => (int)($existing['order_id'] ?? 0)]);
                    $booster = !empty($existing['booster_id']) ? db_get_row('boosters', ['id' => (int)$existing['booster_id']]) : false;
                    $client = false;
                    $form = false;

                    if ($order) {
                        if (!empty($order['client_id'])) {
                            $client = db_get_row('clients', ['id' => (int)$order['client_id']]);
                        }
                        if (!$booster && !empty($order['booster_id'])) {
                            $booster = db_get_row('boosters', ['id' => (int)$order['booster_id']]);
                        }
                        if (!empty($order['form_id'])) {
                            $form = db_get_row('boost_forms', ['id' => (int)$order['form_id']]);
                        }
                    }

                    $clientName = 'Client';
                    if ($client && !empty($client['username'])) {
                        $clientName = (string)$client['username'];
                    } elseif ($order && !empty($order['client_id'])) {
                        $clientName = 'Client #' . (int)$order['client_id'];
                    }

                    // Privacy friendly display name for Discord, example: Guest#15543 becomes G*****3.
                    $maskDiscordName = function ($name) {
                        $name = trim((string)$name);
                        if ($name === '') {
                            return 'C*****t';
                        }

                        $clean = preg_replace('/\s+/', '', $name);
                        $chars = preg_split('//u', $clean, -1, PREG_SPLIT_NO_EMPTY);
                        if (!$chars || count($chars) < 2) {
                            return $chars ? ($chars[0] . '*****') : 'C*****t';
                        }

                        return $chars[0] . '*****' . $chars[count($chars) - 1];
                    };

                    $maskedClientName = $maskDiscordName($clientName);

                    $clientIcon = ($client && !empty($client['icon'])) ? (string)$client['icon'] : '';
                    if ($clientIcon !== '' && strpos($clientIcon, 'http') !== 0) {
                        $clientIcon = BASE_URL . '/' . ltrim($clientIcon, '/');
                    }
                    if ($clientIcon === '') {
                        $clientIcon = 'https://lolboost.gg/public/uploads/icons/default1.png';
                    }

                    // Use your official LOLBoost icon as Discord webhook sender avatar.
                    // Upload icon-bg.png to this path, or replace this URL with the final public image URL.
                    $lolboostWebhookIcon = 'https://lolboost.gg/public/assets/website/images/icon-bg.png';

                    $boosterName = ($booster && !empty($booster['username'])) ? (string)$booster['username'] : 'Booster';
                    $boosterValue = $boosterName;

                    $boosterIcon = ($booster && !empty($booster['icon'])) ? (string)$booster['icon'] : '';
                    if ($boosterIcon !== '' && strpos($boosterIcon, 'http') !== 0) {
                        $boosterIcon = BASE_URL . '/' . ltrim($boosterIcon, '/');
                    }

                    $serviceName = 'LOLBoost Service';
                    if ($form && !empty($form['name'])) {
                        $serviceName = (string)$form['name'];
                    } elseif ($form && !empty($form['type'])) {
                        $serviceName = (string)$form['type'];
                    }

                    $orderId = (int)($existing['order_id'] ?? 0);
                    $reviewUrl = 'https://lolboost.gg/reviews';
                    $trustpilotUrl = 'https://www.trustpilot.com/review/lolboost.gg';
                    $boosterProfileUrl = ($booster && !empty($booster['id'])) ? (BASE_URL . '/boosters/' . (int)$booster['id']) : $reviewUrl;

                    $payload = [
                        "username" => "lolboost.gg Reviews",
                        "avatar_url" => $lolboostWebhookIcon,
                        "content" => "⭐ Client " . $maskedClientName . " rated the service with **" . $overallRating . " stars!**",
                        "allowed_mentions" => [
                            "parse" => []
                        ],
                        "embeds" => [
                            [
                                "title" => "New Review Available!",
                                "description" => "*\"" . $comment . "\"*",
                                "url" => $reviewUrl,
                                "color" => hexdec("FFD700"),
                                "author" => [
                                    "name" => "Booster " . $boosterName,
                                    "icon_url" => $boosterIcon !== '' ? $boosterIcon : 'https://lolboost.gg/public/uploads/icons/default1.png'
                                ],
                                "fields" => [
                                    [
                                        "name" => "Score",
                                        "value" => $stars . " **" . $overallRating . "/5**",
                                        "inline" => true
                                    ],
                                    [
                                        "name" => "Client",
                                        "value" => $maskedClientName,
                                        "inline" => true
                                    ],
                                    [
                                        "name" => "Service",
                                        "value" => $serviceName,
                                        "inline" => true
                                    ],
                                    [
                                        "name" => "Booster",
                                        "value" => $boosterValue,
                                        "inline" => true
                                    ],
                                    [
                                        "name" => "Order",
                                        "value" => "#" . $orderId,
                                        "inline" => true
                                    ],
                                    [
                                        "name" => "Links",
                                        "value" => "[View Reviews](" . $reviewUrl . ") • [Trustpilot](" . $trustpilotUrl . ") • [Booster Profile](" . $boosterProfileUrl . ")",
                                        "inline" => false
                                    ]
                                ],
                                "footer" => [
                                    "text" => "LOLBoost.gg verified review"
                                ],
                                "timestamp" => date("c")
                            ]
                        ]
                    ];

                    $ch = curl_init($discordWebhookUrl);
                    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
                    curl_setopt($ch, CURLOPT_POST, 1);
                    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                    curl_setopt($ch, CURLOPT_TIMEOUT, 5);
                    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
                    curl_exec($ch);
                    curl_close($ch);
                }
            }

            echo json_encode([
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Review approved successfully.',
                ],
                'playSound' => 'success',
                'refreshPage' => true,
            ]);
        } else {
            echo json_encode([
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to approve review. Please try again later.',
                ],
                'playSound' => 'error',
            ]);
        }
    }

