    /**
     * Permanently delete a review (Admin only)
     * Expected POST: id
     */
    function admin_delete_review()
    {
        global $is_admin;

        if (!$is_admin) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Unauthorized action.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        $review_id = intval($_POST['id'] ?? 0);

        if ($review_id <= 0) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Invalid review id.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // Ensure review exists before deletion (optional but clearer errors)
        $existing = db_get_row('reviews', ['id' => $review_id]);
        if (!$existing) {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Review not found.',
                ],
                'playSound' => 'error',
            ]);
            return;
        }

        // Permanent delete
        $deleted = db_delete_rows('reviews', ['id' => $review_id]);

        if ($deleted) {
            recalculate_booster_rating((int)$existing['booster_id']);

            echo json_encode([
                'success' => true,
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Success',
                    'message' => 'Review deleted permanently.',
                ],
                'playSound' => 'success',
            ]);
        } else {
            echo json_encode([
                'success' => false,
                'sendToast' => [
                    'type' => 'danger',
                    'title' => 'Error',
                    'message' => 'Failed to delete review. Please try again later.',
                ],
                'playSound' => 'error',
            ]);
        }
    }


    private function bv_profile_page_numbers_ajax(int $current, int $total): array
    {
        $total = max(1, $total);
        $current = max(1, min($total, $current));
        if ($total <= 7) {
            return range(1, $total);
        }
        $pages = [1];
        $start = max(2, $current - 1);
        $end = min($total - 1, $current + 1);
        if ($start > 2) $pages[] = '...';
        for ($i = $start; $i <= $end; $i++) $pages[] = $i;
        if ($end < $total - 1) $pages[] = '...';
        $pages[] = $total;
        return $pages;
    }

    private function load_booster_reviews_full(int $booster_id, int $page, int $limit): array
    {
        global $db;
        $limit = max(1, min(20, $limit));
        $total = 0;
        try {
            $countRows = $db->run("SELECT COUNT(*) AS total FROM reviews WHERE booster_id = ? AND approved = 1", $booster_id) ?: [];
            $total = (int)($countRows[0]['total'] ?? 0);
        } catch (\Throwable $e) {
            $total = (int) db_get_row_count('reviews', ['booster_id' => $booster_id, 'approved' => 1]);
        }
        $totalPages = max(1, (int)ceil($total / $limit));
        $page = max(1, min($totalPages, $page));
        $offset = ($page - 1) * $limit;
        $reviews = db_get_rows('reviews', ['booster_id' => $booster_id, 'approved' => 1, 'order' => 'created_at,DESC', 'limit' => $limit, 'offset' => $offset]) ?: [];

        $order_ids = array_values(array_filter(array_map('intval', array_column($reviews, 'order_id'))));
        $orders_map = $opts_map = $accs_map = $notes_map = $forms_map = $clients_map = [];
        if (!empty($order_ids)) {
            $ph = implode(',', array_fill(0, count($order_ids), '?'));
            $orders_rows = $db->run("SELECT * FROM orders WHERE id IN ($ph)", ...$order_ids) ?: [];
            foreach ($orders_rows as $r) $orders_map[(int)$r['id']] = $r;
            $opts_rows = $db->run("SELECT * FROM order_options WHERE order_id IN ($ph)", ...$order_ids) ?: [];
            foreach ($opts_rows as $r) $opts_map[(int)$r['order_id']] = $r;
            $accs_rows = $db->run("SELECT * FROM order_accounts WHERE order_id IN ($ph)", ...$order_ids) ?: [];
            foreach ($accs_rows as $r) $accs_map[(int)$r['order_id']] = $r;
            $notes_rows = $db->run("SELECT * FROM order_notes WHERE order_id IN ($ph) AND type='client'", ...$order_ids) ?: [];
            foreach ($notes_rows as $r) $notes_map[(int)$r['order_id']][] = $r;
            $form_ids = array_unique(array_filter(array_map('intval', array_column($orders_rows, 'form_id'))));
            if (!empty($form_ids)) {
                $fph = implode(',', array_fill(0, count($form_ids), '?'));
                $forms_rows = $db->run("SELECT * FROM boost_forms WHERE id IN ($fph)", ...$form_ids) ?: [];
                foreach ($forms_rows as $r) $forms_map[(int)$r['id']] = $r;
            }
            $client_ids = array_unique(array_filter(array_map('intval', array_column($orders_rows, 'client_id'))));
            if (!empty($client_ids)) {
                $cph = implode(',', array_fill(0, count($client_ids), '?'));
                $clients_rows = $db->run("SELECT id, username FROM clients WHERE id IN ($cph)", ...$client_ids) ?: [];
                foreach ($clients_rows as $r) $clients_map[(int)$r['id']] = $r;
            }
        }

        foreach ($reviews as $key => $review) {
            $order = $orders_map[(int)($review['order_id'] ?? 0)] ?? null;
            if (empty($order)) { unset($reviews[$key]); continue; }
            $order_id = (int)$order['id'];
            $order_full = array_merge(
                $forms_map[(int)($order['form_id'] ?? 0)] ?? [],
                $opts_map[$order_id] ?? [],
                $accs_map[$order_id] ?? [],
                $order,
                ['notes' => $notes_map[$order_id] ?? []]
            );
            $client = $clients_map[(int)($order['client_id'] ?? 0)] ?? [];
            $order_full['client'] = $client['username'] ?? 'Guest';
            $reviews[$key] = array_merge($review, ['order' => $order_full]);
        }

        return ['reviews' => array_values($reviews), 'page' => $page, 'totalPages' => $totalPages, 'total' => $total, 'limit' => $limit];
    }

    private function render_booster_reviews_html(array $reviews): string
    {
        $html = '';
        foreach ($reviews as $review) {
            $order = $review['order'] ?? [];
            $date = !empty($order['created_at']) ? date('d.m.Y', strtotime($order['created_at'])) : '';
            $comment = trim((string)($review['comments'] ?? ''));
            $highlights = json_decode($review['highlights'] ?? '[]', true);
            $highlights = is_array($highlights) ? $highlights : [];
            $clientName = function_exists('mask_guest_style') ? mask_guest_style($order['client'] ?? 'Guest') : htmlspecialchars((string)($order['client'] ?? 'Guest'), ENT_QUOTES, 'UTF-8');

            $html .= '<div class="bv-review-card">';
            $html .= '<div class="bv-review-top"><div class="bv-review-left"><h5>';
            $html .= t('Customer') . ' ' . $clientName . ' <span>| ' . t('Order') . ' #' . (int)($order['id'] ?? 0) . '</span>';
            $html .= '</h5><small>';
            $html .= util_format_boost_overview($order['game'] ?? null, $order['type'] ?? null, $order);
            $html .= $date ? ' · ' . $date : '';
            $html .= '</small></div><div class="bv-review-stars">';
            $overall = (int)($review['overall'] ?? 0);
            for ($s = 1; $s <= 5; $s++) $html .= '<i class="fa-solid fa-star" style="opacity:' . ($s <= $overall ? '1' : '.2') . ';"></i>';
            $html .= '</div></div>';

            $html .= '<div class="bv-review-pills">';
            if (!empty($review['communication'])) $html .= '<span class="bv-review-pill"><i class="fa-solid fa-comments" style="font-size:.7em;"></i> Communication ' . (function_exists('process_stars') ? process_stars($review['communication']) : '') . '</span>';
            if (!empty($review['skill'])) $html .= '<span class="bv-review-pill"><i class="fa-solid fa-bolt" style="font-size:.7em;"></i> Skill ' . (function_exists('process_stars') ? process_stars($review['skill']) : '') . '</span>';
            if (!empty($review['speed'])) $html .= '<span class="bv-review-pill"><i class="fa-solid fa-gauge-high" style="font-size:.7em;"></i> Speed ' . (function_exists('process_stars') ? process_stars($review['speed']) : '') . '</span>';
            $html .= '</div>';

            if (!empty($highlights)) {
                $html .= '<div class="bv-review-tags">';
                foreach ($highlights as $highlight) $html .= '<span class="bv-review-tag">' . htmlspecialchars(ucwords(str_replace('-', ' ', (string)$highlight)), ENT_QUOTES, 'UTF-8') . '</span>';
                $html .= '</div>';
            }

            if ($comment !== '') {
                $html .= '<div class="bv-review-comment"><div class="bv-review-comment-label">Comment</div>';
                $html .= '<div class="bv-review-comment-text js-review-text">' . htmlspecialchars($comment, ENT_QUOTES, 'UTF-8') . '</div>';
                $html .= '<button class="bv-review-toggle js-review-toggle" hidden aria-expanded="false">Show more</button></div>';
            }
            $html .= '</div>';
        }
        return $html;
    }

    private function render_booster_reviews_pagination_html(int $booster_id, int $page, int $totalPages, int $limit): string
    {
        if ($totalPages <= 1) return '';
        $html = '<div class="bv-review-pagination" id="bvReviewPagination" data-booster="' . (int)$booster_id . '" data-page="' . (int)$page . '" data-total-pages="' . (int)$totalPages . '" data-per-page="' . (int)$limit . '">';
        $html .= $page > 1 ? '<button type="button" class="bv-page-arrow" data-review-page-btn="' . ($page - 1) . '" data-page-prev aria-label="Previous reviews page"><i class="fa-solid fa-chevron-left"></i></button>' : '<button type="button" class="bv-page-arrow is-disabled" disabled aria-disabled="true"><i class="fa-solid fa-chevron-left"></i></button>';
        foreach ($this->bv_profile_page_numbers_ajax($page, $totalPages) as $pageNo) {
            if ($pageNo === '...') $html .= '<span class="bv-page-ellipsis">…</span>';
            else { $p = (int)$pageNo; $html .= '<button type="button" class="bv-page-btn' . ($p === $page ? ' is-active' : '') . '" data-review-page-btn="' . $p . '">' . $p . '</button>'; }
        }
        $html .= $page < $totalPages ? '<button type="button" class="bv-page-arrow" data-review-page-btn="' . ($page + 1) . '" data-page-next aria-label="Next reviews page"><i class="fa-solid fa-chevron-right"></i></button>' : '<button type="button" class="bv-page-arrow is-disabled" disabled aria-disabled="true"><i class="fa-solid fa-chevron-right"></i></button>';
        $html .= '<span class="bv-page-status" id="bvReviewPageStatus">' . (int)$page . ' / ' . (int)$totalPages . '</span></div>';
        return $html;
    }

