    private function load_booster_orders_full(int $booster_id, int $page, int $limit): array
    {
        global $db;
        $limit = max(1, min(30, $limit));
        $total = 0;
        try {
            $countRows = $db->run("SELECT COUNT(*) AS total FROM orders WHERE booster_id = ? AND status IN ('COMPLETED','IN_PROGRESS')", $booster_id) ?: [];
            $total = (int)($countRows[0]['total'] ?? 0);
        } catch (\Throwable $e) { $total = 0; }
        $totalPages = max(1, (int)ceil($total / $limit));
        $page = max(1, min($totalPages, $page));
        $offset = ($page - 1) * $limit;
        $orders = $db->run("SELECT * FROM orders WHERE booster_id = ? AND status IN ('COMPLETED','IN_PROGRESS') ORDER BY created_at DESC LIMIT $offset, $limit", $booster_id) ?: [];
        $forms = db_get_rows('boost_forms', ['select' => 'id,type,name,icon,game']) ?: [];
        $forms = array_column($forms, null, 'id');
        foreach ($orders as $key => $order) {
            $order_opts = db_get_row('order_options', ['order_id' => $order['id'], 'select' => 'server,hours,start_tier,start_division,end_tier,end_division,start_lp,end_lp,matches,queue_type,is_duo,is_streaming,is_coaching,is_voice,is_hidden_duo,current_rank'], 1) ?: [];
            $orders[$key] = array_merge($order_opts, $forms[$order['form_id']] ?? [], $order);
        }
        return ['orders' => $orders, 'page' => $page, 'totalPages' => $totalPages, 'total' => $total, 'limit' => $limit];
    }

