    // Load more reviews for a booster (AJAX)
    public function load_more_booster_reviews()
    {
        $booster_id = intval($_POST['booster_id'] ?? 0);
        $offset = intval($_POST['offset'] ?? 0);
        $limit = intval($_POST['limit'] ?? 10);

        if ($booster_id <= 0) {
            echo json_encode(['html' => '', 'count' => 0]);
            return;
        }

        $reviews = db_get_rows('reviews', ['booster_id' => $booster_id, 'approved' => 1, 'order' => 'created_at,DESC', 'limit' => $limit, 'offset' => $offset]);

        // Batch-load all related data upfront — replaces N×6 individual queries with 6 total.
        $order_ids   = array_filter(array_column($reviews, 'order_id'));
        $orders_map = $opts_map = $accs_map = $notes_map = $forms_map = $clients_map = [];

        if (!empty($order_ids) && isset($db)) {
            $ph = implode(',', array_fill(0, count($order_ids), '?'));
            $orders_rows = $db->run("SELECT * FROM orders WHERE id IN ($ph)", ...$order_ids) ?: [];
            foreach ($orders_rows as $r) { $orders_map[(int)$r['id']] = $r; }

            $opts_rows = $db->run("SELECT * FROM order_options WHERE order_id IN ($ph)", ...$order_ids) ?: [];
            foreach ($opts_rows as $r) { $opts_map[(int)$r['order_id']] = $r; }

            $accs_rows = $db->run("SELECT * FROM order_accounts WHERE order_id IN ($ph)", ...$order_ids) ?: [];
            foreach ($accs_rows as $r) { $accs_map[(int)$r['order_id']] = $r; }

            $notes_rows = $db->run("SELECT * FROM order_notes WHERE order_id IN ($ph) AND type='client'", ...$order_ids) ?: [];
            foreach ($notes_rows as $r) { $notes_map[(int)$r['order_id']][] = $r; }

            $form_ids = array_unique(array_filter(array_column($orders_rows, 'form_id')));
            if (!empty($form_ids)) {
                $fph = implode(',', array_fill(0, count($form_ids), '?'));
                $forms_rows = $db->run("SELECT * FROM boost_forms WHERE id IN ($fph)", ...$form_ids) ?: [];
                foreach ($forms_rows as $r) { $forms_map[(int)$r['id']] = $r; }
            }

            $client_ids = array_unique(array_filter(array_column($orders_rows, 'client_id')));
            if (!empty($client_ids)) {
                $cph = implode(',', array_fill(0, count($client_ids), '?'));
                $clients_rows = $db->run("SELECT id, username FROM clients WHERE id IN ($cph)", ...$client_ids) ?: [];
                foreach ($clients_rows as $r) { $clients_map[(int)$r['id']] = $r; }
            }
        }

        $html = '';
        foreach ($reviews as $review) {
            $order = $orders_map[(int)($review['order_id'] ?? 0)] ?? null;
            if (empty($order))
                continue;
            $order_opts = $opts_map[(int)$order['id']] ?? [];
            $order_acc  = $accs_map[(int)$order['id']] ?? [];
            $form       = $forms_map[(int)$order['form_id']] ?? [];
            $notes      = $notes_map[(int)$order['id']] ?? [];
            $order_full = array_merge($form, $order_opts, $order_acc, $order, ['notes' => $notes]);
            $client     = $clients_map[(int)$order['client_id']] ?? [];
            $order_full = array_merge($order_full, ['client' => $client['username'] ?? '']);

            $createdAt = $order_full['created_at'] ?? null;
            $dateOnly = $createdAt ? date('d.m.Y', strtotime($createdAt)) : '';

            $html .= '<div class="review-row">';
            $html .= '<div class="review-top">';
            $html .= '<div class="left">';
            $html .= '<h5>' . t('Customer') . ' ' . mask_guest_style($order_full['client'] ?? '') . ' <span>| ' . t('Order') . ' #' . esc($order_full['id']) . '</span></h5>';
            $html .= '<small>' . util_format_boost_overview($order_full['game'], $order_full['type'], $order_full) . ($dateOnly ? ' • ' . $dateOnly : '') . '</small>';
            $html .= '</div>';
            $html .= '<div class="right">';
            $html .= '<span class="label">' . t('Overall') . '</span>';
            $html .= '<div class="stars">' . process_stars($review['overall']) . '</div>';
            $html .= '</div></div>';

            $html .= '<div class="review-pills">';
            $html .= '<span>' . t('Communication') . ' ' . process_stars($review['communication']) . '</span>';
            $html .= '<span>' . t('Skill') . ' ' . process_stars($review['skill']) . '</span>';
            $html .= '<span>' . t('Speed') . ' ' . process_stars($review['speed']) . '</span>';
            $html .= '<span>' . t('Overall') . ' ' . process_stars($review['overall']) . '</span>';
            $html .= '</div>';

            $html .= '<div class="review-tags">';
            foreach ((array) json_decode($review['highlights'] ?? '[]', true) as $highlight) {
                $html .= '<span>' . esc(ucwords(str_replace('-', ' ', $highlight))) . '</span>';
            }
            $html .= '</div>';

            $html .= '<div class="review-comment">';
            $html .= '<div class="review-comment-head"><span class="review-comment-title">' . t('Comment') . '</span><span class="review-comment-line"></span></div>';
            $html .= '<div class="review-comment-box"><p class="review-text">' . esc($review['comments']) . '</p></div>';
            $html .= '</div>';

            $html .= '</div>';
        }

        echo json_encode(['html' => $html, 'count' => count($reviews)]);
    }

    /* =========================
     * Booster Payout (Withdrawals)
     * ========================= */

    private function payout_base_fee_percent(string $method): float
    {
        // Accept legacy aliases too
        if ($method === 'bank' || $method === 'bank-transfer') {
            $method = 'bank_transfer';
        }

        switch ($method) {
            case 'bank_transfer': return 3.0;
            case 'crypto': return 5.0;
            default: return 0.0;
        }
    }

    private function payout_total_fee_percent(string $method, string $speed): float
    {
        if ($method === 'bank' || $method === 'bank-transfer') { $method = 'bank_transfer'; }
        $base = $this->payout_base_fee_percent($method);
        $extra = ($speed === 'fast') ? 5.0 : 0.0; // fast payout +5% on top
        return $base + $extra;
    }

    private function payout_calc(int $gross_cents, float $fee_percent): array
    {
        $fee = (int) round($gross_cents * ($fee_percent / 100));
        $net = max(0, $gross_cents - $fee);
        return [$fee, $net];
    }

    
    

    private function booster_payout_method_schema(?string $method = null): array
    {
        $schema = [
            'crypto' => [
                'label' => 'Crypto (USDC on Solana)',
                'description' => 'We use USDC on Solana for crypto payouts.',
                'fixed' => ['coin' => 'USDC', 'network' => 'Solana'],
                'fields' => [
                    ['name' => 'name', 'label' => 'Name', 'placeholder' => 'Your name', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'wallet', 'label' => 'Wallet / Exchange', 'placeholder' => 'e.g. Binance', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'country', 'label' => 'Country', 'placeholder' => 'e.g. Germany', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'address', 'label' => 'USDC (Solana) Address', 'placeholder' => 'Solana address', 'required' => true, 'col' => 'col-md-6'],
                ],
            ],
            'bank_transfer' => [
                'label' => 'Bank transfer',
                'description' => 'Use the same beneficiary details that belong to the IBAN.',
                'fixed' => [],
                'fields' => [
                    ['name' => 'beneficiary', 'label' => 'Beneficiary', 'placeholder' => 'Full name', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'iban', 'label' => 'IBAN', 'placeholder' => 'DE00 0000 0000 0000 0000 00', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'bic', 'label' => 'BIC', 'placeholder' => 'BANKDEFFXXX', 'required' => false, 'col' => 'col-md-6'],
                    ['name' => 'bank_name', 'label' => 'Bank name', 'placeholder' => 'Your bank', 'required' => false, 'col' => 'col-md-6'],
                    ['name' => 'country', 'label' => 'Country', 'placeholder' => 'e.g. Germany', 'required' => true, 'col' => 'col-md-6'],
                    ['name' => 'currency', 'label' => 'Currency', 'placeholder' => 'EUR', 'required' => true, 'col' => 'col-md-6', 'default' => 'EUR'],
                    ['name' => 'address', 'label' => 'Address', 'placeholder' => 'Your address', 'required' => true, 'col' => 'col-12'],
                ],
            ],
        ];
        return $method !== null ? ($schema[$method] ?? []) : $schema;
    }

    public function booster_get_payout_method_schema()
    {
        if (!$this->is_booster) return;

        $method = trim((string)($_POST['method'] ?? ''));
        if ($method === 'bank' || $method === 'bank-transfer') $method = 'bank_transfer';

        echo json_encode([
            'success' => true,
            'methods' => $this->booster_payout_method_schema(),
            'method' => $method,
            'schema' => $method !== '' ? $this->booster_payout_method_schema($method) : null,
        ], JSON_UNESCAPED_SLASHES);
    }

    public function booster_save_payout_method()
    {
        if (!$this->is_booster) return;
        global $db;

        $booster_id = (int) BOOSTER_ID;
        $method = trim((string)($_POST['method'] ?? ''));
        if ($method === 'bank' || $method === 'bank-transfer') $method = 'bank_transfer';

        $schema = $this->booster_payout_method_schema($method);
        if (empty($schema)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid payout method.']]);
            return;
        }

        $make_default = false;
        $make_default_provided = false;
        foreach (['make_default', 'is_default', 'set_default'] as $k) {
            if (isset($_POST[$k])) {
                $make_default_provided = true;
                $make_default = ((int)$_POST[$k] === 1);
                break;
            }
        }

        $label = '';
        $details = $schema['fixed'] ?? [];
        $missing = [];
        foreach (($schema['fields'] ?? []) as $field) {
            $name = (string)($field['name'] ?? '');
            if ($name === '') continue;
            $default = array_key_exists('default', $field) ? (string)$field['default'] : '';
            $value = esc($_POST[$name] ?? $default);
            $details[$name] = $value;
            if (!empty($field['required']) && trim($value) === '') {
                $missing[] = (string)($field['label'] ?? $name);
            }
        }

        if (!empty($missing)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => implode(', ', $missing) . ' required.'],
                'missing' => $missing,
            ], JSON_UNESCAPED_SLASHES);
            return;
        }

        $posted_id = (int)($_POST['id'] ?? 0);
        $target_id = 0;
        if ($posted_id > 0) {
            $row = $db->row("SELECT id FROM booster_payout_methods WHERE id=? AND booster_id=? LIMIT 1", $posted_id, $booster_id);
            if ($row) $target_id = (int)$row['id'];
        }
        if ($target_id <= 0) {
            $existing = $db->row("SELECT id FROM booster_payout_methods WHERE booster_id=? AND method=? ORDER BY id DESC LIMIT 1", $booster_id, $method);
            if (!empty($existing['id'])) $target_id = (int)$existing['id'];
        }

        $is_default_value = 0;
        if ($make_default_provided) {
            $is_default_value = $make_default ? 1 : 0;
            if ($make_default) $db->run("UPDATE booster_payout_methods SET is_default=0 WHERE booster_id=?", $booster_id);
        } elseif ($target_id > 0) {
            $cur = $db->row("SELECT is_default FROM booster_payout_methods WHERE id=? AND booster_id=? LIMIT 1", $target_id, $booster_id);
            $is_default_value = (int)($cur['is_default'] ?? 0);
        }

        $payload = [
            'booster_id' => $booster_id,
            'method' => $method,
            'label' => $label,
            'details' => json_encode($details, JSON_UNESCAPED_SLASHES),
            'is_default' => $is_default_value,
        ];

        if ($target_id > 0) {
            db_update_row('booster_payout_methods', ['id' => $target_id], $payload);
        } else {
            $new_id = db_add_row('booster_payout_methods', $payload);
            if (is_array($new_id)) $new_id = (int)($new_id['id'] ?? 0);
            $target_id = (int)$new_id;
        }

        if ($target_id > 0) $db->run("DELETE FROM booster_payout_methods WHERE booster_id=? AND method=? AND id<>?", $booster_id, $method, $target_id);

        $has_default = $db->row("SELECT id FROM booster_payout_methods WHERE booster_id=? AND is_default=1 LIMIT 1", $booster_id);
        if (!$has_default && $target_id > 0) $db->run("UPDATE booster_payout_methods SET is_default=1 WHERE id=? AND booster_id=?", $target_id, $booster_id);

        echo json_encode(['success' => true, 'sendToast'=>['type'=>'success','title'=>'Saved','message'=>'Payout method saved.'], 'refreshPage'=>true], JSON_UNESCAPED_SLASHES);
    }



    
    

    public function booster_delete_payout_method()
    {
        if (!$this->is_booster) return;
        global $db;

        $booster_id = (int) BOOSTER_ID;
        $id = (int)($_POST['id'] ?? 0);

        if ($id <= 0) {
                    echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Removed','message'=>'Payout method removed.'],
            'playSound'=>'success',
            'redirectUrl'=>(isset($_POST['redirectUrl']) && is_string($_POST['redirectUrl']) && strpos(trim($_POST['redirectUrl']), BASE_URL)===0)
                ? trim($_POST['redirectUrl'])
                : (BASE_URL . '/booster-area/payout')
        ]);
return;
        }

        $row = $db->row("SELECT id, is_default FROM booster_payout_methods WHERE id=? AND booster_id=? LIMIT 1", $id, $booster_id);
        if (!$row) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Method not found.']]);
            return;
        }

        $was_default = ((int)($row['is_default'] ?? 0) === 1);

        $db->run("DELETE FROM booster_payout_methods WHERE id=? AND booster_id=?", $id, $booster_id);

        if ($was_default) {
            $fallback = $db->row("SELECT id FROM booster_payout_methods WHERE booster_id=? ORDER BY id DESC LIMIT 1", $booster_id);
            if (!empty($fallback['id'])) {
                $db->run("UPDATE booster_payout_methods SET is_default=0 WHERE booster_id=?", $booster_id);
                $db->run("UPDATE booster_payout_methods SET is_default=1 WHERE id=? AND booster_id=?", (int)$fallback['id'], $booster_id);
            }
        } else {
            // still ensure one default exists
            $has_default = $db->row("SELECT id FROM booster_payout_methods WHERE booster_id=? AND is_default=1 LIMIT 1", $booster_id);
            if (!$has_default) {
                $fallback = $db->row("SELECT id FROM booster_payout_methods WHERE booster_id=? ORDER BY id DESC LIMIT 1", $booster_id);
                if (!empty($fallback['id'])) {
                    $db->run("UPDATE booster_payout_methods SET is_default=1 WHERE id=? AND booster_id=?", (int)$fallback['id'], $booster_id);
                }
            }
        }

        echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Removed','message'=>'Payout method removed.'],
            'refreshPage'=>true
        ]);
    }

public function booster_request_payout()
    {
        if (!$this->is_booster) return;
        global $db;

        $booster_id = (int) BOOSTER_ID;
        $method_id = (int)($_POST['payout_method_id'] ?? 0);
        $speed = esc($_POST['payout_speed'] ?? 'normal'); // normal|fast
        $note  = esc($_POST['note'] ?? '');

        if (!in_array($speed, ['normal','fast'], true)) $speed = 'normal';

        $method = $db->row("SELECT * FROM booster_payout_methods WHERE id=? AND booster_id=? LIMIT 1", $method_id, $booster_id);
        if (!$method) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Please select a payout method.']]);
            return;
        }

        // Current balance + insurance reserve (cents)
        $booster = $db->row("SELECT balance, insurance_required_amount FROM boosters WHERE id=? LIMIT 1", $booster_id);
        $balance = (int)($booster['balance'] ?? 0);

        // Permanent insurance reserve (Frozen)
        $insurance_required = isset($booster['insurance_required_amount']) && $booster['insurance_required_amount'] !== null && $booster['insurance_required_amount'] !== ''
            ? max(0, (int)$booster['insurance_required_amount'])
            : 2500; // default 25€

        $available = $balance - $insurance_required;
        if ($available < 0) $available = 0;

        $use_full = ((int)($_POST['full_balance'] ?? 0) === 1);

        // If "Full balance" is selected, we store a marker so admin processing can always pay the current AVAILABLE amount later.
        if ($use_full) {
            if (stripos($note, '[FULL_BALANCE]') === false) {
                $note = '[FULL_BALANCE]' . ($note !== '' ? (' ' . $note) : '');
            }
        }

        $gross_input = (int) util_format_price_db($_POST['amount'] ?? 0); // cents
        $gross = $use_full ? $available : $gross_input;

        // Cap to available (not total balance)
        if ($gross > $available) $gross = $available;

        if ($gross <= 0) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Invalid amount.']]);
            return;
        }

        // Minimum payout request: 25€ available
        if ($gross < 2500) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Minimum payout request is 25.00 EUR (available for payout).']]);
            return;
        }

        // If nothing is available due to insurance reserve
        if ($available < 2500) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Your available balance is below the minimum payout (25.00 EUR) due to the insurance reserve.']]);
            return;
        }

        // Only one open request at a time
        $open = $db->row("SELECT id FROM booster_payout_requests WHERE booster_id=? AND status IN ('pending','processing') LIMIT 1", $booster_id);
        if ($open) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'You already have an open payout request.']]);
            return;
        }

        $fee_percent = $this->payout_total_fee_percent((string)$method['method'], $speed);
        [$fee_amount, $net_amount] = $this->payout_calc($gross, $fee_percent);

        db_add_row('booster_payout_requests', [
            'booster_id' => $booster_id,
            'payout_method_id' => $method_id,
            'payout_speed' => $speed,
            'requested_amount' => $gross,
            'requested_fee_percent' => $fee_percent,
            'requested_fee_amount' => $fee_amount,
            'requested_net_amount' => $net_amount,
            'note' => $note,
            'status' => 'pending',
        ]);

        // Discord webhook notification (best-effort)
        $webhookUrl = "https://discord.com/api/webhooks/1469789889036947791/EJAh6OOm2iFLl9gSSp8twQjrjnvWyAWlllLhf8gYy45hTyXqVdfgvV-RC22FQXKVZUZX";
        if (!empty($webhookUrl) && strpos($webhookUrl, 'XXX/XXX') === false && function_exists('curl_init')) {
            try {
                $requestId = null;
                // Try to fetch last insert id if available
                if (isset($db) && method_exists($db, 'lastInsertId')) {
                    $requestId = $db->lastInsertId();
                }

                $speedLabel = strtoupper($speed);
                $methodLabel = strtoupper((string)($method['method'] ?? ''));
                if ($methodLabel === 'BANK_TRANSFER') $methodLabel = 'BANK';

                $requestedEur = number_format($gross / 100, 2) . " EUR";
                $feeEur = number_format($fee_amount / 100, 2) . " EUR (" . $fee_percent . "%)";
                $netEur = number_format($net_amount / 100, 2) . " EUR";

                // FAST = red highlight
                $embedColor = ($speed === 'fast') ? hexdec("ED4245") : hexdec("5865F2");

                $data = [
                    "username" => "Payout Requests",
                    "avatar_url" => "https://lolboost.gg/public/uploads/icons/default1.png",
                    "content" => "<@1522336111144341680>",
                    "allowed_mentions" => [
                        "users" => [
                            "1522336111144341680"
                        ]
                    ],
                    "embeds" => [
                        [
                            "title" => "💸 New Payout Request",
                            "color" => $embedColor,
                            "fields" => [
                                [
                                    "name" => "Booster",
                                    "value" => (BOOSTER_DATA['username'] ?? 'Booster') . " (ID: " . $booster_id . ")",
                                    "inline" => true
                                ],
                                [
                                    "name" => "Speed",
                                    "value" => $speedLabel,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Method",
                                    "value" => $methodLabel,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Requested",
                                    "value" => $requestedEur,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Fee",
                                    "value" => $feeEur,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Net",
                                    "value" => $netEur,
                                    "inline" => true
                                ],
                                [
                                    "name" => "Request ID",
                                    "value" => $requestId ? ("#" . $requestId) : "—",
                                    "inline" => false
                                ],
                                [
                                    "name" => "Action",
                                    "value" => "[🚀 View](" . BASE_URL . "/admin-area/payout-requests)",
                                    "inline" => false
                                ]
                            ],
                            "timestamp" => date("c")
                        ]
                    ]
                ];

                $ch = curl_init($webhookUrl);
                curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
                curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
                curl_setopt($ch, CURLOPT_HEADER, 0);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_TIMEOUT, 3);
                curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 2);
                curl_exec($ch);
                curl_close($ch);
            } catch (Exception $e) {
                // ignore webhook errors
            }
        }


        echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Requested','message'=>'Payout request submitted.'],
            'refreshPage'=>true
        ]);
    }

    public function booster_delete_payout_request()
    {
        if (!$this->is_booster) return;
        global $db;

        $booster_id = (int) BOOSTER_ID;
        $id = (int)($_POST['id'] ?? 0);

        if ($id <= 0) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Invalid request id.']]);
            return;
        }

        $row = $db->row("SELECT id, status FROM booster_payout_requests WHERE id=? AND booster_id=? LIMIT 1", $id, $booster_id);
        if (!$row) {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Request not found.']]);
            return;
        }

        if (($row['status'] ?? '') !== 'pending') {
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Only pending requests can be cancelled.']]);
            return;
        }

        $db->run("DELETE FROM booster_payout_requests WHERE id=? AND booster_id=?", $id, $booster_id);

        echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Cancelled','message'=>'Payout request cancelled.'],
            'refreshPage'=>true
        ]);
    }

    public function admin_get_payout_method_details()
    {
        if (!$this->is_admin) {
            $this->json(['success' => false, 'message' => 'Unauthorized.']);
        }

        $methodId = (int)($_POST['payout_method_id'] ?? 0);
        $boosterId = (int)($_POST['booster_id'] ?? 0);

        if ($methodId <= 0 || $boosterId <= 0) {
            $this->json(['success' => false, 'message' => 'Missing payout method id or booster id.']);
        }

        $stmt = $this->conn->prepare("SELECT id, booster_id, method_type, label, details, is_default, created_at FROM booster_payout_methods WHERE id = ? AND booster_id = ? LIMIT 1");
        $stmt->bind_param("ii", $methodId, $boosterId);
        $stmt->execute();
        $res = $stmt->get_result();
        $row = $res ? $res->fetch_assoc() : null;

        if (!$row) {
            $this->json(['success' => false, 'message' => 'Payout method not found.']);
        }

        $details = [];
        if (!empty($row['details'])) {
            $decoded = json_decode($row['details'], true);
            if (is_array($decoded)) {
                $details = $decoded;
            }
        }

        // Normalize common keys for the UI
        if ($row['method_type'] === 'bank_transfer') {
            $details = [
                'beneficiary_name' => $details['beneficiary_name'] ?? ($details['beneficiary'] ?? ($details['name'] ?? '')),
                'iban'             => $details['iban'] ?? ($details['account_number'] ?? ''),
                'swift_bic'        => $details['swift_bic'] ?? ($details['swift'] ?? ($details['bic'] ?? '')),
                'bank_name'        => $details['bank_name'] ?? ($details['bank'] ?? ''),
            ];
        } elseif ($row['method_type'] === 'crypto') {
            $details = [
                'coin'            => $details['coin'] ?? '',
                'network'         => $details['network'] ?? '',
                'name'            => $details['name'] ?? '',
                'wallet_exchange' => $details['wallet_exchange'] ?? ($details['wallet'] ?? ''),
                'wallet_address'  => $details['wallet_address'] ?? ($details['address'] ?? ''),
            ];
        }

        $this->json([
            'success' => true,
            'method' => [
                'id' => (int)$row['id'],
                'booster_id' => (int)$row['booster_id'],
                'method_type' => $row['method_type'],
                'label' => $row['label'],
                'is_default' => (int)$row['is_default'],
                'created_at' => $row['created_at'],
            ],
            'details' => $details
        ]);
    }






    /**
     * Send a payout status Discord DM to a booster, seller or E-Girl.
     * Best-effort only, payout processing must never fail because Discord is unavailable.
     */
    private function payout_send_discord_dm(string $discord_id, string $recipient_type, array $data): bool
    {
        $discord_id = trim($discord_id);
        if ($discord_id === '') return false;

        $status = strtolower((string)($data['status'] ?? ''));
        $completed = in_array($status, ['completed', 'paid', 'approved'], true);
        $title = $completed ? '✅ Payout Completed' : '❌ Payout Rejected';
        $color = $completed ? 0x22c55e : 0xef4444;

        $amount_cents = max(0, (int)($data['amount_cents'] ?? 0));
        $fee_cents = max(0, (int)($data['fee_cents'] ?? 0));
        $net_cents = max(0, (int)($data['net_cents'] ?? $amount_cents));
        $method = strtolower((string)($data['method'] ?? 'bank_transfer'));
        $method_label = $method === 'crypto' ? 'Crypto' : 'Bank Transfer';
        $request_id = (int)($data['request_id'] ?? 0);
        $balance_cents = array_key_exists('balance_cents', $data) ? (int)$data['balance_cents'] : null;
        $reason = trim((string)($data['reason'] ?? ''));
        $note = trim((string)($data['note'] ?? ''));

        $fields = [
            ['name' => 'Request', 'value' => '#' . $request_id, 'inline' => true],
            ['name' => 'Account Type', 'value' => ucfirst($recipient_type), 'inline' => true],
            ['name' => 'Method', 'value' => $method_label, 'inline' => true],
            ['name' => 'Requested Amount', 'value' => '€' . number_format($amount_cents / 100, 2, '.', ','), 'inline' => true],
        ];

        if ($completed) {
            if ($fee_cents > 0) {
                $fields[] = ['name' => 'Fee', 'value' => '€' . number_format($fee_cents / 100, 2, '.', ','), 'inline' => true];
            }
            $fields[] = ['name' => 'Paid Amount', 'value' => '€' . number_format($net_cents / 100, 2, '.', ','), 'inline' => true];
            if ($balance_cents !== null) {
                $fields[] = ['name' => 'Remaining Balance', 'value' => '€' . number_format(max(0, $balance_cents) / 100, 2, '.', ','), 'inline' => true];
            }
        } else {
            $fields[] = ['name' => 'Reason', 'value' => $reason !== '' ? $reason : 'The payout request was rejected by an administrator.', 'inline' => false];
        }

        if ($note !== '') {
            $fields[] = ['name' => 'Admin Note', 'value' => mb_substr($note, 0, 1000), 'inline' => false];
        }

        $payload = [
            'embeds' => [[
                'title' => $title,
                'description' => $completed
                    ? 'Your payout request has been processed successfully.'
                    : 'Your payout request could not be completed.',
                'color' => $color,
                'fields' => $fields,
                'footer' => ['text' => 'LoLBoost.gg Payouts'],
                'timestamp' => date('c'),
            ]],
        ];

        return $this->seller_chat_send_discord_dm_payload($discord_id, $payload);
    }


    public function admin_process_payout_request()
    {
        if (!$this->is_admin) return;
        global $db;

        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) return;

        $db->run("START TRANSACTION");
        $req = $db->row("SELECT * FROM booster_payout_requests WHERE id=? LIMIT 1 FOR UPDATE", $id);
        if (!$req || !in_array($req['status'], ['pending','processing'], true)) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Request not found or already handled.']]);
            return;
        }

        $booster_id = (int)$req['booster_id'];
        $booster = $db->row("SELECT * FROM boosters WHERE id=? LIMIT 1 FOR UPDATE", $booster_id);
        if (!$booster) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Booster not found.']]);
            return;
        }

        $method = $db->row("SELECT * FROM booster_payout_methods WHERE id=? LIMIT 1", (int)$req['payout_method_id']);
        $method_type = $method['method'] ?? 'bank_transfer';

        $current_balance = (int)($booster['balance'] ?? 0);
        $gross_requested = (int)($req['requested_amount'] ?? 0);

        // Permanent insurance reserve (Frozen)
        $insurance_required = isset($booster['insurance_required_amount']) && $booster['insurance_required_amount'] !== null && $booster['insurance_required_amount'] !== ''
            ? max(0, (int)$booster['insurance_required_amount'])
            : 2500; // default 25€

        $available = $current_balance - $insurance_required;
        if ($available < 0) $available = 0;

        // If request was created as "Full balance", always pay the current AVAILABLE amount at processing time.
        $is_full_balance = (strpos((string)($req['note'] ?? ''), '[FULL_BALANCE]') !== false);

        // auto-adjust to max possible amount if insufficient available
        $gross = $is_full_balance ? $available : min($gross_requested, $available);
if ($gross <= 0) {
            $db->run("UPDATE booster_payout_requests
                      SET status='rejected',
                          note=CONCAT(COALESCE(note,''),' | rejected: insufficient balance'),
                          processed_at=NOW(),
                          processed_by=?,
                          updated_at=NOW()
                      WHERE id=?",
                      ADMIN_ID, $id);

            $db->run("COMMIT");
            $this->payout_send_discord_dm((string)($booster['discord_id'] ?? ''), 'booster', [
                'status' => 'rejected',
                'request_id' => $id,
                'amount_cents' => $gross_requested,
                'method' => $method_type,
                'reason' => 'Insufficient available balance',
            ]);
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Rejected','message'=>'Insufficient balance.']]);
            return;
        }

        // Minimum payout request: 25€ available
        if ($gross < 2500) {
            $db->run("UPDATE booster_payout_requests
                      SET status='rejected',
                          note=CONCAT(COALESCE(note,''),' | rejected: below minimum payout'),
                          processed_at=NOW(),
                          processed_by=?,
                          updated_at=NOW()
                      WHERE id=?",
                      ADMIN_ID, $id);

            $db->run("COMMIT");
            $this->payout_send_discord_dm((string)($booster['discord_id'] ?? ''), 'booster', [
                'status' => 'rejected',
                'request_id' => $id,
                'amount_cents' => $gross,
                'method' => $method_type,
                'reason' => 'Amount is below the minimum payout of €25.00',
            ]);
            echo json_encode(['sendToast'=>['type'=>'danger','title'=>'Rejected','message'=>'Below minimum payout (25.00 EUR).']]);
            return;
        }

        $fee_percent = (float)($req['requested_fee_percent'] ?? 0);
        [$fee, $net] = $this->payout_calc($gross, $fee_percent);

        // Deduct booster balance
        $new_balance = $current_balance - $gross;
        db_update_row('boosters', ['id'=>$booster_id], ['balance'=>$new_balance]);

        // Create booster_payments record (negative = payout)
        db_insert_row('booster_payments', [
            'booster_id' => $booster_id,
            'amount' => -$gross,
            'note' => "Payout request #{$id} ({$method_type})",
            'type' => 'payout_request',
            'sender' => ADMIN_DATA['username'],
            'sender_type' => 'admin',
            'sender_id' => ADMIN_ID,
            'balance_update' => $current_balance . "|" . $new_balance,
        ]);

        // Update request as completed
        $db->run(
            "UPDATE booster_payout_requests
             SET status='completed',
                 requested_amount=?,
                 requested_fee_amount=?,
                 requested_net_amount=?,
                 processed_amount=?,
                 processed_fee_amount=?,
                 processed_net_amount=?,
                 processed_at=NOW(),
                 processed_by=?,
                 updated_at=NOW()
             WHERE id=?",
            $gross, $fee, $net, $gross, $fee, $net, ADMIN_ID, $id
        );
        $db->run("COMMIT");

        $this->payout_send_discord_dm((string)($booster['discord_id'] ?? ''), 'booster', [
            'status' => 'completed',
            'request_id' => $id,
            'amount_cents' => $gross,
            'fee_cents' => $fee,
            'net_cents' => $net,
            'method' => $method_type,
            'balance_cents' => $new_balance,
        ]);

        echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Completed','message'=>'Payout marked as completed.'],
            'refreshPage'=>true
        ]);
    }

    /**
     * Live amounts for pending FULL_BALANCE payout requests.
     * Used by the admin payout requests table to show up-to-date requested/fee/net.
     */
    public function admin_get_live_full_balance_amounts()
    {
        if (!$this->is_admin) return;
        global $db;

        $raw = (string)($_POST['ids'] ?? '[]');
        $ids = json_decode($raw, true);
        if (!is_array($ids)) $ids = [];
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids), fn($v) => $v > 0)));
        if (count($ids) > 100) $ids = array_slice($ids, 0, 100);
        if (!$ids) {
            echo json_encode(['success'=>true,'data'=>[]]);
            return;
        }

        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $rows = $db->rows(
            "SELECT id, booster_id, status, note, requested_fee_percent
             FROM booster_payout_requests
             WHERE id IN ($placeholders)",
            ...$ids
        );

        $out = [];
        foreach ($rows as $r) {
            $id = (int)$r['id'];
            $status = (string)($r['status'] ?? '');
            $note = (string)($r['note'] ?? '');
            if (!in_array($status, ['pending', 'processing'], true)) continue;
            if (stripos($note, '[FULL_BALANCE]') === false) continue;

            $boosterId = (int)($r['booster_id'] ?? 0);
            if ($boosterId <= 0) continue;

            $booster = $db->row(
                "SELECT balance, insurance_required_amount FROM boosters WHERE id=? LIMIT 1",
                $boosterId
            );
            if (!$booster) continue;

            $availableCents = function_exists('booster_available_for_payout_cents')
                ? (int)booster_available_for_payout_cents($booster)
                : max(0, (int)($booster['balance'] ?? 0) - 2500);

            $gross = round($availableCents / 100, 2);
            $feePercent = (float)($r['requested_fee_percent'] ?? 0);
            $fee = round(($gross * $feePercent) / 100.0, 2);
            $net = round($gross - $fee, 2);

            $out[$id] = [
                'gross' => $gross,
                'fee' => $fee,
                'net' => $net,
                'fee_percent' => $feePercent,
            ];
        }

        echo json_encode(['success'=>true,'data'=>$out]);
    }

    
    public function admin_reject_payout_request()
    {
        if (!$this->is_admin) return;
        global $db;

        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) return;

        $reason = trim((string)($_POST['reason'] ?? 'Rejected'));
        if ($reason === '') $reason = 'Rejected';

        // Load all data required for the Discord DM before changing the request.
        $req = $db->row(
            "SELECT r.*, b.discord_id, b.balance AS booster_balance,
                    pm.method_type, pm.method
             FROM booster_payout_requests r
             LEFT JOIN boosters b ON b.id = r.booster_id
             LEFT JOIN booster_payout_methods pm ON pm.id = r.payout_method_id
             WHERE r.id = ?
             LIMIT 1",
            $id
        );

        if (!$req || !in_array((string)($req['status'] ?? ''), ['pending', 'processing'], true)) {
            echo json_encode([
                'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Request not found or already handled.']
            ]);
            return;
        }

        $prev = (string)($req['note'] ?? '');
        $final_note = $prev;
        if ($final_note !== '' && $reason !== '') $final_note .= " | ";
        $final_note .= "Admin: " . $reason;

        $db->run("UPDATE booster_payout_requests
                  SET status='rejected',
                      note=?,
                      processed_at=NOW(),
                      processed_by=?,
                      updated_at=NOW()
                  WHERE id=? AND status IN ('pending','processing')",
                  $final_note, ADMIN_ID, $id);

        // Send only when the status update actually succeeded.
        $updated = $db->row("SELECT status FROM booster_payout_requests WHERE id=? LIMIT 1", $id);
        if (($updated['status'] ?? '') === 'rejected') {
            $method_type = (string)($req['method_type'] ?? ($req['method'] ?? 'bank_transfer'));
            $this->payout_send_discord_dm((string)($req['discord_id'] ?? ''), 'booster', [
                'status' => 'rejected',
                'request_id' => $id,
                'amount_cents' => (int)($req['requested_amount'] ?? 0),
                'method' => $method_type,
                'balance_cents' => (int)($req['booster_balance'] ?? 0),
                'reason' => $reason,
            ]);
        }

        echo json_encode([
            'sendToast'=>['type'=>'success','title'=>'Rejected','message'=>'Request rejected.'],
            'refreshPage'=>true
        ]);
    }





