    // Giveaway Admin Actions
    // =========================

    function admin_giveaway_save()
    {
        if (!$this->is_admin) return;

        $id = isset($_POST['id']) ? (int)$_POST['id'] : 0;
        $title = esc(trim((string)($_POST['title'] ?? '')));
        $description = esc(trim((string)($_POST['description'] ?? '')));
        $starts_at = esc(trim((string)($_POST['starts_at'] ?? '')));
        $ends_at = esc(trim((string)($_POST['ends_at'] ?? '')));
        $winners_count = max(1, (int)($_POST['winners_count'] ?? 1));
        $status = strtoupper(trim((string)($_POST['status'] ?? 'ACTIVE')));
        if (!in_array($status, ['DRAFT', 'ACTIVE', 'ENDED', 'DRAWN'], true)) {
            $status = 'ACTIVE';
        }

        // Basic validation
        if ($title === '' || $starts_at === '' || $ends_at === '') {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill title, start and end date.'],
                'playSound' => 'error'
            ]);
            exit;
        }

        $payload = [
            'title' => $title,
            'description' => $description,
            'starts_at' => $starts_at,
            'ends_at' => $ends_at,
            'winners_count' => $winners_count,
            'status' => $status,
            'updated_at' => date('Y-m-d H:i:s'),
        ];

        if ($id > 0) {
            $ok = db_update_row('giveaways', ['id' => $id], $payload);
        } else {
            $payload['created_at'] = date('Y-m-d H:i:s');
            $ok = db_add_row('giveaways', $payload);
            if ($ok) {
                // fetch new id
                $new = db_get_row('giveaways', ['select' => 'id', 'order' => 'id,DESC'], 1);
                $id = (int)($new['id'] ?? 0);
            }
        }

        // Save prizes
        if ($id > 0) {
            db_delete_rows('giveaway_prizes', ['giveaway_id' => $id]);
            $prizes = $_POST['prizes'] ?? [];
            if (is_array($prizes)) {
                $pos = 1;
                foreach ($prizes as $p) {
                    $name = esc(trim((string)($p['name'] ?? '')));
                    $desc = esc(trim((string)($p['description'] ?? '')));
                    if ($name === '') continue;
                    db_add_row('giveaway_prizes', [
                        'giveaway_id' => $id,
                        'position' => $pos,
                        'name' => $name,
                        'description' => $desc,
                        'created_at' => date('Y-m-d H:i:s'),
                    ]);
                    $pos++;
                }
            }
        }

        if ($ok) {
            log_admin_action(ADMIN_ID, 'Saved giveaway #' . $id);
            echo json_encode([
                'sendToast' => ['type' => 'success', 'title' => 'Success', 'message' => 'Giveaway saved.'],
                'playSound' => 'success',
                'redirect' => ADMN_URL . '/giveaways'
            ]);
        } else {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not save giveaway.'],
                'playSound' => 'error'
            ]);
        }
        exit;
    }


    function admin_giveaway_draw()
    {
        if (!$this->is_admin) return;

        $giveaway_id = (int)($_POST['id'] ?? 0);
        if ($giveaway_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid giveaway id'], 'playSound' => 'error']);
            exit;
        }

        if (!function_exists('giveaway_draw_winners')) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Giveaway system not installed'], 'playSound' => 'error']);
            exit;
        }

        $res = giveaway_draw_winners($giveaway_id);
        if (!empty($res['ok'])) {
            log_admin_action(ADMIN_ID, 'Drew winners for giveaway #' . $giveaway_id);
            echo json_encode([
                'sendToast' => ['type' => 'success', 'title' => 'Success', 'message' => 'Winners drawn successfully.'],
                'playSound' => 'success',
                'refreshPage' => true
            ]);
        } else {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => $res['error'] ?? 'Could not draw winners'],
                'playSound' => 'error'
            ]);
        }
        exit;
    }


    function admin_giveaway_adjust_tickets()
    {
        if (!$this->is_admin) return;

        $giveaway_id = (int)($_POST['giveaway_id'] ?? 0);
        $client_id = (int)($_POST['client_id'] ?? 0);
        $delta = (int)($_POST['delta'] ?? 0);
        $note = esc(trim((string)($_POST['note'] ?? '')));

        if ($giveaway_id <= 0 || $client_id <= 0 || $delta === 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid input'], 'playSound' => 'error']);
            exit;
        }

        $ok = false;
        if (function_exists('giveaway_admin_adjust_tickets')) {
            $ok = giveaway_admin_adjust_tickets($giveaway_id, $client_id, $delta, (int)ADMIN_ID, $note);
        }

        if ($ok) {
            log_admin_action(ADMIN_ID, 'Adjusted giveaway tickets: giveaway #' . $giveaway_id . ', client #' . $client_id . ', delta ' . $delta);
            echo json_encode([
                'sendToast' => ['type' => 'success', 'title' => 'Success', 'message' => 'Tickets updated.'],
                'playSound' => 'success',
                'refreshPage' => true
            ]);
        } else {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not update tickets.'],
                'playSound' => 'error'
            ]);
        }
        exit;
    }


    /* =========================
     * Notifications (Web)
     * ========================= */

    private function notif_get_scope(): array
    {
        if ($this->is_seller) {
            $seller_id = (int)(defined('SELLER_ID') ? SELLER_ID : (SELLER_DATA['id'] ?? 0));
            return ['recipient' => 'seller', 'recipient_id' => $seller_id];
        }
        if ($this->is_booster) return ['recipient' => 'booster', 'recipient_id' => (int)BOOSTER_ID];
        if ($this->is_client) return ['recipient' => 'client', 'recipient_id' => (int)CLIENT_ID];
        return ['recipient' => null, 'recipient_id' => null];
    }

    private function notif_resolve_scope_from_request(): array
    {
        $scope = isset($_POST['scope']) ? esc($_POST['scope']) : '';
        $ref = $_SERVER['HTTP_REFERER'] ?? '';

        // URL-based override takes highest priority — the area in the URL is definitive.
        if (strpos($ref, 'seller-area') !== false) {
            $scope = 'seller';
        } elseif (strpos($ref, 'booster-area') !== false) {
            $scope = 'booster';
        } elseif (empty($scope)) {
            // No scope posted and no URL hint — derive from authentication.
            // A user who has both client + booster accounts defaults to client
            // when no area URL is present (they're on the client-facing site).
            if ($this->is_seller) $scope = 'seller';
            elseif ($this->is_client) $scope = 'client';
            elseif ($this->is_booster) $scope = 'booster';
            else $scope = 'client';
        }

        // Honour the requested scope as long as the user is authenticated for it.
        // A user who is both client + booster can explicitly request either scope
        // by posting the correct scope value from their respective header.
        if ($scope === 'seller' && $this->is_seller) {
            $seller_id = (int)(defined('SELLER_ID') ? SELLER_ID : (SELLER_DATA['id'] ?? 0));
            return ['scope' => 'seller', 'recipient' => 'seller', 'recipient_id' => $seller_id];
        }

        if ($scope === 'client' && $this->is_client) {
            return ['scope' => 'client', 'recipient' => 'client', 'recipient_id' => (int)CLIENT_ID];
        }

        if ($scope === 'booster' && $this->is_booster) {
            return ['scope' => 'booster', 'recipient' => 'booster', 'recipient_id' => (int)BOOSTER_ID];
        }

        // Scope mismatch — fall back by authentication priority.
        if ($this->is_seller) {
            $seller_id = (int)(defined('SELLER_ID') ? SELLER_ID : (SELLER_DATA['id'] ?? 0));
            return ['scope' => 'seller', 'recipient' => 'seller', 'recipient_id' => $seller_id];
        }
        if ($this->is_client) {
            return ['scope' => 'client', 'recipient' => 'client', 'recipient_id' => (int)CLIENT_ID];
        }
        if ($this->is_booster) {
            return ['scope' => 'booster', 'recipient' => 'booster', 'recipient_id' => (int)BOOSTER_ID];
        }

        return ['scope' => '', 'recipient' => null, 'recipient_id' => 0];
    }

    private function notif_format_time($ts): string
    {
        if (!$ts) return '';
        $t = strtotime($ts);
        return $t ? date('d.m.Y H:i', $t) : '';
    }

    private function notif_decode_action_url($data): ?string
    {
        if (!is_array($data)) return null;
        if (!empty($data['action_url'])) {
            $url = $data['action_url'];
            // some rows store base64
            $decoded = base64_decode($url, true);
            if ($decoded !== false && preg_match('~^https?://~i', $decoded)) return $decoded;
            if (preg_match('~^https?://~i', $url)) return $url;
        }
        // fallback for order_id
        if (!empty($data['order_id'])) {
            $oid = (int)$data['order_id'];
            if ($oid > 0) {
                if ($this->is_seller && defined('BASE_URL')) return BASE_URL . '/seller-area/item-orders';
                if ($this->is_booster && defined('BSTR_URL')) return BSTR_URL . '/order/' . $oid;
                if ($this->is_client && defined('CLNT_URL')) return CLNT_URL . '/order/' . $oid;
                if (defined('BASE_URL')) return BASE_URL . '/order/' . $oid;
            }
        }
        return null;
    }

    private function notif_parse_amount_eur($v): ?float
{
    if ($v === null) return null;

    // Base64 decode if needed
    if (is_string($v)) {
        $s = trim($v);

        // common encoded cents like "MTAw" => "100"
        if (preg_match('/^[A-Za-z0-9+\/=]+$/', $s) && (strlen($s) % 4 === 0)) {
            $dec = base64_decode($s, true);
            if ($dec !== false) {
                $dec = trim((string)$dec);
                if (preg_match('/^-?\d+(\.\d+)?$/', $dec)) {
                    $s = $dec;
                }
            }
        }

        // normalize decimal separator
        $s = str_replace(['€', 'EUR'], ['', ''], $s);
        $s = str_replace(',', '.', $s);
        $v = trim($s);
    }

    if (!is_numeric($v)) return null;
    $num = (float)$v;

    // If integer -> assume cents
    if ((string)(int)$num === (string)$v || floor($num) == $num) {
        return $num / 100.0;
    }

    // already EUR
    return $num;
}

private function notif_fmt_eur($eur): string
{
    return number_format((float)$eur, 2, '.', '') . ' €';
}

private function notif_web_whitelist_for_recipient(string $recipient): array
{
    if ($recipient === 'seller') {
        return [
            'welcome_seller',
            'seller_payout_request',
            'seller_payout_paid',
            'seller_payout_rejected',
            'seller_account_sold',
            'seller_item_sold',
            'item_sold',
            'topup_sold',
            'digital_good_sold',
            'item_order_paid',
            'account_order_paid',
            'seller_chat_message',
            'seller_new_message',
            'seller_unread_message',
            'poke_seller',
        ];
    }

    if ($recipient === 'booster') {
        return [
            'ds_msg_notif_booster',   // booster-specific message notification
            'poke_booster',           // booster-specific poke
            'booster_money_added',
            'booster_money_fined',
            'booster_balance_withdrawn',
            'order_claimed',          // booster claimed an order (their own confirmation)
            'order_paused',
            'order_completed',
            'booster_request',
            'booster_ready_request',
            'booster_assigned',       // booster was assigned
            'booster_removed',        // booster was removed
            'booster_request_declined',
            'egirl_booking_paid',     // e-girl: new paid booking (service or GG-Girl)
        ];
    }

    // client — only client-facing notification types
    // IMPORTANT: do NOT include booster-specific types here (ds_msg_notif_booster,
    // poke_booster, booster_money_*, etc.) — those would show booster data to clients.
    return [
        'ds_msg_notif_client',        // client-specific message notification
        'poke_client',                // client-specific poke
        'order_claimed',              // client sees their order was claimed
        'order_paused',
        'order_completed',
        'order_ping',                 // admin/booster pinged the client
        'order_refunded',             // order was refunded
        'order_payout',               // payout-related client notification
        'booster_assigned',           // client sees a booster was assigned
        'booster_removed',            // client sees their booster was removed
        'booster_request_declined',
        'invoice_paid',
        'invoice_payment_succeeded',
        'client_custom_invoice',
        'egirl_session_started',
        'egirl_session_completed',
    ];
}
function notif_build_item(array $row): array
    {
        $type = (string)($row['type'] ?? '');
        $dataRaw = $row['data'] ?? null;
        $data = [];
        if (is_string($dataRaw) && $dataRaw !== '') {
            $decoded = json_decode($dataRaw, true);
            if (is_array($decoded)) $data = $decoded;
        }

        // defaults
        $item = [
            'id' => (int)($row['id'] ?? 0),
            'type' => $type,
            'icon' => 'fa-duotone fa-bell',
            'title' => 'Notification',
            'subtitle' => $type,
            'time' => $this->notif_format_time($row['created_at'] ?? null),
            'url' => $this->notif_decode_action_url($data),
            'is_seen' => (int)($row['is_seen'] ?? 0),
        ];

        // helper fields
        $clientName = $data['client_username'] ?? ($data['client'] ?? $data['customer'] ?? null);
        $boosterName = $data['booster_username'] ?? ($data['booster'] ?? null);

        switch ($type) {
            case 'ds_msg_notif_booster':
                $item['icon'] = 'fa-duotone fa-messages';
                $item['title'] = 'New message';
                if ($clientName) $item['subtitle'] = $clientName . ' sent you a message';
                else $item['subtitle'] = 'You received a new message';
                break;

            case 'ds_msg_notif_client':
                $item['icon'] = 'fa-duotone fa-messages';
                $item['title'] = 'New message';
                if ($boosterName) $item['subtitle'] = $boosterName . ' sent you a message';
                else $item['subtitle'] = 'You received a new message';
                break;

            case 'poke_booster':
                $item['icon'] = 'fa-duotone fa-hand-point-up';
                $item['title'] = 'You were poked';
                $item['subtitle'] = ($clientName ?: 'Customer') . ' poked you';
                break;

            case 'egirl_booking_paid':
                $item['icon'] = 'fa-duotone fa-calendar-heart';
                $item['title'] = 'New booking';

                $egOrderId = 0;
                if (!empty($data['order_id'])) {
                    $egDec = base64_decode((string)$data['order_id'], true);
                    $egOrderId = (int)($egDec !== false ? $egDec : $data['order_id']);
                }
                $egEgirlId = 0;
                if (!empty($data['egirl_id'])) {
                    $egDec = base64_decode((string)$data['egirl_id'], true);
                    $egEgirlId = (int)($egDec !== false ? $egDec : $data['egirl_id']);
                }
                $egServiceType = '';
                if (!empty($data['service_type'])) {
                    $egDec = base64_decode((string)$data['service_type'], true);
                    $egServiceType = trim((string)($egDec !== false ? $egDec : $data['service_type']));
                }
                $egTitle = '';
                if (!empty($data['service_title'])) {
                    $egDec = base64_decode((string)$data['service_title'], true);
                    $egTitle = trim((string)($egDec !== false ? $egDec : $data['service_title']));
                }
                if ($egTitle === '') {
                    $egTitle = ($egServiceType === 'lol_ggirl_boost') ? 'GG-Girl (League of Legends)' : 'E-Girl session';
                }

                // Unassigned pool bookings are claimed in the panel, assigned ones open directly.
                if ($egEgirlId > 0 && $egOrderId > 0 && defined('BSTR_URL')) {
                    $item['url'] = BSTR_URL . '/egirl-order/' . $egOrderId;
