    public function notifications_unread_today()
    {
        $scope = $this->notif_get_scope();
        if (!$scope['recipient']) {
            echo json_encode(['success' => false, 'error' => 'Not authenticated']);
            return;
        }

        global $db;

        $today = date('Y-m-d 00:00:00');
        $blocked = ['ds_msg_notif_booster_missed_log', 'notif_booster_missed_log'];
        $ph = implode(',', array_fill(0, count($blocked), '?'));

        $sql = "SELECT COUNT(*) AS c
                FROM notifications
                WHERE recipient = ? AND recipient_id = ?
                  AND is_web = 1
                  AND is_seen = 0
                  AND created_at >= ?
                  AND type NOT IN ($ph)";

        $params = array_merge(
            [$scope['recipient'], (int)$scope['recipient_id'], $today],
            $blocked
        );

        $rows = $db->run($sql, ...$params);
        $count = 0;
        if (is_array($rows) && !empty($rows)) {
            $count = (int)($rows[0]['c'] ?? 0);
        }

        echo json_encode(['success' => true, 'data' => ['unread_today' => $count]]);
    }

    public function notifications_unread_count()
    {
        global $db;

        $scopeInfo = $this->notif_resolve_scope_from_request();
        $scope = $scopeInfo['scope'];
        $recipient = $scopeInfo['recipient'];
        $recipient_id = (int)$scopeInfo['recipient_id'];

        if (!$recipient || $recipient_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Not authenticated']);
            return;
        }

        $whitelist = $this->notif_web_whitelist_for_recipient($recipient);

        $blacklist = [
            'ds_msg_notif_booster_missed_log',
            'notif_booster_missed_log',
            'ds_msg_notif_client_missed_log',
            'notif_client_missed_log',
        ];

        $wl = "'" . implode("','", array_map('esc', $whitelist)) . "'";
        $bl = "'" . implode("','", array_map('esc', $blacklist)) . "'";

        $countQuery = "
            SELECT COUNT(*) AS cnt
            FROM notifications
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND is_seen = 0
              AND type NOT IN ({$bl})
              AND type IN ({$wl})
        ";
        $cntRow = $db->run($countQuery);
        $unread = !empty($cntRow) ? (int)$cntRow[0]['cnt'] : 0;

        echo json_encode(['success' => true, 'unread' => $unread]);
    }

    public function notifications_list()
    {
        global $db;

        // Use the same resolver as unread/mark-read so seller-area cannot fall
        // back to booster/client notifications.
        $scopeInfo = $this->notif_resolve_scope_from_request();
        $scope = $scopeInfo['scope'];
        $recipient = $scopeInfo['recipient'];
        $recipient_id = (int)$scopeInfo['recipient_id'];

        if (!$recipient || $recipient_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Not authenticated']);
            return;
        }

        $since_id = isset($_POST['since_id']) ? (int)$_POST['since_id'] : 0;
        $limit = isset($_POST['limit']) ? (int)$_POST['limit'] : 30;
        if ($limit <= 0 || $limit > 100) $limit = 30;

        $whitelist = $this->notif_web_whitelist_for_recipient($recipient);

        $blacklist = [
            'ds_msg_notif_booster_missed_log',
            'notif_booster_missed_log',
            'ds_msg_notif_client_missed_log',
            'notif_client_missed_log',
        ];

        $wl = "'" . implode("','", array_map('esc', $whitelist)) . "'";
        $bl = "'" . implode("','", array_map('esc', $blacklist)) . "'";

        // Filter strictly by type whitelist AND recipient/recipient_id.
        // This prevents cross-contamination between client/booster/seller notifications.
        // We do NOT filter by is_web here — some valid notification types are inserted
        // without is_web=1 (e.g. order_claimed, egirl_session_*) but are still relevant.
        // The whitelist per recipient already ensures only the right types are shown.
        $query = "
            SELECT id, type, data, is_seen, created_at
            FROM notifications
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND id > {$since_id}
              AND is_seen = 0
              AND type NOT IN ({$bl})
              AND type IN ({$wl})
            ORDER BY id DESC
            LIMIT {$limit}
        ";

        $items = $db->run($query) ?? [];

        $countQuery = "
            SELECT COUNT(*) AS cnt
            FROM notifications
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND is_seen = 0
              AND type NOT IN ({$bl})
              AND type IN ({$wl})
        ";
        $cntRow = $db->run($countQuery);
        $unread = !empty($cntRow) ? (int)$cntRow[0]['cnt'] : 0;

        $maxQuery = "
            SELECT MAX(id) AS max_id
            FROM notifications
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND type NOT IN ({$bl})
              AND type IN ({$wl})
        ";
        $maxRow = $db->run($maxQuery);
        $max_id = !empty($maxRow) ? (int)$maxRow[0]['max_id'] : 0;

        echo json_encode([
            'success' => true,
            'scope' => $scope,
            'unread' => $unread,
            'max_id' => $max_id,
            'items' => $items,
        ]);
    }

    public function notifications_mark_read()
    {
        global $db;

        $scopeInfo = $this->notif_resolve_scope_from_request();
        $scope = $scopeInfo['scope'];
        $recipient = $scopeInfo['recipient'];
        $recipient_id = (int)$scopeInfo['recipient_id'];

        if (!$recipient || $recipient_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Not authenticated']);
            return;
        }

        $id = isset($_POST['id']) ? (int)$_POST['id'] : 0;
        if ($id <= 0) {
            echo json_encode(['success' => false]);
            return;
        }

        $db->run("
            UPDATE notifications
            SET is_seen = 1
            WHERE id = {$id}
              AND recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
        ");

        echo json_encode(['success' => true]);
    }

    public function notifications_mark_all_read()
    {
        global $db;

        $scopeInfo = $this->notif_resolve_scope_from_request();
        $scope = $scopeInfo['scope'];
        $recipient = $scopeInfo['recipient'];
        $recipient_id = (int)$scopeInfo['recipient_id'];

        if (!$recipient || $recipient_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Not authenticated']);
            return;
        }

        $blacklist = [
            'ds_msg_notif_booster_missed_log',
            'notif_booster_missed_log',
            'ds_msg_notif_client_missed_log',
            'notif_client_missed_log',
        ];
        $bl = "'" . implode("','", array_map('esc', $blacklist)) . "'";

        $db->run("
            UPDATE notifications
            SET is_seen = 1
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND is_seen = 0
              AND type NOT IN ({$bl})
        ");

        $maxRow = $db->run("
            SELECT MAX(id) AS max_id
            FROM notifications
            WHERE recipient = '{$recipient}'
              AND recipient_id = {$recipient_id}
              AND type NOT IN ({$bl})
        ");
        $max_id = !empty($maxRow) ? (int)$maxRow[0]['max_id'] : 0;

        echo json_encode(['success' => true, 'max_id' => $max_id]);
    }

