    private function seller_account_server_from_post(string $game, array $post, ?string $fallback = null): string
    {
        $game = strtolower(trim($game));
        $game = function_exists('util_account_normalize_game_slug') ? util_account_normalize_game_slug($game) : $game;

        $aliases = [
            'eu-west' => 'euw', 'eu west' => 'euw', 'euwest' => 'euw', 'euw' => 'euw',
            'eu-nordic-east' => 'eune', 'eu-nordic & east' => 'eune', 'eu north east' => 'eune',
            'eu-northeast' => 'eune', 'eune' => 'eune',
            'north america' => 'na', 'na' => 'na',
            'brazil' => 'br', 'br' => 'br',
            'latin america north' => 'lan', 'lan' => 'lan',
            'latin america south' => 'las', 'las' => 'las',
            'oceania' => 'oce', 'oce' => 'oce',
            'russia' => 'ru', 'ru' => 'ru',
            'turkey' => 'tr', 'tr' => 'tr',
            'japan' => 'jp', 'jp' => 'jp',
            'korea' => 'kr', 'kr' => 'kr',
            'pbe' => 'pbe',
            'europe' => 'eu', 'eu' => 'eu',
            'southeast asia' => 'sea', 'sea' => 'sea',
            'middle east' => 'me', 'me' => 'me',
            'vietnam' => 'vn', 'vn' => 'vn',
            'philippines' => 'ph', 'ph' => 'ph',
            'singapore' => 'sg', 'sg' => 'sg',
            'thailand' => 'th', 'th' => 'th',
            'taiwan' => 'tw', 'tw' => 'tw',
        ];

        if ($game !== 'league-of-legends' && $game !== 'valorant' && $game !== 'lol' && $game !== 'val') {
            foreach ([($post['effective_server'] ?? null), ($post['server'] ?? null), ($post['schema_server'] ?? null), ($post['schema_region'] ?? null), $fallback] as $candidate) {
                $raw = strtolower(trim((string)($candidate ?? '')));
                if ($raw !== '') return preg_replace('/[^a-z0-9_-]/', '', $raw);
            }
            return 'global';
        }

        $allowed = ($game === 'valorant' || $game === 'val')
            ? ['eu', 'na', 'sea', 'me', 'vn', 'ph', 'sg', 'th', 'tw']
            : ['euw', 'eune', 'na', 'br', 'lan', 'las', 'oce', 'ru', 'tr', 'jp', 'kr', 'pbe', 'me', 'vn', 'ph', 'sg', 'th', 'tw'];

        // Prefer the explicit value from the visible select, then the game-specific field.
        // The generic server field and DB fallback are only legacy fallbacks.
        $candidates = ($game === 'valorant' || $game === 'val')
            ? [($post['effective_server'] ?? null), ($post['val_server'] ?? null), ($post['server'] ?? null), ($post['schema_server'] ?? null), ($post['schema_region'] ?? null), $fallback]
            : [($post['effective_server'] ?? null), ($post['lol_server'] ?? null), ($post['server'] ?? null), ($post['schema_server'] ?? null), ($post['schema_region'] ?? null), $fallback];

        foreach ($candidates as $candidate) {
            $raw = strtolower(trim((string)($candidate ?? '')));
            if ($raw === '') {
                continue;
            }
            $normalized = $aliases[$raw] ?? $raw;
            if (in_array($normalized, $allowed, true)) {
                return $normalized;
            }
        }

        return ($game === 'valorant' || $game === 'val') ? 'eu' : 'euw';
    }

    public function seller_create_account()
    {
        $this->ensure_selling_schema();
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        $validator  = new Validator();
        $validation = $validator->make($_POST, [
            'title'       => 'required',
            'price'       => 'required',
            'description' => 'required',
        ]);
        $validation->validate();

        if ($validation->fails()) {
            echo json_encode([
                'sendToast'        => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'],
                'playSound'        => 'error',
                'validationErrors' => $validation->errors()->firstOfAll(),
            ]);
            return;
        }

        $uploaded_images = [];
        if (isset($_FILES['images']['name']) && is_array($_FILES['images']['name'])) {
            for ($i = 0; $i < count($_FILES['images']['name']); $i++) {
                if (empty($_FILES['images']['name'][$i]) || $_FILES['images']['error'][$i] !== UPLOAD_ERR_OK) continue;
                $file = [
                    'name'     => $_FILES['images']['name'][$i],
                    'type'     => $_FILES['images']['type'][$i],
                    'tmp_name' => $_FILES['images']['tmp_name'][$i],
                    'error'    => $_FILES['images']['error'][$i],
                    'size'     => $_FILES['images']['size'][$i],
                ];
                $uuid      = uniqid('account_', true);
                $image_url = upload_image($file, 'accounts-gallery/' . $uuid);
                if ($image_url === false) {
                    echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid image: ' . $file['name']], 'playSound' => 'error']);
                    return;
                }
                $uploaded_images[] = $image_url;
            }
        }

        if (empty($uploaded_images)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please upload at least one screenshot.'], 'playSound' => 'error']);
            return;
        }

        $price_raw   = str_replace(',', '.', $_POST['price'] ?? '0');
        $price_cents = (int)round((float)$price_raw * 100);

        // Do not force unknown DB games back to LoL. Dynamic games such as GTA VI,
        // Call of Duty, Roblox, etc. must keep their selected game slug.
        $raw_game = strtolower(trim((string)($_POST['game'] ?? 'league-of-legends')));
        $raw_game = preg_replace('/[^a-z0-9_-]/', '', $raw_game);
        $game = function_exists('util_account_normalize_game_slug') ? util_account_normalize_game_slug($raw_game) : $raw_game;
        if ($game === '') { $game = 'league-of-legends'; }

        // Server is normalized from the selected game's field; generic `server` is only a legacy fallback.
        $server = $this->seller_account_server_from_post($game, $_POST);

        $data = [
            'title'                 => esc($_POST['title']),
            'slug'                  => generateUniqueSlug($_POST['title'], 'selling_accounts'),
            'price'                 => $price_cents,
            'game'                  => $game,
            'admin_id'              => null,
            'seller_id'             => (int)$this->seller_data['id'],
            'description'           => $_POST['description'] ?? '',
            'game'                  => $game,
            'server'                => $server,
            'level'                 => (isset($_POST['level'])         && $_POST['level']         !== '') ? (int)$_POST['level']         : null,
            'delivery_type'         => $_POST['delivery_type']         ?? 'manual',
            'login'                 => esc($_POST['login']             ?? ''),
            'password'              => esc($_POST['password']          ?? ''),
            'email'                 => esc($_POST['email']             ?? ''),
            'email_password'        => esc($_POST['email_password']    ?? ''),
            'in_game_name'          => esc($_POST['in_game_name']      ?? ''),
            '2fa'                   => !empty($_POST['has_2fa']) ? 1 : 0,
            'delivery_instructions' => $_POST['delivery_instructions'] ?? '',
            'images'                => json_encode($uploaded_images),
        ];

        if ($game === 'lol' || $game === 'league-of-legends') {
            // LoL-spezifische Felder (bestehende Spalten bleiben)
            $current_rank     = (int)($_POST['current_rank']     ?? 0);
            $current_division = (int)($_POST['current_division'] ?? 0);
            $current_lp       = (isset($_POST['current_lp']) && $_POST['current_lp'] !== '') ? (int)$_POST['current_lp'] : null;
            $data = array_merge($data, [
                'current_rank'      => $current_rank,
                'current_division'  => $current_division,
                'current_lp'        => $current_lp,
                'flex_rank'         => $_POST['flex_rank']         ?? null,
                'flex_division'     => $_POST['flex_division']     ?? null,
                'flex_lp'           => (isset($_POST['flex_lp']) && $_POST['flex_lp'] !== '') ? (int)$_POST['flex_lp'] : null,
                'previous_rank'     => $_POST['previous_rank']     ?? null,
                'previous_division' => $_POST['previous_division'] ?? null,
                'blue_essence'      => (isset($_POST['blue_essence'])  && $_POST['blue_essence']  !== '') ? (int)$_POST['blue_essence']  : null,
                'riot_points'       => (isset($_POST['riot_points'])   && $_POST['riot_points']   !== '') ? (int)$_POST['riot_points']   : null,
                'winrate_percent'   => (isset($_POST['winrate_percent']) && $_POST['winrate_percent'] !== '') ? (int)$_POST['winrate_percent'] : null,
                'champions'         => (isset($_POST['champions']) && is_array($_POST['champions'])) ? implode('|', $_POST['champions']) : '',
                'skins'             => (isset($_POST['skins'])     && is_array($_POST['skins']))     ? implode('|', $_POST['skins'])     : '',
                'champion_count'    => (isset($_POST['champion_count']) && $_POST['champion_count'] !== '' && !(isset($_POST['champions']) && is_array($_POST['champions']) && count($_POST['champions']) > 0)) ? (int)$_POST['champion_count'] : null,
                'skin_count'        => (isset($_POST['skin_count']) && $_POST['skin_count'] !== '' && !(isset($_POST['skins']) && is_array($_POST['skins']) && count($_POST['skins']) > 0)) ? (int)$_POST['skin_count'] : null,
                'roles'             => (isset($_POST['roles'])     && is_array($_POST['roles']))     ? implode('|', $_POST['roles'])     : '',
                // Universal rank fields
                'rank'              => $current_rank,
                'rank_label'        => function_exists('util_get_lol_rank') ? util_get_lol_rank($current_rank) : '',
                'game_data'         => json_encode([
                    'division'      => $current_division,
                    'lp'            => $current_lp ?? 0,
                    'flex_rank'     => (int)($_POST['flex_rank']     ?? 0),
                    'flex_division' => (int)($_POST['flex_division'] ?? 0),
                    'prev_rank'     => (int)($_POST['previous_rank']     ?? 0),
                    'prev_division' => (int)($_POST['previous_division'] ?? 0),
                ]),
            ]);
        } elseif ($game === 'val' || $game === 'valorant') {
            // Valorant-spezifische Felder
            $val_rank         = (int)($_POST['val_rank'] ?? 0);
            $val_peak_rank    = (int)($_POST['val_peak_rank'] ?? 0);
            $val_act          = esc($_POST['val_act'] ?? '');
            $val_platform     = esc($_POST['val_platform'] ?? '');
            $val_points       = (isset($_POST['val_points']) && $_POST['val_points'] !== '') ? (int)$_POST['val_points'] : 0;
            $val_radianite    = (isset($_POST['val_radianite']) && $_POST['val_radianite'] !== '') ? (int)$_POST['val_radianite'] : 0;
            $val_winrate      = (isset($_POST['val_winrate']) && $_POST['val_winrate'] !== '') ? (int)$_POST['val_winrate'] : 0;
            $val_weapon_skins = (isset($_POST['val_weapon_skins']) && $_POST['val_weapon_skins'] !== '') ? (int)$_POST['val_weapon_skins'] : 0;
            $val_ranked_ready = !empty($_POST['val_ranked_ready']) ? 1 : 0;
            $val_agents       = isset($_POST['val_agents']) && is_array($_POST['val_agents']) ? array_values(array_map('esc', $_POST['val_agents'])) : [];
            $val_agent_count  = (count($val_agents) > 0) ? null
                : ((isset($_POST['val_agent_count']) && $_POST['val_agent_count'] !== '') ? (int)$_POST['val_agent_count'] : null);

            $data = array_merge($data, [
                'champions'      => '',
                'skins'          => '',
                'roles'          => '',
                'val_agent_count' => $val_agent_count,
                'rank'       => $val_rank,
                'rank_label' => function_exists('util_get_val_rank') ? util_get_val_rank($val_rank) : '',
                'game_data'  => json_encode([
                    'val_rank'          => $val_rank,
                    'val_peak_rank'     => $val_peak_rank,
                    'val_act'           => $val_act,
                    'val_platform'      => $val_platform,
                    'val_points'        => $val_points,
                    'val_radianite'     => $val_radianite,
                    'val_winrate'       => $val_winrate,
                    'val_weapon_skins'  => $val_weapon_skins,
                    'val_ranked_ready'  => $val_ranked_ready,
                    'agents'            => $val_agents,
                ]),
            ]);
        }

        if ($game !== 'lol' && $game !== 'league-of-legends' && $game !== 'val' && $game !== 'valorant') {
            $gameData = [];
            if (!empty($_POST['game_data'])) {
                $decoded = json_decode((string)$_POST['game_data'], true);
                if (is_array($decoded)) { $gameData = $decoded; }
            }
            foreach ($_POST as $k => $v) {
                if (strpos((string)$k, 'schema_') === 0) {
                    $schemaKey = substr((string)$k, 7);
                    if ($schemaKey !== '') { $gameData[$schemaKey] = $v; }
                }
            }
            $data['rank'] = (int)($_POST['rank'] ?? 0);
            $data['rank_label'] = trim((string)($_POST['rank_label'] ?? ''));
            $data['game_data'] = json_encode($gameData, JSON_UNESCAPED_UNICODE);
        }

        $account_id = db_add_row('selling_accounts', $data);

        if ($account_id) {
            if (function_exists('trigger_notification_sender_async')) {
                @trigger_notification_sender_async();
            }
            echo json_encode([
                'sendToast'   => ['type' => 'success', 'title' => 'Listed!', 'message' => 'Your account is now live in the shop 🎉'],
                'playSound'   => 'success',
                'redirectUrl' => BASE_URL . '/seller-area/accounts',
            ]);
        } else {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Failed to create listing.'], 'playSound' => 'error']);
        }
    }

    public function seller_duplicate_account()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        global $db;
        $id        = (int)($_POST['id'] ?? 0);
        $seller_id = (int)$this->seller_data['id'];
        $account   = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => $seller_id]);

        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Account not found.']]);
            return;
        }
        if ((int)$account['sold'] === 1) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Cannot duplicate a sold account.']]);
            return;
        }

        $copy = $account;
        unset($copy['id'], $copy['client_id'], $copy['created_at'], $copy['updated_at']);
        $copy['sold']   = 0;
        $copy['active'] = 0;
        $copy['title']  = ($copy['title'] ?? '') . ' (Copy)';
        $base_slug      = rtrim($copy['slug'] ?? '', '-');
        $copy['slug']   = $base_slug . '-copy-' . time();

        $new_id = db_insert_row('selling_accounts', $copy);

        if ($new_id) {
            echo json_encode([
                'sendToast'   => ['type' => 'success', 'title' => 'Duplicated', 'message' => 'Account copied as unlisted draft.'],
                'playSound'   => 'success',
                'refreshPage' => true,
            ]);
        } else {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Failed to duplicate account.']]);
        }
    }

    public function seller_delete_account()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id      = (int)($_POST['id'] ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']]);

        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Account not found.']]);
            return;
        }
        if ((int)$account['sold'] === 1) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Cannot delete a sold account.']]);
            return;
        }

        db_delete_rows('selling_accounts', ['id' => $id]);

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Deleted', 'message' => 'Account listing removed.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_bulk_delete_accounts()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        $sellerId = (int)($this->seller_data['id'] ?? 0);
        if ($sellerId <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Seller not found.']]);
            return;
        }

        /*
         * Accept multiple transport formats because jQuery/PHP can collapse
         * repeated "ids=1&ids=2" values into a single scalar.
         *
         * Supported:
         * - ids_json: "[1,2,3]"
         * - ids: "1,2,3"
         * - ids: [1,2,3]
         * - ids[]: [1,2,3]
         */
        $rawIds = [];

        if (!empty($_POST['ids_json'])) {
            $decodedIds = json_decode((string)$_POST['ids_json'], true);
            if (is_array($decodedIds)) {
                $rawIds = $decodedIds;
            }
        }

        if (empty($rawIds)) {
            $postedIds = $_POST['ids'] ?? ($_POST['ids[]'] ?? []);
            if (is_array($postedIds)) {
                $rawIds = $postedIds;
            } else {
                $rawIds = preg_split('/[,\s]+/', (string)$postedIds, -1, PREG_SPLIT_NO_EMPTY);
            }
        }

        $ids = array_values(array_unique(array_filter(array_map('intval', $rawIds), function ($id) {
            return $id > 0;
        })));

        if (empty($ids)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No accounts selected.']]);
            return;
        }

        $deleted = 0;
        $skipped = 0;

        /*
         * Delete per account instead of relying on one large IN query.
         * This is safer with the existing DB wrapper and guarantees every
         * selected ID is checked against seller ownership and sold status.
         */
        foreach ($ids as $accountId) {
            $account = db_get_row('selling_accounts', [
                'id' => $accountId,
                'seller_id' => $sellerId
            ], 1);

            if (empty($account)) {
                $skipped++;
                continue;
            }

            if ((int)($account['sold'] ?? 0) === 1) {
                $skipped++;
                continue;
            }

            db_delete_rows('selling_accounts', [
                'id' => $accountId,
                'seller_id' => $sellerId
            ]);

            $deleted++;
        }

        if ($deleted <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No selected accounts could be deleted. Sold or missing accounts were skipped.']]);
            return;
        }

        $message = $deleted . ' account' . ($deleted === 1 ? '' : 's') . ' deleted.';
        if ($skipped > 0) {
            $message .= ' ' . $skipped . ' account' . ($skipped === 1 ? ' was' : 's were') . ' skipped.';
        }

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Deleted', 'message' => $message],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_request_payout()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        global $db;
        $seller_id    = (int)$this->seller_data['id'];
        $seller       = db_get_row('sellers', ['id' => $seller_id]);
        $amount_raw   = str_replace(',', '.', $_POST['amount'] ?? '0');
        $is_full      = !empty($_POST['full_balance']);
        $amount_cents = $is_full ? (int)$seller['balance'] : (int)round((float)$amount_raw * 100);

        if ($amount_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid amount.']]);
            return;
        }
        if ($amount_cents > (int)$seller['balance']) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Amount exceeds your available balance.']]);
            return;
        }

        // Resolve method from saved payout method ID
        // Ensure table exists first (auto-create on first use)
        try {
            $db->run("CREATE TABLE IF NOT EXISTS seller_payout_methods (
                id INT AUTO_INCREMENT PRIMARY KEY, seller_id INT NOT NULL, method VARCHAR(32) NOT NULL,
                details TEXT, is_default TINYINT(1) NOT NULL DEFAULT 0,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX(seller_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        } catch (\Throwable $e) {}

        $method_id = (int)($_POST['payout_method_id'] ?? 0);
        $pm = null;
        try {
            if ($method_id > 0) {
                $pm = $db->row("SELECT * FROM seller_payout_methods WHERE id=? AND seller_id=? LIMIT 1", $method_id, $seller_id);
            }
            if (empty($pm)) {
                $pm = $db->row("SELECT * FROM seller_payout_methods WHERE seller_id=? AND is_default=1 LIMIT 1", $seller_id);
            }
        } catch (\Throwable $e) { $pm = null; }

        if (empty($pm)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'No Payout Method', 'message' => 'Please save a payout method first (Bank Transfer or Crypto).']]);
            return;
        }

        $method  = $pm['method'];   // 'bank_transfer' or 'crypto'
        $details = $pm['details'];  // already JSON string

        // Ensure all needed columns exist (table may have been created with fewer columns)
        try {
            $db->run("CREATE TABLE IF NOT EXISTS seller_payout_requests (
                id           INT AUTO_INCREMENT PRIMARY KEY,
                seller_id    INT NOT NULL,
                amount_cents INT NOT NULL DEFAULT 0,
                method       VARCHAR(32) NOT NULL DEFAULT 'bank_transfer',
                details      TEXT NULL,
                status       VARCHAR(16) NOT NULL DEFAULT 'PENDING',
                admin_note   TEXT NULL,
                created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
                INDEX(seller_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        } catch (\Throwable $e) {}
        // Always try to add missing columns (safe if they exist)
        foreach ([
            "ALTER TABLE seller_payout_requests ADD COLUMN IF NOT EXISTS amount_cents INT NOT NULL DEFAULT 0",
            "ALTER TABLE seller_payout_requests ADD COLUMN IF NOT EXISTS method VARCHAR(32) NOT NULL DEFAULT 'bank_transfer'",
            "ALTER TABLE seller_payout_requests ADD COLUMN IF NOT EXISTS details TEXT NULL",
            "ALTER TABLE seller_payout_requests ADD COLUMN IF NOT EXISTS status VARCHAR(16) NOT NULL DEFAULT 'PENDING'",
            "ALTER TABLE seller_payout_requests ADD COLUMN IF NOT EXISTS admin_note TEXT NULL",
        ] as $alter) {
            try { $db->run($alter); } catch (\Throwable $e2) {}
        }

        $pending = 0;
        try {
            $pending = (int)$db->single(
                "SELECT COUNT(*) FROM seller_payout_requests WHERE seller_id = ? AND status = 'PENDING'",
                [$seller_id]
            );
        } catch (\Throwable $e) {}
        if ($pending > 0) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Pending', 'message' => 'You already have a pending payout request.']]);
            return;
        }

        try {
            db_add_row('seller_payout_requests', [
                'seller_id'    => $seller_id,
                'amount_cents' => $amount_cents,
                'method'       => $method,
                'details'      => $details,
                'status'       => 'PENDING',
            ]);
        } catch (\Throwable $e) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => $e->getMessage()]]);
            return;
        }
        
        
                // Discord webhook notification for seller payout request (best-effort)
        $webhookUrl = "https://discord.com/api/webhooks/1469789889036947791/EJAh6OOm2iFLl9gSSp8twQjrjnvWyAWlllLhf8gYy45hTyXqVdfgvV-RC22FQXKVZUZX";
        if (!empty($webhookUrl) && strpos($webhookUrl, 'XXX/XXX') === false && function_exists('curl_init')) {
            try {
                $requestId = null;
                if (isset($db) && method_exists($db, 'lastInsertId')) {
                    $requestId = $db->lastInsertId();
                }

                $methodLabel = strtoupper((string)$method);
                if ($methodLabel === 'BANK_TRANSFER') $methodLabel = 'BANK';

                $requestedEur = number_format($amount_cents / 100, 2) . " EUR";

                $adminUrl = BASE_URL . "/admin-area/seller-payout-requests";

                $data = [
                    "username" => "Seller Payout Requests",
                    "avatar_url" => "https://lolboost.gg/public/uploads/icons/default1.png",
                    "content" => "",
                    "embeds" => [[
                        "title" => "💸 New Seller Payout Request",
                        "color" => hexdec("57F287"),
                        "fields" => [
                            [
                                "name" => "Seller",
                                "value" => ($seller['username'] ?? 'Seller') . " (ID: " . $seller_id . ")",
                                "inline" => true
                            ],
                            [
                                "name" => "Method",
                                "value" => $methodLabel,
                                "inline" => true
                            ],
                            [
                                "name" => "Requested",
                                "value" => $requestedEur,
                                "inline" => true
                            ],
                            [
                                "name" => "Request ID",
                                "value" => $requestId ? ("#" . $requestId) : "—",
                                "inline" => true
                            ],
                            [
                                "name" => "Action",
                                "value" => "[🚀 View](" . $adminUrl . ")",
                                "inline" => false
                            ]
                        ],
                        "timestamp" => date("c")
                    ]]
                ];

                $ch = curl_init($webhookUrl);
                curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
                curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
                curl_setopt($ch, CURLOPT_HEADER, 0);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_TIMEOUT, 3);
                curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 2);
                curl_exec($ch);
                curl_close($ch);
            } catch (\Throwable $e) {
                // ignore webhook errors
            }
        }
        
        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Submitted', 'message' => 'Payout request submitted. We\'ll process it soon.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    // ─────────────────────────────────────────────
    // seller_cancel_payout_request
    // ─────────────────────────────────────────────
    public function seller_cancel_payout_request()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        global $db;
        $req = $db->row("SELECT id, status FROM seller_payout_requests WHERE id=? AND seller_id=? LIMIT 1", $id, (int)$this->seller_data['id']);
        if (empty($req)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Request not found.']]); return; }
        if (strtoupper($req['status'] ?? '') !== 'PENDING') { echo json_encode(['sendToast' => ['type' => 'warning', 'message' => 'Only pending requests can be cancelled.']]); return; }
        $db->run("DELETE FROM seller_payout_requests WHERE id=?", $id);
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Cancelled', 'message' => 'Payout request cancelled.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_save_payout_method  (insert or update)
    // Uses seller_payout_methods table (same structure as booster_payout_methods)
    // ─────────────────────────────────────────────
    public function seller_save_payout_method()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        global $db;
        $seller_id  = (int)$this->seller_data['id'];
        $method     = in_array($_POST['method'] ?? '', ['bank_transfer', 'crypto'], true) ? $_POST['method'] : null;
        if (!$method) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Invalid method.']]); return; }
        $posted_id  = (int)($_POST['id'] ?? 0);
        $is_default = (int)(!empty($_POST['is_default']));

        // Build details payload
        if ($method === 'bank_transfer') {
            $details = json_encode([
                'beneficiary' => trim($_POST['beneficiary'] ?? ''),
                'iban'        => trim($_POST['iban'] ?? ''),
                'bic'         => trim($_POST['bic'] ?? ''),
                'bank_name'   => trim($_POST['bank_name'] ?? ''),
            ]);
        } else {
            $details = json_encode([
                'coin'    => trim($_POST['coin'] ?? 'USDC'),
                'network' => trim($_POST['network'] ?? 'Solana'),
                'name'    => trim($_POST['name'] ?? ''),
                'wallet'  => trim($_POST['wallet'] ?? ''),
                'address' => trim($_POST['address'] ?? ''),
            ]);
        }

        // Check if table exists, create if not
        $db->run("CREATE TABLE IF NOT EXISTS seller_payout_methods (
            id         INT AUTO_INCREMENT PRIMARY KEY,
            seller_id  INT NOT NULL,
            method     VARCHAR(32) NOT NULL,
            details    TEXT,
            is_default TINYINT(1) NOT NULL DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            INDEX(seller_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

        // Find target row
        $target_id = 0;
        if ($posted_id > 0) {
            $row = $db->row("SELECT id FROM seller_payout_methods WHERE id=? AND seller_id=? LIMIT 1", $posted_id, $seller_id);
            if ($row) $target_id = (int)$row['id'];
        }
        if (!$target_id) {
            $existing = $db->row("SELECT id FROM seller_payout_methods WHERE seller_id=? AND method=? ORDER BY id DESC LIMIT 1", $seller_id, $method);
            if ($existing) $target_id = (int)$existing['id'];
        }

        // If setting as default, clear others
        if ($is_default) {
            $db->run("UPDATE seller_payout_methods SET is_default=0 WHERE seller_id=?", $seller_id);
        }

        if ($target_id) {
            $cur = $db->row("SELECT is_default FROM seller_payout_methods WHERE id=? AND seller_id=? LIMIT 1", $target_id, $seller_id);
            $keep_default = $is_default ? 1 : (int)($cur['is_default'] ?? 0);
            $db->run("UPDATE seller_payout_methods SET details=?, is_default=? WHERE id=? AND seller_id=?", $details, $keep_default, $target_id, $seller_id);
        } else {
            $target_id = db_add_row('seller_payout_methods', ['seller_id' => $seller_id, 'method' => $method, 'details' => $details, 'is_default' => $is_default]);
        }

        // Remove duplicates for this method
        $db->run("DELETE FROM seller_payout_methods WHERE seller_id=? AND method=? AND id<>?", $seller_id, $method, $target_id);

        // Ensure at least one default
        $has_default = $db->row("SELECT id FROM seller_payout_methods WHERE seller_id=? AND is_default=1 LIMIT 1", $seller_id);
        if (!$has_default) {
            $db->run("UPDATE seller_payout_methods SET is_default=1 WHERE id=? AND seller_id=?", $target_id, $seller_id);
        }

        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Payout method saved.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_delete_payout_method
    // ─────────────────────────────────────────────
    public function seller_delete_payout_method()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $id = (int)($_POST['id'] ?? 0);
        $row = $db->row("SELECT id, is_default FROM seller_payout_methods WHERE id=? AND seller_id=? LIMIT 1", $id, $seller_id);
        if (empty($row)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Not found.']]); return; }
        $was_default = !empty($row['is_default']);
        $db->run("DELETE FROM seller_payout_methods WHERE id=? AND seller_id=?", $id, $seller_id);
        if ($was_default) {
            $fallback = $db->row("SELECT id FROM seller_payout_methods WHERE seller_id=? ORDER BY id DESC LIMIT 1", $seller_id);
            if ($fallback) $db->run("UPDATE seller_payout_methods SET is_default=1 WHERE id=?", (int)$fallback['id']);
        }
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Removed', 'message' => 'Payout method removed.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    public function admin_add_seller_from_client()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $username = trim($_POST['username'] ?? '');
        $email    = trim($_POST['email']    ?? '');
        $password = trim($_POST['password'] ?? '');
        $fee_raw  = $_POST['fee_percent'] ?? '';
        $fee      = ($fee_raw !== '' && $fee_raw !== null) ? (float)$fee_raw : null;

        if ($username === '' || $email === '' || $password === '') {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Username, email and password are required.']]);
            return;
        }

        try {
            global $db;
            $existing = $db->row("SELECT id FROM sellers WHERE email = ? LIMIT 1", $email);
            if (!empty($existing)) {
                echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Already exists', 'message' => 'A seller with this email already exists.']]);
                return;
            }

            $seller_id = db_add_row('sellers', [
                'username'    => $username,
                'email'       => $email,
                'password'    => sha1($password),
                'fee_percent' => $fee,
                'balance'     => 0,
                'is_banned'   => 0,
            ]);

            if (!$seller_id) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Failed to create seller account.']]);
                return;
            }

            log_admin_action(ADMIN_ID, "Created seller #{$seller_id} ({$email})");

            echo json_encode([
                'sendToast'   => ['type' => 'success', 'title' => 'Created', 'message' => "Seller account created for {$email}. Password: {$password}"],
                'playSound'   => 'success',
                'redirectUrl' => BASE_URL . '/admin-area/seller/' . $seller_id,
            ]);

        } catch (\Exception $e) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => $e->getMessage()]]);
        }
    }

    public function admin_update_seller()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id     = (int)($_POST['id'] ?? 0);
        $seller = db_get_row('sellers', ['id' => $id]);
        if (empty($seller)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Seller not found.']]);
            return;
        }

        $username = trim((string)($_POST['username'] ?? $seller['username'] ?? ''));
        $email    = trim((string)($_POST['email'] ?? $seller['email'] ?? ''));
        $discord  = trim((string)($_POST['discord'] ?? $seller['discord'] ?? ''));
        $fee_raw  = $_POST['fee_percent'] ?? '';
        $fee      = ($fee_raw !== '' && $fee_raw !== null) ? (float)$fee_raw : null;
        $password = trim((string)($_POST['password'] ?? ''));

        if ($username === '' || $email === '') {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Username and email are required.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid email address.'],
                'playSound' => 'error',
            ]);
            return;
        }

        global $db;
        $existing = $db->row("SELECT id FROM sellers WHERE email = ? AND id != ? LIMIT 1", $email, $id);
        if (!empty($existing)) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'This email address is already used by another seller.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $status_state = strtolower(trim((string)($_POST['status_state'] ?? '')));
        if ($status_state === '') {
            // Backwards compatibility for older forms that only posted is_banned.
            $status_state = ((int)($_POST['is_banned'] ?? 0) === 1) ? 'banned' : 'active';
        }

        $current_onboarding = strtolower(trim((string)($seller['onboarding_status'] ?? 'pending')));

        switch ($status_state) {
            case 'active':
                $is_banned = 0;
                $is_active = 1;
                $onboarding_status = 'approved';
                break;

            case 'inactive':
                $is_banned = 0;
                $is_active = 0;
                $onboarding_status = 'approved';
                break;

            case 'pending':
                $is_banned = 0;
                $is_active = 0;
                $onboarding_status = 'pending';
                break;

            case 'banned':
                $is_banned = 1;
                $is_active = 0;
                $onboarding_status = ($current_onboarding === 'approved') ? 'approved' : 'pending';
                break;

            default:
                $is_banned = (int)($seller['is_banned'] ?? 0);
                $is_active = (int)($seller['is_active'] ?? 0);
                $onboarding_status = $current_onboarding ?: 'pending';
                break;
        }

        // Permissions from the admin seller profile. These columns are added defensively
        // because older Live databases may not have them yet on new.lolboost.gg.
        try { $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS can_list_digital_goods TINYINT(1) NOT NULL DEFAULT 0"); } catch (\Throwable $e) {}
        try { $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS allowed_games TEXT NULL COMMENT 'comma-separated game slugs; empty = all games allowed'"); } catch (\Throwable $e) {}

        $can_list_digital_goods = isset($_POST['can_list_digital_goods']) ? 1 : 0;

        $allowed_games_raw = $_POST['allowed_games'] ?? [];
        if (!is_array($allowed_games_raw)) {
            $allowed_games_raw = [$allowed_games_raw];
        }
        $allowed_games = implode(',', array_values(array_unique(array_filter(array_map(function($v) {
            $v = strtolower(trim((string)$v));
            return preg_replace('/[^a-z0-9_-]/', '', $v);
        }, $allowed_games_raw)))));

        $update = [
            'username'               => esc($username),
            'email'                  => esc($email),
            'discord'                => esc($discord),
            'fee_percent'            => $fee,
            'is_banned'              => $is_banned,
            'is_active'              => $is_active,
            'onboarding_status'      => $onboarding_status,
            'can_list_digital_goods' => $can_list_digital_goods,
            'allowed_games'          => $allowed_games,
        ];

        if ($password !== '') {
            $update['password'] = sha1(trim($password));
        }

        db_update_row('sellers', ['id' => $id], $update);

        log_admin_action(
            ADMIN_ID,
            "Updated seller #{$id} (status={$status_state}, onboarding={$onboarding_status}, active={$is_active}, banned={$is_banned})"
        );

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Seller updated.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

