    public function admin_ban_seller()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $seller_id = (int)($_POST['id'] ?? 0);
        $reason    = esc($_POST['reason'] ?? '');
        $details   = esc($_POST['details'] ?? '');

        if ($seller_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid seller ID.']]);
            return;
        }

        $seller = db_get_row('sellers', ['id' => $seller_id]);
        if (empty($seller)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Seller not found.']]);
            return;
        }

        $upd = db_update_row('sellers', ['id' => $seller_id], ['is_banned' => 1, 'is_active' => 0]);

        if ($upd) {
            log_admin_action(ADMIN_ID, 'Banned seller account #' . $seller_id . ' for reason: ' . $reason . ' with details: ' . $details);
            echo json_encode([
                'sendToast'   => ['type' => 'success', 'title' => 'Banned', 'message' => 'Seller banned successfully.'],
                'playSound'   => 'success',
                'refreshPage' => true,
            ]);
        } else {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Something went wrong.'],
                'playSound' => 'error',
            ]);
        }
