    public function admin_process_seller_payout()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id     = (int)($_POST['id'] ?? 0);
        $status = strtoupper(trim((string)($_POST['status'] ?? '')));

        // Older forms may still submit APPROVED. Treat that as a completed payout.
        if ($status === 'APPROVED') {
            $status = 'COMPLETED';
        }

        if (!in_array($status, ['COMPLETED', 'REJECTED'], true) || $id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid request.']]);
            return;
        }

        global $db;
        $db->run("START TRANSACTION");
        $req = $db->row("SELECT * FROM seller_payout_requests WHERE id = ? LIMIT 1 FOR UPDATE", $id);

        $current_status = strtoupper(trim((string)($req['status'] ?? '')));
        if (empty($req) || !in_array($current_status, ['PENDING', ''], true)) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Request not found or already processed.']]);
            return;
        }

        $seller = $db->row("SELECT * FROM sellers WHERE id = ? LIMIT 1 FOR UPDATE", (int)$req['seller_id']);
        if (empty($seller)) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Seller not found.']]);
            return;
        }

        $new_bal = (int)($seller['balance'] ?? 0);
        if ($status === 'COMPLETED') {
            $old_bal = (int)$seller['balance'];
            $amount = (int)$req['amount_cents'];
            if ($amount <= 0 || $old_bal < $amount) {
                $db->run("ROLLBACK");
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Seller balance is insufficient for this payout.']]);
                return;
            }
            $new_bal = $old_bal - $amount;

            $db->run("UPDATE sellers SET balance = ? WHERE id = ?", $new_bal, (int)$req['seller_id']);
            db_add_row('seller_payments', [
                'seller_id'     => (int)$req['seller_id'],
                'type'          => 'payout_withdrawal',
                'amount_cents'  => -(int)$req['amount_cents'],
                'note'          => "Payout request #{$id} completed by admin #" . ADMIN_ID,
                'balance_after' => $new_bal,
            ]);

            log_admin_action(ADMIN_ID, "Completed seller payout #{$id} – seller #{$req['seller_id']} – €" . number_format($req['amount_cents'] / 100, 2));
        } else {
            log_admin_action(ADMIN_ID, "Rejected seller payout #{$id} – seller #{$req['seller_id']}");
        }

        // seller_payout_requests still uses the legacy ENUM
        // ('PENDING','APPROVED','REJECTED'). APPROVED is the persisted completed
        // state and is normalized to "Completed" everywhere in the admin UI.
        $stored_status = $status === 'COMPLETED' ? 'APPROVED' : 'REJECTED';
        $db->run(
            "UPDATE seller_payout_requests SET status = ?, admin_note = ? WHERE id = ? AND status IN ('PENDING', '')",
            $stored_status, esc($_POST['admin_note'] ?? ''), $id
        );
        $db->run("COMMIT");

        $admin_note = trim((string)($_POST['admin_note'] ?? ''));
        $this->payout_send_discord_dm((string)($seller['discord_id'] ?? ''), 'seller', [
            'status' => strtolower($status),
            'request_id' => $id,
            'amount_cents' => (int)($req['amount_cents'] ?? 0),
            'net_cents' => (int)($req['amount_cents'] ?? 0),
            'method' => (string)($req['method'] ?? 'bank_transfer'),
            'balance_cents' => $status === 'COMPLETED' ? $new_bal : (int)($seller['balance'] ?? 0),
            'reason' => $status === 'REJECTED' ? ($admin_note !== '' ? $admin_note : 'Rejected by an administrator') : '',
            'note' => $admin_note,
        ]);

        echo json_encode([
            'sendToast'   => [
                'type'    => 'success',
                'title'   => $status === 'COMPLETED' ? 'Completed' : 'Rejected',
                'message' => "Payout #{$id} " . strtolower($status) . ".",
            ],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_adjust_seller_balance()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $seller_id    = (int)($_POST['seller_id'] ?? 0);
        $amount_raw   = str_replace(',', '.', $_POST['amount'] ?? '0');
        $amount_cents = abs((int)round((float)$amount_raw * 100));
        $mode         = strtolower(trim((string)($_POST['mode'] ?? '')));
        if ($mode === '') $mode = ((float)$amount_raw < 0) ? 'fine' : 'add';
        $reason       = esc($_POST['reason'] ?? ($mode === 'fine' ? 'admin_fine' : 'manual_credit'));
        $note         = esc($_POST['note'] ?? '');
        if (!in_array($mode, ['add', 'fine'], true) || $amount_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid amount.']]);
            return;
        }

        global $db;
        $db->run("START TRANSACTION");
        $seller = $db->row("SELECT * FROM sellers WHERE id = ? LIMIT 1 FOR UPDATE", $seller_id);
        if (empty($seller)) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Seller not found.']]);
            return;
        }

        $old_bal = (int)$seller['balance'];
        $signed_amount = $mode === 'fine' ? -$amount_cents : $amount_cents;
        $new_bal = $old_bal + $signed_amount;
        if ($new_bal < 0) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Balance cannot go below 0.']]);
            return;
        }

        $db->run("UPDATE sellers SET balance = ? WHERE id = ?", $new_bal, $seller_id);
        db_add_row('seller_payments', [
            'seller_id'    => $seller_id,
            'type'         => $mode === 'fine' ? 'admin_fine' : $reason,
            'amount_cents' => $signed_amount,
            'note'         => $reason . ($note !== '' ? ': ' . $note : '') . " (admin #" . ADMIN_ID . ")",
            'balance_after' => $new_bal,
        ]);
        db_add_row('notifications', [
            'type' => $mode === 'fine' ? 'seller_money_fined' : 'seller_money_added',
            'recipient' => 'seller',
            'recipient_id' => $seller_id,
            'data' => json_encode(['amount' => $amount_cents, 'reason' => $reason, 'note' => $note, 'balance' => $new_bal]),
            'is_web' => 1,
            'is_email' => 0,
            'is_discord' => 0,
            'is_sent' => 1,
        ]);
        $db->run("COMMIT");

        log_admin_action(ADMIN_ID, "Adjusted seller #{$seller_id} balance by €" . number_format($amount_cents / 100, 2));

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Done', 'message' => "Balance adjusted to €" . number_format($new_bal / 100, 2) . "."],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    // ─────────────────────────────────────────────
    // ─────────────────────────────────────────────
    // seller_upload_profile_picture
    // ─────────────────────────────────────────────
    public function seller_upload_profile_picture()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $image_url = $_FILES['image_url'] ?? null;
        if (!$image_url || empty($image_url['name'])) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No file selected.']]);
            return;
        }
        $url = upload_image($image_url, 'icons/');
        if ($url === false) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid file type. Use JPG, PNG or GIF.']]);
            return;
        }
        global $db;
        // Ensure sellers.icon column exists (may not exist on older installs)
        try {
            $this->ensure_selling_schema();
        } catch (\Throwable $e) {}
        try {
            $db->run("UPDATE sellers SET icon = ? WHERE id = ?", $url, (int)$this->seller_data['id']);
        } catch (\Throwable $e) {
            // Fallback: column name might differ
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => 'Could not save icon: ' . $e->getMessage()]]);
            return;
        }
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Updated', 'message' => 'Profile picture updated.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_upload_banner
    // ─────────────────────────────────────────────
    public function seller_upload_banner()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $file = $_FILES['banner_image'] ?? null;
        if (!$file || empty($file['name'])) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No file selected.']]);
            return;
        }

        $url = upload_image($file, 'seller_banners/');
        if ($url === false) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid file type. Use JPG, PNG or WEBP.']]);
            return;
        }

        // Sanitize optional position (e.g. "50% 32%")
        $posRaw = trim($_POST['banner_position'] ?? '50% 50%');
        $position = preg_match('/^(\d{1,3}(?:\.\d{1,2})?%)\s+(\d{1,3}(?:\.\d{1,2})?%)$/', $posRaw)
            ? $posRaw : '50% 50%';

        global $db;
        $this->ensure_selling_schema();

        try {
            $db->run("UPDATE sellers SET banner = ?, banner_position = ? WHERE id = ?",
                $url, $position, (int)$this->seller_data['id']);
        } catch (\Throwable $e) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => 'Could not save banner: ' . $e->getMessage()]]);
            return;
        }

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Updated', 'message' => 'Banner updated successfully.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    // ─────────────────────────────────────────────
    // seller_save_banner_position
    // ─────────────────────────────────────────────
    public function seller_save_banner_position()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $posRaw  = trim($_POST['banner_position'] ?? '50% 50%');
        $position = preg_match('/^(\d{1,3}(?:\.\d{1,2})?%)\s+(\d{1,3}(?:\.\d{1,2})?%)$/', $posRaw)
            ? $posRaw : '50% 50%';

        global $db;
        $this->ensure_selling_schema();

        $db->run("UPDATE sellers SET banner_position = ? WHERE id = ?",
            $position, (int)$this->seller_data['id']);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Banner position saved.'],
            'playSound' => 'success',
        ]);
    }

    // ─────────────────────────────────────────────
    // ─────────────────────────────────────────────
    // seller_update_profile
    // ─────────────────────────────────────────────
    public function seller_update_profile()
{
    if (!$this->is_seller) {
        echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
        return;
    }

    $seller_id   = (int)$this->seller_data['id'];
    $username    = trim($_POST['username'] ?? '');
    $email       = strtolower(trim($_POST['email'] ?? ''));
    $discord     = trim($_POST['discord'] ?? '');
    $discord_id  = trim($_POST['discord_id'] ?? '');
    $description = trim($_POST['description'] ?? '');
    $languages   = $_POST['languages'] ?? [];

    if (!is_array($languages)) {
        $languages = [];
    }

    $languages = array_values(array_unique(array_filter(array_map(function ($lang) {
        return trim((string)$lang);
    }, $languages))));

    if ($username === '' || $email === '') {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Username and email are required.'
            ]
        ]);
        return;
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Invalid email address.'
            ]
        ]);
        return;
    }

    global $db;

    $existUn = $db->row("SELECT id FROM sellers WHERE username = ? AND id != ? LIMIT 1", $username, $seller_id);
    if ($existUn) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Username already taken.'
            ]
        ]);
        return;
    }

    $existEm = $db->row("SELECT id FROM sellers WHERE email = ? AND id != ? LIMIT 1", $email, $seller_id);
    if ($existEm) {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Error',
                'message' => 'Email address already in use.'
            ]
        ]);
        return;
    }

    $languagesJson = json_encode($languages, JSON_UNESCAPED_UNICODE);
    $allow_chat_requests = isset($_POST['allow_chat_requests']) ? 1 : 0;
    $this->ensure_selling_schema();

    $db->run(
        "UPDATE sellers 
         SET username = ?, email = ?, discord = ?, discord_id = ?, description = ?, languages = ?, allow_chat_requests = ?
         WHERE id = ?",
        $username,
        $email,
        $discord,
        $discord_id ?: null,
        $description,
        $languagesJson,
        $allow_chat_requests,
        $seller_id
    );

    log_admin_action(0, "Seller #{$seller_id} updated their profile (username: {$username})");

    echo json_encode([
        'sendToast' => [
            'type' => 'success',
            'title' => 'Saved',
            'message' => 'Profile updated successfully.'
        ],
        'playSound' => 'success',
        'refreshPage' => true,
    ]);
}

    // seller_update_personals
    // ─────────────────────────────────────────────
    public function seller_update_personals()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized']]);
            return;
        }

        global $db;

        $id = (int)$this->seller_data['id'];

        $fullname = trim((string)($_POST['fullname'] ?? ''));
        $dob      = trim((string)($_POST['dob'] ?? ''));
        $address  = trim((string)($_POST['address'] ?? ''));
        $country  = trim((string)($_POST['country'] ?? ''));

        $db->run(
            "UPDATE sellers SET fullname = ?, dob = ?, address = ?, country = ? WHERE id = ?",
            $fullname, $dob, $address, $country, $id
        );

        $uploads = ['id_front', 'id_back', 'selfie'];

        foreach ($uploads as $field) {
            if (!empty($_FILES[$field]['name'])) {
                $url = upload_image($_FILES[$field], 'seller_docs/' . $id);
                if ($url) {
                    $db->run("UPDATE sellers SET {$field} = ? WHERE id = ?", $url, $id);
                }
            }
        }

        // A complete seller onboarding must enter the admin review list, even when
        // the seller account was already active before the documents were submitted.
        $freshSeller = $db->row(
            "SELECT fullname, dob, address, country, id_front, id_back, selfie FROM sellers WHERE id = ? LIMIT 1",
            $id
        ) ?: [];
        $requiredFields = ['fullname', 'dob', 'address', 'country', 'id_front', 'id_back', 'selfie'];
        $onboardingComplete = true;
        foreach ($requiredFields as $requiredField) {
            if (trim((string)($freshSeller[$requiredField] ?? '')) === '') {
                $onboardingComplete = false;
                break;
            }
        }
        if ($onboardingComplete) {
            $db->run("UPDATE sellers SET onboarding_status = 'pending' WHERE id = ?", $id);
        }

        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'message' => $onboardingComplete
                    ? 'Onboarding submitted successfully and is now awaiting admin review.'
                    : 'Saved successfully'
            ],
            'refreshPage' => true
        ]);
    }


    // seller_change_password
    // ─────────────────────────────────────────────
    public function seller_change_password()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $current_password = trim($_POST['current_password'] ?? '');
        $new_password     = trim($_POST['new_password']     ?? '');
        $confirm_password = trim($_POST['confirm_password'] ?? '');

        if ($current_password === '' || $new_password === '' || $confirm_password === '') {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'All fields are required.']]);
            return;
        }

        if (strlen($new_password) < 8) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'New password must be at least 8 characters.']]);
            return;
        }

        if ($new_password !== $confirm_password) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Passwords do not match.']]);
            return;
        }

        global $db;
        $seller = $db->row(
            "SELECT id, password FROM sellers WHERE id = ? LIMIT 1",
            (int)$this->seller_data['id']
        );

        if (!$seller || $seller['password'] !== sha1($current_password)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Current password is incorrect.']]);
            return;
        }

        $db->run("UPDATE sellers SET password = ? WHERE id = ?", sha1($new_password), (int)$this->seller_data['id']);

        log_admin_action(0, 'Seller #' . (int)$this->seller_data['id'] . ' changed their password.');

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Password updated', 'message' => 'Your password has been changed successfully.'],
            'playSound' => 'success',
        ]);
    }

    // seller_update_account
    // ─────────────────────────────────────────────
    public function seller_update_account()
    {
        $this->ensure_selling_schema();
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        $id      = (int)($_POST['id'] ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']]);

        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Account not found.'], 'playSound' => 'error']);
            return;
        }

        $validator  = new Validator();
        $validation = $validator->make($_POST, [
            'title'       => 'required',
            'price'       => 'required',
            'description' => 'required',
        ]);
        $validation->validate();
        if ($validation->fails()) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'], 'playSound' => 'error', 'validationErrors' => $validation->errors()->firstOfAll()]);
            return;
        }

        // Handle image uploads
        $uploaded_images = [];
        if (isset($_FILES['images']['name']) && is_array($_FILES['images']['name'])) {
            for ($i = 0; $i < count($_FILES['images']['name']); $i++) {
                if (empty($_FILES['images']['name'][$i]) || $_FILES['images']['error'][$i] !== UPLOAD_ERR_OK) continue;
                $file = [
                    'name'     => $_FILES['images']['name'][$i],
                    'type'     => $_FILES['images']['type'][$i],
                    'tmp_name' => $_FILES['images']['tmp_name'][$i],
                    'error'    => $_FILES['images']['error'][$i],
                    'size'     => $_FILES['images']['size'][$i],
                ];
                $uuid      = uniqid('account_', true);
                $image_url = upload_image($file, 'accounts-gallery/' . $uuid);
                if ($image_url === false) {
                    echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid file: ' . $file['name']], 'playSound' => 'error']);
                    return;
                }
                $uploaded_images[] = $image_url;
            }
        }

        $price_raw   = str_replace(',', '.', $_POST['price'] ?? '0');
        $price_cents = (int)round((float)$price_raw * 100);

        $posted_game = strtolower(trim((string)($_POST['game'] ?? '')));
        $posted_game = preg_replace('/[^a-z0-9_-]/', '', $posted_game);
        $existing_game = strtolower(trim((string)($account['game'] ?? 'league-of-legends')));
        $game = $posted_game !== '' ? $posted_game : $existing_game;
        if (function_exists('util_account_normalize_game_slug')) {
            $game = util_account_normalize_game_slug($game);
        }
        if ($game === '') { $game = 'league-of-legends'; }
        // Server is normalized from the selected game's field; generic `server` is only a legacy fallback.
        $server = $this->seller_account_server_from_post($game, $_POST, $account['server'] ?? null);

        $data = [
            'title'                 => esc($_POST['title']),
            'slug'                  => generateUniqueSlug($_POST['title'], 'selling_accounts'),
            'price'                 => $price_cents,
            'description'           => $_POST['description'] ?? '',
            'server'                => $server,
            'level_up_method'       => $_POST['level_up_method']       ?? 'by_hand',
            'level'                 => (isset($_POST['level'])          && $_POST['level']          !== '') ? (int)$_POST['level']          : null,
            'delivery_type'         => $_POST['delivery_type']     ?? 'instant',
            'login'                 => esc($_POST['login']          ?? ''),
            'password'              => esc($_POST['password']       ?? ''),
            'email'                 => esc($_POST['email']          ?? ''),
            'email_password'        => esc($_POST['email_password'] ?? ''),
            'in_game_name'          => esc($_POST['in_game_name']   ?? ''),
            '2fa'                   => !empty($_POST['has_2fa']) ? 1 : 0,
            'delivery_instructions' => $_POST['delivery_instructions'] ?? '',
        ];

        if ($game === 'lol' || $game === 'league-of-legends') {
            $current_rank     = (int)($_POST['current_rank']     ?? 0);
            $current_division = (int)($_POST['current_division'] ?? 0);
            $current_lp       = (isset($_POST['current_lp']) && $_POST['current_lp'] !== '') ? (int)$_POST['current_lp'] : null;
            $data = array_merge($data, [
                'current_rank'      => $current_rank,
                'current_division'  => $current_division,
                'current_lp'        => $current_lp,
                'flex_rank'         => $_POST['flex_rank']         ?? null,
                'flex_division'     => $_POST['flex_division']     ?? null,
                'flex_lp'           => (isset($_POST['flex_lp']) && $_POST['flex_lp'] !== '') ? (int)$_POST['flex_lp'] : null,
                'previous_rank'     => $_POST['previous_rank']     ?? null,
                'previous_division' => $_POST['previous_division'] ?? null,
                'previous_lp'       => (isset($_POST['previous_lp']) && $_POST['previous_lp'] !== '') ? (int)$_POST['previous_lp'] : null,
                'blue_essence'      => (isset($_POST['blue_essence'])   && $_POST['blue_essence']   !== '') ? (int)$_POST['blue_essence']   : null,
                'riot_points'       => (isset($_POST['riot_points'])    && $_POST['riot_points']    !== '') ? (int)$_POST['riot_points']    : null,
                'winrate_percent'   => (isset($_POST['winrate_percent']) && $_POST['winrate_percent'] !== '') ? (int)$_POST['winrate_percent'] : null,
                'champions'         => (isset($_POST['champions'])  && is_array($_POST['champions']))  ? implode('|', $_POST['champions'])  : '',
                'skins'             => (isset($_POST['skins'])      && is_array($_POST['skins']))      ? implode('|', $_POST['skins'])      : '',
                'champion_count'    => (isset($_POST['champion_count']) && $_POST['champion_count'] !== '' && !(isset($_POST['champions']) && is_array($_POST['champions']) && count($_POST['champions']) > 0)) ? (int)$_POST['champion_count'] : null,
                'skin_count'        => (isset($_POST['skin_count']) && $_POST['skin_count'] !== '' && !(isset($_POST['skins']) && is_array($_POST['skins']) && count($_POST['skins']) > 0)) ? (int)$_POST['skin_count'] : null,
                'roles'             => (isset($_POST['roles'])      && is_array($_POST['roles']))      ? implode('|', $_POST['roles'])      : '',
                'rank'              => $current_rank,
                'rank_label'        => function_exists('util_get_lol_rank') ? util_get_lol_rank($current_rank) : '',
                'game_data'         => json_encode([
                    'division'      => $current_division,
                    'lp'            => $current_lp ?? 0,
                    'flex_rank'     => (int)($_POST['flex_rank']     ?? 0),
                    'flex_division' => (int)($_POST['flex_division'] ?? 0),
                    'prev_rank'     => (int)($_POST['previous_rank']     ?? 0),
                    'prev_division' => (int)($_POST['previous_division'] ?? 0),
                ]),
            ]);
        } elseif ($game === 'val' || $game === 'valorant') {
            $val_rank         = (int)($_POST['val_rank'] ?? 0);
            $val_peak_rank    = (int)($_POST['val_peak_rank'] ?? 0);
            $val_act          = esc($_POST['val_act'] ?? '');
            $val_platform     = esc($_POST['val_platform'] ?? '');
            $val_points       = (isset($_POST['val_points']) && $_POST['val_points'] !== '') ? (int)$_POST['val_points'] : 0;
            $val_radianite    = (isset($_POST['val_radianite']) && $_POST['val_radianite'] !== '') ? (int)$_POST['val_radianite'] : 0;
            $val_winrate      = (isset($_POST['val_winrate']) && $_POST['val_winrate'] !== '') ? (int)$_POST['val_winrate'] : 0;
            $val_weapon_skins = (isset($_POST['val_weapon_skins']) && $_POST['val_weapon_skins'] !== '') ? (int)$_POST['val_weapon_skins'] : 0;
            $val_ranked_ready = !empty($_POST['val_ranked_ready']) ? 1 : 0;
            $val_agents       = isset($_POST['val_agents']) && is_array($_POST['val_agents']) ? array_values(array_map('esc', $_POST['val_agents'])) : [];
            $val_agent_count  = (count($val_agents) > 0) ? null
                : ((isset($_POST['val_agent_count']) && $_POST['val_agent_count'] !== '') ? (int)$_POST['val_agent_count'] : null);

            $data = array_merge($data, [
                'champions'       => '',
                'skins'           => '',
                'roles'           => '',
                'val_agent_count' => $val_agent_count,
                'rank'       => $val_rank,
                'rank_label' => function_exists('util_get_val_rank') ? util_get_val_rank($val_rank) : '',
                'game_data'  => json_encode([
                    'val_rank'          => $val_rank,
                    'val_peak_rank'     => $val_peak_rank,
                    'val_act'           => $val_act,
                    'val_platform'      => $val_platform,
                    'val_points'        => $val_points,
                    'val_radianite'     => $val_radianite,
                    'val_winrate'       => $val_winrate,
                    'val_weapon_skins'  => $val_weapon_skins,
                    'val_ranked_ready'  => $val_ranked_ready,
                    'agents'            => $val_agents,
                ]),
            ]);
        } else {
            $gameData = [];
            if (!empty($_POST['game_data'])) {
                $decoded = json_decode((string)$_POST['game_data'], true);
                if (is_array($decoded)) $gameData = $decoded;
            }
            if (function_exists('util_collect_account_schema_data')) {
                $schemaData = util_collect_account_schema_data($game, $_POST);
                if (!empty($schemaData)) $gameData = array_merge($gameData, $schemaData);
            }
            $rankLabel = '';
            foreach (['rank','main_title','platform','level'] as $rk) {
                if (isset($gameData[$rk]) && $gameData[$rk] !== '' && $gameData[$rk] !== null) { $rankLabel = is_array($gameData[$rk]) ? implode(', ', $gameData[$rk]) : (string)$gameData[$rk]; break; }
            }
            $data = array_merge($data, [
                'champions' => '',
                'skins' => '',
                'roles' => '',
                'game' => $game,
                'rank' => function_exists('util_account_rank_number_from_label') ? util_account_rank_number_from_label($gameData['rank'] ?? ($_POST['rank'] ?? 0)) : (int)($_POST['rank'] ?? 0),
                'rank_label' => $rankLabel,
                'game_data' => json_encode($gameData, JSON_UNESCAPED_UNICODE),
            ]);
        }

        // Merge image order (same logic as admin version)
        $existing_images = json_decode($account['images'] ?? '[]', true);
        if (!is_array($existing_images)) $existing_images = [];

        $final_images = null;
        $posted_order = null;
        if (isset($_POST['images_order']) && $_POST['images_order'] !== '') {
            $posted_order = json_decode((string)$_POST['images_order'], true);
            if (!is_array($posted_order)) $posted_order = null;
        }
        if (is_array($posted_order)) {
            $final_images = [];
            $existing_set = array_flip($existing_images);
            $used_new = [];
            foreach ($posted_order as $entry) {
                if (!is_string($entry) || $entry === '') continue;
                if (strpos($entry, '__new__') !== 0) {
                    if (isset($existing_set[$entry])) $final_images[] = $entry;
                    continue;
                }
                $idx = (int)substr($entry, 7);
                if (isset($uploaded_images[$idx]) && empty($used_new[$idx])) {
                    $final_images[] = $uploaded_images[$idx];
                    $used_new[$idx] = true;
                }
            }
            foreach ($uploaded_images as $i => $url) {
                if (empty($used_new[$i])) $final_images[] = $url;
            }
            $seen = []; $deduped = [];
            foreach ($final_images as $u) { if (!isset($seen[$u])) { $deduped[] = $u; $seen[$u] = true; } }
            $final_images = $deduped;
        } elseif (!empty($uploaded_images)) {
            $final_images = array_merge($existing_images, $uploaded_images);
        }
        if ($final_images !== null) {
            $data['images'] = json_encode(array_values($final_images));
        }

        db_update_row('selling_accounts', ['id' => $id], $data);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Updated!', 'message' => 'Account updated successfully 🎉'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    // ─────────────────────────────────────────────
    // seller_mark_sold / seller_mark_unsold
    // ─────────────────────────────────────────────
    public function seller_mark_sold()
    {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Not allowed',
                'message' => 'Only admins can mark accounts as sold.',
            ],
            'playSound' => 'error',
        ]);
    }

    public function seller_mark_unsold()
    {
        echo json_encode([
            'sendToast' => [
                'type' => 'danger',
                'title' => 'Not allowed',
                'message' => 'Only admins can change the sold status of an account.',
            ],
            'playSound' => 'error',
        ]);
    }

    // ─────────────────────────────────────────────
    // seller_mark_unlist  (hide from shop, active=0)
    // ─────────────────────────────────────────────
    public function seller_mark_unlist()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']]);
        if (empty($account)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Not found.']]); return; }
        db_update_row('selling_accounts', ['id' => $id], ['active' => 0]);
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Unlisted', 'message' => 'Account hidden from shop.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_mark_active  (re-list, active=1)
    // ─────────────────────────────────────────────
    public function seller_mark_active()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']]);
        if (empty($account)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Not found.']]); return; }
        db_update_row('selling_accounts', ['id' => $id], ['active' => 1]);
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Listed', 'message' => 'Account is now visible in shop.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_delete_account_image
    // ─────────────────────────────────────────────
    public function seller_delete_account_image()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $data    = json_decode($_POST['id'] ?? '{}');
        $id      = (int)($data->id ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']]);
        if (empty($account)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Not found.']]); return; }
        $images        = json_decode($account['images'], true) ?: [];
        $imageToDelete = stripslashes($data->image ?? '');
        if (($key = array_search($imageToDelete, $images)) !== false) {
            unset($images[$key]);
            $images = array_values($images);
        }
        db_update_row('selling_accounts', ['id' => $id], ['images' => json_encode($images)]);
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Deleted', 'message' => 'Image removed.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_account_chat_send  (Seller → Buyer)
    // ─────────────────────────────────────────────
    // -------------------------------------------------
    // seller_chat_unread_count  (Sidebar unread badge)
    // -------------------------------------------------
    public function seller_chat_unread_count()
    {
        if (!$this->is_seller) {
            echo json_encode(['success' => false, 'accounts' => 0, 'items' => 0, 'unread' => 0, 'total' => 0]);
            return;
        }

        $seller_id = (int)($this->seller_data['id'] ?? 0);

        // Cache unread count for 5 s — called on every sidebar poll.
        // Shared with the seller sidebar's initial render (util_seller_chat_unread_count in
        // functions.php) — scans the account/item/top-up chat JSON files that the actual send
        // handlers write to (seller_chat_messages/seller_conversations exist but nothing writes
        // to them yet, so a DB-only count here was silently always ~0). Cached above for 5s so
        // this full scan doesn't run on every poll.
        $accounts_unread = 0;
        $items_unread = 0;
        $total = function_exists('util_seller_chat_unread_count') ? util_seller_chat_unread_count($seller_id) : 0;

        $_uc_result = json_encode([
            'success'  => true,
            'accounts' => $accounts_unread,
            'items'    => $items_unread,
            'unread'   => $total,
            'total'    => $total,
            'role'     => 'seller',
            'user_id'  => $seller_id,
        ]);
        echo $_uc_result;
    }

    public function seller_account_chat_seen()
    {
        $account_id = (int)($_POST['account_id'] ?? 0);
        $viewer_role = strtolower(trim((string)($_POST['viewer_role'] ?? '')));
        $account = false;

        if ($viewer_role === 'client' && $this->is_client) {
            $account = db_get_row('selling_accounts', [
                'id' => $account_id,
                'client_id' => (int)CLIENT_ID,
                'sold' => 1,
            ]);
        } elseif ($viewer_role === 'seller' && $this->is_seller) {
            $account = db_get_row('selling_accounts', [
                'id' => $account_id,
                'seller_id' => (int)$this->seller_data['id'],
            ]);
        }

        if (empty($account) || !in_array($viewer_role, ['client', 'seller'], true)) {
            echo json_encode(['success' => false]);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $chat_data = ['account_id' => $account_id, 'messages' => []];
        $changed = false;
        $fp = @fopen($chat_path, 'c+');

        if ($fp) {
            flock($fp, LOCK_EX);
            $raw = stream_get_contents($fp);
            $decoded = json_decode($raw ?: '', true);
            if (is_array($decoded)) $chat_data = $decoded;
            if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];

            foreach ($chat_data['messages'] as &$m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                $sender = strtolower((string)($m['sender'] ?? $m['type'] ?? ''));

                if (!array_key_exists('seen_by_seller', $m)) {
                    $m['seen_by_seller'] = ($sender === 'seller') ? 1 : 0;
                    $changed = true;
                }
                if (!array_key_exists('seen_by_client', $m)) {
                    $m['seen_by_client'] = ($sender === 'client') ? 1 : 0;
                    $changed = true;
                }

                if ($viewer_role === 'seller' && $sender === 'client' && (int)$m['seen_by_seller'] !== 1) {
                    $m['seen_by_seller'] = 1;
                    $m['read_by_seller_at'] = $m['read_by_seller_at'] ?? date('Y-m-d H:i:s');
                    $changed = true;
                } elseif ($viewer_role === 'client' && $sender !== 'client' && (int)$m['seen_by_client'] !== 1) {
                    $m['seen_by_client'] = 1;
                    $m['read_by_client_at'] = $m['read_by_client_at'] ?? date('Y-m-d H:i:s');
                    $changed = true;
                }
            }
            unset($m);

            if ($changed) {
                rewind($fp);
                ftruncate($fp, 0);
                fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            }
            flock($fp, LOCK_UN);
            fclose($fp);
        }

        $messages = array_values(array_filter($chat_data['messages'] ?? [], static fn($m) => is_array($m) && empty($m['deleted'])));

        // Normalize sender identity for direct read receipt payloads as well.
        // Older JSON messages may not contain sender_id or sender_icon, while the
        // normal chat loader enriches those fields from the database.
        $icon_cache = [];
        foreach ($messages as &$message_row) {
            $sender = strtolower((string)($message_row['sender'] ?? $message_row['sender_type'] ?? $message_row['type'] ?? ''));
            if (!in_array($sender, ['client', 'seller', 'admin', 'system'], true)) $sender = 'seller';
            $message_row['sender'] = $sender;
            $message_row['sender_type'] = $sender;

            $sender_id = (int)($message_row['sender_id'] ?? 0);
            if ($sender_id <= 0) {
                if ($sender === 'client') $sender_id = (int)($account['client_id'] ?? 0);
                elseif ($sender === 'seller') $sender_id = (int)($account['seller_id'] ?? 0);
            }
            $message_row['sender_id'] = $sender_id;

            $icon_key = $sender . ':' . $sender_id;
            if (!array_key_exists($icon_key, $icon_cache)) {
                $stored_icon = trim((string)($message_row['sender_icon'] ?? ''));
                if ($stored_icon !== '') {
                    $icon_cache[$icon_key] = $stored_icon;
                } elseif ($sender_id > 0 && $sender === 'client') {
                    $row = db_get_row('clients', ['id' => $sender_id, 'select' => 'username,icon']);
                    $icon_cache[$icon_key] = (string)($row['icon'] ?? '');
                    if (empty($message_row['sender_name']) && !empty($row['username'])) $message_row['sender_name'] = $row['username'];
                } elseif ($sender_id > 0 && $sender === 'seller') {
                    $row = db_get_row('sellers', ['id' => $sender_id, 'select' => 'username,icon']);
                    $icon_cache[$icon_key] = (string)($row['icon'] ?? '');
                    if (empty($message_row['sender_name']) && !empty($row['username'])) $message_row['sender_name'] = $row['username'];
                } else {
                    $icon_cache[$icon_key] = '';
                }
            }
            $message_row['sender_icon'] = $icon_cache[$icon_key];
        }
        unset($message_row);

        if ($changed) {
            $payload = [
                'account_id' => $account_id,
                'order_id' => 'acct_' . $account_id,
                'messages' => $messages,
                'read_receipt_update' => true,
                'reader_role' => $viewer_role,
            ];
            $is_realtime_internal = !empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
            if (!$is_realtime_internal && function_exists('lb_realtime_emit')) {
                lb_realtime_emit('account_chat_update', $payload, ['sellers', 'admins', 'clients']);
            }
            if (!$is_realtime_internal && function_exists('lb_realtime_emit_order')) {
                lb_realtime_emit_order('chat_update', 'acct_' . $account_id, $payload, ['sellers', 'admins', 'clients']);
            }
        }

        echo json_encode(['success' => true, 'changed' => $changed, 'messages' => $messages]);
    }

    public function item_chat_seen()
    {
        // Legacy action kept as a compatibility alias. All read handling now goes
        // through item_chat_load so no second implementation can overwrite receipts.
        $_POST['mark_seen'] = 1;
        $this->item_chat_load();
    }

    public function seller_account_chat_send()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        $message    = trim(esc($_POST['message'] ?? ''));

        // Image upload support
        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Image upload failed.'], 'playSound' => 'error']);
                return;
            }
        }

        if ($message === '' && !$image_url) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please type a message or attach an image.'], 'playSound' => 'error']);
            return;
        }

        // Verify ownership
        $account = db_get_row('selling_accounts', ['id' => $account_id, 'seller_id' => (int)$this->seller_data['id']]);
        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Account not found.']]);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Could not open chat file.']]);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['account_id' => $account_id, 'messages' => []];
        if (!isset($chat_data['messages'])) $chat_data['messages'] = [];

        $now = date('Y-m-d H:i:s');

        if ($message !== '') {
            $chat_data['messages'][] = [
                'type'         => 'seller',
                'sender'       => 'seller',
                'sender_id'    => (int)$this->seller_data['id'],
                'sender_name'  => $this->seller_data['username'] ?? 'Seller',
                'message'      => $message,
                'content'      => $message,
                'message_type' => 'text',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
                'seen_by_seller' => 1,
                'seen_by_client' => 0,
                'seen_by_admin'  => 0,
            ];
        }
        if ($image_url) {
            $chat_data['messages'][] = [
                'type'         => 'seller',
                'sender'       => 'seller',
                'sender_id'    => (int)$this->seller_data['id'],
                'sender_name'  => $this->seller_data['username'] ?? 'Seller',
                'message'      => $image_url,
                'content'      => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message_type' => 'image',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
                'seen_by_seller' => 1,
                'seen_by_client' => 0,
                'seen_by_admin'  => 0,
            ];
        }

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT));
        flock($fp, LOCK_UN);
        fclose($fp);

        $account_payload=['account_id'=>$account_id,'order_id'=>'acct_'.$account_id,'messages'=>array_values(array_filter($chat_data['messages'],fn($m)=>empty($m['deleted']))),'read_receipt_update'=>true];
        $is_realtime_internal=!empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
        if(!$is_realtime_internal&&function_exists('lb_realtime_emit')) lb_realtime_emit('account_chat_update',$account_payload,['sellers','admins','clients']);
        if(!$is_realtime_internal&&function_exists('lb_realtime_emit_order')) lb_realtime_emit_order('chat_update','acct_'.$account_id,$account_payload,['sellers','admins','clients']);
        if (function_exists('lb_realtime_schedule_client_unread_email') && !empty($account['client_id'])) {
            lb_realtime_schedule_client_unread_email(['client_id'=>(int)$account['client_id'],'seller_id'=>(int)$this->seller_data['id'],'ref_type'=>'account','ref_id'=>$account_id]);
        }

        echo json_encode(['success'=>true,'resetForm'=>true,'reFocus'=>true,'created_at'=>date('d.m.Y H:i',strtotime($now)),'messages'=>$account_payload['messages'],'read_receipt_update'=>true]);
    }

    // ─────────────────────────────────────────────
    // seller_account_chat_load  (poll for new msgs)
    // ─────────────────────────────────────────────
    public function seller_account_chat_load()
    {
        $account_id = (int)($_POST['account_id'] ?? 0);

        // Resolve the role explicitly because client and seller sessions can coexist in one browser.
        $requested_role = strtolower(trim((string)($_POST['viewer_role'] ?? '')));
        $viewer_role = '';
        $account = false;
        if ($requested_role === 'client' && $this->is_client) {
            $account = db_get_row('selling_accounts', ['id' => $account_id, 'client_id' => (int)CLIENT_ID, 'sold' => 1]);
            if (!empty($account)) $viewer_role = 'client';
        } elseif ($requested_role === 'seller' && $this->is_seller) {
            $account = db_get_row('selling_accounts', ['id' => $account_id, 'seller_id' => (int)$this->seller_data['id']]);
            if (!empty($account)) $viewer_role = 'seller';
        }
        if ($viewer_role === '') {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }

        if (empty($account)) {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $messages  = [];
        $chat_data = ['account_id' => $account_id, 'messages' => []];

        // Mark messages as seen for the current viewer while the chat is open.
        // Fix: the seller inbox badge must not count every old client message.
        $fp = @fopen($chat_path, 'c+');
        if ($fp) {
            flock($fp, LOCK_EX);
            $raw = stream_get_contents($fp);
            $decoded = json_decode($raw ?: '', true);
            if (is_array($decoded)) {
                $chat_data = $decoded;
            }
            if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) {
                $chat_data['messages'] = [];
            }

            $changed = false;
            // Do not auto-mark seller messages as read-by-client just because the JSON chat is loaded/polled.
            // Only an explicit frontend read action may set seen_by_client/seen_by_seller.
            $mark_seen = !empty($_POST['mark_seen']) || !empty($_POST['seen']) || !empty($_POST['set_seen']) || !empty($_POST['mark_read']);
            foreach ($chat_data['messages'] as &$m) {
                if (!is_array($m) || !empty($m['deleted'])) {
                    continue;
                }

                $sender = $m['sender'] ?? $m['type'] ?? '';

                if (!array_key_exists('seen_by_seller', $m)) {
                    $m['seen_by_seller'] = ($sender === 'seller') ? 1 : 0;
                    $changed = true;
                }
                if (!array_key_exists('seen_by_client', $m)) {
                    $m['seen_by_client'] = ($sender === 'client') ? 1 : 0;
                    $changed = true;
                }
                if (!array_key_exists('seen_by_admin', $m)) {
                    $m['seen_by_admin'] = ($sender === 'admin') ? 1 : 0;
                    $changed = true;
                }

                if ($mark_seen && $viewer_role === 'seller' && $sender === 'client' && (int)($m['seen_by_seller'] ?? 0) !== 1) {
                    $m['seen_by_seller'] = 1;
                    $m['seen'] = 1;
                    $m['read_by_seller_at'] = $m['read_by_seller_at'] ?? date('Y-m-d H:i:s');
                    $changed = true;
                }

                if ($mark_seen && $viewer_role === 'client' && $sender !== 'client' && (int)($m['seen_by_client'] ?? 0) !== 1) {
                    $m['seen_by_client'] = 1;
                    $m['seen'] = 1;
                    $m['read_by_client_at'] = $m['read_by_client_at'] ?? date('Y-m-d H:i:s');
                    $changed = true;
                    $read_changed = true;
                }
            }
            unset($m);

            if ($changed) {
                rewind($fp);
                ftruncate($fp, 0);
                fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT));
            }
            flock($fp, LOCK_UN);
            fclose($fp);

            if ($mark_seen && $viewer_role === 'seller' && function_exists('lb_legacy_chat_sync_seller_seen')) {
                lb_legacy_chat_sync_seller_seen('account', $account_id);
            }
        }

        if (isset($chat_data['messages'])) {
            $messages = array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted'])));
        }

        // Normalize fields so JS renderer works for both seller + client messages
        // Pre-load icons for all unique senders to avoid N+1 queries
        $icon_cache = [];
        $normalized = [];
        foreach ($messages as $i => $m) {
            $sender    = $m['sender'] ?? $m['type'] ?? 'seller';
            $sender_id = (int)($m['sender_id'] ?? 0);
            $msg_text  = $m['message'] ?? '';
            $is_image  = ($m['message_type'] ?? '') === 'image';

            // Resolve icon from DB (cached per sender+id)
            $icon_key = $sender . ':' . $sender_id;
            // Use icon stored on the message first (set at send time) — avoids a DB lookup per sender.
            if (!isset($icon_cache[$icon_key])) {
                $stored_icon = (string)($m['sender_icon'] ?? '');
                if ($stored_icon !== '') {
                    $icon_cache[$icon_key] = $stored_icon;
                } elseif ($sender_id > 0) {
                    if ($sender === 'client') {
                        $row = db_get_row('clients', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? $row['icon'] : '';
                    } elseif ($sender === 'seller') {
                        $row = db_get_row('sellers', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? $row['icon'] : '';
                    } else {
                        $icon_cache[$icon_key] = '';
                    }
                } else {
                    $icon_cache[$icon_key] = '';
                }
            }
            $sender_icon = $icon_cache[$icon_key];

            $seen_for_viewer = (int)($m['seen'] ?? 0);
            if ($viewer_role === 'seller') {
                // For seller's own messages: seen = whether the CLIENT has read it (for tick display).
                // For client messages: seen = whether the SELLER has read it.
                $seen_for_viewer = ($sender === 'seller')
                    ? (int)($m['seen_by_client'] ?? $m['seen'] ?? 0)
                    : (int)($m['seen_by_seller'] ?? $m['seen'] ?? 0);
            } elseif ($viewer_role === 'client') {
                // For client's own messages: seen = whether the SELLER has read it.
                // For seller messages: seen = whether the CLIENT has read it.
                $seen_for_viewer = ($sender === 'client')
                    ? (int)($m['seen_by_seller'] ?? $m['seen'] ?? 0)
                    : (int)($m['seen_by_client'] ?? $m['seen'] ?? 0);
            }

            $normalized[$i] = [
                'sender'      => $sender,
                'sender_id'   => $sender_id,
                'sender_name' => $m['sender_name'] ?? ($sender === 'client' ? 'Client' : 'Seller'),
                'sender_icon' => $sender_icon,
                'content'     => $m['content'] ?? ($is_image ? '<img src="' . htmlspecialchars($msg_text, ENT_QUOTES) . '" alt="image">' : $msg_text),
                'time'        => $m['time'] ?? (isset($m['created_at']) ? strtotime($m['created_at']) : 0),
                'seen'        => $seen_for_viewer,
                'seen_by_seller' => (int)($m['seen_by_seller'] ?? 0),
                'seen_by_client' => (int)($m['seen_by_client'] ?? 0),
                'seen_by_admin'  => (int)($m['seen_by_admin'] ?? 0),
                'read_at'     => !empty($m['read_at']) ? strtotime((string)$m['read_at']) : null,
                'read_at_fmt' => !empty($m['read_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_at'])) : '',
                'read_by_seller_at'     => !empty($m['read_by_seller_at']) ? strtotime((string)$m['read_by_seller_at']) : null,
                'read_by_seller_at_fmt' => !empty($m['read_by_seller_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_seller_at'])) : '',
                'read_by_client_at'     => !empty($m['read_by_client_at']) ? strtotime((string)$m['read_by_client_at']) : null,
                'read_by_client_at_fmt' => !empty($m['read_by_client_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_client_at'])) : '',
                'notify'      => $m['notify'] ?? 0,
                'edited'      => $m['edited'] ?? 0,
                'edited_at'   => $m['edited_at'] ?? null,
                'deleted'     => $m['deleted'] ?? 0,
                'message_type'=> $m['message_type'] ?? 'text',
            ];
        }

        echo json_encode(['success' => true, 'messages' => $normalized]);
    }

    // ─────────────────────────────────────────────
    // admin_account_chat_load  (Admin insight into marketplace account chat)
    // ─────────────────────────────────────────────
    public function admin_account_chat_load()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        $account = db_get_row('selling_accounts', ['id' => $account_id], 1);
        if (empty($account)) {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $messages  = [];
        if (is_file($chat_path)) {
            $raw = file_get_contents($chat_path);
            $chat_data = json_decode($raw, true);
            if (is_array($chat_data) && isset($chat_data['messages'])) {
                $messages = array_values($chat_data['messages']);
            }
        }

        $icon_cache = [];
        $normalized = [];
        foreach ($messages as $i => $m) {
            $sender    = $m['sender'] ?? $m['type'] ?? 'seller';
            $sender_id = (int)($m['sender_id'] ?? 0);
            $msg_text  = $m['message'] ?? '';
            $is_image  = ($m['message_type'] ?? '') === 'image';

            $icon_key = $sender . ':' . $sender_id;
            if (!isset($icon_cache[$icon_key])) {
                $stored_icon = (string)($m['sender_icon'] ?? '');
                if ($stored_icon !== '') {
                    $icon_cache[$icon_key] = $stored_icon;
                } elseif ($sender_id > 0) {
                    if ($sender === 'client') {
                        $row = db_get_row('clients', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? $row['icon'] : '';
                    } elseif ($sender === 'seller') {
                        $row = db_get_row('sellers', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? $row['icon'] : '';
                    } elseif ($sender === 'admin') {
                        $row = db_get_row('admins', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? $row['icon'] : '';
                    } else {
                        $icon_cache[$icon_key] = '';
                    }
                } else {
                    $icon_cache[$icon_key] = '';
                }
            }
            $sender_icon = $icon_cache[$icon_key];

            $normalized[$i] = [
                'sender'       => $sender,
                'sender_id'    => $sender_id,
                'sender_name'  => $m['sender_name'] ?? ucfirst($sender),
                'sender_icon'  => $sender_icon,
                'content'      => $m['content'] ?? ($is_image ? '<img src="' . htmlspecialchars($msg_text, ENT_QUOTES) . '" alt="image">' : $msg_text),
                'time'         => $m['time'] ?? (isset($m['created_at']) ? strtotime($m['created_at']) : 0),
                'seen'         => $m['seen'] ?? 0,
                'notify'       => $m['notify'] ?? 0,
                'edited'       => $m['edited'] ?? 0,
                'edited_at'    => $m['edited_at'] ?? null,
                'deleted'      => $m['deleted'] ?? 0,
                'message_type' => $m['message_type'] ?? 'text',
                'type'         => $m['type'] ?? null,
            ];
        }

        echo json_encode(['success' => true, 'messages' => $normalized]);
    }

    // ─────────────────────────────────────────────
    // admin_account_chat_send  (Admin → marketplace account chat)
    // ─────────────────────────────────────────────
    public function admin_account_chat_send()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        $message    = trim(esc($_POST['message'] ?? ''));

        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Image upload failed.'], 'playSound' => 'error']);
                return;
            }
        }

        if ($message === '' && !$image_url) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please type a message or attach an image.'], 'playSound' => 'error']);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id], 1);
        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Account not found.']]);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Could not open chat file.']]);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['account_id' => $account_id, 'messages' => []];
        if (!isset($chat_data['messages'])) $chat_data['messages'] = [];

        $now = date('Y-m-d H:i:s');
        $admin_name = ADMIN_DATA['username'] ?? 'Admin';

        if ($message !== '') {
            $chat_data['messages'][] = [
                'type'         => 'admin',
                'sender'       => 'admin',
                'sender_id'    => (int)ADMIN_ID,
                'sender_name'  => $admin_name,
                'content'      => $message,
                'message'      => $message,
                'message_type' => 'text',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
            ];
        }
        if ($image_url) {
            $chat_data['messages'][] = [
                'type'         => 'admin',
                'sender'       => 'admin',
                'sender_id'    => (int)ADMIN_ID,
                'sender_name'  => $admin_name,
                'content'      => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message'      => $image_url,
                'message_type' => 'image',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
            ];
        }

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT));
        flock($fp, LOCK_UN);
        fclose($fp);

        $account_payload=['account_id'=>$account_id,'order_id'=>'acct_'.$account_id,'messages'=>array_values(array_filter($chat_data['messages'],fn($m)=>empty($m['deleted']))),'read_receipt_update'=>true];
        $is_realtime_internal=!empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
        if(!$is_realtime_internal&&function_exists('lb_realtime_emit')) lb_realtime_emit('account_chat_update',$account_payload,['sellers','admins','clients']);
        if(!$is_realtime_internal&&function_exists('lb_realtime_emit_order')) lb_realtime_emit_order('chat_update','acct_'.$account_id,$account_payload,['sellers','admins','clients']);

        echo json_encode(['success' => true, 'resetForm' => true, 'reFocus' => true, 'created_at' => date('d.m.Y H:i', strtotime($now))]);
    }

