        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Could not open chat file.']]);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['account_id' => $account_id, 'messages' => []];
        if (!isset($chat_data['messages'])) $chat_data['messages'] = [];

        $now = date('Y-m-d H:i:s');

        if ($message !== '') {
            $chat_data['messages'][] = [
                'type'         => 'client',
                'sender'       => 'client',
                'sender_id'    => (int)CLIENT_ID,
                'sender_name'  => $client_name,
                'message'      => $message,
                'content'      => $message,
                'message_type' => 'text',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
            ];
        }
        if ($image_url) {
            $chat_data['messages'][] = [
                'type'         => 'client',
                'sender'       => 'client',
                'sender_id'    => (int)CLIENT_ID,
                'sender_name'  => $client_name,
                'message'      => $image_url,
                'content'      => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message_type' => 'image',
                'created_at'   => $now,
                'time'         => time(),
                'seen'         => 0,
                'notify'       => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
            ];
        }

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT));
        flock($fp, LOCK_UN);
        fclose($fp);

        if (function_exists('lb_legacy_chat_open')) {
            try {
                lb_legacy_chat_open(
                    'seller:account:' . $account_id,
                    'account',
                    $account_id,
                    ['seller_id' => (int)($account['seller_id'] ?? 0), 'client_id' => (int)CLIENT_ID],
                    $chat_path
                );
            } catch (\Throwable $e) {
                error_log('Client account chat DB sync failed: ' . $e->getMessage());
            }
        }

        $account_payload = [
            'account_id' => $account_id,
            'order_id' => 'acct_' . $account_id,
            'messages' => array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted']))),
            'read_receipt_update' => true,
        ];
        $is_realtime_internal = !empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
        if (!$is_realtime_internal && function_exists('lb_realtime_emit')) {
            lb_realtime_emit('account_chat_update', $account_payload, ['sellers', 'admins', 'clients']);
