        if (!$is_realtime_internal && function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('chat_update', 'acct_' . $account_id, $account_payload, ['sellers', 'admins', 'clients']);
        }

        if (function_exists('lb_realtime_schedule_seller_unread_email')) {
            lb_realtime_schedule_seller_unread_email([
                'seller_id' => (int)($account['seller_id'] ?? 0),
                'client_id' => (int)CLIENT_ID,
                'ref_type' => 'account',
                'ref_id' => $account_id,
            ]);
        }

        echo json_encode(['success'=>true,'resetForm'=>true,'reFocus'=>true,'messages'=>$account_payload['messages'],'read_receipt_update'=>true]);
    }

    // ─────────────────────────────────────────────
    // client_account_chat_edit  (Client edits own msg)
    // ─────────────────────────────────────────────
    public function client_account_chat_edit()
    {
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        $msg_index  = (int)($_POST['id'] ?? -1);
        $new_text   = trim(esc($_POST['message'] ?? ''));

        if ($msg_index < 0 || $new_text === '') {
            echo json_encode(['success' => false, 'message' => 'Invalid input.']);
            return;
        }

        $account = db_get_row('selling_accounts', ['id' => $account_id, 'client_id' => (int)CLIENT_ID, 'sold' => 1]);
        if (empty($account)) {
            echo json_encode(['success' => false, 'message' => 'Account not found.']);
            return;
        }

        $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $account_id) . '.json';
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['success' => false, 'message' => 'Could not open chat file.']);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);

        if (!is_array($chat_data) || !isset($chat_data['messages'][$msg_index])) {
            flock($fp, LOCK_UN); fclose($fp);
            echo json_encode(['success' => false, 'message' => 'Message not found.']);
            return;
        }

        $msg = $chat_data['messages'][$msg_index];
        // Only client can edit their own messages
        if (($msg['sender'] ?? $msg['type'] ?? '') !== 'client' || (int)($msg['sender_id'] ?? 0) !== (int)CLIENT_ID) {
            flock($fp, LOCK_UN); fclose($fp);
            echo json_encode(['success' => false, 'message' => 'Not your message.']);
            return;
        }

        $chat_data['messages'][$msg_index]['message']    = $new_text;
        $chat_data['messages'][$msg_index]['content']    = $new_text;
        $chat_data['messages'][$msg_index]['edited']     = 1;
        $chat_data['messages'][$msg_index]['edited_at']  = date('Y-m-d H:i:s');

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT));
        flock($fp, LOCK_UN);
        fclose($fp);

        echo json_encode(['success' => true]);
    }




