        if (!$fp) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Could not open chat file.']]);
            return;
        }

        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['account_id' => $account_id, 'ref_type' => 'premium_account', 'messages' => []];
        if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];
        $chat_data['account_id'] = $account_id;
        $chat_data['ref_type']   = 'premium_account';
        $chat_data['client_id']  = (int)CLIENT_ID;

        $now = date('Y-m-d H:i:s');

        if ($message !== '') {
            $chat_data['messages'][] = [
                'type'           => 'client',
                'sender'         => 'client',
                'sender_type'    => 'client',
