                'sender_name'    => $client_name,
                'sender_icon'    => $client['icon'] ?? '',
                'message'        => $message,
                'content'        => $message,
                'message_type'   => 'text',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
