                'sender_type'    => 'client',
                'sender_id'      => (int)CLIENT_ID,
                'sender_name'    => $client_name,
                'sender_icon'    => $client['icon'] ?? '',
                'message'        => $image_url,
                'content'        => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message_type'   => 'image',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
            ];
        }

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));
        flock($fp, LOCK_UN);
        fclose($fp);

        try {
            $pkg = db_get_row('account_packages', ['id' => (int)($account['package_id'] ?? 0), 'select' => 'name'], 1);
            $pkg_name = (string)($pkg['name'] ?? ('Account #' . $account_id));
            db_add_row('notifications', [
                'type'       => 'premium_account_chat_message',
                'title'      => 'New Client Message (Premium Account)',
