        echo json_encode([
            'success' => true,
            'resetForm' => true,
            'reFocus' => true,
            'created_at' => date('d.m.Y H:i', strtotime($now)),
            'image_url' => $image_url ?: null,
        ]);
    }

    // ─────────────────────────────────────────────────────────────
    // client_premium_account_chat_load  (Client polls for new msgs)
    // ─────────────────────────────────────────────────────────────
    public function client_premium_account_chat_load()
    {
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'error' => 'Not authorized']);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        if ($account_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Invalid account_id']);
            return;
        }

        $account = db_get_row('accounts', ['id' => $account_id, 'client_id' => (int)CLIENT_ID, 'status' => 1], 1);
        if (empty($account)) {
            echo json_encode(['success' => false, 'error' => 'Account not found']);
            return;
        }

        $last_ts   = (int)($_POST['last_ts'] ?? 0);
        $chat_path = SYS_PATH . '/public/uploads/private/chat/accounts_' . sha1('account_' . $account_id) . '.json';

        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['success' => true, 'messages' => []]);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data) || !isset($chat_data['messages'])) {
            flock($fp, LOCK_UN); fclose($fp);
            echo json_encode(['success' => true, 'messages' => []]);
            return;
        }

        // Ungelesene Admin-Nachrichten als gelesen markieren
        $changed = false;
        foreach ($chat_data['messages'] as &$m) {
            $sender = strtolower((string)($m['sender'] ?? $m['sender_type'] ?? ''));
            if ($sender === 'admin' && empty($m['seen_by_client'])) {
                $m['seen_by_client'] = 1;
                $changed = true;
            }
        }
        unset($m);
        if ($changed) {
            rewind($fp);
            ftruncate($fp, 0);
            fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));
        }
        flock($fp, LOCK_UN);
        fclose($fp);

        $messages = array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted'])));

        if ($last_ts > 0) {
            $messages = array_values(array_filter($messages, fn($m) => (int)($m['time'] ?? 0) > $last_ts));
        }

        echo json_encode(['success' => true, 'messages' => $messages]);
    }

    // ─────────────────────────────────────────────────────────────
    // admin_premium_account_chat_send  (Admin → Client)
    // ─────────────────────────────────────────────────────────────
    public function admin_premium_account_chat_send()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        $message    = trim(esc($_POST['message'] ?? ''));

        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Image upload failed.'], 'playSound' => 'error']);
                return;
            }
        }

        if ($message === '' && !$image_url) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please type a message or attach an image.'], 'playSound' => 'error']);
            return;
        }

        $account = db_get_row('accounts', ['id' => $account_id], 1);
        if (empty($account)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Account not found.']]);
            return;
        }

        $admin_id = defined('ADMIN_ID') ? (int)ADMIN_ID : 0;
        $admin_data = [];
        try {
            if ($admin_id > 0 && function_exists('db_get_row')) {
                $admin_data = db_get_row('admins', ['id' => $admin_id, 'select' => 'id,username,icon'], 1) ?: [];
            }
        } catch (\Throwable $e) {}
        $admin_name = $admin_data['username'] ?? 'Admin';

        $chat_path = SYS_PATH . '/public/uploads/private/chat/accounts_' . sha1('account_' . $account_id) . '.json';
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Could not open chat file.']]);
            return;
        }

        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['account_id' => $account_id, 'ref_type' => 'premium_account', 'messages' => []];
        if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];
        $chat_data['account_id'] = $account_id;
        $chat_data['ref_type']   = 'premium_account';
        if (!empty($account['client_id'])) $chat_data['client_id'] = (int)$account['client_id'];

        $now = date('Y-m-d H:i:s');

        if ($message !== '') {
            $chat_data['messages'][] = [
                'type'           => 'admin',
                'sender'         => 'admin',
                'sender_type'    => 'admin',
                'sender_id'      => $admin_id,
                'sender_name'    => $admin_name,
                'sender_icon'    => $admin_data['icon'] ?? '',
                'message'        => $message,
                'content'        => $message,
                'message_type'   => 'text',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 0,
                'seen_by_admin'  => 1,
            ];
        }
        if ($image_url) {
            $chat_data['messages'][] = [
                'type'           => 'admin',
                'sender'         => 'admin',
                'sender_type'    => 'admin',
                'sender_id'      => $admin_id,
                'sender_name'    => $admin_name,
                'sender_icon'    => $admin_data['icon'] ?? '',
                'message'        => $image_url,
                'content'        => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message_type'   => 'image',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 0,
                'seen_by_admin'  => 1,
            ];
        }

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));
        flock($fp, LOCK_UN);
        fclose($fp);

        if (!empty($account['client_id'])) {
            try {
                db_add_row('notifications', [
                    'type'       => 'premium_account_admin_message',
                    'client_id'  => (int)$account['client_id'],
                    'title'      => 'New Message from Support',
                    'body'       => 'Admin sent a message on your account.',
                    'url'        => defined('BASE_URL') ? BASE_URL . '/premium-account/' . $account_id : '',
                    'created_at' => date('Y-m-d H:i:s'),
                ]);
            } catch (\Throwable $e) {}
        }

        if (function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('chat_update', 'premacct_' . $account_id, [], ['admins', 'clients']);
        }

        echo json_encode(['success' => true, 'resetForm' => true, 'reFocus' => true, 'created_at' => date('d.m.Y H:i', strtotime($now))]);
    }

    // ─────────────────────────────────────────────────────────────
    // admin_premium_account_chat_load  (Admin polls for new msgs)
    // ─────────────────────────────────────────────────────────────
    public function admin_premium_account_chat_load()
    {
        if (!$this->is_admin) {
            echo json_encode(['success' => false, 'error' => 'Not authorized']);
            return;
        }

        $account_id = (int)($_POST['account_id'] ?? 0);
        if ($account_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'Invalid account_id']);
            return;
        }

        $last_ts   = (int)($_POST['last_ts'] ?? 0);
        $chat_path = SYS_PATH . '/public/uploads/private/chat/accounts_' . sha1('account_' . $account_id) . '.json';

        $fp = @fopen($chat_path, 'c+');
        if (!$fp) {
            echo json_encode(['success' => true, 'messages' => []]);
            return;
        }
        flock($fp, LOCK_EX);
        $raw       = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data) || !isset($chat_data['messages'])) {
            flock($fp, LOCK_UN); fclose($fp);
            echo json_encode(['success' => true, 'messages' => []]);
            return;
        }

        // Client-Nachrichten als gelesen markieren (Admin-Seite)
        $changed = false;
        foreach ($chat_data['messages'] as &$m) {
            $sender = strtolower((string)($m['sender'] ?? $m['sender_type'] ?? ''));
            if ($sender === 'client' && empty($m['seen_by_admin'])) {
                $m['seen_by_admin'] = 1;
                $changed = true;
            }
        }
        unset($m);
        if ($changed) {
            rewind($fp);
            ftruncate($fp, 0);
            fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));
        }
        flock($fp, LOCK_UN);
        fclose($fp);

        $messages = array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted'])));

        if ($last_ts > 0) {
            $messages = array_values(array_filter($messages, fn($m) => (int)($m['time'] ?? 0) > $last_ts));
        }

        echo json_encode(['success' => true, 'messages' => $messages]);
    }

    // ─────────────────────────────────────────────
    // admin_toggle_seller_status
    // ─────────────────────────────────────────────
    public function admin_toggle_seller_status()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        global $db;

        $seller = db_get_row('sellers', ['id' => $id]);
        if (empty($seller)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Seller not found.']]);
            return;
        }

        $this->ensure_selling_schema();

        $current_is_active = (int)($seller['is_active'] ?? 0);
        $current_is_banned = (int)($seller['is_banned'] ?? 0);
        $current_onboarding = strtolower(trim((string)($seller['onboarding_status'] ?? 'pending')));

        if ($current_is_banned === 1 || $current_is_active === 0 || $current_onboarding !== 'approved') {
            $db->run(
                "UPDATE sellers SET is_active = 1, is_banned = 0, onboarding_status = 'approved' WHERE id = ?",
                $id
            );
            $label = 'Approved';
            $message = "Seller #{$id} is now active and approved.";
            $log_state = 'approved';
        } else {
            $db->run(
                "UPDATE sellers SET is_active = 0 WHERE id = ?",
                $id
            );
            $label = 'Deactivated';
            $message = "Seller #{$id} is now inactive.";
            $log_state = 'inactive';
        }

        log_admin_action(ADMIN_ID, "Seller #{$id} toggled to {$log_state}");

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => $label, 'message' => $message],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    // ─────────────────────────────────────────────
    // admin_reject_seller
    // ─────────────────────────────────────────────
    public function admin_reject_seller()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        global $db;
        $seller = db_get_row('sellers', ['id' => $id]);
        if (empty($seller)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Seller not found.']]); return; }
        $this->ensure_selling_schema();
        $db->run("UPDATE sellers SET is_active = 0, is_banned = 1 WHERE id = ?", $id);
        log_admin_action(ADMIN_ID, "Rejected seller application #{$id}");
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Rejected', 'message' => "Seller #{$id} rejected."], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // ─────────────────────────────────────────────
    // seller_register  (public – no auth required)
    // ─────────────────────────────────────────────
    public function seller_api_create_key()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        seller_api_ensure_tables();
        $seller_id = (int)$this->seller_data['id'];
        $name = trim((string)($_POST['name'] ?? 'Default API Key'));
        $plain = 'lb_live_' . bin2hex(random_bytes(24));
        $hash = hash('sha256', $plain);
        $prefix = substr($plain, 0, 14);
        db_add_row('seller_api_keys', [
            'seller_id' => $seller_id,
            'name' => $name !== '' ? $name : 'Default API Key',
            'api_key_hash' => $hash,
            'key_prefix' => $prefix,
            'permissions' => 'accounts:read,accounts:write,items:read,items:write',
            'is_active' => 1,
        ]);
        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'API Key created', 'message' => 'Copy the key now. It will only be shown once.'],
            'playSound' => 'success',
            'refreshPage' => true,
            'api_key' => $plain,
        ]);
    }

    public function seller_api_delete_key()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        seller_api_ensure_tables();
        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Invalid key.']]); return; }
        global $db;
        $db->run("UPDATE seller_api_keys SET is_active = 0 WHERE id = ? AND seller_id = ?", $id, (int)$this->seller_data['id']);
        echo json_encode(['sendToast' => ['type' => 'success', 'message' => 'API key disabled.'], 'refreshPage' => true]);
    }

    public function seller_api_create_webhook()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        seller_api_ensure_tables();
        $url = trim((string)($_POST['url'] ?? ''));
        if (!filter_var($url, FILTER_VALIDATE_URL) || stripos($url, 'https://') !== 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Invalid URL', 'message' => 'Webhook URL must start with https://']]);
            return;
        }
        $secret = bin2hex(random_bytes(24));
        db_add_row('seller_webhooks', [
            'seller_id' => (int)$this->seller_data['id'],
            'url' => $url,
            'secret' => $secret,
            'events' => 'account.created,account.listed,account.archived,account.sold,item.created,item.listed,item.updated,item.archived,item.sold',
            'is_active' => 1,
        ]);
        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Webhook saved', 'message' => 'API sync webhooks will now be sent to this URL.'], 'refreshPage' => true, 'secret' => $secret]);
    }

    public function seller_api_delete_webhook()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        seller_api_ensure_tables();
        $id = (int)($_POST['id'] ?? 0);
        global $db;
        $db->run("UPDATE seller_webhooks SET is_active = 0 WHERE id = ? AND seller_id = ?", $id, (int)$this->seller_data['id']);
        echo json_encode(['sendToast' => ['type' => 'success', 'message' => 'Webhook disabled.'], 'refreshPage' => true]);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // SELLER ACCOUNT IMPORTS, JSON PREVIEW + PER ACCOUNT IMAGE UPLOAD
    // Flow: create import -> upload JSON -> rows are staged -> upload images per row -> import all
    // ═══════════════════════════════════════════════════════════════════════
    private function seller_import_ensure_tables(): void
    {
        global $db;
        if (function_exists('seller_api_ensure_tables')) { seller_api_ensure_tables(); }

        $db->run("CREATE TABLE IF NOT EXISTS seller_account_import_batches (
            id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
            seller_id INT UNSIGNED NOT NULL,
            import_name VARCHAR(191) NULL,
            game VARCHAR(50) NULL,
            filename VARCHAR(255) NULL,
            status VARCHAR(30) NOT NULL DEFAULT 'draft',
            total_rows INT UNSIGNED NOT NULL DEFAULT 0,
            created_count INT UNSIGNED NOT NULL DEFAULT 0,
            updated_count INT UNSIGNED NOT NULL DEFAULT 0,
            skipped_count INT UNSIGNED NOT NULL DEFAULT 0,
            failed_count INT UNSIGNED NOT NULL DEFAULT 0,
            update_existing TINYINT(1) NOT NULL DEFAULT 0,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
            KEY idx_seller_import_batches_seller (seller_id),
            KEY idx_seller_import_batches_created (created_at)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

        $db->run("CREATE TABLE IF NOT EXISTS seller_account_import_rows (
            id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
            batch_id INT UNSIGNED NOT NULL,
            seller_id INT UNSIGNED NOT NULL,
            account_id INT UNSIGNED NULL,
            external_id VARCHAR(191) NULL,
            status VARCHAR(30) NOT NULL DEFAULT 'draft',
            message TEXT NULL,
            row_data LONGTEXT NULL,
            image_ids TEXT NULL,
            image_urls LONGTEXT NULL,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
            KEY idx_import_rows_batch (batch_id),
            KEY idx_import_rows_seller (seller_id),
            KEY idx_import_rows_external (external_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

        foreach ([
            "ALTER TABLE seller_account_import_batches ADD COLUMN IF NOT EXISTS import_name VARCHAR(191) NULL AFTER seller_id",
            "ALTER TABLE seller_account_import_batches ADD COLUMN IF NOT EXISTS game VARCHAR(50) NULL AFTER import_name",
            "ALTER TABLE seller_account_import_batches ADD COLUMN IF NOT EXISTS status VARCHAR(30) NOT NULL DEFAULT 'draft' AFTER filename",
            "ALTER TABLE seller_account_import_batches ADD COLUMN IF NOT EXISTS updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP AFTER created_at",
            "ALTER TABLE seller_account_import_rows ADD COLUMN IF NOT EXISTS image_ids TEXT NULL AFTER row_data",
            "ALTER TABLE seller_account_import_rows ADD COLUMN IF NOT EXISTS image_urls LONGTEXT NULL AFTER image_ids",
            "ALTER TABLE seller_account_import_rows ADD COLUMN IF NOT EXISTS updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP AFTER created_at",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS gallery_image_ids TEXT NULL",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS api_source TINYINT(1) NOT NULL DEFAULT 0",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS api_created_at DATETIME NULL",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS api_updated_at DATETIME NULL"
        ] as $sql) {
            try { $db->run($sql); } catch (\Throwable $e) {}
        }
    }

    private function seller_import_json_response(array $payload): void
    {
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    public function seller_import_create_batch()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        $seller_id = (int)$this->seller_data['id'];
        $name = trim((string)($_POST['name'] ?? ''));
        $game = strtolower(trim((string)($_POST['game'] ?? 'lol')));
        if ($name === '') { $name = 'Account Import ' . date('Y-m-d H:i'); }
        $game = preg_replace('/[^a-z0-9_-]/', '', $game);
        if ($game === '') { $game = 'lol'; }
        if ($game === 'valorant') { $game = 'val'; }

        $batch_id = (int)db_add_row('seller_account_import_batches', [
            'seller_id' => $seller_id,
            'import_name' => $name,
            'game' => $game,
            'status' => 'draft',
            'total_rows' => 0,
        ]);

        $this->seller_import_json_response([
            'sendToast' => ['type' => 'success', 'title' => 'Import created', 'message' => 'Upload your JSON file next.'],
            'playSound' => 'success',
            'redirectUrl' => BASE_URL . '/seller-area/import-accounts?id=' . $batch_id,
            'batch_id' => $batch_id,
        ]);
    }

    private function seller_import_rank_id($rank): ?int
    {
        if ($rank === null || $rank === '') { return null; }
        if (is_numeric($rank)) { return (int)$rank; }
        $key = strtolower(trim((string)$rank));
        $key = str_replace([' ', '-', '_'], '', $key);
        $map = ['unranked'=>0,'iron'=>1,'bronze'=>2,'silver'=>3,'gold'=>4,'platinum'=>5,'plat'=>5,'emerald'=>6,'diamond'=>7,'master'=>8,'grandmaster'=>9,'challenger'=>10];
        return $map[$key] ?? null;
    }

    private function seller_import_division_id($division): ?int
    {
        if ($division === null || $division === '') { return null; }

        // Seller JSON and the import preview use normal LoL division values:
        // 1 = I, 2 = II, 3 = III, 4 = IV.
        // The existing marketplace stores LoL divisions internally reversed:
        // 1 = IV, 2 = III, 3 = II, 4 = I.
        // Convert only here, so we do not have to change the global util functions.
        $key = strtoupper(trim((string)$division));
        $map = ['IV' => 1, 'III' => 2, 'II' => 3, 'I' => 4, '4' => 1, '3' => 2, '2' => 3, '1' => 4];
        return $map[$key] ?? null;
    }

    private function seller_import_price_cents($price): int
    {
        if (is_string($price) && strpos($price, '.') !== false) { return (int)round(((float)$price) * 100); }
        if (is_float($price)) { return (int)round($price * 100); }
        return (int)$price;
    }

    private function seller_import_account_payload(int $seller_id, array $data, ?string &$error = null): array
    {
        $external_id = trim((string)($data['external_id'] ?? ''));
        $title = trim((string)($data['title'] ?? ''));
        $price = $this->seller_import_price_cents($data['price'] ?? 0);
        if ($external_id === '' || $title === '' || $price <= 0) {
            $error = 'external_id, title and price are required.';
            return [];
        }

        $status = strtolower((string)($data['status'] ?? 'listed'));
        if (!in_array($status, ['draft', 'pending', 'listed', 'archived'], true)) { $status = 'listed'; }
        $active = ($status === 'listed') ? 1 : 0;

        $imageIds = [];
        if (!empty($data['image_ids']) && is_array($data['image_ids'])) { $imageIds = array_values(array_unique(array_filter(array_map('intval', $data['image_ids'])))); }
        elseif (!empty($data['images']) && is_array($data['images'])) { $imageIds = array_values(array_unique(array_filter(array_map('intval', $data['images'])))); }
        $galleryUrls = [];
        if (!empty($imageIds)) {
            if (!function_exists('seller_gallery_urls_from_ids')) { $error = 'Gallery image helper not available.'; return []; }
            $galleryUrls = seller_gallery_urls_from_ids($seller_id, $imageIds);
            if (count($galleryUrls) !== count($imageIds)) {
                $error = 'One or more image_ids do not exist for this seller.';
                return [];
            }
        }

        $parameters = [];
        if (!empty($data['parameters']) && is_array($data['parameters'])) { $parameters = $data['parameters']; }
        if (!empty($data['game_data']) && is_array($data['game_data'])) { $parameters = array_merge($parameters, $data['game_data']); }
        $rankId = $this->seller_import_rank_id($data['current_rank'] ?? ($data['rank'] ?? ($parameters['rank'] ?? null)));
        $divisionId = $this->seller_import_division_id($data['current_division'] ?? ($data['division'] ?? ($parameters['division'] ?? null)));
        $rankLabel = $data['rank_label'] ?? null;
        if (!$rankLabel && !empty($data['rank'])) { $rankLabel = (string)$data['rank'] . (!empty($data['division']) ? ' ' . (string)$data['division'] : ''); }
        if ($rankId !== null) { $parameters['rank_id'] = $rankId; }
        if ($divisionId !== null) {
            $parameters['division_id'] = $divisionId;
            $parameters['division'] = $divisionId;
        }
        if ($rankLabel !== null) { $parameters['rank_label'] = $rankLabel; }

        $flexRankId = $this->seller_import_rank_id($data['flex_rank'] ?? ($parameters['flex_rank'] ?? null));
        $flexDivisionId = $this->seller_import_division_id($data['flex_division'] ?? ($parameters['flex_division'] ?? null));
        $previousRankId = $this->seller_import_rank_id($data['previous_rank'] ?? ($parameters['previous_rank'] ?? ($parameters['prev_rank'] ?? null)));
        $previousDivisionId = $this->seller_import_division_id($data['previous_division'] ?? ($parameters['previous_division'] ?? ($parameters['prev_division'] ?? null)));
        if ($flexRankId !== null) { $parameters['flex_rank'] = $flexRankId; }
        if ($flexDivisionId !== null) { $parameters['flex_division'] = $flexDivisionId; }
        if ($previousRankId !== null) { $parameters['previous_rank'] = $previousRankId; $parameters['prev_rank'] = $previousRankId; }
        if ($previousDivisionId !== null) { $parameters['previous_division'] = $previousDivisionId; $parameters['prev_division'] = $previousDivisionId; }
        $currentLp = isset($data['current_lp']) ? (int)$data['current_lp'] : null;
        $flexLp = isset($data['flex_lp']) ? (int)$data['flex_lp'] : null;
        $previousLp = isset($data['previous_lp']) ? (int)$data['previous_lp'] : null;

        $gameKey = strtolower((string)($data['game'] ?? 'lol'));
        $normalizeLolRankParts = static function (?int $rank, ?int &$division, ?int &$lp): void {
            if ($rank === null) {
                return;
            }

            // LoL/TFT: Iron through Diamond use divisions only.
            // Master, Grandmaster and Challenger use LP only.
            if ($rank >= 8) {
                $division = null;
            } else {
                $lp = null;
                if ($rank <= 0) {
                    $division = null;
                }
            }
        };

        if (in_array($gameKey, ['lol', 'tft'], true)) {
            $normalizeLolRankParts($rankId, $divisionId, $currentLp);
            $normalizeLolRankParts($flexRankId, $flexDivisionId, $flexLp);
            $normalizeLolRankParts($previousRankId, $previousDivisionId, $previousLp);

            unset($parameters['lp'], $parameters['flex_lp'], $parameters['previous_lp']);

            if ($rankId !== null && $rankId >= 8) {
                unset($parameters['division_id'], $parameters['division']);
            } elseif ($rankId !== null && $rankId <= 0) {
                unset($parameters['division_id'], $parameters['division']);
            } elseif ($divisionId !== null) {
                $parameters['division_id'] = $divisionId;
                $parameters['division'] = $divisionId;
            }

            if ($flexRankId !== null && $flexRankId >= 8) {
                unset($parameters['flex_division']);
            } elseif ($flexRankId !== null && $flexRankId <= 0) {
                unset($parameters['flex_division']);
            } elseif ($flexDivisionId !== null) {
                $parameters['flex_division'] = $flexDivisionId;
            }

            if ($previousRankId !== null && $previousRankId >= 8) {
                unset($parameters['previous_division'], $parameters['prev_division']);
            } elseif ($previousRankId !== null && $previousRankId <= 0) {
                unset($parameters['previous_division'], $parameters['prev_division']);
            } elseif ($previousDivisionId !== null) {
                $parameters['previous_division'] = $previousDivisionId;
                $parameters['prev_division'] = $previousDivisionId;
            }

            if ($currentLp !== null) { $parameters['lp'] = $currentLp; }
            if ($flexLp !== null) { $parameters['flex_lp'] = $flexLp; }
            if ($previousLp !== null) { $parameters['previous_lp'] = $previousLp; }
        } else {
            if (isset($data['flex_lp'])) { $parameters['flex_lp'] = (int)$data['flex_lp']; }
            if (isset($data['previous_lp'])) { $parameters['previous_lp'] = (int)$data['previous_lp']; }
            if (isset($data['current_lp'])) { $parameters['lp'] = (int)$data['current_lp']; }
        }

        return [
            'seller_id' => $seller_id,
            'external_id' => $external_id,
            'api_source' => 1,
            'api_created_at' => date('Y-m-d H:i:s'),
            'api_updated_at' => date('Y-m-d H:i:s'),
            'title' => $title,
            'slug' => strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $title . '-' . substr(sha1($external_id . microtime(true)), 0, 6)), '-')),
            'price' => $price,
            'game' => $data['game'] ?? 'lol',
            'rank' => $rankId,
            'rank_label' => $rankLabel,
            'current_rank' => $rankId,
            'current_division' => $divisionId,
            'current_lp' => $currentLp,
            'flex_rank' => $flexRankId,
            'flex_division' => $flexDivisionId,
            'flex_lp' => $flexLp,
            'previous_rank' => $previousRankId,
            'previous_division' => $previousDivisionId,
            'previous_lp' => $previousLp,
            'server' => $data['server'] ?? null,
            'description' => $data['description'] ?? null,
            'game_data' => !empty($parameters) ? json_encode($parameters, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : null,
            'images' => !empty($galleryUrls) ? json_encode($galleryUrls, JSON_UNESCAPED_SLASHES) : (!empty($data['image_urls']) ? json_encode($data['image_urls'], JSON_UNESCAPED_SLASHES) : null),
            'gallery_image_ids' => !empty($imageIds) ? json_encode(array_values($imageIds)) : null,
            'delivery_type' => !empty($data['is_manual_delivery']) ? 'manual' : ($data['delivery_type'] ?? 'instant'),
            'login' => $data['credentials']['login'] ?? ($data['login'] ?? null),
            'password' => $data['credentials']['password'] ?? ($data['password'] ?? null),
            'email' => $data['credentials']['email_login'] ?? ($data['email_login'] ?? ($data['email'] ?? null)),
            'email_password' => $data['credentials']['email_password'] ?? ($data['email_password'] ?? null),
            'in_game_name' => $data['in_game_name'] ?? null,
            'delivery_instructions' => $data['delivery_instructions'] ?? null,
            'level' => $data['level'] ?? null,
            'blue_essence' => $data['blue_essence'] ?? null,
            'riot_points' => $data['riot_points'] ?? null,
            'winrate_percent' => $data['winrate_percent'] ?? ($data['winrate'] ?? null),
            'champions' => is_array($data['champions'] ?? null) ? implode('|', $data['champions']) : ($data['champions'] ?? null),
            'skins' => is_array($data['skins'] ?? null) ? implode('|', $data['skins']) : ($data['skins'] ?? null),
            'roles' => is_array($data['roles'] ?? null) ? implode('|', $data['roles']) : ($data['roles'] ?? null),
            'champion_count' => $data['champion_count'] ?? null,
            'skin_count' => $data['skin_count'] ?? null,
            'active' => $active,
            'sold' => 0,
            'created_at' => date('Y-m-d H:i:s'),
        ];
    }

    public function seller_import_upload_json()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $batch_id = (int)($_POST['batch_id'] ?? 0);
        $batch = $db->row('SELECT * FROM seller_account_import_batches WHERE id = ? AND seller_id = ? LIMIT 1', $batch_id, $seller_id);
        if (empty($batch)) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Import not found.']]); return; }

        try {
            if (empty($_FILES['json_file']) || ($_FILES['json_file']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) { throw new \RuntimeException('Please upload a JSON file.'); }
            if ((int)($_FILES['json_file']['size'] ?? 0) > 5 * 1024 * 1024) { throw new \RuntimeException('JSON file must be smaller than 5 MB.'); }
            $raw = file_get_contents((string)$_FILES['json_file']['tmp_name']);
            $decoded = json_decode($raw ?: '', true);
            if (!is_array($decoded)) { throw new \RuntimeException('Invalid JSON format.'); }
            $accounts = $decoded['accounts'] ?? $decoded;
            if (!is_array($accounts) || empty($accounts)) { throw new \RuntimeException('JSON must contain an accounts array.'); }
            if (count($accounts) > 1000) { throw new \RuntimeException('Maximum 1000 accounts per import.'); }

            $db->run('DELETE FROM seller_account_import_rows WHERE batch_id = ? AND seller_id = ? AND account_id IS NULL', $batch_id, $seller_id);
            $total = 0;
            foreach (array_values($accounts) as $idx => $row) {
                if (!is_array($row)) { continue; }
                $externalId = trim((string)($row['external_id'] ?? ''));
                if (empty($row['game'])) { $row['game'] = $batch['game'] ?? 'lol'; }
                $ids = [];
                if (!empty($row['image_ids']) && is_array($row['image_ids'])) { $ids = array_values(array_unique(array_filter(array_map('intval', $row['image_ids'])))); }
                db_add_row('seller_account_import_rows', [
                    'batch_id' => $batch_id,
                    'seller_id' => $seller_id,
                    'external_id' => $externalId,
                    'status' => 'draft',
                    'message' => 'Ready for review.',
                    'row_data' => json_encode($row, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                    'image_ids' => !empty($ids) ? json_encode($ids) : null,
                    'image_urls' => null,
                ]);
                $total++;
            }
            db_update_row('seller_account_import_batches', ['id' => $batch_id, 'seller_id' => $seller_id], [
                'filename' => substr((string)($_FILES['json_file']['name'] ?? 'accounts.json'), 0, 255),
                'total_rows' => $total,
                'status' => 'review',
                'created_count' => 0,
                'updated_count' => 0,
                'skipped_count' => 0,
                'failed_count' => 0,
            ]);
            $this->seller_import_json_response(['sendToast' => ['type' => 'success', 'title' => 'JSON loaded', 'message' => $total . ' account(s) loaded for review.'], 'playSound' => 'success', 'refreshPage' => true]);
        } catch (\Throwable $e) {
            $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'title' => 'Upload failed', 'message' => $e->getMessage()]]);
        }
    }

    public function seller_import_row_upload_images()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $row_id = (int)($_POST['row_id'] ?? 0);
        $row = $db->row('SELECT * FROM seller_account_import_rows WHERE id = ? AND seller_id = ? LIMIT 1', $row_id, $seller_id);
        if (empty($row)) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Row not found.']]); return; }

        try {
            $uploaded = [];
            if (!empty($_FILES['images']) && is_array($_FILES['images']['name'])) {
                $count = count($_FILES['images']['name']);
                for ($i = 0; $i < $count; $i++) {
                    if (($_FILES['images']['error'][$i] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) { continue; }
                    $file = ['name'=>$_FILES['images']['name'][$i] ?? '', 'type'=>$_FILES['images']['type'][$i] ?? '', 'tmp_name'=>$_FILES['images']['tmp_name'][$i] ?? '', 'error'=>$_FILES['images']['error'][$i] ?? UPLOAD_ERR_NO_FILE, 'size'=>$_FILES['images']['size'][$i] ?? 0];
                    $uploaded[] = seller_gallery_upload_file($file, $seller_id);
                }
            }
            if (empty($uploaded)) { throw new \RuntimeException('Please select at least one image.'); }
            $existingIds = json_decode((string)($row['image_ids'] ?? '[]'), true);
            if (!is_array($existingIds)) { $existingIds = []; }
            $newIds = array_column($uploaded, 'id');
            $imageIds = array_values(array_unique(array_merge(array_map('intval', $existingIds), array_map('intval', $newIds))));
            $imageRows = seller_gallery_images_by_ids($seller_id, $imageIds);
            $finalIds = array_map(fn($r) => (int)$r['id'], $imageRows);
            $urls = array_map(fn($r) => $r['url'], $imageRows);
            $data = json_decode((string)($row['row_data'] ?? '{}'), true);
            if (!is_array($data)) { $data = []; }
            $data['image_ids'] = $finalIds;
            db_update_row('seller_account_import_rows', ['id' => $row_id, 'seller_id' => $seller_id], [
                'row_data' => json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                'image_ids' => json_encode($finalIds),
                'image_urls' => json_encode($urls, JSON_UNESCAPED_SLASHES),
                'message' => count($finalIds) . ' image(s) assigned.',
            ]);
            $this->seller_import_json_response([
                'sendToast' => ['type' => 'success', 'title' => 'Images added', 'message' => count($uploaded) . ' image(s) uploaded.'],
                'playSound' => 'success',
                'row_id' => $row_id,
                'images' => array_map('seller_api_public_gallery_image', $imageRows),
            ]);
        } catch (\Throwable $e) {
            $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'title' => 'Image upload failed', 'message' => $e->getMessage()]]);
        }
    }

    public function seller_import_row_set_images()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
