        if (empty($row)) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Row not found.']]); return; }

        $ids = $_POST['image_ids'] ?? [];
        if (!is_array($ids)) { $ids = []; }
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids), fn($v) => $v > 0)));

        try {
            // seller_gallery_images_by_ids re-validates ownership and preserves the given order via ORDER BY FIELD().
            $imageRows = empty($ids) ? [] : seller_gallery_images_by_ids($seller_id, $ids);
            $finalIds = array_map(fn($r) => (int)$r['id'], $imageRows);
            $urls = array_map(fn($r) => $r['url'], $imageRows);
            $data = json_decode((string)($row['row_data'] ?? '{}'), true);
            if (!is_array($data)) { $data = []; }
            $data['image_ids'] = $finalIds;
            db_update_row('seller_account_import_rows', ['id' => $row_id, 'seller_id' => $seller_id], [
                'row_data' => json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                'image_ids' => json_encode($finalIds),
                'image_urls' => json_encode($urls, JSON_UNESCAPED_SLASHES),
                'message' => count($finalIds) . ' image(s) assigned.',
            ]);
            $this->seller_import_json_response([
                'sendToast' => ['type' => 'success', 'title' => 'Images updated', 'message' => count($finalIds) . ' image(s).'],
                'row_id' => $row_id,
                'images' => array_map('seller_api_public_gallery_image', $imageRows),
            ]);
        } catch (\Throwable $e) {
            $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'title' => 'Could not update images', 'message' => $e->getMessage()]]);
        }
    }

    public function seller_import_save_rows()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $batch_id = (int)($_POST['batch_id'] ?? 0);
        $batch = $db->row('SELECT * FROM seller_account_import_batches WHERE id = ? AND seller_id = ? LIMIT 1', $batch_id, $seller_id);
        if (empty($batch)) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Import not found.']]); return; }

        $rows = $_POST['rows'] ?? [];
        if (!is_array($rows) || empty($rows)) { $this->seller_import_json_response(['sendToast' => ['type' => 'warning', 'message' => 'Nothing to save.']]); return; }

        $editableKeys = [
            'external_id', 'title', 'slug', 'game', 'server', 'price',
            'rank', 'division', 'current_rank', 'current_division', 'current_lp',
            'flex_rank', 'flex_division', 'flex_lp',
            'previous_rank', 'previous_division', 'previous_lp',
            'level_up_method', 'level', 'blue_essence', 'riot_points', 'winrate_percent',
            'champion_count', 'skin_count', 'val_agent_count', 'roles',
            'email', 'in_game_name', '2fa', 'delivery_type', 'delivery_instructions',
            'description', 'active', 'status'
        ];
        $credentialKeys = ['login', 'password', 'email_login', 'email_password'];
        $saved = 0;

        foreach ($rows as $rowId => $fields) {
            $rowId = (int)$rowId;
            if ($rowId <= 0 || !is_array($fields)) { continue; }
            $existingRow = $db->row('SELECT * FROM seller_account_import_rows WHERE id = ? AND batch_id = ? AND seller_id = ? LIMIT 1', $rowId, $batch_id, $seller_id);
            if (empty($existingRow)) { continue; }

            $data = json_decode((string)($existingRow['row_data'] ?? '{}'), true);
            if (!is_array($data)) { $data = []; }

            foreach ($editableKeys as $key) {
                if (array_key_exists($key, $fields)) {
                    $val = trim((string)$fields[$key]);
                    $data[$key] = $val;
                }
            }

            if (array_key_exists('is_manual_delivery', $fields)) {
                $data['is_manual_delivery'] = !empty($fields['is_manual_delivery']) && $fields['is_manual_delivery'] !== '0' ? 1 : 0;
            }

            // Credentials: keep both flat and nested in sync so the import payload builder picks them up either way.
            $hasCredEdit = false;
            foreach ($credentialKeys as $key) {
                if (array_key_exists($key, $fields)) { $hasCredEdit = true; break; }
            }
            if ($hasCredEdit) {
                foreach ($credentialKeys as $key) {
                    $val = trim((string)($fields[$key] ?? ($data['credentials'][$key] ?? ($data[$key] ?? ''))));
                    $data[$key] = $val;
                    $data['credentials'][$key] = $val;
                }
            }

            $newExternalId = trim((string)($data['external_id'] ?? $existingRow['external_id'] ?? ''));

            db_update_row('seller_account_import_rows', ['id' => $rowId, 'seller_id' => $seller_id], [
                'external_id' => $newExternalId,
                'row_data' => json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                'message' => 'Edited manually. Ready for review.',
            ]);
            $saved++;
        }

        $this->seller_import_json_response([
            'sendToast' => ['type' => 'success', 'title' => 'Changes saved', 'message' => $saved . ' account(s) updated.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_import_all_accounts()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $batch_id = (int)($_POST['batch_id'] ?? 0);
        $updateExisting = !empty($_POST['update_existing']);
        $batch = $db->row('SELECT * FROM seller_account_import_batches WHERE id = ? AND seller_id = ? LIMIT 1', $batch_id, $seller_id);
        if (empty($batch)) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Import not found.']]); return; }
        $rows = $db->run("SELECT * FROM seller_account_import_rows WHERE batch_id = ? AND seller_id = ? ORDER BY id ASC", $batch_id, $seller_id) ?: [];
        if (empty($rows)) { $this->seller_import_json_response(['sendToast' => ['type' => 'warning', 'message' => 'Upload a JSON file first.']]); return; }

        $created = $updated = $skipped = $failed = 0;
        foreach ($rows as $row) {
            $rowStatus = 'failed'; $message = ''; $accountId = null;
            $externalId = trim((string)($row['external_id'] ?? ''));
            try {
                $data = json_decode((string)($row['row_data'] ?? '{}'), true);
                if (!is_array($data)) { throw new \RuntimeException('Invalid staged row data.'); }
                if (!empty($row['image_ids'])) {
                    $ids = json_decode((string)$row['image_ids'], true);
                    if (is_array($ids)) { $data['image_ids'] = array_values(array_unique(array_filter(array_map('intval', $ids)))); }
                }
                $err = null;
                $payload = $this->seller_import_account_payload($seller_id, $data, $err);
                if ($err) { throw new \RuntimeException($err); }
                $externalId = trim((string)$payload['external_id']);
                $existing = $db->row('SELECT * FROM selling_accounts WHERE seller_id = ? AND external_id = ? LIMIT 1', $seller_id, $externalId);

                if (!empty($existing) && !$updateExisting) {
                    $rowStatus = 'skipped'; $message = 'external_id already exists.'; $accountId = (int)$existing['id']; $skipped++;
                } elseif (!empty($existing) && $updateExisting) {
                    unset($payload['seller_id'], $payload['external_id'], $payload['api_created_at'], $payload['created_at'], $payload['sold']);
                    $payload['api_updated_at'] = date('Y-m-d H:i:s');
                    db_update_row('selling_accounts', ['id' => (int)$existing['id'], 'seller_id' => $seller_id], $payload);
                    $accountId = (int)$existing['id']; $rowStatus = 'updated'; $message = 'Account updated.'; $updated++;
                    $updatedAccount = $db->row('SELECT * FROM selling_accounts WHERE id = ? AND seller_id = ? LIMIT 1', $accountId, $seller_id);
                    if (function_exists('seller_api_dispatch_webhook') && !empty($updatedAccount)) { seller_api_dispatch_webhook('account.updated', $updatedAccount); }
                } else {
                    $accountId = (int)db_add_row('selling_accounts', $payload);
                    $rowStatus = 'created'; $message = 'Account created.'; $created++;
                    $createdAccount = $db->row('SELECT * FROM selling_accounts WHERE id = ? AND seller_id = ? LIMIT 1', $accountId, $seller_id);
                    if (function_exists('seller_api_dispatch_webhook') && !empty($createdAccount)) {
                        seller_api_dispatch_webhook('account.created', $createdAccount);
                        if ((int)($createdAccount['active'] ?? 0) === 1) { seller_api_dispatch_webhook('account.listed', $createdAccount); }
                    }
                }
            } catch (\Throwable $e) {
                $failed++; $message = $e->getMessage(); $rowStatus = 'failed';
            }
            db_update_row('seller_account_import_rows', ['id' => (int)$row['id'], 'seller_id' => $seller_id], [
                'account_id' => $accountId,
                'external_id' => $externalId,
                'status' => $rowStatus,
                'message' => $message,
            ]);
        }

        db_update_row('seller_account_import_batches', ['id' => $batch_id, 'seller_id' => $seller_id], [
            'status' => $failed > 0 ? 'completed_with_errors' : 'completed',
            'total_rows' => count($rows),
            'created_count' => $created,
            'updated_count' => $updated,
            'skipped_count' => $skipped,
            'failed_count' => $failed,
            'update_existing' => $updateExisting ? 1 : 0,
        ]);

        $this->seller_import_json_response([
            'sendToast' => ['type' => $failed > 0 ? 'warning' : 'success', 'title' => 'Import finished', 'message' => "Created: {$created}, updated: {$updated}, skipped: {$skipped}, failed: {$failed}"],
            'playSound' => $failed > 0 ? null : 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_import_delete_batch()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $this->seller_import_ensure_tables();
        global $db;
        $seller_id = (int)$this->seller_data['id'];
        $batch_id = (int)($_POST['batch_id'] ?? 0);
        $db->run('DELETE FROM seller_account_import_rows WHERE batch_id = ? AND seller_id = ?', $batch_id, $seller_id);
        $db->run('DELETE FROM seller_account_import_batches WHERE id = ? AND seller_id = ?', $batch_id, $seller_id);
        $this->seller_import_json_response(['sendToast' => ['type' => 'success', 'message' => 'Import deleted.'], 'redirectUrl' => BASE_URL . '/seller-area/import-accounts']);
    }


    private function seller_listing_import_ensure_tables(): void
    {
        global $db;
        $db->run("CREATE TABLE IF NOT EXISTS seller_listing_import_batches (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,seller_id INT UNSIGNED NOT NULL,entity_type VARCHAR(20) NOT NULL,game_slug VARCHAR(191) NULL,import_name VARCHAR(191) NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',total_rows INT UNSIGNED NOT NULL DEFAULT 0,created_count INT UNSIGNED NOT NULL DEFAULT 0,updated_count INT UNSIGNED NOT NULL DEFAULT 0,skipped_count INT UNSIGNED NOT NULL DEFAULT 0,failed_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,KEY idx_slie_seller_entity (seller_id,entity_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $cols=$db->run("SHOW COLUMNS FROM seller_listing_import_batches LIKE 'game_slug'"); if(!$cols){$db->run("ALTER TABLE seller_listing_import_batches ADD COLUMN game_slug VARCHAR(191) NULL AFTER entity_type");}
        try { $db->run("UPDATE seller_listing_import_batches b SET b.game_slug=(SELECT JSON_UNQUOTE(JSON_EXTRACT(r.row_data,'$.game')) FROM seller_listing_import_rows r WHERE r.batch_id=b.id AND r.seller_id=b.seller_id AND JSON_UNQUOTE(JSON_EXTRACT(r.row_data,'$.game')) IS NOT NULL LIMIT 1) WHERE (b.game_slug IS NULL OR b.game_slug='')"); } catch (\Throwable $e) {}
        $db->run("CREATE TABLE IF NOT EXISTS seller_listing_import_rows (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,batch_id INT UNSIGNED NOT NULL,seller_id INT UNSIGNED NOT NULL,entity_type VARCHAR(20) NOT NULL,external_id VARCHAR(191) NULL,row_data LONGTEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',message TEXT NULL,listing_id INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_slir_batch (batch_id,seller_id),KEY idx_slir_external (seller_id,entity_type,external_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    }

    private function seller_listing_import_entity(): string
    {
        $entity = strtolower(trim((string)($_POST['entity'] ?? 'items')));
        return $entity === 'topups' ? 'topups' : 'items';
    }

    private function seller_listing_import_redirect(string $entity, int $id = 0): string
    {
        return BASE_URL . '/seller-area/' . ($entity === 'topups' ? 'import-top-ups' : 'import-items') . ($id > 0 ? '?id=' . $id : '');
    }

    public function seller_listing_import_create_batch()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $this->seller_listing_import_ensure_tables(); global $db;
        $entity=$this->seller_listing_import_entity(); $seller=(int)$this->seller_data['id'];
        $game=trim((string)($_POST['game_slug']??($_POST['game']??''))); $name=trim((string)($_POST['name']??'')); if($name===''){$name=($entity==='topups'?'Top Up':'Item').' Import '.date('Y-m-d H:i');}
        $schemaTable = $entity === 'topups' ? 'game_topup_schemas' : 'game_item_schemas';
        $gameRow = null;
        if ($game !== '') {
            $gameRow = $db->row("SELECT g.id,g.slug,g.name,g.icon FROM games g INNER JOIN {$schemaTable} s ON s.game_slug=g.slug WHERE g.status=1 AND s.enabled=1 AND (g.slug=? OR g.id=?) LIMIT 1", $game, ctype_digit($game) ? (int)$game : 0);
        }
        if (!$gameRow) {
            $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Please select a valid game for this import.']]);
            return;
        }
        $game = (string)$gameRow['slug'];
        $id=(int)db_add_row('seller_listing_import_batches',['seller_id'=>$seller,'entity_type'=>$entity,'game_slug'=>$game,'import_name'=>$name,'status'=>'draft']);
        $this->seller_import_json_response(['sendToast'=>['type'=>'success','message'=>'Import created.'],'redirectUrl'=>$this->seller_listing_import_redirect($entity,$id)]);
    }

    public function seller_listing_import_upload_json()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $this->seller_listing_import_ensure_tables(); global $db;
        $entity=$this->seller_listing_import_entity(); $seller=(int)$this->seller_data['id']; $batch=(int)($_POST['batch_id']??0);
        $found=$db->row('SELECT * FROM seller_listing_import_batches WHERE id=? AND seller_id=? AND entity_type=? LIMIT 1',$batch,$seller,$entity);
        if(!$found){$this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Import not found.']]);return;}
        $raw=trim((string)($_POST['json_text']??''));
        if(!empty($_FILES['json_file']['tmp_name'])){$raw=(string)file_get_contents($_FILES['json_file']['tmp_name']);}
        $data=json_decode($raw,true); if(isset($data['data'])&&is_array($data['data'])){$data=$data['data'];} if(isset($data[$entity])&&is_array($data[$entity])){$data=$data[$entity];} if($entity==='topups'&&isset($data['top_ups'])&&is_array($data['top_ups'])){$data=$data['top_ups'];}
        if(!is_array($data) || array_is_list($data)===false){$this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'JSON must be an array of listings.']]);return;}
        $db->run('DELETE FROM seller_listing_import_rows WHERE batch_id=? AND seller_id=?',$batch,$seller);
        $batchGame=trim((string)($found['game_slug']??'')); $count=0; foreach($data as $row){if(!is_array($row))continue;if($batchGame!==''&&empty($row['game']))$row['game']=$batchGame;$external=trim((string)($row['external_id']??''));db_add_row('seller_listing_import_rows',['batch_id'=>$batch,'seller_id'=>$seller,'entity_type'=>$entity,'external_id'=>$external,'row_data'=>json_encode($row,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'status'=>'pending']);$count++;}
        db_update_row('seller_listing_import_batches',['id'=>$batch,'seller_id'=>$seller],['status'=>'review','total_rows'=>$count]);
        $this->seller_import_json_response(['sendToast'=>['type'=>'success','message'=>$count.' listing(s) loaded.'],'refreshPage'=>true]);
    }

    public function seller_listing_import_save_rows()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $this->seller_listing_import_ensure_tables(); global $db;
        $entity=$this->seller_listing_import_entity(); $seller=(int)$this->seller_data['id']; $batch=(int)($_POST['batch_id']??0);
        $rows=json_decode((string)($_POST['rows']??'[]'),true);
        if(!is_array($rows)){ $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Invalid row data.']]); return; }
        $allowed=$db->run('SELECT id FROM seller_listing_import_rows WHERE batch_id=? AND seller_id=? AND entity_type=?',$batch,$seller,$entity)?:[];
        $allowedIds=array_fill_keys(array_map(fn($x)=>(int)$x['id'],$allowed),true); $saved=0;
        foreach($rows as $row){ $id=(int)($row['id']??0); $data=$row['data']??null; if(!$id||!isset($allowedIds[$id])||!is_array($data))continue; $external=trim((string)($data['external_id']??'')); db_update_row('seller_listing_import_rows',['id'=>$id,'seller_id'=>$seller],['external_id'=>$external,'row_data'=>json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'status'=>'pending','message'=>null]); $saved++; }
        db_update_row('seller_listing_import_batches',['id'=>$batch,'seller_id'=>$seller],['status'=>'review']);
        $this->seller_import_json_response(['sendToast'=>['type'=>'success','message'=>$saved.' row(s) saved.']]);
    }

    private function seller_listing_import_payload(string $entity, int $seller, array $d): array
    {
        $external=trim((string)($d['external_id']??'')); $title=trim((string)($d['title']??($d['offer_title']??''))); $price=(int)($d['price']??0);
        if($external===''||$title===''||$price<=0) throw new RuntimeException('external_id, title and price are required.');
        $status=in_array((string)($d['status']??'listed'),['draft','pending','listed','archived'],true)?(string)$d['status']:'listed'; $now=date('Y-m-d H:i:s');
        if($entity==='items') return ['seller_id'=>$seller,'external_id'=>$external,'api_source'=>1,'api_created_at'=>$now,'api_updated_at'=>$now,'game'=>$d['game']??'league-of-legends','type'=>$d['type']??'gifting','title'=>$title,'slug'=>strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$title.'-'.substr(sha1($external.microtime(true)),0,6)),'-')),'description'=>$d['description']??null,'delivery_instructions'=>$d['delivery_instructions']??null,'images'=>!empty($d['image_urls'])?json_encode($d['image_urls'],JSON_UNESCAPED_SLASHES):(!empty($d['images'])?json_encode($d['images'],JSON_UNESCAPED_SLASHES):null),'price_type'=>$d['price_type']??'fixed','price'=>$price,'currency'=>$d['currency']??'EUR','server'=>$d['server']??'EUW','delivery_type'=>'manual','requires_friendship_days'=>(int)($d['requires_friendship_days']??7),'stock'=>(int)($d['stock']??1),'min_purchase_qty'=>(int)($d['min_purchase_qty']??1),'max_purchase_qty'=>isset($d['max_purchase_qty'])?(int)$d['max_purchase_qty']:null,'active'=>$status==='listed'?1:0,'sold_count'=>0,'sort_order'=>(int)($d['sort_order']??0),'created_at'=>$now,'updated_at'=>$now];
        if(function_exists('lb_topups_table_ensure'))lb_topups_table_ensure(); $slug=strtolower(trim((string)($d['game']??'league-of-legends'))); $g=function_exists('util_get_game_by_slug')?(util_get_game_by_slug($slug)?:[]):[]; $unit=strtolower(trim((string)($d['waiting_time_unit']??'minutes')));if(!in_array($unit,['minutes','hours','days'],true))$unit='minutes';$wv=(int)($d['waiting_time_value']??10);$wm=function_exists('seller_api_topup_waiting_minutes')?seller_api_topup_waiting_minutes($wv,$unit):($unit==='days'?$wv*1440:($unit==='hours'?$wv*60:$wv));
        return ['seller_id'=>$seller,'external_id'=>$external,'api_source'=>1,'api_created_at'=>$now,'api_updated_at'=>$now,'game_id'=>(int)($g['id']??0)?:null,'game_slug'=>$slug,'game_name'=>$d['game_name']??($g['name']??ucwords(str_replace('-',' ',$slug))),'service_label'=>$d['service_label']??null,'offer_key'=>$d['offer_key']??null,'offer_title'=>$title,'offer_amount'=>isset($d['amount'])?(float)$d['amount']:(isset($d['offer_amount'])?(float)$d['offer_amount']:null),'offer_unit'=>$d['unit']??($d['offer_unit']??null),'region'=>$d['region']??null,'platform'=>$d['platform']??null,'price'=>$price,'currency'=>$d['currency']??'EUR','stock'=>(int)($d['stock']??999),'min_quantity'=>(int)($d['min_quantity']??1),'waiting_time_value'=>$wv,'waiting_time_unit'=>$unit,'waiting_time_minutes'=>$wm,'instructions'=>$d['instructions']??null,'image'=>$d['image_url']??($d['image']??null),'active'=>$status==='listed'?1:0,'sold_count'=>0,'created_at'=>$now,'updated_at'=>$now];
    }

    public function seller_listing_import_run()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $this->seller_listing_import_ensure_tables(); global $db; $entity=$this->seller_listing_import_entity();$seller=(int)$this->seller_data['id'];$batch=(int)($_POST['batch_id']??0);$update=!empty($_POST['update_existing']);
        $rows=$db->run('SELECT * FROM seller_listing_import_rows WHERE batch_id=? AND seller_id=? AND entity_type=? ORDER BY id',$batch,$seller,$entity)?:[]; $table=$entity==='items'?'selling_items':'selling_topups';$created=$updated=$skipped=$failed=0;
        foreach($rows as $r){$status='failed';$msg='';$listingId=null;try{$d=json_decode((string)$r['row_data'],true);if(!is_array($d))throw new RuntimeException('Invalid row.');$p=$this->seller_listing_import_payload($entity,$seller,$d);$existing=$db->row("SELECT * FROM {$table} WHERE seller_id=? AND external_id=? LIMIT 1",$seller,$p['external_id']);if($existing&&!$update){$status='skipped';$msg='external_id already exists.';$listingId=(int)$existing['id'];$skipped++;}elseif($existing){unset($p['seller_id'],$p['external_id'],$p['api_created_at'],$p['created_at'],$p['sold_count']);$p['api_updated_at']=date('Y-m-d H:i:s');db_update_row($table,['id'=>(int)$existing['id'],'seller_id'=>$seller],$p);$listingId=(int)$existing['id'];$status='updated';$msg='Listing updated.';$updated++;}else{$listingId=(int)db_add_row($table,$p);$status='created';$msg='Listing created.';$created++;}}catch(Throwable $e){$failed++;$msg=$e->getMessage();}db_update_row('seller_listing_import_rows',['id'=>(int)$r['id'],'seller_id'=>$seller],['listing_id'=>$listingId,'status'=>$status,'message'=>$msg]);}
        db_update_row('seller_listing_import_batches',['id'=>$batch,'seller_id'=>$seller],['status'=>$failed?'completed_with_errors':'completed','total_rows'=>count($rows),'created_count'=>$created,'updated_count'=>$updated,'skipped_count'=>$skipped,'failed_count'=>$failed]);
        if (($created > 0 || $updated > 0) && function_exists('trigger_notification_sender_async')) {
            @trigger_notification_sender_async();
        }
        $this->seller_import_json_response(['sendToast'=>['type'=>$failed?'warning':'success','title'=>'Import finished','message'=>"Created: {$created}, updated: {$updated}, skipped: {$skipped}, failed: {$failed}"],'refreshPage'=>true]);
    }

    public function seller_listing_import_delete_batch()
    {
        if (!$this->is_seller) { $this->seller_import_json_response(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $this->seller_listing_import_ensure_tables();global $db;$entity=$this->seller_listing_import_entity();$seller=(int)$this->seller_data['id'];$batch=(int)($_POST['batch_id']??0);$db->run('DELETE FROM seller_listing_import_rows WHERE batch_id=? AND seller_id=?',$batch,$seller);$db->run('DELETE FROM seller_listing_import_batches WHERE id=? AND seller_id=? AND entity_type=?',$batch,$seller,$entity);$this->seller_import_json_response(['sendToast'=>['type'=>'success','message'=>'Import deleted.'],'redirectUrl'=>$this->seller_listing_import_redirect($entity)]);
    }

    public function seller_register()
    {
        global $db;
        $username = trim($_POST['username'] ?? '');
        $email    = strtolower(trim($_POST['email'] ?? ''));
        $password = trim($_POST['password'] ?? '');
        $discord  = trim($_POST['discord'] ?? '');
        $note     = trim($_POST['note'] ?? '');

        if (!$username || !$email || !$password) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Username, email and password are required.']]);
            return;
        }
        if (strlen($password) < 8) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Password must be at least 8 characters.']]);
            return;
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid email address.']]);
            return;
        }

        // Ensure extended columns exist
        $this->ensure_selling_schema();
        try { $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS discord VARCHAR(191) NULL"); } catch (\Throwable $e) {}
        try { $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS application_note TEXT NULL"); } catch (\Throwable $e) {}

        $existing = $db->row("SELECT id FROM sellers WHERE email = ? LIMIT 1", $email);
        if (!empty($existing)) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Already exists', 'message' => 'An account with this email already exists.']]);
            return;
        }

        try {
            $seller_id = $db->insert('sellers', [
                'username'         => $username,
                'email'            => $email,
                'password'         => sha1($password),
                'discord'          => $discord ?: null,
                'fee_percent'      => null,
                'balance'          => 0,
                'is_active'        => 0,
                'is_banned'        => 0,
                'application_note' => $note ?: null,
            ]);
        } catch (\Throwable $e) {
            // Fallback without new columns
            $seller_id = $db->insert('sellers', [
                'username'    => $username,
                'email'       => $email,
                'password'    => sha1($password),
                'fee_percent' => null,
                'balance'     => 0,
                'is_banned'   => 0,
            ]);
        }

        if (!$seller_id) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Registration failed. Please try again.']]);
            return;
        }

        try { log_admin_action(0, "New seller application #{$seller_id}: {$username} ({$email})"); } catch (\Throwable $e) {}

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Application Submitted!', 'message' => 'We will review your application and contact you via email.'],
            'playSound'   => 'success',
            'redirectUrl' => BASE_URL . '/seller-area/auth/login?applied=1',
        ]);
    }

