    public function egirl_book_service()
    {
        $service_id = (int)($_POST['service_id'] ?? 0);
        $notes      = esc($_POST['notes'] ?? '');
        $client_id  = (defined('CLIENT_ID') && CLIENT_ID) ? (int)CLIENT_ID : 0;

        if (!$service_id) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid service.']]);
            return;
        }

        global $db;

        $service = $db->row(
            "SELECT es.*, b.id AS egirl_id, b.username, b.icon AS egirl_icon, b.is_banned
             FROM egirl_services es
             LEFT JOIN boosters b ON b.id = es.egirl_id
             WHERE es.id = ? AND es.is_active = 1 AND b.is_banned = 0
             LIMIT 1",
            $service_id
        );

        if (!$service) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Service not available.']]);
            return;
        }

        $currency = $_SESSION['currency'] ?? (!empty($service['currency']) ? $service['currency'] : 'EUR');
        $price_eur = (int)$service['price_cents'];
        $price     = $price_eur;
        if ($currency === 'USD') {
            $rate = (float)get_exchange_rate();
            if ($rate > 0) {
                $price = (int) round($price_eur * $rate);
            }
        }
        $uuid     = Uuid::uuid4()->toString();

        $order_id = db_add_row('egirl_orders', [
            'client_id'     => $client_id,
            'egirl_id'      => $service['egirl_id'],
            'service_id'    => $service_id,
            'service_type'  => $service['type'],
            'service_title' => $service['title'],
            'game'          => $service['game'],
            'unit_value'    => $service['unit_value'],
            'unit_type'     => $service['unit_type'],
            'price'         => $price,
            'price_eur'     => $price_eur,
            'currency'      => $currency,
            'status'        => 'UNPAID',
            'client_notes'  => $notes,
            'created_at'    => date('Y-m-d H:i:s')
        ]);

        if (!$order_id) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create booking.']]);
            return;
        }

        $invoice_id = db_add_row('invoices', [
            'uuid'        => $uuid,
            'order_id'    => $order_id,
            'order_type'  => 'egirl_session',
            'price'       => $price,
            'price_eur'   => $price_eur,
            'total_price' => $price,
            'currency'    => $currency,
            'status'      => 'UNPAID',
            'description' => 'E-Girl Session: ' . $service['title'],
            'client_id'   => $client_id,
        ]);

        if (!$invoice_id) {
            $db->run("DELETE FROM egirl_orders WHERE id = ?", $order_id);
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create checkout invoice.']]);
            return;
        }

        db_update_row('egirl_orders', ['id' => $order_id], ['invoice_id' => $invoice_id]);

        db_add_row('egirl_notifications', [
            'egirl_id'   => $service['egirl_id'],
            'type'       => 'new_booking',
            'data'       => json_encode(['order_id' => $order_id, 'client_id' => $client_id, 'invoice_id' => $invoice_id]),
            'created_at' => date('Y-m-d H:i:s')
        ]);

        echo json_encode([
            'success'     => true,
            'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
            'sendToast'   => ['type' => 'success', 'title' => 'Booked!', 'message' => 'Your session has been booked. Complete payment to confirm.']
        ]);
    }

    public function egirl_book_lol_boost()
    {
        global $db;

        $client_id = (defined('CLIENT_ID') && CLIENT_ID) ? (int) CLIENT_ID : 0;
        $egirl_id  = (int)($_POST['selected_egirl_id'] ?? 0);
        $assignment = preg_replace('/[^a-z_]/i', '', (string)($_POST['ggirl_assignment'] ?? ''));
        $is_any_available = ($assignment === 'any_available' || $egirl_id <= 0);
        if ($is_any_available) {
            $egirl_id = 0;
        }
        $queue     = preg_replace('/[^a-z0-9_]/i', '', (string)($_POST['ggirl_queue_type'] ?? 'normal_draft'));
        $server    = preg_replace('/[^a-z0-9_\-]/i', '', (string)($_POST['server'] ?? 'euw'));
        $amount    = max(1, min(20, (int)($_POST['ggirl_amount'] ?? 1)));
        $rank      = preg_replace('/[^a-z0-9_\-]/i', '', (string)($_POST['ggirl_rank'] ?? 'unranked'));
        $notesRaw  = trim((string)($_POST['ggirl_notes'] ?? ''));

        $prices = [
            'normal_draft' => ['title' => 'Normal Draft Game', 'unit_type' => 'games', 'price' => 500],
            'swiftplay'    => ['title' => 'Swift Play', 'unit_type' => 'games', 'price' => 400],
            'aram'         => ['title' => 'ARAM', 'unit_type' => 'games', 'price' => 400],
            'solo_queue'   => ['title' => 'Solo Queue', 'unit_type' => 'games', 'price' => 600],
            'chatting'     => ['title' => '30 Minutes of Chatting', 'unit_type' => 'sessions', 'price' => 600],
            'watching'     => ['title' => 'Watching You Play', 'unit_type' => 'sessions', 'price' => 500],
        ];

        $rankModifiers = [
            'unranked' => 0, 'iron' => 0, 'bronze' => 0, 'silver' => 0, 'gold' => 0,
            'platinum' => 0, 'emerald' => 0, 'diamond' => 0, 'master' => 0,
        ];

        $pricingFile = SYS_PATH . '/public/uploads/private/boost-forms/ggirls-lol.json';
        if (is_file($pricingFile) && is_readable($pricingFile)) {
            $pricingRaw = @file_get_contents($pricingFile);
            $pricingJson = $pricingRaw !== false ? json_decode($pricingRaw, true) : null;
            if (is_array($pricingJson)) {
                if (!empty($pricingJson['modes']) && is_array($pricingJson['modes'])) {
                    $loadedPrices = [];
                    foreach ($pricingJson['modes'] as $modeKey => $modeData) {
                        if (!is_array($modeData)) continue;
                        $unit = strtolower((string)($modeData['unit'] ?? 'games'));
                        $loadedPrices[$modeKey] = [
                            'title' => (string)($modeData['title'] ?? $modeKey),
                            'unit_type' => rtrim($unit, 's') === 'session' ? 'sessions' : 'games',
                            'price' => (int)($modeData['price_cents'] ?? 0),
                        ];
                    }
                    if (!empty($loadedPrices)) {
                        $prices = $loadedPrices;
                    }
                }
                if (!empty($pricingJson['ranks']) && is_array($pricingJson['ranks'])) {
                    foreach ($pricingJson['ranks'] as $rankKey => $rankData) {
                        if (is_array($rankData)) {
                            $rankModifiers[$rankKey] = (int)($rankData['price_modifier_cents'] ?? 0);
                        }
                    }
                }
            }
        }

        if (!isset($prices[$queue])) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid GGirl mode.']]);
            return;
        }

        $egirl = null;
        if (!$is_any_available) {
            $egirl = $db->row(
                "SELECT b.id, b.username, b.icon, b.is_banned, b.egirl_cut_percent
                 FROM boosters b
                 WHERE b.id = ? AND b.is_egirl = 1 AND b.is_banned = 0 AND b.show_profile = 1
                 LIMIT 1",
                $egirl_id
            );
            if (!$egirl) {
                echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'This GGirl is not available.']]);
                return;
            }
        }

        $currency  = $_SESSION['currency'] ?? 'EUR';
        $unit_price_eur = max(0, (int)$prices[$queue]['price'] + (int)($rankModifiers[$rank] ?? 0));
        $price_eur = $unit_price_eur * $amount;
        $price     = $price_eur;
        if ($currency === 'USD') {
            $rate = (float)(function_exists('get_exchange_rate') ? get_exchange_rate() : 0);
            if ($rate > 0) {
                $price = (int)round($price_eur * $rate);
            }
        }

        $modeTitle = (string)$prices[$queue]['title'];
        $rankLabel = ucwords(str_replace('_', ' ', $rank));
        $assignmentLabel = $is_any_available ? 'Any Available' : (string)($egirl['username'] ?? 'Selected GGirl');
        $title = 'LoL GGirl: ' . $modeTitle;
        $details = [
            'type' => 'lol_ggirl_boost',
            'mode' => $queue,
            'mode_title' => $modeTitle,
            'unit_price_cents' => $unit_price_eur,
            'server' => $server,
            'amount' => $amount,
            'rank' => $rank,
            'rank_label' => $rankLabel,
            'assignment' => $is_any_available ? 'any_available' : 'selected',
            'egirl_id' => $is_any_available ? 0 : $egirl_id,
            'egirl_name' => $assignmentLabel,
            'notes' => $notesRaw,
        ];

        $client_notes = "LoL GGirl Booking\n";
        $client_notes .= "Mode: " . $modeTitle . "\n";
        $client_notes .= "Server: " . strtoupper($server) . "\n";
        $client_notes .= "Rank: " . $rankLabel . "\n";
        $client_notes .= "Amount: " . $amount . "\n";
        $client_notes .= "Assignment: " . $assignmentLabel . "\n";
        if ($notesRaw !== '') {
            $client_notes .= "Notes: " . $notesRaw . "\n";
        }
        $client_notes .= "\nDATA:" . json_encode($details, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

        $uuid = Uuid::uuid4()->toString();

        $orderData = [
            'client_id'     => $client_id,
            'egirl_id'      => $is_any_available ? 0 : $egirl_id,
            'service_id'    => 0,
            'service_type'  => 'lol_ggirl_boost',
            'service_title' => $title,
            'game'          => 'lol',
            'unit_value'    => $amount,
            'unit_type'     => $prices[$queue]['unit_type'],
            'price'         => $price,
            'price_eur'     => $price_eur,
            'currency'      => $currency,
            'status'        => 'UNPAID',
            'client_notes'  => $client_notes,
            'created_at'    => date('Y-m-d H:i:s')
        ];
        if (!$is_any_available && is_array($egirl) && array_key_exists('egirl_cut_percent', $egirl) && $egirl['egirl_cut_percent'] !== null && $egirl['egirl_cut_percent'] !== '') {
            $orderData['egirl_cut'] = (float)$egirl['egirl_cut_percent'];
        }

        $order_id = db_add_row('egirl_orders', $orderData);
        if (!$order_id) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create GGirl booking.']]);
            return;
        }

        $invoice_id = db_add_row('invoices', [
            'uuid'        => $uuid,
            'order_id'    => $order_id,
            'order_type'  => 'egirl_session',
            'price'       => $price,
            'price_eur'   => $price_eur,
            'total_price' => $price,
            'currency'    => $currency,
            'status'      => 'UNPAID',
            'description' => $title,
            'client_id'   => $client_id,
        ]);

        if (!$invoice_id) {
            $db->run("DELETE FROM egirl_orders WHERE id = ?", $order_id);
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create checkout invoice.']]);
            return;
        }

        db_update_row('egirl_orders', ['id' => $order_id], ['invoice_id' => $invoice_id]);

        if (!$is_any_available) {
            db_add_row('egirl_notifications', [
                'egirl_id'   => $egirl_id,
                'type'       => 'new_booking',
                'data'       => json_encode(['order_id' => $order_id, 'client_id' => $client_id, 'invoice_id' => $invoice_id, 'source' => 'lol_ggirl_boost']),
                'created_at' => date('Y-m-d H:i:s')
            ]);
        }

        // Discord webhook intentionally NOT sent here.
        // This function only creates the UNPAID checkout invoice.
        // The GGirl public Discord "new order" webhook is created after payment
        // inside process_order() when the invoice/order becomes PAID.

        echo json_encode([
            'success'     => true,
            'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
            'sendToast'   => ['type' => 'success', 'title' => 'Booked!', 'message' => 'Your GGirl booking has been created. Complete payment to confirm.']
        ]);
    }

    /**
     * CLIENT: Send message in egirl order chat
     */
    public function client_egirl_chat_send()
    {
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $message  = trim((string)($_POST['message'] ?? ''));

        if ($order_id <= 0) {
            echo json_encode(['success' => false]); return;
        }

        // Verify order belongs to this client
        global $db;
        $order = $db->row(
            "SELECT id, egirl_id, status FROM egirl_orders WHERE id = ? AND client_id = ? LIMIT 1",
            $order_id, (int) CLIENT_ID
        );

        if (!$order || in_array(strtoupper($order['status'] ?? ''), ['UNPAID', 'CANCELLED', 'REFUNDED'])) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'warning', 'title' => 'Not allowed']]);
            return;
        }

        // Handle image upload
        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
        }

        if ($message === '' && !$image_url) {
            echo json_encode(['success' => false]); return;
        }

        $now = time();
        if ($message !== '') {
            chat_insert_message('eg_' . $order_id, ['message' => $message, 'message_type' => 'text'], CLIENT_DATA, 'client');
        }
        if ($image_url) {
            chat_insert_message('eg_' . $order_id, ['message' => $image_url, 'message_type' => 'image'], CLIENT_DATA, 'client');
        }

        if (function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('chat_update', 'eg_' . $order_id);
        }

        // Notify egirl (best-effort, table may not exist yet)
        try {
            $db->run(
                "INSERT INTO egirl_notifications (egirl_id, type, data, created_at)
                 VALUES (?, 'new_message', ?, NOW())",
                (int)$order['egirl_id'],
                json_encode(['order_id' => $order_id, 'client_id' => (int) CLIENT_ID])
            );
        } catch (\Throwable $e) { /* ignore if table missing */ }

        $this->add_egirl_site_notification('egirl_new_message', (int)$order['egirl_id'], [
            'order_id' => $order_id,
            'egirl_id' => (int)$order['egirl_id'],
            'client_id' => (int)CLIENT_ID,
            'sender_type' => 'client',
            'sender_name' => (string)(CLIENT_DATA['username'] ?? 'Client'),
        ]);

        echo json_encode(['success' => true, 'time' => $now, 'image_url' => $image_url]);
    }

    /**
     * CLIENT: Poll new messages in egirl order chat (after a given unix timestamp)
     */
    public function client_egirl_chat_poll()
    {
        if (!$this->is_client) {
            echo json_encode(['messages' => []]);
            return;
        }

        $order_id   = (int)($_GET['order_id'] ?? $_POST['order_id'] ?? 0);
        $after_time = (int)($_GET['after_time'] ?? $_POST['after_time'] ?? 0);

        if ($order_id <= 0) {
            echo json_encode(['messages' => []]);
            return;
        }

        // Verify ownership
        global $db;
        $order = $db->row(
            "SELECT id FROM egirl_orders WHERE id = ? AND client_id = ? LIMIT 1",
            $order_id, (int) CLIENT_ID
        );

        if (!$order) {
            echo json_encode(['messages' => []]);
            return;
        }

        $chat_raw  = chat_load_messages('eg_' . $order_id);
        $chat_prep = chat_prepare_for_viewer($chat_raw, 'client');
        $all       = $chat_prep['messages'] ?? [];

        // Filter to only messages newer than after_time
        $new = array_values(array_filter($all, function ($m) use ($after_time) {
            return (int)($m['time'] ?? 0) > $after_time;
        }));

        echo json_encode(['messages' => $new]);
    }

    
    public function egirl_send_message()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['success' => false]); return; }
        $order_id = (int)($_POST['order_id'] ?? 0);
        $message  = trim((string)($_POST['message'] ?? ''));
        if ($order_id <= 0) { echo json_encode(['success' => false]); return; }
