    public function client_egirl_report_problem()
    {
        if (!$this->is_client) { echo json_encode(['success' => false]); return; }
        $order_id = (int)($_POST['order_id'] ?? 0);
        $reason   = trim((string)($_POST['reason'] ?? ''));
        $details  = trim((string)($_POST['details'] ?? ''));
        if ($order_id <= 0 || $reason === '') { echo json_encode(['success' => false, 'sendToast' => ['type' => 'warning', 'title' => 'Please select a reason']]); return; }
        global $db;
        $order = $db->row("SELECT eo.*, b.username AS egirl_username FROM egirl_orders eo LEFT JOIN boosters b ON b.id = eo.egirl_id WHERE eo.id = ? AND eo.client_id = ? LIMIT 1", $order_id, (int) CLIENT_ID);
        if (!$order) { echo json_encode(['success' => false]); return; }
        $clientName = CLIENT_DATA['username'] ?? 'Unknown';
        $egirlName  = $order['egirl_username'] ?? '--';
        $status     = $order['status'] ?? '--';
        $price      = number_format((int)($order['price'] ?? 0) / 100, 2);
        // Keep problem reports beside the order-drop notifications instead of
        // sending them to the retired E-Girl report channel.
        $webhookUrl = lb_booster_notification_webhook_url('order_drop');
        $data = ['username' => 'E-Girl Report', 'avatar_url' => 'https://lolboost.gg/public/uploads/icons/default1.png',
            'embeds' => [['title' => 'Problem Report E-Girl Booking #eg' . $order_id, 'color' => 0xEC4899,
                'fields' => [['name' => 'Client',  'value' => $clientName . ' (ID: ' . ((int)CLIENT_ID) . ')', 'inline' => true],
                    ['name' => 'E-Girl',  'value' => $egirlName, 'inline' => true],
                    ['name' => 'Order',   'value' => '#eg' . $order_id . ' | ' . $status . ' | EUR ' . $price, 'inline' => false],
                    ['name' => 'Reason',  'value' => $reason, 'inline' => false],
                    ['name' => 'Details', 'value' => $details !== '' ? $details : '--', 'inline' => false]],
                'timestamp' => date('c')]]];
        if (function_exists('curl_init')) {
            $ch = curl_init($webhookUrl);
            curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
            curl_setopt($ch, CURLOPT_POST, 1);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
            curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1); curl_setopt($ch, CURLOPT_HEADER, 0);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_TIMEOUT, 5);
            curl_exec($ch); curl_close($ch);
        }
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Report sent!', 'message' => 'Our team will review your issue shortly.']]);
    }



    public function admin_remove_egirl_from_order()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order ID'],
                'playSound' => 'error',
            ]);
            return;
        }

        global $db;
        $order = $db->row(
            "SELECT eo.*, b.username AS egirl_username
             FROM egirl_orders eo
             LEFT JOIN boosters b ON b.id = eo.egirl_id
             WHERE eo.id = ?
             LIMIT 1",
            $order_id
        );

        if (!$order) {
            echo json_encode([
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'GGirl order not found'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (empty($order['egirl_id'])) {
            echo json_encode([
                'sendToast' => ['type' => 'warning', 'title' => 'Not assigned', 'message' => 'No GG-Girl is assigned to this order.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $status = strtoupper((string)($order['status'] ?? ''));
        if (in_array($status, ['COMPLETED', 'CANCELLED', 'REFUNDED'], true)) {
            echo json_encode([
                'sendToast' => ['type' => 'warning', 'title' => 'Not allowed', 'message' => 'Completed, cancelled or refunded orders cannot be reopened this way.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $newStatus = ($status === 'IN_PROGRESS') ? 'PAID' : $status;
        if ($newStatus === '') $newStatus = 'PAID';

        db_update_row('egirl_orders', ['id' => $order_id], [
            'egirl_id' => 0,
            'egirl_cut' => null,
            'status' => $newStatus,
            'claimed_at' => null,
            'session_end_at' => null,
            'is_paused' => 0,
            'paused_remaining_seconds' => null,
        ]);

        $egirlName = trim((string)($order['egirl_username'] ?? 'GG-Girl'));
        if ($egirlName === '') $egirlName = 'GG-Girl';

        try {
            chat_insert_message(
                'eg_' . $order_id,
                ['message' => $egirlName . " was removed from this order by an admin. The order is now available for another GG-Girl.", 'message_type' => 'text'],
                ['id' => 999, 'username' => 'System', 'icon' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
                'system'
            );
        } catch (Throwable $e) {}

        $this->add_egirl_order_site_notification('egirl_booking_removed', $order, [
            'admin_id' => (int)ADMIN_ID,
            'status' => 'REMOVED',
        ]);

        log_admin_action(ADMIN_ID, 'Removed GG-Girl #' . (int)$order['egirl_id'] . ' from GGirl order #' . $order_id);

        echo json_encode([
            'sendToast' => ['type' => 'success', 'title' => 'Removed', 'message' => 'GG-Girl removed. Order is available again.'],
            'playSound' => 'success',
            'refreshPage' => true,
        ]);
    }

