    public function egirl_accept_order()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $order_id = (int)($_POST['order_id'] ?? 0);
        global $db;
        $order = $db->row("SELECT * FROM egirl_orders WHERE id = ? AND (egirl_id = ? OR egirl_id = 0) AND status = 'PAID' LIMIT 1", $order_id, BOOSTER_ID);
        if (!$order) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found or already accepted.']]); return; }
        $unit_value = (float)($order['unit_value'] ?? 1);
        $unit_type = strtolower((string)($order['unit_type'] ?? 'hours'));
        if (in_array($unit_type, ['minute','minutes','min','mins'], true)) {
            $duration_seconds = (int)round($unit_value * 60);
        } elseif (in_array($unit_type, ['day','days'], true)) {
            $duration_seconds = (int)round($unit_value * 86400);
        } else {
            $duration_seconds = (int)round($unit_value * 3600);
        }
        if ($duration_seconds <= 0) { $duration_seconds = 3600; }
        $now_dt = date('Y-m-d H:i:s');
        $session_end_at = date('Y-m-d H:i:s', time() + $duration_seconds);

        // Resolve the egirl's individual cut rate.
        // boosters.egirl_cut_percent overrides the platform default of 60%.
        $egirl_row  = $db->row("SELECT egirl_cut_percent FROM boosters WHERE id = ? LIMIT 1", BOOSTER_ID);
        $egirl_cut  = ($egirl_row && $egirl_row['egirl_cut_percent'] !== null)
            ? (float)$egirl_row['egirl_cut_percent']
            : 60.0;

        db_update_row('egirl_orders', ['id' => $order_id], [
            'status' => 'IN_PROGRESS',
            'egirl_id' => BOOSTER_ID,
            'egirl_cut' => $egirl_cut,
            'claimed_at' => $now_dt,
            'session_end_at' => $session_end_at,
            'is_paused' => 0,
            'paused_remaining_seconds' => null
        ]);

        $order['egirl_id'] = BOOSTER_ID;
        $this->add_egirl_order_site_notification('egirl_booking_assigned', $order, ['status' => 'IN_PROGRESS']);

        db_add_row('notifications', ['type' => 'egirl_session_started', 'recipient' => 'client', 'recipient_id' => $order['client_id'], 'data' => json_encode(['order_id' => $order_id]), 'created_at' => date('Y-m-d H:i:s')]);
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Accepted!', 'message' => 'Session started.']]);
    }

    public function egirl_complete_order()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $order_id = (int)($_POST['order_id'] ?? 0);
        global $db;
        $order = $db->row("SELECT * FROM egirl_orders WHERE id = ? AND egirl_id = ? AND status = 'IN_PROGRESS' LIMIT 1", $order_id, BOOSTER_ID);
        if (!$order) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.']]); return; }
        $cut_percent  = (float)($order['egirl_cut'] ?? 60.0);
        $price_eur_cents = (int)($order['price_eur'] ?? 0);
        if ($price_eur_cents <= 0) {
            $price_eur_cents = (int)($order['price'] ?? 0);
            if (strtoupper((string)($order['currency'] ?? 'EUR')) === 'USD') {
                $rate = (float)(function_exists('get_exchange_rate') ? get_exchange_rate() : 0);
                if ($rate > 0) {
                    $price_eur_cents = (int) round($price_eur_cents / $rate);
                }
            }
        }
        $payout_cents = (int)floor($price_eur_cents * $cut_percent / 100);
        db_update_row('egirl_orders', ['id' => $order_id], ['status' => 'COMPLETED', 'completed_at' => date('Y-m-d H:i:s'), 'session_end_at' => null, 'is_paused' => 0, 'paused_remaining_seconds' => null]);
        $old = (int)($db->cell("SELECT balance FROM egirl_balance WHERE egirl_id = ?", BOOSTER_ID) ?? 0);
        $new = $old + $payout_cents;
        $db->run("INSERT INTO egirl_balance (egirl_id, balance) VALUES (?, ?) ON DUPLICATE KEY UPDATE balance = ?", BOOSTER_ID, $new, $new);
        db_add_row('egirl_payments', ['egirl_id' => BOOSTER_ID, 'egirl_order_id' => $order_id, 'amount' => $payout_cents, 'currency' => 'EUR', 'type' => 'order_payout', 'note' => 'Session #' . $order_id . ' (' . $cut_percent . '%)', 'balance_update' => $old . '|' . $new, 'created_at' => date('Y-m-d H:i:s')]);

        $order['egirl_id'] = BOOSTER_ID;
        $this->add_egirl_order_site_notification('egirl_booking_completed', $order, [
            'amount' => $payout_cents,
            'balance' => $new,
        ]);
        $this->add_egirl_order_site_notification('egirl_payout_received', $order, [
            'amount' => $payout_cents,
            'balance' => $new,
            'reason' => 'booking_completed',
        ]);

        $db->run("UPDATE egirl_profiles SET total_sessions = total_sessions + 1 WHERE egirl_id = ?", BOOSTER_ID);
        db_add_row('notifications', ['type' => 'egirl_session_completed', 'recipient' => 'client', 'recipient_id' => $order['client_id'], 'data' => json_encode(['order_id' => $order_id, 'egirl_id' => BOOSTER_ID]), 'created_at' => date('Y-m-d H:i:s')]);
        if (function_exists('lb_ajax_realtime_notify_update')) {
            lb_ajax_realtime_notify_update('clients');
        }
        if (function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('order_status_update', 'eg_' . $order_id, [
                'egirl_order_id' => $order_id,
                'status' => 'COMPLETED',
            ]);
        }
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Completed!', 'message' => 'Session complete. Payout added to your balance.']]);
    }

    public function egirl_pause_session()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);
        $remaining_seconds = (int)($_POST['remaining_seconds'] ?? 0);

        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order.']]);
            return;
        }

        if ($remaining_seconds < 0) {
            $remaining_seconds = 0;
        }

        global $db;
        $order = $db->row(
            "SELECT * FROM egirl_orders WHERE id = ? AND egirl_id = ? AND status = 'IN_PROGRESS' LIMIT 1",
            $order_id,
            BOOSTER_ID
        );

        if (!$order) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Session not found.']]);
            return;
        }

        db_update_row('egirl_orders', ['id' => $order_id], [
            'is_paused' => 1,
            'paused_remaining_seconds' => $remaining_seconds,
            'session_end_at' => null
        ]);

        $this->add_egirl_order_site_notification('egirl_booking_paused', $order, [
            'remaining_seconds' => $remaining_seconds,
        ]);

        echo json_encode([
            'success' => true,
            'paused' => true,
            'remaining_seconds' => $remaining_seconds,
            'sendToast' => ['type' => 'success', 'title' => 'Paused', 'message' => 'Session paused.']
        ]);
    }

    public function egirl_resume_session()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]);
            return;
        }

        $order_id = (int)($_POST['order_id'] ?? 0);

        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order.']]);
            return;
        }

        global $db;
        $order = $db->row(
            "SELECT * FROM egirl_orders WHERE id = ? AND egirl_id = ? AND status = 'IN_PROGRESS' LIMIT 1",
            $order_id,
            BOOSTER_ID
        );

        if (!$order) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Session not found.']]);
            return;
        }

        $remaining_seconds = (int)($order['paused_remaining_seconds'] ?? 0);

        $unit_value = (float)($order['unit_value'] ?? 1);
        $unit_type = strtolower((string)($order['unit_type'] ?? 'hours'));

        if (in_array($unit_type, ['minute', 'minutes', 'min', 'mins'], true)) {
            $duration_seconds = (int)round($unit_value * 60);
        } elseif (in_array($unit_type, ['day', 'days'], true)) {
            $duration_seconds = (int)round($unit_value * 86400);
        } else {
            $duration_seconds = (int)round($unit_value * 3600);
        }

        if ($duration_seconds <= 0) {
            $duration_seconds = 3600;
        }

        if ($remaining_seconds <= 0 || $remaining_seconds > $duration_seconds) {
            $remaining_seconds = $duration_seconds;
        }

        $now_dt = date('Y-m-d H:i:s');
        $session_end_at = date('Y-m-d H:i:s', time() + $remaining_seconds);

        db_update_row('egirl_orders', ['id' => $order_id], [
            'is_paused' => 0,
            'paused_remaining_seconds' => null,
            'claimed_at' => $now_dt,
            'session_end_at' => $session_end_at
        ]);

        $this->add_egirl_order_site_notification('egirl_booking_unpaused', $order, [
            'remaining_seconds' => $remaining_seconds,
            'session_end_at' => $session_end_at,
        ]);

        echo json_encode([
            'success' => true,
            'paused' => false,
            'remaining_seconds' => $remaining_seconds,
            'claimed_at' => $now_dt,
            'session_end_at' => $session_end_at,
            'sendToast' => ['type' => 'success', 'title' => 'Resumed', 'message' => 'Session resumed.']
        ]);
    }

    public function egirl_save_service()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $service_id  = (int)($_POST['service_id']  ?? 0);
        $type        = esc($_POST['type']        ?? 'hourly');
        $title       = esc($_POST['title']       ?? '');
        $description = esc($_POST['description'] ?? '');
        $game_raw    = trim((string)($_POST['game'] ?? ''));
        $game        = function_exists('lb_egirl_game_key') ? lb_egirl_game_key($game_raw) : strtolower($game_raw);
        $price_cents = (int)($_POST['price_cents'] ?? 0);
        $unit_value  = (int)($_POST['unit_value']  ?? 1);
        $unit_type   = esc($_POST['unit_type']   ?? 'hours');
        $is_active   = (int)($_POST['is_active'] ?? 1);
        $voice_chat  = (int)($_POST['voice_chat'] ?? 0);
        if (!in_array($type, ['hourly','per_game','rank_boost','coaching','just_chat','custom'], true)) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid type.']]); return; }
        if (!$title || $price_cents <= 0) { echo json_encode(['validationErrors' => ['title' => 'Title and price are required.']]); return; }
        global $db;
        if ($game !== '') {
            $profile_row = $db->row("SELECT games FROM egirl_profiles WHERE egirl_id = ? LIMIT 1", BOOSTER_ID) ?: [];
            $profile_games = array_values(array_filter(array_map(
                static fn($value) => function_exists('lb_egirl_game_key') ? lb_egirl_game_key((string)$value) : strtolower(trim((string)$value)),
                explode('|', (string)($profile_row['games'] ?? ''))
            )));
            if (!in_array($game, $profile_games, true)) {
                echo json_encode(['validationErrors' => ['game' => 'Please select a game from your profile.']]);
                return;
            }
        }
        $game = esc($game);
        $data = ['type' => $type, 'title' => $title, 'description' => $description, 'game' => $game, 'price_cents' => $price_cents, 'unit_value' => $unit_value, 'unit_type' => $unit_type, 'includes_voice' => $voice_chat, 'is_active' => $is_active];
        if ($service_id > 0) {
            if (!$db->row("SELECT id FROM egirl_services WHERE id = ? AND egirl_id = ? LIMIT 1", $service_id, BOOSTER_ID)) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found']]); return; }
            db_update_row('egirl_services', ['id' => $service_id], $data);
            echo json_encode([
                'success' => true,
                'redirect' => BASE_URL . '/booster-area/egirl-services',
                'sendToast' => ['type' => 'success', 'title' => 'Saved!', 'message' => 'Service updated.'],
            ]);
        } else {
            // No hard service limit
            $data['egirl_id'] = BOOSTER_ID;
            $new_id = db_add_row('egirl_services', $data);
            if ($new_id === false) {
                echo json_encode([
                    'success' => false,
                    'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'The service could not be created.'],
                ]);
                return;
            }
            echo json_encode([
                'success' => true,
                'newId' => $new_id,
                'redirect' => BASE_URL . '/booster-area/egirl-services',
                'sendToast' => ['type' => 'success', 'title' => 'Created!', 'message' => 'Service added.'],
            ]);
        }
    }

    public function egirl_delete_service()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $service_id = (int)($_POST['service_id'] ?? 0);
        global $db;
        if (!$db->row("SELECT id FROM egirl_services WHERE id = ? AND egirl_id = ? LIMIT 1", $service_id, BOOSTER_ID)) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found']]); return; }
        $db->run("DELETE FROM egirl_services WHERE id = ?", $service_id);
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Deleted']]);
