    public function egirl_toggle_featured()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $service_id  = (int)($_POST['service_id'] ?? 0);
        $is_featured = (int)($_POST['is_featured'] ?? 0) ? 1 : 0;
        global $db;
        if (!$db->row("SELECT id FROM egirl_services WHERE id = ? AND egirl_id = ? LIMIT 1", $service_id, BOOSTER_ID)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found']]); return;
        }
        if ($is_featured === 1) {
            $count = (int)$db->cell("SELECT COUNT(*) FROM egirl_services WHERE egirl_id = ? AND is_featured = 1", BOOSTER_ID);
            if ($count >= 3) { echo json_encode(['success' => false, 'message' => 'Max 3 featured services allowed.']); return; }
        }
        $db->run("UPDATE egirl_services SET is_featured = ? WHERE id = ? AND egirl_id = ?", $is_featured, $service_id, BOOSTER_ID);
        echo json_encode(['success' => true]);
    }

    public function egirl_save_profile()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        global $db;

        // Widens `games` and adds `game_ranks` once — the pipe string holds every
        // boosting game now and no longer fits the original column.
        if (function_exists('lb_egirl_profiles_ensure_game_ranks_column')) {
            lb_egirl_profiles_ensure_game_ranks_column();
        }

        // ── Profile data (stored in egirl_profiles table) ──
        $languages = $_POST['languages'] ?? '';
        // Support both array (languages[]) and pipe-string
        if (is_array($languages)) {
            $languages = implode('|', array_filter(array_map('esc', $languages)));
        } else {
            $languages = esc($languages);
        }

        $data = [
            'bio'       => esc($_POST['bio']       ?? ''),
            'languages' => $languages,
            'games'     => esc($_POST['games']      ?? ''),
            'lol_rank'  => esc($_POST['lol_rank']   ?? ''),
            'val_rank'  => esc($_POST['val_rank']   ?? ''),
            'tft_rank'  => esc($_POST['tft_rank']   ?? ''),
            'timezone'  => esc($_POST['timezone']   ?? 'Europe/Berlin'),
            'country'   => esc($_POST['country']    ?? ''),
        ];

        // Ranks of every other boosting game (Apex, Rocket League, …) live in one
        // JSON column, so a newly added game needs no schema change.
        if (isset($_POST['game_ranks'])) {
            $decoded = json_decode((string)$_POST['game_ranks'], true);
            $gameRanks = [];
            if (is_array($decoded)) {
                foreach ($decoded as $gameKey => $rank) {
                    $gameKey = function_exists('lb_egirl_game_key')
                        ? lb_egirl_game_key((string)$gameKey)
                        : strtolower(trim((string)$gameKey));
                    $rank = esc(trim((string)$rank));
                    if ($gameKey !== '' && $rank !== '') $gameRanks[$gameKey] = $rank;
                }
            }
            if (function_exists('lb_egirl_profiles_ensure_game_ranks_column')) {
                lb_egirl_profiles_ensure_game_ranks_column();
            }
            $data['game_ranks'] = json_encode($gameRanks, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }

        if ($db->row("SELECT id FROM egirl_profiles WHERE egirl_id = ? LIMIT 1", BOOSTER_ID)) {
            db_update_row('egirl_profiles', ['egirl_id' => BOOSTER_ID], $data);
        } else {
            $data['egirl_id'] = BOOSTER_ID;
            db_add_row('egirl_profiles', $data);
        }

        // ── voice_chat + show_profile stored in boosters table ──
        $voice_chat   = (int)($_POST['voice_chat']   ?? 0);
        $show_profile = (int)($_POST['show_profile'] ?? 0);
        db_update_row('boosters', ['id' => BOOSTER_ID], [
            'voice_chat'   => $voice_chat,
            'show_profile' => $show_profile,
        ]);

        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved!', 'message' => 'Profile updated.']]);
    }

    public function egirl_save_availability()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $slots = json_decode($_POST['availability'] ?? '[]', true);
        if (!is_array($slots)) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Invalid data']]); return; }
        global $db;
        $db->run("DELETE FROM egirl_availability WHERE egirl_id = ?", BOOSTER_ID);
        foreach ($slots as $slot) {
            $day = (int)($slot['day'] ?? 0);
            if ($day < 0 || $day > 6) continue;
            db_add_row('egirl_availability', ['egirl_id' => BOOSTER_ID, 'day_of_week' => $day, 'time_from' => esc($slot['from'] ?? '00:00') . ':00', 'time_to' => esc($slot['to'] ?? '23:59') . ':00', 'timezone' => esc($slot['timezone'] ?? 'Europe/Berlin')]);
        }
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved!', 'message' => 'Availability updated.']]);
    }

    public function egirl_request_payout()
    {
        if (!defined('IS_EGIRL') || !IS_EGIRL) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        global $db;

        $egirl_id  = (int) BOOSTER_ID;
        $method_id = (int)($_POST['payout_method_id'] ?? 0);
        $note      = esc($_POST['note'] ?? '');
        $use_full  = ((int)($_POST['full_balance'] ?? 0) === 1);

        $balance = (int)($db->cell("SELECT balance FROM egirl_balance WHERE egirl_id = ?", $egirl_id) ?? 0);

        $method_row = $db->row("SELECT * FROM booster_payout_methods WHERE id = ? AND booster_id = ? LIMIT 1", $method_id, $egirl_id);
        if (!$method_row) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please select a payout method.']]);
            return;
        }

        $gross_input = (int) round(((float) str_replace(',', '.', (string)($_POST['amount'] ?? 0))) * 100);
        $gross = $use_full ? $balance : $gross_input;
        if ($gross > $balance) $gross = $balance;

        if ($gross <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid amount.']]);
            return;
        }
        if ($gross < 500) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Minimum payout is €5.00.']]);
            return;
        }
        if ((int)$db->cell("SELECT COUNT(*) FROM egirl_payout_requests WHERE egirl_id = ? AND status = 'PENDING'", $egirl_id) > 0) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Pending', 'message' => 'You already have a pending request.']]);
            return;
        }

        $isCrypto   = (strtolower((string)$method_row['method']) === 'crypto');
        $feePercent = $isCrypto ? 5.0 : 3.0;
        $feeAmount  = (int) round($gross * ($feePercent / 100));
        $netAmount  = max(0, $gross - $feeAmount);

        $details = json_encode([
            'payout_method_id' => $method_id,
            'fee_percent'       => $feePercent,
            'fee_amount_cents'  => $feeAmount,
            'net_amount_cents'  => $netAmount,
            'full_balance'      => $use_full ? 1 : 0,
            'note'              => $note,
        ], JSON_UNESCAPED_SLASHES);

        db_add_row('egirl_payout_requests', [
            'egirl_id'     => $egirl_id,
            'amount_cents' => $gross,
            'method'       => $isCrypto ? 'crypto' : 'bank_transfer',
            'details'      => $details,
            'status'       => 'PENDING',
            'created_at'   => date('Y-m-d H:i:s'),
        ]);

        echo json_encode([
            'success'    => true,
            'sendToast'  => ['type' => 'success', 'title' => 'Requested!', 'message' => 'Payout request submitted.'],
            'refreshPage' => true,
        ]);
    }

    public function egirl_submit_review()
    {
        if (!CLIENT_ID) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Please log in.']]); return; }
        $order_id = (int)($_POST['order_id'] ?? 0);
        $rating   = max(1, min(5, (int)($_POST['rating']  ?? 5)));
        $comment  = trim(esc($_POST['comment'] ?? ''));
        if (mb_strlen($comment) > 1000) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Too long', 'message' => 'Review text may contain up to 1000 characters.']]);
            return;
        }
        global $db;
        $order = $db->row("SELECT * FROM egirl_orders WHERE id = ? AND client_id = ? AND status = 'COMPLETED' LIMIT 1", $order_id, CLIENT_ID);
        if (!$order) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found']]); return; }
        if ($db->row("SELECT id FROM egirl_reviews WHERE egirl_order_id = ? LIMIT 1", $order_id)) { echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Already reviewed']]); return; }
        // Reviews go live immediately. Only ratings below 3 stars are held back for a
        // manual check, so a single bad experience cannot be published unreviewed.
        $autoApproved = $rating >= 3;

        $reviewId = db_add_row('egirl_reviews', [
            'egirl_order_id' => $order_id,
            'egirl_id' => $order['egirl_id'],
            'client_id' => CLIENT_ID,
            'rating' => $rating,
            'comment' => $comment,
            'approved' => $autoApproved ? 1 : 0,
            'created_at' => date('Y-m-d H:i:s'),
        ]);

        $stats = $db->row("SELECT COUNT(*) AS cnt, AVG(rating) AS avg FROM egirl_reviews WHERE egirl_id = ? AND approved = 1", $order['egirl_id']);
        $db->run("UPDATE egirl_profiles SET review_count = ?, review_avg = ? WHERE egirl_id = ?", (int)$stats['cnt'], round((float)$stats['avg'], 2), $order['egirl_id']);
        $this->add_egirl_site_notification('egirl_review_received', (int)$order['egirl_id'], [
            'order_id' => $order_id,
            'rating' => $rating,
            'client_id' => (int)CLIENT_ID,
        ]);

        if (function_exists('lb_send_egirl_review_webhook')) {
            // Same two channels the boosting reviews use: the internal #review-notif
            // and the community #reviews webhook.
            $reviewAdminWebhookUrl     = "https://discord.com/api/webhooks/1461094683995275358/xEVZbjb_LnUZGjIIwHzhlaQodNUill6dMEST3KHAA3bnS6big5aKA8LmoF1eMgK_xJtM";
            $reviewCommunityWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

            lb_send_egirl_review_webhook([
                'id' => (int)$reviewId,
                'egirl_id' => (int)$order['egirl_id'],
                'client_id' => (int)CLIENT_ID,
                'order_id' => $order_id,
                'rating' => $rating,
                'comment' => $comment,
                'approved' => $autoApproved ? 1 : 0,
            ], $reviewAdminWebhookUrl, $reviewCommunityWebhookUrl);
        }

        echo json_encode([
            'success' => true,
            'sendToast' => ['type' => 'success', 'title' => 'Thank you!', 'message' => 'Review submitted.'],
            'refreshPage' => true,
        ]);
    }

    public function admin_add_egirl()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $username  = esc($_POST['username']  ?? '');
        $email     = esc($_POST['email']     ?? '');
        $password  = esc($_POST['password']  ?? '');
        $discord   = esc($_POST['discord']   ?? '');
        $games_arr = $_POST['games']         ?? ['lol'];
        $languages = esc($_POST['languages'] ?? '');
        $bio       = esc($_POST['bio']       ?? '');
        if (!$username || !$email || !$password) { echo json_encode(['validationErrors' => ['username' => 'Username, email and password are required.']]); return; }
        global $db;
        if ($db->cell("SELECT id FROM boosters WHERE email = ? OR username = ? LIMIT 1", $email, $username)) { echo json_encode(['validationErrors' => ['email' => 'Username or email already exists.']]); return; }
        $games    = implode('|', array_map('esc', (array)$games_arr));
        $egirl_id = db_add_row('boosters', ['username' => $username, 'email' => $email, 'password' => sha1($password), 'discord' => $discord, 'games' => $games, 'rank_id' => 0, 'is_egirl' => 1, 'is_banned' => 0, 'created_at' => date('Y-m-d H:i:s')]);
        if (!$egirl_id) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create account.']]); return; }
        db_add_row('egirl_profiles', ['egirl_id' => $egirl_id, 'games' => $games, 'languages' => $languages, 'bio' => $bio]);
        db_add_row('egirl_balance', ['egirl_id' => $egirl_id, 'balance' => 0]);
        log_admin_action(ADMIN_ID, 'Added E-Girl #' . $egirl_id . ' (' . $username . ')');
        echo json_encode(['success' => true, 'redirectUrl' => ADMN_URL . '/egirls', 'sendToast' => ['type' => 'success', 'title' => 'Created!', 'message' => 'E-Girl account created.']]);
    }

    public function admin_egirl_ban()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $egirl_id = (int)($_POST['egirl_id'] ?? 0);
        $ban      = (int)($_POST['ban']      ?? 0);
        db_update_row('boosters', ['id' => $egirl_id, 'is_egirl' => 1], ['is_banned' => $ban ? 1 : 0]);
        log_admin_action(ADMIN_ID, ($ban ? 'Banned' : 'Unbanned') . ' E-Girl #' . $egirl_id);
        echo json_encode(['success' => true]);
    }

    public function admin_adjust_egirl_balance()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized.']]);
            return;
        }

        $egirl_id = (int)($_POST['egirl_id'] ?? $_POST['id'] ?? 0);
        $amount_raw = str_replace(',', '.', (string)($_POST['amount'] ?? '0'));
        $amount_cents = abs((int)round((float)$amount_raw * 100));
        $mode = strtolower(trim((string)($_POST['mode'] ?? '')));
        if ($mode === '') $mode = ((float)$amount_raw < 0) ? 'fine' : 'add';
        $reason = esc($_POST['reason'] ?? ($mode === 'fine' ? 'admin_fine' : 'manual_credit'));
        $note = esc($_POST['note'] ?? '');

        if ($egirl_id <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid E-Girl ID.']]);
            return;
        }

        if (!in_array($mode, ['add', 'fine'], true) || $amount_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid amount.']]);
            return;
        }

        global $db;
        $db->run("START TRANSACTION");
        $egirl = $db->row("SELECT id, username FROM boosters WHERE id = ? AND is_egirl = 1 LIMIT 1", $egirl_id);
        if (!$egirl) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'E-Girl not found.']]);
            return;
        }

        $balance_row = $db->row("SELECT balance FROM egirl_balance WHERE egirl_id = ? LIMIT 1 FOR UPDATE", $egirl_id);
        $old_balance = (int)($balance_row['balance'] ?? 0);
        $signed_amount = $mode === 'fine' ? -$amount_cents : $amount_cents;
        $new_balance = $old_balance + $signed_amount;

        if ($new_balance < 0) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Balance cannot go below €0.00.']]);
            return;
        }

        $db->run(
            "INSERT INTO egirl_balance (egirl_id, balance) VALUES (?, ?) ON DUPLICATE KEY UPDATE balance = ?",
            $egirl_id,
            $new_balance,
            $new_balance
        );

        db_add_row('egirl_payments', [
            'egirl_id'       => $egirl_id,
            'amount'         => $signed_amount,
            'currency'       => 'EUR',
            'type'           => $mode === 'fine' ? 'admin_fine' : $reason,
            'note'           => $reason . ($note !== '' ? ': ' . $note : '') . ' (admin #' . ADMIN_ID . ')',
            'balance_update' => $old_balance . '|' . $new_balance,
            'created_at'     => date('Y-m-d H:i:s'),
        ]);

        if ($mode === 'fine') {
            $this->add_egirl_site_notification('egirl_fine_received', $egirl_id, [
                'amount' => $amount_cents,
                'balance' => $new_balance,
                'note' => $note,
                'admin_id' => (int)ADMIN_ID,
            ]);
        } else {
            $this->add_egirl_site_notification('egirl_payout_received', $egirl_id, [
                'amount' => $amount_cents,
                'balance' => $new_balance,
                'reason' => 'manual_adjustment',
                'note' => $note,
            ]);
        }

        $db->run("COMMIT");
        $amount_label = number_format($signed_amount / 100, 2, '.', '');
        $balance_label = number_format($new_balance / 100, 2, '.', '');
        log_admin_action(ADMIN_ID, 'Adjusted E-Girl #' . $egirl_id . ' balance by €' . $amount_label);

        echo json_encode([
            'success'     => true,
            'sendToast'   => ['type' => 'success', 'title' => 'Done', 'message' => 'Balance adjusted to €' . $balance_label . '.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function admin_egirl_payout_update()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $request_id = (int)($_POST['request_id'] ?? 0);
        $status     = strtoupper(esc($_POST['status'] ?? ''));
        $note       = esc($_POST['note']         ?? '');
        if (!in_array($status, ['APPROVED','REJECTED','PAID','COMPLETED'], true)) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Invalid status']]); return; }
        global $db;
        $db->run("START TRANSACTION");
        $req = $db->row("SELECT * FROM egirl_payout_requests WHERE id = ? LIMIT 1 FOR UPDATE", $request_id);
        $current_status = strtoupper((string)($req['status'] ?? ''));
        if (!$req || !in_array($current_status, ['PENDING', 'APPROVED'], true)) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Request not found or already processed.']]);
            return;
        }
        $egirl = $db->row("SELECT id, username, discord_id FROM boosters WHERE id = ? AND is_egirl = 1 LIMIT 1", (int)$req['egirl_id']);
        if (!$egirl) {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'E-Girl not found.']]);
            return;
        }
        if ($status === 'REJECTED' && $current_status !== 'PENDING') {
            $db->run("ROLLBACK");
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Only pending requests can be rejected.']]);
            return;
        }
        $db->run("UPDATE egirl_payout_requests SET status = ?, admin_note = ? WHERE id = ?", $status, $note, $request_id);
        if (in_array($status, ['PAID', 'COMPLETED'], true)) {
            $egirl_id = (int)$req['egirl_id'];
            $amount   = (int)$req['amount_cents'];
            $balance_row = $db->row("SELECT balance FROM egirl_balance WHERE egirl_id = ? LIMIT 1 FOR UPDATE", $egirl_id);
            $old = (int)($balance_row['balance'] ?? 0);
            if ($amount <= 0 || $old < $amount) {
                $db->run("ROLLBACK");
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'E-Girl balance is insufficient for this payout.']]);
                return;
            }
            $new = $old - $amount;
            $db->run("UPDATE egirl_balance SET balance = ? WHERE egirl_id = ?", $new, $egirl_id);
            db_add_row('egirl_payments', ['egirl_id' => $egirl_id, 'amount' => -$amount, 'currency' => 'EUR', 'type' => 'payout_withdrawal', 'note' => 'Payout #' . $request_id . ' completed', 'balance_update' => $old . '|' . $new, 'created_at' => date('Y-m-d H:i:s')]);
            $this->add_egirl_site_notification('egirl_payout_received', $egirl_id, [
                'payout_request_id' => $request_id,
                'amount' => $amount,
                'balance' => $new,
                'status' => $status,
            ]);
            $db->run("COMMIT");
            $details = json_decode((string)($req['details'] ?? ''), true);
            if (!is_array($details)) $details = [];
            $this->payout_send_discord_dm((string)($egirl['discord_id'] ?? ''), 'E-Girl', [
                'status' => 'completed',
                'request_id' => $request_id,
                'amount_cents' => $amount,
                'fee_cents' => (int)($details['fee_amount_cents'] ?? 0),
                'net_cents' => (int)($details['net_amount_cents'] ?? $amount),
                'method' => (string)($req['method'] ?? 'bank_transfer'),
                'balance_cents' => $new,
                'note' => $note,
            ]);
        } elseif (in_array($status, ['APPROVED','REJECTED'], true)) {
            $this->add_egirl_site_notification('egirl_payout_update', (int)$req['egirl_id'], [
                'payout_request_id' => $request_id,
                'amount' => (int)($req['amount_cents'] ?? 0),
                'status' => $status,
            ]);
            $db->run("COMMIT");
            if ($status === 'REJECTED') {
                $this->payout_send_discord_dm((string)($egirl['discord_id'] ?? ''), 'E-Girl', [
                    'status' => 'rejected',
                    'request_id' => $request_id,
                    'amount_cents' => (int)($req['amount_cents'] ?? 0),
                    'method' => (string)($req['method'] ?? 'bank_transfer'),
                    'reason' => $note !== '' ? $note : 'Rejected by an administrator',
                    'note' => $note,
                ]);
            }
        }
        log_admin_action(ADMIN_ID, 'E-Girl payout #' . $request_id . ' → ' . $status);
        echo json_encode([
            'success' => true,
            'sendToast' => ['type' => 'success', 'title' => $status === 'REJECTED' ? 'Rejected' : 'Completed', 'message' => 'Payout request updated.'],
            'refreshPage' => true,
        ]);
    }

    public function admin_egirl_save_profile()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $egirl_id = (int)($_POST['egirl_id'] ?? 0);
        global $db;
        if (!$db->row("SELECT id FROM boosters WHERE id = ? AND is_egirl = 1 LIMIT 1", $egirl_id)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'E-Girl not found.']]); return;
        }

        if (function_exists('lb_egirl_profiles_ensure_game_ranks_column')) {
            lb_egirl_profiles_ensure_game_ranks_column();
        }

        $languages = $_POST['languages'] ?? '';
        if (is_array($languages)) {
            $languages = implode('|', array_filter(array_map('esc', $languages)));
        } else {
            $languages = esc($languages);
        }

        $data = [
            'bio'       => esc($_POST['bio']      ?? ''),
            'languages' => $languages,
            'games'     => esc($_POST['games']     ?? ''),
            'lol_rank'  => esc($_POST['lol_rank']  ?? ''),
            'val_rank'  => esc($_POST['val_rank']  ?? ''),
            'tft_rank'  => esc($_POST['tft_rank']  ?? ''),
            'timezone'  => esc($_POST['timezone']  ?? ''),
            'country'   => esc($_POST['country']   ?? ''),
        ];

        // Ranks of every other game (Apex, Rocket League, …) share one JSON column,
        // same storage the GG-Girl's own profile writes.
        if (isset($_POST['game_ranks'])) {
            $decoded = json_decode((string)$_POST['game_ranks'], true);
            $gameRanks = [];
            if (is_array($decoded)) {
                foreach ($decoded as $gameKey => $rank) {
                    $gameKey = function_exists('lb_egirl_game_key')
                        ? lb_egirl_game_key((string)$gameKey)
                        : strtolower(trim((string)$gameKey));
                    $rank = esc(trim((string)$rank));
                    if ($gameKey !== '' && $rank !== '') $gameRanks[$gameKey] = $rank;
                }
            }
            $data['game_ranks'] = json_encode($gameRanks, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }

        if ($db->row("SELECT id FROM egirl_profiles WHERE egirl_id = ? LIMIT 1", $egirl_id)) {
            db_update_row('egirl_profiles', ['egirl_id' => $egirl_id], $data);
        } else {
            $data['egirl_id'] = $egirl_id;
            db_add_row('egirl_profiles', $data);
        }

        $voice_chat   = (int)($_POST['voice_chat']   ?? 0);
        $show_profile = (int)($_POST['show_profile'] ?? 0);
        db_update_row('boosters', ['id' => $egirl_id], [
            'voice_chat'   => $voice_chat,
            'show_profile' => $show_profile,
        ]);

        log_admin_action(ADMIN_ID, 'Updated E-Girl #' . $egirl_id . ' profile');
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved!', 'message' => 'Profile updated.']]);
    }

    public function admin_egirl_set_cut()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $egirl_id   = (int)($_POST['egirl_id']   ?? 0);
        $cut_raw    = $_POST['cut_percent'] ?? '';

        global $db;
        if (!$db->row("SELECT id FROM boosters WHERE id = ? AND is_egirl = 1 LIMIT 1", $egirl_id)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Not found', 'message' => 'E-Girl not found.']]); return;
        }

        // Allow clearing back to platform default by sending empty string / "default"
        if ($cut_raw === '' || strtolower($cut_raw) === 'default') {
            $cut_value = null;
        } else {
            $cut_value = round((float)$cut_raw, 2);
            if ($cut_value < 1 || $cut_value > 99) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Invalid', 'message' => 'Cut must be between 1 and 99%.']]); return;
            }
        }

        $db->run("UPDATE boosters SET egirl_cut_percent = ? WHERE id = ?", $cut_value, $egirl_id);
        $label = $cut_value !== null ? $cut_value . '%' : 'platform default (60%)';
        log_admin_action(ADMIN_ID, 'Set E-Girl #' . $egirl_id . ' cut to ' . $label);
        echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved!', 'message' => 'Cut set to ' . $label]]);
    }

    public function admin_egirl_review_update()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized']]); return; }
        $review_id = (int)($_POST['review_id'] ?? 0);
        $approved  = (int)($_POST['approved']  ?? 0);
        global $db;
        $review = $db->row("SELECT * FROM egirl_reviews WHERE id = ? LIMIT 1", $review_id);
        if ($approved === -1) {
            $db->run("DELETE FROM egirl_reviews WHERE id = ?", $review_id);
        } elseif ($approved === 0) {
            // Hide: takes the review off the public page without deleting it.
            $db->run("UPDATE egirl_reviews SET approved = 0 WHERE id = ?", $review_id);
        } else {
            $db->run("UPDATE egirl_reviews SET approved = 1 WHERE id = ?", $review_id);

            // A held-back review only reaches the community channel once it is approved.
            // The admin channel already saw it on submit, so only the community one fires.
            if ($review && (int)($review['approved'] ?? 0) !== 1 && function_exists('lb_send_egirl_review_webhook')) {
                $reviewCommunityWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

                lb_send_egirl_review_webhook([
                    'id' => $review_id,
                    'egirl_id' => (int)($review['egirl_id'] ?? 0),
                    'client_id' => (int)($review['client_id'] ?? 0),
                    'order_id' => (int)($review['egirl_order_id'] ?? 0),
                    'rating' => (int)($review['rating'] ?? 0),
                    'comment' => (string)($review['comment'] ?? ''),
                    'approved' => 1,
                ], '', $reviewCommunityWebhookUrl);
            }
        }
        if ($review) {
            $stats = $db->row("SELECT COUNT(*) AS cnt, AVG(rating) AS avg FROM egirl_reviews WHERE egirl_id = ? AND approved = 1", $review['egirl_id']);
            $db->run("UPDATE egirl_profiles SET review_count = ?, review_avg = ? WHERE egirl_id = ?", (int)$stats['cnt'], round((float)$stats['avg'], 2), $review['egirl_id']);
        }
        echo json_encode(['success' => true]);
    }

