    /**
     * Tops up the booster's Nexus account using a custom amount from their booster balance.
     * POST: action=booster_buy_nexus, amount=10.00
     */
    public function booster_buy_nexus()
    {
        if (!$this->is_booster) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Please log in.']]);
            return;
        }

        global $db;

        $amount_raw = trim((string)($_POST['amount'] ?? ''));
        $amount_raw = str_replace(',', '.', $amount_raw);
        $amount_float = (float)$amount_raw;
        $price_cents = (int)round($amount_float * 100);
        $booster_id = (int)BOOSTER_ID;

        if ($price_cents < 100) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Enter an amount', 'message' => 'The minimum top-up amount is €1.00.']]);
            return;
        }

        $booster_row = $db->row("SELECT * FROM boosters WHERE id = ? LIMIT 1", $booster_id);

        if (!$booster_row) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Booster account not found.']]);
            return;
        }

        $nexus_owner_booster_id = 791;
        $nexus_owner_row = $db->row("SELECT * FROM boosters WHERE id = ? LIMIT 1", $nexus_owner_booster_id);

        if (!$nexus_owner_row) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Nexus owner payout account was not found. Please contact an admin.']]);
            return;
        }

        $balance        = (int)($booster_row['balance'] ?? 0);
        $buyer_username = trim((string)($booster_row['username'] ?? ('Booster #' . $booster_id)));
        $discord_id     = trim((string)($booster_row['discord_id'] ?? ''));

        $frozen_cents = 0;
        if (function_exists('booster_insurance_frozen_cents')) {
            $frozen_cents = (int)booster_insurance_frozen_cents($booster_row);
        } elseif (isset($booster_row['insurance_required_amount'])) {
            $frozen_cents = max(0, (int)$booster_row['insurance_required_amount']);
        }

        if (function_exists('booster_available_for_payout_cents')) {
            $available_cents = (int)booster_available_for_payout_cents($booster_row);
        } else {
            $available_cents = max($balance - $frozen_cents, 0);
        }

        if ($discord_id === '') {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'No Discord ID', 'message' => 'Your numeric Discord ID is missing. Please ask an admin to set it on your account.']]);
            return;
        }

        if ($price_cents > $available_cents) {
            $missing = number_format(($price_cents - $available_cents) / 100, 2, '.', '');
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Insufficient balance', 'message' => 'You need €' . $missing . ' more available Booster Balance.']]);
            return;
        }

        $nexus_url   = 'https://nexus-back-production-0e04.up.railway.app/api/lolboostgg/webhook';
        $nexus_token = '441d4598a4a01c3d667046fb6d8e81895008065867cb70ddc0ed6306c7a8dc49fb88bddf3e18b7e3b44b644a6ba2eac3a6f4729b96264c22f54f7861fd1775b214ce5cd372469e7538b8034d85c61caa968231e6ed98824e75495c31c910d0b818ce948952d1916c3c7c77baebea8e601affa27df777c552c51a42c536cec094';

        $ch = curl_init($nexus_url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST           => true,
            CURLOPT_POSTFIELDS     => json_encode(['amount' => $price_cents, 'discordId' => $discord_id]),
            CURLOPT_TIMEOUT        => 15,
            CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bearer ' . $nexus_token],
        ]);

        $response_raw = curl_exec($ch);
        $http_status  = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $curl_error   = curl_error($ch);
        curl_close($ch);

        if ($curl_error) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Nexus unreachable', 'message' => 'Could not reach Nexus. Please try again in a few minutes.']]);
            return;
        }

        if ($http_status < 200 || $http_status >= 300) {
            $decoded   = json_decode($response_raw, true);
            $nexus_msg = !empty($decoded['message']) ? ' — ' . $decoded['message'] : (!empty($decoded['error']) ? ' — ' . $decoded['error'] : '');
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Nexus error', 'message' => 'Top-up rejected (HTTP ' . $http_status . ')' . $nexus_msg . '. Your balance was NOT deducted.']]);
            return;
        }

        $amount_display = number_format($price_cents / 100, 2, '.', '');

        $new_balance = max(0, $balance - $price_cents);
        $db->run("UPDATE boosters SET balance = ? WHERE id = ?", $new_balance, $booster_id);

        db_add_row('booster_payments', [
            'booster_id'     => $booster_id,
            'amount'         => -$price_cents,
            'currency'       => 'EUR',
            'type'           => 'nexus_balance_topup',
            'note'           => 'Nexus Balance Top-Up €' . $amount_display . ' | Paid to Nexus Owner #' . $nexus_owner_booster_id . ' | Discord ID: ' . $discord_id,
            'balance_update' => $balance . '|' . $new_balance,
            'created_at'     => date('Y-m-d H:i:s'),
        ]);

        // Transfer the deducted amount to the Nexus owner so it can be paid out normally.
        $nexus_owner_row_now = $db->row("SELECT * FROM boosters WHERE id = ? LIMIT 1", $nexus_owner_booster_id);
        $nexus_owner_old_balance = (int)($nexus_owner_row_now['balance'] ?? 0);
        $nexus_owner_new_balance = $nexus_owner_old_balance + $price_cents;
        $db->run("UPDATE boosters SET balance = ? WHERE id = ?", $nexus_owner_new_balance, $nexus_owner_booster_id);

        db_add_row('booster_payments', [
            'booster_id'     => $nexus_owner_booster_id,
            'amount'         => $price_cents,
            'currency'       => 'EUR',
            'type'           => 'nexus_balance_sale',
            'note'           => 'Nexus Balance Purchase | Booster #' . $booster_id . ' (' . $buyer_username . ') | €' . $amount_display . ' | Discord ID: ' . $discord_id,
            'balance_update' => $nexus_owner_old_balance . '|' . $nexus_owner_new_balance,
            'created_at'     => date('Y-m-d H:i:s'),
        ]);

        echo json_encode([
            'success'   => true,
            'sendToast' => [
                'type'    => 'success',
                'title'   => 'Nexus balance topped up! 🎉',
                'message' => '€' . number_format($price_cents / 100, 2) . ' added to your Nexus account. Open Nexus and buy your membership using Balance.',
            ],
        ]);
    }

