    private function item_purchase_chat_path(int $purchase_id): string
    {
        $base = defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__);
        $dir = $base . '/public/uploads/private/chat';
        if (!is_dir($dir)) { @mkdir($dir, 0775, true); }
        return $dir . '/selling_' . sha1('selling_item_purchase_' . $purchase_id) . '.json';
    }

    private function item_chat_normalize_messages(array $messages): array
    {
        $icon_cache = [];
        $normalized = [];

        foreach ($messages as $i => $m) {
            $sender = strtolower((string)($m['sender'] ?? $m['type'] ?? 'seller'));
            $sender_id = (int)($m['sender_id'] ?? 0);
            $body = $m['image_url'] ?? $m['body'] ?? $m['message'] ?? '';
            $message_type = (string)($m['message_type'] ?? (!empty($m['image_url']) ? 'image' : 'text'));

            $icon_key = $sender . ':' . $sender_id;
            if (!isset($icon_cache[$icon_key])) {
                $stored_icon = trim((string)($m['sender_icon'] ?? ''));
                if ($stored_icon !== '') {
                    $icon_cache[$icon_key] = $stored_icon;
                } elseif ($sender_id > 0) {
                    if ($sender === 'client') {
                        $row = db_get_row('clients', ['id' => $sender_id, 'select' => 'icon']);
                    } elseif ($sender === 'seller') {
                        $row = db_get_row('sellers', ['id' => $sender_id, 'select' => 'icon']);
                    } elseif ($sender === 'admin') {
                        $row = db_get_row('admins', ['id' => $sender_id, 'select' => 'icon']);
                    } else {
                        $row = null;
                    }
                    $icon_cache[$icon_key] = !empty($row['icon']) ? (string)$row['icon'] : '';
                } else {
                    $icon_cache[$icon_key] = '';
                }
            }

            $created_at = (string)($m['created_at'] ?? '');
            $normalized[$i] = [
                'id' => (string)($m['id'] ?? ''),
                'sender' => $sender,
                'type' => $sender,
                'sender_id' => $sender_id,
                'sender_name' => (string)($m['sender_name'] ?? ucfirst($sender)),
                'sender_icon' => $icon_cache[$icon_key] ?? '',
                'message_type' => $message_type,
                'body' => $body,
                'message' => $m['message'] ?? $body,
                'content' => $m['content'] ?? ($message_type === 'image' ? '<img src="' . htmlspecialchars((string)$body, ENT_QUOTES) . '" alt="image">' : $body),
                'created_at' => $created_at,
                'created_at_fmt' => $created_at !== '' ? date('d.m.Y H:i', strtotime($created_at)) : '',
                'time' => (int)($m['time'] ?? ($created_at !== '' ? strtotime($created_at) : 0)),
                'notify' => (int)($m['notify'] ?? 0),
                'deleted' => (int)($m['deleted'] ?? 0),
                'seen' => (int)($sender === 'client' ? ($m['seen_by_seller'] ?? $m['seen'] ?? 0) : ($m['seen_by_client'] ?? $m['seen'] ?? 0)),
                'seen_by_seller' => (int)($m['seen_by_seller'] ?? ($sender === 'seller' ? 1 : 0)),
                'seen_by_client' => (int)($m['seen_by_client'] ?? ($sender === 'client' ? 1 : 0)),
                'seen_by_admin' => (int)($m['seen_by_admin'] ?? ($sender === 'admin' ? 1 : 0)),
                'read_at' => !empty($m['read_at']) ? strtotime((string)$m['read_at']) : null,
                'read_at_fmt' => !empty($m['read_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_at'])) : '',
                'read_by_client_at' => !empty($m['read_by_client_at']) ? strtotime((string)$m['read_by_client_at']) : null,
                'read_by_client_at_fmt' => !empty($m['read_by_client_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_client_at'])) : '',
                'read_by_seller_at' => !empty($m['read_by_seller_at']) ? strtotime((string)$m['read_by_seller_at']) : null,
                'read_by_seller_at_fmt' => !empty($m['read_by_seller_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_seller_at'])) : '',
            ];
        }

        return array_values($normalized);
    }

    private function item_chat_realtime_payload(int $purchase_id, array $messages, string $reason = 'update'): array
    {
        return [
            'purchase_id' => $purchase_id,
            'order_id' => 'itempurch_' . $purchase_id,
            'reason' => $reason,
            'messages' => $this->item_chat_normalize_messages($messages),
        ];
    }

    private function item_chat_emit(int $purchase_id, array $messages, string $reason = 'update'): void
    {
        if (!empty($_SERVER['HTTP_X_REALTIME_INTERNAL'])) return;
        $payload = $this->item_chat_realtime_payload($purchase_id, $messages, $reason);
        if (function_exists('lb_realtime_emit')) {
            lb_realtime_emit('item_chat_update', $payload, ['sellers','admins','clients']);
        }
    }

    private function item_chat_append_message(int $purchase_id, string $sender, int $sender_id, string $sender_name, string $message = '', ?string $image_url = null): array
    {
        $chat_path = $this->item_purchase_chat_path($purchase_id);
        $now = date('Y-m-d H:i:s');
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) return ['success' => false, 'message' => 'Could not open chat.'];

        flock($fp, LOCK_EX);
        $raw = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['purchase_id' => $purchase_id, 'messages' => []];
        if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];

        $new_message = [
            'id' => uniqid('msg_', true),
            'sender' => $sender,
            'type' => $sender,
            'sender_id' => $sender_id,
            'sender_name' => $sender_name,
            'message' => $message,
            'body' => $image_url ?: $message,
            'content' => $image_url ? '<img src="' . htmlspecialchars((string)$image_url, ENT_QUOTES) . '" alt="image">' : $message,
            'message_type' => $image_url ? 'image' : 'text',
            'image_url' => $image_url,
            'created_at' => $now,
            'time' => time(),
            'notify' => 0,
            'seen' => 0,
            'seen_by_seller' => ($sender === 'seller') ? 1 : 0,
            'seen_by_client' => ($sender === 'client') ? 1 : 0,
            'seen_by_admin' => ($sender === 'admin') ? 1 : 0,
        ];
        $chat_data['messages'][] = $new_message;

        rewind($fp);
        ftruncate($fp, 0);
        fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
        flock($fp, LOCK_UN);
        fclose($fp);

        if (function_exists('lb_legacy_chat_open')) {
            try {
                $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id], 1) ?: [];
                lb_legacy_chat_open(
                    'seller:item_purchase:' . $purchase_id,
                    'item_purchase',
                    $purchase_id,
                    ['seller_id' => (int)($purchase['seller_id'] ?? 0), 'client_id' => (int)($purchase['client_id'] ?? 0)],
                    $chat_path
                );
            } catch (\Throwable $e) {
                error_log('Item chat DB sync failed: ' . $e->getMessage());
            }
        }

        $messages = array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted'])));
        $normalized = $this->item_chat_normalize_messages($messages);
        $this->item_chat_emit($purchase_id, $messages, 'message');

        return [
            'success' => true,
            'created_at' => $now,
            'image_url' => $image_url,
            'chat_message' => end($normalized) ?: null,
            'messages' => $normalized,
        ];
    }

    public function item_chat_load()
    {
        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        if ($purchase_id <= 0) { echo json_encode(['success' => false, 'messages' => []]); return; }

        // A browser may contain client and seller sessions at the same time.
        // Resolve the role requested by the current view, then validate that role
        // against the authenticated session and purchase ownership.
        $requested_role = strtolower(trim((string)($_POST['viewer_role'] ?? '')));
        $viewer_role = '';
        $purchase = null;

        if ($requested_role === 'client' && $this->is_client) {
            $viewer_role = 'client';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'client_id' => (int)CLIENT_ID], 1);
        } elseif ($requested_role === 'seller' && $this->is_seller) {
            $viewer_role = 'seller';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'seller_id' => (int)$this->seller_data['id']], 1);
        } elseif ($requested_role === 'admin' && $this->is_admin) {
            $viewer_role = 'admin';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id], 1);
        } elseif ($this->is_client) {
            // Backward compatibility for older client views without viewer_role.
            $viewer_role = 'client';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'client_id' => (int)CLIENT_ID], 1);
        } elseif ($this->is_seller) {
            // Backward compatibility for older seller views without viewer_role.
            $viewer_role = 'seller';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'seller_id' => (int)$this->seller_data['id']], 1);
        } elseif ($this->is_admin) {
            $viewer_role = 'admin';
            $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id], 1);
        }
        if (empty($purchase)) { echo json_encode(['success' => false, 'messages' => []]); return; }

        $mark_seen = !empty($_POST['mark_seen']) || !empty($_POST['seen']) || !empty($_POST['set_seen']) || !empty($_POST['mark_read']);
        $path = $this->item_purchase_chat_path($purchase_id);
        $messages = [];
        $changed = false;
        $read_changed = false;
        $fp = @fopen($path, 'c+');

        if ($fp) {
            flock($fp, LOCK_EX);
            $raw = stream_get_contents($fp);
            $chat_data = json_decode($raw ?: '', true);
            if (!is_array($chat_data)) $chat_data = ['purchase_id' => $purchase_id, 'messages' => []];
            if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];
            $now = date('Y-m-d H:i:s');

            foreach ($chat_data['messages'] as &$m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                $sender = strtolower((string)($m['sender'] ?? $m['type'] ?? ''));

                if (empty($m['id'])) { $m['id'] = uniqid('msg_', true); $changed = true; }
                if (!array_key_exists('seen_by_seller', $m)) { $m['seen_by_seller'] = ($sender === 'seller') ? 1 : 0; $changed = true; }
                if (!array_key_exists('seen_by_client', $m)) { $m['seen_by_client'] = ($sender === 'client') ? 1 : 0; $changed = true; }
                if (!array_key_exists('seen_by_admin', $m)) { $m['seen_by_admin'] = ($sender === 'admin') ? 1 : 0; $changed = true; }

                if ($mark_seen && $viewer_role === 'client' && $sender !== 'client' && (int)$m['seen_by_client'] !== 1) {
                    $m['seen_by_client'] = 1;
                    $m['seen'] = 1;
                    $m['read_at'] = $m['read_at'] ?? $now;
                    $m['read_by_client_at'] = $m['read_by_client_at'] ?? $now;
                    $changed = $read_changed = true;
                } elseif ($mark_seen && $viewer_role === 'seller' && $sender === 'client' && (int)$m['seen_by_seller'] !== 1) {
                    $m['seen_by_seller'] = 1;
                    $m['seen'] = 1;
                    $m['read_at'] = $m['read_at'] ?? $now;
                    $m['read_by_seller_at'] = $m['read_by_seller_at'] ?? $now;
                    $changed = $read_changed = true;
                } elseif ($mark_seen && $viewer_role === 'admin' && $sender !== 'admin' && (int)$m['seen_by_admin'] !== 1) {
                    $m['seen_by_admin'] = 1;
                    $changed = $read_changed = true;
                }
            }
            unset($m);

            $messages = array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted'])));
            if ($changed) {
                rewind($fp);
                ftruncate($fp, 0);
                fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            }
            flock($fp, LOCK_UN);
            fclose($fp);

            if ($mark_seen && $viewer_role === 'seller' && function_exists('lb_legacy_chat_sync_seller_seen')) {
                lb_legacy_chat_sync_seller_seen('item_purchase', $purchase_id);
            }
        }

        if ($read_changed) $this->item_chat_emit($purchase_id, $messages, 'read');

        echo json_encode([
            'success' => true,
            'purchase_id' => $purchase_id,
            'order_id' => 'itempurch_' . $purchase_id,
            'viewer_role' => $viewer_role,
            'seller_id' => (int)($purchase['seller_id'] ?? 0),
            'client_id' => (int)($purchase['client_id'] ?? 0),
            'messages' => $this->item_chat_normalize_messages($messages),
        ]);
    }

    public function seller_item_chat_send()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }
        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        $message = trim(esc($_POST['message'] ?? ''));
        $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'seller_id' => (int)$this->seller_data['id']], 1);
        if (empty($purchase)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Order not found.']]);
            return;
        }
        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Image upload failed.']]);
                return;
            }
        }
        if ($message === '' && !$image_url) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Please type a message or attach an image.']]);
            return;
        }
        $res = $this->item_chat_append_message($purchase_id, 'seller', (int)$this->seller_data['id'], $this->seller_data['username'] ?? 'Seller', $message, $image_url);
        if (!empty($res['success']) && function_exists('lb_realtime_schedule_client_unread_email')) { lb_realtime_schedule_client_unread_email(['client_id'=>(int)($purchase['client_id']??0),'seller_id'=>(int)$this->seller_data['id'],'ref_type'=>'item_purchase','ref_id'=>$purchase_id]); }
        echo json_encode($res['success'] ? ['success'=>true,'resetForm'=>true,'reFocus'=>true,'created_at'=>$res['created_at'],'image_url'=>$res['image_url']??null,'chat_message'=>$res['chat_message']??null,'messages'=>$res['messages']??[],'read_receipt_update'=>!empty($res['read_receipt_update'])] : ['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

