    public function seller_item_friendship_confirm()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }
        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        $purchase = db_get_row('selling_item_purchases', ['id' => $purchase_id, 'seller_id' => (int)$this->seller_data['id']], 1);
        if (empty($purchase)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Order not found.']]);
            return;
        }
        if (!empty($purchase['friendship_confirmed_at'])) {
            echo json_encode(['sendToast' => ['type' => 'info', 'message' => 'Friendship was already confirmed.']]);
            return;
        }
        $item = !empty($purchase['item_id']) ? db_get_row('selling_items', ['id' => (int)$purchase['item_id']], 1) : null;
        $days = max(1, (int)($item['requires_friendship_days'] ?? 7));
        $confirmed_at = date('Y-m-d H:i:s');
        $ready_at = date('Y-m-d H:i:s', strtotime('+' . $days . ' days'));
        db_update_row('selling_item_purchases', ['id' => $purchase_id], [
            'friendship_confirmed_at' => $confirmed_at,
            'friendship_ready_at' => $ready_at,
            'friendship_confirmed_by_seller_id' => (int)$this->seller_data['id'],
            'status' => 'WAITING_FRIENDSHIP',
        ]);
        @db_add_row('selling_item_logs', [
            'purchase_id' => $purchase_id,
            'actor_type' => 'seller',
            'actor_id' => (int)$this->seller_data['id'],
            'action' => 'friendship_confirmed',
            'meta' => json_encode(['ready_at' => $ready_at]),
            'created_at' => date('Y-m-d H:i:s'),
        ]);
        echo json_encode(['sendToast' => ['type' => 'success', 'message' => 'Friendship confirmed. 7 day timer started.'], 'refreshPage' => true]);
    }



    private function seller_item_upload_images($prefix = 'item_')
    {
        $uploaded = [];
        if (!isset($_FILES['images']['name']) || !is_array($_FILES['images']['name'])) {
            return $uploaded;
        }
        for ($i = 0; $i < count($_FILES['images']['name']); $i++) {
            if (empty($_FILES['images']['name'][$i]) || (int)$_FILES['images']['error'][$i] !== UPLOAD_ERR_OK) continue;
            $file = [
                'name' => $_FILES['images']['name'][$i],
                'type' => $_FILES['images']['type'][$i],
                'tmp_name' => $_FILES['images']['tmp_name'][$i],
                'error' => $_FILES['images']['error'][$i],
                'size' => $_FILES['images']['size'][$i],
            ];
            $uuid = uniqid($prefix, true);
            $image_url = upload_image($file, 'items-gallery/' . $uuid);
            if ($image_url === false) {
                echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid image: ' . $file['name']], 'playSound' => 'error']);
                exit;
            }
            $uploaded[] = $image_url;
        }
        return $uploaded;
    }

    private function seller_item_merge_images($existing_images, $uploaded_images)
    {
        $existing_images = is_array($existing_images) ? $existing_images : [];
        $uploaded_images = is_array($uploaded_images) ? $uploaded_images : [];
        $posted_order = null;
        if (isset($_POST['images_order']) && $_POST['images_order'] !== '') {
            $posted_order = json_decode((string)$_POST['images_order'], true);
            if (!is_array($posted_order)) $posted_order = null;
        }
        if (!is_array($posted_order)) {
            return array_values(array_merge($existing_images, $uploaded_images));
        }
        $final_images = [];
        $existing_set = array_flip($existing_images);
        $used_new = [];
        foreach ($posted_order as $entry) {
            if (!is_string($entry) || $entry === '') continue;
            if (strpos($entry, '__new__') !== 0) {
                if (isset($existing_set[$entry])) $final_images[] = $entry;
                continue;
            }
            $idx = (int)substr($entry, 7);
            if (isset($uploaded_images[$idx]) && empty($used_new[$idx])) {
                $final_images[] = $uploaded_images[$idx];
                $used_new[$idx] = true;
            }
        }
        foreach ($uploaded_images as $i => $url) {
            if (empty($used_new[$i])) $final_images[] = $url;
        }
        $seen = []; $deduped = [];
        foreach ($final_images as $u) {
            if (!isset($seen[$u])) { $deduped[] = $u; $seen[$u] = true; }
        }
        return array_values($deduped);
    }

    private function seller_item_waiting_time_from_post(array $source, string $gameSlug = '', array $fallbackItem = []): array
    {
        $amount = isset($source['waiting_time_amount']) ? (int)$source['waiting_time_amount'] : 0;
        $unit = strtolower(trim((string)($source['waiting_time_unit'] ?? '')));

        if ($amount < 0 || !in_array($unit, ['minutes','hours','days'], true)) {
            $existingData = [];
            if (!empty($fallbackItem['item_data'])) {
                $decoded = json_decode((string)$fallbackItem['item_data'], true);
                if (is_array($decoded)) $existingData = $decoded;
            }
            $amount = (int)($fallbackItem['waiting_time_amount'] ?? ($existingData['waiting_time_amount'] ?? 0));
            $unit = strtolower(trim((string)($fallbackItem['waiting_time_unit'] ?? ($existingData['waiting_time_unit'] ?? ''))));
        }

        if (($amount <= 0 && $unit !== 'minutes') || $amount < 0 || !in_array($unit, ['minutes','hours','days'], true)) {
            $legacyDays = (int)($fallbackItem['requires_friendship_days'] ?? 0);
            $gameSlug = strtolower(trim($gameSlug));
            if ($legacyDays >= 7 || in_array($gameSlug, ['league-of-legends','lol','league'], true)) {
                $amount = 7;
                $unit = 'days';
            } elseif ($legacyDays > 1) {
                $amount = $legacyDays;
                $unit = 'days';
            } else {
                $amount = 24;
                $unit = 'hours';
            }
        }

        if ($unit === 'minutes') {
            $amount = max(0, min(60, $amount));
        } else {
            $amount = max(1, min(365, $amount));
        }
        $minutes = $unit === 'days' ? $amount * 1440 : ($unit === 'hours' ? $amount * 60 : $amount);
        $days = max(1, (int)ceil($minutes / 1440));
        $labelUnit = $amount === 1 ? rtrim($unit, 's') : $unit;
        return [
            'amount' => $amount,
            'unit' => $unit,
            'minutes' => $minutes,
            'days' => $days,
            'label' => $amount . ' ' . $labelUnit,
        ];
    }

    public function seller_create_item()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        try {
            global $db;
            $this->ensure_selling_schema();
            $this->ensure_selling_items_extra_schema();
        } catch (\Throwable $e) {}

        $validator = new Validator();
        $validation = $validator->make($_POST, [
            'title' => 'required',
            'description' => 'required',
        ]);
        $validation->validate();
        if ($validation->fails()) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'], 'playSound' => 'error', 'validationErrors' => $validation->errors()->firstOfAll()]);
            return;
        }

        $price_input = $_POST['price_display'] ?? $_POST['price'] ?? '0';
        $price_raw = str_replace(',', '.', (string)$price_input);
        $price_cents = (int)round((float)$price_raw * 100);
        if ($price_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid price.'], 'playSound' => 'error']);
            return;
        }

        $uploaded_images = $this->seller_item_upload_images('item_');
        if (empty($uploaded_images)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please upload at least one image.'], 'playSound' => 'error']);
            return;
        }

        $title = trim((string)($_POST['title'] ?? ''));
        $slug = generateUniqueSlug($title, 'selling_items');
        $images = $this->seller_item_merge_images([], $uploaded_images);

        $stock = max(1, (int)($_POST['stock'] ?? 1));
        $min_qty = max(1, (int)($_POST['min_purchase_qty'] ?? 1));
        if ($min_qty > $stock) $min_qty = $stock;
        $max_qty = null;
        if (isset($_POST['max_purchase_qty']) && $_POST['max_purchase_qty'] !== '') {
            $max_qty = max($min_qty, (int)$_POST['max_purchase_qty']);
            if ($max_qty > $stock) $max_qty = $stock;
        }

        $active_value = $_POST['active'] ?? 0;
        $is_active = in_array((string)$active_value, ['1','true','on'], true) ? 1 : 0;

        $gameSlug = strtolower(trim((string)($_POST['game'] ?? 'league-of-legends')));
        $gameId = null;
        try {
            if (function_exists('util_get_game_by_slug')) {
                $g = util_get_game_by_slug($gameSlug);
                if (!empty($g['id'])) $gameId = (int)$g['id'];
            } else {
                $gr = $db->run('SELECT id FROM games WHERE slug = ? LIMIT 1', $gameSlug) ?: [];
                if (!empty($gr[0]['id'])) $gameId = (int)$gr[0]['id'];
            }
        } catch (\Throwable $e) {}
        $itemData = isset($_POST['item_data']) && is_array($_POST['item_data']) ? $_POST['item_data'] : [];
        if (array_key_exists('type', $_POST)) {
            $itemData['type'] = trim((string)$_POST['type']);
        }
        if (array_key_exists('server', $_POST)) {
            $itemData['server'] = strtoupper(trim((string)$_POST['server']));
        }
        $itemData['game'] = $gameSlug;
        $itemData = array_map(static function ($v) { return is_array($v) ? array_values(array_filter($v, static fn($x) => trim((string)$x) !== '')) : trim((string)$v); }, $itemData);
        $itemTypeValue = trim((string)($itemData['type'] ?? ''));
        $itemServerValue = strtoupper(trim((string)($itemData['server'] ?? '')));
        $waitingTime = $this->seller_item_waiting_time_from_post($_POST, $gameSlug);
        $itemData['waiting_time_amount'] = (string)$waitingTime['amount'];
        $itemData['waiting_time_unit'] = $waitingTime['unit'];
        $itemData['waiting_time_minutes'] = (string)$waitingTime['minutes'];
        $itemData['waiting_time_label'] = $waitingTime['label'];
        unset($itemData['delivery_time']);
        $friendshipDaysValue = (int)$waitingTime['days'];

        $data = [
            'seller_id' => (int)$this->seller_data['id'],
            'game' => $gameSlug,
            'game_id' => $gameId,
            'type' => $itemTypeValue,
            'title' => esc($title),
            'slug' => $slug,
            'description' => $_POST['description'] ?? '',
            'images' => json_encode($images),
            'price_type' => 'fixed',
            'price' => $price_cents,
            'currency' => 'EUR',
            'server' => $itemServerValue,
            'item_data' => json_encode($itemData, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            'delivery_type' => 'manual',
            'requires_friendship_days' => $friendshipDaysValue,
            'waiting_time_amount' => (int)$waitingTime['amount'],
            'waiting_time_unit' => $waitingTime['unit'],
            'waiting_time_minutes' => (int)$waitingTime['minutes'],
            'stock' => $stock,
            'min_purchase_qty' => $min_qty,
            'max_purchase_qty' => $max_qty,
            'active' => $is_active,
            'sort_order' => 0,
        ];

        $item_id = db_add_row('selling_items', $data);
        if ($item_id) {
    if ($is_active && function_exists('trigger_notification_sender_async')) {
        @trigger_notification_sender_async();
    }
    echo json_encode([
        'sendToast' => [
            'type' => 'success',
            'title' => 'Saved',
            'message' => 'Your item is now saved successfully.'
        ],
        'playSound' => 'success',
        'redirectUrl' => BASE_URL . '/seller-area/items'
    ]);
} else {
    echo json_encode([
        'sendToast' => [
            'type' => 'danger',
            'title' => 'Error',
            'message' => 'Failed to create item.'
        ],
        'playSound' => 'error'
    ]);
}
    }

    public function seller_update_item()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        try {
            global $db;
            $this->ensure_selling_schema();
            $this->ensure_selling_items_extra_schema();
        } catch (\Throwable $e) {}

        $id = (int)($_POST['id'] ?? 0);
        $item = db_get_row('selling_items', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']], 1);
        if (empty($item)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Item not found.']]);
            return;
        }

        $validator = new Validator();
        $validation = $validator->make($_POST, ['title' => 'required', 'description' => 'required']);
        $validation->validate();
        if ($validation->fails()) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'], 'playSound' => 'error', 'validationErrors' => $validation->errors()->firstOfAll()]);
            return;
        }

        $price_input = $_POST['price_display'] ?? $_POST['price'] ?? '0';
        $price_raw = str_replace(',', '.', (string)$price_input);
        $price_cents = (int)round((float)$price_raw * 100);
        if ($price_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid price.'], 'playSound' => 'error']);
            return;
        }

        $uploaded_images = $this->seller_item_upload_images('item_');
        $existing_images = json_decode((string)($item['images'] ?? '[]'), true);
        if (!is_array($existing_images)) $existing_images = [];
        $final_images = $this->seller_item_merge_images($existing_images, $uploaded_images);
        if (empty($final_images)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please keep at least one image.'], 'playSound' => 'error']);
            return;
        }

        $title = trim((string)($_POST['title'] ?? ''));
        $slug = $item['slug'];
        if ($title !== ($item['title'] ?? '')) {
            $slug = generateUniqueSlug($title, 'selling_items');
        }

        $stock = max(1, (int)($_POST['stock'] ?? ($item['stock'] ?? 1)));
        $min_qty = max(1, (int)($_POST['min_purchase_qty'] ?? ($item['min_purchase_qty'] ?? 1)));
        if ($min_qty > $stock) $min_qty = $stock;
        $max_qty = null;
        if (isset($_POST['max_purchase_qty']) && $_POST['max_purchase_qty'] !== '') {
            $max_qty = max($min_qty, (int)$_POST['max_purchase_qty']);
            if ($max_qty > $stock) $max_qty = $stock;
        }

        $active_value = $_POST['active'] ?? 0;
        $is_active = in_array((string)$active_value, ['1','true','on'], true) ? 1 : 0;

        $gameSlug = strtolower(trim((string)($_POST['game'] ?? ($item['game'] ?? 'league-of-legends'))));
        $gameId = $item['game_id'] ?? null;
        try {
            if (function_exists('util_get_game_by_slug')) {
                $g = util_get_game_by_slug($gameSlug);
                if (!empty($g['id'])) $gameId = (int)$g['id'];
            } else {
                $gr = $db->run('SELECT id FROM games WHERE slug = ? LIMIT 1', $gameSlug) ?: [];
                if (!empty($gr[0]['id'])) $gameId = (int)$gr[0]['id'];
            }
        } catch (\Throwable $e) {}
        $existingItemData = [];
        $decodedExistingItemData = json_decode((string)($item['item_data'] ?? '{}'), true);
        if (is_array($decodedExistingItemData)) $existingItemData = $decodedExistingItemData;
        $itemData = isset($_POST['item_data']) && is_array($_POST['item_data']) ? $_POST['item_data'] : [];
        if (array_key_exists('type', $_POST)) {
            $itemData['type'] = trim((string)$_POST['type']);
        } elseif (isset($itemData['type'])) {
            $itemData['type'] = trim((string)$itemData['type']);
        }
        if (array_key_exists('server', $_POST)) {
            $itemData['server'] = strtoupper(trim((string)$_POST['server']));
        } elseif (isset($itemData['server'])) {
            $itemData['server'] = strtoupper(trim((string)$itemData['server']));
        }
        $itemData['game'] = $gameSlug;
        $itemData = array_map(static function ($v) { return is_array($v) ? array_values(array_filter($v, static fn($x) => trim((string)$x) !== '')) : trim((string)$v); }, $itemData);
        $itemTypeValue = array_key_exists('type', $itemData) ? trim((string)$itemData['type']) : '';
        $itemServerValue = array_key_exists('server', $itemData) ? strtoupper(trim((string)$itemData['server'])) : '';
        $waitingTime = $this->seller_item_waiting_time_from_post($_POST, $gameSlug, is_array($item) ? $item : []);
        $itemData['waiting_time_amount'] = (string)$waitingTime['amount'];
        $itemData['waiting_time_unit'] = $waitingTime['unit'];
        $itemData['waiting_time_minutes'] = (string)$waitingTime['minutes'];
        $itemData['waiting_time_label'] = $waitingTime['label'];
        unset($itemData['delivery_time']);
        $friendshipDaysValue = (int)$waitingTime['days'];

        db_update_row('selling_items', ['id' => $id], [
            'game' => $gameSlug,
            'game_id' => $gameId,
            'type' => $itemTypeValue,
            'title' => esc($title),
            'slug' => $slug,
            'description' => $_POST['description'] ?? '',
            'images' => json_encode($final_images),
            'price' => $price_cents,
            'server' => $itemServerValue,
            'item_data' => json_encode($itemData, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            'requires_friendship_days' => $friendshipDaysValue,
            'waiting_time_amount' => (int)$waitingTime['amount'],
            'waiting_time_unit' => $waitingTime['unit'],
            'waiting_time_minutes' => (int)$waitingTime['minutes'],
            'stock' => $stock,
            'min_purchase_qty' => $min_qty,
            'max_purchase_qty' => $max_qty,
            'active' => $is_active,
        ]);

        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Updated', 'message' => 'Item updated successfully.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    public function seller_mark_item_unlist()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        $item = db_get_row('selling_items', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']], 1);
        if (empty($item)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Item not found.']]); return; }
        db_update_row('selling_items', ['id' => $id], ['active' => 0, 'api_updated_at' => date('Y-m-d H:i:s')]);
        if (function_exists('seller_api_dispatch_item_webhook')) { $updated = db_get_row('selling_items', ['id' => $id], 1) ?: $item; seller_api_dispatch_item_webhook('item.archived', $updated, ['archived_reason' => 'seller_unlist']); }
        echo json_encode(['sendToast' => ['type' => 'success', 'message' => 'Item unlisted.'], 'refreshPage' => true]);
    }

    public function seller_mark_item_active()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        $item = db_get_row('selling_items', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']], 1);
        if (empty($item)) { echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Item not found.']]); return; }
        db_update_row('selling_items', ['id' => $id], ['active' => 1, 'api_updated_at' => date('Y-m-d H:i:s')]);
        if (function_exists('seller_api_dispatch_item_webhook')) { $updated = db_get_row('selling_items', ['id' => $id], 1) ?: $item; seller_api_dispatch_item_webhook('item.listed', $updated); }
        echo json_encode(['sendToast' => ['type' => 'success', 'message' => 'Item activated.'], 'refreshPage' => true]);
    }


    public function prepare_lol_item_order()
    {
        // No login required – mirrors prepare_lol_account_order behaviour exactly.
        // Only the invoice is created here; client_id stays null for guests.
        // The checkout page handles login/register.

        global $db;

        try {
            $this->ensure_selling_schema();
        } catch (\Throwable $e) {}

        $item_id  = (int)($_POST['item_id'] ?? 0);
        $quantity = max(1, (int)($_POST['quantity'] ?? 1));
        $item     = db_get_row('selling_items', ['id' => $item_id, 'active' => 1], 1);

        if (empty($item)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Item not found.'], 'playSound' => 'error']);
            return;
        }

        $stock   = max(0, (int)($item['stock'] ?? 0));
        $min_qty = max(1, (int)($item['min_purchase_qty'] ?? 1));
        $max_qty = !empty($item['max_purchase_qty']) ? (int)$item['max_purchase_qty'] : $stock;

        if ($stock <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Out of stock', 'message' => 'This item is currently out of stock.'], 'playSound' => 'error']);
            return;
        }
        if ($quantity < $min_qty) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Minimum quantity is ' . $min_qty . '.'], 'playSound' => 'error']);
            return;
        }
        if ($quantity > $max_qty) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Maximum quantity is ' . $max_qty . '.'], 'playSound' => 'error']);
            return;
        }
        if ($quantity > $stock) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Only ' . $stock . ' items are in stock.'], 'playSound' => 'error']);
            return;
        }

        $unit_price_eur  = (int)($item['price'] ?? 0);
        $total_price_eur = $unit_price_eur * $quantity;
        $currency        = $_SESSION['currency'] ?? 'EUR';

        $itemGameName = '';
        $itemGameSlug = '';
        $postedGameId = (int)($_POST['game_id'] ?? 0);
        $postedGameSlug = strtolower(trim((string)($_POST['game_slug'] ?? '')));
        try {
            if (!empty($item['game_id'])) {
                $g = $db->row('SELECT id, name, slug FROM games WHERE id = ? LIMIT 1', (int)$item['game_id']);
            } elseif ($postedGameId > 0) {
                $g = $db->row('SELECT id, name, slug FROM games WHERE id = ? LIMIT 1', $postedGameId);
            } elseif ($postedGameSlug !== '') {
                $g = function_exists('util_get_game_by_slug') ? util_get_game_by_slug($postedGameSlug) : null;
            } elseif (!empty($item['game'])) {
                $g = function_exists('util_get_game_by_slug') ? util_get_game_by_slug((string)$item['game']) : null;
            } else {
                $g = null;
            }
            if (is_array($g)) {
                $itemGameName = trim((string)($g['name'] ?? ''));
                $itemGameSlug = trim((string)($g['slug'] ?? ''));
            }
        } catch (Throwable $e) {}
        if ($itemGameName === '') {
            $itemGameName = !empty($item['game']) ? ucwords(str_replace('-', ' ', (string)$item['game'])) : 'Game';
        }

        // Convert to session currency exactly like prepare_lol_account_order
        if ($currency === 'USD') {
            $total_price = (int)round($total_price_eur * get_exchange_rate());
        } else {
            $total_price = $total_price_eur;
        }

        $uuid = Uuid::uuid4()->toString();

        db_add_row('invoices', function_exists('lb_referral_attach_snapshot_to_invoice_data')
            ? lb_referral_attach_snapshot_to_invoice_data([
            'uuid'        => $uuid,
            'order_id'    => $item_id,
            'order_type'  => 'selling_item',
            'price'       => $total_price,
            'price_eur'   => $total_price_eur,
            'total_price' => $total_price,
            'currency'    => $currency,
            'description' => trim($itemGameName . ': ' . ($item['title'] ?? 'Item') . ' x' . $quantity),
            'client_id'   => CLIENT_ID ?? null,
        
            ])
            : [
            'uuid'        => $uuid,
            'order_id'    => $item_id,
            'order_type'  => 'selling_item',
            'price'       => $total_price,
            'price_eur'   => $total_price_eur,
            'total_price' => $total_price,
            'currency'    => $currency,
            'description' => trim($itemGameName . ': ' . ($item['title'] ?? 'Item') . ' x' . $quantity),
            'client_id'   => CLIENT_ID ?? null,
        ]
        );

        echo json_encode(['redirectUrl' => BASE_URL . '/checkout/' . $uuid]);
    }

    public function prepare_topup_order()
    {
        global $db;

        try {
            if (function_exists('lb_topups_table_ensure')) {
                lb_topups_table_ensure();
            }
        } catch (\Throwable $e) {}

        $topup_id = (int)($_POST['topup_id'] ?? 0);
        $quantity = max(1, (int)($_POST['quantity'] ?? 1));

        $topup = $db->row(
            "SELECT st.*, g.name AS db_game_name, g.slug AS db_game_slug
             FROM selling_topups st
             LEFT JOIN games g ON g.id = st.game_id
             WHERE st.id = ? AND COALESCE(st.active, 1) = 1
             LIMIT 1",
            $topup_id
        );

        if (!$topup) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Top up offer not found.'], 'playSound' => 'error']);
            return;
        }

        $stock = max(0, (int)($topup['stock'] ?? 0));
        $min_qty = max(1, (int)($topup['min_quantity'] ?? 1));
        if ($stock <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Out of stock', 'message' => 'This top up is currently out of stock.'], 'playSound' => 'error']);
            return;
        }
        if ($quantity < $min_qty) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Minimum quantity is ' . $min_qty . '.'], 'playSound' => 'error']);
            return;
        }
        if ($quantity > $stock) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Only ' . $stock . ' units are in stock.'], 'playSound' => 'error']);
            return;
        }

        $unit_price_eur = (int)($topup['price'] ?? 0);
        $total_price_eur = $unit_price_eur * $quantity;
        $currency = $_SESSION['currency'] ?? 'EUR';
        $total_price = $currency === 'USD' ? (int)round($total_price_eur * get_exchange_rate()) : $total_price_eur;
        $uuid = Uuid::uuid4()->toString();
        $gameName = trim((string)($topup['db_game_name'] ?? $topup['game_name'] ?? 'Game'));
        $title = trim((string)($topup['offer_title'] ?? 'Top Up'));

        $checkoutFields = [];
        foreach ($_POST as $k => $v) {
            $key = preg_replace('/[^a-z0-9_]/i', '', (string)$k);
            if ($key === '' || in_array($key, ['action', 'topup_id', 'quantity'], true)) continue;
            if (is_array($v)) continue;
            $value = trim((string)$v);
            if ($value === '') continue;
            $checkoutFields[$key] = mb_substr($value, 0, 500);
        }
        try { $db->run("ALTER TABLE invoices ADD COLUMN IF NOT EXISTS checkout_data LONGTEXT NULL"); } catch (Throwable $e) {}

        $invoiceData = [
            'uuid'          => $uuid,
            'order_id'      => $topup_id,
            'order_type'    => 'selling_topup',
            'price'         => $total_price,
            'price_eur'     => $total_price_eur,
            'total_price'   => $total_price,
            'currency'      => $currency,
            'description'   => trim($gameName . ': ' . $title . ' x' . $quantity),
            'client_id'     => CLIENT_ID ?? null,
            'checkout_data' => json_encode(['fields' => $checkoutFields], JSON_UNESCAPED_UNICODE),
        ];
        if (function_exists('lb_referral_attach_snapshot_to_invoice_data')) {
            $invoiceData = lb_referral_attach_snapshot_to_invoice_data($invoiceData);
        }
        db_add_row('invoices', $invoiceData);

        echo json_encode(['redirectUrl' => BASE_URL . '/checkout/' . $uuid]);
    }


    private function topup_purchase_chat_path(int $purchase_id): string
    {
        // Keep Top Up chat storage aligned with Seller Item chat storage.
        // The previous app/storage path could break on installs where BASE_PATH is not defined
        // or the directory is not writable, which made the chat silently fail.
        $base = defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__);
        $dir = $base . '/public/uploads/private/chat';
        if (!is_dir($dir)) { @mkdir($dir, 0775, true); }
        return $dir . '/selling_' . sha1('selling_topup_purchase_' . $purchase_id) . '.json';
    }

    private function topup_chat_append_message(int $purchase_id, string $sender, int $sender_id, string $sender_name, string $message = '', ?string $image_url = null): array
    {
        $chat_path = $this->topup_purchase_chat_path($purchase_id);
        $now = date('Y-m-d H:i:s');
        $fp = @fopen($chat_path, 'c+');
        if (!$fp) return ['success' => false, 'message' => 'Could not open chat.'];
        flock($fp, LOCK_EX);
        $raw = stream_get_contents($fp);
        $chat_data = json_decode($raw ?: '', true);
        if (!is_array($chat_data)) $chat_data = ['purchase_id' => $purchase_id, 'messages' => []];
        if (!isset($chat_data['messages']) || !is_array($chat_data['messages'])) $chat_data['messages'] = [];

        // A reply also acts as a read receipt for all earlier peer messages.
        foreach ($chat_data['messages'] as &$existing_message) {
            if (!is_array($existing_message) || !empty($existing_message['deleted'])) continue;
            $existing_sender = strtolower((string)($existing_message['sender'] ?? $existing_message['type'] ?? ''));
            if ($sender === 'client' && $existing_sender !== 'client' && (int)($existing_message['seen_by_client'] ?? 0) !== 1) {
                $existing_message['seen_by_client'] = 1;
                $existing_message['seen'] = 1;
                $existing_message['read_at'] = $existing_message['read_at'] ?? $now;
                $existing_message['read_by_client_at'] = $existing_message['read_by_client_at'] ?? $now;
            } elseif ($sender === 'seller' && $existing_sender === 'client' && (int)($existing_message['seen_by_seller'] ?? 0) !== 1) {
                $existing_message['seen_by_seller'] = 1;
                $existing_message['seen'] = 1;
                $existing_message['read_at'] = $existing_message['read_at'] ?? $now;
                $existing_message['read_by_seller_at'] = $existing_message['read_by_seller_at'] ?? $now;
            }
        }
        unset($existing_message);

        $new_message = [
            'id' => uniqid('msg_', true),
            'sender' => $sender,
            'sender_id' => $sender_id,
            'sender_name' => $sender_name,
            'message' => $message,
            'body' => $image_url ?: $message,
            'message_type' => $image_url ? 'image' : 'text',
            'image_url' => $image_url,
            'created_at' => $now,
            'seen_by_seller' => ($sender === 'seller') ? 1 : 0,
            'seen_by_client' => ($sender === 'client') ? 1 : 0,
            'seen_by_admin' => ($sender === 'admin') ? 1 : 0,
        ];
        $chat_data['messages'][] = $new_message;
        rewind($fp); ftruncate($fp, 0); fwrite($fp, json_encode($chat_data, JSON_PRETTY_PRINT)); flock($fp, LOCK_UN); fclose($fp);

        if (function_exists('lb_legacy_chat_open')) {
            try {
                $purchase = db_get_row('selling_topup_purchases', ['id' => $purchase_id], 1) ?: [];
                lb_legacy_chat_open(
                    'seller:topup_purchase:' . $purchase_id,
                    'topup_purchase',
                    $purchase_id,
                    ['seller_id' => (int)($purchase['seller_id'] ?? 0), 'client_id' => (int)($purchase['client_id'] ?? 0)],
                    $chat_path
                );
            } catch (\Throwable $e) {
                error_log('Top up chat DB sync failed: ' . $e->getMessage());
            }
        }

        $normalized_messages = $this->topup_chat_normalize_messages(array_values(array_filter($chat_data['messages'], fn($m) => empty($m['deleted']))));
        $normalized_message = end($normalized_messages) ?: null;
        $payload = [
            'purchase_id' => $purchase_id,
            'order_id' => 'topuppurch_' . $purchase_id,
            'chat_message' => $normalized_message,
            'messages' => $normalized_messages,
            'read_receipt_update' => true,
        ];
        $is_realtime_internal = !empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
        if (!$is_realtime_internal && function_exists('lb_realtime_emit')) {
            lb_realtime_emit('topup_chat_update', $payload, ['sellers','admins','clients']);
        }
        if (!$is_realtime_internal && function_exists('lb_realtime_emit_order')) {
            lb_realtime_emit_order('chat_update', 'topuppurch_' . $purchase_id, $payload, ['sellers','admins','clients']);
        }
        return [
            'success' => true,
            'created_at' => $now,
            'image_url' => $image_url,
            'chat_message' => $normalized_message,
            'messages' => $normalized_messages,
            'read_receipt_update' => true,
        ];
    }

    private function topup_chat_normalize_messages(array $messages): array
    {
        $icon_cache = [];
        $normalized = [];

        foreach ($messages as $i => $m) {
            $sender = (string)($m['sender'] ?? $m['type'] ?? 'seller');
            $sender_id = (int)($m['sender_id'] ?? 0);
            $body = $m['image_url'] ?? $m['body'] ?? $m['message'] ?? '';

            $icon_key = strtolower($sender) . ':' . $sender_id;
            if (!isset($icon_cache[$icon_key])) {
                $stored_icon = trim((string)($m['sender_icon'] ?? ''));
                if ($stored_icon !== '') {
                    $icon_cache[$icon_key] = $stored_icon;
                } elseif ($sender_id > 0) {
                    if ($sender === 'client') {
                        $row = db_get_row('clients', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? (string)$row['icon'] : '';
                    } elseif ($sender === 'seller') {
                        $row = db_get_row('sellers', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? (string)$row['icon'] : '';
                    } elseif ($sender === 'admin') {
                        $row = db_get_row('admins', ['id' => $sender_id, 'select' => 'icon']);
                        $icon_cache[$icon_key] = !empty($row['icon']) ? (string)$row['icon'] : '';
                    } else {
                        $icon_cache[$icon_key] = '';
                    }
                } else {
                    $icon_cache[$icon_key] = '';
                }
            }

            $normalized[$i] = [
                'id' => $m['id'] ?? uniqid('msg_', true),
                'sender' => $sender,
                'sender_id' => $sender_id,
                'sender_name' => $m['sender_name'] ?? ucfirst((string)$sender),
                'sender_icon' => $icon_cache[$icon_key] ?? '',
                'message_type' => $m['message_type'] ?? (!empty($m['image_url']) ? 'image' : 'text'),
                'body' => $body,
                'created_at' => $m['created_at'] ?? '',
                'created_at_fmt' => !empty($m['created_at']) ? date('d.m.Y H:i', strtotime((string)$m['created_at'])) : '',
                'seen' => (int)($sender === 'client' ? ($m['seen_by_seller'] ?? $m['seen'] ?? 0) : ($m['seen_by_client'] ?? $m['seen'] ?? 0)),
                'seen_by_seller' => (int)($m['seen_by_seller'] ?? ($sender === 'seller' ? 1 : 0)),
                'seen_by_client' => (int)($m['seen_by_client'] ?? ($sender === 'client' ? 1 : 0)),
                'read_at' => !empty($m['read_at']) ? strtotime((string)$m['read_at']) : null,
                'read_at_fmt' => !empty($m['read_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_at'])) : '',
                'read_by_client_at' => !empty($m['read_by_client_at']) ? strtotime((string)$m['read_by_client_at']) : null,
                'read_by_client_at_fmt' => !empty($m['read_by_client_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_client_at'])) : '',
                'read_by_seller_at' => !empty($m['read_by_seller_at']) ? strtotime((string)$m['read_by_seller_at']) : null,
                'read_by_seller_at_fmt' => !empty($m['read_by_seller_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_seller_at'])) : '',
            ];
        }

        return array_values($normalized);
    }

    public function topup_chat_load()
    {
        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        if ($purchase_id <= 0) { echo json_encode(['success'=>false,'messages'=>[]]); return; }
        if ($this->is_seller) $purchase = db_get_row('selling_topup_purchases', ['id'=>$purchase_id,'seller_id'=>(int)$this->seller_data['id']], 1);
        elseif ($this->is_client) $purchase = db_get_row('selling_topup_purchases', ['id'=>$purchase_id,'client_id'=>(int)CLIENT_ID], 1);
        elseif ($this->is_admin) $purchase = db_get_row('selling_topup_purchases', ['id'=>$purchase_id], 1);
        else $purchase = null;
        if (empty($purchase)) { echo json_encode(['success'=>false,'messages'=>[]]); return; }
        $path = $this->topup_purchase_chat_path($purchase_id);
        $messages = [];
        $fp = @fopen($path, 'c+');
        if ($fp) {
            flock($fp, LOCK_EX); $raw = stream_get_contents($fp); $decoded = json_decode($raw ?: '', true);
            $changed = false;
            if (is_array($decoded) && isset($decoded['messages']) && is_array($decoded['messages'])) {
                $mark_seen = !empty($_POST['mark_seen']) || !empty($_POST['seen']) || !empty($_POST['set_seen']) || !empty($_POST['mark_read']);
                if ($mark_seen) {
                    foreach ($decoded['messages'] as &$m) {
                        $sender = strtolower((string)($m['sender'] ?? $m['type'] ?? ''));
                        if ($this->is_client && $sender !== 'client' && (int)($m['seen_by_client'] ?? 0) !== 1) {
                            $m['seen_by_client'] = 1; $m['seen'] = 1; $m['read_at'] = $m['read_at'] ?? date('Y-m-d H:i:s'); $changed = true;
                        }
                        if ($this->is_seller && $sender === 'client' && (int)($m['seen_by_seller'] ?? 0) !== 1) {
                            $readNow = date('Y-m-d H:i:s');
                            $m['seen_by_seller'] = 1;
                            $m['seen'] = 1;
                            $m['read_at'] = $m['read_at'] ?? $readNow;
                            $m['read_by_seller_at'] = $m['read_by_seller_at'] ?? $readNow;
                            $changed = true;
                        }
                    }
                    unset($m);
                }
                $messages = array_values(array_filter($decoded['messages'], fn($m)=>empty($m['deleted'])));
            }
            if ($changed) { rewind($fp); ftruncate($fp,0); fwrite($fp,json_encode($decoded,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)); }
            flock($fp, LOCK_UN); fclose($fp);

            if ($changed && $this->is_seller && function_exists('lb_legacy_chat_sync_seller_seen')) {
                lb_legacy_chat_sync_seller_seen('item_purchase', $purchase_id);
            }

            if ($changed) {
                $payload = [
                    'purchase_id' => $purchase_id,
                    'order_id' => 'topuppurch_' . $purchase_id,
                    'messages' => $this->topup_chat_normalize_messages($messages),
                    'read_receipt_update' => true,
                ];
                $is_realtime_internal = !empty($_SERVER['HTTP_X_REALTIME_INTERNAL']);
                if (!$is_realtime_internal && function_exists('lb_realtime_emit')) { lb_realtime_emit('topup_chat_update', $payload, ['sellers','admins','clients']); }
                if (!$is_realtime_internal && function_exists('lb_realtime_emit_order')) { lb_realtime_emit_order('chat_update', 'topuppurch_' . $purchase_id, $payload, ['sellers','admins','clients']); }
            }
        }
        $viewer_role = $this->is_seller ? 'seller' : ($this->is_client ? 'client' : ($this->is_admin ? 'admin' : ''));
        echo json_encode([
            'success' => true,
            'purchase_id' => $purchase_id,
            'order_id' => 'topuppurch_' . $purchase_id,
            'viewer_role' => $viewer_role,
            'seller_id' => (int)($purchase['seller_id'] ?? 0),
            'client_id' => (int)($purchase['client_id'] ?? 0),
            'messages' => $this->topup_chat_normalize_messages($messages),
        ]);
    }

    public function client_topup_chat_send()
    {
        if (!$this->is_client) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $purchase_id=(int)($_POST['purchase_id']??0); $message=trim(esc($_POST['message']??''));
        $purchase=db_get_row('selling_topup_purchases',['id'=>$purchase_id,'client_id'=>(int)CLIENT_ID],1);
        if (empty($purchase)) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return; }
        $image_url=null; if(isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])){ $image_url=upload_image($_FILES['chat_image'],'private/chat_images'); if($image_url===false){ echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }}
        if($message==='' && !$image_url){ echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $client=db_get_row('clients',['id'=>(int)CLIENT_ID],1); $name=$client['username']??$client['email']??'Client';
        $res=$this->topup_chat_append_message($purchase_id,'client',(int)CLIENT_ID,$name,$message,$image_url);
        if (!empty($res['success']) && function_exists('lb_realtime_schedule_seller_unread_email')) {
            lb_realtime_schedule_seller_unread_email([
                'seller_id'=>(int)($purchase['seller_id']??0),
                'client_id'=>(int)CLIENT_ID,
                'ref_type'=>'topup_purchase',
                'ref_id'=>$purchase_id,
            ]);
        }
        echo json_encode($res['success']?['success'=>true,'resetForm'=>true,'reFocus'=>true,'created_at'=>$res['created_at'],'image_url'=>$res['image_url']??null,'chat_message'=>$res['chat_message']??null,'messages'=>$res['messages']??[],'read_receipt_update'=>!empty($res['read_receipt_update'])]:['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

    public function client_topup_report_problem()
    {
        header('Content-Type: application/json; charset=utf-8');
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        $issue_key   = strtolower(trim((string)($_POST['issue'] ?? '')));
        $details     = trim(strip_tags((string)($_POST['details'] ?? '')));
        $allowed = [
            'delivery'     => 'Delivery is taking too long',
            'wrong_amount' => 'Wrong amount or product',
            'seller'       => 'Seller is not responding',
            'account'      => 'Problem with submitted details',
            'other'        => 'Other problem',
        ];
        if ($purchase_id <= 0 || !isset($allowed[$issue_key])) {
            echo json_encode(['success' => false, 'message' => 'Invalid report.']);
            return;
        }
        if (function_exists('mb_substr')) $details = mb_substr($details, 0, 1000, 'UTF-8');
        else $details = substr($details, 0, 1000);

        global $db;
        $purchase = $db->row(
            "SELECT p.*, s.username AS seller_username, s.discord_id AS seller_discord_id, c.username AS client_username
             FROM selling_topup_purchases p
             LEFT JOIN sellers s ON s.id = p.seller_id
             LEFT JOIN clients c ON c.id = p.client_id
             WHERE p.id = ? AND p.client_id = ? LIMIT 1",
            $purchase_id,
            (int)CLIENT_ID
        );
        if (empty($purchase)) {
            echo json_encode(['success' => false, 'message' => 'Order not found.']);
            return;
        }

        $base = defined('BASE_URL') ? rtrim(BASE_URL, '/') : 'https://lolboost.gg';
        $admin_base = defined('ADMN_URL') ? rtrim(ADMN_URL, '/') : ($base . '/admin-area');
        $seller_name = trim((string)($purchase['seller_username'] ?? 'Seller')) ?: 'Seller';
        $client_name = trim((string)($purchase['client_username'] ?? 'Client')) ?: 'Client';
        $offer = trim((string)($purchase['offer_title'] ?? 'Top Up')) ?: 'Top Up';
        $game = trim((string)($purchase['game_name'] ?? 'Game')) ?: 'Game';
        $issue_label = $allowed[$issue_key];

        $fields = [
            ['name' => '🎮 Order', 'value' => '**' . $offer . '** (#' . $purchase_id . ')', 'inline' => true],
            ['name' => '🕹️ Game', 'value' => $game, 'inline' => true],
            ['name' => '🏪 Seller', 'value' => $seller_name, 'inline' => true],
            ['name' => '👤 Client', 'value' => $client_name . ' (#' . (int)CLIENT_ID . ')', 'inline' => true],
            ['name' => '⚠️ Issue', 'value' => $issue_label, 'inline' => false],
        ];
        if ($details !== '') $fields[] = ['name' => '📝 Details', 'value' => $details, 'inline' => false];
        $fields[] = ['name' => '🔗 Admin', 'value' => '[Open Top Up Order](' . $admin_base . '/top-up-order/' . $purchase_id . ')', 'inline' => false];
        $fields[] = ['name' => '💬 Seller Order', 'value' => '[Open in Seller Area](' . $base . '/seller-area/top-up-order/' . $purchase_id . ')', 'inline' => false];

        $payload = [
            'username' => 'Top Up Reports',
            'embeds' => [[
                'title' => '🚨 Top Up Problem Report',
                'description' => 'A client reported a problem with a top up order.',
                'color' => 0xef4444,
                'fields' => $fields,
                'footer' => ['text' => 'Reported via lolboost.gg'],
                'timestamp' => date('c'),
            ]],
        ];

        $webhook_ok = false;
        $webhook_url = lb_seller_notification_webhook_url('topup_problem');
        try {
            $ch = curl_init($webhook_url);
            curl_setopt_array($ch, [
                CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
                CURLOPT_POST => 1,
                CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT => 8,
            ]);
            curl_exec($ch);
            $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            $webhook_ok = ($status >= 200 && $status < 300);
        } catch (\Throwable $e) {}

        $seller_dm_sent = false;
        if (!empty($purchase['seller_discord_id'])) {
            $dm_payload = $payload;
            unset($dm_payload['username']);
            $dm_payload['embeds'][0]['title'] = '🚨 A Client Reported Your Top Up Order';
            $dm_payload['embeds'][0]['description'] = 'Please review the problem and reply to the customer as soon as possible.';
            $seller_dm_sent = $this->seller_chat_send_discord_dm_payload((string)$purchase['seller_discord_id'], $dm_payload);
        }

        if (!$webhook_ok) {
            echo json_encode(['success' => false, 'message' => 'The report channel could not be reached.']);
            return;
        }
        echo json_encode(['success' => true, 'seller_dm_sent' => $seller_dm_sent]);
    }

    /**
     * Client "report a problem" for account, item and digital good orders.
     * Posts into the matching SELLER NOTIFICATION thread and also DMs the seller,
     * the same way the top up report already does.
     */
    public function client_report_problem()
    {
        header('Content-Type: application/json; charset=utf-8');

        if (!$this->is_client) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized.']);
            return;
        }

        global $db;

        $ref_type = strtolower(trim((string)($_POST['ref_type'] ?? '')));
        $ref_id   = (int)($_POST['ref_id'] ?? 0);
        $issue    = trim(strip_tags((string)($_POST['issue_label'] ?? $_POST['issue'] ?? '')));
        $details  = trim(strip_tags((string)($_POST['details'] ?? '')));
        $client_id = (int)CLIENT_ID;

        if ($ref_id <= 0 || $issue === '') {
            echo json_encode(['success' => false, 'message' => 'Invalid report.']);
            return;
        }
        $details = function_exists('mb_substr') ? mb_substr($details, 0, 1000, 'UTF-8') : substr($details, 0, 1000);

        $base = defined('BASE_URL') ? rtrim(BASE_URL, '/') : 'https://lolboost.gg';
        $admin_base = defined('ADMN_URL') ? rtrim(ADMN_URL, '/') : ($base . '/admin-area');

        $seller_id = 0; $seller_discord = ''; $seller_name = 'Seller';
        $title = ''; $subject_label = ''; $webhook_type = ''; $admin_url = ''; $seller_url = '';

        if ($ref_type === 'item' || $ref_type === 'item_purchase') {
            $row = $db->row(
                "SELECT p.*, i.title AS item_title, s.username AS seller_username, s.discord_id AS seller_discord_id
                 FROM selling_item_purchases p
                 LEFT JOIN selling_items i ON i.id = p.item_id
                 LEFT JOIN sellers s ON s.id = p.seller_id
                 WHERE p.id = ? AND p.client_id = ? LIMIT 1",
                $ref_id, $client_id
            );
            if (empty($row)) { echo json_encode(['success' => false, 'message' => 'Order not found.']); return; }
            $seller_id = (int)($row['seller_id'] ?? 0);
            $seller_discord = (string)($row['seller_discord_id'] ?? '');
            $seller_name = trim((string)($row['seller_username'] ?? 'Seller')) ?: 'Seller';
            $title = trim((string)($row['item_title'] ?? 'Item')) ?: 'Item';
            $subject_label = 'Item Order';
            $webhook_type = 'item_problem';
            $admin_url = $admin_base . '/selling-item-purchase/' . $ref_id;
            $seller_url = $base . '/seller-area/item-order/' . $ref_id;

        } elseif ($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') {
            $row = $db->row(
                "SELECT p.*, g.title AS item_title, s.username AS seller_username, s.discord_id AS seller_discord_id
                 FROM digital_good_purchases p
                 LEFT JOIN digital_goods g ON g.id = p.item_id
                 LEFT JOIN sellers s ON s.id = p.seller_id
                 WHERE p.id = ? AND p.client_id = ? LIMIT 1",
