            );
            if (empty($row)) { echo json_encode(['success' => false, 'message' => 'Order not found.']); return; }
            $seller_id = (int)($row['seller_id'] ?? 0);
            $seller_discord = (string)($row['seller_discord_id'] ?? '');
            $seller_name = trim((string)($row['seller_username'] ?? 'Seller')) ?: 'Seller';
            $title = trim((string)($row['item_title'] ?? 'Digital Good')) ?: 'Digital Good';
            $subject_label = 'Digital Good Order';
            $webhook_type = 'digital_good_problem';
            $admin_url = $admin_base . '/digital-good-order/' . $ref_id;
            $seller_url = $base . '/seller-area/digital-goods/order/' . $ref_id;

        } elseif ($ref_type === 'premium_account') {
