                "SELECT a.*, s.username AS seller_username, s.discord_id AS seller_discord_id
                 FROM selling_accounts a
                 LEFT JOIN sellers s ON s.id = a.seller_id
                 WHERE a.id = ? AND a.client_id = ? LIMIT 1",
