        $fields[] = ['name' => '🔗 Admin', 'value' => '[Open in Admin Panel](' . $admin_url . ')', 'inline' => false];
        if ($seller_url !== '') $fields[] = ['name' => '💬 Seller Order', 'value' => '[Open in Seller Area](' . $seller_url . ')', 'inline' => false];

        $payload = [
