                'description' => 'A client reported a problem with a ' . strtolower($subject_label) . '.',
                'color' => 0xef4444,
                'fields' => $fields,
                'footer' => ['text' => 'Reported via lolboost.gg'],
                'timestamp' => date('c'),
            ]],
        ];

        $webhook_ok = false;
        try {
            $ch = curl_init(lb_seller_notification_webhook_url($webhook_type));
            curl_setopt_array($ch, [
                CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
                CURLOPT_POST => 1,
                CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT => 8,
            ]);
            curl_exec($ch);
            $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            $webhook_ok = ($status >= 200 && $status < 300);
        } catch (\Throwable $e) {}

        $seller_dm_sent = false;
        if ($seller_discord !== '') {
            $dm_payload = $payload;
            unset($dm_payload['username']);
            $dm_payload['embeds'][0]['title'] = '🚨 A Client Reported Your ' . $subject_label;
            $dm_payload['embeds'][0]['description'] = 'Please review the problem and reply to the customer as soon as possible.';
            $seller_dm_sent = $this->seller_chat_send_discord_dm_payload($seller_discord, $dm_payload);
        }

        if (!$webhook_ok) {
            echo json_encode(['success' => false, 'message' => 'The report channel could not be reached.']);
            return;
        }
        echo json_encode(['success' => true, 'seller_dm_sent' => $seller_dm_sent]);
    }

    public function seller_topup_chat_send()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $purchase_id=(int)($_POST['purchase_id']??0); $message=trim(esc($_POST['message']??''));
        $purchase=db_get_row('selling_topup_purchases',['id'=>$purchase_id,'seller_id'=>(int)$this->seller_data['id']],1);
        if (empty($purchase)) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return; }
        $image_url=null; if(isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])){ $image_url=upload_image($_FILES['chat_image'],'private/chat_images'); if($image_url===false){ echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }}
        if($message==='' && !$image_url){ echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $res=$this->topup_chat_append_message($purchase_id,'seller',(int)$this->seller_data['id'],$this->seller_data['username']??'Seller',$message,$image_url);
        if (!empty($res['success']) && function_exists('lb_realtime_schedule_client_unread_email')) { lb_realtime_schedule_client_unread_email(['client_id'=>(int)($purchase['client_id']??0),'seller_id'=>(int)$this->seller_data['id'],'ref_type'=>'topup_purchase','ref_id'=>$purchase_id]); }
        echo json_encode($res['success']?['success'=>true,'resetForm'=>true,'reFocus'=>true,'created_at'=>$res['created_at'],'image_url'=>$res['image_url']??null,'chat_message'=>$res['chat_message']??null,'messages'=>$res['messages']??[],'read_receipt_update'=>!empty($res['read_receipt_update'])]:['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

    public function admin_topup_chat_send()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $purchase_id = (int)($_POST['purchase_id'] ?? 0);
        $message = trim(esc($_POST['message'] ?? ''));
        if (empty(db_get_row('selling_topup_purchases', ['id'=>$purchase_id], 1))) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return;
        }
        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }
        }
        if ($message === '' && !$image_url) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $res = $this->topup_chat_append_message($purchase_id, 'admin', (int)ADMIN_ID, ADMIN_DATA['username'] ?? 'Admin', $message, $image_url);
        echo json_encode(!empty($res['success']) ? ['success'=>true,'resetForm'=>true,'messages'=>$res['messages']??[]] : ['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

    public function seller_toggle_item_active()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id     = (int)($_POST['id'] ?? 0);
        $active = (int)($_POST['active'] ?? 0);
        $item   = db_get_row('selling_items', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']], 1);

        if (empty($item)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Item not found.']]);
            return;
        }

        db_update_row('selling_items', ['id' => $id], ['active' => $active ? 1 : 0, 'api_updated_at' => date('Y-m-d H:i:s')]);
        if (function_exists('seller_api_dispatch_item_webhook')) { $updated = db_get_row('selling_items', ['id' => $id], 1) ?: $item; seller_api_dispatch_item_webhook($active ? 'item.listed' : 'item.archived', $updated, $active ? [] : ['archived_reason' => 'seller_toggle']); }

        $msg = $active ? 'Item is now listed and visible.' : 'Item unlisted and hidden from the shop.';
        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => $active ? 'Relisted' : 'Unlisted', 'message' => $msg],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_delete_item()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        $id   = (int)($_POST['id'] ?? 0);
        $item = db_get_row('selling_items', ['id' => $id, 'seller_id' => (int)$this->seller_data['id']], 1);

        if (empty($item)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Item not found.']]);
            return;
        }

        $sold_count = (int)($item['sold_count'] ?? 0);
        if ($sold_count > 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Cannot delete an item that has been sold.']]);
            return;
        }

        db_delete_rows('selling_items', ['id' => $id]);

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Deleted', 'message' => 'Item removed successfully.'],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_bulk_delete_items()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        $ids = $_POST['ids'] ?? [];
        if (!is_array($ids)) $ids = [$ids];
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));

        if (empty($ids)) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Nothing selected', 'message' => 'Please select at least one item.']]);
            return;
        }

        $seller_id = (int)$this->seller_data['id'];
        $deleted   = 0;
        $skipped   = 0;

        foreach ($ids as $item_id) {
            $item = db_get_row('selling_items', ['id' => $item_id, 'seller_id' => $seller_id], 1);
            if (empty($item)) { $skipped++; continue; }
            if ((int)($item['sold_count'] ?? 0) > 0) { $skipped++; continue; }
            db_delete_rows('selling_items', ['id' => $item_id]);
            $deleted++;
        }

        $msg = $deleted . ' item(s) deleted successfully.';
        if ($skipped > 0) $msg .= ' ' . $skipped . ' skipped (sold or not found).';

        echo json_encode([
            'sendToast'   => ['type' => 'success', 'title' => 'Deleted', 'message' => $msg],
            'playSound'   => 'success',
            'refreshPage' => true,
        ]);
    }

    public function seller_bulk_delete_item_orders()
    {
        if (!$this->is_seller) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }
    
        $ids = $_POST['ids'] ?? [];
        if (!is_array($ids)) $ids = [$ids];
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
    
        if (empty($ids)) {
            echo json_encode(['sendToast' => ['type' => 'warning', 'title' => 'Nothing selected', 'message' => 'Please select at least one item order.']]);
            return;
        }
    
        global $db;
        $deleted = 0;
    
        foreach ($ids as $purchase_id) {
            $purchase = db_get_row('selling_item_purchases', [
                'id' => $purchase_id,
                'seller_id' => (int)$this->seller_data['id']
            ], 1);
    
            if (empty($purchase)) continue;
    
            if (!empty($purchase['invoice_id'])) {
                @db_delete_rows('invoices', ['id' => (int)$purchase['invoice_id']]);
            }
    
            @db_delete_rows('selling_item_purchase_details', ['purchase_id' => $purchase_id]);
            @db_delete_rows('selling_item_logs', ['purchase_id' => $purchase_id]);
            @db_delete_rows('selling_item_purchases', ['id' => $purchase_id]);
    
            $chat_path = SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_item_purchase_' . $purchase_id) . '.json';
            if (is_file($chat_path)) @unlink($chat_path);
    
            $deleted++;
        }
    
        echo json_encode([
            'sendToast' => [
                'type' => 'success',
                'title' => 'Deleted',
                'message' => $deleted . ' item order(s) deleted successfully.'
            ],
            'refreshPage' => true,
        ]);
    }

