    public function admin_update_item()
    {
        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.']]);
            return;
        }

        try {
            global $db;
            $this->ensure_selling_schema();
        } catch (\Throwable $e) {}

        $id = (int)($_POST['id'] ?? 0);
        $item = db_get_row('selling_items', ['id' => $id], 1);
        if (empty($item)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Item not found.']]);
            return;
        }

        $validator = new Validator();
        $validation = $validator->make($_POST, ['title' => 'required', 'description' => 'required']);
        $validation->validate();
        if ($validation->fails()) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please fill in all required fields.'], 'playSound' => 'error', 'validationErrors' => $validation->errors()->firstOfAll()]);
            return;
        }

        $price_input = $_POST['price_display'] ?? $_POST['price'] ?? '0';
        $price_raw = str_replace(',', '.', (string)$price_input);
        $price_cents = (int)round((float)$price_raw * 100);
        if ($price_cents <= 0) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please enter a valid price.'], 'playSound' => 'error']);
            return;
        }

        $uploaded_images = $this->seller_item_upload_images('item_');
        $existing_images = json_decode((string)($item['images'] ?? '[]'), true);
        if (!is_array($existing_images)) $existing_images = [];
        $final_images = $this->seller_item_merge_images($existing_images, $uploaded_images);
        if (empty($final_images)) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Please keep at least one image.'], 'playSound' => 'error']);
            return;
        }

        $title = trim((string)($_POST['title'] ?? ''));
        $slug = $item['slug'];
        if ($title !== ($item['title'] ?? '')) {
            $slug = generateUniqueSlug($title, 'selling_items');
        }

        $stock = max(1, (int)($_POST['stock'] ?? ($item['stock'] ?? 1)));
        $min_qty = max(1, (int)($_POST['min_purchase_qty'] ?? ($item['min_purchase_qty'] ?? 1)));
        if ($min_qty > $stock) $min_qty = $stock;
        $max_qty = null;
        if (isset($_POST['max_purchase_qty']) && $_POST['max_purchase_qty'] !== '') {
            $max_qty = max($min_qty, (int)$_POST['max_purchase_qty']);
            if ($max_qty > $stock) $max_qty = $stock;
        }

        $active_value = $_POST['active'] ?? $item['active'] ?? 1;
        $is_active = in_array((string)$active_value, ['1','true','on'], true) ? 1 : 0;

        db_update_row('selling_items', ['id' => $id], [
            'game'                    => $_POST['game'] ?? ($item['game'] ?? 'league-of-legends'),
            'type'                    => $_POST['type'] ?? ($item['type'] ?? 'skins'),
            'title'                   => esc($title),
            'slug'                    => $slug,
            'description'             => $_POST['description'] ?? '',
            'delivery_instructions'   => $_POST['delivery_instructions'] ?? '',
            'images'                  => json_encode($final_images),
            'price'                   => $price_cents,
            'server'                  => strtoupper(trim((string)($_POST['server'] ?? 'EUW'))),
            'requires_friendship_days'=> max(0, (int)($_POST['requires_friendship_days'] ?? 7)),
            'stock'                   => $stock,
            'min_purchase_qty'        => $min_qty,
            'max_purchase_qty'        => $max_qty,
            'active'                  => $is_active,
        ]);

        echo json_encode(['sendToast' => ['type' => 'success', 'title' => 'Updated', 'message' => 'Item updated successfully.'], 'playSound' => 'success', 'refreshPage' => true]);
    }

    // =============================================
    // JOB APPLICATIONS
    // =============================================

    private function job_application_is_booster_role($role): bool
    {
        // 'booster' is the generic role used for every game that has no dedicated
        // lol/tft/val booster role (Apex, Fortnite, Rocket League, OW2, CS2,
        // Marvel Rivals, Wild Rift, ...). It follows the same trial flow.
        return in_array((string)$role, ['lol_booster', 'tft_booster', 'val_booster', 'booster'], true);
    }

    private function job_application_role_label($role): string
    {
        $map = [
            'lol_booster' => 'LoL Booster',
            'tft_booster' => 'TFT Booster',
            'val_booster' => 'VAL Booster',
            'booster'     => 'Booster',
            'gg_girl'     => 'GG Girl',
            'seller'      => 'Seller',
        ];

        return $map[(string)$role] ?? ucfirst(str_replace('_', ' ', (string)$role));
    }

    /**
     * Resolves the Discord thread + sender icon for an application, so the apply
     * notice and the later hired notice always land in the same place.
     *
     * @return array{url:string,icon:string}
     */
    private function job_application_webhook_target(array $application): array
    {
        $role = (string)($application['role'] ?? '');
        $lbggIcon = 'https://lolboost.gg/public/uploads/icons/default1.png';

        // TODO: this base webhook URL is temporary and will be replaced.
        $applyBaseWebhook = 'https://discord.com/api/webhooks/1530506345957294152/4tcb-slVC9qS5Is1_Bn6jUTkTM7tzGCbfo2Dtv2Klq6g_QTbIqS6niXMdyVJcwxu1K-j';

        $threadByRole = [
            'lol_booster' => '1530506238536847440',
            'val_booster' => '1530506197462028399',
            'tft_booster' => '1530506143485661204',
            'gg_girl'     => '1530507078144102460',
            'seller'      => '1530506991087124640',
        ];
        $threadByGame = [
            'lol'           => '1530506238536847440',
            'val'           => '1530506197462028399',
            'tft'           => '1530506143485661204',
            'cs2'           => '1530506099348996137',
            'fortnite'      => '1530506047075389480',
            'wild-rift'     => '1530505999277101189',
            'overwatch'     => '1530505964032229386',
            'rocket-league' => '1530505915898400768',
            'apex'          => '1530505862781603930',
            'marvel-rivals' => '1530505692258111600',
        ];
        $otherGamesThread = '1530505790232858674';
        $gameIconFiles = [
            'lol'           => 'league-of-legends.png',
            'val'           => 'valorant.png',
            'tft'           => 'teamfight-tactics.png',
            'cs2'           => 'counter-strike-2.png',
            'fortnite'      => 'fortnite.png',
            'wild-rift'     => 'lol-wild-rift.png',
            'overwatch'     => 'overwatch-2.png',
            'rocket-league' => 'rocket-league.png',
            'apex'          => 'apex-legends.png',
            'marvel-rivals' => 'marvel-rivals.png',
        ];

        $gameKey = static function (string $game): ?string {
            $g = strtolower(trim($game));
            if ($g === '') return null;
            if (strpos($g, 'wild') !== false) return 'wild-rift';
            if (strpos($g, 'league of legends') !== false || $g === 'lol') return 'lol';
            if (strpos($g, 'valorant') !== false || $g === 'val') return 'val';
            if (strpos($g, 'teamfight') !== false || strpos($g, 'tft') !== false) return 'tft';
            if (strpos($g, 'counter') !== false || strpos($g, 'cs2') !== false || strpos($g, 'cs 2') !== false) return 'cs2';
            if (strpos($g, 'fortnite') !== false) return 'fortnite';
            if (strpos($g, 'overwatch') !== false) return 'overwatch';
            if (strpos($g, 'rocket') !== false) return 'rocket-league';
            if (strpos($g, 'apex') !== false) return 'apex';
            if (strpos($g, 'marvel') !== false || strpos($g, 'rivals') !== false) return 'marvel-rivals';
            return null;
        };

        $boostGame = trim((string)($application['boost_game'] ?? ''));
        if ($role === 'booster') {
            $key = $gameKey($boostGame);
            $threadId = $key !== null ? ($threadByGame[$key] ?? $otherGamesThread) : $otherGamesThread;
            $iconKey = $key;
            $channelKey = $key ?? 'other-games';
        } else {
            $threadId = $threadByRole[$role] ?? '';
            $iconKey = ['lol_booster' => 'lol', 'val_booster' => 'val', 'tft_booster' => 'tft'][$role] ?? null;
            $channelKey = ['lol_booster' => 'lol', 'val_booster' => 'val', 'tft_booster' => 'tft', 'gg_girl' => 'gg_girl', 'seller' => 'seller'][$role] ?? '';
        }

        $icon = ($iconKey !== null && isset($gameIconFiles[$iconKey]))
            ? 'https://lolboost.gg/public/assets/website/images/icons/' . $gameIconFiles[$iconKey]
            : $lbggIcon;

        // Prefer the plain channel once configured, otherwise the forum thread.
        $channelUrl = ($channelKey !== '' && function_exists('lb_discord_channel_webhook'))
            ? lb_discord_channel_webhook('apply', $channelKey)
            : '';
        if ($channelUrl !== '') {
            return ['url' => $channelUrl, 'icon' => $icon];
        }

        if ($threadId === '' || $applyBaseWebhook === '') {
            return ['url' => '', 'icon' => $lbggIcon];
        }

        return [
            'url' => $applyBaseWebhook . '?thread_id=' . rawurlencode($threadId),
            'icon' => $icon,
        ];
    }

    private function job_application_send_webhook(array $application): void
    {
        $role = (string)($application['role'] ?? '');

        // Single base webhook + one thread per game/role, mirroring the New Order
        // notification routing (see notification_discord_game_route()). Each apply
        // is posted into its game's thread via ?thread_id=.
        // TODO: this base webhook URL is temporary and will be replaced.
        $applyBaseWebhook = 'https://discord.com/api/webhooks/1530506345957294152/4tcb-slVC9qS5Is1_Bn6jUTkTM7tzGCbfo2Dtv2Klq6g_QTbIqS6niXMdyVJcwxu1K-j';

        // Threads keyed by the specific role (lol/tft/val have dedicated roles).
        $threadByRole = [
            'lol_booster' => '1530506238536847440',
            'val_booster' => '1530506197462028399',
            'tft_booster' => '1530506143485661204',
            'gg_girl'     => '1530507078144102460',
            'seller'      => '1530506991087124640',
        ];

        // Generic 'booster' role: pick the thread from the chosen game, else the
        // shared "Other Games" thread.
        $threadByGame = [
            'lol'           => '1530506238536847440',
            'val'           => '1530506197462028399',
            'tft'           => '1530506143485661204',
            'cs2'           => '1530506099348996137',
            'fortnite'      => '1530506047075389480',
            'wild-rift'     => '1530505999277101189',
            'overwatch'     => '1530505964032229386',
            'rocket-league' => '1530505915898400768',
            'apex'          => '1530505862781603930',
            'marvel-rivals' => '1530505692258111600',
        ];
        $otherGamesThread = '1530505790232858674';

        // Normalize a stored game name/slug to one of the $threadByGame keys.
        $gameKey = static function (string $game): ?string {
            $g = strtolower(trim($game));
            if ($g === '') return null;
            if (strpos($g, 'wild') !== false) return 'wild-rift';
            if (strpos($g, 'league of legends') !== false || $g === 'lol') return 'lol';
            if (strpos($g, 'valorant') !== false || $g === 'val') return 'val';
            if (strpos($g, 'teamfight') !== false || strpos($g, 'tft') !== false) return 'tft';
            if (strpos($g, 'counter') !== false || strpos($g, 'cs2') !== false || strpos($g, 'cs 2') !== false) return 'cs2';
            if (strpos($g, 'fortnite') !== false) return 'fortnite';
            if (strpos($g, 'overwatch') !== false) return 'overwatch';
            if (strpos($g, 'rocket') !== false) return 'rocket-league';
            if (strpos($g, 'apex') !== false) return 'apex';
            if (strpos($g, 'marvel') !== false || strpos($g, 'rivals') !== false) return 'marvel-rivals';
            return null;
        };

        $boostGame = trim((string)($application['boost_game'] ?? ''));
        if ($role === 'booster') {
            $key = $gameKey($boostGame);
            $threadId = $key !== null ? ($threadByGame[$key] ?? $otherGamesThread) : $otherGamesThread;
            $channelKey = $key ?? 'other-games';
        } else {
            $threadId = $threadByRole[$role] ?? '';
            $channelKey = ['lol_booster' => 'lol', 'val_booster' => 'val', 'tft_booster' => 'tft', 'gg_girl' => 'gg_girl', 'seller' => 'seller'][$role] ?? '';
        }

        // Prefer the plain channel once configured, otherwise the forum thread.
        $targetWebhookUrl = ($channelKey !== '' && function_exists('lb_discord_channel_webhook'))
            ? lb_discord_channel_webhook('apply', $channelKey)
            : '';

        if ($targetWebhookUrl === '') {
            // Unknown role with no thread → nothing to post.
            if ($threadId === '' || $applyBaseWebhook === '') {
                return;
            }
            $targetWebhookUrl = $applyBaseWebhook . '?thread_id=' . rawurlencode($threadId);
        }

        $boosterTitle = $boostGame !== '' ? ('NEW ' . $boostGame . ' Booster Apply') : 'NEW Booster Apply';
        $titles = [
            'lol_booster' => 'NEW LoL Booster Apply',
            'tft_booster' => 'NEW TFT Booster Apply',
            'val_booster' => 'NEW VAL Booster Apply',
            'booster'     => $boosterTitle,
            'gg_girl'     => 'NEW GG Girl Apply',
            'seller'      => 'NEW Seller Apply',
        ];

        $truncate = function ($value, $limit = 1000) {
            $value = trim((string)$value);
            if ($value === '') {
                return '';
            }
            if (function_exists('mb_strlen') && mb_strlen($value) > $limit) {
                return mb_substr($value, 0, $limit - 3) . '...';
            }
            if (strlen($value) > $limit) {
                return substr($value, 0, $limit - 3) . '...';
            }
            return $value;
        };

        $addField = function (&$fields, $label, $value, $inline = false) use ($truncate) {
            $value = $truncate($value);
            if ($value === '') {
                return;
            }
            $fields[] = ['name' => $label, 'value' => $value, 'inline' => $inline];
        };

        $adminUrl = rtrim((string)BASE_URL, '/') . '/admin-area/job-applications';
        $fields = [
            ['name' => 'Applicant', 'value' => $truncate($application['fullname'] ?? '-'), 'inline' => true],
            ['name' => 'Email', 'value' => $truncate($application['email'] ?? '-'), 'inline' => true],
            ['name' => 'Discord', 'value' => $truncate($application['discord_tag'] ?? '-'), 'inline' => true],
            ['name' => 'Country', 'value' => $truncate($application['country'] ?? '-') ?: '-', 'inline' => true],
        ];

        if ($role === 'seller') {
            $addField($fields, 'Services', $application['ingame_name'] ?? '');
            $addField($fields, 'Store Link', $application['current_rank'] ?? '');
            $addField($fields, 'Second Link', $application['peak_rank'] ?? '');
            $addField($fields, 'Languages', $application['languages'] ?? '');
            $addField($fields, 'Other Platforms', $application['availability'] ?? '');
            $addField($fields, 'Preferred Messaging Platform', $application['experience'] ?? '');
            $addField($fields, 'Sourcing / Stock', $application['champ_pool'] ?? '');
            $addField($fields, 'Additional Details', $application['motivation'] ?? '');
            $addField($fields, 'Referral', $application['referral'] ?? '');
        } elseif ($role === 'gg_girl') {
            $addField($fields, 'Age', $application['age'] ?? '', true);
            $addField($fields, 'Languages', $application['languages'] ?? '');
            $addField($fields, 'Main Games', $application['ingame_name'] ?? '');
            $addField($fields, 'Current Rank(s)', $application['current_rank'] ?? '');
            $addField($fields, 'How Long Gaming', $application['peak_rank'] ?? '');
            $addField($fields, 'Personality', $application['champ_pool'] ?? '');
            $addField($fields, 'Comfortable With Clients', $application['availability'] ?? '');
            $addField($fields, 'Voice / Streaming Experience', $application['experience'] ?? '');
            $addField($fields, 'Why Join', $application['motivation'] ?? '');
            $addField($fields, 'Additional Notes', $application['referral'] ?? '');
            if (!empty($application['has_vpn'])) {
                $addField($fields, 'Microphone', 'Yes');
            }
        } else {
            $ingameLabel = 'Profile Link';
            $currentLabel = 'Current Rank';
            $peakLabel = 'Peak Rank';
            $champLabel = 'Main Roles / Champions';
            if ($role === 'tft_booster') {
                $ingameLabel = 'lolchess.gg Link';
                $currentLabel = 'Current TFT Rank';
                $peakLabel = 'Peak TFT Rank';
                $champLabel = 'Extra Details';
            } elseif ($role === 'val_booster') {
                $ingameLabel = 'tracker.gg Link';
                $currentLabel = 'Current VAL Rank';
                $peakLabel = 'Peak VAL Rank';
                $champLabel = 'Main Agents';
            } elseif ($role === 'booster') {
                // Generic booster: the game itself is the important context, since
                // there is no game-specific channel telling admins what this is for.
                $addField($fields, 'Game', $application['boost_game'] ?? '', true);
                $currentLabel = 'Current Rank';
                $peakLabel = 'Peak Rank';
            } else {
                $currentLabel = 'Current LoL Rank';
                $peakLabel = 'Peak LoL Rank';
            }
            $addField($fields, $ingameLabel, $application['ingame_name'] ?? '');
            $addField($fields, 'Region', $application['server_region'] ?? '', true);
            $addField($fields, $currentLabel, $application['current_rank'] ?? '', true);
            $addField($fields, $peakLabel, $application['peak_rank'] ?? '', true);
            $addField($fields, $champLabel, $application['champ_pool'] ?? '');
            if (!empty($application['has_vpn'])) {
                $addField($fields, 'VPN', 'Yes', true);
            }
            $addField($fields, 'Languages', $application['languages'] ?? '');
            $addField($fields, 'Availability', $application['availability'] ?? '');
            $addField($fields, 'Extra Info', $application['experience'] ?? '');
            $addField($fields, 'Why Join', $application['motivation'] ?? '');
            $addField($fields, 'Referral', $application['referral'] ?? '');
        }

        $fields[] = ['name' => 'Open in Admin', 'value' => '[View application](' . $adminUrl . ')', 'inline' => false];

        // Per-game embed icon (Discord thumbnail). Each game thread shows its own
        // game icon; "Other Games" and non-game roles (gg_girl/seller) fall back to
        // the LoLBoost.GG logo. SVG is intentionally not used — Discord thumbnails
        // only render png/jpg/webp/gif.
        $lbggIcon = 'https://lolboost.gg/public/uploads/icons/default1.png';
        $gameIconFiles = [
            'lol'           => 'league-of-legends.png',
            'val'           => 'valorant.png',
            'tft'           => 'teamfight-tactics.png',
            'cs2'           => 'counter-strike-2.png',
            'fortnite'      => 'fortnite.png',
            'wild-rift'     => 'lol-wild-rift.png',
            'overwatch'     => 'overwatch-2.png',
            'rocket-league' => 'rocket-league.png',
            'apex'          => 'apex-legends.png',
            'marvel-rivals' => 'marvel-rivals.png',
        ];
        // Resolve the effective game key for the icon.
        if ($role === 'lol_booster') {
            $iconKey = 'lol';
        } elseif ($role === 'val_booster') {
            $iconKey = 'val';
        } elseif ($role === 'tft_booster') {
            $iconKey = 'tft';
        } elseif ($role === 'booster') {
            $iconKey = $gameKey($boostGame); // null → falls back to lbgg (Other Games)
        } else {
            $iconKey = null; // gg_girl / seller → lbgg logo
        }
        $senderIcon = ($iconKey !== null && isset($gameIconFiles[$iconKey]))
            ? 'https://lolboost.gg/public/assets/website/images/icons/' . $gameIconFiles[$iconKey]
            : $lbggIcon;

        $payload = [
            'username' => 'LoLBoost Apply System',
            'avatar_url' => $senderIcon,
            'embeds' => [[
                'title' => $titles[$role] ?? 'NEW Job Apply',
                'color' => 0x5865F2,
                'fields' => $fields,
                'footer' => ['text' => 'Application #' . (int)($application['id'] ?? 0), 'icon_url' => $lbggIcon],
                'timestamp' => date('c'),
            ]],
        ];

        try {
            $ch = curl_init($targetWebhookUrl);
            curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-type: application/json']);
            curl_setopt($ch, CURLOPT_POST, 1);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
            curl_setopt($ch, CURLOPT_HEADER, 0);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
            curl_setopt($ch, CURLOPT_TIMEOUT, 10);
            $resp = curl_exec($ch);
            $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $curlErr = curl_error($ch);
            curl_close($ch);

            // Discord rejects a bad thread_id / channel mismatch with a 4xx and a
            // JSON error body, but the post otherwise "succeeds" from PHP's view.
            // Log it so a missing/misplaced thread is diagnosable instead of silent.
            if ($resp === false || $httpCode < 200 || $httpCode >= 300) {
                error_log(sprintf(
                    '[job_application_send_webhook] FAILED role=%s game=%s thread_id=%s http=%d curl_err=%s resp=%s',
                    $role,
                    $boostGame,
                    $threadId,
                    $httpCode,
                    $curlErr,
                    is_string($resp) ? substr($resp, 0, 500) : '(false)'
                ));
            }
        } catch (\Throwable $e) {
            error_log('[job_application_send_webhook] Exception: ' . $e->getMessage());
        }
    }


    /**
     * Baut einen frischen Onboarding-Link (One-Time-Token, 72h) fuer Seller / GG-Girl.
     * Leerer String, wenn die Rolle keinen Onboarding-Flow hat oder das Token nicht
     * erzeugt werden kann.
     */
    private function job_application_onboarding_link(string $role): string
    {
        $map = [
            'gg_girl' => ['action' => 'egirl_onboarding',  'path' => '/egirl-onboarding'],
            'seller'  => ['action' => 'seller_onboarding', 'path' => '/seller-onboarding'],
        ];

        if (!isset($map[$role]) || !function_exists('generateOneTimeLink')) {
            return '';
        }

        try {
            $token = generateOneTimeLink($map[$role]['action'], 72);
        } catch (\Throwable $e) {
            return '';
        }

        if (empty($token)) {
            return '';
        }

        return rtrim((string)BASE_URL, '/') . $map[$role]['path'] . '?t=' . rawurlencode((string)$token);
    }

    private function job_application_send_invite_email(array $application, string $invite_link, string $note = ''): bool
    {
        $email = trim((string)($application['email'] ?? ''));
        if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return false;
        }

        $role = trim((string)($application['role'] ?? ''));

        $applicationId = (int)($application['id'] ?? 0);
        if ($applicationId <= 0) {
            return false;
        }

        $jobUser = db_get_row('job_applications', ['id' => $applicationId]);
        if (!$jobUser) {
            return false;
        }

        $jobUserId = (int)($jobUser['id'] ?? 0);
        if ($jobUserId <= 0) {
            return false;
        }

        // Booster: Trial-Invite (nur Discord). Seller/GG-Girl: Onboarding-Link + Discord-Invite.
        if ($this->job_application_is_booster_role($role)) {
            $type = 'booster_trial_invite';
            $data = [
                'discord_invite' => base64_encode(trim($invite_link)),
                'note'           => base64_encode(trim($note)),
            ];
        } elseif (in_array($role, ['seller', 'gg_girl'], true)) {
            $type = 'application_onboarding_invite';
            $data = [
                'onboarding_link' => base64_encode($this->job_application_onboarding_link($role)),
                'discord_invite'  => base64_encode(trim($invite_link)),
                'note'            => base64_encode(trim($note)),
            ];
        } else {
            return false;
        }

        try {
            $notifId = db_insert_row('notifications', [
                'type' => $type,
                'data' => json_encode($data),
                'recipient' => 'job_application',
                'recipient_id' => $jobUserId,
                'is_email' => 1,
                'is_web' => 0,
                'is_discord' => 0,
            ]);
        } catch (\Throwable $e) {
            $notifId = false;
        }

        if (!$notifId) {
            return false;
        }

        if (function_exists('trigger_notification_sender_async')) {
            @trigger_notification_sender_async();
        }

        return true;
    }

    /**
     * Öffentlich: Bewerbung einreichen (kein Login nötig)
     * POST action=submit_job_application
     */
    public function submit_job_application()
    {
        global $db;

        $allowed_roles = ['lol_booster', 'tft_booster', 'val_booster', 'booster', 'gg_girl', 'seller'];
        $role          = trim($_POST['role'] ?? '');
        $fullname      = trim($_POST['fullname'] ?? '');
        $email         = trim($_POST['email'] ?? '');
        $discord_tag   = trim($_POST['discord_tag'] ?? '');
        $motivation    = trim($_POST['motivation'] ?? '');
        $is_booster    = $this->job_application_is_booster_role($role);

        if (!in_array($role, $allowed_roles, true)) {
            echo json_encode(['status' => 'error', 'message' => 'Invalid role selected.']);
            return;
        }
        if (!$fullname || !$email || !$motivation || !$discord_tag) {
            echo json_encode(['status' => 'error', 'message' => 'Please fill in all required fields.']);
            return;
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            echo json_encode(['status' => 'error', 'message' => 'Invalid email address.']);
            return;
        }
        if ($is_booster && trim((string)($_POST['ingame_name'] ?? '')) === '') {
            echo json_encode(['status' => 'error', 'message' => 'Please enter your in game name.']);
            return;
        }
        if ($is_booster && trim((string)($_POST['peak_rank'] ?? '')) === '') {
            echo json_encode(['status' => 'error', 'message' => 'Please enter your peak rank.']);
            return;
        }

        // One open application per email and role. Without this the same person could
        // submit the identical application over and over and flood the admin list.
        // Declined applicants may re-apply, accepted ones are already onboarded.
        try {
            $openApplication = $db->row(
                "SELECT id, status FROM job_applications
                  WHERE LOWER(email) = LOWER(?)
                    AND role = ?
                    AND status IN ('pending', 'trial')
                  ORDER BY id DESC
                  LIMIT 1",
                $email,
                $role
            );
        } catch (\Throwable $e) {
            $openApplication = null;
        }

        if (!empty($openApplication)) {
            $openStatus = (string)($openApplication['status'] ?? 'pending');
            echo json_encode([
                'status'  => 'error',
                'message' => $openStatus === 'trial'
                    ? 'You already have an application in trial for this role. Please wait for our team to get back to you.'
                    : 'You already have a pending application for this role. Please wait for our team to review it.',
            ]);
            return;
        }

        $age          = !empty($_POST['age']) ? (int)$_POST['age'] : null;
        $has_vpn      = isset($_POST['has_vpn']) ? 1 : 0;
        $country      = trim($_POST['country'] ?? '') ?: null;
        $ingame_name  = trim($_POST['ingame_name'] ?? '') ?: null;
        $peak_rank    = trim($_POST['peak_rank'] ?? '') ?: null;
        $curr_rank    = trim($_POST['current_rank'] ?? '') ?: null;
        $region       = trim($_POST['server_region'] ?? '') ?: null;
        $champ_pool   = trim($_POST['champ_pool'] ?? '') ?: null;
        $languages    = trim($_POST['languages'] ?? '') ?: null;
        $availability = trim($_POST['availability'] ?? '') ?: null;
        $experience   = trim($_POST['experience'] ?? '') ?: null;
        $referral     = trim($_POST['referral'] ?? '') ?: null;
        $disc         = $discord_tag ?: null;
        $boost_game   = trim($_POST['boost_game'] ?? '') ?: null;

        // The `role` column is historically an ENUM limited to the five original
        // roles. Inserting the new generic 'booster' value into an ENUM silently
        // stores an empty string (MySQL non-strict), which is exactly why generic
        // booster applications saved with a blank role, showed no badge, and never
        // routed a Discord webhook. Widen it to VARCHAR so 'booster' is accepted.
        try {
            $roleCol  = $db->run("SHOW COLUMNS FROM job_applications LIKE 'role'");
            $roleType = strtolower((string)($roleCol[0]['Type'] ?? ''));
            if ($roleType !== '' && strpos($roleType, 'char') === false && strpos($roleType, 'text') === false) {
                $db->run("ALTER TABLE job_applications MODIFY COLUMN role VARCHAR(32) NOT NULL DEFAULT ''");
            }
        } catch (\Throwable $e) {
            // Non-fatal: if it can't be widened, known roles still work as before.
        }

        // The chosen boosting game was previously discarded. For generic 'booster'
        // applications it is the only thing that identifies the game, so persist it.
        // Self-heal the column so this works without a manual migration.
        try {
            $hasBoostGameCol = $db->run("SHOW COLUMNS FROM job_applications LIKE 'boost_game'");
            if (empty($hasBoostGameCol)) {
                $db->run("ALTER TABLE job_applications ADD COLUMN boost_game VARCHAR(64) NULL AFTER role");
            }
        } catch (\Throwable $e) {
            // If the column can't be ensured, fall back to inserting without it below.
            $hasBoostGameCol = false;
        }

        if (!empty($hasBoostGameCol) || $boost_game !== null) {
            $db->run(
                "INSERT INTO job_applications
                    (role, boost_game, fullname, email, discord_tag, country, age, ingame_name, peak_rank, current_rank,
                     server_region, champ_pool, has_vpn, languages, availability, experience, motivation, referral)
                 VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                $role, $boost_game, $fullname, $email, $disc, $country, $age, $ingame_name, $peak_rank, $curr_rank,
                $region, $champ_pool, $has_vpn, $languages, $availability, $experience, $motivation, $referral
            );
        } else {
            $db->run(
                "INSERT INTO job_applications
                    (role, fullname, email, discord_tag, country, age, ingame_name, peak_rank, current_rank,
                     server_region, champ_pool, has_vpn, languages, availability, experience, motivation, referral)
                 VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                $role, $fullname, $email, $disc, $country, $age, $ingame_name, $peak_rank, $curr_rank,
                $region, $champ_pool, $has_vpn, $languages, $availability, $experience, $motivation, $referral
            );
        }

        $application = $db->row("SELECT * FROM job_applications WHERE id = LAST_INSERT_ID() LIMIT 1");
        if (is_array($application) && !empty($application)) {
            $this->job_application_send_webhook($application);
        }

        echo json_encode(['status' => 'success', 'message' => 'Application submitted successfully.']);
    }

    /**
     * Admin: Bewerbung annehmen
     * Booster pending -> trial
     * Booster trial -> accepted
     * GG Girl / Seller pending -> accepted
     * POST action=accept_job_application  id=<int>
     */
    public function accept_job_application()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.']]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        if (!$id) {
            echo json_encode(['status' => 'error', 'message' => 'Invalid ID.']);
            return;
        }

        $application = $db->row("SELECT * FROM job_applications WHERE id = ? LIMIT 1", $id);
        if (!$application) {
            echo json_encode(['status' => 'error', 'message' => 'Application not found.']);
            return;
        }

        $admin_id = ADMIN_DATA['id'] ?? null;
        $role = (string)($application['role'] ?? '');
        $current_status = (string)($application['status'] ?? 'pending');
        $is_booster = $this->job_application_is_booster_role($role);

        if ($current_status === 'declined') {
            echo json_encode(['status' => 'error', 'message' => 'Declined applications cannot be accepted directly.']);
            return;
        }

        if ($is_booster) {
            if ($current_status === 'pending') {
                $new_status = 'trial';
                $message = 'Application moved to trial.';
                $toastTitle = 'Trial';
                $toastMessage = 'Booster application moved to trial.';
            } elseif ($current_status === 'trial') {
                $new_status = 'accepted';
                $message = 'Booster application accepted.';
                $toastTitle = 'Accepted';
                $toastMessage = 'Booster application has been fully accepted.';
            } elseif ($current_status === 'accepted') {
                echo json_encode(['status' => 'error', 'message' => 'Application is already accepted.']);
                return;
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Invalid application state.']);
                return;
            }
        } else {
            if ($current_status === 'accepted') {
                echo json_encode(['status' => 'error', 'message' => 'Application is already accepted.']);
                return;
            }
            $new_status = 'accepted';
            $message = $this->job_application_role_label($role) . ' application accepted.';
            $toastTitle = 'Accepted';
            $toastMessage = 'Application has been accepted.';
        }

        $db->run(
            "UPDATE job_applications SET status=?, reviewed_by=?, reviewed_at=NOW() WHERE id=?",
            $new_status, $admin_id, $id
        );

        // Seller / GG-Girl: beim Annehmen direkt Onboarding-Link (+ ggf. gespeicherten
        // Discord-Invite) per E-Mail schicken. Booster laufen ueber den Trial-Flow.
        if (!$is_booster && $new_status === 'accepted' && in_array($role, ['seller', 'gg_girl'], true)) {
            $application['status'] = 'accepted';

            // Discord invite entered in the Accept dialog (one-step onboarding + Discord).
            // Fall back to any previously saved invite if the field was left empty.
            $invite_link = trim((string)($_POST['invite_link'] ?? ''));
            if ($invite_link === '') {
                $invite_link = (string)($application['discord_invite'] ?? '');
            }
            if ($invite_link !== '') {
                $db->run("UPDATE job_applications SET discord_invite=? WHERE id=?", $invite_link, $id);
                $application['discord_invite'] = $invite_link;
            }

            $onboarding_sent = $this->job_application_send_invite_email(
                $application,
                $invite_link,
                ''
            );
            if ($onboarding_sent) {
                $message      = $this->job_application_role_label($role) . ' accepted — onboarding email sent.';
                $toastMessage = 'Application accepted and onboarding email queued.';
            }
        }

        echo json_encode([
            'status' => 'success',
            'message' => $message,
            'new_status' => $new_status,
            'sendToast' => ['type' => 'success', 'title' => $toastTitle, 'message' => $toastMessage],
            'refresh' => true,
        ]);
    }

    /**
     * Admin: Bewerbung ablehnen
     * POST action=decline_job_application  id=<int>
     */
    public function decline_job_application()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.']]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        if (!$id) {
            echo json_encode(['status' => 'error', 'message' => 'Invalid ID.']);
            return;
        }

        $application = $db->row("SELECT * FROM job_applications WHERE id = ? LIMIT 1", $id);
        if (!$application) {
            echo json_encode(['status' => 'error', 'message' => 'Application not found.']);
            return;
        }

        if ((string)($application['status'] ?? '') === 'declined') {
            echo json_encode(['status' => 'error', 'message' => 'Application is already declined.']);
            return;
        }

        $admin_id = ADMIN_DATA['id'] ?? null;
        $decline_note = trim((string)($_POST['decline_note'] ?? ''));
        $db->run(
            "UPDATE job_applications SET status='declined', reviewed_by=?, reviewed_at=NOW() WHERE id=?",
            $admin_id, $id
        );

        $email_sent = false;
        $email = trim((string)($application['email'] ?? ''));
        if ($email !== '' && filter_var($email, FILTER_VALIDATE_EMAIL)) {
            $notifId = db_insert_row('notifications', [
                'type' => 'application_declined',
                'data' => json_encode([
                    'note' => base64_encode($decline_note),
                ]),
                'recipient' => 'job_application',
                'recipient_id' => $id,
                'is_email' => 1,
                'is_web' => 0,
                'is_discord' => 0,
            ]);

            if ($notifId) {
                $email_sent = true;
                if (function_exists('trigger_notification_sender_async')) {
                    @trigger_notification_sender_async();
                }
            } else {
            }
        }

        echo json_encode([
            'status'  => 'success',
            'message' => $email_sent ? 'Application declined and email queued.' : 'Application declined.',
            'new_status' => 'declined',
            'email_sent' => $email_sent,
            'sendToast' => ['type' => 'warning', 'title' => 'Declined', 'message' => $email_sent ? 'Application declined and email queued.' : 'Application has been declined.'],
            'refresh' => true,
        ]);
    }

    /**
     * Admin: Booster-Bewerbung in Trial setzen und direkt Discord Trial Invite senden
     * POST action=move_to_trial_and_send_invite_application  id=<int>  invite_link=<url>
     */
    public function move_to_trial_and_send_invite_application()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.']]);
            return;
        }

        $id = (int)($_POST['id'] ?? 0);
        $invite_link = trim((string)($_POST['invite_link'] ?? ''));
        $note = trim((string)($_POST['note'] ?? ''));

        if (!$id || $invite_link === '') {
            echo json_encode(['status' => 'error', 'message' => 'Missing data.']);
            return;
        }

        $application = $db->row("SELECT * FROM job_applications WHERE id = ? LIMIT 1", $id);
        if (!$application) {
            echo json_encode(['status' => 'error', 'message' => 'Application not found.']);
            return;
        }

        $role = (string)($application['role'] ?? '');
        $current_status = (string)($application['status'] ?? 'pending');

        if (!$this->job_application_is_booster_role($role)) {
            echo json_encode(['status' => 'error', 'message' => 'Trial invite is only available for booster applications.']);
            return;
        }

        if ($current_status === 'declined') {
            echo json_encode(['status' => 'error', 'message' => 'Declined applications cannot be moved to trial.']);
            return;
        }

        if ($current_status === 'accepted') {
            echo json_encode(['status' => 'error', 'message' => 'Application is already accepted.']);
            return;
        }

        $admin_id = ADMIN_DATA['id'] ?? null;
        $db->run(
            "UPDATE job_applications SET status='trial', discord_invite=?, reviewed_by=?, reviewed_at=NOW() WHERE id=?",
            $invite_link, $admin_id, $id
        );

        $application['status'] = 'trial';
        $application['discord_invite'] = $invite_link;
        $email_sent = $this->job_application_send_invite_email($application, $invite_link, $note);

        echo json_encode([
            'status' => 'success',
            'message' => $email_sent ? 'Application moved to trial and trial invite email queued.' : 'Application moved to trial and invite saved. Email could not be queued.',
            'new_status' => 'trial',
            'invite_link' => $invite_link,
            'email_sent' => $email_sent ? 1 : 0,
            'refresh' => true,
            'sendToast' => [
                'type' => $email_sent ? 'success' : 'warning',
                'title' => $email_sent ? 'Trial Invite Sent' : 'Trial Saved',
                'message' => $email_sent ? 'Applicant moved to trial and invite email queued.' : 'Applicant moved to trial, but the email could not be queued.'
            ],
        ]);
    }

    /**
     * Admin: Discord-Einladungslink zu einer Bewerbung speichern
     * POST action=send_discord_invite_application  id=<int>  invite_link=<url>
     */
    public function send_discord_invite_application()
    {
        global $db;

        if (!$this->is_admin) {
            echo json_encode(['sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Access denied.']]);
            return;
        }

        $id          = (int)($_POST['id'] ?? 0);
        $invite_link = trim($_POST['invite_link'] ?? '');

        if (!$id || !$invite_link) {
            echo json_encode(['status' => 'error', 'message' => 'Missing data.']);
            return;
        }

        $application = $db->row("SELECT * FROM job_applications WHERE id = ? LIMIT 1", $id);
        if (!$application) {
            echo json_encode(['status' => 'error', 'message' => 'Application not found.']);
            return;
        }

        $db->run(
            "UPDATE job_applications SET discord_invite=?, reviewed_by=?, reviewed_at=NOW() WHERE id=?",
            $invite_link, (ADMIN_DATA['id'] ?? null), $id
        );

        $email_sent = $this->job_application_send_invite_email($application, $invite_link, trim((string)($_POST['note'] ?? '')));

        // Re-read current status so the UI can update the row without F5
        $updated = $db->row("SELECT status FROM job_applications WHERE id = ? LIMIT 1", $id);
        $current_status = (string)($updated['status'] ?? $application['status'] ?? 'pending');

        echo json_encode([
            'status'     => 'success',
            'new_status' => $current_status,
            'message'    => $email_sent ? 'Discord invite saved and email queued.' : 'Discord invite saved. Email could not be queued.',
            'invite_link' => $invite_link,
            'email_sent' => $email_sent ? 1 : 0,
            'refresh' => false,
            'sendToast' => [
                'type' => $email_sent ? 'success' : 'warning',
                'title' => $email_sent ? 'Saved' : 'Partly Done',
                'message' => $email_sent ? 'Discord invite was saved and the email was queued successfully.' : 'Discord invite was saved, but the email could not be queued.'
            ],
        ]);
    }

