public function referral_admin_get_settings()
{
    if (!$this->is_admin) {
        echo json_encode([
            'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
            'playSound' => 'error',
        ]);
        return;
    }

    echo json_encode([
        'status' => 'success',
        'data' => function_exists('lb_referral_get_settings') ? lb_referral_get_settings() : [],
    ]);
}

public function referral_admin_save_settings()
{
    if (!$this->is_admin) {
        echo json_encode([
            'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
            'playSound' => 'error',
        ]);
        return;
    }

    if (!function_exists('lb_referral_set_setting')) {
        echo json_encode([
            'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Referral helpers missing.'],
            'playSound' => 'error',
        ]);
        return;
    }

    $enabled = isset($_POST['enabled']) ? (int) $_POST['enabled'] : 1;
    $clientRewardPercent = isset($_POST['client_reward_percent']) ? (float) $_POST['client_reward_percent'] : 5;
    $boosterRewardPercent = isset($_POST['booster_reward_percent']) ? (float) $_POST['booster_reward_percent'] : 5;
    $sellerRewardPercent = isset($_POST['seller_reward_percent']) ? (float) $_POST['seller_reward_percent'] : 5;
    $minOrderEur = isset($_POST['min_order_eur']) ? (float) $_POST['min_order_eur'] : 0;
    $cookieDays = isset($_POST['cookie_days']) ? (int) $_POST['cookie_days'] : 30;
    $requireCompleted = isset($_POST['require_completed']) ? (int) $_POST['require_completed'] : 1;
    $blockSameClientAccount = isset($_POST['block_same_client_account']) ? (int) $_POST['block_same_client_account'] : 1;
    $blockSameEmail = isset($_POST['block_same_email']) ? (int) $_POST['block_same_email'] : 1;
    $allowClientReferrals = isset($_POST['allow_client_referrals']) ? (int) $_POST['allow_client_referrals'] : 1;
    $allowBoosterReferrals = isset($_POST['allow_booster_referrals']) ? (int) $_POST['allow_booster_referrals'] : 1;
    $allowSellerReferrals = isset($_POST['allow_seller_referrals']) ? (int) $_POST['allow_seller_referrals'] : 1;

    lb_referral_set_setting('enabled', $enabled ? 1 : 0);
    lb_referral_set_setting('client_reward_percent', max(0, min(100, $clientRewardPercent)));
    lb_referral_set_setting('booster_reward_percent', max(0, min(100, $boosterRewardPercent)));
    lb_referral_set_setting('seller_reward_percent', max(0, min(100, $sellerRewardPercent)));
    lb_referral_set_setting('min_order_cents', (int) round(max(0, $minOrderEur) * 100));
    lb_referral_set_setting('cookie_days', max(1, $cookieDays));
    lb_referral_set_setting('require_completed', $requireCompleted ? 1 : 0);
    lb_referral_set_setting('block_same_client_account', $blockSameClientAccount ? 1 : 0);
    lb_referral_set_setting('block_same_email', $blockSameEmail ? 1 : 0);
    lb_referral_set_setting('allow_client_referrals', $allowClientReferrals ? 1 : 0);
    lb_referral_set_setting('allow_booster_referrals', $allowBoosterReferrals ? 1 : 0);
    lb_referral_set_setting('allow_seller_referrals', $allowSellerReferrals ? 1 : 0);

    echo json_encode([
        'status' => 'success',
        'message' => 'Referral settings saved',
        'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Referral settings saved'],
        'playSound' => 'success',
        'data' => lb_referral_get_settings(),
    ]);
}

    /**
     * Booster: Report games to admins via Discord webhook
     * POST action=booster_report_games  match_ids=<csv>  reason=<string>  note=<string>
     */
    public function booster_report_games()
    {
        if (!$this->is_booster) {
            echo json_encode(['ok' => false, 'message' => 'Unauthorized.']);
            return;
        }

        $raw = trim((string)($_POST['match_ids'] ?? ''));
        $ids = array_values(array_unique(array_filter(
            array_map('intval', preg_split('/[^0-9]+/', $raw, -1, PREG_SPLIT_NO_EMPTY)),
            fn($id) => $id > 0
        )));

        if (empty($ids)) {
            echo json_encode(['ok' => false, 'message' => 'No games selected.']);
            return;
        }

        $reason = trim((string)($_POST['reason'] ?? ''));
        $note   = trim((string)($_POST['note']   ?? ''));

        $reasonLabels = [
            'not_my_game'           => 'Not my game',
            'client_played_himself' => 'Client played himself',
            'client_afk'            => 'Client was AFK / feeding',
            'duplicate_error'       => 'Duplicate / data error',
            'other'                 => 'Other reason',
        ];
        $reasonLabel = $reasonLabels[$reason] ?? $reason;

        $boosterId   = (int)BOOSTER_ID;
        $boosterName = BOOSTER_DATA['username'] ?? ('Booster #' . $boosterId);

        global $db;
        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $matches = $db->run(
            "SELECT om.id, om.order_id, om.champion, om.kills, om.deaths, om.assists,
                    om.won, om.played_at, COALESCE(om.is_remake,0) AS is_remake
               FROM order_matches om
              WHERE om.id IN ($placeholders)",
            ...$ids
        ) ?: [];

        $matchLines = array_map(function($m) {
            $res   = (int)($m['is_remake'] ?? 0) ? 'Remake' : ((int)($m['won'] ?? 0) ? 'Win' : 'Loss');
            $champ = $m['champion'] ?: '--';
            $kda   = ($m['kills'] ?? 0) . '/' . ($m['deaths'] ?? 0) . '/' . ($m['assists'] ?? 0);
            $date  = !empty($m['played_at']) ? date('d.m.Y H:i', strtotime($m['played_at'])) : '--';
            return "- #{$m['id']} | {$champ} {$kda} {$res} | Order #{$m['order_id']} | {$date}";
        }, $matches);

        $matchText = implode("\n", $matchLines) ?: 'IDs: ' . implode(', ', $ids);
        $noteText  = $note !== '' ? $note : 'No additional notes';
        $siteUrl   = defined('BASE_URL') ? rtrim(BASE_URL, '/') : 'https://lolboost.gg';

        $payload = [
            'username'         => 'LolBoost Report System',
            'content'          => '<@&1295032857907171339>',
            'allowed_mentions' => ['roles' => ['1295032857907171339']],
            'embeds'           => [[
                'title'       => 'Game Report from Booster',
                'color'       => 0xFB7185,
                'description' => "**Booster:** [{$boosterName}]({$siteUrl}/admin-area/booster/{$boosterId}/profile) (ID #{$boosterId})\n**Reason:** {$reasonLabel}\n**Note:** {$noteText}",
                'fields'      => [
                    [
                        'name'   => 'Reported Games (' . count($ids) . ')',
                        'value'  => mb_substr($matchText, 0, 1000),
                        'inline' => false,
                    ],
                    [
                        'name'   => 'Admin Action',
                        'value'  => "[View Booster Games]({$siteUrl}/admin-area/booster-games?booster={$boosterId}&reported_games=" . rawurlencode(implode(',', $ids)) . ")",
                        'inline' => false,
                    ],
                ],
                'footer'    => ['text' => 'Game IDs: ' . implode(', ', $ids)],
                'timestamp' => date('c'),
            ]],
        ];

        $webhookUrl = lb_booster_notification_webhook_url('delete_booster_games');

        $ch = curl_init($webhookUrl);
        curl_setopt_array($ch, [
            CURLOPT_POST           => true,
            CURLOPT_POSTFIELDS     => json_encode($payload),
            CURLOPT_HTTPHEADER     => ['Content-Type: application/json'],
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 8,
        ]);
        curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        $ok = ($httpCode >= 200 && $httpCode < 300);

        echo json_encode([
            'ok'      => $ok,
            'message' => $ok ? 'Report sent.' : 'Could not reach Discord.',
        ]);
    }



    // ─────────────────────────────────────────────
    // Seller direct chat methods
    // ─────────────────────────────────────────────

    private function ensure_seller_chat_schema()
    {
        // Guard: only run once per PHP process. ALTER TABLE on every poll is a major CPU drain.
        static $already_ran = false;
        if ($already_ran) return;
        $already_ran = true;

        // Additionally, skip entirely if a cheap sentinel column already exists.
        // This makes repeated deploys cost a single SHOW COLUMNS instead of 29 ALTER/UPDATEs.
        global $db;
        try {
            $cols = $db->run("SHOW COLUMNS FROM seller_chat_messages LIKE 'created_at'") ?: [];
            if (!empty($cols)) return; // Schema already fully applied
        } catch (\Throwable $e) {}

        try { $db->run("ALTER TABLE sellers ADD COLUMN allow_chat_requests TINYINT(1) NOT NULL DEFAULT 1"); } catch (Exception $e) {}
        try { $db->run("CREATE TABLE IF NOT EXISTS seller_conversations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); } catch (Exception $e) {}
        try { $db->run("CREATE TABLE IF NOT EXISTS seller_chat_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); } catch (Exception $e) {}

        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN seller_id INT UNSIGNED NOT NULL DEFAULT 0 AFTER id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN client_id INT UNSIGNED NOT NULL DEFAULT 0 AFTER seller_id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN ref_type ENUM('account','item_purchase','none') NOT NULL DEFAULT 'none' AFTER client_id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN ref_id INT UNSIGNED NULL AFTER ref_type"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN initiated_by ENUM('client','seller') NOT NULL DEFAULT 'client' AFTER ref_id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN seller_status ENUM('open','archived') NOT NULL DEFAULT 'open' AFTER initiated_by"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN last_message_at DATETIME NULL AFTER seller_status"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN seller_seen_at DATETIME NULL AFTER last_message_at"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN client_seen_at DATETIME NULL AFTER seller_seen_at"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_conversations ADD COLUMN created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP AFTER client_seen_at"); } catch (Exception $e) {}

        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN conversation_id INT UNSIGNED NULL AFTER id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN sender_type ENUM('seller','client') NOT NULL DEFAULT 'client' AFTER conversation_id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN sender_id INT UNSIGNED NOT NULL DEFAULT 0 AFTER sender_type"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN message TEXT NULL AFTER sender_id"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN body TEXT NULL AFTER message"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN message_type VARCHAR(16) NOT NULL DEFAULT 'text' AFTER body"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN is_read TINYINT(1) NOT NULL DEFAULT 0 AFTER message_type"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN seen_by_seller TINYINT(1) NOT NULL DEFAULT 0 AFTER is_read"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN seen_by_client TINYINT(1) NOT NULL DEFAULT 0 AFTER seen_by_seller"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN read_at DATETIME NULL AFTER seen_by_client"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN missed_dm_sent_at DATETIME NULL AFTER read_at"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN deleted TINYINT(1) NOT NULL DEFAULT 0 AFTER read_at"); } catch (Exception $e) {}
        try { $db->run("ALTER TABLE seller_chat_messages ADD COLUMN created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP AFTER deleted"); } catch (Exception $e) {}
        // Add performance indexes (safe to run repeatedly — checks existence first)
        $index_stmts = [
            // Most critical: every chat poll hits this
            "CREATE INDEX IF NOT EXISTS idx_scm_conv_del ON seller_chat_messages (conversation_id, deleted, id)",
            "CREATE INDEX IF NOT EXISTS idx_scm_conv_sender_read ON seller_chat_messages (conversation_id, sender_type, is_read)",
            // Seller unread count query
            "CREATE INDEX IF NOT EXISTS idx_sc_seller_last ON seller_conversations (seller_id, last_message_at)",
            "CREATE INDEX IF NOT EXISTS idx_sc_client ON seller_conversations (client_id)",
        ];
        foreach ($index_stmts as $sql) {
            try { $db->run($sql); } catch (\Throwable $e) {}
        }

        // One-time data migrations removed — these full-table-scan UPDATEs were only
        // needed during initial deploy and caused high CPU on every new PHP-FPM worker.
        // Run them manually once if needed: UPDATE seller_chat_messages SET seen_by_seller=1
        // WHERE sender_type='client' AND is_read=1 AND seen_by_seller=0 (etc.)
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ensure_selling_schema — guards ALL ad-hoc ALTER TABLE calls that were
    // scattered across action handlers. Called once per PHP process max.
    // ─────────────────────────────────────────────────────────────────────────
    private function ensure_selling_schema(): void
    {
        static $done = false;
        if ($done) return;
        $done = true;

        global $db;
        if (!isset($db) || !is_object($db)) return;

        // Always guarantee core sale tracking columns before using the sentinel below.
        try { $db->run("ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS sold_at DATETIME NULL DEFAULT NULL"); } catch (\Throwable $e) {}

        // Sentinel: check for val_agent_count (newest column). If it exists, all migrations ran.
        try {
            $cols = $db->run("SHOW COLUMNS FROM selling_accounts LIKE 'val_agent_count'") ?: [];
            if (!empty($cols)) return;
        } catch (\Throwable $e) {}

        // sellers columns
        $seller_alters = [
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS icon VARCHAR(512) NULL DEFAULT NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS banner VARCHAR(512) NULL DEFAULT NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS banner_position VARCHAR(32) NULL DEFAULT '50% 50%'",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS is_active TINYINT(1) NOT NULL DEFAULT 0",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS onboarding_status VARCHAR(16) NOT NULL DEFAULT 'pending'",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS discord VARCHAR(191) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS application_note TEXT NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS fullname VARCHAR(191) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS dob VARCHAR(32) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS address TEXT NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS country VARCHAR(100) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS id_front VARCHAR(512) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS id_back VARCHAR(512) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS selfie VARCHAR(512) NULL",
            "ALTER TABLE sellers ADD COLUMN IF NOT EXISTS allow_chat_requests TINYINT(1) NOT NULL DEFAULT 1",
            // boosters
            "ALTER TABLE boosters ADD COLUMN IF NOT EXISTS cover_position VARCHAR(32) NULL DEFAULT '50% 50%'",
            // selling_items
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS stock INT(11) NOT NULL DEFAULT 1",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS min_purchase_qty INT(11) NOT NULL DEFAULT 1",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS max_purchase_qty INT(11) DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS delivery_instructions TEXT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS game_id INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS item_data JSON NULL",
            // selling_item_purchases
            "ALTER TABLE selling_item_purchases ADD COLUMN IF NOT EXISTS quantity INT(11) NOT NULL DEFAULT 1",
            "ALTER TABLE selling_item_purchases ADD COLUMN IF NOT EXISTS unit_price INT(11) NOT NULL DEFAULT 0",
            "ALTER TABLE selling_item_purchases ADD COLUMN IF NOT EXISTS game_id INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_item_purchases ADD COLUMN IF NOT EXISTS game_slug VARCHAR(100) NULL DEFAULT NULL",
            "ALTER TABLE selling_item_purchases ADD COLUMN IF NOT EXISTS game_name VARCHAR(191) NULL DEFAULT NULL",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS champion_count INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS skin_count INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_accounts ADD COLUMN IF NOT EXISTS val_agent_count INT(11) NULL DEFAULT NULL",
        ];
        foreach ($seller_alters as $sql) {
            try { $db->run($sql); } catch (\Throwable $e) {}
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ensure_selling_items_extra_schema — same guard pattern as ensure_selling_schema(),
    // covers the waiting-time/friendship columns that were re-run on every single
    // item_shop_filters() / seller_create_item() / seller_update_item() call.
    // ─────────────────────────────────────────────────────────────────────────
    private function ensure_selling_items_extra_schema(): void
    {
        static $done = false;
        if ($done) return;
        $done = true;

        global $db;
        if (!isset($db) || !is_object($db)) return;

        try {
            $cols = $db->run("SHOW COLUMNS FROM selling_items LIKE 'requires_friendship_days'") ?: [];
            if (!empty($cols)) return;
        } catch (\Throwable $e) {}

        $alters = [
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS game_id INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS item_data JSON NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS waiting_time_amount INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS waiting_time_unit VARCHAR(10) NULL DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS waiting_time_minutes INT(11) NULL DEFAULT NULL",
            "ALTER TABLE selling_items ADD COLUMN IF NOT EXISTS requires_friendship_days INT(11) NOT NULL DEFAULT 1",
        ];
        foreach ($alters as $sql) {
            try { $db->run($sql); } catch (\Throwable $e) {}
        }
    }

    public function seller_direct_chat_send()
    {
        global $db;
        $this->ensure_seller_chat_schema();
        if (!$this->is_seller) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }
    
        $conv_id  = (int)($_POST['conv_id'] ?? 0);
        $message  = trim(esc($_POST['message'] ?? ''));
        $seller_id = (int)$this->seller_data['id'];
    
        // Image upload
        $image_url = null;
        if (!empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Image upload failed.']]);
                return;
            }
        }
    
        if ($message === '' && !$image_url) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Please enter a message.']]);
            return;
        }
    
        // Verify ownership
        $conv = $db->row(
            "SELECT * FROM seller_conversations WHERE id = ? AND seller_id = ? LIMIT 1",
            $conv_id, $seller_id
        );
        if (!$conv) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Conversation not found.']]);
            return;
        }
    
        $now = date('Y-m-d H:i:s');
    
        if ($message !== '') {
            $db->run(
                "INSERT INTO seller_chat_messages (conversation_id, sender_type, sender_id, message, message_type, is_read, seen_by_seller, seen_by_client, created_at)
                 VALUES (?, 'seller', ?, ?, 'text', 0, 1, 0, ?)",
                $conv_id, $seller_id, $message, $now
            );
        }
        if ($image_url) {
            $db->run(
                "INSERT INTO seller_chat_messages (conversation_id, sender_type, sender_id, message, message_type, is_read, seen_by_seller, seen_by_client, created_at)
                 VALUES (?, 'seller', ?, ?, 'image', 0, 1, 0, ?)",
                $conv_id, $seller_id, $image_url, $now
            );
        }
    
        $db->run("UPDATE seller_conversations SET last_message_at = ? WHERE id = ?", $now, $conv_id);
    
        echo json_encode([
            'success'    => true,
            'created_at' => date('d.m.Y H:i', strtotime($now)),
            'image_url'  => $image_url,
        ]);
    }
    
    /**
     * seller_direct_chat_load
     * POST: conv_id, sig (last known)
     */
    public function seller_direct_chat_load()
    {
        global $db;
        // Performance: do not run schema migrations in the frequently-polled chat loader.
        // Run ensure_seller_chat_schema() once via setup/migration instead.
        if (!$this->is_seller) { echo json_encode(['success' => false, 'messages' => []]); return; }
    
        $conv_id   = (int)($_POST['conv_id'] ?? 0);
        $seller_id = (int)$this->seller_data['id'];
        $old_sig   = $_POST['sig'] ?? '';
    
        $conv = $db->row("SELECT id FROM seller_conversations WHERE id = ? AND seller_id = ? LIMIT 1", $conv_id, $seller_id);
        if (!$conv) { echo json_encode(['success' => false, 'messages' => []]); return; }
    
        // Mark client messages as read BEFORE comparing the signature.
        // Otherwise a poll with an unchanged message list can return early and the
        // seller sidebar unread badge stays visible even though the chat is open/read.
        $mark_read = ((string)($_POST['mark_read'] ?? '0') === '1');
        if ($mark_read) {
            $db->run(
                "UPDATE seller_chat_messages SET is_read = 1, seen_by_seller = 1, read_at = COALESCE(read_at, NOW()) WHERE conversation_id = ? AND sender_type = 'client' AND (is_read = 0 OR seen_by_seller = 0)",
                $conv_id
            );
            $db->run(
                "UPDATE seller_conversations SET seller_seen_at = NOW() WHERE id = ?",
                $conv_id
            );
        }

        // CPU optimisation: first fetch only the lightweight sig fields.
        // If nothing changed, skip the full SELECT * and COUNT entirely.
        $sig_rows = $db->run(
            "SELECT id, is_read, seen_by_seller, seen_by_client, read_at FROM seller_chat_messages WHERE conversation_id = ? AND deleted = 0 ORDER BY id ASC",
            $conv_id
        ) ?: [];

        $sig = md5(json_encode(array_map(function ($m) {
            return [(int)($m['id'] ?? 0), (int)($m['is_read'] ?? 0), (int)($m['seen_by_seller'] ?? 0), (int)($m['seen_by_client'] ?? 0), (string)($m['read_at'] ?? '')];
        }, $sig_rows)));

        if ($sig === $old_sig && !$mark_read) {
            echo json_encode(['success' => true, 'sig' => $sig, 'messages' => null, 'unread' => 0, 'total' => 0]);
            return;
        }

        // Sig changed — now fetch the full message data.
        $raw = $db->run(
            "SELECT * FROM seller_chat_messages WHERE conversation_id = ? AND deleted = 0 ORDER BY id ASC",
            $conv_id
        ) ?: [];

        // Only run the unread count when the message list actually changed.
        $unread_total = 0;
        if (method_exists($db, 'cell')) {
            $unread_total = (int)$db->cell(
                "SELECT COUNT(*)
                   FROM seller_chat_messages m
                   INNER JOIN seller_conversations c ON c.id = m.conversation_id
                  WHERE c.seller_id = ?
                    AND COALESCE(c.seller_status, 'open') = 'open'
                    AND m.sender_type = 'client'
                    AND m.is_read = 0
                    AND COALESCE(m.deleted, 0) = 0",
                $seller_id
            );
        }
            $messages = array_map(function ($m) {
            $sender  = (string)($m['sender_type'] ?? '');
            $seen_by_seller = $sender === 'client' ? (int)($m['seen_by_seller'] ?? $m['is_read'] ?? 0) : 1;
            $seen_by_client = $sender === 'seller' ? (int)($m['seen_by_client'] ?? 0) : 1;
            $peer_read = $sender === 'seller' ? $seen_by_client : $seen_by_seller;
            $read_at = !empty($m['read_at']) ? strtotime($m['read_at']) : 0;

            return [
                'id'             => (int)$m['id'],
                'sender_type'    => $sender,
                'body'           => ($m['message'] ?? $m['body'] ?? ''),
                'message_type'   => $m['message_type'] ?? 'text',
                'is_read'        => $peer_read,
                'seen'           => $peer_read,
                'seen_by_seller' => $seen_by_seller,
                'seen_by_client' => $seen_by_client,
                'read_at'        => $read_at ?: null,
                'read_at_fmt'    => ($peer_read && $read_at) ? date('d.m.Y H:i', $read_at) : '',
                'read_by_client_at'     => ($sender === 'seller' && $seen_by_client && $read_at) ? $read_at : null,
                'read_by_client_at_fmt' => ($sender === 'seller' && $seen_by_client && $read_at) ? date('d.m.Y H:i', $read_at) : '',
                'created_at_fmt' => date('d.m.Y H:i', strtotime($m['created_at'])),
            ];
        }, $raw);
    
        echo json_encode(['success' => true, 'sig' => $sig, 'messages' => $messages, 'unread' => $unread_total, 'total' => $unread_total]);
    }
    
    /**
     * seller_chat_archive
     * POST: conv_id, status ('open'|'archived')
     */
    public function seller_chat_archive()
    {
        global $db;
        if (!$this->is_seller) { echo json_encode(['success' => false]); return; }
    
        $conv_id   = (int)($_POST['conv_id'] ?? 0);
        $status    = in_array($_POST['status'] ?? '', ['open', 'archived']) ? $_POST['status'] : 'open';
        $seller_id = (int)$this->seller_data['id'];
    
        $db->run(
            "UPDATE seller_conversations SET seller_status = ? WHERE id = ? AND seller_id = ?",
            $status, $conv_id, $seller_id
        );
    
        echo json_encode(['success' => true, 'status' => $status]);
    }
    
