    private function seller_direct_chat_json_context(string $fallback_ref_type = 'account'): array
    {
        $seller_id = (int)($_POST['seller_id'] ?? 0);
        $ref_type  = (string)($_POST['ref_type'] ?? $fallback_ref_type);
        $ref_id    = (int)($_POST['ref_id'] ?? $_POST['account_id'] ?? $_POST['purchase_id'] ?? 0);

        if (!in_array($ref_type, ['account', 'item_purchase', 'digital_good', 'none'], true)) {
            $ref_type = 'account';
        }

        if ($ref_type === 'digital_good') {
            // Pre-purchase chat on a digital-good listing page.
            $listing = $ref_id > 0 ? db_get_row('digital_goods', ['id' => $ref_id], 1) : null;
            if (empty($listing)) {
                return ['success' => false, 'message' => 'Listing not found.'];
            }
            if ($seller_id <= 0) {
                $seller_id = (int)($listing['seller_id'] ?? 0);
            }
            if ($seller_id > 0 && (int)($listing['seller_id'] ?? 0) !== $seller_id) {
                return ['success' => false, 'message' => 'Seller mismatch.'];
            }
            return [
                'success'   => true,
                'seller_id' => $seller_id,
                'ref_type'  => 'digital_good',
                'ref_id'    => $ref_id,
                'chat_path' => SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('digital_good_' . $ref_id) . '.json',
                'meta'      => ['digital_good_id' => $ref_id, 'seller_id' => $seller_id],
            ];
        }

        if ($ref_type === 'item_purchase') {
            $purchase = $ref_id > 0 ? db_get_row('selling_item_purchases', ['id' => $ref_id], 1) : null;
            if (empty($purchase)) {
                return ['success' => false, 'message' => 'Listing not found.'];
            }
            if ($seller_id <= 0) {
                $seller_id = (int)($purchase['seller_id'] ?? 0);
            }
            if ($seller_id > 0 && (int)($purchase['seller_id'] ?? 0) !== $seller_id) {
                return ['success' => false, 'message' => 'Seller mismatch.'];
            }
            return [
                'success'   => true,
                'seller_id' => $seller_id,
                'ref_type'  => 'item_purchase',
                'ref_id'    => $ref_id,
                'chat_path' => SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_item_purchase_' . $ref_id) . '.json',
                'meta'      => ['purchase_id' => $ref_id, 'seller_id' => $seller_id],
            ];
        }

        // Product/account listing chat: this is intentionally JSON-file based, not DB conversation based.
        $account = $ref_id > 0 ? db_get_row('selling_accounts', ['id' => $ref_id], 1) : null;
        if (empty($account)) {
            return ['success' => false, 'message' => 'Listing not found.'];
        }
        if ($seller_id <= 0) {
            $seller_id = (int)($account['seller_id'] ?? 0);
        }
        if ($seller_id > 0 && (int)($account['seller_id'] ?? 0) !== $seller_id) {
            return ['success' => false, 'message' => 'Seller mismatch.'];
        }

        return [
            'success'   => true,
            'seller_id' => $seller_id,
            'ref_type'  => 'account',
            'ref_id'    => $ref_id,
            'chat_path' => SYS_PATH . '/public/uploads/private/chat/selling_' . sha1('selling_account_' . $ref_id) . '.json',
            'meta'      => ['account_id' => $ref_id, 'seller_id' => $seller_id],
        ];
    }

    private function seller_direct_chat_json_read(string $chat_path, array $meta = []): array
    {
        try {
            $refType = (string)($meta['ref_type'] ?? (!empty($meta['purchase_id']) ? 'item_purchase' : 'account'));
            $refId = (int)($meta['ref_id'] ?? $meta['purchase_id'] ?? $meta['account_id'] ?? 0);
            $key = 'seller:' . $refType . ':' . $refId;
            $opened = lb_legacy_chat_open($key, $refType, $refId, $meta, $chat_path);
            $messages = [];
            foreach ($opened['messages'] as $row) {
                $messages[] = [
                    '_db_id' => (int)$row['id'], 'id' => (int)$row['id'],
                    'type' => (string)$row['sender_type'], 'sender' => (string)$row['sender_type'],
                    'sender_id' => (int)$row['sender_id'], 'sender_name' => (string)$row['sender_name'],
                    'sender_icon' => (string)$row['sender_icon'], 'message' => (string)$row['body'],
                    'body' => (string)$row['body'], 'content' => (string)($row['rendered_body'] ?: $row['body']),
                    'message_type' => (string)$row['message_type'], 'created_at' => (string)$row['created_at'],
                    'time' => strtotime((string)$row['created_at']), 'seen_by_client' => (int)$row['seen_by_client'],
                    'seen_by_seller' => (int)$row['seen_by_seller'], 'seen_by_admin' => (int)$row['seen_by_admin'],
                    'notify' => (int)$row['notify'], 'deleted' => (int)$row['deleted'], 'edited' => (int)$row['edited'],
                ];
            }
            $fp = fopen('php://temp', 'w+');
            $this->legacy_chat_handles[(int)$fp] = (int)$opened['thread']['id'];
            return ['success' => true, 'fp' => $fp, 'data' => array_merge($meta, ['messages' => $messages])];
        } catch (\Throwable $e) {
            return ['success' => false, 'message' => 'Could not open database chat.'];
        }
    }

    private function seller_direct_chat_json_write($fp, array $chat_data): void
    {
        global $db;
        $handle = (int)$fp;
        $threadId = (int)($this->legacy_chat_handles[$handle] ?? 0);
        if ($threadId > 0) {
            foreach ((array)($chat_data['messages'] ?? []) as $m) {
                if (!is_array($m)) continue;
                $dbId = (int)($m['_db_id'] ?? 0);
                $sender = (string)($m['sender'] ?? $m['type'] ?? 'system');
                $body = (string)($m['message'] ?? $m['body'] ?? $m['raw'] ?? $m['content'] ?? '');
                if ($dbId > 0) {
                    $db->run("UPDATE legacy_chat_messages SET body=?,rendered_body=?,seen_by_client=?,seen_by_seller=?,seen_by_admin=?,notify=?,deleted=?,edited=?,read_at=? WHERE id=? AND thread_id=?",
                        $body, (string)($m['content'] ?? $body), (int)($m['seen_by_client'] ?? 0), (int)($m['seen_by_seller'] ?? 0),
                        (int)($m['seen_by_admin'] ?? 0), (int)($m['notify'] ?? 0), (int)($m['deleted'] ?? 0), (int)($m['edited'] ?? 0),
                        !empty($m['read_at']) ? date('Y-m-d H:i:s', strtotime((string)$m['read_at'])) : null, $dbId, $threadId);
                } else {
                    lb_legacy_chat_add($threadId, $sender, (int)($m['sender_id'] ?? 0), (string)($m['sender_name'] ?? ''), $body,
                        (string)($m['message_type'] ?? 'text'), ['sender_icon' => (string)($m['sender_icon'] ?? ''), 'rendered_body' => (string)($m['content'] ?? $body)]);
                }
            }
        }
        unset($this->legacy_chat_handles[$handle]);
        if (is_resource($fp)) fclose($fp);
    }

    private function seller_direct_chat_json_close($fp): void
    {
        unset($this->legacy_chat_handles[(int)$fp]);
        if (is_resource($fp)) fclose($fp);
    }

    private function seller_direct_chat_json_normalize(array $messages): array
    {
        $out = [];
        foreach (array_values($messages) as $idx => $m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = (string)($m['sender'] ?? $m['type'] ?? 'client');
            $created = (string)($m['created_at'] ?? '');
            $ts = !empty($m['time']) ? (int)$m['time'] : (!empty($created) ? strtotime($created) : time());
            if (!$ts) $ts = time();
            $body = (string)($m['message'] ?? $m['body'] ?? $m['content'] ?? '');
            if (($m['message_type'] ?? '') === 'image' && preg_match('/<img[^>]+src=["\\\']([^"\\\']+)/i', (string)($m['content'] ?? ''), $mm)) {
                $body = $body ?: $mm[1];
            }
            $out[] = [
                'id'             => (int)($m['id'] ?? ($idx + 1)),
                'sender_type'    => $sender,
                'body'           => $body,
                'message_type'   => (string)($m['message_type'] ?? 'text'),
                'is_read'        => (int)($sender === 'client' ? ($m['seen_by_seller'] ?? $m['seen'] ?? 0) : ($m['seen_by_client'] ?? $m['seen'] ?? 0)),
                'seen'           => (int)($m['seen'] ?? 0),
                'seen_by_seller' => (int)($m['seen_by_seller'] ?? ($sender === 'seller' ? 1 : 0)),
                'seen_by_client' => (int)($m['seen_by_client'] ?? ($sender === 'client' ? 1 : 0)),
                'read_at'        => !empty($m['read_at']) ? strtotime((string)$m['read_at']) : null,
                'read_at_fmt'    => !empty($m['read_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_at'])) : '',
                'read_by_seller_at'     => !empty($m['read_by_seller_at']) ? strtotime((string)$m['read_by_seller_at']) : null,
                'read_by_seller_at_fmt' => !empty($m['read_by_seller_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_seller_at'])) : '',
                'read_by_client_at'     => !empty($m['read_by_client_at']) ? strtotime((string)$m['read_by_client_at']) : null,
                'read_by_client_at_fmt' => !empty($m['read_by_client_at']) ? date('d.m.Y H:i', strtotime((string)$m['read_by_client_at'])) : '',
                'created_at_fmt' => date('d.m.Y H:i', $ts),
            ];
        }
        return $out;
    }


    /**
     * Send a Discord payload to a seller DM. Best-effort only.
     */
    private function seller_chat_send_discord_dm_payload(string $discord_id, array $dm_payload): bool
    {
        try {
            if (!defined('DS_BOT_TOKEN') || !DS_BOT_TOKEN || trim($discord_id) === '') {
                return false;
            }

            if (function_exists('getDMChannelId') && function_exists('sendEmbedDM')) {
                $dm_channel = getDMChannelId(DS_BOT_TOKEN, trim($discord_id));
                if ($dm_channel) {
                    sendEmbedDM(
                        DS_BOT_TOKEN,
                        $dm_channel,
                        json_encode($dm_payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
                    );
                    return true;
                }
            }

            $ch_dm = curl_init('https://discord.com/api/v10/users/@me/channels');
            curl_setopt_array($ch_dm, [
                CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bot ' . DS_BOT_TOKEN],
                CURLOPT_POST           => 1,
                CURLOPT_POSTFIELDS     => json_encode(['recipient_id' => trim($discord_id)]),
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT        => 5,
            ]);
            $dm_resp = curl_exec($ch_dm);
            curl_close($ch_dm);
            $dm_channel = json_decode($dm_resp, true);
            if (empty($dm_channel['id'])) {
                return false;
            }

            $ch_msg = curl_init('https://discord.com/api/v10/channels/' . $dm_channel['id'] . '/messages');
            curl_setopt_array($ch_msg, [
                CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bot ' . DS_BOT_TOKEN],
                CURLOPT_POST           => 1,
                CURLOPT_POSTFIELDS     => json_encode($dm_payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT        => 5,
            ]);
            curl_exec($ch_msg);
            curl_close($ch_msg);
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    private function seller_chat_message_timestamp(array $m): int
    {
        if (!empty($m['time']) && is_numeric($m['time'])) {
            return (int)$m['time'];
        }
        foreach (['created_at', 'date', 'timestamp'] as $key) {
            if (!empty($m[$key])) {
                $ts = strtotime((string)$m[$key]);
                if ($ts !== false) return (int)$ts;
            }
        }
        return time();
    }

    private function seller_chat_plain_message(array $m): string
    {
        $msg = trim(strip_tags(html_entity_decode((string)($m['message'] ?? $m['body'] ?? $m['content'] ?? ''), ENT_QUOTES | ENT_HTML5, 'UTF-8')));
        if ($msg === '' && (($m['message_type'] ?? '') === 'image' || ($m['type'] ?? '') === 'image')) {
            $msg = '[Image]';
        }
        if (function_exists('mb_strlen') && mb_strlen($msg, 'UTF-8') > 900) {
            $msg = mb_substr($msg, 0, 897, 'UTF-8') . '...';
        } elseif (strlen($msg) > 900) {
            $msg = substr($msg, 0, 897) . '...';
        }
        return $msg;
    }

    private function seller_chat_build_context_details(array $ctx): array
    {
        $ref_type = (string)($ctx['ref_type'] ?? 'account');
        $ref_id   = (int)($ctx['ref_id'] ?? $ctx['account_id'] ?? $ctx['purchase_id'] ?? 0);
        $title    = $ref_type === 'item_purchase' ? ('Item Order #' . $ref_id) : ('Account #' . $ref_id);
        $chat_url = '';
        $source_url = '';
        $kind_label = 'Client Request';

        if ($ref_type === 'account') {
            $account = $ref_id > 0 ? db_get_row('selling_accounts', ['id' => $ref_id], 1) : null;
            if (!empty($account['title'])) $title = (string)$account['title'];
            $is_sold = !empty($account) && (int)($account['sold'] ?? 0) === 1 && (int)($account['client_id'] ?? 0) > 0;
            $kind_label = $is_sold ? 'Account Chat' : 'Client Request';
            $chat_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/chat/account/' . $ref_id;
            $source_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/account/' . $ref_id;
        } elseif ($ref_type === 'item_purchase') {
            $purchase = $ref_id > 0 ? db_get_row('selling_item_purchases', ['id' => $ref_id], 1) : null;
            if (!empty($purchase['item_title'])) $title = (string)$purchase['item_title'];
            $kind_label = 'Item Chat';
            $chat_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/chat/item/' . $ref_id;
            $source_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/item-order/' . $ref_id;
        }

        return compact('ref_type', 'ref_id', 'title', 'chat_url', 'source_url', 'kind_label');
    }

    private function notify_seller_missed_client_message_dm(array $ctx, array $client, string $message, int $created_ts): bool
    {
        try {
            if (!defined('DS_BOT_TOKEN') || !DS_BOT_TOKEN || empty($ctx['seller_id'])) {
                return false;
            }

            global $db;
            $seller = $db->row("SELECT id, username, discord_id FROM sellers WHERE id = ? LIMIT 1", (int)$ctx['seller_id']);
            if (empty($seller['discord_id'])) {
                return false;
            }

            $client_name = trim((string)($client['username'] ?? ''));
            if ($client_name === '') {
                $client_name = trim((string)($client['email'] ?? 'Client')) ?: 'Client';
            }

            $details = $this->seller_chat_build_context_details($ctx);
            $plain_message = trim(strip_tags(html_entity_decode($message, ENT_QUOTES | ENT_HTML5, 'UTF-8')));
            if ($plain_message === '') $plain_message = '[Image]';
            if (function_exists('mb_strlen') && mb_strlen($plain_message, 'UTF-8') > 900) {
                $plain_message = mb_substr($plain_message, 0, 897, 'UTF-8') . '...';
            } elseif (strlen($plain_message) > 900) {
                $plain_message = substr($plain_message, 0, 897) . '...';
            }

            $fields = [
                ['name' => '👤 Customer', 'value' => $client_name, 'inline' => true],
                ['name' => '📌 Type', 'value' => $details['kind_label'], 'inline' => true],
                ['name' => '🆔 Order ID', 'value' => '#' . $details['ref_id'], 'inline' => true],
                ['name' => '🧾 Listing', 'value' => $details['title'], 'inline' => false],
                ['name' => '⏱️ Unseen Since', 'value' => date('d.m.Y H:i', $created_ts), 'inline' => true],
                ['name' => '💬 Message', 'value' => $plain_message, 'inline' => false],
            ];
            if ($details['chat_url'] !== '') {
                $fields[] = ['name' => '🔗 Open Chat', 'value' => '[Reply in Seller Area](' . $details['chat_url'] . ')', 'inline' => false];
            }
            if ($details['source_url'] !== '') {
                $fields[] = ['name' => '📦 Product', 'value' => '[View Listing](' . $details['source_url'] . ')', 'inline' => false];
            }

            $payload = [
                'embeds' => [[
                    'title'       => '⏰ Missed Message from Client',
                    'description' => 'A customer message has been unseen for more than 5 minutes.',
                    'color'       => 0xf59e0b,
                    'fields'      => $fields,
                    'timestamp'   => date('c'),
                ]]
            ];

            return $this->seller_chat_send_discord_dm_payload(trim((string)$seller['discord_id']), $payload);
        } catch (\Throwable $e) {
            return false;
        }
    }

    private function notify_seller_missed_client_messages(int $seller_id): void
    {
        if ($seller_id <= 0) return;
        $threshold_ts = time() - 300;
        $now = date('Y-m-d H:i:s');

        try {
            $this->ensure_seller_chat_schema();
            global $db;
            if (isset($db) && is_object($db) && method_exists($db, 'query')) {
                $rows = $db->query(
                    "SELECT m.*, c.seller_id, c.client_id, c.ref_type, c.ref_id
                       FROM seller_chat_messages m
                       INNER JOIN seller_conversations c ON c.id = m.conversation_id
                      WHERE c.seller_id = ?
                        AND COALESCE(c.seller_status, 'open') = 'open'
                        AND m.sender_type = 'client'
                        AND m.is_read = 0
                        AND COALESCE(m.deleted, 0) = 0
                        AND m.created_at <= DATE_SUB(NOW(), INTERVAL 5 MINUTE)
                        AND m.missed_dm_sent_at IS NULL
                      ORDER BY m.created_at ASC
                      LIMIT 20",
                    $seller_id
                ) ?: [];
                foreach ($rows as $row) {
                    $client = !empty($row['client_id']) ? (db_get_row('clients', ['id' => (int)$row['client_id']], 1) ?: []) : [];
                    $msg = (string)($row['message'] ?? $row['body'] ?? '');
                    if ($msg === '' && (string)($row['message_type'] ?? '') === 'image') $msg = '[Image]';
                    $created_ts = !empty($row['created_at']) ? strtotime((string)$row['created_at']) : $threshold_ts;
                    if (!$created_ts) $created_ts = $threshold_ts;
                    $this->notify_seller_missed_client_message_dm([
                        'seller_id' => $seller_id,
                        'client_id' => (int)($row['client_id'] ?? 0),
                        'ref_type'  => (string)($row['ref_type'] ?? 'account'),
                        'ref_id'    => (int)($row['ref_id'] ?? 0),
                    ], $client, $msg, $created_ts);
                    $db->run("UPDATE seller_chat_messages SET missed_dm_sent_at = ? WHERE id = ?", $now, (int)$row['id']);
                }
            }
        } catch (\Throwable $e) {}

        try {
            $chat_dir = (defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__, 3)) . '/public/uploads/private/chat';
            if (!is_dir($chat_dir)) return;
            foreach (glob($chat_dir . '/selling_*.json') ?: [] as $chat_file) {
                $fp = @fopen($chat_file, 'c+');
                if (!$fp) continue;
                if (!flock($fp, LOCK_EX)) { fclose($fp); continue; }
                $raw = stream_get_contents($fp);
                $data = json_decode($raw ?: '', true);
                if (!is_array($data) || (int)($data['seller_id'] ?? 0) !== $seller_id || empty($data['messages']) || !is_array($data['messages'])) {
                    flock($fp, LOCK_UN); fclose($fp); continue;
                }

                $changed = false;
                foreach ($data['messages'] as &$m) {
                    if (!is_array($m) || !empty($m['deleted'])) continue;
                    $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? $m['type'] ?? '')));
                    if ($sender !== 'client') continue;
                    $seen_by_seller = (int)($m['seen_by_seller'] ?? $m['seen'] ?? $m['is_read'] ?? 0);
                    if ($seen_by_seller === 1) continue;
                    if (!empty($m['missed_seller_dm_at']) || !empty($m['missed_dm_sent_at'])) continue;
                    $created_ts = $this->seller_chat_message_timestamp($m);
                    if ($created_ts > $threshold_ts) continue;

                    $client_id = (int)($m['sender_id'] ?? $data['client_id'] ?? 0);
                    $client = $client_id > 0 ? (db_get_row('clients', ['id' => $client_id], 1) ?: []) : [];
                    if (empty($client) && !empty($m['sender_name'])) $client = ['username' => (string)$m['sender_name']];
                    $ctx = [
                        'seller_id' => $seller_id,
                        'client_id' => $client_id,
                        'ref_type'  => (string)($data['ref_type'] ?? (!empty($data['purchase_id']) ? 'item_purchase' : 'account')),
                        'ref_id'    => (int)($data['ref_id'] ?? $data['account_id'] ?? $data['purchase_id'] ?? 0),
                    ];
                    $this->notify_seller_missed_client_message_dm($ctx, $client, $this->seller_chat_plain_message($m), $created_ts);
                    $m['missed_seller_dm_at'] = $now;
                    $m['missed_dm_sent_at'] = $now;
                    $changed = true;
                }
                unset($m);

                if ($changed) {
                    rewind($fp);
                    ftruncate($fp, 0);
                    fwrite($fp, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
                }
                flock($fp, LOCK_UN);
                fclose($fp);
            }
        } catch (\Throwable $e) {}
    }

    /**
     * Send a Discord DM to the seller when a client starts a new seller chat.
     * This is intentionally best-effort: Discord errors must never block chat sending.
     */
    private function notify_seller_new_customer_request_dm(array $ctx, array $client, string $message, ?string $image_url = null): void
    {
        try {
            if (!defined('DS_BOT_TOKEN') || !DS_BOT_TOKEN || empty($ctx['seller_id'])) {
                return;
            }

            global $db;

            $seller = $db->row(
                "SELECT id, username, discord_id FROM sellers WHERE id = ? LIMIT 1",
                (int)$ctx['seller_id']
            );
            if (empty($seller['discord_id'])) {
                return;
            }

            $client_name = trim((string)($client['username'] ?? ''));
            if ($client_name === '') {
                $client_name = trim((string)($client['email'] ?? 'Client')) ?: 'Client';
            }

            $ref_type = (string)($ctx['ref_type'] ?? 'account');
            $ref_id   = (int)($ctx['ref_id'] ?? 0);
            $title    = $ref_type === 'item_purchase' ? ('Item Order #' . $ref_id) : ('Account #' . $ref_id);
            $chat_url = '';
            $source_url = '';
            $kind_label = 'Client Request';

            if ($ref_type === 'account') {
                $account = $ref_id > 0 ? db_get_row('selling_accounts', ['id' => $ref_id], 1) : null;
                if (!empty($account['title'])) {
                    $title = (string)$account['title'];
                }
                $is_sold = !empty($account) && (int)($account['sold'] ?? 0) === 1 && (int)($account['client_id'] ?? 0) > 0;
                $kind_label = $is_sold ? 'Account Chat' : 'Client Request';
                $chat_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/chat/account/' . $ref_id;
                $source_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/account/' . $ref_id;
            } elseif ($ref_type === 'item_purchase') {
                $purchase = $ref_id > 0 ? db_get_row('selling_item_purchases', ['id' => $ref_id], 1) : null;
                if (!empty($purchase['item_title'])) {
                    $title = (string)$purchase['item_title'];
                }
                $kind_label = 'Item Chat';
                $chat_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/chat/item/' . $ref_id;
                $source_url = (defined('BASE_URL') ? BASE_URL : '') . '/seller-area/item-order/' . $ref_id;
            }

            $plain_message = trim(strip_tags(html_entity_decode($message, ENT_QUOTES | ENT_HTML5, 'UTF-8')));
            if ($plain_message === '' && $image_url) {
                $plain_message = '[Image]';
            }
            if (mb_strlen($plain_message, 'UTF-8') > 900) {
                $plain_message = mb_substr($plain_message, 0, 897, 'UTF-8') . '...';
            }

            $fields = [
                ['name' => '👤 Customer', 'value' => $client_name, 'inline' => true],
                ['name' => '📌 Type', 'value' => $kind_label, 'inline' => true],
                ['name' => '🧾 Listing', 'value' => $title, 'inline' => false],
            ];
            if ($plain_message !== '') {
                $fields[] = ['name' => '💬 Message', 'value' => $plain_message, 'inline' => false];
            }
            if ($chat_url !== '') {
                $fields[] = ['name' => '🔗 Open Chat', 'value' => '[Open in Seller Area](' . $chat_url . ')', 'inline' => false];
            }
            if ($source_url !== '') {
                $fields[] = ['name' => '📦 Product', 'value' => '[View Listing](' . $source_url . ')', 'inline' => false];
            }

            $dm_embed = [
                'embeds' => [[
                    'title'       => '📩 New Customer Request',
                    'description' => 'A customer started a chat with you on LoLBoost.GG.',
                    'color'       => 0x8b5cf6,
                    'fields'      => $fields,
                    'timestamp'   => date('c'),
                ]]
            ];

            if (function_exists('getDMChannelId') && function_exists('sendEmbedDM')) {
                $dm_channel = getDMChannelId(DS_BOT_TOKEN, trim((string)$seller['discord_id']));
                if ($dm_channel) {
                    sendEmbedDM(
                        DS_BOT_TOKEN,
                        $dm_channel,
                        json_encode($dm_embed, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
                    );
                    return;
                }
            }

            // Fallback if the global helper functions are unavailable.
            $ch_dm = curl_init('https://discord.com/api/v10/users/@me/channels');
            curl_setopt_array($ch_dm, [
                CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bot ' . DS_BOT_TOKEN],
                CURLOPT_POST           => 1,
                CURLOPT_POSTFIELDS     => json_encode(['recipient_id' => trim((string)$seller['discord_id'])]),
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT        => 5,
            ]);
            $dm_resp = curl_exec($ch_dm);
            curl_close($ch_dm);
            $dm_channel = json_decode($dm_resp, true);
            if (!empty($dm_channel['id'])) {
                $ch_msg = curl_init('https://discord.com/api/v10/channels/' . $dm_channel['id'] . '/messages');
                curl_setopt_array($ch_msg, [
                    CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bot ' . DS_BOT_TOKEN],
                    CURLOPT_POST           => 1,
                    CURLOPT_POSTFIELDS     => json_encode($dm_embed, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                    CURLOPT_RETURNTRANSFER => 1,
                    CURLOPT_TIMEOUT        => 5,
                ]);
                curl_exec($ch_msg);
                curl_close($ch_msg);
            }
        } catch (\Throwable $e) {
            // Never block chat sending because of Discord DM issues.
        }
    }

    /**
     * client_seller_chat_send
     * POST: seller_id, message, [ref_type, ref_id, conv_id, chat_image]
     */
    public function client_seller_chat_send()
    {
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'auth_required' => true, 'sendToast' => ['type' => 'danger', 'message' => 'Please log in to send a message.']]);
            return;
        }

        $ctx = $this->seller_direct_chat_json_context('account');
        if (empty($ctx['success'])) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => $ctx['message'] ?? 'Listing not found.']]);
            return;
        }

        $message = trim(esc($_POST['message'] ?? ''));
        $image_url = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $image_url = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($image_url === false) {
                echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Image upload failed.']]);
                return;
            }
        }

        if ($message === '' && !$image_url) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Please enter a message.']]);
            return;
        }

        $client = db_get_row('clients', ['id' => (int)CLIENT_ID], 1);
        $client_name = $client['username'] ?? $client['email'] ?? 'Client';
        $now = date('Y-m-d H:i:s');

        $opened = $this->seller_direct_chat_json_read($ctx['chat_path'], array_merge($ctx['meta'], [
            'client_id' => (int)CLIENT_ID,
            'ref_type'  => $ctx['ref_type'],
            'ref_id'    => $ctx['ref_id'],
        ]));
        if (empty($opened['success'])) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => $opened['message'] ?? 'Could not open chat file.']]);
            return;
        }

        $fp = $opened['fp'];
        $chat_data = $opened['data'];
        $chat_data = array_merge($ctx['meta'], $chat_data, [
            'client_id' => (int)CLIENT_ID,
            'ref_type'  => $ctx['ref_type'],
            'ref_id'    => $ctx['ref_id'],
            'updated_at'=> $now,
        ]);

        $next_id = count($chat_data['messages']) + 1;
        $is_first_message = empty($chat_data['messages']);

        // Inject system context message on first contact
        if ($is_first_message) {
            $account_title = '';
            $listing_url   = '';
            if ($ctx['ref_type'] === 'account') {
                $acc = db_get_row('selling_accounts', ['id' => $ctx['ref_id']], 1);
                $account_title = $acc['title'] ?? ('Account #' . $ctx['ref_id']);
                $listing_url   = defined('BASE_URL') ? BASE_URL . '/lol/accounts/' . $ctx['ref_id'] : '';
            } elseif ($ctx['ref_type'] === 'item_purchase') {
                $purch = db_get_row('selling_item_purchases', ['id' => $ctx['ref_id']], 1);
                $account_title = $purch['item_title'] ?? ('Item Order #' . $ctx['ref_id']);
                $listing_url   = defined('BASE_URL') ? BASE_URL . '/profile/item/' . $ctx['ref_id'] : '';
            } elseif ($ctx['ref_type'] === 'digital_good') {
                $dg = db_get_row('digital_goods', ['id' => $ctx['ref_id']], 1);
                $account_title = $dg['title'] ?? ('Digital Good #' . $ctx['ref_id']);
                $listing_url   = (!empty($dg) && function_exists('dg_listing_url'))
                    ? dg_listing_url($dg)
                    : (defined('BASE_URL') ? BASE_URL . '/digital-good/' . $ctx['ref_id'] : '');
            }
            if ($account_title !== '') {
                // Plain text only — the chat renderers escape this and turn bare URLs
                // into links themselves, so markup here would show up as literal tags.
                $system_msg = $client_name . ' started a chat about: ' . $account_title;
                if ($listing_url) $system_msg .= "\n" . $listing_url;
                $chat_data['messages'][] = [
                    'id'             => $next_id++,
                    'type'           => 'system',
                    'sender'         => 'system',
                    'sender_id'      => 0,
                    'sender_name'    => 'System',
                    'message'        => $system_msg,
                    'content'        => $system_msg,
                    'message_type'   => 'system',
                    'body'           => $system_msg,
                    'raw'            => $system_msg,
                    'created_at'     => $now,
                    'time'           => time(),
                    'seen'           => 1,
                    'notify'         => 0,
                    'seen_by_seller' => 0,
                    'seen_by_client' => 1,
                    'seen_by_admin'  => 0,
                ];
            }
        }

        if ($message !== '') {
            $chat_data['messages'][] = [
                'id'             => $next_id++,
                'type'           => 'client',
                'sender'         => 'client',
                'sender_id'      => (int)CLIENT_ID,
                'sender_name'    => $client_name,
                'message'        => $message,
                'content'        => $message,
                'message_type'   => 'text',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
            ];
        }
        if ($image_url) {
            $chat_data['messages'][] = [
                'id'             => $next_id++,
                'type'           => 'client',
                'sender'         => 'client',
                'sender_id'      => (int)CLIENT_ID,
                'sender_name'    => $client_name,
                'message'        => $image_url,
                'content'        => '<img src="' . htmlspecialchars($image_url, ENT_QUOTES) . '" alt="image">',
                'message_type'   => 'image',
                'created_at'     => $now,
                'time'           => time(),
                'seen'           => 0,
                'notify'         => 0,
                'seen_by_seller' => 0,
                'seen_by_client' => 1,
                'seen_by_admin'  => 0,
            ];
        }

        $this->seller_direct_chat_json_write($fp, $chat_data);

        if (function_exists('lb_realtime_schedule_seller_unread_email')) {
            lb_realtime_schedule_seller_unread_email([
                'seller_id' => (int)($ctx['seller_id'] ?? 0),
                'client_id' => (int)CLIENT_ID,
                'ref_type' => (string)($ctx['ref_type'] ?? 'account'),
                'ref_id' => (int)($ctx['ref_id'] ?? 0),
            ]);
        }

        if ($is_first_message) {
            $this->notify_seller_new_customer_request_dm($ctx, $client ?: [], $message, $image_url);
        }

        $redirect_url = $is_first_message
            ? (defined('BASE_URL') ? BASE_URL : '') . '/profile/chat#conv=' . urlencode($ctx['ref_type'] . ':' . $ctx['ref_id'])
            : null;

        echo json_encode([
            'success'     => true,
            'conv_id'     => $ctx['ref_type'] . ':' . $ctx['ref_id'],
            'ref_type'    => $ctx['ref_type'],
            'ref_id'      => $ctx['ref_id'],
            'created_at'  => date('d.m.Y H:i', strtotime($now)),
            'image_url'   => $image_url,
            'redirectUrl' => $redirect_url,
        ]);
    }

    
    /**
     * client_seller_chat_load
     * POST: seller_id, [conv_id], sig
     */
    public function client_seller_chat_load()
    {
        if (!$this->is_client) { echo json_encode(['success' => false, 'messages' => [], 'auth_required' => true]); return; }

        $ctx = $this->seller_direct_chat_json_context('account');
        if (empty($ctx['success'])) {
            echo json_encode(['success' => true, 'conv_id' => null, 'sig' => '', 'messages' => [], 'unread_client' => 0]);
            return;
        }

        $opened = $this->seller_direct_chat_json_read($ctx['chat_path'], array_merge($ctx['meta'], [
            'client_id' => (int)CLIENT_ID,
            'ref_type'  => $ctx['ref_type'],
            'ref_id'    => $ctx['ref_id'],
        ]));
        if (empty($opened['success'])) {
            echo json_encode(['success' => false, 'messages' => [], 'sendToast' => ['type' => 'danger', 'message' => $opened['message'] ?? 'Could not open chat file.']]);
            return;
        }

        $fp = $opened['fp'];
        $chat_data = $opened['data'];
        $old_sig = (string)($_POST['sig'] ?? '');
        $changed = false;
        $unread = 0;
        $mark_read = ((string)($_POST['mark_read'] ?? '0') === '1');

        $msg_order = function (array $m, int $index): int {
            if (!empty($m['time']) && is_numeric($m['time'])) { return (int)$m['time']; }
            if (!empty($m['created_at'])) { $ts = strtotime((string)$m['created_at']); if ($ts !== false) { return (int)$ts; } }
            return $index;
        };
        $msg_sender = function (array $m): string {
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $type = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && in_array($type, ['client', 'seller', 'system'], true)) { $sender = $type; }
            return $sender;
        };
        $last_client_value = 0;
        foreach ($chat_data['messages'] as $idx => $m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            if ($msg_sender($m) === 'client') { $last_client_value = max($last_client_value, $msg_order($m, $idx + 1)); }
        }
        foreach ($chat_data['messages'] as $idx => &$m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = $msg_sender($m);
            if (in_array($sender, ['seller', 'admin'], true)) {
                if (array_key_exists('seen_by_client', $m)) {
                    $seen_by_client = (int)$m['seen_by_client'];
                } elseif (array_key_exists('seen', $m)) {
                    $seen_by_client = (int)$m['seen'];
                } elseif (array_key_exists('is_read', $m)) {
                    $seen_by_client = (int)$m['is_read'];
                } else {
                    $seen_by_client = 1;
                }
                $message_value = $msg_order($m, $idx + 1);
                $is_unread = ($seen_by_client !== 1) && !($last_client_value > 0 && $message_value <= $last_client_value);
                if ($is_unread) {
                    $unread++;
                    if ($mark_read) {
                        $m['seen_by_client'] = 1;
                        $m['seen'] = 1;
                        $m['is_read'] = 1;
                        $m['read_by_client_at'] = $m['read_by_client_at'] ?? date('Y-m-d H:i:s');
                        $changed = true;
                    }
                } elseif (!array_key_exists('seen_by_client', $m)) {
                    $m['seen_by_client'] = 1;
                    $changed = true;
                }
            }
        }
        unset($m);

        $sig = md5(json_encode(array_map(function ($m) {
            if (!is_array($m) || !empty($m['deleted'])) return null;
            return [
                $m['id'] ?? null,
                $m['sender'] ?? $m['type'] ?? '',
                $m['message'] ?? $m['content'] ?? '',
                $m['time'] ?? $m['created_at'] ?? '',
                $m['seen_by_client'] ?? null,
                $m['seen_by_seller'] ?? null,
            ];
        }, $chat_data['messages'])));

        if ($changed) {
            $chat_data['client_seen_at'] = date('Y-m-d H:i:s');
            $this->seller_direct_chat_json_write($fp, $chat_data);
        if (function_exists('lb_realtime_schedule_client_unread_email')) {
            lb_realtime_schedule_client_unread_email(['client_id'=>(int)($ctx['client_id']??$chat_data['client_id']??0),'seller_id'=>(int)$this->seller_data['id'],'ref_type'=>$ctx['ref_type'],'ref_id'=>(int)$ctx['ref_id']]);
        }
        } else {
            $this->seller_direct_chat_json_close($fp);
        }

        if ($mark_read) {
            $unread = 0;
        }

        if ($sig === $old_sig) {
            echo json_encode(['success' => true, 'conv_id' => $ctx['ref_type'] . ':' . $ctx['ref_id'], 'sig' => $sig, 'messages' => null, 'unread_client' => $unread]);
            return;
        }

        echo json_encode([
            'success'       => true,
            'conv_id'       => $ctx['ref_type'] . ':' . $ctx['ref_id'],
            'ref_type'      => $ctx['ref_type'],
            'ref_id'        => $ctx['ref_id'],
            'sig'           => $sig,
            'messages'      => $this->seller_direct_chat_json_normalize($chat_data['messages']),
            'unread_client' => $unread,
        ]);
    }

    
    /**
     * client_seller_chat_mark_read
     * POST: seller_id, [conv_id]
     */
    public function client_seller_chat_mark_read()
    {
        if (!$this->is_client) { echo json_encode(['success' => false, 'auth_required' => true]); return; }
        $ctx = $this->seller_direct_chat_json_context('account');
        if (empty($ctx['success'])) { echo json_encode(['success' => false]); return; }
        $opened = $this->seller_direct_chat_json_read($ctx['chat_path'], $ctx['meta']);
        if (empty($opened['success'])) { echo json_encode(['success' => false]); return; }
        $fp = $opened['fp'];
        $chat_data = $opened['data'];
        $changed = false;
        foreach ($chat_data['messages'] as &$m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $type = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && in_array($type, ['client', 'seller', 'system'], true)) { $sender = $type; }
            if (in_array($sender, ['seller', 'admin'], true) && (int)($m['seen_by_client'] ?? 0) !== 1) {
                $m['seen_by_client'] = 1;
                $m['seen'] = 1;
                $m['is_read'] = 1;
                $m['read_by_client_at'] = $m['read_by_client_at'] ?? date('Y-m-d H:i:s');
                $changed = true;
            }
        }
        unset($m);
        if ($changed) $this->seller_direct_chat_json_write($fp, $chat_data); else $this->seller_direct_chat_json_close($fp);
        echo json_encode(['success' => true]);
    }


    /**
     * seller_chat_mark_seen
     * Setzt seller_seen_at = NOW() — wird beim Öffnen eines Chats aufgerufen.
     * POST: conv_id
     */
    public function seller_chat_mark_seen()
    {
        global $db;
        // ensure_seller_chat_schema() removed from this hot path — called only on send.
        if (!$this->is_seller) { echo json_encode(['success' => false]); return; }

        $conv_id   = (int)($_POST['conv_id'] ?? 0);
        $seller_id = (int)$this->seller_data['id'];

        if ($conv_id <= 0) { echo json_encode(['success' => false]); return; }

        $conv = $db->row(
            "SELECT id FROM seller_conversations WHERE id = ? AND seller_id = ? LIMIT 1",
            $conv_id, $seller_id
        );
        if (!$conv) { echo json_encode(['success' => false]); return; }

        $db->run("UPDATE seller_conversations SET seller_seen_at = NOW() WHERE id = ?", $conv_id);
        $db->run(
            "UPDATE seller_chat_messages SET is_read = 1, seen_by_seller = 1, read_at = COALESCE(read_at, NOW()) WHERE conversation_id = ? AND sender_type = 'client' AND (is_read = 0 OR seen_by_seller = 0)",
            $conv_id
        );

        echo json_encode(['success' => true]);
    }

    /**
     * client_seller_chat_unread_count
     * Realtime count for the client sidebar "My Chats" badge.
     * JSON-file based, counts unread seller messages for the current client.
     */
    public function client_seller_chat_unread_count()
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success' => false, 'unread' => 0, 'total' => 0]);
            return;
        }

        $client_id = (int)CLIENT_ID;

        // Cache for 10 s — this is polled on every sidebar tick.
        // Shared with the client sidebar's initial render (util_client_chat_unread_count in
        // functions.php) so both agree on the same seller-chat + booster/admin-order-chat total.
        $total = 0;
        ob_start();
        $this->client_seller_chat_inbox_state();
        $stateRaw = (string)ob_get_clean();
        $state = json_decode($stateRaw, true);
        if (is_array($state) && !empty($state['success']) && is_array($state['conversations'] ?? null)) {
            foreach ($state['conversations'] as $conversation) {
                $total += max(0, (int)($conversation['unread_client'] ?? 0));
            }
        }

        $json = json_encode([
            'success' => true,
            'unread' => $total,
            'total' => $total,
            'role' => 'client',
            'user_id' => $client_id,
        ]);

        echo $json;
    }

    /**
     * client_seller_chat_inbox_state
     * Realtime conversation list for the client inbox (/profile/chat), JSON-file based.
     */
    public function client_seller_chat_inbox_state()
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success' => false, 'conversations' => [], 'total' => 0, 'account_count' => 0, 'item_count' => 0, 'boosting_count' => 0]);
            return;
        }
        $client_id = (int)CLIENT_ID;
        global $db;

        // CPU optimisation: short-lived transient cache (10 s TTL).
        // Rebuilt at most every 10 s even if browser polls every 5 s.
        // Client JS already skips re-rendering when sig is unchanged.
        $chat_dir = (defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__, 3)) . '/public/uploads/private/chat';
        $conversations = [];
        $senderOf = static function(array $m): string {
            $s = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $t = strtolower(trim((string)($m['type'] ?? '')));
            if ($s === '' && in_array($t, ['client','seller','booster','system','admin'], true)) $s = $t;
            return $s;
        };
        $timeOf = static function(array $m, int $i): int {
            foreach (['time', 'timestamp', 'created_at_ts'] as $k) {
                if (!empty($m[$k]) && is_numeric($m[$k])) {
                    $v = (int)$m[$k];
                    return $v > 20000000000 ? (int)floor($v / 1000) : $v;
                }
            }
            foreach (['created_at', 'created_at_fmt', 'date', 'datetime'] as $k) {
                if (empty($m[$k])) { continue; }
                $raw = trim((string)$m[$k]);
                $ts = strtotime($raw);
                if ($ts !== false) { return (int)$ts; }
                foreach (['d.m.Y H:i:s', 'd.m.Y H:i', 'd.m.y H:i:s', 'd.m.y H:i'] as $fmt) {
                    $dt = \DateTime::createFromFormat($fmt, $raw, new \DateTimeZone('Europe/Berlin'));
                    if ($dt instanceof \DateTime) { return (int)$dt->getTimestamp(); }
                }
            }
            return $i;
        };
        $bodyOf = static function(array $m): string {
            $body = trim(strip_tags((string)($m['message'] ?? $m['body'] ?? $m['content'] ?? $m['raw'] ?? '')));
            if (($m['message_type'] ?? '') === 'image' || ($m['type'] ?? '') === 'image') return $body !== '' ? $body : 'Image';
            if (($m['message_type'] ?? '') === 'system' || ($m['type'] ?? '') === 'system') return $body !== '' ? $body : 'System message';
            return $body;
        };
        if (is_dir($chat_dir)) {
            foreach (glob($chat_dir . '/selling_*.json') ?: [] as $chat_file) {
                $data = json_decode(@file_get_contents($chat_file) ?: '', true);
                if (!is_array($data)) continue;
                $messages = isset($data['messages']) && is_array($data['messages']) ? array_values($data['messages']) : [];
                $belongs = ((int)($data['client_id'] ?? 0) === $client_id);
                if (!$belongs) {
                    foreach ($messages as $m) {
                        if (is_array($m) && empty($m['deleted']) && $senderOf($m) === 'client' && (int)($m['sender_id'] ?? 0) === $client_id) { $belongs = true; break; }
                    }
                }
                if (!$belongs) continue;
                if ((string)($data['ref_type'] ?? '') === 'digital_good' || !empty($data['digital_good_id'])) {
                    $ref_type = 'digital_good';
                } elseif (!empty($data['purchase_id']) || (string)($data['ref_type'] ?? '') === 'item_purchase') {
                    $ref_type = 'item_purchase';
                } else {
                    $ref_type = 'account';
                }
                if ($ref_type === 'digital_good')      $ref_id = (int)($data['digital_good_id'] ?? $data['ref_id'] ?? 0);
                elseif ($ref_type === 'item_purchase') $ref_id = (int)($data['purchase_id'] ?? $data['ref_id'] ?? 0);
                else                                   $ref_id = (int)($data['account_id'] ?? $data['ref_id'] ?? 0);
                if ($ref_id <= 0) continue;
                $seller_id = (int)($data['seller_id'] ?? 0);
                $title = $ref_type === 'digital_good' ? ('Digital Good #' . $ref_id) : ($ref_type === 'item_purchase' ? ('Item Order #' . $ref_id) : ('Account #' . $ref_id));
                $status = $ref_type === 'item_purchase' ? 'paid' : 'request';
                if ($ref_type === 'digital_good') {
                    $dg = function_exists('db_get_row') ? db_get_row('digital_goods', ['id' => $ref_id], 1) : null;
                    if (!empty($dg)) { $seller_id = $seller_id ?: (int)($dg['seller_id'] ?? 0); $title = (string)($dg['title'] ?? $title); }
                    $source_url = (!empty($dg) && function_exists('dg_listing_url'))
                        ? dg_listing_url($dg)
                        : (defined('BASE_URL') ? BASE_URL . '/digital-good/' . $ref_id : '');
                } elseif ($ref_type === 'item_purchase') {
                    $p = function_exists('db_get_row') ? db_get_row('selling_item_purchases', ['id' => $ref_id], 1) : null;
                    if (!empty($p)) { $seller_id = $seller_id ?: (int)($p['seller_id'] ?? 0); $title = (string)($p['item_title'] ?? $p['title'] ?? $title); }
                    $source_url = defined('BASE_URL') ? BASE_URL . '/profile/item/' . $ref_id : '';
                } else {
                    $a = function_exists('db_get_row') ? db_get_row('selling_accounts', ['id' => $ref_id], 1) : null;
                    if (!empty($a)) { $seller_id = $seller_id ?: (int)($a['seller_id'] ?? 0); $title = (string)($a['title'] ?? $title); }
                    $source_url = defined('BASE_URL') ? BASE_URL . '/lol/accounts/' . $ref_id : '';
                }
                $seller = $seller_id > 0 && function_exists('db_get_row') ? db_get_row('sellers', ['id' => $seller_id], 1) : null;
                $seller_name = !empty($seller) ? (string)($seller['username'] ?? 'Seller') : 'Seller';
                $seller_icon = !empty($seller) ? (string)($seller['icon'] ?? '') : '';
                $last = null; $last_at = 0; $unread = 0;
                $last_client_value = 0;
                foreach ($messages as $ci => $cm) {
                    if (!is_array($cm) || !empty($cm['deleted'])) continue;
                    if ($senderOf($cm) === 'client') { $last_client_value = max($last_client_value, $timeOf($cm, $ci + 1)); }
                }
                foreach ($messages as $i => $m) {
                    if (!is_array($m) || !empty($m['deleted'])) continue;
                    $t = $timeOf($m, $i + 1);
                    if ($t >= $last_at) { $last_at = $t; $last = $m; }
                    if ($senderOf($m) === 'seller') {
                        if (array_key_exists('seen_by_client', $m)) $is_unread = ((int)$m['seen_by_client'] === 0);
                        elseif (array_key_exists('is_read', $m)) $is_unread = ((int)$m['is_read'] === 0);
                        elseif (array_key_exists('seen', $m)) $is_unread = ((int)$m['seen'] === 0);
                        else $is_unread = false;
                        if ($is_unread && !($last_client_value > 0 && $t <= $last_client_value)) $unread++;
                    }
                }
                $conversations[] = [
                    'key' => $ref_type . ':' . $ref_id, 'seller_id' => $seller_id, 'seller_username' => $seller_name,
                    'seller_icon' => $seller_icon, 'ref_type' => $ref_type, 'ref_id' => $ref_id, 'request_status' => $status,
                    'title' => $title, 'source_url' => $source_url, 'source_label' => $status === 'request' ? 'View Shop Listing' : 'View Order',
                    'last_body' => $last ? $bodyOf($last) : 'No message yet', 'last_message_at' => $last_at,
                    'last_time_label' => $last_at > 0 ? (date('Y-m-d', $last_at) === date('Y-m-d') ? date('H:i', $last_at) : ($last_at > strtotime('-7 days') ? date('D', $last_at) : date('M j', $last_at))) : '',
                    'unread_client' => $unread,
                ];
            }
        }

        // Include classic/premium account chats (accounts table).
        // These files are stored as accounts_<sha1('account_'.$id)>.json and must not be treated as booster chats.
        try {
            $premium_accounts = [];
            $premium_sql = "SELECT a.id, a.package_id, a.login, a.server, a.admin_id, a.sold_at, a.created_at,
                            ap.name AS package_name, ap.server AS package_server,
                            adm.username AS admin_username, adm.icon AS admin_icon
                     FROM accounts a
                     LEFT JOIN account_packages ap ON ap.id = a.package_id
                     LEFT JOIN admins adm ON adm.id = a.admin_id
                     WHERE a.client_id = ? AND (a.status = 1 OR a.client_id IS NOT NULL)
                     ORDER BY COALESCE(a.sold_at, a.created_at) DESC, a.id DESC
                     LIMIT 150";
            if (isset($db) && method_exists($db, 'run')) {
                $premium_accounts = $db->run($premium_sql, $client_id) ?: [];
            } elseif (isset($db) && method_exists($db, 'rows')) {
                $premium_accounts = $db->rows($premium_sql, $client_id) ?: [];
            }

            foreach ($premium_accounts as $account) {
                if (!is_array($account)) { continue; }
                $account_id = (int)($account['id'] ?? 0);
                if ($account_id <= 0) { continue; }

                $chat_file = $chat_dir . '/accounts_' . sha1('account_' . $account_id) . '.json';
                $messages = [];
                $has_chat_file = is_file($chat_file);
                if ($has_chat_file) {
                    $raw = json_decode(@file_get_contents($chat_file) ?: '', true);
                    $messages = isset($raw['messages']) && is_array($raw['messages']) ? array_values($raw['messages']) : (is_array($raw) ? array_values($raw) : []);
                }

                $last = null; $last_at = 0; $unread = 0;
                foreach ($messages as $i => $m) {
                    if (!is_array($m) || !empty($m['deleted'])) { continue; }
                    $sender = $senderOf($m);
                    $t = $timeOf($m, $i + 1);
                    if ($t >= $last_at) { $last_at = $t; $last = $m; }
                    if ($sender === 'admin') {
                        if (array_key_exists('seen_by_client', $m)) $is_unread = ((int)$m['seen_by_client'] === 0);
                        elseif (array_key_exists('is_read', $m)) $is_unread = ((int)$m['is_read'] === 0);
                        elseif (array_key_exists('seen', $m)) $is_unread = ((int)$m['seen'] === 0);
                        else $is_unread = false;
                        if ($is_unread) { $unread++; }
                    }
                }

                if ($last_at <= 0) {
                    $base_ts = strtotime((string)($account['sold_at'] ?? $account['created_at'] ?? ''));
                    $last_at = $base_ts !== false ? (int)$base_ts : 0;
                }

                $title = trim((string)($account['package_name'] ?? $account['login'] ?? 'Smurf Account'));
                $server = trim((string)($account['package_server'] ?? $account['server'] ?? ''));
                $admin_name = trim((string)($account['admin_username'] ?? '')) ?: 'Support';

                $conversations[] = [
                    'key' => 'premium_account:' . $account_id,
                    'chat_type' => 'premium_account',
                    'seller_id' => 0,
                    'seller_username' => $admin_name,
                    'seller_icon' => (string)($account['admin_icon'] ?? ''),
                    'ref_type' => 'premium_account',
                    'ref_id' => $account_id,
                    'request_status' => 'paid',
                    'title' => $title !== '' ? $title : ('Account #' . $account_id),
                    'source_url' => defined('BASE_URL') ? BASE_URL . '/premium-account/' . $account_id : '',
                    'source_label' => 'View Account',
                    'last_body' => $last ? $bodyOf($last) : 'No message yet',
                    'last_message_at' => $last_at,
                    'last_time_label' => $last_at > 0 ? (date('Y-m-d', $last_at) === date('Y-m-d') ? date('H:i', $last_at) : ($last_at > strtotime('-7 days') ? date('D', $last_at) : date('M j', $last_at))) : '',
                    'unread_client' => $unread,
                    'server' => $server,
                ];
            }
        } catch (\Throwable $e) {}

        // Also include normal LoL boosting order chats (JSON files: public/uploads/private/chat/{sha1(order_id)}.json).
        // Important: these are NOT seller chats. They are the regular client <-> booster order chats.
        try {
            global $db;
            $orders = [];
            // Do not require booster_id here: older chats can exist before/after assignment changes.
            // We only show orders owned by the current client, and we prefer orders that have a JSON chat file
            // or a real assigned booster.
            $orders_sql = "SELECT o.id, o.form_id, o.status, o.created_at, o.paid_at, o.booster_id,
                            b.username AS booster_username, b.icon AS booster_icon,
                            bf.name AS form_name, bf.type AS form_type
                     FROM orders o
                     LEFT JOIN boosters b ON b.id = o.booster_id
                     LEFT JOIN boost_forms bf ON bf.id = o.form_id
                     WHERE o.client_id = ?
                     ORDER BY COALESCE(o.paid_at, o.created_at) DESC, o.id DESC
                     LIMIT 150";
            if (isset($db) && method_exists($db, 'run')) {
                $orders = $db->run($orders_sql, $client_id) ?: [];
            } elseif (isset($db) && method_exists($db, 'rows')) {
                $orders = $db->rows($orders_sql, $client_id) ?: [];
            }

            $normalize_messages = static function($raw): array {
                if (!is_array($raw)) return [];
                if (isset($raw['messages']) && is_array($raw['messages'])) return array_values($raw['messages']);
                return array_values($raw);
            };

            foreach ($orders as $order) {
                if (!is_array($order)) continue;
                $order_id = (int)($order['id'] ?? 0);
                if ($order_id <= 0) continue;

                $chat_file = $chat_dir . '/' . sha1((string)$order_id) . '.json';
                $messages = [];
                $has_chat_file = is_file($chat_file);

                if ($has_chat_file) {
                    $raw_chat = json_decode(@file_get_contents($chat_file) ?: '', true);
                    $messages = $normalize_messages($raw_chat);
                } elseif (function_exists('chat_load_messages')) {
                    // Fallback to the project chat helper, in case the storage path changes.
                    $raw_chat = chat_load_messages($order_id);
                    $messages = $normalize_messages($raw_chat);
                }

                // If there is no JSON chat and no assigned booster, do not flood the inbox with every old order.
                if (!$has_chat_file && empty($messages) && (int)($order['booster_id'] ?? 0) <= 0) {
                    continue;
                }

                $booster_name = trim((string)($order['booster_username'] ?? ''));
                $booster_icon = trim((string)($order['booster_icon'] ?? ''));
                if ($booster_name === '') $booster_name = ((int)($order['booster_id'] ?? 0) > 0) ? 'Booster' : 'Booster not assigned';

                $title = trim((string)($order['form_name'] ?? $order['form_type'] ?? ''));
                if ($title === '') $title = 'Boosting Order #' . $order_id;

                $last = null; $last_at = 0; $unread = 0;
                $last_client_value = 0;
                foreach ($messages as $ci => $cm) {
                    if (!is_array($cm) || !empty($cm['deleted'])) continue;
                    if ($senderOf($cm) === 'client') { $last_client_value = max($last_client_value, $timeOf($cm, $ci + 1)); }
                }
                foreach ($messages as $i => $m) {
                    if (!is_array($m) || !empty($m['deleted'])) continue;
                    $sender = $senderOf($m);
                    $t = $timeOf($m, $i + 1);
                    if ($t >= $last_at) { $last_at = $t; $last = $m; }

                    // In boosting order JSON chats, booster messages can be stored as sender/sender_type = booster.
                    if ($sender === 'booster') {
                        if (array_key_exists('seen_by_client', $m)) $is_unread = ((int)$m['seen_by_client'] === 0);
                        elseif (array_key_exists('is_read', $m)) $is_unread = ((int)$m['is_read'] === 0);
                        elseif (array_key_exists('seen', $m)) $is_unread = ((int)$m['seen'] === 0);
                        else $is_unread = false;
                        if ($is_unread && !($last_client_value > 0 && $t <= $last_client_value)) $unread++;
                    }
                }
                if ($last_at <= 0) {
                    $base_ts = strtotime((string)($order['paid_at'] ?? $order['created_at'] ?? ''));
                    $last_at = $base_ts !== false ? (int)$base_ts : 0;
                }

                $conversations[] = [
                    'key' => 'booster_order:' . $order_id,
                    'chat_type' => 'booster',
                    'seller_id' => 0,
                    'seller_username' => $booster_name,
                    'seller_icon' => $booster_icon,
                    'ref_type' => 'booster_order',
                    'ref_id' => $order_id,
                    'request_status' => 'paid',
                    'title' => $title,
                    'source_url' => defined('BASE_URL') ? BASE_URL . '/profile/orders/' . $order_id : '',
                    'source_label' => 'View Order',
                    'last_body' => $last ? $bodyOf($last) : 'No booster message yet',
                    'last_message_at' => $last_at,
                    'last_time_label' => $last_at > 0 ? (date('Y-m-d', $last_at) === date('Y-m-d') ? date('H:i', $last_at) : ($last_at > strtotime('-7 days') ? date('D', $last_at) : date('M j', $last_at))) : '',
                    'unread_client' => $unread,
                ];
            }
        } catch (\Throwable $e) {}


        $random_booster_chat_summary = static function(string $chat_file) use ($client_id, $senderOf, $timeOf, $bodyOf, $chat_dir) {
            $base = basename($chat_file, '.json');
            if (strpos($base, 'selling_') === 0 || strpos($base, 'accounts_') === 0) return null;
            $data = json_decode(@file_get_contents($chat_file) ?: '', true);
            if (!is_array($data)) return null;
            $messages = (isset($data['messages']) && is_array($data['messages'])) ? array_values($data['messages']) : array_values($data);
            if (empty($messages)) return null;
            $client_username = defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? strtolower(trim((string)(CLIENT_DATA['username'] ?? ''))) : '';
            $belongs = ((int)($data['client_id'] ?? $data['user_id'] ?? 0) === $client_id);
            foreach ($messages as $m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                if ($senderOf($m) !== 'client') continue;
                $mid = (int)($m['sender_id'] ?? $m['client_id'] ?? $m['user_id'] ?? 0);
                if ($mid === $client_id) { $belongs = true; break; }
                $mname = strtolower(trim((string)($m['sender_name'] ?? $m['username'] ?? $m['name'] ?? '')));
                if ($client_username !== '' && $mname !== '' && $mname === $client_username) { $belongs = true; break; }
            }
            if (!$belongs) return null;

            $order_id = (int)($data['order_id'] ?? $data['ref_id'] ?? $data['id'] ?? 0);
            $last = null; $last_at = 0; $unread = 0;
            $last_client_value = 0;
            foreach ($messages as $ci => $cm) {
                if (!is_array($cm) || !empty($cm['deleted'])) continue;
                if ($senderOf($cm) === 'client') { $last_client_value = max($last_client_value, $timeOf($cm, $ci + 1)); }
            }
            foreach ($messages as $i => $m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                $sender = $senderOf($m);
                $t = $timeOf($m, $i + 1);
                if ($t >= $last_at) { $last_at = $t; $last = $m; }
                if (in_array($sender, ['booster','admin','seller'], true)) {
                    if (array_key_exists('seen_by_client', $m)) $is_unread = ((int)$m['seen_by_client'] === 0);
                    elseif (array_key_exists('is_read', $m)) $is_unread = ((int)$m['is_read'] === 0);
                    elseif (array_key_exists('seen', $m)) $is_unread = ((int)$m['seen'] === 0);
                    else $is_unread = false;
                    if ($is_unread && !($last_client_value > 0 && $t <= $last_client_value)) $unread++;
                }
            }
            return ['chat_key' => $base, 'order_id' => $order_id, 'messages' => $messages, 'last' => $last, 'last_at' => $last_at, 'unread' => $unread, 'data' => $data];
        };

        if (is_dir($chat_dir)) {
            $existing_booster_keys = [];
            foreach ($conversations as $c) {
                if (($c['chat_type'] ?? '') === 'booster') {
                    $existing_booster_keys[(string)($c['ref_id'] ?? 0)] = true;
                    if (!empty($c['chat_key'])) $existing_booster_keys[(string)$c['chat_key']] = true;
                }
            }
            foreach (glob($chat_dir . '/*.json') ?: [] as $chat_file) {
                $sum = $random_booster_chat_summary($chat_file);
                if (!$sum) continue;
                $order_id = (int)$sum['order_id'];
                $chat_key = (string)$sum['chat_key'];
                if (($order_id > 0 && isset($existing_booster_keys[(string)$order_id])) || isset($existing_booster_keys[$chat_key])) continue;
                $order = null;
                $booster_name = 'Booster Chat'; $booster_icon = ''; $title = 'Boosting Chat'; $source_url = '';
                if ($order_id > 0 && isset($db)) {
                    $order = $db->row("SELECT o.id, o.client_id, o.form_id, o.status, o.created_at, o.paid_at, o.booster_id, b.username AS booster_username, b.icon AS booster_icon, bf.name AS form_name, bf.type AS form_type FROM orders o LEFT JOIN boosters b ON b.id=o.booster_id LEFT JOIN boost_forms bf ON bf.id=o.form_id WHERE o.id=? AND o.client_id=? LIMIT 1", $order_id, $client_id);
                }
                if (!empty($order)) {
                    $booster_name = trim((string)($order['booster_username'] ?? '')) ?: (((int)($order['booster_id'] ?? 0)>0) ? 'Booster' : 'Booster not assigned');
                    $booster_icon = (string)($order['booster_icon'] ?? '');
                    $title = trim((string)($order['form_name'] ?? $order['form_type'] ?? '')) ?: ('Boosting Order #' . $order_id);
                    $source_url = defined('BASE_URL') ? BASE_URL . '/profile/orders/' . $order_id : '';
                }
                $conversations[] = [
                    'key' => 'booster_raw:' . $chat_key,
                    'chat_type' => 'booster', 'seller_id' => 0, 'seller_username' => $booster_name, 'seller_icon' => $booster_icon,
                    'ref_type' => 'booster_order', 'ref_id' => $order_id, 'chat_key' => $chat_key, 'request_status' => 'paid',
                    'title' => $title, 'source_url' => $source_url, 'source_label' => $order_id > 0 ? 'View Order' : 'Boosting Chat',
                    'last_body' => $sum['last'] ? $bodyOf($sum['last']) : 'No booster message yet', 'last_message_at' => (int)$sum['last_at'],
                    'last_time_label' => ((int)$sum['last_at'] > 0 ? (date('Y-m-d', (int)$sum['last_at']) === date('Y-m-d') ? date('H:i', (int)$sum['last_at']) : ((int)$sum['last_at'] > strtotime('-7 days') ? date('D', (int)$sum['last_at']) : date('M j', (int)$sum['last_at']))) : ''),
                    'unread_client' => (int)$sum['unread'],
                ];
            }
        }


        // Last-resort direct JSON scan for premium/classic account chats.
        // This is the important part for /public/uploads/private/chat/accounts_<sha1('account_'.$id)>.json:
        // we do not depend on the accounts DB query only. If the JSON file belongs to this client,
        // it is added to the inbox directly.
        if (is_dir($chat_dir)) {
            $existing_premium_keys = [];
            foreach ($conversations as $c) {
                if (($c['chat_type'] ?? '') === 'premium_account' || ($c['ref_type'] ?? '') === 'premium_account') {
                    $existing_premium_keys[(int)($c['ref_id'] ?? 0)] = true;
                }
            }
            $client_username_lc = defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? strtolower(trim((string)(CLIENT_DATA['username'] ?? ''))) : '';
            foreach (glob($chat_dir . '/accounts_*.json') ?: [] as $account_chat_file) {
                $raw = json_decode(@file_get_contents($account_chat_file) ?: '', true);
                if (!is_array($raw)) { continue; }
                $messages = isset($raw['messages']) && is_array($raw['messages']) ? array_values($raw['messages']) : (array_is_list($raw) ? array_values($raw) : []);

                $belongs = ((int)($raw['client_id'] ?? $raw['user_id'] ?? 0) === $client_id);
                if (!$belongs) {
                    foreach ($messages as $m) {
                        if (!is_array($m) || !empty($m['deleted'])) { continue; }
                        if ($senderOf($m) !== 'client') { continue; }
                        $mid = (int)($m['sender_id'] ?? $m['client_id'] ?? $m['user_id'] ?? 0);
                        $mname = strtolower(trim((string)($m['sender_name'] ?? $m['username'] ?? $m['name'] ?? '')));
                        if ($mid === $client_id || ($client_username_lc !== '' && $mname !== '' && $mname === $client_username_lc)) { $belongs = true; break; }
                    }
                }
                if (!$belongs) { continue; }

                $account_id = (int)($raw['account_id'] ?? $raw['ref_id'] ?? $raw['id'] ?? 0);
                if ($account_id <= 0 && isset($db) && method_exists($db, 'run')) {
                    // Hash cannot be reversed, so compare against the client's recent account ids.
                    try {
                        $file_hash = preg_replace('/^accounts_|\.json$/', '', basename($account_chat_file));
                        $rows = $db->run("SELECT id FROM accounts WHERE client_id = ? ORDER BY id DESC LIMIT 500", $client_id) ?: [];
                        foreach ($rows as $r) {
                            $rid = (int)($r['id'] ?? 0);
                            if ($rid > 0 && sha1('account_' . $rid) === $file_hash) { $account_id = $rid; break; }
                        }
                    } catch (\Throwable $e) {}
                }
                if ($account_id <= 0 || isset($existing_premium_keys[$account_id])) { continue; }

                $account = null; $package = null; $admin = null;
                try {
                    if (isset($db) && method_exists($db, 'row')) {
                        $account = $db->row("SELECT * FROM accounts WHERE id = ? AND client_id = ? LIMIT 1", $account_id, $client_id);
                    } elseif (function_exists('db_get_row')) {
                        $account = db_get_row('accounts', ['id' => $account_id, 'client_id' => $client_id], 1);
                    }
                    if (!empty($account) && !empty($account['package_id']) && function_exists('db_get_row')) {
                        $package = db_get_row('account_packages', ['id' => (int)$account['package_id']], 1);
                    }
                    if (!empty($account) && !empty($account['admin_id']) && function_exists('db_get_row')) {
                        $admin = db_get_row('admins', ['id' => (int)$account['admin_id']], 1);
                    }
                } catch (\Throwable $e) {}

                $last = null; $last_at = 0; $unread = 0; $last_client_value = 0;
                foreach ($messages as $ci => $cm) {
                    if (!is_array($cm) || !empty($cm['deleted'])) { continue; }
                    if ($senderOf($cm) === 'client') { $last_client_value = max($last_client_value, $timeOf($cm, $ci + 1)); }
                }
                foreach ($messages as $i => $m) {
                    if (!is_array($m) || !empty($m['deleted'])) { continue; }
                    $sender = $senderOf($m);
                    $t = $timeOf($m, $i + 1);
                    if ($t >= $last_at) { $last_at = $t; $last = $m; }
                    if ($sender === 'admin' || $sender === 'seller' || $sender === 'support') {
                        if (array_key_exists('seen_by_client', $m)) $is_unread = ((int)$m['seen_by_client'] === 0);
                        elseif (array_key_exists('is_read', $m)) $is_unread = ((int)$m['is_read'] === 0);
                        elseif (array_key_exists('seen', $m)) $is_unread = ((int)$m['seen'] === 0);
                        else $is_unread = false;
                        if ($is_unread && !($last_client_value > 0 && $t <= $last_client_value)) $unread++;
                    }
                }
                if ($last_at <= 0 && !empty($account)) {
                    $base_ts = strtotime((string)($account['sold_at'] ?? $account['created_at'] ?? ''));
                    $last_at = $base_ts !== false ? (int)$base_ts : 0;
                }

                $title = trim((string)($package['name'] ?? $account['name'] ?? $account['login'] ?? 'Smurf Account'));
                $server = trim((string)($package['server'] ?? $account['server'] ?? ''));
                $admin_name = trim((string)($admin['username'] ?? '')) ?: 'Support';
                $admin_icon = (string)($admin['icon'] ?? '');
                $conversations[] = [
                    'key' => 'premium_account:' . $account_id,
                    'chat_type' => 'premium_account',
                    'seller_id' => 0,
                    'seller_username' => $admin_name,
                    'seller_icon' => $admin_icon,
                    'ref_type' => 'premium_account',
                    'ref_id' => $account_id,
                    'request_status' => 'paid',
                    'title' => $title !== '' ? $title : ('Account #' . $account_id),
                    'source_url' => defined('BASE_URL') ? BASE_URL . '/premium-account/' . $account_id : '',
                    'source_label' => 'View Account',
                    'last_body' => $last ? $bodyOf($last) : 'No message yet',
                    'last_message_at' => $last_at,
                    'last_time_label' => $last_at > 0 ? (date('Y-m-d', $last_at) === date('Y-m-d') ? date('H:i', $last_at) : ($last_at > strtotime('-7 days') ? date('D', $last_at) : date('M j', $last_at))) : '',
                    'unread_client' => $unread,
                    'server' => $server,
                ];
                $existing_premium_keys[$account_id] = true;
            }
        }

        // DB-first overlay for migrated seller chats. New account/item messages are written to
        // legacy_chat_messages; overlaying by ref key prevents the old JSON snapshot from
        // hiding them in the client inbox.
        try {
            if (function_exists('lb_legacy_chat_ensure_schema')) {
                lb_legacy_chat_ensure_schema();
                $dbThreads = $db->run(
                    "SELECT t.*,
                            (SELECT m.body FROM legacy_chat_messages m WHERE m.thread_id=t.id AND m.deleted=0 ORDER BY m.created_at DESC,m.id DESC LIMIT 1) AS last_body,
                            (SELECT m.created_at FROM legacy_chat_messages m WHERE m.thread_id=t.id AND m.deleted=0 ORDER BY m.created_at DESC,m.id DESC LIMIT 1) AS last_message_at,
                            (SELECT COUNT(*) FROM legacy_chat_messages m WHERE m.thread_id=t.id AND m.deleted=0 AND m.sender_type IN ('seller','admin') AND m.seen_by_client=0) AS unread_client
                       FROM legacy_chat_threads t
                      WHERE t.client_id=? OR EXISTS (SELECT 1 FROM legacy_chat_messages cm WHERE cm.thread_id=t.id AND cm.sender_type='client' AND cm.sender_id=?)",
                    $client_id, $client_id
                ) ?: [];
                $dbOverlay = [];
                foreach ($dbThreads as $thread) {
                    $refType = (string)($thread['chat_type'] ?? 'account');
                    $refId = (int)($thread['ref_id'] ?? 0);
                    if ($refId <= 0) continue;
                    $metaRow = json_decode((string)($thread['metadata'] ?? ''), true);
                    $metaRow = is_array($metaRow) ? $metaRow : [];
                    $sellerId = (int)($thread['seller_id'] ?? $metaRow['seller_id'] ?? 0);
                    $sellerRow = $sellerId > 0 ? $db->row("SELECT username,icon FROM sellers WHERE id=? LIMIT 1", $sellerId) : [];
                    $lastAt = strtotime((string)($thread['last_message_at'] ?? '')) ?: 0;
                    $dbOverlay[$refType . ':' . $refId] = [
                        'key' => $refType . ':' . $refId,
                        'chat_type' => $refType === 'topup_purchase' ? 'topup' : 'seller',
                        'seller_id' => $sellerId,
                        'seller_username' => (string)($sellerRow['username'] ?? 'Seller'),
                        'seller_icon' => (string)($sellerRow['icon'] ?? ''),
                        'ref_type' => $refType,
                        'ref_id' => $refId,
                        'request_status' => 'paid',
                        'title' => (string)($metaRow['title'] ?? ucfirst(str_replace('_', ' ', $refType)) . ' #' . $refId),
                        'source_url' => '',
                        'source_label' => 'View Order',
                        'last_body' => (string)($thread['last_body'] ?? 'No message yet'),
                        'last_message_at' => $lastAt,
                        'last_time_label' => $lastAt > 0 ? (date('Y-m-d', $lastAt) === date('Y-m-d') ? date('H:i', $lastAt) : date('M j', $lastAt)) : '',
                        'unread_client' => (int)($thread['unread_client'] ?? 0),
                    ];
                }
                if ($dbOverlay) {
                    $conversations = array_values(array_filter($conversations, static function(array $c) use ($dbOverlay): bool {
                        return !isset($dbOverlay[(string)($c['ref_type'] ?? '') . ':' . (int)($c['ref_id'] ?? 0)]);
                    }));
                    foreach ($dbOverlay as $dbConversation) $conversations[] = $dbConversation;
                }
            }
        } catch (\Throwable $e) {}

        usort($conversations, static function($a, $b){ return ((int)($b['last_message_at'] ?? 0)) <=> ((int)($a['last_message_at'] ?? 0)); });
        $account_count = 0; $item_count = 0; $boosting_count = 0;
        foreach ($conversations as $c) {
            $ref_type = (string)($c['ref_type'] ?? '');
            $chat_type = (string)($c['chat_type'] ?? '');
            if ($chat_type === 'booster' || $ref_type === 'booster_order') $boosting_count++;
            elseif ($ref_type === 'item_purchase') $item_count++;
            else $account_count++;
        }
        $result_json = json_encode(['success' => true, 'conversations' => $conversations, 'total' => count($conversations), 'account_count' => $account_count, 'item_count' => $item_count, 'boosting_count' => $boosting_count, 'request_count' => $account_count, 'order_count' => ($item_count + $boosting_count), 'sig' => md5(json_encode($conversations))]);
        // Cache directly (no ob_start needed — avoids nesting issues with other handlers)
        echo $result_json;
    }

    /**
     * client_booster_chat_load
     * Realtime load for normal client <-> booster order chat inside the client inbox.
     */
    public function client_booster_chat_load()
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }
        $order_id = (int)($_POST['order_id'] ?? $_POST['ref_id'] ?? 0);
        $chat_key = preg_replace('/[^a-fA-F0-9]/', '', (string)($_POST['chat_key'] ?? ''));
        $chat_dir = (defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__, 3)) . '/public/uploads/private/chat';
        $chat_file = '';
        $order = null;
        if ($order_id > 0) {
            $order = function_exists('db_get_row') ? db_get_row('orders', ['id' => $order_id, 'client_id' => (int)CLIENT_ID], 1) : null;
            if (!empty($order)) $chat_file = $chat_dir . '/' . sha1((string)$order_id) . '.json';
        }
        if ($chat_file === '' && $chat_key !== '' && strlen($chat_key) === 40) {
            $candidate = $chat_dir . '/' . $chat_key . '.json';
            if (is_file($candidate)) $chat_file = $candidate;
        }
        $raw_chat = null;
        $messages = [];

        $has_chat_file = $chat_file !== '' && is_file($chat_file);
        if ($has_chat_file) {
            $raw_chat = json_decode(@file_get_contents($chat_file) ?: '', true);
        }
        // DB-only booster chats have no JSON file. The inbox already discovers
        // them through chat_messages, so loading must use the same source.
        if (!is_array($raw_chat) && $order_id > 0 && !empty($order) && function_exists('chat_load_messages')) {
            $raw_chat = chat_load_messages($order_id);
        }
        if (!is_array($raw_chat)) {
            echo json_encode(['success' => false, 'messages' => []]);
            return;
        }
        $messages = isset($raw_chat['messages']) && is_array($raw_chat['messages']) ? array_values($raw_chat['messages']) : array_values($raw_chat);
        // A successfully loaded order was already constrained by client_id above.
        $belongs = !empty($order) || ((int)($raw_chat['client_id'] ?? $raw_chat['user_id'] ?? 0) === (int)CLIENT_ID);
        $client_username = defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? strtolower(trim((string)(CLIENT_DATA['username'] ?? ''))) : '';
        foreach ($messages as $m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $typeField = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && $typeField === 'client') $sender = 'client';
            if ($sender !== 'client') continue;
            $mid = (int)($m['sender_id'] ?? $m['client_id'] ?? $m['user_id'] ?? 0);
            $mname = strtolower(trim((string)($m['sender_name'] ?? $m['username'] ?? $m['name'] ?? '')));
            if ($mid === (int)CLIENT_ID || ($client_username !== '' && $mname !== '' && $mname === $client_username)) { $belongs = true; break; }
        }
        if (!$belongs) { echo json_encode(['success' => false, 'messages' => []]); return; }

        // Mark booster messages as seen by the client only when the inbox explicitly opens the chat with mark_read=1.
        $mark_read = ((string)($_POST['mark_read'] ?? '0') === '1');
        if ($mark_read) {
            $changed = false;
            $container_key = (isset($raw_chat['messages']) && is_array($raw_chat['messages'])) ? 'messages' : null;
            $work =& $messages;
            foreach ($work as &$m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? $m['type'] ?? '')));
                if (in_array($sender, ['booster', 'admin', 'seller'], true)) {
                    if ((int)($m['seen_by_client'] ?? 0) !== 1) { $m['seen_by_client'] = 1; $changed = true; }
                    if (array_key_exists('seen', $m) && (int)$m['seen'] !== 1) { $m['seen'] = 1; $changed = true; }
                    if (array_key_exists('is_read', $m) && (int)$m['is_read'] !== 1) { $m['is_read'] = 1; $changed = true; }
                }
            }
            unset($m);
            if ($changed && $has_chat_file) {
                if ($container_key) $raw_chat[$container_key] = $work; else $raw_chat = $work;
                @file_put_contents($chat_file, json_encode($raw_chat, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
            }

            // Keep the legacy DB mirror in sync as well. Some older orders still have
            // chat_messages rows, and leaving those unseen made the sidebar jump back up
            // after F5 even though the JSON chat had already been read.
            if ($order_id > 0) {
                global $db;
                if (isset($db) && is_object($db)) {
                    try {
                        $db->run(
                            "UPDATE chat_messages
                                SET seen = 1
                              WHERE order_id = ?
                                AND sender IN ('booster', 'admin')
                                AND seen = 0
                                AND COALESCE(deleted, 0) = 0",
                            $order_id
                        );
                    } catch (\Throwable $e) {}
                }
            }
        }

        // Prepare after mark_read, so returned messages reflect the current seen state.
        if (function_exists('chat_prepare_for_viewer')) {
            $prepared = chat_prepare_for_viewer(['messages' => $messages], 'client');
            if (is_array($prepared) && isset($prepared['messages']) && is_array($prepared['messages'])) {
                $messages = array_values($prepared['messages']);
            }
        }

        $norm = [];
        foreach ($messages as $i => $m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $typeField = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && in_array($typeField, ['client', 'booster', 'admin', 'system'], true)) $sender = $typeField;
            if (!in_array($sender, ['client', 'booster', 'admin', 'system'], true)) $sender = 'booster';
            $body = (string)($m['body'] ?? $m['message'] ?? $m['content'] ?? $m['raw'] ?? '');
            $message_type = (string)($m['message_type'] ?? ($typeField === 'image' ? 'image' : 'text'));
            if ($typeField === 'system') $message_type = 'system';
            $ts = 0;
            if (!empty($m['time']) && is_numeric($m['time'])) $ts = (int)$m['time'];
            elseif (!empty($m['created_at'])) { $tmp = strtotime((string)$m['created_at']); if ($tmp !== false) $ts = (int)$tmp; }
            elseif (!empty($m['timestamp']) && is_numeric($m['timestamp'])) $ts = (int)$m['timestamp'];
            $norm[] = [
                'id' => $m['id'] ?? $i,
                'sender_type' => $sender,
                'sender' => $sender,
                'sender_icon' => (string)($m['sender_icon'] ?? $m['icon'] ?? ''),
                'body' => $body,
                'raw' => $body,
                'image_url' => ($message_type === 'image') ? $body : (string)($m['image_url'] ?? ''),
                'message_type' => $message_type,
                'type' => $message_type,
                'created_at_fmt' => (string)($m['created_at_fmt'] ?? ($ts > 0 ? date('d.m.Y H:i', $ts) : '')),
                'seen_by_seller' => (int)($m['seen_by_seller'] ?? $m['seen_by_booster'] ?? $m['seen'] ?? 0),
            ];
        }
        $sig = md5(json_encode($norm));
        if ((string)($_POST['sig'] ?? '') !== '' && hash_equals((string)$_POST['sig'], $sig)) {
            echo json_encode(['success' => true, 'messages' => null, 'sig' => $sig]);
            return;
        }
        echo json_encode(['success' => true, 'messages' => $norm, 'sig' => $sig]);
    }


    public function client_raw_booster_chat_send()
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }
        $chat_key = preg_replace('/[^a-fA-F0-9]/', '', (string)($_POST['chat_key'] ?? ''));
        if ($chat_key === '' || strlen($chat_key) !== 40) {
            echo json_encode(['success' => false, 'message' => 'Invalid chat']);
            return;
        }
        $chat_dir = (defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__, 3)) . '/public/uploads/private/chat';
        $chat_file = $chat_dir . '/' . $chat_key . '.json';
        if (!is_file($chat_file)) {
            echo json_encode(['success' => false, 'message' => 'Chat not found']);
            return;
        }
        $raw = json_decode(@file_get_contents($chat_file) ?: '', true);
        if (!is_array($raw)) $raw = ['messages' => []];
        $messages = isset($raw['messages']) && is_array($raw['messages']) ? array_values($raw['messages']) : array_values($raw);
        $belongs = ((int)($raw['client_id'] ?? $raw['user_id'] ?? 0) === (int)CLIENT_ID);
        $client_username = defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? strtolower(trim((string)(CLIENT_DATA['username'] ?? ''))) : '';
        foreach ($messages as $m) {
            if (!is_array($m) || !empty($m['deleted'])) continue;
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $typeField = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && $typeField === 'client') $sender = 'client';
            if ($sender !== 'client') continue;
            $mid = (int)($m['sender_id'] ?? $m['client_id'] ?? $m['user_id'] ?? 0);
            $mname = strtolower(trim((string)($m['sender_name'] ?? $m['username'] ?? $m['name'] ?? '')));
            if ($mid === (int)CLIENT_ID || ($client_username !== '' && $mname !== '' && $mname === $client_username)) { $belongs = true; break; }
        }
        if (!$belongs) { echo json_encode(['success' => false, 'message' => 'Unauthorized chat']); return; }

        $message = trim((string)($_POST['message'] ?? ''));
        $image_url = null;
        $fileKey = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) $fileKey = 'chat_image';
        elseif (isset($_FILES['image_url']) && !empty($_FILES['image_url']['tmp_name'])) $fileKey = 'image_url';
        if ($fileKey) {
            $image_url = upload_image($_FILES[$fileKey], 'private/chat_images');
            if ($image_url === false) { echo json_encode(['success' => false, 'message' => 'Image upload failed']); return; }
        }
        if ($message === '' && !$image_url) { echo json_encode(['success' => false, 'message' => 'Please type a message or attach an image.']); return; }
        $now = time();
        $created = date('Y-m-d H:i:s', $now);
        $append = [];
        if ($message !== '') {
            $append[] = ['id' => count($messages), 'sender_type' => 'client', 'sender' => 'client', 'sender_id' => (int)CLIENT_ID, 'sender_name' => defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? (string)(CLIENT_DATA['username'] ?? '') : '', 'message' => $message, 'body' => $message, 'message_type' => 'text', 'type' => 'text', 'time' => $now, 'created_at' => $created, 'seen_by_client' => 1, 'seen_by_booster' => 0];
        }
        if ($image_url) {
            $append[] = ['id' => count($messages) + count($append), 'sender_type' => 'client', 'sender' => 'client', 'sender_id' => (int)CLIENT_ID, 'sender_name' => defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? (string)(CLIENT_DATA['username'] ?? '') : '', 'message' => $image_url, 'body' => $image_url, 'message_type' => 'image', 'type' => 'image', 'time' => $now, 'created_at' => $created, 'seen_by_client' => 1, 'seen_by_booster' => 0];
        }
        foreach ($append as $m) $messages[] = $m;
        if (isset($raw['messages']) && is_array($raw['messages'])) $raw['messages'] = $messages; else $raw = $messages;
        @file_put_contents($chat_file, json_encode($raw, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
        echo json_encode(['success' => true, 'created_at' => date('d.m.Y H:i', $now), 'image_url' => $image_url]);
    }


    /**
     * client_seller_chat_mark_all_read
     * Marks every unread message in the client's chat inbox as read.
     * Covers marketplace seller JSON chats (selling_*.json) and regular/random booster order JSON chats (*.json).
     */
    public function client_seller_chat_mark_all_read()
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        $client_id = (int)CLIENT_ID;
        $client_username = defined('CLIENT_DATA') && is_array(CLIENT_DATA) ? strtolower(trim((string)(CLIENT_DATA['username'] ?? ''))) : '';
        $chat_dir = (defined('SYS_PATH') ? SYS_PATH : dirname(__DIR__, 3)) . '/public/uploads/private/chat';
        $changed_chats = 0;
        $changed_messages = 0;

        $senderOf = static function(array $m): string {
            $sender = strtolower(trim((string)($m['sender_type'] ?? $m['sender'] ?? $m['from'] ?? '')));
            $type = strtolower(trim((string)($m['type'] ?? '')));
            if ($sender === '' && in_array($type, ['client', 'seller', 'booster', 'admin', 'system'], true)) {
                $sender = $type;
            }
            return $sender;
        };

        $belongsToClient = static function(array $data, array $messages) use ($client_id, $client_username, $senderOf): bool {
            if ((int)($data['client_id'] ?? $data['user_id'] ?? 0) === $client_id) {
                return true;
            }
            foreach ($messages as $m) {
                if (!is_array($m) || !empty($m['deleted'])) { continue; }
                if ($senderOf($m) !== 'client') { continue; }
                $mid = (int)($m['sender_id'] ?? $m['client_id'] ?? $m['user_id'] ?? 0);
                $mname = strtolower(trim((string)($m['sender_name'] ?? $m['username'] ?? $m['name'] ?? '')));
                if ($mid === $client_id || ($client_username !== '' && $mname !== '' && $mname === $client_username)) {
                    return true;
                }
            }
            return false;
        };

        $markMessage = static function(array &$m) use ($senderOf): bool {
            $sender = $senderOf($m);
            if (!in_array($sender, ['seller', 'booster', 'admin'], true)) {
                return false;
            }
            $changed = false;
            if ((int)($m['seen_by_client'] ?? 0) !== 1) { $m['seen_by_client'] = 1; $changed = true; }
            if (array_key_exists('seen', $m) && (int)$m['seen'] !== 1) { $m['seen'] = 1; $changed = true; }
            if (array_key_exists('is_read', $m) && (int)$m['is_read'] !== 1) { $m['is_read'] = 1; $changed = true; }
            if ($changed && empty($m['read_at'])) { $m['read_at'] = date('Y-m-d H:i:s'); }
            return $changed;
        };

        if (is_dir($chat_dir)) {
            foreach (glob($chat_dir . '/*.json') ?: [] as $chat_file) {
                $raw = json_decode(@file_get_contents($chat_file) ?: '', true);
                if (!is_array($raw)) { continue; }

                $has_container = isset($raw['messages']) && is_array($raw['messages']);
                $messages = $has_container ? array_values($raw['messages']) : array_values($raw);
                if (!$belongsToClient($raw, $messages)) { continue; }

                $changed_this_chat = false;
                foreach ($messages as &$m) {
                    if (!is_array($m) || !empty($m['deleted'])) { continue; }
                    if ($markMessage($m)) {
                        $changed_this_chat = true;
                        $changed_messages++;
                    }
                }
                unset($m);

                if ($changed_this_chat) {
                    if ($has_container) { $raw['messages'] = $messages; }
                    else { $raw = $messages; }
                    @file_put_contents($chat_file, json_encode($raw, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
                    $changed_chats++;
                }
            }
        }

        echo json_encode([
            'success' => true,
            'changed_chats' => $changed_chats,
            'changed_messages' => $changed_messages,
            'unread' => 0,
            'total' => 0,
        ]);
    }

    /**
     * client_seller_chat_mark_seen
     * Setzt client_seen_at = NOW() — wird beim Öffnen des Chats auf Client-Seite aufgerufen.
     * POST: seller_id
     */
    public function client_seller_chat_mark_seen()
    {
        $this->client_seller_chat_mark_read();
    }


    // ════════════════════════════════════════════════════════════════════════
    //  ADMIN: Banner Settings
    //  Saves all top-banner configuration (texts, colors, images, countdown)
    //  into the `site_settings` key/value table.
    // ════════════════════════════════════════════════════════════════════════
    public function admin_banner_save()
    {
        global $db;

        if (!defined('ADMIN_DATA') || ADMIN_DATA == false) {
            echo json_encode(['status' => 'error', 'message' => 'Unauthorized']);
            return;
        }

        // Ensure site_settings table exists
        try {
            $db->query("CREATE TABLE IF NOT EXISTS `site_settings` (
                `key`        VARCHAR(160) NOT NULL,
                `value`      TEXT         NOT NULL,
                `updated_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (`key`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        } catch (\Throwable $e) {}

        // All allowed text/color/url keys
        $text_keys = [
            'banner_type',
            // Pro Games
            'banner_pg_badge_text', 'banner_pg_badge_color', 'banner_pg_badge_border',
            'banner_pg_icon_url',
            'banner_pg_title', 'banner_pg_title_color', 'banner_pg_accent_color',
            'banner_pg_bg_color_from', 'banner_pg_bg_color_to',
            'banner_pg_bg_image', 'banner_pg_bg_image_opacity',
            'banner_pg_pill_1', 'banner_pg_pill_2', 'banner_pg_pill_3', 'banner_pg_pill_4', 'banner_pg_pill_5',
            'banner_pg_cta_text', 'banner_pg_cta_link',
            'banner_pg_cta_bg_from', 'banner_pg_cta_bg_to', 'banner_pg_cta_color',
            'banner_pg_mob_title', 'banner_pg_mob_sub', 'banner_pg_mob_title_color', 'banner_pg_mob_sub_color',
            'banner_pg_mob_cta_text', 'banner_pg_mob_cta_link',
            // Sale
            'banner_sale_headline', 'banner_sale_title_color',
            'banner_sale_accent_from', 'banner_sale_accent_to',
            'banner_sale_sub', 'banner_sale_sub_color',
            'banner_sale_bg_color_from', 'banner_sale_bg_color_to',
            'banner_sale_bg_image_left', 'banner_sale_bg_image_right', 'banner_sale_bg_image_opacity',
            'banner_sale_bg_left_pos_x_desktop', 'banner_sale_bg_left_pos_y_desktop',
            'banner_sale_bg_right_pos_x_desktop', 'banner_sale_bg_right_pos_y_desktop',
            'banner_sale_bg_left_pos_x_mobile', 'banner_sale_bg_left_pos_y_mobile',
            'banner_sale_bg_right_pos_x_mobile', 'banner_sale_bg_right_pos_y_mobile',
            'banner_sale_ends_at', 'banner_sale_countdown_label',
            'banner_sale_countdown_color', 'banner_sale_countdown_unit_bg', 'banner_sale_countdown_border',
            'banner_sale_cta_1_text', 'banner_sale_cta_1_link', 'banner_sale_cta_1_icon',
            'banner_sale_cta_1_bg_from', 'banner_sale_cta_1_bg_to',
            'banner_sale_cta_2_text', 'banner_sale_cta_2_link', 'banner_sale_cta_2_icon',
            'banner_sale_cta_2_bg_from', 'banner_sale_cta_2_bg_to',
            'banner_sale_mob_pct', 'banner_sale_mob_pct_color_from', 'banner_sale_mob_pct_color_to',
            'banner_sale_mob_label', 'banner_sale_mob_label_color',
        ];

        // File inputs → [hidden field key, upload subdirectory]
        $file_keys = [
            'banner_pg_bg_image_file'        => ['banner_pg_bg_image',        'banner'],
            'banner_pg_icon_url_file'         => ['banner_pg_icon_url',        'banner'],
            'banner_sale_bg_image_left_file'  => ['banner_sale_bg_image_left', 'banner'],
            'banner_sale_bg_image_right_file' => ['banner_sale_bg_image_right','banner'],
            'banner_sale_cta_1_icon_file'     => ['banner_sale_cta_1_icon',    'banner'],
            'banner_sale_cta_2_icon_file'     => ['banner_sale_cta_2_icon',    'banner'],
        ];

        $errors   = [];
        $uploaded = [];

        // Process file uploads
        foreach ($file_keys as $input_name => [$hidden_key, $dir]) {
            if (empty($_FILES[$input_name]['tmp_name'])) continue;
            $url = upload_image($_FILES[$input_name], $dir);
            if ($url) {
                $uploaded[$hidden_key] = $url;
            } else {
                $errors[] = 'Upload failed for ' . htmlspecialchars($input_name) . ' (unsupported type or too large).';
            }
        }

        // Auto-increment LocalStorage version so dismissed banners reappear
        $ls_ver = 12;
        try {
            $row = $db->row("SELECT `value` FROM `site_settings` WHERE `key` = 'banner_ls_version' LIMIT 1");
            $ls_ver = (int)(($row['value'] ?? 12) ?: 12);
        } catch (\Throwable $e) {}
        $ls_ver++;

        // Upsert all values
        foreach ($text_keys as $key) {
            if (isset($uploaded[$key])) {
                $value = $uploaded[$key];
            } elseif (isset($_POST[$key])) {
                $value = trim((string)$_POST[$key]);
            } else {
                continue;
            }

            // Sanitize specific keys
            if ($key === 'banner_type' && !in_array($value, ['progames', 'sale', 'off'], true)) {
                $value = 'progames';
            }
            if ($key === 'banner_sale_ends_at' && $value !== '') {
                $ts = strtotime($value);
                if ($ts === false) { $errors[] = 'Invalid countdown end date format (use YYYY-MM-DD HH:MM:SS).'; continue; }
                $value = date('Y-m-d H:i:s', $ts);
            }
            if (str_ends_with($key, '_opacity') && $value !== '') {
                $value = (string)max(0.0, min(1.0, (float)$value));
            }
            if (preg_match('/^banner_sale_bg_(left|right)_pos_[xy]_(desktop|mobile)$/', $key) && $value !== '') {
                $value = (string)max(0, min(100, (int)$value));
            }

            try {
                $db->run(
                    "INSERT INTO `site_settings` (`key`, `value`) VALUES (?, ?) ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)",
                    $key,
                    $value
                );
            } catch (\Throwable $e) {
                $errors[] = 'DB error saving key "' . htmlspecialchars($key) . '".';
            }
        }

        // Save LS version
        try {
            $db->run(
                "INSERT INTO `site_settings` (`key`, `value`) VALUES ('banner_ls_version', ?) ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)",
                (string)$ls_ver
            );
        } catch (\Throwable $e) {}

        if (!empty($errors)) {
            echo json_encode(['status' => 'error', 'message' => implode(' | ', $errors)]);
            return;
        }

        echo json_encode([
            'status'     => 'ok',
            'message'    => 'Banner settings saved.',
            'ls_version' => $ls_ver,
        ]);
    }


    // ── SELLER DIGITAL GOODS MERGE FIX ───────────────────────────────────────
    private function dg_slug_from_title(string $title): string
    {
        $title = trim($title);
        if ($title === '') return 'digital-good';
        if (function_exists('slugify')) {
            $slug = slugify($title);
        } else {
            if (function_exists('iconv')) {
                $converted = @iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $title);
                if ($converted !== false) $title = $converted;
            }
            $slug = strtolower($title);
            $slug = preg_replace('/[^a-z0-9]+/i', '-', $slug);
            $slug = trim((string)$slug, '-');
        }
        return ($slug !== '' && $slug !== 'n-a') ? $slug : 'digital-good';
    }

    private function dg_unique_listing_slug(string $title, int $ignoreId = 0, string $preferredSlug = ''): string
    {
        global $db;
        $preferredSlug = trim($preferredSlug);
        $base = $this->dg_slug_from_title($preferredSlug !== '' ? $preferredSlug : $title);
        $slug = $base;
        // If the base slug is already used, keep the first listing clean and
        // number duplicates as -2, -3, -4 ... (never append database IDs).
        $i = 2;
        while (true) {
            $row = $db->row(
                "SELECT id FROM digital_goods WHERE slug = ? AND id <> ? LIMIT 1",
                $slug,
                $ignoreId
            );
            if (empty($row)) return $slug;
            $slug = $base . '-' . $i;
            $i++;
        }
    }

    private function dg_duplicate_listing_row(array $source, int $sellerId = 0): int
    {
        global $db;

        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS brand_icon VARCHAR(255) NULL DEFAULT NULL COMMENT 'Relative path to brand icon image' AFTER brand"); } catch (\Throwable $e) {}
        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS safety_information TEXT NULL DEFAULT NULL COMMENT 'Public safety / risk notes for buyers' AFTER delivery_instructions"); } catch (\Throwable $e) {}

        $title = trim((string)($source['title'] ?? 'Digital Good'));
        $slug = $this->dg_unique_listing_slug($title, 0, (string)($source['slug'] ?? ''));
        $copySellerId = $sellerId > 0 ? $sellerId : (int)($source['seller_id'] ?? 0);

        $db->run(
            "INSERT INTO digital_goods (seller_id,category_id,slug,title,brand,brand_icon,description,delivery_instructions,safety_information,images,price_type,price,currency,delivery_type,region,validity_days,stock,min_purchase_qty,max_purchase_qty,active,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)",
            $copySellerId,
            (int)($source['category_id'] ?? 0),
            $slug,
            esc($title),
            esc($source['brand'] ?? ''),
            esc($source['brand_icon'] ?? ''),
            $source['description'] ?? '',
            $source['delivery_instructions'] ?? '',
            $source['safety_information'] ?? ($source['safety_info'] ?? ''),
            $source['images'] ?? '[]',
            $source['price_type'] ?? 'fixed',
            (int)($source['price'] ?? 0),
            $source['currency'] ?? 'EUR',
            esc($source['delivery_type'] ?? 'manual'),
            esc($source['region'] ?? ''),
            ($source['validity_days'] !== null && $source['validity_days'] !== '') ? (int)$source['validity_days'] : null,
            max(0, (int)($source['stock'] ?? 0)),
            max(1, (int)($source['min_purchase_qty'] ?? 1)),
            !empty($source['max_purchase_qty']) ? (int)$source['max_purchase_qty'] : null,
            0
        );

        return (int)$db->lastInsertId();
    }

    /**
     * Public live search used by the Digital Goods hub.
     * Returns every matching, purchasable listing instead of category cards only.
     */
    public function dg_search_listings()
    {
        global $db;

        header('Content-Type: application/json; charset=utf-8');

        $query = trim((string)($_POST['q'] ?? ''));
        if (function_exists('mb_substr')) {
            $query = mb_substr($query, 0, 100, 'UTF-8');
        } else {
            $query = substr($query, 0, 100);
        }

        // An empty query is not an error: the hub opens the dropdown on focus and
        // expects the best-selling listings as suggestions.
        $isSuggestions = ($query === '' || strlen($query) < 2);

        $like = '%' . $query . '%';

        try {
            if ($isSuggestions) {
                $rows = $db->run(
                    "SELECT dg.id, dg.slug, dg.title, dg.brand, dg.brand_icon,
                            dg.description, dg.images, dg.price, dg.currency,
                            dg.stock, dg.sold_count,
                            dgc.name AS category_name, dgc.slug AS category_slug
                     FROM digital_goods dg
                     LEFT JOIN digital_good_categories dgc ON dgc.id = dg.category_id
                     WHERE dg.active = 1
                       AND dg.stock > 0
                     ORDER BY dg.sold_count DESC, dg.sort_order ASC, dg.id DESC
                     LIMIT 8"
                ) ?: [];
            } else {
                $rows = $db->run(
                "SELECT dg.id, dg.slug, dg.title, dg.brand, dg.brand_icon,
                        dg.description, dg.images, dg.price, dg.currency,
                        dg.stock, dg.sold_count,
                        dgc.name AS category_name, dgc.slug AS category_slug
                 FROM digital_goods dg
                 LEFT JOIN digital_good_categories dgc ON dgc.id = dg.category_id
                 WHERE dg.active = 1
                   AND dg.stock > 0
                   AND (
                       dg.title LIKE ?
                       OR dg.brand LIKE ?
                       OR dg.slug LIKE ?
                       OR dg.description LIKE ?
                       OR dgc.name LIKE ?
                       OR dgc.slug LIKE ?
                   )
                 ORDER BY
                   CASE
                       WHEN dg.title LIKE ? THEN 0
                       WHEN dg.brand LIKE ? THEN 1
                       ELSE 2
                   END,
                   dg.sold_count DESC,
                   dg.sort_order ASC,
                   dg.id DESC
                 LIMIT 200",
                $like,
                $like,
                $like,
                $like,
                $like,
                $like,
                $query . '%',
                $query . '%'
                ) ?: [];
            }

            $baseUrl = defined('BASE_URL') ? rtrim((string)BASE_URL, '/') : '';
            $assetUrl = defined('ASSET_URL') ? rtrim((string)ASSET_URL, '/') : '';
            $normalizeAsset = static function ($path) use ($assetUrl): string {
                $path = trim((string)($path ?? ''));
                if ($path === '') return '';
                if (preg_match('#^(?:https?:)?//#i', $path) || str_starts_with($path, 'data:')) return $path;
                $path = preg_replace('#^/public/assets#', '', $path);
                $path = preg_replace('#/public/assets/#', '/', $path);
                return $assetUrl . '/' . ltrim((string)$path, '/');
            };

            $items = [];
            foreach ($rows as $row) {
                $slug = trim((string)($row['slug'] ?? ''));
                if ($slug === '') continue;

                $candidates = [];
                $images = json_decode((string)($row['images'] ?? '[]'), true);
                if (is_array($images)) {
                    foreach ($images as $image) {
                        $imageUrl = $normalizeAsset($image);
                        if ($imageUrl !== '' && !in_array($imageUrl, $candidates, true)) {
                            $candidates[] = $imageUrl;
                        }
                    }
                }

                $brandIcon = $normalizeAsset($row['brand_icon'] ?? '');
                if ($brandIcon !== '' && !in_array($brandIcon, $candidates, true)) {
                    $candidates[] = $brandIcon;
                }

                $brand = trim((string)($row['brand'] ?? ''));
                $title = trim((string)($row['title'] ?? 'Digital Good'));
                $currency = strtoupper(trim((string)($row['currency'] ?? 'EUR')));

                $items[] = [
                    'id' => (int)($row['id'] ?? 0),
                    'title' => $title,
                    'brand' => $brand,
                    'category' => trim((string)($row['category_name'] ?? 'Digital Goods')),
                    'stock' => max(0, (int)($row['stock'] ?? 0)),
                    'price' => number_format(max(0, (int)($row['price'] ?? 0)) / 100, 2, '.', ''),
                    'currency' => $currency,
                    'url' => $baseUrl . '/digital-good/' . rawurlencode($slug),
                    'icon' => $candidates[0] ?? '',
                    'icon_candidates' => $candidates,
                    'brand_initial' => strtoupper(substr($brand !== '' ? $brand : $title, 0, 1)),
                ];
            }

            echo json_encode(['success' => true, 'suggestions' => $isSuggestions, 'items' => $items], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        } catch (\Throwable $e) {
            @error_log('[Digital Goods Search] ' . $e->getMessage());
            echo json_encode(['success' => false, 'items' => []]);
        }
    }


    public function client_dg_checkout()
    {
        global $db;

        $respond = static function (array $payload): void {
            echo json_encode($payload);
        };

        // Allow guest checkout exactly like boosting / E-Girl orders.
        // The checkout page can attach the invoice to the client after login.
        $clientId = ($this->is_client && defined('CLIENT_ID') && (int)CLIENT_ID > 0) ? (int)CLIENT_ID : 0;

        $itemId = (int)($_POST['item_id'] ?? $_POST['digital_good_id'] ?? $_POST['listing_id'] ?? 0);
        $quantity = max(1, (int)($_POST['quantity'] ?? $_POST['qty'] ?? 1));

        if ($itemId <= 0) {
            $respond([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Digital good not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $listing = function_exists('dg_get_listing') ? dg_get_listing($itemId) : db_get_row('digital_goods', ['id' => $itemId], 1);
        if (!$listing || !is_array($listing) || (int)($listing['active'] ?? 0) !== 1) {
            $respond([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'This digital good is no longer available.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $stock = max(0, (int)($listing['stock'] ?? 0));
        $minQty = max(1, (int)($listing['min_purchase_qty'] ?? 1));
        $maxQtyRaw = $listing['max_purchase_qty'] ?? null;
        $maxQty = $maxQtyRaw !== null && $maxQtyRaw !== '' ? max($minQty, (int)$maxQtyRaw) : max($minQty, $stock);
        $quantity = max($minQty, min($quantity, $maxQty));

        if ($stock <= 0 || $quantity > $stock) {
            $respond([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Out of stock', 'message' => 'This digital good is currently out of stock.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $unitEur = max(0, (int)($listing['price'] ?? 0));
        if ($unitEur <= 0) {
            $respond([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'This listing has an invalid price.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $priceEur = $unitEur * $quantity;
        $currency = strtoupper((string)($_SESSION['currency'] ?? ($listing['currency'] ?? 'EUR')));
        if (!in_array($currency, ['EUR', 'USD'], true)) {
            $currency = 'EUR';
        }

        $totalPrice = $priceEur;
        if ($currency === 'USD') {
            $rate = function_exists('get_exchange_rate') ? (float)get_exchange_rate() : 1.0;
            if ($rate <= 0) $rate = 1.0;
            $totalPrice = (int)round($priceEur * $rate);
        }

        $brand = trim((string)($listing['brand'] ?? ''));
        $title = trim((string)($listing['title'] ?? 'Digital Good'));
        $descriptionTitle = trim(($brand !== '' ? $brand . ' · ' : '') . $title);
        if ($quantity > 1) {
            $descriptionTitle .= ' x' . $quantity;
        }

        $uuid = Uuid::uuid4()->toString();

        try {
            $invoiceId = (int)db_add_row('invoices', [
                'uuid' => $uuid,
                'order_id' => $itemId,
                'order_type' => 'digital_good',
                'price' => $totalPrice,
                'price_eur' => $priceEur,
                'total_price' => $totalPrice,
                'currency' => $currency,
                'status' => 'UNPAID',
                'description' => $descriptionTitle,
                'client_id' => $clientId,
            ]);
        } catch (\Throwable $e) {
            $invoiceId = 0;
        }

        if ($invoiceId <= 0) {
            $respond([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Could not create checkout invoice.'],
                'playSound' => 'error',
            ]);
            return;
        }

        // Keep an unpaid purchase row for dashboards, but payment completion is still
        // idempotently handled by lb_dg_mark_invoice_paid / dg_mark_invoice_paid.
        try {
            $existing = $db->row("SELECT id FROM digital_good_purchases WHERE invoice_id = ? LIMIT 1", $invoiceId);
            if (empty($existing['id'])) {
                db_add_row('digital_good_purchases', [
                    'item_id' => $itemId,
                    'seller_id' => (int)($listing['seller_id'] ?? 0),
                    'client_id' => $clientId,
                    'invoice_id' => $invoiceId,
                    'quantity' => $quantity,
                    'unit_price' => $unitEur,
                    'price' => $priceEur,
                    'currency' => $currency,
                    'region' => (string)($listing['region'] ?? ''),
                    'customer_note' => trim((string)($_POST['customer_note'] ?? '')),
                    'status' => 'UNPAID',
                    'created_at' => date('Y-m-d H:i:s'),
                    'updated_at' => date('Y-m-d H:i:s'),
                ]);
            }
        } catch (\Throwable $e) {
            // Non-fatal: the paid invoice processor can still create/sync the purchase.
        }

        $respond([
            'success' => true,
            'redirectUrl' => BASE_URL . '/checkout/' . $uuid,
            'sendToast' => ['type' => 'success', 'title' => 'Checkout created', 'message' => 'Redirecting to checkout.'],
        ]);
    }

    public function seller_dg_create_listing()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        if (empty($this->seller_data['can_list_digital_goods'])) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'You are not permitted to list digital goods. Contact an admin.']]); return; }
        $validator  = new \Rakit\Validation\Validator();
        $validation = $validator->make($_POST, ['title'=>'required','description'=>'required','category_id'=>'required']);
        $validation->validate();
        if ($validation->fails()) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please fill in all required fields.'],'validationErrors'=>$validation->errors()->firstOfAll()]); return; }
        $priceRaw   = str_replace(',', '.', (string)($_POST['price_display'] ?? $_POST['price'] ?? '0'));
        $priceCents = (int)round((float)$priceRaw * 100);
        if ($priceCents <= 0) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please enter a valid price.']]); return; }
        $images = []; // Product images removed — brand icon + gradient used instead
        $title  = trim((string)($_POST['title'] ?? ''));
        $slug   = $this->dg_unique_listing_slug($title, 0, (string)($_POST['slug'] ?? ''));
        $stock  = max(1, (int)($_POST['stock'] ?? 1));
        $minQty = max(1, (int)($_POST['min_purchase_qty'] ?? 1));
        $maxQty = !empty($_POST['max_purchase_qty']) ? max($minQty, (int)$_POST['max_purchase_qty']) : null;
        $active = in_array((string)($_POST['active'] ?? '0'), ['1','true','on'], true) ? 1 : 0;
        global $db;
        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS brand_icon VARCHAR(255) NULL DEFAULT NULL COMMENT 'Relative path to brand icon image' AFTER brand"); } catch (\Throwable $e) {}
        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS safety_information TEXT NULL DEFAULT NULL COMMENT 'Public safety / risk notes for buyers' AFTER delivery_instructions"); } catch (\Throwable $e) {}
        $brandIcon = esc(trim((string)($_POST['brand_icon'] ?? '')));
        $safetyInformation = trim((string)($_POST['safety_information'] ?? ($_POST['safety_info'] ?? '')));
        $db->run(
            "INSERT INTO digital_goods (seller_id,category_id,slug,title,brand,brand_icon,description,delivery_instructions,safety_information,images,price_type,price,currency,delivery_type,region,validity_days,stock,min_purchase_qty,max_purchase_qty,active,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)",
            (int)$this->seller_data['id'],(int)$_POST['category_id'],$slug,esc($title),esc($_POST['brand']??''),
            $brandIcon, $_POST['description']??'', $_POST['delivery_instructions']??'', $safetyInformation, json_encode($images),'fixed',
            $priceCents,'EUR',esc($_POST['delivery_type']??'manual'),esc($_POST['region']??''),
            !empty($_POST['validity_days'])?(int)$_POST['validity_days']:null,
            $stock,$minQty,$maxQty,$active
        );
        $id = (int)$db->lastInsertId();
        echo $id
            ? json_encode(['success'=>true,'sendToast'=>['type'=>'success','title'=>'Saved','message'=>'Listing created.'],'playSound'=>'success','redirectUrl'=>BASE_URL.'/seller-area/digital-goods/listings'])
            : json_encode(['sendToast'=>['type'=>'danger','message'=>'Failed to create listing.']]);
    }

    // ── SELLER — Listing bearbeiten ───────────────────────────────────────────

    public function seller_dg_update_listing()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        if (empty($this->seller_data['can_list_digital_goods'])) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'You are not permitted to list digital goods.']]); return; }
        $id = (int)($_POST['id'] ?? 0);
        global $db;
        $rows = $db->run("SELECT * FROM digital_goods WHERE id=? AND seller_id=? LIMIT 1", $id, (int)$this->seller_data['id']);
        $listing = $rows[0] ?? null;
        if (!$listing) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Listing not found.']]); return; }
        $priceRaw   = str_replace(',', '.', (string)($_POST['price_display'] ?? $_POST['price'] ?? '0'));
        $priceCents = (int)round((float)$priceRaw * 100);
        if ($priceCents <= 0) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please enter a valid price.']]); return; }
        $existingImages = []; // Product images removed — brand icon + gradient used instead
        $stock  = max(1, (int)($_POST['stock'] ?? $listing['stock']));
        $minQty = max(1, (int)($_POST['min_purchase_qty'] ?? $listing['min_purchase_qty']));
        $maxQty = !empty($_POST['max_purchase_qty']) ? max($minQty, (int)$_POST['max_purchase_qty']) : null;
        $active = in_array((string)($_POST['active'] ?? '0'), ['1','true','on'], true) ? 1 : 0;
        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS brand_icon VARCHAR(255) NULL DEFAULT NULL COMMENT 'Relative path to brand icon image' AFTER brand"); } catch (\Throwable $e) {}
        try { $db->run("ALTER TABLE digital_goods ADD COLUMN IF NOT EXISTS safety_information TEXT NULL DEFAULT NULL COMMENT 'Public safety / risk notes for buyers' AFTER delivery_instructions"); } catch (\Throwable $e) {}
        $brandIconUpd = esc(trim((string)($_POST['brand_icon'] ?? $listing['brand_icon'] ?? '')));
        $safetyInformationUpd = trim((string)($_POST['safety_information'] ?? ($_POST['safety_info'] ?? ($listing['safety_information'] ?? ''))));
        $titleUpd = trim((string)($_POST['title'] ?? $listing['title'] ?? ''));
        $slugUpd  = $this->dg_unique_listing_slug($titleUpd, $id, (string)($_POST['slug'] ?? ''));
        $db->run(
            "UPDATE digital_goods SET category_id=?,slug=?,title=?,brand=?,brand_icon=?,description=?,delivery_instructions=?,safety_information=?,images=?,price=?,delivery_type=?,region=?,validity_days=?,stock=?,min_purchase_qty=?,max_purchase_qty=?,active=? WHERE id=? AND seller_id=?",
            (int)($_POST['category_id']??$listing['category_id']),$slugUpd,esc($titleUpd),esc($_POST['brand']??$listing['brand']),
            $brandIconUpd, $_POST['description']??$listing['description'],$_POST['delivery_instructions']??$listing['delivery_instructions'],$safetyInformationUpd,
            json_encode($existingImages),$priceCents,esc($_POST['delivery_type']??$listing['delivery_type']),
            esc($_POST['region']??$listing['region']),!empty($_POST['validity_days'])?(int)$_POST['validity_days']:null,
            $stock,$minQty,$maxQty,$active,$id,(int)$this->seller_data['id']
        );
        echo json_encode(['success'=>true,'sendToast'=>['type'=>'success','title'=>'Saved','message'=>'Listing updated.'],'playSound'=>'success']);
    }

    public function seller_dg_duplicate_listing()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false,'message'=>'Unauthorized']); return; }
        if (empty($this->seller_data['can_list_digital_goods'])) { echo json_encode(['success'=>false,'message'=>'You are not permitted to list digital goods.']); return; }
        $id = (int)($_POST['id'] ?? 0);
        if ($id <= 0) { echo json_encode(['success'=>false,'message'=>'Invalid listing.']); return; }
        global $db;
        $rows = $db->run("SELECT * FROM digital_goods WHERE id=? AND seller_id=? LIMIT 1", $id, (int)$this->seller_data['id']);
        $source = $rows[0] ?? null;
        if (!$source) { echo json_encode(['success'=>false,'message'=>'Listing not found.']); return; }
        $newId = $this->dg_duplicate_listing_row($source, (int)$this->seller_data['id']);
        echo $newId
            ? json_encode(['success'=>true,'id'=>$newId,'sendToast'=>['type'=>'success','title'=>'Duplicated','message'=>'Offer duplicated. The copy is inactive until you edit or activate it.'],'redirectUrl'=>BASE_URL.'/seller-area/digital-goods/listings'])
            : json_encode(['success'=>false,'message'=>'Could not duplicate offer.']);
    }

    // ── SELLER — Listing löschen ──────────────────────────────────────────────

    public function seller_dg_delete_listing()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false,'message'=>'Unauthorized']); return; }
        $id = (int)($_POST['id'] ?? 0);
        global $db;
        $rows = $db->run("SELECT id FROM digital_goods WHERE id=? AND seller_id=? LIMIT 1", $id, (int)$this->seller_data['id']);
        if (empty($rows)) { echo json_encode(['success'=>false,'message'=>'Not found']); return; }
        $db->run("DELETE FROM digital_goods WHERE id=? AND seller_id=?", $id, (int)$this->seller_data['id']);
        echo json_encode(['success'=>true,'sendToast'=>['type'=>'success','message'=>'Listing deleted.'],'removeRow'=>true]);
    }

    // ── SELLER — Listing aktiv/inaktiv ────────────────────────────────────────

    public function seller_dg_toggle_listing()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false]); return; }
        $id  = (int)($_POST['id'] ?? 0);
        $val = in_array((string)($_POST['active']??''), ['1','true'], true) ? 1 : 0;
        global $db;
        $db->run("UPDATE digital_goods SET active=? WHERE id=? AND seller_id=?", $val, $id, (int)$this->seller_data['id']);
        echo json_encode(['success'=>true]);
    }


    /**
     * Auto-complete delivered digital-good purchases after 24 hours.
     * Returns true when the purchase is already/completed or was completed now.
     */
    private function dg_auto_complete_overdue_purchase(int $purchaseId, ?int $clientId = null): bool
    {
        if ($purchaseId <= 0) {
            return false;
        }

        global $db;

        $params = [$purchaseId];
        $clientSql = '';
        if ($clientId !== null && $clientId > 0) {
            $clientSql = ' AND client_id = ?';
            $params[] = $clientId;
        }

        $rows = $db->run(
            "SELECT id, status, delivered_at, completed_at
             FROM digital_good_purchases
             WHERE id = ?" . $clientSql . "
             LIMIT 1",
            ...$params
        ) ?: [];

        if (empty($rows)) {
            return false;
        }

        $row = $rows[0];
        $status = strtoupper(trim((string)($row['status'] ?? '')));

        if ($status === 'COMPLETED') {
            return true;
        }

        if ($status !== 'DELIVERED') {
            return false;
        }

        $deliveredAt = trim((string)($row['delivered_at'] ?? ''));
        if ($deliveredAt === '' || $deliveredAt === '0000-00-00 00:00:00') {
            return false;
        }

        $deliveredTs = strtotime($deliveredAt);
        if ($deliveredTs === false || $deliveredTs > (time() - 86400)) {
            return false;
        }

        $now = date('Y-m-d H:i:s');
        $db->run(
            "UPDATE digital_good_purchases
             SET status = 'COMPLETED', completed_at = COALESCE(completed_at, ?)
             WHERE id = ?" . $clientSql . "
               AND status = 'DELIVERED'
               AND delivered_at IS NOT NULL
               AND delivered_at <> '0000-00-00 00:00:00'
               AND delivered_at <= DATE_SUB(NOW(), INTERVAL 24 HOUR)",
            ...array_merge([$now, $purchaseId], $clientId !== null && $clientId > 0 ? [$clientId] : [])
        );

        $check = $db->run(
            "SELECT status FROM digital_good_purchases WHERE id = ?" . $clientSql . " LIMIT 1",
            ...$params
        ) ?: [];

        $freshStatus = strtoupper(trim((string)($check[0]['status'] ?? '')));
        if ($freshStatus === 'COMPLETED') {
            try {
                dg_log($purchaseId, 'system', 0, 'auto_completed_after_24h');
                dg_chat_append($purchaseId, 'system', 0, 'System', '✅ Delivery automatically confirmed after 24 hours.');
            } catch (\Throwable $e) {
                error_log('dg_auto_complete_overdue_purchase side effect failed: ' . $e->getMessage());
            }
            return true;
        }

        return false;
    }

    // ── SELLER — Als geliefert markieren ─────────────────────────────────────

    public function seller_dg_mark_delivered()
    {
        $__dg_ob_level = ob_get_level();
        ob_start();

        $respond = static function (array $payload) use ($__dg_ob_level): void {
            while (ob_get_level() > $__dg_ob_level) {
                @ob_end_clean();
            }

            if (!headers_sent()) {
                header('Content-Type: application/json; charset=utf-8');
                http_response_code(200);
            }

            echo json_encode($payload);
        };

        try {
            if (!$this->is_seller) {
                $respond(['success' => false, 'message' => 'Unauthorized']);
                return;
            }

            $purchaseId   = (int)($_POST['purchase_id'] ?? 0);
            $deliveryNote = trim((string)($_POST['delivery_note'] ?? ''));

            if ($purchaseId <= 0) {
                $respond(['success' => false, 'message' => 'Invalid order.']);
                return;
            }

            $sellerId = (int)($this->seller_data['id'] ?? 0);
            $purchase = dg_get_purchase($purchaseId);

            if (!$purchase || (int)($purchase['seller_id'] ?? 0) !== $sellerId) {
                $respond(['success' => false, 'message' => 'Order not found.']);
                return;
            }

            $currentStatus = strtoupper(trim((string)($purchase['status'] ?? '')));

            // Idempotent: if a previous request already marked it delivered, return success.
            // This prevents the UI from showing an error when the DB update succeeded but the
            // browser retried / parsed a stale response.
            if (in_array($currentStatus, ['DELIVERED', 'COMPLETED'], true)) {
                $respond([
                    'success' => true,
                    'alreadyDelivered' => true,
                    'sendToast' => [
                        'type' => 'success',
                        'title' => 'Delivered',
                        'message' => 'Order #' . $purchaseId . ' is already marked as delivered.',
                    ],
                    'playSound' => 'success',
                    'refreshPage' => true,
                    'refreshRow' => true,
                ]);
                return;
            }

            if (!in_array($currentStatus, ['PAID', 'PROCESSING'], true)) {
                $respond(['success' => false, 'message' => 'Cannot deliver in status: ' . ($currentStatus ?: 'UNKNOWN')]);
                return;
            }

            global $db;
            $now = date('Y-m-d H:i:s');

            $db->run(
                "UPDATE digital_good_purchases
                 SET status = 'DELIVERED',
                     delivery_note = ?,
                     delivered_at = ?,
                     updated_at = COALESCE(updated_at, ?)
                 WHERE id = ?
                   AND seller_id = ?
                   AND status IN ('PAID', 'PROCESSING')",
                $deliveryNote,
                $now,
                $now,
                $purchaseId,
                $sellerId
            );

            // Do not use $db->cell() here. In some installs it can return false even when
            // the UPDATE succeeded, which made the seller UI show "Could not mark delivered"
            // although a refresh showed the order as delivered.
            $checkRows = $db->run(
                "SELECT status, delivered_at
                 FROM digital_good_purchases
                 WHERE id = ? AND seller_id = ?
                 LIMIT 1",
                $purchaseId,
                $sellerId
            ) ?: [];

            $freshStatus = strtoupper(trim((string)($checkRows[0]['status'] ?? '')));

            if (!in_array($freshStatus, ['DELIVERED', 'COMPLETED'], true)) {
                $respond(['success' => false, 'message' => 'Could not mark delivered.']);
                return;
            }

            try {
                dg_log($purchaseId, 'seller', $sellerId, 'marked_delivered');
                $chatMsg = "Your order has been delivered!\n\nDelivery details:\n" . ($deliveryNote !== '' ? $deliveryNote : '(See delivery note above)');
                dg_chat_append($purchaseId, 'seller', $sellerId, $this->seller_data['username'] ?? 'Seller', $chatMsg);
            } catch (\Throwable $e) {
                error_log('seller_dg_mark_delivered side effect failed: ' . $e->getMessage());
            }

            try {
                $mailPurchase = dg_get_purchase($purchaseId) ?: $purchase;
                if (is_array($mailPurchase)) {
                    $mailPurchase['delivery_note'] = $deliveryNote;
                    $ctx = $this->dg_purchase_email_context($mailPurchase);
                    $this->dg_queue_email_notification('digital_good_delivered', 'client', (int)$ctx['client_id'], [
                        'username' => $ctx['buyer'],
                        'purchase_id' => (string)$ctx['purchase_id'],
                        'item_title' => $ctx['item_title'],
                        'item_cover' => $ctx['item_cover'],
                        'order_url' => $ctx['client_url'],
                        'price' => $ctx['price'],
                        'quantity' => $ctx['quantity'],
                        'seller' => $ctx['seller'],
                        'delivery_note' => $deliveryNote,
                    ]);
                }
            } catch (\Throwable $e) {
                error_log('seller_dg_mark_delivered email queue failed: ' . $e->getMessage());
            }

            $this->dg_trigger_notification_sender();

            $respond([
                'success' => true,
                'status' => $freshStatus,
                'delivered_at' => (string)($checkRows[0]['delivered_at'] ?? $now),
                'sendToast' => [
                    'type' => 'success',
                    'title' => 'Delivered',
                    'message' => 'Order #' . $purchaseId . ' marked as delivered.',
                ],
                'playSound' => 'success',
                'refreshPage' => true,
                'refreshRow' => true,
            ]);
            return;

        } catch (\Throwable $e) {
            error_log('seller_dg_mark_delivered failed: ' . $e->getMessage());
            $respond(['success' => false, 'message' => 'Server error. Please try again.']);
            return;
        }
    }

    // ── SELLER — Order stornieren ─────────────────────────────────────────────

    public function seller_dg_cancel_order()
    {
        if (!$this->is_seller && !$this->is_admin) { echo json_encode(['success'=>false,'message'=>'Unauthorized']); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        $purchase   = dg_get_purchase($purchaseId);
        if (!$purchase) { echo json_encode(['success'=>false,'message'=>'Order not found']); return; }
        if ($this->is_seller && !$this->is_admin && (int)$purchase['seller_id'] !== (int)$this->seller_data['id']) { echo json_encode(['success'=>false,'message'=>'Unauthorized']); return; }
        if (!in_array($purchase['status'], ['UNPAID','PAID','PROCESSING'], true)) { echo json_encode(['success'=>false,'message'=>'Cannot cancel in status: '.$purchase['status']]); return; }
        global $db;
        $db->run("UPDATE digital_good_purchases SET status='CANCELLED',cancelled_at=? WHERE id=?", date('Y-m-d H:i:s'), $purchaseId);
        $db->run("UPDATE digital_goods SET stock=stock+?,sold_count=GREATEST(0,sold_count-?) WHERE id=?", (int)$purchase['quantity'], (int)$purchase['quantity'], (int)$purchase['item_id']);
        if (!empty($purchase['seller_id']) && function_exists('sync_seller_stats')) sync_seller_stats((int)$purchase['seller_id']);
        $actorType = $this->is_admin ? 'admin' : 'seller';
        $actorId   = $this->is_admin ? (defined('ADMIN_ID')?(int)ADMIN_ID:0) : (int)$this->seller_data['id'];
        dg_log($purchaseId, $actorType, $actorId, 'purchase_cancelled');
        dg_chat_append($purchaseId, 'system', 0, 'System', '❌ This order has been cancelled.');
        echo json_encode(['success'=>true,'sendToast'=>['type'=>'info','title'=>'Cancelled','message'=>'Order #'.$purchaseId.' cancelled.'],'refreshRow'=>true]);
    }

    // ── SELLER — Unread-Badge ─────────────────────────────────────────────────

    public function seller_dg_unread_count()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false,'unread'=>0]); return; }
        $sellerId = (int)$this->seller_data['id'];
        global $db;
        $purchases = $db->run("SELECT id FROM digital_good_purchases WHERE seller_id=? AND status NOT IN ('COMPLETED','CANCELLED','REFUNDED') ORDER BY created_at DESC LIMIT 200", $sellerId) ?: [];
        $unread = 0;
        foreach ($purchases as $p) {
            $path = dg_chat_path((int)$p['id']);
            if (!file_exists($path)) continue;
            $data = json_decode(@file_get_contents($path) ?: '', true);
            if (!is_array($data) || empty($data['messages'])) continue;
            foreach ($data['messages'] as $m) {
                if (!is_array($m) || !empty($m['deleted'])) continue;
                if (($m['sender']??$m['type']??'') === 'client' && (int)($m['seen_by_seller']??0) === 0) { $unread++; break; }
            }
        }
        echo json_encode(['success'=>true,'unread'=>$unread,'digital_goods'=>$unread]);
    }

    // ── SELLER — Chat laden ───────────────────────────────────────────────────

    public function seller_dg_chat_load()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false,'messages',[]]); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        global $db;
        $rows = $db->run("SELECT id FROM digital_good_purchases WHERE id=? AND seller_id=? LIMIT 1", $purchaseId, (int)$this->seller_data['id']);
        if (empty($rows)) { echo json_encode(['success'=>false,'messages',[]]); return; }
        echo json_encode(['success'=>true,'messages'=>$this->_dg_chat_read($purchaseId, 'seller')]);
    }

    // ── SELLER — Nachricht senden ─────────────────────────────────────────────

    public function seller_dg_chat_send()
    {
        if (!$this->is_seller) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        $message    = trim(esc($_POST['message'] ?? ''));
        global $db;
        $rows = $db->run("SELECT id FROM digital_good_purchases WHERE id=? AND seller_id=? LIMIT 1", $purchaseId, (int)$this->seller_data['id']);
        if (empty($rows)) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return; }
        $imageUrl = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $imageUrl = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($imageUrl === false) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }
        }
        if ($message === '' && !$imageUrl) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $res = dg_chat_append($purchaseId, 'seller', (int)$this->seller_data['id'], $this->seller_data['username']??'Seller', $message, $imageUrl);
        if (!empty($res['success'])) $this->dg_chat_emit($purchaseId, 'seller_message');
        echo json_encode($res['success'] ? ['success'=>true,'resetForm'=>true,'reFocus'=>true] : ['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

    public function admin_dg_chat_load()
    {
        if (!$this->is_admin) { echo json_encode(['success'=>false,'messages'=>[]]); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        $purchase = db_get_row('digital_good_purchases', ['id'=>$purchaseId], 1);
        if (empty($purchase)) { echo json_encode(['success'=>false,'messages'=>[]]); return; }
        echo json_encode(['success'=>true,'messages'=>$this->_dg_chat_read($purchaseId, 'admin')]);
    }

    public function admin_dg_chat_send()
    {
        if (!$this->is_admin) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Unauthorized.']]); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        if (empty(db_get_row('digital_good_purchases', ['id'=>$purchaseId], 1))) {
            echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return;
        }
        $message = trim(esc($_POST['message'] ?? ''));
        $imageUrl = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $imageUrl = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($imageUrl === false) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }
        }
        if ($message === '' && !$imageUrl) { echo json_encode(['sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $res = dg_chat_append($purchaseId, 'admin', (int)ADMIN_ID, ADMIN_DATA['username'] ?? 'Admin', $message, $imageUrl);
        if (!empty($res['success'])) $this->dg_chat_emit($purchaseId, 'admin_message');
        echo json_encode(!empty($res['success']) ? ['success'=>true,'resetForm'=>true,'messages'=>$this->_dg_chat_read($purchaseId, 'admin')] : ['sendToast'=>['type'=>'danger','message'=>$res['message']??'Error']]);
    }

