    public function seller_dg_chat_seen()
    {
        if (!$this->is_seller) { echo json_encode(['success'=>false]); return; }
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        global $db;
        $rows = $db->run("SELECT id FROM digital_good_purchases WHERE id=? AND seller_id=? LIMIT 1", $purchaseId, (int)$this->seller_data['id']);
