    // ── Shared Chat-Helper (Datei lesen / seen markieren) ─────────────────────

    /**
     * Digital Goods chat used to poll every 5s. Push updates over the same
     * realtime channel the item chat already uses, so a new order/message shows
     * up instantly for both sides.
     */
    private function dg_chat_emit(int $purchaseId, string $reason = 'update'): void
    {
        if (!empty($_SERVER['HTTP_X_REALTIME_INTERNAL'])) return;
        if (!function_exists('lb_realtime_emit')) return;

        lb_realtime_emit('dg_chat_update', [
            'purchase_id' => $purchaseId,
            'order_id' => 'dgpurch_' . $purchaseId,
            'reason' => $reason,
            'messages' => $this->_dg_chat_read($purchaseId, 'seller'),
        ], ['sellers', 'admins', 'clients']);
    }

    private function _dg_chat_read(int $purchaseId, string $viewer): array
    {
        $path = dg_chat_path($purchaseId);
        if (!file_exists($path)) return [];
        $data = json_decode(@file_get_contents($path) ?: '', true);
        if (!is_array($data) || empty($data['messages']) || !is_array($data['messages'])) return [];
        $messages = dg_chat_normalize($data['messages']);
        foreach ($messages as $k => $m) {
            if (!empty($m['deleted'])) unset($messages[$k]);
        }
        return $messages;
    }

    private function _dg_chat_mark_seen(int $purchaseId, string $viewer): void
    {
        $field = 'seen_by_' . $viewer;
        if (!in_array($viewer, ['seller', 'client', 'admin'], true)) return;
        $path = dg_chat_path($purchaseId);
        if (!file_exists($path)) return;
        $fp = @fopen($path, 'c+');
        if (!$fp) return;
        flock($fp, LOCK_EX);
        $data = json_decode(stream_get_contents($fp) ?: '', true);
        if (is_array($data) && !empty($data['messages']) && is_array($data['messages'])) {
            $changed = false;
            foreach ($data['messages'] as $i => $m) {
                if (!is_array($m)) continue;
                $sender = $m['sender'] ?? $m['type'] ?? '';
                if ($sender === $viewer) continue;
                if ((int)($m[$field] ?? 0) === 1) continue;
                $data['messages'][$i][$field] = 1;
                $changed = true;
            }
            if ($changed) {
                rewind($fp); ftruncate($fp, 0);
                fwrite($fp, json_encode($data, JSON_PRETTY_PRINT));
            }
        }
        flock($fp, LOCK_UN); fclose($fp);
    }

    // ── CLIENT — Chat laden / senden / gelesen ────────────────────────────────

    private function _dg_client_purchase(int $purchaseId): ?array
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) return null;
        global $db;
        $rows = $db->run("SELECT id, seller_id, status FROM digital_good_purchases WHERE id=? AND client_id=? LIMIT 1", $purchaseId, (int)CLIENT_ID);
        return empty($rows) ? null : $rows[0];
    }

    public function client_dg_chat_load()
    {
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        if (!$this->_dg_client_purchase($purchaseId)) { echo json_encode(['success'=>false,'messages'=>[]]); return; }
        if (!empty($_POST['mark_seen'])) $this->_dg_chat_mark_seen($purchaseId, 'client');
        echo json_encode(['success'=>true,'messages'=>$this->_dg_chat_read($purchaseId, 'client')]);
    }

    public function client_dg_chat_send()
    {
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        $purchase   = $this->_dg_client_purchase($purchaseId);
        if (!$purchase) { echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Order not found.']]); return; }
        $message = trim(esc($_POST['message'] ?? ''));
        $imageUrl = null;
        if (isset($_FILES['chat_image']) && !empty($_FILES['chat_image']['tmp_name'])) {
            $imageUrl = upload_image($_FILES['chat_image'], 'private/chat_images');
            if ($imageUrl === false) { echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Image upload failed.']]); return; }
        }
        if ($message === '' && !$imageUrl) { echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>'Please type a message or attach an image.']]); return; }
        $res = dg_chat_append($purchaseId, 'client', (int)CLIENT_ID, CLIENT_DATA['username'] ?? 'Client', $message, $imageUrl);
        if (empty($res['success'])) { echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','message'=>$res['message'] ?? 'Error']]); return; }
        $this->dg_chat_emit($purchaseId, 'client_message');
        echo json_encode(['success'=>true,'resetForm'=>true,'reFocus'=>true,'created_at'=>$res['created_at'] ?? null]);
    }

    public function client_dg_chat_seen()
    {
        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        if (!$this->_dg_client_purchase($purchaseId)) { echo json_encode(['success'=>false]); return; }
        $this->_dg_chat_mark_seen($purchaseId, 'client');
        echo json_encode(['success'=>true]);
    }

    // ── CLIENT — Lieferung bestätigen ─────────────────────────────────────────

    public function client_dg_confirm_delivery()
    {
        $__dg_ob_level = ob_get_level();
        ob_start();

        $respond = static function (array $payload) use ($__dg_ob_level): void {
            while (ob_get_level() > $__dg_ob_level) { @ob_end_clean(); }
            if (!headers_sent()) {
                header('Content-Type: application/json; charset=utf-8');
                http_response_code(200);
            }
            echo json_encode($payload);
        };

        try {
            $purchaseId = (int)($_POST['purchase_id'] ?? 0);
            if ($purchaseId <= 0) { $respond(['success'=>false,'message'=>'Invalid order.']); return; }

            $purchase = $this->_dg_client_purchase($purchaseId);
            if (!$purchase) { $respond(['success'=>false,'message'=>'Order not found.']); return; }

            $status = strtoupper(trim((string)($purchase['status'] ?? '')));

            // Idempotent: a retry after a successful confirm must not show an error.
            if ($status === 'COMPLETED') {
                $respond([
                    'success' => true,
                    'alreadyCompleted' => true,
                    'status' => 'COMPLETED',
                    'sendToast' => ['type'=>'success','title'=>'Done!','message'=>'Delivery already confirmed.'],
                ]);
                return;
            }

            if ($status !== 'DELIVERED') {
                $respond(['success'=>false,'message'=>'Cannot confirm in status: ' . ($status ?: 'UNKNOWN')]);
                return;
            }

            global $db;
            $now = date('Y-m-d H:i:s');

            $db->run(
                "UPDATE digital_good_purchases
                 SET status = 'COMPLETED',
                     completed_at = COALESCE(completed_at, ?),
                     updated_at = ?
                 WHERE id = ?
                   AND client_id = ?
                   AND status = 'DELIVERED'",
                $now,
                $now,
                $purchaseId,
                (int)CLIENT_ID
            );

            $check = $db->run(
                "SELECT status, completed_at FROM digital_good_purchases WHERE id = ? AND client_id = ? LIMIT 1",
                $purchaseId,
                (int)CLIENT_ID
            ) ?: [];

            $freshStatus = strtoupper(trim((string)($check[0]['status'] ?? '')));
            if ($freshStatus !== 'COMPLETED') {
                $respond(['success'=>false,'message'=>'Could not confirm delivery.']);
                return;
            }

            try {
                dg_log($purchaseId, 'client', (int)CLIENT_ID, 'delivery_confirmed');
                dg_chat_append($purchaseId, 'system', 0, 'System', '✅ The buyer confirmed the delivery. This order is now completed.');
                $this->dg_chat_emit($purchaseId, 'client_confirmed');
            } catch (\Throwable $e) {
                error_log('client_dg_confirm_delivery side effect failed: ' . $e->getMessage());
            }

            $respond([
                'success' => true,
                'status' => 'COMPLETED',
                'completed_at' => (string)($check[0]['completed_at'] ?? $now),
                'sendToast' => ['type'=>'success','title'=>'Done!','message'=>'Delivery confirmed. Thanks for your purchase!'],
                'playSound' => 'success',
            ]);
            return;

        } catch (\Throwable $e) {
            error_log('client_dg_confirm_delivery failed: ' . $e->getMessage());
            $respond(['success'=>false,'message'=>'Server error. Please try again.']);
            return;
        }
    }

    // ── CLIENT — Digital Good Review ──────────────────────────────────────────
    // Digital-good reviews live in seller_reviews as one review per completed purchase.

    public function client_dg_submit_review()
    {
        global $db;

        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Please log in first.']]);
            return;
        }

        $purchaseId = (int)($_POST['purchase_id'] ?? 0);
        $rating     = (int)($_POST['rating'] ?? 0);
        $comment    = trim(strip_tags((string)($_POST['comment'] ?? '')));

        if ($purchaseId <= 0 || $rating < 1 || $rating > 5) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Please select a rating between 1 and 5.']]);
            return;
        }

        $rows = $db->run(
            "SELECT id, item_id, seller_id, status FROM digital_good_purchases WHERE id = ? AND client_id = ? LIMIT 1",
            $purchaseId,
            (int)CLIENT_ID
        ) ?: [];
        $purchase = $rows[0] ?? null;

        if (!$purchase) {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Order not found.']]);
            return;
        }

        if (strtoupper(trim((string)($purchase['status'] ?? ''))) !== 'COMPLETED') {
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'You can review this order once it is completed.']]);
            return;
        }

        $existing = $db->run(
            "SELECT id FROM seller_reviews
             WHERE review_source = 'digital_good' AND source_purchase_id = ? AND client_id = ?
             LIMIT 1",
            $purchaseId,
            (int)CLIENT_ID
        ) ?: [];

        if (!empty($existing)) {
            echo json_encode([
                'success' => true,
                'alreadyReviewed' => true,
                'sendToast' => ['type'=>'warning','title'=>'Already reviewed','message'=>'You already reviewed this order.'],
            ]);
            return;
        }

        try {
            db_add_row('seller_reviews', [
                'purchase_id' => $purchaseId,
                'seller_id'   => (int)($purchase['seller_id'] ?? 0),
                'client_id'   => (int)CLIENT_ID,
                'review_source' => 'digital_good',
                'source_purchase_id' => $purchaseId,
                'digital_good_id' => (int)($purchase['item_id'] ?? 0),
                'rating'      => $rating,
                'comment'     => $comment,
                'approved'    => 1,
                'created_at'  => date('Y-m-d H:i:s'),
            ]);
        } catch (\Throwable $e) {
            error_log('client_dg_submit_review failed: ' . $e->getMessage());
            echo json_encode(['success'=>false,'sendToast'=>['type'=>'danger','title'=>'Error','message'=>'Could not submit review.']]);
            return;
        }

        try { dg_log($purchaseId, 'client', (int)CLIENT_ID, 'review_submitted', ['rating' => $rating]); } catch (\Throwable $e) {}

        if (function_exists('lb_send_seller_review_webhook')) {
            // Same two channels the boosting reviews use: the internal #review-notif
            // and the community #reviews webhook.
            $reviewAdminWebhookUrl     = "https://discord.com/api/webhooks/1461094683995275358/xEVZbjb_LnUZGjIIwHzhlaQodNUill6dMEST3KHAA3bnS6big5aKA8LmoF1eMgK_xJtM";
            $reviewCommunityWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

            lb_send_seller_review_webhook([
                'seller_id'     => (int)($purchase['seller_id'] ?? 0),
                'client_id'     => (int)CLIENT_ID,
                'purchase_id'   => $purchaseId,
                'review_source' => 'digital_good',
                'rating'        => $rating,
                'comment'       => $comment,
                'approved'      => 1,
            ], $reviewAdminWebhookUrl, $reviewCommunityWebhookUrl);
        }

        echo json_encode([
            'success' => true,
            'sendToast' => ['type'=>'success','title'=>'Thank you!','message'=>'Your review has been submitted.'],
            'playSound' => 'success',
        ]);
    }


    // ═══════════════════════════════════════════════════════════════════════
    // LOLBOOST APP JSON ENDPOINTS (merged from live ajax 52)
    // ═══════════════════════════════════════════════════════════════════════



    private function lb_app_json(array $payload): void
    {
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function lb_app_decode($value): string
    {
        $s = (string)($value ?? '');
        for ($i = 0; $i < 3; $i++) {
            $decoded = html_entity_decode($s, ENT_QUOTES | ENT_HTML5, 'UTF-8');
            if ($decoded === $s) {
                break;
            }
            $s = $decoded;
        }
        return $s;
    }

    private function lb_app_normalize_game_key($game): string
    {
        $game = strtolower(trim((string)$game));
        $game = str_replace(['_', ' '], '-', $game);

        $map = [
            'league-of-legends' => 'lol',
            'league' => 'lol',
            'lol' => 'lol',
            'valorant' => 'val',
            'val' => 'val',
            'teamfight-tactics' => 'tft',
            'teamfighttactics' => 'tft',
            'tft' => 'tft',
        ];

        return $map[$game] ?? $game;
    }

    private function lb_app_split_game_keys($games): array
    {
        $parts = preg_split('/[|,;\s]+/', (string)$games);
        $out = [];
        foreach ($parts as $part) {
            $key = $this->lb_app_normalize_game_key($part);
            if ($key !== '') {
                $out[$key] = true;
            }
        }

        // Backward compatibility for old booster rows that do not have games configured yet.
        if (empty($out)) {
            $out = ['lol' => true, 'val' => true, 'tft' => true];
        }

        return array_keys($out);
    }

    private function lb_app_price_eur($value): float
    {
        if ($value === null || $value === '') {
            return 0.0;
        }
        $n = (float)$value;
        return $n > 1000 ? round($n / 100, 2) : round($n, 2);
    }

    private function lb_app_clean_details(array $details): array
    {
        $out = [];
        foreach ($details as $row) {
            $label = trim((string)($row['label'] ?? ''));
            if ($label === '') {
                continue;
            }
            $out[] = [
                'label' => $label,
                'value' => $this->lb_app_decode($row['value'] ?? ''),
            ];
        }
        return $out;
    }


    public function whoami_json()
    {
        // A single browser can hold a valid client session AND a valid booster
        // session at the same time (separate cookies) — report both if present
        // so the app can offer a real "switch dashboard" toggle instead of
        // guessing which one to show.
        $client = $this->is_client ? [
            'id'       => (int) CLIENT_ID,
            'username' => CLIENT_DATA['username'] ?? '',
            'email'    => CLIENT_DATA['email'] ?? '',
            'icon'     => CLIENT_DATA['icon'] ?? '',
        ] : null;

        $booster = $this->is_booster ? [
            'id'       => (int) BOOSTER_ID,
            'username' => BOOSTER_DATA['username'] ?? '',
            'email'    => BOOSTER_DATA['email'] ?? '',
            'icon'     => BOOSTER_DATA['icon'] ?? '',
        ] : null;

        if (!$client && !$booster) {
            echo json_encode(['success' => false]);
            return;
        }

        echo json_encode([
            'success'    => true,
            'role'       => $client ? 'client' : 'booster', // default/primary role to land on
            'has_client' => (bool) $client,
            'has_booster'=> (bool) $booster,
            'client'     => $client,
            'booster'    => $booster,
        ]);
    }

    private function lb_get_booster($id)
    {
        $id = (int) $id;
        if ($id <= 0) {
            return null;
        }
        if (!array_key_exists($id, self::$lb_booster_cache)) {
            self::$lb_booster_cache[$id] = db_get_row('boosters', ['id' => $id, 'select' => 'id,username,icon'], 1) ?: null;
        }
        return self::$lb_booster_cache[$id];
    }

    private function lb_get_client($id)
    {
        $id = (int) $id;
        if ($id <= 0) {
            return null;
        }
        if (!array_key_exists($id, self::$lb_client_cache)) {
            self::$lb_client_cache[$id] = db_get_row('clients', ['id' => $id, 'select' => 'id,username,icon'], 1) ?: null;
        }
        return self::$lb_client_cache[$id];
    }


    private function lb_order_row_json($order, $form, $opts, $extra = [])
    {
        // Same merge order your own code uses: options, then form, then the order row wins on overlaps.
        $row = array_merge((array) $opts, (array) $form, (array) $order);

        return array_merge([
            'id'             => (int) $order['id'],
            'status'         => $order['status'],
            'price'          => round((float) (($order['price_eur'] ?? $order['price'] ?? 0)) / 100, 2),
            'currency'       => $order['currency'] ?? 'EUR',
            'created_at'     => $order['created_at'],
            'game'           => $this->lb_app_normalize_game_key($form['game'] ?? ($order['game'] ?? null)),
            'game_raw'       => $form['game'] ?? ($order['game'] ?? null),
            'form_name'      => $form['name'] ?? null,
            'form_type'      => $form['type'] ?? null,
            'server'         => $row['server'] ?? null,
            'start_tier'     => $row['start_tier'] ?? null,
            'start_division' => $row['start_division'] ?? null,
            'start_lp'       => $row['start_lp'] ?? null,
            'start_rr'       => $row['start_rr'] ?? null,
            'end_tier'       => $row['end_tier'] ?? null,
            'end_division'   => $row['end_division'] ?? null,
            'end_lp'         => $row['end_lp'] ?? null,
            'end_rr'         => $row['end_rr'] ?? null,
            'matches'        => $row['matches'] ?? null,
            'hours'          => $row['hours'] ?? null,
            'current_rank'   => $row['current_rank'] ?? null,
            'coach_type'     => $row['coach_type'] ?? null,
            'queue_type'     => $row['queue_type'] ?? null,
            'is_duo'         => $row['is_duo'] ?? null,
        ], $extra);
    }


    public function client_orders_list_json()
    {
        if (!$this->is_client) {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        global $db;
        $forms  = array_column(db_get_rows('boost_forms', ['select' => 'id,type,name,icon,game']) ?: [], null, 'id');
        $out = [];

        // Boost orders
        $orders = db_get_rows('orders', ['client_id' => CLIENT_ID], 1) ?: [];
        foreach ($orders as $order) {
            $opts    = db_get_row('order_options', ['order_id' => $order['id']]) ?: [];
            $form    = $forms[$order['form_id']] ?? [];
            $booster = $this->lb_get_booster($order['booster_id'] ?? 0);

            $out[] = $this->lb_order_row_json($order, $form, $opts, [
                'app_kind'         => 'boost',
                'booster_id'       => $order['booster_id'] ?? null,
                'booster_username' => $booster['username'] ?? null,
                'booster_icon'     => $booster['icon'] ?? null,
            ]);
        }

        // Smurf accounts from the classic accounts table
        $classic_accounts = db_get_rows('accounts', ['client_id' => CLIENT_ID, 'status' => 1], 1) ?: [];
        foreach ($classic_accounts as $account) {
            $package = [];
            if (!empty($account['package_id'])) {
                $package = db_get_row('account_packages', ['id' => (int)$account['package_id']]) ?: [];
            }
            $title = trim((string)($package['name'] ?? $account['login'] ?? 'Smurf Account'));
            $server = trim((string)($package['server'] ?? $account['server'] ?? ''));
            $admin = !empty($account['admin_id']) ? db_get_row('admins', ['id' => (int)$account['admin_id'], 'select' => 'id,username,icon'], 1) : null;
            $game = strtolower((string)($account['game'] ?? $package['game'] ?? 'lol'));
            if (!in_array($game, ['lol', 'val', 'tft'], true)) { $game = 'lol'; }
            $rank_index = (int)($game === 'val' ? ($account['rank'] ?? 0) : ($account['current_rank'] ?? $account['rank'] ?? 0));
            $rank_label = $game === 'val'
                ? (function_exists('util_get_val_rank') ? util_get_val_rank($rank_index) : (string)$rank_index)
                : (function_exists('util_get_lol_rank') ? util_get_lol_rank($rank_index) : (string)$rank_index);
            $out[] = [
                'id'          => 'acc_' . (int)$account['id'],
                'numeric_id'  => (int)$account['id'],
                'ref_type'    => 'premium_account',
                'ref_id'      => (int)$account['id'],
                'legacy_chat_type' => 'premium_account',
                'app_kind'    => 'account',
                'account_type'=> 'smurf',
                'status'      => 'COMPLETED',
                'price'       => round((float)($account['price_eur'] ?? $account['price'] ?? $package['price'] ?? 0) / (((float)($account['price_eur'] ?? 0) > 100) ? 100 : 1), 2),
                'currency'    => $account['currency'] ?? 'EUR',
                'created_at'  => $account['sold_at'] ?? $account['created_at'] ?? '',
                'game'        => $game,
                'form_name'   => 'Account',
                'form_type'   => 'account',
                'title'       => $title !== '' ? $title : ('Account #' . (int)$account['id']),
                'account_name'=> $title !== '' ? $title : ('Account #' . (int)$account['id']),
                'subtitle'    => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . 'Purchased account'),
                'server'      => $server,
                'admin_id'    => (int)($account['admin_id'] ?? 0),
                'admin_username' => $admin['username'] ?? null,
                'admin_icon'  => $admin['icon'] ?? null,
                'in_game_name'=> $account['in_game_name'] ?? null,
                'login'       => $account['login'] ?? null,
                'password'    => $account['password'] ?? null,
                'email'       => $account['email'] ?? null,
                'account_email' => $account['email'] ?? null,
                'email_password' => $account['email_password'] ?? null,
                'data'        => $account['data'] ?? null,
                'account_data'=> $account['data'] ?? null,
                'rank'        => $rank_index,
                'rank_label'  => $rank_label,
                'level'       => $account['level'] ?? null,
                'blue_essence'=> $account['blue_essence'] ?? null,
                'riot_points' => $account['riot_points'] ?? null,
                'details'     => [
                    ['label' => 'Type', 'value' => 'Smurf Account'],
                    ['label' => 'Account', 'value' => $title !== '' ? $title : ('#' . (int)$account['id'])],
                    ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                    ['label' => $game === 'val' ? 'Riot ID' : 'In-Game Name', 'value' => $account['in_game_name'] ?? ''],
                    ['label' => 'Login', 'value' => $account['login'] ?? ''],
                    ['label' => 'Password', 'value' => $account['password'] ?? ''],
                    ['label' => 'Account Email', 'value' => $account['email'] ?? ''],
                    ['label' => 'Email Password', 'value' => $account['email_password'] ?? ''],
                    ['label' => 'Data', 'value' => $account['data'] ?? ''],
                    ['label' => 'Rank', 'value' => $rank_label],
                    ['label' => 'Level', 'value' => $account['level'] ?? ''],
                    ['label' => 'Blue Essence', 'value' => $account['blue_essence'] ?? ''],
                    ['label' => 'Riot Points', 'value' => $account['riot_points'] ?? ''],
                ],
                'source_url'   => BASE_URL . '/profile/accounts',
            ];
        }

        // Marketplace accounts bought from sellers
        $market_accounts = db_get_rows('selling_accounts', ['client_id' => CLIENT_ID, 'sold' => 1], 1) ?: [];
        foreach ($market_accounts as $account) {
            $seller = !empty($account['seller_id']) ? db_get_row('sellers', ['id' => (int)$account['seller_id'], 'select' => 'id,username,icon'], 1) : null;
            $game = strtolower((string)($account['game'] ?? 'lol'));
            if (!in_array($game, ['lol', 'val', 'tft'], true)) { $game = 'lol'; }
            $title = trim((string)($account['title'] ?? 'Marketplace Account'));
            $server = trim((string)($account['server'] ?? ''));
            $game_data = [];
            try { $game_data = json_decode($account['game_data'] ?? '[]', true) ?: []; } catch (\Throwable $e) { $game_data = []; }
            if (!is_array($game_data)) { $game_data = []; }
            $rank_index = (int)($game === 'val' ? ($account['rank'] ?? 0) : ($account['current_rank'] ?? 0));
            $rank_label = $game === 'val'
                ? (function_exists('util_get_val_rank') ? util_get_val_rank($rank_index) : (string)$rank_index)
                : (function_exists('util_get_lol_rank') ? util_get_lol_rank($rank_index) : (string)$rank_index);
            $out[] = [
                'id'          => 'macc_' . (int)$account['id'],
                'numeric_id'  => (int)$account['id'],
                'app_kind'    => 'account',
                'account_type'=> 'marketplace',
                'legacy_chat_type' => 'marketplace_account',
                'status'      => 'COMPLETED',
                'price'       => round((float)($account['price'] ?? 0), 2),
                'price_cents' => (int)($account['price'] ?? 0),
                'currency'    => $account['currency'] ?? 'EUR',
                'created_at'  => $account['sold_at'] ?? $account['created_at'] ?? '',
                'game'        => $game,
                'form_name'   => 'Account',
                'form_type'   => 'account',
                'title'       => $title !== '' ? $title : ('Account #' . (int)$account['id']),
                'account_name'=> $title !== '' ? $title : ('Account #' . (int)$account['id']),
                'subtitle'    => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . 'Marketplace account'),
                'server'      => $server,
                'seller_id'   => (int)($account['seller_id'] ?? 0),
                'seller_username' => $seller['username'] ?? null,
                'seller_icon' => $seller['icon'] ?? null,
                'ref_type'    => 'account',
                'ref_id'      => (int)$account['id'],
                'in_game_name'=> $account['in_game_name'] ?? null,
                'login'       => $account['login'] ?? null,
                'password'    => $account['password'] ?? null,
                'email'       => $account['email'] ?? null,
                'account_email' => $account['email'] ?? null,
                'email_password' => $account['email_password'] ?? null,
                'delivery_instructions' => $account['delivery_instructions'] ?? null,
                'rank'        => $rank_index,
                'rank_label'  => $rank_label,
                'peak_rank'   => $game === 'val' ? ($game_data['val_peak_rank'] ?? null) : ($account['peak_rank'] ?? null),
                'level'       => $account['level'] ?? null,
                'blue_essence'=> $account['blue_essence'] ?? null,
                'riot_points' => $account['riot_points'] ?? null,
                'agents'      => !empty($game_data['agents']) && is_array($game_data['agents']) ? implode(', ', $game_data['agents']) : null,
                'agent_count' => $account['val_agent_count'] ?? null,
                'skins'       => $account['skin_count'] ?? null,
                'skin_count'  => $account['skin_count'] ?? null,
                'details'     => [
                    ['label' => 'Type', 'value' => 'Marketplace Account'],
                    ['label' => 'Seller', 'value' => $seller['username'] ?? 'Seller'],
                    ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                    ['label' => $game === 'val' ? 'Riot ID' : 'In-Game Name', 'value' => $account['in_game_name'] ?? ''],
                    ['label' => 'Login', 'value' => $account['login'] ?? ''],
                    ['label' => 'Password', 'value' => $account['password'] ?? ''],
                    ['label' => 'Account Email', 'value' => $account['email'] ?? ''],
                    ['label' => 'Email Password', 'value' => $account['email_password'] ?? ''],
                    ['label' => 'Instructions', 'value' => $account['delivery_instructions'] ?? ''],
                    ['label' => 'Rank', 'value' => $rank_label],
                    ['label' => 'Level', 'value' => $account['level'] ?? ''],
                    ['label' => 'Blue Essence', 'value' => $account['blue_essence'] ?? ''],
                    ['label' => 'Riot Points', 'value' => $account['riot_points'] ?? ''],
                ],
                'source_url'   => BASE_URL . '/account/' . (int)$account['id'],
            ];
        }

        // Item purchases
        $item_rows = [];
        try {
            $item_rows = $db->run(
                "SELECT sip.*, si.title AS item_title, si.type, si.server, si.images, si.price AS item_price, si.description AS item_description,
                        si.game_id AS item_game_id, si.game AS item_game_slug, si.item_data,
                        g.name AS item_game_name, g.slug AS game_slug, g.icon AS game_icon,
                        s.username AS seller_username, s.icon AS seller_icon
                 FROM selling_item_purchases sip
                 LEFT JOIN selling_items si ON si.id = sip.item_id
                 LEFT JOIN games g ON g.id = si.game_id
                 LEFT JOIN sellers s ON s.id = sip.seller_id
                 WHERE sip.client_id = ?
                 ORDER BY sip.created_at DESC",
                (int) CLIENT_ID
            ) ?: [];
        } catch (\Throwable $e) { $item_rows = []; }
        foreach ($item_rows as $purchase) {
            $title = trim((string)($purchase['item_title'] ?? 'Item Order'));
            $server = trim((string)($purchase['server'] ?? ''));
            $gameSlug = trim((string)($purchase['game_slug'] ?? $purchase['item_game_slug'] ?? 'league-of-legends'));
            $gameName = trim((string)($purchase['item_game_name'] ?? ''));
            if ($gameName === '') $gameName = ucwords(str_replace('-', ' ', $gameSlug));
            $price = $purchase['total_price'] ?? $purchase['amount'] ?? $purchase['price'] ?? $purchase['item_price'] ?? 0;
            $out[] = [
                'id'          => 'item_' . (int)$purchase['id'],
                'numeric_id'  => (int)$purchase['id'],
                'app_kind'    => 'item',
                'status'      => strtoupper((string)($purchase['status'] ?? 'PAID')),
                'price'       => round((float)$price, 2),
                'currency'    => $purchase['currency'] ?? 'EUR',
                'created_at'  => $purchase['created_at'] ?? '',
                'game'        => $gameSlug,
                'game_name'   => $gameName,
                'game_icon'   => $purchase['game_icon'] ?? null,
                'form_name'   => 'Item',
                'form_type'   => 'item',
                'title'       => $title !== '' ? $title : ('Item #' . (int)$purchase['id']),
                'subtitle'    => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . ucwords(str_replace('_', ' ', (string)($purchase['type'] ?? 'Item purchase')))),
                'server'      => $server,
                'seller_id'   => (int)($purchase['seller_id'] ?? 0),
                'seller_username' => $purchase['seller_username'] ?? null,
                'seller_icon' => $purchase['seller_icon'] ?? null,
                'ref_type'    => 'item_purchase',
                'ref_id'      => (int)$purchase['id'],
                'details'     => [
                    ['label' => 'Game', 'value' => $gameName],
                    ['label' => 'Type', 'value' => ucwords(str_replace('_', ' ', (string)($purchase['type'] ?? 'Item')))],
                    ['label' => 'Seller', 'value' => $purchase['seller_username'] ?? 'Seller'],
                    ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                ],
                'source_url'   => BASE_URL . '/profile/item/' . (int)$purchase['id'],
            ];
        }

        usort($out, function ($a, $b) {
            return strtotime((string) ($b['created_at'] ?? '')) - strtotime((string) ($a['created_at'] ?? ''));
        });

        echo json_encode(['success' => true, 'orders' => $out]);
    }


    public function booster_orders_queue_json()
    {
        if (!$this->is_booster) {
            $this->lb_app_json(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        global $db;

        $booster = db_get_row('boosters', ['id' => BOOSTER_ID], 1) ?: [];
        $games = $this->lb_app_split_game_keys($booster['games'] ?? '');
        $forms = array_column(db_get_rows('boost_forms', ['select' => 'id,type,name,icon,game']) ?: [], null, 'id');

        // Match the website booster orders panel source:
        // status PAID, no assigned booster, not claimed yet, newest first.
        // Use raw SQL here because the db_get_rows wrapper cannot express
        // (booster_id IS NULL OR booster_id = 0) safely together with claimed_at.
        try {
            $available_raw = $db->run(
                "SELECT id,form_id,price,price_eur,currency,status,created_at,paid_at,client_id,booster_id,claimed_at
                   FROM orders
                  WHERE status = 'PAID'
                    AND (booster_id IS NULL OR booster_id = 0)
                    AND (claimed_at IS NULL OR claimed_at = '' OR claimed_at = '0000-00-00 00:00:00')
                  ORDER BY created_at DESC"
            ) ?: [];
        } catch (\Throwable $e) {
            $available_raw = [];
        }

        $available = [];
        $skipped_by_game = 0;
        foreach ($available_raw as $order) {
            $form = $forms[$order['form_id']] ?? [];
            $formGame = $this->lb_app_normalize_game_key($form['game'] ?? '');

            if ($formGame !== '' && !in_array($formGame, $games, true)) {
                $skipped_by_game++;
                continue;
            }

            $opts = db_get_row('order_options', ['order_id' => $order['id']]) ?: [];

            // Important for the app: the website stores claimable orders as PAID,
            // but the app UI only shows available orders when status maps to placed.
            // AVAILABLE is intentionally unknown to statusFromApi(), so it maps to placed.
            $appOrder = $order;
            $appOrder['status'] = 'AVAILABLE';

            $available[] = $this->lb_order_row_json($appOrder, $form, $opts, [
                'assigned' => false,
                'db_status' => $order['status'] ?? null,
                'raw_status' => $order['status'] ?? null,
            ]);
        }

        $mine_raw = db_get_rows('orders', [
            'select'     => 'id,form_id,price,price_eur,currency,status,created_at,client_id',
            'booster_id' => BOOSTER_ID,
            'order'      => 'created_at DESC',
        ], 1) ?: [];

        $mine = [];
        foreach ($mine_raw as $order) {
            $form   = $forms[$order['form_id']] ?? [];
            $opts   = db_get_row('order_options', ['order_id' => $order['id']]) ?: [];
            $client = $this->lb_get_client($order['client_id'] ?? 0);

            $mine[] = $this->lb_order_row_json($order, $form, $opts, [
                'assigned'        => true,
                'client_id'       => $order['client_id'] ?? null,
                'client_username' => $client['username'] ?? null,
                'client_icon'     => $client['icon'] ?? null,
            ]);
        }

        $this->lb_app_json([
            'success' => true,
            'available' => $available,
            'assigned' => $mine,
            'games' => $games,
            'raw_available_count' => count($available_raw),
            'available_count' => count($available),
            'skipped_by_game' => $skipped_by_game,
        ]);
    }



    public function order_detail_json()
    {
        $order_id = (int) ($_POST['order_id'] ?? 0);
        if ($order_id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid order']);
            return;
        }

        if ($this->is_client) {
            $order = db_get_row('orders', ['id' => $order_id, 'client_id' => CLIENT_ID], 1);
        } elseif ($this->is_booster) {
            $order = db_get_row('orders', ['id' => $order_id, 'booster_id' => BOOSTER_ID], 1);
            if (!$order) {
                $order = db_get_row('orders', ['id' => $order_id, 'status' => 'PAID'], 1);
            }
        } else {
            echo json_encode(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        if (!$order) {
            echo json_encode(['success' => false, 'message' => 'Order not found']);
            return;
        }

        $form    = db_get_row('boost_forms', ['id' => $order['form_id']]) ?: [];
        $opts    = db_get_row('order_options', ['order_id' => $order_id]) ?: [];
        $booster = $this->lb_get_booster($order['booster_id'] ?? 0);
        $client  = $this->lb_get_client($order['client_id'] ?? 0);

        $row = $this->lb_order_row_json($order, $form, $opts, [
            'booster' => $booster,
            'client'  => $client,
        ]);

        echo json_encode(['success' => true, 'order' => $row]);
    }



    public function client_app_product_detail_json()
    {
        if (!$this->is_client) {
            $this->lb_app_json(['success' => false, 'message' => 'Unauthorized']);
            return;
        }

        global $db;

        $typeRaw = strtolower(trim((string)($_POST['type'] ?? '')));
        $refId = (int)($_POST['ref_id'] ?? 0);
        $orderIdRaw = trim((string)($_POST['order_id'] ?? ''));

        if ($refId <= 0 && preg_match('/(\d+)$/', $orderIdRaw, $m)) {
            $refId = (int)$m[1];
        }

        if ($refId <= 0) {
            $this->lb_app_json(['success' => false, 'message' => 'Invalid product order']);
            return;
        }

        if (in_array($typeRaw, ['premium_account', 'smurf', 'premium'], true) || strpos($orderIdRaw, 'acc_') === 0) {
            $account = db_get_row('accounts', ['id' => $refId, 'client_id' => CLIENT_ID], 1);
            if (!$account) {
                $this->lb_app_json(['success' => false, 'message' => 'Account not found']);
                return;
            }

            $package = [];
            if (!empty($account['package_id'])) {
                $package = db_get_row('account_packages', ['id' => (int)$account['package_id']]) ?: [];
            }
            $admin = !empty($account['admin_id']) ? db_get_row('admins', ['id' => (int)$account['admin_id'], 'select' => 'id,username,icon'], 1) : null;
            $game = $this->lb_app_normalize_game_key($account['game'] ?? $package['game'] ?? 'lol');
            $title = trim($this->lb_app_decode($package['name'] ?? $account['login'] ?? ('Account #' . $refId)));
            $server = trim((string)($package['server'] ?? $account['server'] ?? ''));

            $rankIndex = (int)($game === 'val' ? ($account['rank'] ?? 0) : ($account['current_rank'] ?? $account['rank'] ?? 0));
            $rankLabel = $game === 'val'
                ? (function_exists('util_get_val_rank') ? util_get_val_rank($rankIndex) : (string)$rankIndex)
                : (function_exists('util_get_lol_rank') ? util_get_lol_rank($rankIndex) : (string)$rankIndex);

            $details = $this->lb_app_clean_details([
                ['label' => 'Type', 'value' => 'Smurf Account'],
                ['label' => 'Account', 'value' => $title],
                ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                ['label' => $game === 'val' ? 'Riot ID' : 'In-Game Name', 'value' => $account['in_game_name'] ?? ''],
                ['label' => 'Login', 'value' => $account['login'] ?? ''],
                ['label' => 'Password', 'value' => $account['password'] ?? ''],
                ['label' => 'Account Email', 'value' => $account['email'] ?? ''],
                ['label' => 'Email Password', 'value' => $account['email_password'] ?? ''],
                ['label' => 'Data', 'value' => $account['data'] ?? ''],
                ['label' => 'Rank', 'value' => $rankLabel],
                ['label' => 'Level', 'value' => $account['level'] ?? ''],
                ['label' => 'Blue Essence', 'value' => $account['blue_essence'] ?? ''],
                ['label' => 'Riot Points', 'value' => $account['riot_points'] ?? ''],
            ]);

            $this->lb_app_json(['success' => true, 'order' => [
                'id' => 'acc_' . $refId,
                'numeric_id' => $refId,
                'ref_type' => 'premium_account',
                'ref_id' => $refId,
                'legacy_chat_type' => 'premium_account',
                'app_kind' => 'account',
                'account_type' => 'smurf',
                'status' => 'COMPLETED',
                'price' => $this->lb_app_price_eur($account['price_eur'] ?? $account['price'] ?? $package['price'] ?? 0),
                'currency' => $account['currency'] ?? 'EUR',
                'created_at' => $account['sold_at'] ?? $account['created_at'] ?? '',
                'game' => $game,
                'title' => $title,
                'account_name' => $title,
                'subtitle' => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . 'Purchased account'),
                'server' => $server,
                'admin_id' => (int)($account['admin_id'] ?? 0),
                'admin_username' => $admin['username'] ?? 'Support',
                'admin_icon' => $admin['icon'] ?? null,
                'login' => $this->lb_app_decode($account['login'] ?? ''),
                'password' => $this->lb_app_decode($account['password'] ?? ''),
                'email' => $this->lb_app_decode($account['email'] ?? ''),
                'account_email' => $this->lb_app_decode($account['email'] ?? ''),
                'email_password' => $this->lb_app_decode($account['email_password'] ?? ''),
                'data' => $this->lb_app_decode($account['data'] ?? ''),
                'account_data' => $this->lb_app_decode($account['data'] ?? ''),
                'rank' => $rankIndex,
                'rank_label' => $rankLabel,
                'level' => $account['level'] ?? null,
                'blue_essence' => $account['blue_essence'] ?? null,
                'riot_points' => $account['riot_points'] ?? null,
                'details' => $details,
                'source_url' => BASE_URL . '/premium-account/' . $refId,
            ]]);
            return;
        }

        if (in_array($typeRaw, ['marketplace_account', 'account', 'marketplace'], true) || strpos($orderIdRaw, 'macc_') === 0) {
            $account = db_get_row('selling_accounts', ['id' => $refId, 'client_id' => CLIENT_ID, 'sold' => 1], 1);
            if (!$account) {
                $this->lb_app_json(['success' => false, 'message' => 'Account not found']);
                return;
            }

            $seller = !empty($account['seller_id']) ? db_get_row('sellers', ['id' => (int)$account['seller_id'], 'select' => 'id,username,icon'], 1) : null;
            $game = $this->lb_app_normalize_game_key($account['game'] ?? 'lol');
            $title = trim($this->lb_app_decode($account['title'] ?? ('Account #' . $refId)));
            $server = trim((string)($account['server'] ?? ''));

            $gameData = [];
            try { $gameData = json_decode($account['game_data'] ?? '[]', true) ?: []; } catch (\Throwable $e) { $gameData = []; }
            if (!is_array($gameData)) { $gameData = []; }

            $rankIndex = (int)($game === 'val' ? ($account['rank'] ?? 0) : ($account['current_rank'] ?? 0));
            $rankLabel = $game === 'val'
                ? (function_exists('util_get_val_rank') ? util_get_val_rank($rankIndex) : (string)$rankIndex)
                : (function_exists('util_get_lol_rank') ? util_get_lol_rank($rankIndex) : (string)$rankIndex);

            $details = $this->lb_app_clean_details([
                ['label' => 'Type', 'value' => 'Marketplace Account'],
                ['label' => 'Seller', 'value' => $seller['username'] ?? 'Seller'],
                ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                ['label' => $game === 'val' ? 'Riot ID' : 'In-Game Name', 'value' => $account['in_game_name'] ?? ''],
                ['label' => 'Login', 'value' => $account['login'] ?? ''],
                ['label' => 'Password', 'value' => $account['password'] ?? ''],
                ['label' => 'Account Email', 'value' => $account['email'] ?? ''],
                ['label' => 'Email Password', 'value' => $account['email_password'] ?? ''],
                ['label' => 'Instructions', 'value' => $account['delivery_instructions'] ?? ''],
                ['label' => 'Rank', 'value' => $rankLabel],
                ['label' => 'Level', 'value' => $account['level'] ?? ''],
                ['label' => 'Blue Essence', 'value' => $account['blue_essence'] ?? ''],
                ['label' => 'Riot Points', 'value' => $account['riot_points'] ?? ''],
            ]);

            $this->lb_app_json(['success' => true, 'order' => [
                'id' => 'macc_' . $refId,
                'numeric_id' => $refId,
                'app_kind' => 'account',
                'account_type' => 'marketplace',
                'legacy_chat_type' => 'marketplace_account',
                'status' => 'COMPLETED',
                'price' => $this->lb_app_price_eur($account['price'] ?? 0),
                'price_cents' => (int)($account['price'] ?? 0),
                'currency' => $account['currency'] ?? 'EUR',
                'created_at' => $account['sold_at'] ?? $account['created_at'] ?? '',
                'game' => $game,
                'title' => $title,
                'account_name' => $title,
                'subtitle' => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . 'Marketplace account'),
                'server' => $server,
                'seller_id' => (int)($account['seller_id'] ?? 0),
                'seller_username' => $seller['username'] ?? null,
                'seller_icon' => $seller['icon'] ?? null,
                'ref_type' => 'account',
                'ref_id' => $refId,
                'login' => $this->lb_app_decode($account['login'] ?? ''),
                'password' => $this->lb_app_decode($account['password'] ?? ''),
                'email' => $this->lb_app_decode($account['email'] ?? ''),
                'account_email' => $this->lb_app_decode($account['email'] ?? ''),
                'email_password' => $this->lb_app_decode($account['email_password'] ?? ''),
                'delivery_instructions' => $this->lb_app_decode($account['delivery_instructions'] ?? ''),
                'rank' => $rankIndex,
                'rank_label' => $rankLabel,
                'level' => $account['level'] ?? null,
                'blue_essence' => $account['blue_essence'] ?? null,
                'riot_points' => $account['riot_points'] ?? null,
                'agents' => !empty($gameData['agents']) && is_array($gameData['agents']) ? implode(', ', $gameData['agents']) : null,
                'details' => $details,
                'source_url' => BASE_URL . '/account/' . $refId,
            ]]);
            return;
        }

        if (in_array($typeRaw, ['item', 'item_purchase'], true) || strpos($orderIdRaw, 'item_') === 0) {
            $rows = $db->run(
                "SELECT sip.*, si.title AS item_title, si.type, si.server, si.description AS item_description, si.price AS item_price,
                        si.game_id AS item_game_id, si.game AS item_game_slug, si.item_data,
                        g.name AS item_game_name, g.slug AS game_slug, g.icon AS game_icon,
                        s.username AS seller_username, s.icon AS seller_icon
                 FROM selling_item_purchases sip
                 LEFT JOIN selling_items si ON si.id = sip.item_id
                 LEFT JOIN games g ON g.id = si.game_id
                 LEFT JOIN sellers s ON s.id = sip.seller_id
                 WHERE sip.id = ? AND sip.client_id = ?
                 LIMIT 1",
                $refId,
                (int)CLIENT_ID
            ) ?: [];
            $purchase = $rows[0] ?? null;
            if (!$purchase) {
                $this->lb_app_json(['success' => false, 'message' => 'Item order not found']);
                return;
            }

            $title = trim($this->lb_app_decode($purchase['item_title'] ?? ('Item #' . $refId)));
            $server = trim((string)($purchase['server'] ?? ''));
            $gameSlug = trim((string)($purchase['game_slug'] ?? $purchase['item_game_slug'] ?? 'league-of-legends'));
            $gameName = trim((string)($purchase['item_game_name'] ?? ''));
            if ($gameName === '') $gameName = ucwords(str_replace('-', ' ', $gameSlug));
            $price = $purchase['total_price'] ?? $purchase['amount'] ?? $purchase['price'] ?? $purchase['item_price'] ?? 0;

            $this->lb_app_json(['success' => true, 'order' => [
                'id' => 'item_' . $refId,
                'numeric_id' => $refId,
                'app_kind' => 'item',
                'status' => strtoupper((string)($purchase['status'] ?? 'PAID')),
                'price' => $this->lb_app_price_eur($price),
                'currency' => $purchase['currency'] ?? 'EUR',
                'created_at' => $purchase['created_at'] ?? '',
                'game' => $gameSlug,
                'game_name' => $gameName,
                'game_icon' => $purchase['game_icon'] ?? null,
                'title' => $title,
                'subtitle' => trim(($server !== '' ? strtoupper($server) . ' · ' : '') . ucwords(str_replace('_', ' ', (string)($purchase['type'] ?? 'Item purchase')))),
                'server' => $server,
                'seller_id' => (int)($purchase['seller_id'] ?? 0),
                'seller_username' => $purchase['seller_username'] ?? null,
                'seller_icon' => $purchase['seller_icon'] ?? null,
                'ref_type' => 'item_purchase',
                'ref_id' => $refId,
                'details' => $this->lb_app_clean_details([
                    ['label' => 'Game', 'value' => $gameName],
                    ['label' => 'Type', 'value' => ucwords(str_replace('_', ' ', (string)($purchase['type'] ?? 'Item')))],
                    ['label' => 'Seller', 'value' => $purchase['seller_username'] ?? 'Seller'],
                    ['label' => 'Server', 'value' => $server !== '' ? strtoupper($server) : '—'],
                    ['label' => 'Description', 'value' => $purchase['item_description'] ?? ''],
                ]),
                'source_url' => BASE_URL . '/profile/item/' . $refId,
            ]]);
            return;
        }

        $this->lb_app_json(['success' => false, 'message' => 'Unsupported product type']);
    }




    /* Restored from live: poke, rewards, seller setup, review and e-girl helpers. */


    public function admin_poke_client()
    {
        if (!$this->is_admin) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'], 'playSound' => 'error']);
            return;
        }

        global $db;

        $ref_type = strtolower(trim((string)($_POST['ref_type'] ?? $_POST['type'] ?? 'order')));
        $id = (int)($_POST['id'] ?? $_POST['order_id'] ?? $_POST['account_id'] ?? $_POST['purchase_id'] ?? 0);

        if ($id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid request.'], 'playSound' => 'error']);
            return;
        }

        $row = null;
        $client_id = 0;
        $title = '';
        $client_url = '';
        $ref_key = '';
        $ref_label = 'order';

        if ($ref_type === 'account' || $ref_type === 'selling_account') {
            $row = db_get_row('selling_accounts', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['title'] ?? ('Account #' . $id)));
            $client_url = BASE_URL . '/profile/account/' . $id;
            $ref_key = 'selling_account:' . $id;
            $ref_label = 'account purchase';
        } elseif ($ref_type === 'premium_account') {
            $row = db_get_row('accounts', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['name'] ?? $row['login'] ?? ('Premium Account #' . $id)));
            $client_url = BASE_URL . '/profile/account/' . $id;
            $ref_key = 'premium_account:' . $id;
            $ref_label = 'premium account';
        } elseif ($ref_type === 'item' || $ref_type === 'item_purchase') {
            $row = db_get_row('selling_item_purchases', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['item_title'] ?? $row['title'] ?? ('Item Order #' . $id)));
            $client_url = BASE_URL . '/profile/item/' . $id;
            $ref_key = 'item_purchase:' . $id;
            $ref_label = 'item purchase';
        } elseif ($ref_type === 'topup' || $ref_type === 'topup_purchase') {
            $row = db_get_row('selling_topup_purchases', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['offer_title'] ?? ('Top Up Order #' . $id)));
            $client_url = BASE_URL . '/profile/top-up/' . $id;
            $ref_key = 'topup_purchase:' . $id;
            $ref_label = 'top up purchase';
        } elseif ($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') {
            $row = db_get_row('digital_good_purchases', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = 'Digital Good Order #' . $id;
            $client_url = BASE_URL . '/profile/digital-goods/' . $id;
            $ref_key = 'digital_good_purchase:' . $id;
            $ref_label = 'digital good purchase';
        } elseif ($ref_type === 'egirl' || $ref_type === 'egirl_order' || $ref_type === 'egirl_booking') {
            $row = db_get_row('egirl_orders', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['service_title'] ?? ('GG-Girl Order #' . $id)));
            $client_url = BASE_URL . '/egirl-order/' . $id;
            $ref_key = 'egirl_order:' . $id . ':admin_to_client';
            $ref_label = 'GG-Girl order';
            $ref_type = 'egirl_order';
        } else {
            $row = db_get_row('orders', ['id' => $id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = 'Order #' . $id;
            if (!empty($row['game']) || !empty($row['type'])) {
                $title = trim((string)(($row['game'] ?? '') . ' ' . ($row['type'] ?? '')));
                $title = $title !== '' ? ('Order #' . $id . ' - ' . $title) : ('Order #' . $id);
            }
            $client_url = BASE_URL . '/order/' . $id;
            $ref_key = 'order:' . $id;
            $ref_label = 'order';
            $ref_type = 'order';
        }

        if (empty($row) || $client_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found for this record.'], 'playSound' => 'error']);
            return;
        }

        $client = db_get_row('clients', ['id' => $client_id], 1);
        if (empty($client)) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found.'], 'playSound' => 'error']);
            return;
        }

        try {
            $last = $db->run(
                "SELECT id, created_at FROM notifications
                 WHERE type = 'poke_client'
                   AND recipient = 'client'
                   AND recipient_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.ref_key')) = ?
                 ORDER BY created_at DESC LIMIT 1",
                $client_id,
                $ref_key
            ) ?: [];
        } catch (\Throwable $e) {
            $last = [];
        }

        if (!empty($last[0]['created_at']) && strtotime((string)$last[0]['created_at']) > strtotime('-30 minutes')) {
            $this->lb_poke_json(['sendToast' => ['type' => 'warning', 'title' => 'Cooldown', 'message' => 'The client was already poked recently.'], 'playSound' => 'error']);
            return;
        }

        $admin_name = 'Support';
        if (defined('ADMIN_DATA') && is_array(ADMIN_DATA) && !empty(ADMIN_DATA['username'])) {
            $admin_name = (string)ADMIN_DATA['username'];
        }

        db_add_row('notifications', [
            'type' => 'poke_client',
            'recipient' => 'client',
            'recipient_id' => $client_id,
            'data' => json_encode([
                'order_id' => $this->lb_poke_b64((string)$id),
                'ref_key' => $ref_key,
                'ref_type' => $this->lb_poke_b64($ref_label),
                'sent_by' => $this->lb_poke_b64('admin'),
                'sender_name' => $this->lb_poke_b64($admin_name),
                'admin_id' => $this->lb_poke_b64((string)(defined('ADMIN_ID') ? ADMIN_ID : 0)),
                'title' => $this->lb_poke_b64($title),
                'action_url' => $this->lb_poke_b64($client_url),
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'is_email' => true,
            'is_discord' => false,
            'is_web' => 1,
        ]);

        if (function_exists('trigger_notification_sender_async')) {
            trigger_notification_sender_async();
        }

        if (function_exists('lb_ajax_realtime_notify_update')) {
            lb_ajax_realtime_notify_update('clients');
        }

        if (!empty($client['discord_id']) && defined('DS_BOT_TOKEN') && DS_BOT_TOKEN && function_exists('getDMChannelId') && function_exists('sendEmbedDM')) {
            try {
                $dmChannel = getDMChannelId(DS_BOT_TOKEN, trim((string)$client['discord_id']));
                if ($dmChannel) {
                    $embed = [
                        'title' => ucfirst($ref_label) . ' #' . $id,
                        'author' => [
                            'name' => 'LoLBoost.GG',
                            'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png',
                        ],
                        'description' => "⚠️ **Support Poked You**\n\nPlease **respond** in the website chat as soon as possible.",
                        'footer' => [
                            'text' => 'LoLBoost.GG - Ranking up never been easier',
                            'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png',
                        ],
                        'timestamp' => date('c'),
                        'color' => 0x5865F2,
                    ];

                    $components = [[
                        'type' => 1,
                        'components' => [[
                            'type' => 2,
                            'style' => 5,
                            'label' => '🔎 Open Chat',
                            'url' => $client_url,
                        ]],
                    ]];

                    sendEmbedDM(DS_BOT_TOKEN, $dmChannel, json_encode(['embeds' => [$embed], 'components' => $components], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                }
            } catch (\Throwable $e) {
                // Discord is optional. The normal website/email notification was already queued.
            }
        }


        $this->lb_poke_json(['sendToast' => ['type' => 'primary', 'title' => 'Success', 'message' => 'Client has been poked.'], 'playSound' => 'success', 'cooldown_seconds' => 5 * 60]);
    }


    public function client_poke_egirl()
    {
        if (!$this->is_client) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'], 'playSound' => 'error']);
            return;
        }

        global $db;
        $order_id = (int)($_POST['order_id'] ?? $_POST['id'] ?? 0);
        $client_id = (int)(defined('CLIENT_ID') ? CLIENT_ID : (CLIENT_DATA['id'] ?? 0));
        if ($order_id <= 0 || $client_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid request.'], 'playSound' => 'error']);
            return;
        }

        $order = db_get_row('egirl_orders', ['id' => $order_id, 'client_id' => $client_id], 1);
        if (empty($order)) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.'], 'playSound' => 'error']);
            return;
        }

        $egirl_id = (int)($order['egirl_id'] ?? 0);
        if ($egirl_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'No GG-Girl is assigned yet.'], 'playSound' => 'error']);
            return;
        }

        $egirl = db_get_row('boosters', ['id' => $egirl_id], 1);
        if (empty($egirl) || (int)($egirl['is_egirl'] ?? 0) !== 1) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'GG-Girl not found.'], 'playSound' => 'error']);
            return;
        }

        $encoded_order_id = $this->lb_poke_b64((string)$order_id);
        $ref_key = 'egirl_order:' . $order_id . ':client_to_egirl';
        try {
            $last = $db->run(
                "SELECT id, created_at FROM notifications
                 WHERE type = 'poke_booster'
                   AND recipient = 'booster'
                   AND recipient_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.ref_key')) = ?
                 ORDER BY created_at DESC LIMIT 1",
                $egirl_id,
                $ref_key
            ) ?: [];
        } catch (\Throwable $e) {
            $last = [];
        }

        $last_poke_at = !empty($last[0]['created_at']) ? strtotime((string)$last[0]['created_at']) : 0;
        $cooldown_remaining = $last_poke_at > 0 ? max(0, ($last_poke_at + (5 * 60)) - time()) : 0;
        if ($cooldown_remaining > 0) {
            $this->lb_poke_json([
                'success' => false,
                'cooldown_seconds' => $cooldown_remaining,
                'sendToast' => ['type' => 'warning', 'title' => 'Poke cooldown', 'message' => 'Please wait until the countdown is finished.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $client_name = (string)(CLIENT_DATA['username'] ?? 'Client');
        $title = trim((string)($order['service_title'] ?? ('GG-Girl Order #' . $order_id)));
        $egirl_url = BASE_URL . '/booster-area/egirl-order/' . $order_id;

        db_add_row('notifications', [
            'type' => 'poke_booster',
            'recipient' => 'booster',
            'recipient_id' => $egirl_id,
            'data' => json_encode([
                'order_id' => $encoded_order_id,
                'ref_key' => $ref_key,
                'ref_type' => $this->lb_poke_b64('GG-Girl order'),
                'sent_by' => $this->lb_poke_b64('client'),
                'sender_name' => $this->lb_poke_b64($client_name),
                'client_id' => $this->lb_poke_b64((string)$client_id),
                'booster_id' => $this->lb_poke_b64((string)$egirl_id),
                'booster_username' => $this->lb_poke_b64((string)($egirl['username'] ?? 'GG-Girl')),
                'title' => $this->lb_poke_b64($title),
                'action_url' => $this->lb_poke_b64($egirl_url),
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'is_email' => true,
            'is_discord' => false,
            'is_web' => 1,
        ]);
        if (function_exists('trigger_notification_sender_async')) {
            trigger_notification_sender_async();
        }
        if (function_exists('lb_ajax_realtime_notify_update')) {
            lb_ajax_realtime_notify_update('boosters');
        }

        if (!empty($egirl['discord_id']) && defined('DS_BOT_TOKEN') && DS_BOT_TOKEN && function_exists('getDMChannelId') && function_exists('sendEmbedDM')) {
            try {
                $dmChannel = getDMChannelId(DS_BOT_TOKEN, trim((string)$egirl['discord_id']));
                if ($dmChannel) {
                    $embed = [
                        'title' => 'GG-Girl Order #' . $order_id,
                        'author' => ['name' => 'LoLBoost.GG', 'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
                        'description' => "⚠️ **Client Poked You**\n\nPlease **respond** in the website chat as soon as possible.",
                        'footer' => ['text' => 'LoLBoost.GG - Ranking up never been easier', 'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
                        'timestamp' => date('c'),
                        'color' => 0xEC4899,
                    ];
                    $components = [['type' => 1, 'components' => [['type' => 2, 'style' => 5, 'label' => '🔎 Open Chat', 'url' => $egirl_url]]]];
                    sendEmbedDM(DS_BOT_TOKEN, $dmChannel, json_encode(['embeds' => [$embed], 'components' => $components], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                }
            } catch (\Throwable $e) {}
        }

        $this->lb_poke_json([
            'success' => true,
            'cooldown_seconds' => 5 * 60,
            'sendToast' => ['type' => 'success', 'title' => 'GG-Girl poked', 'message' => 'The GG-Girl has been notified successfully.'],
            'playSound' => 'success',
        ]);
    }


    public function client_poke_seller()
    {
        if (!$this->is_client) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'], 'playSound' => 'error']);
            return;
        }

        global $db;
        $ref_type = strtolower(trim((string)($_POST['ref_type'] ?? $_POST['type'] ?? 'account')));
        $id = (int)($_POST['id'] ?? $_POST['account_id'] ?? $_POST['purchase_id'] ?? 0);
        $client_id = (int)(defined('CLIENT_ID') ? CLIENT_ID : 0);
        if ($id <= 0 || $client_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid request.'], 'playSound' => 'error']);
            return;
        }

        $seller = null;
        $seller_url = '';
        $title = '';
        if ($ref_type === 'item' || $ref_type === 'item_purchase') {
            $row = db_get_row('selling_item_purchases', ['id' => $id, 'client_id' => $client_id], 1);
            if (!empty($row)) {
                $seller = db_get_row('sellers', ['id' => (int)($row['seller_id'] ?? 0)], 1);
                $title = trim((string)($row['item_title'] ?? $row['title'] ?? ('Item Order #' . $id)));
                $seller_url = BASE_URL . '/seller-area/item-order/' . $id;
                $ref_key = 'item_purchase:' . $id;
            }
        } elseif ($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') {
            $row = db_get_row('digital_good_purchases', ['id' => $id, 'client_id' => $client_id], 1);
            if (!empty($row)) {
                $seller = db_get_row('sellers', ['id' => (int)($row['seller_id'] ?? 0)], 1);
                $dgRow = db_get_row('digital_goods', ['id' => (int)($row['item_id'] ?? 0)], 1);
                $title = trim((string)($dgRow['title'] ?? $row['item_title'] ?? ('Digital Good Order #' . $id)));
                $seller_url = BASE_URL . '/seller-area/digital-goods/' . $id;
                $ref_key = 'digital_good_purchase:' . $id;
            }
        } elseif ($ref_type === 'topup' || $ref_type === 'topup_purchase') {
            $row = db_get_row('selling_topup_purchases', ['id' => $id, 'client_id' => $client_id], 1);
            if (!empty($row)) {
                $seller = db_get_row('sellers', ['id' => (int)($row['seller_id'] ?? 0)], 1);
                $title = trim((string)($row['offer_title'] ?? ('Top Up Order #' . $id)));
                $seller_url = BASE_URL . '/seller-area/top-up-order/' . $id;
                $ref_key = 'topup_purchase:' . $id;
            }
        } elseif ($ref_type === 'premium_account') {
            $row = db_get_row('accounts', ['id' => $id, 'client_id' => $client_id], 1);
            if (!empty($row)) {
                $seller = $this->lb_poke_resolve_premium_account_seller($row);
                $title = trim((string)($row['name'] ?? $row['login'] ?? ('Premium Account #' . $id)));
                $seller_url = !empty($seller['id']) ? BASE_URL . '/seller-area/account/' . $id : '';
                $ref_key = 'premium_account:' . $id;
            }
        } else {
            $row = db_get_row('selling_accounts', ['id' => $id, 'client_id' => $client_id, 'sold' => 1], 1);
            if (!empty($row)) {
                $seller = db_get_row('sellers', ['id' => (int)($row['seller_id'] ?? 0)], 1);
                $title = trim((string)($row['title'] ?? ('Account #' . $id)));
                $seller_url = BASE_URL . '/seller-area/account/' . $id;
                $ref_key = 'selling_account:' . $id;
            }
        }

        if (empty($row) || empty($seller)) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Seller not found for this purchase.'], 'playSound' => 'error']);
            return;
        }

        $seller_id = (int)($seller['id'] ?? 0);
        try {
            $last = $db->run(
                "SELECT id, created_at FROM notifications
                 WHERE type = 'poke_seller'
                   AND recipient = 'seller'
                   AND recipient_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.ref_key')) = ?
                 ORDER BY created_at DESC LIMIT 1",
                $seller_id,
                $ref_key
            ) ?: [];
        } catch (\Throwable $e) {
            $last = [];
        }

        $poke_cooldown_seconds = 5 * 60;
        if (!empty($last[0]['created_at'])) {
            $last_ts = strtotime((string)$last[0]['created_at']);
            if ($last_ts !== false && ($last_ts + $poke_cooldown_seconds) > time()) {
                $remaining = max(1, ($last_ts + $poke_cooldown_seconds) - time());
                $this->lb_poke_json([
                    'success' => false,
                    'cooldown_seconds' => $remaining,
                    'sendToast' => ['type' => 'warning', 'title' => 'Poke cooldown', 'message' => 'Please wait 5 minutes between pokes.'],
                    'playSound' => 'error',
                ]);
                return;
            }
        }

        $client = db_get_row('clients', ['id' => $client_id], 1) ?: [];
        $client_name = (string)($client['username'] ?? CLIENT_DATA['username'] ?? 'Client');
        $dm_sent = false;
        $discord_title = 'Purchase #' . $id;
        if ($ref_type === 'premium_account') {
            $discord_title = 'Premium Account #' . $id;
        } elseif ($ref_type === 'item' || $ref_type === 'item_purchase') {
            $discord_title = 'Item Order #' . $id;
        } elseif ($ref_type === 'account') {
            $discord_title = 'Account Order #' . $id;
        } elseif ($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') {
            $discord_title = 'Digital Good Order #' . $id;
        } elseif ($ref_type === 'topup' || $ref_type === 'topup_purchase') {
            $discord_title = 'Top Up Order #' . $id;
        }
        if (!empty($seller['discord_id'])) {
            $dm_sent = $this->lb_poke_send_seller_dm(
                $seller,
                $discord_title,
                "⚠️ **Client Poked You**

Please **respond** to the client **immediately** through the website chat.
",
                $seller_url ?: BASE_URL . '/seller-area',
                '🔎 Open Chat'
            );
        }

        db_add_row('notifications', [
            'type' => 'poke_seller',
            'recipient' => 'seller',
            'recipient_id' => $seller_id,
            'data' => json_encode([
                'order_id' => $this->lb_poke_b64((string)$id),
                'ref_key' => $ref_key,
                'ref_type' => $this->lb_poke_b64(
                    $ref_type === 'premium_account' ? 'premium account'
                    : (($ref_type === 'item' || $ref_type === 'item_purchase') ? 'item purchase'
                    : ((($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase')) ? 'digital good purchase'
                    : (($ref_type === 'topup' || $ref_type === 'topup_purchase') ? 'top up purchase'
                    : 'account purchase')))
                ),
                'sent_by' => $this->lb_poke_b64('client'),
                'sender_name' => $this->lb_poke_b64($client_name),
                'client_id' => $this->lb_poke_b64((string)$client_id),
                'client_username' => $this->lb_poke_b64($client_name),
                'seller_id' => $this->lb_poke_b64((string)$seller_id),
                'title' => $this->lb_poke_b64($title),
                'action_url' => $this->lb_poke_b64($seller_url ?: (BASE_URL . '/seller-area')),
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            // A client poke always sends an email. Discord is an additional channel.
            'is_email' => 1,
            'is_discord' => false,
            'is_web' => 1,
        ]);
        if (function_exists('trigger_notification_sender_async')) {
            trigger_notification_sender_async();
        }

        $this->lb_poke_json([
            'success' => true,
            'cooldown_seconds' => $poke_cooldown_seconds,
            'sendToast' => ['type' => 'primary', 'title' => 'Success', 'message' => 'Seller has been notified'],
            'playSound' => 'success',
        ]);
    }


    public function egirl_poke_client()
    {
        if (!$this->is_booster || !$this->is_egirl) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'], 'playSound' => 'error']);
            return;
        }

        global $db;
        $order_id = (int)($_POST['order_id'] ?? $_POST['id'] ?? 0);
        if ($order_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid order.'], 'playSound' => 'error']);
            return;
        }

        $order = db_get_row('egirl_orders', ['id' => $order_id], 1);
        if (empty($order) || (int)($order['egirl_id'] ?? 0) !== (int)BOOSTER_ID) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Order not found.'], 'playSound' => 'error']);
            return;
        }

        $client_id = (int)($order['client_id'] ?? 0);
        if ($client_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found for this order.'], 'playSound' => 'error']);
            return;
        }

        $client = db_get_row('clients', ['id' => $client_id], 1);
        if (empty($client)) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found.'], 'playSound' => 'error']);
            return;
        }

        $ref_key = 'egirl_order:' . $order_id . ':egirl_to_client';
        try {
            $last = $db->run(
                "SELECT id, created_at FROM notifications
                 WHERE type = 'poke_client'
                   AND recipient = 'client'
                   AND recipient_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.ref_key')) = ?
                 ORDER BY created_at DESC LIMIT 1",
                $client_id,
                $ref_key
            ) ?: [];
        } catch (\Throwable $e) {
            $last = [];
        }

        if (!empty($last[0]['created_at']) && strtotime((string)$last[0]['created_at']) > strtotime('-30 minutes')) {
            $this->lb_poke_json(['sendToast' => ['type' => 'warning', 'title' => 'Cooldown', 'message' => 'The client was already poked recently.'], 'playSound' => 'error']);
            return;
        }

        $egirl_name = (string)(BOOSTER_DATA['username'] ?? 'GG-Girl');
        $title = trim((string)($order['service_title'] ?? ('GG-Girl Order #' . $order_id)));
        $client_url = BASE_URL . '/egirl-order/' . $order_id;

        db_add_row('notifications', [
            'type' => 'poke_client',
            'recipient' => 'client',
            'recipient_id' => $client_id,
            'data' => json_encode([
                'order_id' => $this->lb_poke_b64((string)$order_id),
                'ref_key' => $ref_key,
                'ref_type' => $this->lb_poke_b64('GG-Girl order'),
                'sent_by' => $this->lb_poke_b64('egirl'),
                'sender_name' => $this->lb_poke_b64($egirl_name),
                'booster_id' => $this->lb_poke_b64((string)BOOSTER_ID),
                'title' => $this->lb_poke_b64($title),
                'action_url' => $this->lb_poke_b64($client_url),
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'is_email' => true,
            'is_discord' => false,
            'is_web' => 1,
        ]);
        if (function_exists('trigger_notification_sender_async')) {
            trigger_notification_sender_async();
        }
        if (function_exists('lb_ajax_realtime_notify_update')) {
            lb_ajax_realtime_notify_update('clients');
        }

        if (!empty($client['discord_id']) && defined('DS_BOT_TOKEN') && DS_BOT_TOKEN && function_exists('getDMChannelId') && function_exists('sendEmbedDM')) {
            try {
                $dmChannel = getDMChannelId(DS_BOT_TOKEN, trim((string)$client['discord_id']));
                if ($dmChannel) {
                    $embed = [
                        'title' => 'GG-Girl Order #' . $order_id,
                        'author' => ['name' => 'LoLBoost.GG', 'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
                        'description' => "⚠️ **Your GG-Girl Poked You**\n\nPlease **respond** in the website chat as soon as possible.",
                        'footer' => ['text' => 'LoLBoost.GG - Ranking up never been easier', 'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png'],
                        'timestamp' => date('c'),
                        'color' => 0xEC4899,
                    ];
                    $components = [['type' => 1, 'components' => [['type' => 2, 'style' => 5, 'label' => '🔎 Open Chat', 'url' => $client_url]]]];
                    sendEmbedDM(DS_BOT_TOKEN, $dmChannel, json_encode(['embeds' => [$embed], 'components' => $components], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                }
            } catch (\Throwable $e) {}
        }

        $this->lb_poke_json([
            'success' => true,
            'cooldown_seconds' => $poke_cooldown_seconds,
            'sendToast' => ['type' => 'primary', 'title' => 'Success', 'message' => 'Client has been notified by email.'],
            'playSound' => 'success',
        ]);
    }


    public function seller_poke_client()
    {
        if (!$this->is_seller) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Unauthorized.'], 'playSound' => 'error']);
            return;
        }

        global $db;
        $ref_type = strtolower(trim((string)($_POST['ref_type'] ?? $_POST['type'] ?? 'account')));
        $id = (int)($_POST['id'] ?? $_POST['account_id'] ?? $_POST['purchase_id'] ?? 0);
        $seller_id = (int)($this->seller_data['id'] ?? 0);
        if ($id <= 0 || $seller_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid request.'], 'playSound' => 'error']);
            return;
        }

        if ($ref_type === 'item' || $ref_type === 'item_purchase') {
            $row = db_get_row('selling_item_purchases', ['id' => $id, 'seller_id' => $seller_id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['item_title'] ?? $row['title'] ?? ('Item Order #' . $id)));
            $client_url = BASE_URL . '/profile/item/' . $id;
            $ref_key = 'item_purchase:' . $id;
        } elseif ($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') {
            $row = db_get_row('digital_good_purchases', ['id' => $id, 'seller_id' => $seller_id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $dgRow = !empty($row) ? db_get_row('digital_goods', ['id' => (int)($row['item_id'] ?? 0)], 1) : null;
            $title = trim((string)($dgRow['title'] ?? ('Digital Good Order #' . $id)));
            $client_url = BASE_URL . '/profile/digital-goods/' . $id;
            $ref_key = 'digital_good_purchase:' . $id;
        } elseif ($ref_type === 'topup' || $ref_type === 'topup_purchase') {
            $row = db_get_row('selling_topup_purchases', ['id' => $id, 'seller_id' => $seller_id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['offer_title'] ?? ('Top Up Order #' . $id)));
            $client_url = BASE_URL . '/profile/top-up/' . $id;
            $ref_key = 'topup_purchase:' . $id;
        } else {
            $row = db_get_row('selling_accounts', ['id' => $id, 'seller_id' => $seller_id], 1);
            $client_id = (int)($row['client_id'] ?? 0);
            $title = trim((string)($row['title'] ?? ('Account #' . $id)));
            $client_url = BASE_URL . '/profile/account/' . $id;
            $ref_key = 'selling_account:' . $id;
        }

        if (empty($row) || $client_id <= 0) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found for this sale.'], 'playSound' => 'error']);
            return;
        }

        $client = db_get_row('clients', ['id' => $client_id], 1);
        if (empty($client)) {
            $this->lb_poke_json(['sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Client not found.'], 'playSound' => 'error']);
            return;
        }

        try {
            $last = $db->run(
                "SELECT id, created_at FROM notifications
                 WHERE type = 'poke_client'
                   AND recipient = 'client'
                   AND recipient_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.ref_key')) = ?
                 ORDER BY created_at DESC LIMIT 1",
                $client_id,
                $ref_key
            ) ?: [];
        } catch (\Throwable $e) {
            $last = [];
        }

        $poke_cooldown_seconds = 5 * 60;
        if (!empty($last[0]['created_at'])) {
            $last_ts = strtotime((string)$last[0]['created_at']);
            if ($last_ts !== false) {
                $elapsed = time() - $last_ts;
                if ($elapsed < $poke_cooldown_seconds) {
                    $remaining = max(1, $poke_cooldown_seconds - $elapsed);
                    $this->lb_poke_json([
                        'sendToast' => ['type' => 'warning', 'title' => 'Cooldown', 'message' => 'The client was already poked recently. Please wait 5 minutes between pokes.'],
                        'playSound' => 'error',
                        'cooldown_seconds' => $remaining
                    ]);
                    return;
                }
            }
        }

        $seller_name = (string)($this->seller_data['username'] ?? 'Seller');

        // Digital Goods pokes also go out as a Discord DM when the buyer has one linked.
        // The email/web notification below is always queued as well.
        if (($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') && !empty($client['discord_id'])) {
            $this->lb_poke_send_seller_dm(
                $client,
                'Digital Good Order #' . $id,
                "⚠️ **" . $seller_name . " poked you**\n\nPlease **open your order** and reply through the website chat.\n",
                $client_url,
                '🔎 Open Order'
            );
        }

        $this->lb_poke_enqueue_email('poke_client', 'client', $client_id, [
            'order_id' => $this->lb_poke_b64((string)$id),
            'ref_key' => $ref_key,
            'ref_type' => $this->lb_poke_b64(
                ($ref_type === 'item' || $ref_type === 'item_purchase') ? 'item purchase'
                : (($ref_type === 'digital_good' || $ref_type === 'digital_good_purchase') ? 'digital good purchase'
                : (($ref_type === 'topup' || $ref_type === 'topup_purchase') ? 'top up purchase'
                : 'account purchase'))
            ),
            'sent_by' => $this->lb_poke_b64('seller'),
            'sender_name' => $this->lb_poke_b64($seller_name),
            'seller_id' => $this->lb_poke_b64((string)$seller_id),
            'seller_username' => $this->lb_poke_b64($seller_name),
            'title' => $this->lb_poke_b64($title),
            'action_url' => $this->lb_poke_b64($client_url),
        ]);

        $this->lb_poke_json([
            'success' => true,
            'cooldown_seconds' => $poke_cooldown_seconds,
            'sendToast' => ['type' => 'primary', 'title' => 'Success', 'message' => 'Client has been notified by email.'],
            'playSound' => 'success',
        ]);
    }


    public function client_reward_open_box()
    {
        global $db;

        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            $this->lb_reward_json(['success' => false, 'message' => 'Please login first.']);
            return;
        }

        if (session_status() !== PHP_SESSION_ACTIVE) { @session_start(); }
        $now = time();
        if (!empty($_SESSION['lb_reward_open_lock']) && ((int)$_SESSION['lb_reward_open_lock'] + 3) > $now) {
            $this->lb_reward_json(['success' => false, 'message' => 'Please wait a moment before opening another box.']);
            return;
        }
        $_SESSION['lb_reward_open_lock'] = $now;

        $box_id = (int)($_POST['box_id'] ?? 0);
        $box_slug = trim((string)($_POST['box_slug'] ?? ''));
        if ($box_id <= 0 && $box_slug === '') {
            $this->lb_reward_json(['success' => false, 'message' => 'Invalid reward box.']);
        }

        $client_id = (int)CLIENT_ID;
        $box = [];
        if ($box_id > 0) {
            $box = $this->lb_reward_row("SELECT * FROM reward_boxes WHERE id = ? AND status = 1 LIMIT 1", [$box_id]);
            if (empty($box)) {
                $inactiveBox = $this->lb_reward_row("SELECT id, name, status FROM reward_boxes WHERE id = ? LIMIT 1", [$box_id]);
                if (!empty($inactiveBox)) {
                    $this->lb_reward_json(['success' => false, 'message' => 'Reward box is inactive.', 'box_id' => $box_id]);
                }
            }
        }
        if (empty($box) && $box_slug !== '') {
            $box = $this->lb_reward_row("SELECT * FROM reward_boxes WHERE slug = ? AND status = 1 LIMIT 1", [$box_slug]);
        }
        if (empty($box)) {
            $this->lb_reward_json([
                'success' => false,
                'message' => 'Reward box not found.',
                'box_id' => $box_id,
                'box_slug' => $box_slug,
                'debug_hint' => $this->lb_reward_is_debug_host() ? 'The posted box id/slug does not match an active reward_boxes row.' : null,
            ]);
        }
        $box_id = (int)($box['id'] ?? $box_id);

        $price = (float)($box['price_coins'] ?? 0);
        $is_daily = (int)($box['is_daily'] ?? 0) === 1;
        if ($is_daily) {
            $cooldown = max(1, (int)($box['cooldown_hours'] ?? 24));
            try {
                $last = $this->lb_reward_single("SELECT created_at FROM reward_openings WHERE client_id = ? AND box_id = ? ORDER BY id DESC LIMIT 1", [$client_id, $box_id]);
                if ($last && strtotime((string)$last) !== false) {
                    $next = strtotime((string)$last) + ($cooldown * 3600);
                    if ($next > time()) {
                        $this->lb_reward_json(['success' => false, 'message' => 'This daily gift is not ready yet.', 'next_available_at' => date('Y-m-d H:i:s', $next)]);
                        return;
                    }
                }
            } catch (\Throwable $e) {}
        }

        try {
            $client = $this->lb_reward_row("SELECT id, points, reward_points FROM clients WHERE id = ? LIMIT 1", [$client_id]) ?: [];
        } catch (\Throwable $e) { $client = []; }
        if (empty($client)) {
            $this->lb_reward_json(['success' => false, 'message' => 'Client not found.']);
            return;
        }

        // Reward Points are the dedicated lootbox currency. They are separate from client.points / LB Coins.
        $lb_points_balance = (float)($client['reward_points'] ?? 0);
        $store_balance = (float)($client['points'] ?? 0);
        if ($price > 0 && $lb_points_balance + 0.00001 < $price) {
            $this->lb_reward_json(['success' => false, 'message' => 'Not enough Reward Points.', 'balance' => round($lb_points_balance, 2)]);
            return;
        }

        try {
            $items = $this->lb_reward_rows("SELECT * FROM reward_box_items WHERE box_id = ? AND status = 1 AND chance > 0 ORDER BY id ASC", [$box_id]) ?: [];
        } catch (\Throwable $e) { $items = []; }
        $item = $this->lb_reward_pick_item($items);
        if (empty($item)) {
            $this->lb_reward_json(['success' => false, 'message' => 'This box has no active rewards yet.']);
            return;
        }

        $reward_type = (string)($item['reward_type'] ?? 'reward_points');
        $reward_value = (string)($item['reward_value'] ?? '0');
        $item_id = (int)($item['id'] ?? 0);
        $new_lb_points_balance = $lb_points_balance;
        $new_store_balance = $store_balance;
        $coupon_code = null;
        $client_reward_status = 'unused';

        try {
            if ($price > 0) {
                $new_lb_points_balance = max(0, $new_lb_points_balance - $price);
                db_update_row('clients', ['id' => $client_id], ['reward_points' => number_format($new_lb_points_balance, 2, '.', '')]);
            }

            if ($reward_type === 'reward_points') {
                $points = max(0, (float)$reward_value);
                if ($points > 0) {
                    $new_lb_points_balance += $points;
                    db_update_row('clients', ['id' => $client_id], ['reward_points' => number_format($new_lb_points_balance, 2, '.', '')]);
                    $client_reward_status = 'credited';
                }
            } elseif ($reward_type === 'lb_coins' || $reward_type === 'wallet_credit') {
                $credit = max(0, (float)$reward_value);
                if ($credit > 0) {
                    $new_store_balance += $credit;
                    db_update_row('clients', ['id' => $client_id], ['points' => number_format($new_store_balance, 2, '.', '')]);
                    try {
                        db_insert_row('coins_history', [
                            'client_id' => $client_id,
                            'amount' => number_format($credit, 2, '.', ''),
                            'type' => 'increment',
                            'reason' => ($reward_type === 'wallet_credit' ? 'Wallet credit reward' : 'LB Coins reward') . ': ' . (string)($item['name'] ?? 'Reward'),
                        ]);
                    } catch (\Throwable $historyError) {
                        error_log('[LB Rewards] coins_history increment failed: ' . $historyError->getMessage());
                    }
                    $client_reward_status = 'credited';
                }
            } elseif ($reward_type === 'discount_coupon') {
                $percent = max(1, min(90, (int)$reward_value));
                $coupon_code = $this->lb_reward_coupon_code();
                for ($i = 0; $i < 5; $i++) {
                    $exists = $this->lb_reward_single("SELECT id FROM discounts WHERE code = ? LIMIT 1", [$coupon_code]);
                    if (!$exists) { break; }
                    $coupon_code = $this->lb_reward_coupon_code();
                }
                db_insert_row('discounts', [
                    'admin_id' => 2,
                    'code' => $coupon_code,
                    'uses' => 0,
                    'max_uses' => 1,
                    'max_uses_client' => 1,
                    'services' => 'boosting,coaching',
                    'amount' => $percent,
                    'is_fixed' => 0,
                    'status' => 1,
                    'starts_at' => date('Y-m-d H:i:s'),
                    'expires_at' => date('Y-m-d H:i:s', strtotime('+14 days')),
                ]);
            }

            $opening_id = db_insert_row('reward_openings', [
                'client_id' => $client_id,
                'box_id' => $box_id,
                'item_id' => $item_id,
                'cost_coins' => number_format($price, 2, '.', ''),
            ]);

            db_insert_row('client_rewards', [
                'client_id' => $client_id,
                'opening_id' => (int)$opening_id,
                'box_id' => $box_id,
                'item_id' => $item_id,
                'reward_type' => $reward_type,
                'reward_value' => $reward_value,
                'status' => $client_reward_status,
                'coupon_code' => $coupon_code,
                'expires_at' => ($reward_type === 'discount_coupon' || in_array($reward_type, ['priority_boost','champion_preference'], true)) ? date('Y-m-d H:i:s', strtotime('+14 days')) : null,
            ]);
        } catch (\Throwable $e) {
            $rewardError = '[LB Rewards] open box failed: ' . $e->getMessage();
            error_log($rewardError);
            @error_log(date('Y-m-d H:i:s') . ' ' . $rewardError . PHP_EOL, 3, dirname(__DIR__, 2) . '/.lb_rewards_debug.log');
            $host = (string)($_SERVER['HTTP_HOST'] ?? '');
            $debugMessage = (stripos($host, 'testing.') !== false || stripos($host, 'localhost') !== false)
                ? ('Could not open reward box: ' . $e->getMessage())
                : 'Could not open reward box. Please check the error log.';
            $this->lb_reward_json(['success' => false, 'message' => $debugMessage]);
            return;
        }

        try {
            $clientWebhookRow = is_array(CLIENT_DATA ?? null) ? CLIENT_DATA : [];
            $clientWebhookRow['id'] = $client_id;
            $this->lb_reward_send_discord_webhook($box, $item, $clientWebhookRow, $new_lb_points_balance, $coupon_code);
        } catch (\Throwable $e) {
            error_log('[LB Rewards] Discord webhook wrapper failed: ' . $e->getMessage());
        }

        $this->lb_reward_json([
            'success' => true,
            'message' => 'Reward box opened.',
            'balance' => round($new_lb_points_balance, 2),
            'lb_points' => round($new_lb_points_balance, 2),
            'store_balance' => round($new_store_balance, 2),
            'box' => ['id' => $box_id, 'name' => (string)($box['name'] ?? '')],
            'item' => [
                'id' => $item_id,
                'name' => (string)($item['name'] ?? 'Reward'),
                'rarity' => (string)($item['rarity'] ?? 'common'),
                'reward_type' => $reward_type,
                'reward_value' => $reward_value,
                'coupon_code' => $coupon_code,
                'icon' => (string)($item['icon'] ?? ''),
            ],
        ]);
    }


    public function admin_egirl_change_password()
    {
        if (!$this->is_admin) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Unauthorized', 'message' => 'Unauthorized'],
                'playSound' => 'error',
            ]);
            return;
        }

        $booster_id = (int)($_POST['id'] ?? $_POST['egirl_id'] ?? $_POST['booster_id'] ?? $_POST['user_id'] ?? 0);
        $new_password = trim((string)($_POST['new_password'] ?? ''));
        $confirm_password = trim((string)($_POST['confirm_password'] ?? ''));
        $send_email = (int)($_POST['send_email'] ?? 0) === 1;

        if ($booster_id <= 0) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Invalid GG-Girl ID.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if (strlen($new_password) < 6) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Password must be at least 6 characters.'],
                'playSound' => 'error',
            ]);
            return;
        }

        if ($new_password !== $confirm_password) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'Passwords do not match.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $booster = db_get_row('boosters', ['id' => $booster_id]);
        if (!$booster || (int)($booster['is_egirl'] ?? 0) !== 1) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'Error', 'message' => 'GG-Girl not found.'],
                'playSound' => 'error',
            ]);
            return;
        }

        $updated = db_update_row('boosters', ['id' => $booster_id], [
            'password' => sha1($new_password),
        ]);

        if (!$updated) {
            echo json_encode([
                'success' => false,
                'sendToast' => ['type' => 'danger', 'title' => 'DB Error', 'message' => 'Password could not be updated.'],
                'playSound' => 'error',
            ]);
            return;
        }

        log_admin_action(ADMIN_ID, 'Changed GG-Girl password #' . $booster_id);

        if ($send_email) {
            db_insert_row('notifications', [
                'type' => 'welcome_egirl',
                'data' => json_encode([
                    'action_url' => base64_encode(BSTR_URL . '/auth/login'),
                    'email' => base64_encode((string)($booster['email'] ?? '')),
                    'password' => base64_encode($new_password),
                ]),
                'recipient' => 'booster',
                'recipient_id' => $booster_id,
                'is_email' => 1,
                'is_web' => 1,
            ]);
            if (function_exists('trigger_notification_sender_async')) {
                trigger_notification_sender_async();
            }
        }

        echo json_encode([
            'success' => true,
            'sendToast' => [
                'type' => 'success',
                'title' => 'Password changed',
                'message' => $send_email ? 'Password changed and login email queued.' : 'Password changed successfully.',
            ],
            'playSound' => 'success',
        ]);
    }

    public function seller_setup_quick_update()
    {
        if (!$this->is_seller) {
            echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Unauthorized.']]);
            return;
        }

        global $db;
        $seller_id = (int)$this->seller_data['id'];
        try { $this->ensure_selling_schema(); } catch (\Throwable $e) {}
        try {
            $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS languages TEXT NULL");
            $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS description TEXT NULL");
            $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS allow_chat_requests TINYINT(1) NOT NULL DEFAULT 1");
            $db->run("ALTER TABLE sellers ADD COLUMN IF NOT EXISTS seller_setup_chat_ack TINYINT(1) NOT NULL DEFAULT 0");
        } catch (\Throwable $e) {}

        $field = trim((string)($_POST['field'] ?? ''));

        if ($field === 'languages') {
            $languages = $_POST['languages'] ?? [];
            if (!is_array($languages)) $languages = [];
            $languages = array_values(array_unique(array_filter(array_map(function ($lang) {
                return preg_replace('/[^a-zA-Z0-9_\-]/', '', trim((string)$lang));
            }, $languages))));
            if (empty($languages)) {
                echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Please select at least one language.']]);
                return;
            }
            $db->run("UPDATE sellers SET languages = ? WHERE id = ?", json_encode($languages, JSON_UNESCAPED_UNICODE), $seller_id);
            echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Languages saved.']]);
            return;
        }

        if ($field === 'description') {
            $description = trim((string)($_POST['value'] ?? ''));
            if ($description === '') {
                echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Please enter a description.']]);
                return;
            }
            $db->run("UPDATE sellers SET description = ? WHERE id = ?", $description, $seller_id);
            echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Description saved.']]);
            return;
        }

        if ($field === 'allow_chat_requests') {
            $value = !empty($_POST['value']) ? 1 : 0;
            $db->run("UPDATE sellers SET allow_chat_requests = ?, seller_setup_chat_ack = 1 WHERE id = ?", $value, $seller_id);
            echo json_encode(['success' => true, 'sendToast' => ['type' => 'success', 'title' => 'Saved', 'message' => 'Chat request setting saved.']]);
            return;
        }

        echo json_encode(['success' => false, 'sendToast' => ['type' => 'danger', 'message' => 'Invalid setup field.']]);
    }


