    private function lb_poke_send_seller_dm(array $seller, string $title, string $description, string $url, string $buttonLabel = '🔎 Open Chat'): bool
    {
        if (empty($seller['discord_id']) || !defined('DS_BOT_TOKEN') || !DS_BOT_TOKEN) {
            return false;
        }

        $discordUserId = trim((string)$seller['discord_id']);
        if ($discordUserId === '') {
            return false;
        }

        try {
            $dmChannel = function_exists('getDMChannelId') ? getDMChannelId(DS_BOT_TOKEN, $discordUserId) : null;
            if (!$dmChannel) {
                return false;
            }

            $embed = [
                'title' => $title,
                'author' => [
                    'name' => 'LoLBoost.GG',
                    'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png',
                ],
                'description' => $description,
                'footer' => [
                    'text' => 'LoLBoost.GG - Ranking up never been easier',
                    'icon_url' => 'https://lolboost.gg/public/uploads/icons/default1.png',
                ],
                'timestamp' => date('c'),
                'color' => 0x5865F2,
            ];

            $components = [[
                'type' => 1,
                'components' => [[
                    'type' => 2,
                    'style' => 5,
                    'label' => $buttonLabel,
                    'url' => $url,
                ]],
            ]];

            $payload = json_encode(['embeds' => [$embed], 'components' => $components], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            if (function_exists('sendEmbedDM')) {
                sendEmbedDM(DS_BOT_TOKEN, $dmChannel, $payload);
                return true;
            }

            $ch = curl_init('https://discord.com/api/v10/channels/' . $dmChannel . '/messages');
            curl_setopt_array($ch, [
                CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Authorization: Bot ' . DS_BOT_TOKEN],
                CURLOPT_POST => 1,
                CURLOPT_POSTFIELDS => $payload,
                CURLOPT_RETURNTRANSFER => 1,
                CURLOPT_TIMEOUT => 8,
            ]);
            curl_exec($ch);
            curl_close($ch);
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }


    private function lb_poke_resolve_premium_account_seller(array $account): ?array
    {
        $seller_id = (int)($account['seller_id'] ?? 0);
        if ($seller_id <= 0) {
            $admin_id = (int)($account['admin_id'] ?? 0);
            if ($admin_id === 51) {
                $seller_id = 28;
            } elseif ($admin_id === 2) {
                $seller_id = 1;
            }
        }
        if ($seller_id <= 0) {
            return null;
        }
        $seller = db_get_row('sellers', ['id' => $seller_id], 1);
        return !empty($seller) ? $seller : null;
    }


    private function lb_send_approved_review_discord_webhook($reviewRow)
    {
        $discordWebhookUrl = "https://discord.com/api/webhooks/1518948301242765393/0c1Snktsseg-q99Ae5ctClU_bGIc6o90gd7FsDdwsqZHq-PUNS0v6Y7oea7GzYeQNYXt";

        if (empty($discordWebhookUrl) || $discordWebhookUrl === "PASTE_DISCORD_COMMUNITY_REVIEW_WEBHOOK_HERE" || empty($reviewRow)) {
            return;
        }

        $overallRating = max(1, min(5, (int)($reviewRow['overall'] ?? 5)));
        $stars = str_repeat("⭐", $overallRating);
        $comment = trim((string)($reviewRow['comments'] ?? ''));

        if ($comment === '') {
            $comment = 'No comment provided.';
        } elseif (function_exists('mb_substr')) {
            $comment = mb_substr($comment, 0, 900);
        } else {
            $comment = substr($comment, 0, 900);
        }

        $order = db_get_row('orders', ['id' => (int)($reviewRow['order_id'] ?? 0)]);
        $booster = !empty($reviewRow['booster_id']) ? db_get_row('boosters', ['id' => (int)$reviewRow['booster_id']]) : false;
        $client = false;
        $form = false;

        if ($order) {
            if (!empty($order['client_id'])) {
                $client = db_get_row('clients', ['id' => (int)$order['client_id']]);
            }
            if (!$booster && !empty($order['booster_id'])) {
                $booster = db_get_row('boosters', ['id' => (int)$order['booster_id']]);
