    private function get_safe_public_login_redirect_url(): ?string
    {
        $redirect = $_POST['redirectUrl'] ?? $_POST['redirect_after_login'] ?? $_POST['redirect_url'] ?? $_POST['return_url'] ?? $_POST['returnUrl'] ?? null;
        $redirect = is_string($redirect) ? trim($redirect) : null;

        if (!$redirect) {
            return null;
        }

        if (strpos($redirect, '/') === 0 && strpos($redirect, '//') !== 0) {
            $redirect = BASE_URL . $redirect;
        }

        if (strpos($redirect, BASE_URL) !== 0) {
            return null;
        }

        $path = parse_url($redirect, PHP_URL_PATH);
        if (!is_string($path) || !preg_match('#/(world-cup-predictions|lootboxes)/?$#', $path)) {
            return null;
        }

        return $redirect;
    }


