    private function egirl_web_notification_data(int $order_id = 0, array $extra = []): array
    {
        $data = [];
        if ($order_id > 0) {
            $data['order_id'] = base64_encode((string)$order_id);
            try {
                global $db;
                if (isset($db)) {
                    $row = $db->row(
                        "SELECT eo.client_id, c.username AS client_username
                         FROM egirl_orders eo
                         LEFT JOIN clients c ON c.id = eo.client_id
                         WHERE eo.id = ? LIMIT 1",
                        $order_id
                    );
                    if ($row) {
                        if (!empty($row['client_id'])) {
                            $data['client_id'] = base64_encode((string)$row['client_id']);
                        }
                        if (!empty($row['client_username'])) {
                            $data['client_username'] = base64_encode((string)$row['client_username']);
                        }
                    }
                }
            } catch (\Throwable $e) {}
        }

        foreach ($extra as $key => $value) {
            if ($value === null || is_array($value) || is_object($value)) continue;
            $data[$key] = base64_encode((string)$value);
        }

        return $data;
    }


    private function lb_reward_pick_item(array $items): ?array
    {
        $total = 0.0;
        foreach ($items as $item) {
            $total += max(0.0, (float)($item['chance'] ?? 0));
        }
        if ($total <= 0) { return null; }
        $rand = mt_rand(1, (int)round($total * 10000)) / 10000;
        $cursor = 0.0;
        foreach ($items as $item) {
            $cursor += max(0.0, (float)($item['chance'] ?? 0));
            if ($rand <= $cursor) { return $item; }
        }
        return !empty($items) ? end($items) : null;
    }


    private function lb_reward_rows(string $sql, array $params = []): array
    {
        global $db;
        try {
            $rows = $db->run($sql, ...$params);
            if (is_array($rows)) { return $rows; }
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] rows run(spread) failed: ' . $e->getMessage());
        }

        try {
            $rows = $db->run($sql, $params);
            if (is_array($rows)) { return $rows; }
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] rows run(array) fallback failed: ' . $e->getMessage());
        }

        return [];
    }


    private function lb_reward_single(string $sql, array $params = [])
    {
        global $db;
        try {
            return $db->single($sql, $params);
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] single(array) failed: ' . $e->getMessage());
        }

        try {
            $rows = $db->run($sql, ...$params);
            if (is_array($rows) && isset($rows[0]) && is_array($rows[0])) {
                $first = reset($rows[0]);
                return $first === false ? null : $first;
            }
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] single run(spread) fallback failed: ' . $e->getMessage());
        }

        return null;
    }


    private function lb_reward_client_display_data(int $client_id, array $fallback = []): array
    {
        $client = $fallback;
        try {
            $row = db_get_row('clients', ['id' => $client_id], 1);
            if (is_array($row) && !empty($row)) {
                $client = array_merge($client, $row);
            }
        } catch (\Throwable $e) {}

        $name = '';
        foreach (['username','name','client_name','display_name','first_name','email'] as $key) {
            if (!empty($client[$key])) { $name = (string)$client[$key]; break; }
        }
        if ($name === '') { $name = 'Guest#' . $client_id; }

        $icon = '';
        foreach (['client_icon','client_avatar','avatar_url','profile_photo','profile_image_url','icon','avatar','profile_image','profile_picture','picture','image','photo','img'] as $key) {
            if (!empty($client[$key])) { $icon = (string)$client[$key]; break; }
        }

        return [
            'name' => $name,
            'icon' => $icon !== '' ? $this->lb_reward_absolute_asset_url($icon) : '',
        ];
    }


    private function lb_reward_order_perks_response(array $available, array $applied): array
    {
        $map = $this->lb_reward_order_perk_map();
        $payload = ['available' => [], 'applied' => []];

        foreach ($available as $type => $row) {
            $payload['available'][$type] = [
                'id' => (int)($row['id'] ?? 0),
                'field' => (string)($map[$type]['field'] ?? ''),
                'label' => (string)($map[$type]['label'] ?? 'Free Reward'),
            ];
        }

        foreach ($applied as $type => $row) {
            $payload['applied'][$type] = [
                'id' => (int)($row['id'] ?? 0),
                'field' => (string)($row['field'] ?? ''),
                'label' => (string)($row['label'] ?? 'Free Reward'),
            ];
        }

        return $payload;
    }


    private function lb_reward_load_unused_order_perks(int $client_id): array
    {
        if ($client_id <= 0) {
            return [];
        }

        global $db;
        $types = array_keys($this->lb_reward_order_perk_map());
        $placeholders = implode(',', array_fill(0, count($types), '?'));
        $params = array_merge([$client_id], $types);

        try {
            $rows = $db->run(
                "SELECT id, reward_type, reward_value, expires_at, status
                 FROM client_rewards
                 WHERE client_id = ?
                   AND reward_type IN ({$placeholders})
                   AND status = 'unused'
                   AND (expires_at IS NULL OR expires_at = '0000-00-00 00:00:00' OR expires_at >= NOW())
                 ORDER BY COALESCE(expires_at, '2999-12-31 23:59:59') ASC, id ASC",
                ...$params
            ) ?: [];
        } catch (\Throwable $e) {
            return [];
        }

        $available = [];
        foreach ($rows as $row) {
            $type = (string)($row['reward_type'] ?? '');
            if ($type === '' || isset($available[$type])) {
                continue;
            }
            $available[$type] = $row;
        }

        return $available;
    }


    private function lb_reward_consume_order_perks(array $applied, int $order_id): void
    {
        if (empty($applied) || $order_id <= 0) {
            return;
        }

        global $db;
        foreach ($applied as $perk) {
            $reward_id = (int)($perk['id'] ?? 0);
            if ($reward_id <= 0) {
                continue;
            }

            try {
                $db->run(
                    "UPDATE client_rewards
                     SET status = 'used', used_at = NOW(), used_order_id = ?
                     WHERE id = ? AND client_id = ? AND status = 'unused'",
                    $order_id,
                    $reward_id,
                    (int)CLIENT_ID
                );
            } catch (\Throwable $e) {
                // Fallback for installs where used_order_id has not been migrated yet.
                try {
                    $db->run(
                        "UPDATE client_rewards
                         SET status = 'used', used_at = NOW()
                         WHERE id = ? AND client_id = ? AND status = 'unused'",
                        $reward_id,
                        (int)CLIENT_ID
                    );
                } catch (\Throwable $ignored) {}
            }
        }
    }



    private function lb_reward_consume_discount_coupon_code($coupon_code, int $order_id = 0): void
    {
        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            return;
        }

        $coupon_code = strtoupper(trim((string)$coupon_code));
        if ($coupon_code === '' || strpos($coupon_code, 'LB-REWARD-') !== 0) {
            return;
        }

        try {
            db_update_row('client_rewards', [
                'client_id' => (int)CLIENT_ID,
                'coupon_code' => $coupon_code,
                'status' => 'unused',
            ], [
                'status' => 'used',
                'used_at' => date('Y-m-d H:i:s'),
                'used_order_id' => $order_id > 0 ? $order_id : null,
            ]);
        } catch (\Throwable $e) {
            // Fallback for installs where used_order_id has not been migrated yet.
            try {
                db_update_row('client_rewards', [
                    'client_id' => (int)CLIENT_ID,
                    'coupon_code' => $coupon_code,
                    'status' => 'unused',
                ], [
                    'status' => 'used',
                    'used_at' => date('Y-m-d H:i:s'),
                ]);
            } catch (\Throwable $ignored) {}
        }
    }



    private function lb_reward_coupon_code(): string
    {
        try { $suffix = strtoupper(bin2hex(random_bytes(3))); }
        catch (\Throwable $e) { $suffix = strtoupper(substr(md5(uniqid('', true)), 0, 6)); }
        return 'LB-REWARD-' . $suffix;
    }


    private function lb_reward_box_image_url(array $box): string
    {
        $slug = trim((string)($box['slug'] ?? ''));
        if ($slug === '') { return ''; }

        $map = [
            'daily-gift' => 'daily-gift.png',
            'starter-box' => 'starter-box.png',
            'silver-box' => 'silver-box.png',
            'gold-box' => 'gold-box.png',
            'diamond-box' => 'diamond-box.png',
            'challenger-box' => 'challenger-box.png',
        ];

        $file = $map[$slug] ?? ($slug . '.png');
        return $this->lb_reward_absolute_asset_url('/public/assets/website/images/rewards/boxes/' . $file);
    }


    private function lb_reward_item_image_url(array $item): string
    {
        $base = defined('BASE_URL') ? rtrim((string)BASE_URL, '/') : 'https://lolboost.gg';

        $type = (string)($item['reward_type'] ?? '');
        $value = $item['reward_value'] ?? 0;
        $amount = is_numeric($value) ? (float)$value : 0.0;

        if ($type === 'reward_points') {
            return $base . '/public/assets/website/images/coins/reward-points.png';
        }
        if ($type === 'lb_coins') {
            return $base . '/public/assets/website/images/coins/coin_purple.png';
        }
        if ($type === 'discount_coupon') {
            $percent = (int)$amount;
            if ($percent >= 15) { return $base . '/public/assets/website/images/rewards/15discount.png'; }
            if ($percent >= 10) { return $base . '/public/assets/website/images/rewards/10discount.png'; }
            return $base . '/public/assets/website/images/rewards/5discount.png';
        }
        if ($type === 'wallet_credit') {
            return $base . '/public/assets/website/images/rewards/' . ($amount >= 5 ? '5storecredits.png' : '2storecredits.png');
        }
        if ($type === 'priority_boost') {
            return $base . '/public/assets/website/images/rewards/priority.png';
        }
        if ($type === 'champion_preference') {
            return $base . '/public/assets/website/images/rewards/champion.png';
        }

        $icon = trim((string)($item['icon'] ?? $item['item_icon'] ?? ''));
        return $icon !== '' ? $this->lb_reward_absolute_asset_url($icon) : '';
    }




    private function lb_reward_absolute_asset_url(string $path): string
    {
        $path = trim($path);
        if ($path === '') { return ''; }
        if (strpos($path, 'http://') === 0 || strpos($path, 'https://') === 0) { return $path; }

        $base = defined('BASE_URL') ? rtrim((string)BASE_URL, '/') : 'https://lolboost.gg';
        return $base . '/' . ltrim($path, '/');
    }


    private function lb_reward_send_discord_webhook(array $box, array $item, array $client, $new_balance, ?string $coupon_code = null): void
    {
        $webhook = trim($this->lb_reward_discord_webhook_url());
        if ($webhook === '' || strpos($webhook, 'discord.com/api/webhooks/') === false) {
            return;
        }

        $clientDisplay = $this->lb_reward_client_display_data((int)($client['id'] ?? 0), $client);
        $clientName = $this->lb_reward_mask_client_name($clientDisplay['name'] ?? ('Guest#' . (int)($client['id'] ?? 0)));
        $clientIcon = (string)($clientDisplay['icon'] ?? '');
        $boxIconUrl = $this->lb_reward_box_image_url($box);
        $rewardIconUrl = $this->lb_reward_item_image_url($item);
        $pointsIconUrl = $this->lb_reward_absolute_asset_url('/public/assets/website/images/coins/reward-points.png');

        $rewardName = (string)($item['name'] ?? 'Reward');
        $rewardType = (string)($item['reward_type'] ?? '');
        $rewardValue = $item['reward_value'] ?? 0;
        $rewardLabel = $this->lb_reward_type_label($rewardType, $rewardValue);
        $rarity = strtoupper((string)($item['rarity'] ?? 'COMMON'));
        $boxName = (string)($box['name'] ?? 'Reward Box');
        $boxSlug = (string)($box['slug'] ?? '');

        $payload = [
            'username' => 'LoLBoost Rewards',
            'avatar_url' => $this->lb_reward_absolute_asset_url('/public/assets/core/main/img/logos/PNG/icon-bg-64x64.png'),
            'embeds' => [[
                'author' => array_filter([
                    'name' => $clientName . ' opened ' . $boxName,
                    'icon_url' => $clientIcon !== '' ? $clientIcon : null,
                ]),
                'title' => '✨ ' . $rewardName,
                'description' => '**' . $rewardLabel . '**',
                'color' => 7049471,
                'thumbnail' => $boxIconUrl !== '' ? ['url' => $boxIconUrl] : null,
                'fields' => array_values(array_filter([
                    ['name' => '🎁 Box', 'value' => $boxName, 'inline' => true],
                    ['name' => '⭐ Rarity', 'value' => $rarity, 'inline' => true],
                    ['name' => '🪙 Balance', 'value' => rtrim(rtrim(number_format((float)$new_balance, 2, '.', ''), '0'), '.') . ' Reward Points', 'inline' => true],
                ])),
                'footer' => [
                    'text' => 'LoLBoost Rewards • Opened at ' . date('d.m.Y H:i'),
                    'icon_url' => $pointsIconUrl,
                ],
                'timestamp' => date(DATE_ATOM),
            ]],
        ];
        $payload['embeds'][0] = array_filter($payload['embeds'][0], static fn($v) => $v !== null);

        $json = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (!$json) { return; }

        try {
            if (function_exists('curl_init')) {
                $ch = curl_init($webhook);
                curl_setopt_array($ch, [
                    CURLOPT_POST => true,
                    CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
                    CURLOPT_POSTFIELDS => $json,
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_CONNECTTIMEOUT_MS => 400,
                    CURLOPT_TIMEOUT_MS => 900,
                ]);
                @curl_exec($ch);
                @curl_close($ch);
                return;
            }

            $context = stream_context_create([
                'http' => [
                    'method' => 'POST',
                    'header' => "Content-Type: application/json\r\n",
                    'content' => $json,
                    'timeout' => 1,
                    'ignore_errors' => true,
                ],
            ]);
            @file_get_contents($webhook, false, $context);
        } catch (\Throwable $e) {
            error_log('[LB Rewards] Discord webhook failed: ' . $e->getMessage());
        }
    }


    private function lb_reward_discord_webhook_url(): string
    {
        return 'https://discord.com/api/webhooks/1524422427973648425/zDQz1rpsG3F8t8hNVVgQSNREAtbvhkOo5XB_p4LHPG7RK2tJVZ1_dH-Cv2gYc_Mt5o5b';
    }



    private function lb_reward_mask_client_name($name): string
    {
        $name = trim((string)($name ?? 'Guest'));
        if ($name === '') { $name = 'Guest'; }
        if (function_exists('mb_substr')) {
            $first = mb_substr($name, 0, 1, 'UTF-8');
            $last = mb_substr($name, -1, 1, 'UTF-8');
        } else {
            $first = substr($name, 0, 1);
            $last = substr($name, -1);
        }
        return $first . '*****' . $last;
    }


    private function lb_reward_type_label($type, $value): string
    {
        $type = (string)$type;
        $amount = is_numeric($value) ? (float)$value : 0.0;
        $clean = rtrim(rtrim(number_format($amount, 2, '.', ''), '0'), '.');

        return match ($type) {
            'reward_points' => $clean . ' Reward Points',
            'lb_coins' => $clean . ' LB Coins',
            'wallet_credit' => $clean . '€ Wallet Credit',
            'discount_coupon' => ((int)$amount) . '% Coupon',
            'priority_boost' => 'Priority Queue Boost',
            'champion_preference' => 'Champion Preference',
            default => 'Reward',
        };
    }

    private function lb_reward_json(array $payload): void
    {
        if (!headers_sent()) {
            header('Content-Type: application/json; charset=utf-8');
            header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
        }
        while (ob_get_level() > 0) { @ob_end_clean(); }
        echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        exit;
    }


    private function lb_reward_row(string $sql, array $params = []): array
    {
        global $db;

        // EasyDB::row() takes variadic params, not a params array — passing the array
        // always threw "Only one-dimensional arrays are allowed" and spammed the log.
        try {
            $row = $db->row($sql, ...$params);
            if (is_array($row) && !empty($row)) { return $row; }
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] row(spread) failed: ' . $e->getMessage());
        }

        try {
            $rows = $db->run($sql, ...$params);
            if (is_array($rows) && !empty($rows[0]) && is_array($rows[0])) { return $rows[0]; }
        } catch (\Throwable $e) {
            @error_log('[LB Rewards] run(spread) fallback failed: ' . $e->getMessage());
        }

        return [];
    }




    private function lb_reward_order_perk_map(): array
    {
        return [
            'priority_boost' => [
                'field' => 'is_priority',
                'label' => 'Free Priority Order',
            ],
            'champion_preference' => [
                'field' => 'is_champions_roles',
                'label' => 'Free Champion Preference',
            ],
            'offline_mode' => [
                'field' => 'is_offline_mode',
                'label' => 'Free Offline Mode',
            ],
            'vpn_addon' => [
                'field' => 'vpn_country',
                'label' => 'Free VPN Addon',
            ],
        ];
    }


    private function lb_reward_order_value_selected(array $post, string $field): bool
    {
        if (!array_key_exists($field, $post)) {
            return false;
        }

        $value = $post[$field];
        if (is_array($value)) {
            return !empty(array_filter($value, static fn($v) => trim((string)$v) !== '' && (string)$v !== '0'));
        }

        $value = trim((string)$value);
        return $value !== '' && $value !== '0' && strtolower($value) !== 'false' && strtolower($value) !== 'off';
    }


    private function lb_reward_prepare_order_perks_for_post(array $post): array
    {
        $available = [];
        $applied = [];
        $pricing_post = $post;

        if (!$this->is_client || !defined('CLIENT_ID') || (int)CLIENT_ID <= 0) {
            return [$pricing_post, $available, $applied];
        }

        $map = $this->lb_reward_order_perk_map();
        $available = $this->lb_reward_load_unused_order_perks((int)CLIENT_ID);

        foreach ($map as $type => $meta) {
            $field = (string)($meta['field'] ?? '');
            if ($field === '' || empty($available[$type]) || !$this->lb_reward_order_value_selected($post, $field)) {
                continue;
            }

            // Remove the addon from the pricing input only. The original POST is still used
            // for order_options, so the customer actually receives the selected option.
            if ($field === 'vpn_country') {
                $pricing_post[$field] = '';
            } else {
                $pricing_post[$field] = 0;
            }

            $applied[$type] = [
                'id' => (int)($available[$type]['id'] ?? 0),
                'type' => $type,
                'field' => $field,
                'label' => (string)($meta['label'] ?? 'Free Reward'),
            ];
        }

        return [$pricing_post, $available, $applied];
    }


    private function lb_reward_is_debug_host(): bool
    {
        $host = (string)($_SERVER['HTTP_HOST'] ?? '');
        return stripos($host, 'testing.') !== false || stripos($host, 'localhost') !== false;
    }
}
